      (v_set_id, 16, E'पोखरा अन्तर्राष्ट्रिय विमानस्थलको उदघाटन कसले गरेका हुन्?', E'रामचन्द्र पौडेल', E'शेरबहादुर देउवा', E'केपि शर्मा वली', E'पुष्पकमल दाहाल', 'D', E'पोखरा अन्तर्राष्ट्रिय विमानस्थलको उद्घाटन **पुष्पकमल दाहालले** वि.सं. २०७९ पुस १७ मा गरेका हुन्। यो नेपालको तेस्रो अन्तर्राष्ट्रिय विमानस्थल हो।\nनोट: यसअघि दोस्रो अन्तर्राष्ट्रिय विमानस्थल, गौतम बुद्ध, को उद्घाटन शेरबहादुर देउवाले वि.सं. २०७९ जेठ २ मा गरेका थिए।', 'nepali'),
      (v_set_id, 17, E'सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गर्ने राष्ट्र देहायको कुन हैन?', E'अस्ट्रिया', E'नेपाल', E'इटाली', E'कोलम्बिया', 'D', E'**सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त नगर्ने राष्ट्र **कोलम्बिया हो।\n- अस्ट्रिया, नेपाल र इटालीले सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गरेका थिए।\n- उक्त दिन संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गर्ने अन्य राष्ट्रहरूमा आयरल्यान्ड, फिनल्याण्ड, बुल्गेरिया, रोमानिया, लाओस, कम्बोडिया, जोर्डन, अल्बानिया, पोर्चुगल, लिबिया, श्रीलंका, स्पेन र हंगेरी पर्दछन्।', 'nepali'),
      (v_set_id, 18, E'नेपालमा हाल सबैभन्दा बढी घाटामा रहेका संस्थान कुन हो?', E'नेपाल खानेपानी संस्थान', E'नेपाल टेलिभिजन', E'नेपाल वायुसेवा निगम', E'हेटौंडा सिमेन्ट उद्योग', 'C', E'**नेपालमा हाल सबैभन्दा बढी घाटामा रहेको संस्थान **नेपाल वायुसेवा निगम हो।\n- नेपाल खानेपानी संस्थान दोस्रो बढी घाटामा रहेको संस्थान हो।\n- हेटौंडा सिमेन्ट उद्योग तेस्रो बढी घाटामा रहेको संस्थान हो।\n- जनक शिक्षा सामग्री केन्द्र लि. चौथो र सार्वजनिक सेवा प्रसारण नेपाल पाँचौ बढी घाटामा रहेका संस्थानहरू हुन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८१/०७/२४', 18;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2081_07_25.csv  →  आसमान दैनिक GK — २०८१/०७/२५  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८१/०७/२५'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८१/०७/२५';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८१/०७/२५', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'सम्पत्तिको हक अन्तर्गत प्रत्येक नागरिकलाई कानूनको अधीनमा रही देहायको कुन कर लगाउन सकिन्छ?', E'सम्पत्ति आर्जन कर', E'सम्पत्ति भोग कर', E'बेचबिखन कर', E'आयमा कर', 'D', E'सम्पत्तिको हक अन्तर्गत प्रत्येक नागरिकलाई कानूनको अधीनमा रही राज्यले व्यक्तिको **आयमा कर** लगाउन सक्नेछ। नागरिकलाई सम्पत्ति आर्जन गर्ने, भोग गर्ने, बेचबिखन गर्ने र व्यावसायिक लाभ प्राप्त गर्ने हक हुनेछ।', 'nepali'),
      (v_set_id, 2, E'छिमेकी मुलुक भारत अन्तरिक्ष प्रवेश गर्ने कति औं मुलुक हो?', E'छैटौं', E'पाँचौं', E'चौथो', E'तेस्रो', 'A', E'छिमेकी मुलुक भारत अन्तरिक्ष प्रवेश गर्ने **छैटौं मुलुक** हो। भारत चन्द्रमामा पुग्ने चौथो मुलुक हो।\nअन्तरिक्षमा पुग्ने मुलुकको क्रम यस प्रकार छ:\n- रुस\n- अमेरिका\n- फ्रान्स\n- जापान\n- चीन\n- भारत', 'nepali'),
      (v_set_id, 3, E'विश्वको सर्वोच्च शिखर सगरमाथाको उचाई कति फिट रहेको छ?', E'२९०३३.६९ फिट', E'२९०३१.६९ फिट', E'२९०२९.६९ फिट', E'२९०२७.६९ फिट', 'C', E'विश्वको सर्वोच्च शिखर सगरमाथाको उचाई **२९०२९.६९ फिट** रहेको छ।\nनोट: यो उचाई ८८४८.८६ मिटर बराबर हो र सगरमाथा नेपालमा अवस्थित छ।', 'nepali'),
      (v_set_id, 4, E'हालसालै कुन मुलुकको पहिलो महिला प्रधानमन्त्रीको रुपमा सानई ताकाइची प्रधानमन्त्री बनिन्?', E'बेलायत', E'द. कोरिया', E'जापान', E'माल्दिभ्स', 'C', E'**सन् २०२१ अक्टोबर २९ मा जापानले सानई ताकाइचीलाई आफ्नो पहिलो महिला प्रधानमन्त्रीको रूपमा पाएको थियो।**\n- उनी जापानकी आइरन लेडी भनेर चिनिन्छिन्।\nनोट: यो ताकाइचीको तेस्रो प्रयास थियो।', 'nepali'),
      (v_set_id, 5, E'सबैभन्दा सानो देश भ्याटिकन सिटभन्दा नेपाल करिब कति ठूलो रहेको छ?', E'३,२४,५०० गुणा', E'३,३३,५०० गुणा', E'३,३२,५०० गुणा', E'३,२१,५०० गुणा', 'A', E'**नेपाल सबैभन्दा सानो देश भ्याटिकन सिटि भन्दा करिब ३,२४,५०२.२७ गुणा ठूलो रहेको छ।**\n- सबैभन्दा ठूलो देश रुसभन्दा नेपाल ११६.१७ गुणा सानो छ।', 'nepali'),
      (v_set_id, 6, E'मकालु हिमाल कुन जिल्लामा रहेको छ?', E'सोलुखुम्बु', E'सङ्खुवासभा', E'ताप्लेजुङ', E'गोरखा', 'B', E'**मकालु हिमाल सङ्खुवासभा जिल्लामा रहेको छ।**\n- सोलुखुम्बु जिल्लामा सगरमाथा, ल्होत्से र चो ओयु हिमाल रहेका छन्।\n- ताप्लेजुङ जिल्लामा कञ्चनजङ्घा हिमाल रहेको छ।\n- गोरखा जिल्लामा मनास्लु हिमाल रहेको छ।\nनोट: धवलागिरि म्याग्दी/मुस्ताङ र अन्नपूर्ण कास्की जिल्लामा रहेका छन्।', 'nepali'),
      (v_set_id, 7, E'विश्वमा शासक र सम्राटको उदय कुन मानव सभ्यताको देन हो?', E'मिश्रको सभ्यता', E'युनानी सभ्यता', E'मेसोपोटामिया सभ्यता', E'सिन्धुघाँटीको सभ्यता', 'C', E'**विश्वमा शासक र सम्राटको उदय मेसोपोटामिया सभ्यताको देन हो।**\n- मिश्रको सभ्यता नील नदीको वरपर विकसित भएको थियो र यसको मुख्य देन पिरामिडहरू हुन्।\n- युनानी सभ्यताले लोकतन्त्र, दर्शन र ओलम्पिक खेलकुदको जग बसाल्यो।\n- सिन्धुघाँटीको सभ्यता व्यवस्थित शहरी योजना र सरसफाइका लागि प्रसिद्ध छ।\nनोट: मेसोपोटामिया सभ्यताको सुमेरियनकालमा राजालाई पटेसी भनिन्थ्यो र ''Eye for eye, tooth for tooth'' न्याय व्यवस्था थियो।', 'nepali'),
      (v_set_id, 8, E'बुढानिलकण्ठमा मानव बस्ती बसाल्ने राजा को हुन्?', E'जयदेव द्वितीय', E'शिवदेव द्वितीय', E'मानदेव', E'बलदेव', 'B', E'**बुढानिलकण्ठमा मानव बस्ती बसाल्ने राजा शिवदेव द्वितीय हुन्।**\n- हाँडिगाउँ बलदेवले र शिवदेव द्वितीयले थानकोटमा बस्ती बसाएका थिए।', 'nepali'),
      (v_set_id, 9, E'हिन्दु धर्मका ६ शास्त्र अन्तर्गत सांख्य शास्त्रका प्रवर्तकको हुन्?', E'कपिल', E'व्यास', E'गौतम ऋषि', E'पतञ्जली', 'A', E'**हिन्दु धर्मका ६ शास्त्र अन्तर्गत सांख्य शास्त्रका प्रवर्तक कपिल हुन्।**\n- योग शास्त्रका प्रवर्तक पतञ्जली हुन्।\n- न्याय शास्त्रका प्रवर्तक गौतम ऋषि हुन्।\n- वेदान्त शास्त्रका प्रवर्तक व्यास हुन्।\nनोट: पूर्व मिमांसाका प्रवर्तक जैमिनी र वैशेषिक शास्त्रका प्रवर्तक कणाद हुन्।', 'nepali'),
      (v_set_id, 10, E'२०८२ कार्तिक देखि सुरु भएको नेपाल संवत् कुन हो?', E'नेपाल संवत् ११४५', E'नेपाल संवत् ११४६', E'नेपाल संवत् ११४७', E'नेपाल संवत् ११४८', 'B', E'नेवार समुदायले नयाँ वर्षका रुपमा मनाउने गरेको नेपाल संवत् **११४६** २०८२ कार्तिक ५ गतेबाट सुरु भएको हो। लिच्छविकालका राजा राघवदेवको शासनकालमा राष्ट्रिय विभूति शंखधर सा:ख्वाले विसं ९३७ (इ सं ८८०) मा गरिब जनताको ऋणमोचन गरी नेपाल संवत्को सुरुवात गराउनुभएको थियो।', 'nepali'),
      (v_set_id, 11, E'सोह्रौं योजनाको अन्त्य सम्म नेपालको (Palma Ratio) कति पुऱ्याउने लक्ष्य रहेको छ?', E'१.३ अनुपात', E'१.२ अनुपात', E'१.४ अनुपात', E'१.१ अनुपात', 'B', E'सोह्रौं योजनाको अन्त्य सम्म नेपालको पाल्मा अनुपात (Palma Ratio) **१.२ अनुपात** पुऱ्याउने लक्ष्य रहेको छ। हाल यो अनुपात १.३ रहेको छ।', 'nepali'),
      (v_set_id, 12, E'Father of Modern genetics का रुपमा कुन वैज्ञानिकलाई चिनिन्छ?', E'चार्ल्स डार्विन', E'T.H. Morgan', E'रोबर्ट बोइल', E'मेण्डल', 'D', E'**मेण्डल**लाई फादर अफ मोडर्न जेनेटिक्स (Father of Modern Genetics) का रुपमा चिनिन्छ।\n- चार्ल्स डार्विनलाई फादर अफ इभोलुसन (Father of Evolution) का रुपमा चिनिन्छ।\n- जोन गेगर मेण्डेले (अस्ट्रिया) लाई वंशाणु विज्ञानका पिता (Father of genetics) मानिन्छ।', 'nepali'),
      (v_set_id, 13, E'दिगो विकासको 5 Ps मा देहाएको कुन पर्दैन?', E'Potential', E'People', E'Prosperity', E'Partnership', 'A', E'दिगो विकास एजेण्डाले पाँचवटा क्षेत्रहरुलाई प्राथमिक महत्वका क्षेत्रहरु मानेको छ जसलाई 5 Ps पनि भन्ने गरिन्छ। ती हुन्: जनता (People), पृथ्वी (Planet), सम्बृद्धि (Prosperity), शान्ति (Peace) र साझेदारी (Partnership)। त्यसैले, **Potential** दिगो विकासको 5 Ps मा पर्दैन।', 'nepali'),
      (v_set_id, 14, E'राजधानी बाहिर आयोजना भएका सार्क शिखर सम्मेलनहरु कतिवटा रहेका छन्?', E'१ मात्र', E'२ मात्र', E'३ वटा', E'छैनन्', 'B', E'राजधानी बाहिर आयोजना भएका सार्क शिखर सम्मेलनहरु **२ वटा** रहेका छन्।\n- ती सम्मेलनहरू दोस्रो सार्क शिखर सम्मेलन (बैङ्गलोर, भारत) र सातौं सार्क शिखर सम्मेलन (अड्डु शहर, माल्दिभ्स) हुन्।', 'nepali'),
      (v_set_id, 15, E'UNDP का अनुसार मानव विकास सूचकाङ्क, २०२४ मा नेपाल कति औं स्थानमा रहेको थियो?', E'१४३ औं', E'१४४ औं', E'१४६ औं', E'१४७ औं', 'B', E'UNDP का अनुसार मानव विकास सूचकाङ्क, २०२४ मा नेपाल **१४४ औं** स्थानमा रहेको थियो। नेपालको मानव विकास सूचकांक ०.६२२ अंक रहेको छ।\nनोट: २०२३ मा नेपाल ०.६०१ अंकका साथ १४७ औं स्थानमा थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८१/०७/२५', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_01_31.csv  →  आसमान दैनिक GK — २०८२/०१/३१  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०१/३१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०१/३१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०१/३१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'तलका मध्ये कुन सञ्चारको माध्यम हैन?', E'घडी', E'रेडियो', E'इमेल', E'पत्रिका', 'A', E'**घडी सञ्चारको माध्यम होइन, यो समय हेर्न प्रयोग गरिने उपकरण हो।**\n- रेडियो एकतर्फी सञ्चारको माध्यम हो, जसबाट सूचना प्रसारण गरिन्छ।\n- इमेल दुईतर्फी सञ्चारको माध्यम हो, जसबाट विद्युतीय सन्देश आदानप्रदान गरिन्छ।\n- पत्रिका एकतर्फी सञ्चारको माध्यम हो, जसबाट लिखित सूचना प्रकाशित गरिन्छ।\nनोट: सञ्चारका माध्यमहरूलाई मुख्यतया एकतर्फी र दुईतर्फी गरी २ प्रकारमा वर्गीकरण गरिन्छ।', 'nepali'),
      (v_set_id, 2, E'दलितको हक अन्तर्गत दलित विद्यार्थीलाई कुन तहसम्मको शिक्षा कानून बमोजिम छात्रवृत्ति सहित निःशुल्क शिक्षाको व्यवस्था रहेको छ?', E'माध्यमिक शिक्षा', E'आधारभूत शिक्षा', E'उच्च शिक्षा', E'विश्वविद्यालय शिक्षा', 'C', E'नेपालको कानून बमोजिम दलित विद्यार्थीलाई प्राथमिकदेखि **उच्च शिक्षासम्म** छात्रवृत्ति सहित निःशुल्क शिक्षाको व्यवस्था गरिएको छ।\nनोट: प्राविधिक र व्यावसायिक उच्च शिक्षामा दलितका लागि कानून बमोजिम विशेष व्यवस्था गरिनेछ, जुन नेपालको संविधानको धारा ४० (दलितको हक) मा उल्लेख छ।', 'nepali'),
      (v_set_id, 3, E'ग्रीक भाषामा सूर्यलाई के भनिन्छ?', E'हेलीयस', E'हेलीयौ', E'सेलेन', E'सेलीयौ', 'A', E'**ग्रीक भाषामा सूर्यलाई हेलीयस भनिन्छ।**\n- ग्रीक भाषामा चन्द्रमालाई सेलेन भनिन्छ।', 'nepali'),
      (v_set_id, 4, E'मनुसुनी महासागरको उपनामले विश्व भूगोलको कुन महासागरलाई बुझिन्छ?', E'आन्ध्र महासागर', E'हिन्द महासागर', E'प्रशान्त महासागर', E'सुमेरु महासागर', 'B', E'**हिन्द महासागरलाई मनुसुनी महासागरको उपनामले चिनिन्छ।** यसलाई तेल महासागर पनि भनिन्छ किनभने विश्वको खनिज तेलको ५० देखि ६० प्रतिशत कच्चा पदार्थको स्रोत यही महासागर हो।\n- आन्ध्र महासागरलाई एटलान्टिक महासागर पनि भनिन्छ।\n- प्रशान्त महासागर विश्वको सबैभन्दा ठूलो र गहिरो महासागर हो।\n- सुमेरु महासागरलाई आर्कटिक महासागर पनि भनिन्छ।\nनोट: हिन्द पौराणिक ग्रन्थहरूमा हिन्द महासागरलाई रत्नाकर भनिएको छ।', 'nepali'),
      (v_set_id, 5, E'नेपालको उत्तर दक्षिण औसत चौडाई कति रहेको छ?', E'१९३ कि.मी.', E'२४१ कि.मी.', E'१४५ कि.मी.', E'८८५ कि.मी.', 'A', E'नेपालको उत्तर दक्षिण औसत चौडाई **१९३ कि.मी.** रहेको छ। यसको अधिकतम चौडाई २४१ कि.मी. र न्यूनतम चौडाई १४५ कि.मी. छ।\nनोट: नेपालको पूर्व-पश्चिम औसत लम्बाई ८८५ कि.मी. रहेको छ।', 'nepali'),
      (v_set_id, 6, E'नेपालको सबैभन्दा लामो नदि कर्णालीको लम्बाई कति रहेको छ?', E'७०५ कि.मी.', E'५१५ कि.मी.', E'७२० कि.मी.', E'१०८० कि.मी.', 'A', E'नेपालको सबैभन्दा लामो नदी कर्णालीको लम्बाई **७०५ कि.मी.** रहेको छ।\n- कोशी नदीको कूल लम्बाई ७२० कि.मी. छ भने नेपालभित्र मात्र यसको लम्बाई २०० कि.मी. छ।\n- गण्डकी नदीको कूल लम्बाई ३३८ कि.मी. छ।', 'nepali'),
      (v_set_id, 7, E'हे ईश्वर मलाई मेरा मित्रहरूबाट जोगाउ शत्रुसँग म आफैं जोगिन्छु यो भनाई कसको हो?', E'नेपोलियन बोर्नपाट', E'मन्टेस्क्यु', E'भोल्टेयर', E'रुसो', 'C', E'उक्त भनाई **भोल्टेयर**को हो।\n- भोल्टेयरका अन्य प्रसिद्ध भनाइहरूमा ''सयओटा मुसाको शासनभन्दा एउटा सिंहको शासन राम्रो हुन्छ'' र ''भ्रष्ट चर्चलाई नष्ट गरिदेऊ'' पर्दछन्।', 'nepali'),
      (v_set_id, 8, E'२०८२ सालमा मनाइएको पृथ्वी जयन्ती कति औं हो?', E'३०३ औं', E'३०४ औं', E'३०५ औं', E'३०६ औं', 'B', E'२०८२ सालमा राष्ट्रनिर्माता पृथ्वीनारायण शाहको **३०४ औं** जन्मजयन्ती तथा राष्ट्रिय एकता दिवस मनाइएको थियो।\nनोट: पृथ्वीनारायण शाहको जन्म १७७९ पुस २७ गते भएको थियो।', 'nepali'),
      (v_set_id, 9, E'गरिबी तथ्यांक, २०८२ अनुसार नेपालमा सबैभन्दा धेरै गरिबी दर रहेको जिल्ला कुन हो?', E'जाजरकोट', E'मुस्ताङ', E'कास्की', E'अछाम', 'D', E'**गरिबी तथ्यांक, २०८२ अनुसार अछाम जिल्लामा सबैभन्दा धेरै गरिबी दर (४९.५८%) रहेको छ।**\n- जाजरकोटको जुनीचाँदे गाउँपालिकामा सबैभन्दा बढी (७७.८९%) गरिबी छ।\n- मुस्ताङको घरपझोङ गाउँपालिकामा सबैभन्दा कम (१.९८%) गरिबी छ।\n- कास्की जिल्लामा सबैभन्दा कम गरिबी दर (५.६३%) रहेको छ।\nनोट: प्रदेशगत रूपमा सुदूरपश्चिम प्रदेशमा गरिबी सबैभन्दा बढी ३४.१६% र गण्डकी प्रदेशमा सबैभन्दा कम ११.८८% छ।', 'nepali'),
      (v_set_id, 10, E'कम्पनी ऐन अन्तर्गत सञ्चालित सार्वजनिक संस्थानको संख्या कति रहेको छ?', E'२२ वटा', E'२३ वटा', E'२४ वटा', E'२६ वटा', 'C', E'**कम्पनी ऐन अन्तर्गत सञ्चालित सार्वजनिक संस्थानको संख्या २४ वटा रहेको छ।**', 'nepali'),
      (v_set_id, 11, E'खस राज्यको राजधानी कहाँ थियो?', E'सिंजा', E'मुसिकोट', E'दुल्लु', E'खलंगा', 'A', E'**खस राज्यको राजधानी जुम्लाको सिंजा थियो।**\n- मुसिकोट रुकुम जिल्लाको सदरमुकाम हो।\n- दुल्लु दैलेख जिल्लामा अवस्थित एक ऐतिहासिक स्थल हो।\n- खलंगा सल्यान जिल्लाको सदरमुकाम हो।', 'nepali'),
      (v_set_id, 12, E'गार्ड फर्क राष्ट्रिय अभियानको सुरुवात कहिले भएको थियो?', E'वि.सं. २०२४', E'वि.सं. २०२८', E'वि.सं. २०१ ९', E'वि.सं. २०३२', 'A', E'गार्ड फर्क राष्ट्रिय अभियानको सुरुवात **वि.सं. २०२४** मा भएको थियो।\n- यो अभियान राजा महेन्द्र वीरविक्रम शाहले सुरु गरेका थिए।', 'nepali'),
      (v_set_id, 13, E'बुद्धले बुद्धत्व प्राप्त गरेको बोधगया कुन नदीको किनारमा अवस्थित छ?', E'यमुना', E'निरञ्जना', E'नर्मदा', E'गंगा', 'B', E'**बुद्धले बुद्धत्व प्राप्त गरेको बोधगया निरञ्जना नदीको किनारमा अवस्थित छ।**\n- यमुना नदी भारतको एक प्रमुख नदी हो, जुन गंगा नदीको सहायक नदी हो।\n- नर्मदा नदी मध्य भारतमा बग्ने एक महत्वपूर्ण नदी हो।\n- गंगा नदी भारतको सबैभन्दा पवित्र र ठूलो नदी हो।', 'nepali'),
      (v_set_id, 14, E'देहायका मध्ये कुन तृतीय उपभोक्ताको उदाहरण हैन?', E'बाघ', E'गोही', E'चिल', E'स्याल', 'D', E'**स्याल तृतीय उपभोक्ताको उदाहरण होइन, यो सामान्यतया द्वितीय उपभोक्ता वा सर्वाहारी हो।**\n- बाघ एक मांसाहारी तृतीय उपभोक्ता हो।\n- गोही एक मांसाहारी तृतीय उपभोक्ता हो।\n- चिल एक मांसाहारी तृतीय उपभोक्ता हो।', 'nepali'),
      (v_set_id, 15, E'बिमस्टेकको स्थापना कुन घोषणा मार्फत भएको थियो?', E'कोलम्बो घोषणा', E'दिल्ली घोषणा', E'ढाका घोषणा', E'बैंकक घोषणा', 'D', E'**बिमस्टेकको स्थापना बैंकक घोषणा मार्फत भएको थियो।**\n- कोलम्बो घोषणा श्रीलंकाको राजधानी कोलम्बोमा जारी गरिएका विभिन्न घोषणाहरूलाई जनाउँछ।\n- दिल्ली घोषणा भारतको राजधानी दिल्लीमा जारी गरिएका विभिन्न घोषणाहरूलाई जनाउँछ।\n- ढाका घोषणा बंगलादेशको राजधानी ढाकामा जारी गरिएका विभिन्न घोषणाहरूलाई जनाउँछ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०१/३१', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_07_26.csv  →  आसमान दैनिक GK — २०८२/०७/२६  (16 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०७/२६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०७/२६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०७/२६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'अरुण तेस्रो जलविद्युत आयोजनाको विद्युत उत्पादन क्षमता कति रहेको छ?', E'१२०० मेगावाट', E'९०० मेगावाट', E'४५६ मेगावाट', E'४४० मेगावाट', 'B', E'अरुण तेस्रो जलविद्युत आयोजनाको विद्युत उत्पादन क्षमता **९०० मेगावाट** रहेको छ। यो अरुण नदीमा निर्माणोन्मुख विद्युत आयोजना हो र संखुवासभा जिल्लाको मकालु गाउँपालिकामा अवस्थित छ।', 'nepali'),
      (v_set_id, 2, E'नेपाली इतिहासको पहिलो संविधान कुन प्रधानमन्त्रीको पालामा निर्माण भएको थियो?', E'पद्म शमशेर', E'मोहन शमशेर', E'भीम शमशेर', E'भिमसेन थापा', 'A', E'नेपालको पहिलो संविधान ''नेपाल सरकारको वैधानिक कानुन २००४'' **पद्म शमशेर**को पालामा जारी भएको थियो। यो संविधान २००४ माघ १३ गते जारी भएको थियो र जनताको नाममा संविधान बनाएकोले पद्म शमशेरले राजीनामा दिनुपरेको थियो।\n- मोहन शमशेर राणा शासनका अन्तिम प्रधानमन्त्री थिए।\n- भीम शमशेरले सती प्रथामा आंशिक रोक लगाएका थिए।\n- भीमसेन थापा नेपालका प्रथम प्रधानमन्त्री हुन्।', 'nepali'),
      (v_set_id, 3, E'विश्वको सबैभन्दा धेरै मुलुक भएको महादेश कुन हो?', E'एसिया', E'अफ्रिका', E'युरोप', E'उत्तर अमेरिका', 'B', E'विश्वमा सबैभन्दा धेरै मुलुक भएको महादेश **अफ्रिका** हो।\n| महादेश | देश संख्या |\n| --- | --- |\n| अफ्रिका | ५४ |\n| एसिया | ४८ |\n| युरोप | ४४ |\n| उत्तर अमेरिका | २३ |\n| अस्ट्रेलिया | १४ |\n| दक्षिण अमेरिका | १२ |\nनोट: विश्वमा कुल १९५ देश छन्, जसमध्ये १९३ संयुक्त राष्ट्र संघका सदस्य राष्ट्र हुन् र होली सी (भ्याटिकन सिटी) तथा प्यालेस्टाइन गैर-सदस्य पर्यवेक्षक राष्ट्र हुन्।', 'nepali'),
      (v_set_id, 4, E'सबैभन्दा बढी वनक्षेत्र भएको नेपाली जिल्ला कुन हो?', E'अर्घाखाँची', E'भक्तपुर', E'कास्की', E'ललितपुर', 'A', E'**अर्घाखाँची जिल्लामा नेपालको सबैभन्दा बढी वनक्षेत्र रहेको छ।**\n- भक्तपुर जिल्लामा भने सबैभन्दा कम प्रतिशत वनक्षेत्र रहेको छ।', 'nepali'),
      (v_set_id, 5, E'लिच्छविकालिन समयमा सिपाहीलाई के भनिन्थ्यो?', E'दण्डनायक', E'भट्ट', E'युवराज', E'अमात्य', 'B', E'**लिच्छविकालिन समयमा सिपाहीलाई भट्ट भनिन्थ्यो।**\n- दण्डनायक प्रहरी प्रमुख हुन्।\n- युवराज भावी राजा हुन्।\n- अमात्य मन्त्री हुन्।', 'nepali'),
      (v_set_id, 6, E'विश्वमा नेपाल कति औं धर्म निरपेक्ष मुलुक हो?', E'२२ औं', E'१९ औं', E'२० औं', E'१६ औं', 'D', E'नेपाल विश्वको **१६ औं** धर्मनिरपेक्ष मुलुक हो। नेपाल २०६३ जेठ ४ गते धर्मनिरपेक्ष राष्ट्र घोषणा भएको थियो।\nनोट: नेपालको वर्तमान संविधानको भाग ३ को धारा २५ मा धार्मिक स्वतन्त्रता सम्बन्धी व्यवस्था रहेको छ।', 'nepali'),
      (v_set_id, 7, E'हालसालै चन्द्रमाको दक्षिणी ध्रुवमा रहेको एउटा क्रेटर नेपाली व्यक्तित्वको नाम बाट नामाकरण गरिएको छ। भन्नुहोस् उहाँको नाम के हो?', E'पासाङ ल्हामु शेर्पा', E'पृथ्वीनारायण शाह', E'महाबिर पुन', E'सन्दुक रुइत', 'A', E'हालसालै चन्द्रमाको दक्षिणी ध्रुवमा रहेको एउटा क्रेटर सगरमाथा आरोहण गर्ने पहिलो नेपाली महिला **पासाङ ल्हामु शेर्पाको** नामबाट नामाकरण गरिएको छ। यस क्रेटरको नाम ''ल्हामु'' राखिएको छ।', 'nepali'),
      (v_set_id, 8, E'ऐनाको प्रयोग गरेर सूर्यको प्रकाशद्वारा शत्रुहरूको जहाज जलाइदिएका वैज्ञानिक को हुन्?', E'आर्किमिडिज', E'अल्बर्ट आइन्स्टाइन', E'सर आइज्याक न्युटन', E'ग्यालिलियो ग्यालिलिली', 'A', E'ऐनाको प्रयोग गरेर सूर्यको प्रकाशद्वारा शत्रुहरूको जहाज जलाइदिएका वैज्ञानिक **आर्किमिडिज** हुन्। उनले सूर्य र चन्द्रमाको व्यास नाप्ने तरिका र उत्तोलकको सिद्धान्त पनि प्रतिपादन गरेका थिए।\nनोट: ''Measurement of Circle'' आर्किमिडिजको प्रसिद्ध कृति हो।', 'nepali'),
      (v_set_id, 9, E'अमेरिकाको न्यूयोर्क सहरमा हालसालै मेयर चुनावमा निर्वाचित चर्चित राजनीतिको हुन् ?', E'एन्ड्रयु कुमो', E'जोहरान ममदानी', E'कर्टिस सिल्वा', E'मिरा नायर', 'B', E'न्यूयोर्क सहरको हालसालै सम्पन्न मेयर चुनावमा **जोहरान ममदानी** निर्वाचित भएका छन्। उनी ३४ वर्षका छन् र न्यूयोर्कको पहिलो मुस्लिम मेयर बनेका छन्।\nनोट: ममदानीले २०२६ जनवरी १ मा पदभार ग्रहण गरेपछि यो शताब्दीका न्यूयोर्कका सबैभन्दा कान्छा मेयर बन्नेछन्।', 'nepali'),
      (v_set_id, 10, E'आसियानको कान्छो तथा ११ औं सदस्यको रुपमा सदस्य बनेको नयाँ सदस्य मुलुक कुन हो ?', E'पूर्वी टिमोर', E'बंगलादेश', E'कम्बोडिया', E'लाओस', 'A', E'**पूर्वी टिमोर** सन् २०२४ अक्टोबर २६ मा आसियानको ११ औं तथा कान्छो सदस्य राष्ट्र बनेको छ।\n- कम्बोडिया सन् १९९९ अप्रिल ३० मा आसियानको १० औं सदस्य राष्ट्र बनेको थियो।', 'nepali'),
      (v_set_id, 11, E'सिमसार दिवस कहिले मनाइन्छ?', E'जनवरी २', E'फेब्रुअरी २', E'मार्च २', E'अप्रिल २', 'B', E'विश्व सिमसार दिवस हरेक वर्ष **फेब्रुअरी २** मा मनाइन्छ।\n- सिमसार भन्नाले भिजेको वा पानी भएको स्थान बुझिन्छ, जहाँ पानी नसुक्ने जमिन हुन्छ।', 'nepali'),
      (v_set_id, 12, E'सन् २०२४ मा सम्पन्न १३ औं आईसीसी महिला एक दिवसीय क्रिकेट विश्वकपको उपाधि जित्ने राष्ट्र कुन हो?', E'माल्दिभ्स', E'दक्षिण अफ्रिका', E'श्रीलंका', E'भारत', 'D', E'सन् २०२४ मा सम्पन्न १३ औं आईसीसी महिला एक दिवसीय क्रिकेट विश्वकपको उपाधि **भारतले** जितेको थियो।', 'nepali'),
      (v_set_id, 13, E'चिनियाँ सभ्यतामा राजतन्त्रात्मक व्यवस्था हुँदा शासन गरेको अन्तिम वंश कुन हो?', E'शिया वंश', E'हाङ वंश', E'छिङ वंश', E'शान वंश', 'C', E'**चिनियाँ सभ्यतामा राजतन्त्रात्मक व्यवस्था हुँदा शासन गरेको अन्तिम वंश छिङ वंश हो।**\n- शिया वंश चीनको पहिलो वंश मानिन्छ, जसले ई.पू. २१०० देखि ई.पू. १६०० सम्म शासन गरेको थियो।\n- हाङ वंशले ई.पू. २५० तिर शासन गरेको थियो, जसपछि सार्वजनिक प्रशासनमा Meritocracy system व्यवस्था सुरु भएको थियो।\n- चीनमा शिया वंशदेखि छिङ वंशसम्म १७ वंशले शासन गरेको पाइन्छ।', 'nepali'),
      (v_set_id, 14, E'२०२६ बाट कार्यकाल सुरु हुने गरि सुरक्षा परिषद्मा निर्वाचित नयाँ मुलुक देहायका मध्ये कुन हो?', E'कम्बोडिया', E'कंगो', E'पाकिस्तान', E'भुटान', 'B', E'**सन् २०२६ बाट कार्यकाल सुरु हुने गरी सुरक्षा परिषद्मा निर्वाचित नयाँ मुलुक कंगो हो।**\n- बहराइन, लाइबेरिया, कोलम्बिया र लाटभिया पनि कंगोसँगै सुरक्षा परिषद्मा निर्वाचित भएका अन्य मुलुकहरू हुन्।\nनोट: यी मुलुकहरूको कार्यकाल सन् २०२६ जनवरी १ बाट सुरु भई सन् २०२७ डिसेम्बर ३१ मा समाप्त हुनेछ।', 'nepali'),
      (v_set_id, 15, E'संयुक्त राष्ट्र संघको महासभाको पहिलो बैठक कहाँ बसेको थियो?', E'बेलायत', E'अमेरिका', E'नर्वे', E'जर्मनी', 'A', E'**संयुक्त राष्ट्र संघको महासभाको पहिलो बैठक बेलायतको लन्डनमा बसेको थियो।**\n- यो बैठक १० जनवरी १९४६ मा लन्डनको मेथोडिस्ट सेन्ट्रल हलमा बसेको थियो।\n- महासभाको पहिलो बैठकमा ५१ संस्थापक राष्ट्रका प्रतिनिधिहरू सहभागी थिए।', 'nepali'),
      (v_set_id, 16, E'विश्वको सबैभन्दा धेरै मुलुक भएको महादेश कुन हो?', E'एसिया', E'अफ्रिका', E'युरोप', E'उत्तर अमेरिका', 'B', E'**विश्वको सबैभन्दा धेरै मुलुक भएको महादेश अफ्रिका हो।**\n- अफ्रिकामा ५४ देश छन्।\n- एसियामा ४८ देश छन्।\n- युरोपमा ४४ देश छन्।\n- उत्तर अमेरिकामा २३ देश छन्।\nनोट: विश्वमा कुल १९५ देश छन्, जसमध्ये १९३ संयुक्त राष्ट्र संघका सदस्य राष्ट्र हुन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०७/२६', 16;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_07_27.csv  →  आसमान दैनिक GK — २०८२/०७/२७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०७/२७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०७/२७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०७/२७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'ग्लोबल पिस इन्डेक्स २०२५ अनुसार नेपाल कति औं स्थानमा रहेको छ ?', E'७५ औं', E'७६ औं', E'७७ औं', E'७८ औं', 'B', E'ग्लोबल पिस इन्डेक्स २०२५ को प्रतिवेदन अनुसार नेपाल **७६ औं स्थानमा** रहेको छ। यस सूचीमा आइसल्यान्डले प्रथम स्थान हासिल गरेको छ भने सार्क राष्ट्र भुटान २१ औं स्थानमा रहेको छ।', 'nepali'),
      (v_set_id, 2, E'२०८२ मा मनाइएको बुद्ध जयन्ती कति औं हो?', E'२५६६ औं', E'२५६७ औं', E'२५६८ औं', E'२५६९ औं', 'D', E'सन् २०८२ मा मनाइएको बुद्ध जयन्ती **२५६९ औं** संस्करण हो। सिद्धार्थ गौतमको २५६९ औं जयन्ती २०८२ मा मनाइएको हो।\nनोट: प्रत्येक वर्ष वैशाख शुक्ल पूर्णिमाका दिन बुद्ध जयन्ती मनाइन्छ, जुन सिद्धार्थ गौतमले विश्व शान्ति स्थापनाका लागि पुऱ्याएको योगदानको स्मरण स्वरुप मनाइने पर्व हो।', 'nepali'),
      (v_set_id, 3, E'संयुक्त राष्ट्रसंघीय शैक्षिक, वैज्ञानिक तथा सांस्कृतिक संगठन (युनेस्को) द्वारा संगीतको सिर्जनात्मक सहरको रुपमा घोषित नेपालको सहर कुन हो ?', E'ललितपुर म.न.पा.', E'भरतपुर म.न.पा.', E'विराटनगर म.न.पा.', E'पोखरा म.न.पा.', 'A', E'युनेस्कोले ललितपुर महानगरपालिकालाई **संगीतको सिर्जनात्मक सहरका रुपमा** घोषणा गरेको छ।\n- युनेस्कोले सन् २०२५ अक्टोबर ३१ तारिख (विश्व सहर दिवसको अवसर) मा यो घोषणा गरेको हो।', 'nepali'),
      (v_set_id, 4, E'सञ्चार तथा सूचना प्रविधि मन्त्रालयमा राष्ट्रिय एआई केन्द्रको स्थापना कहिले भएको हो ?', E'२०८२ कार्तिक २७', E'२०८२ कार्तिक २६', E'२०८२ कार्तिक २५', E'२०८२ कार्तिक २४', 'D', E'सञ्चार तथा सूचना प्रविधि मन्त्रालयमा राष्ट्रिय एआई केन्द्रको स्थापना **२०८२ कार्तिक २४** मा भएको हो।\n- सञ्चार तथा सूचना प्रविधिमन्त्री जगदीश खरेलले यस केन्द्रको उद्घाटन गरेका थिए।', 'nepali'),
      (v_set_id, 5, E'सामान्यतया: स्थानीय तहको बजेट प्रस्तुत कसले गर्ने प्रावधान रहेको छ?', E'वडा अध्यक्ष', E'अध्यक्ष, प्रमुख', E'उपाध्यक्ष, उपप्रमुख', E'प्रमुख प्र. अधिकृत', 'C', E'**स्थानीय तहको बजेट उपाध्यक्ष वा उपप्रमुखले प्रस्तुत गर्ने प्रावधान रहेको छ।**\n- वडा अध्यक्षले वडाको बजेट तथा कार्यक्रम प्रस्तुत गर्छन्।\n- अध्यक्ष वा प्रमुख स्थानीय तहको कार्यकारी प्रमुख हुन्।\n- प्रमुख प्रशासकीय अधिकृत स्थानीय तहको प्रशासनिक प्रमुख हुन्।', 'nepali'),
      (v_set_id, 6, E'जलवायु परिवर्तनसम्बन्धी संयुक्त राष्ट्रसंघीय संरचना महासन्धिमा पक्ष राष्ट्रहरूको ३० औं सम्मेलन (कोप-३०) सञ्चालन मिति कुन सहि रहेको छ?', E'२०२५ नोभेम्बर ११-२१', E'२०२५ नोभेम्बर १०-२१', E'२०२५ नोभेम्बर ११-२२', E'२०२५ नोभेम्बर १२-२२', 'B', E'**सन् २०२५ नोभेम्बर १०-२१ मा जलवायु परिवर्तनसम्बन्धी संयुक्त राष्ट्रसंघीय संरचना महासन्धिमा पक्ष राष्ट्रहरूको ३० औं सम्मेलन (कोप-३०) ब्राजिलको बेलेममा सम्पन्न भएको थियो।**\n- कोप २९ सन् २०२४ नोभेम्बर ११-२२ मा बाकु, अजरबैजानमा सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 7, E'१७ औं BRICS सम्मेलन २०२५ कहाँ सम्पन्न भएको छ?', E'ब्राजिल', E'भारत', E'दक्षिण अफ्रिका', E'इन्डोनेसिया', 'A', E'**१७ औं BRICS सम्मेलन सन् २०२५ मा ब्राजिलको रियो दि जेनेरियोमा सम्पन्न भएको थियो।**\n- भारत, चीन र दक्षिण अफ्रिका BRICS का संस्थापक सदस्य राष्ट्रहरू हुन्।\n- सन् २०२४ देखि साउदी अरेबिया, इजिप्ट, इथियोपिया, इरान र युएई BRICS मा थपिएका हुन्।\n- इन्डोनेसिया सन् २०२५ जनवरी ६ मा BRICS मा थपिएको थियो।', 'nepali'),
      (v_set_id, 8, E'संयुक्त राष्ट्रसंघ महासभाको नयाँ अध्यक्षको रुपमा निर्वाचित अन्नालेना शार्लोट अल्मा बेरेबक कुन मुलुककी हुन्?', E'जर्मनी', E'बेलायत', E'पेरु', E'कम्बोडिया', 'A', E'**जर्मनीकी कूटनीतिज्ञ तथा राजनीतिज्ञ अन्नालेना शार्लोट अल्मा बेरेबक** १ सेप्टेम्बर २०२४ देखि १ वर्षको कार्यकालको लागि संयुक्त राष्ट्रसंघ महासभाको ८० औं अध्यक्षको रुपमा निर्वाचित भइन्।', 'nepali'),
      (v_set_id, 9, E'संयुक्त राष्ट्रसंघ महासभाको २०२४ मा आयोजना भएको कति औं सत्रको महासभा बैठक हो?', E'७८ औं', E'७९ औं', E'८० औं', E'८१ औं', 'C', E'**संयुक्त राष्ट्रसंघ महासभाको ८० औं सत्र** सन् २०२४ मा आयोजना भएको थियो।\nनोट: यो सत्र १ सेप्टेम्बर २०२४ देखि ८ सेप्टेम्बर २०२६ सम्मका लागि तय भएको छ र यसको बैठक अमेरिकाको न्यूयोर्कमा २०२४ सेप्टेम्बर २३ देखि २९ सम्म भएको थियो।', 'nepali'),
      (v_set_id, 10, E'हाल सालै नेपालकी जीवित देवी उपाधिले चिनिने कुमारी पदमा कसलाई चयन गरियो?', E'आर्यातारा शाक्य', E'प्रतिस्था शाक्य', E'तृष्णा शाक्य', E'दिनुषा शाक्य', 'A', E'**२०८२ असोज १४ गते आर्यातारा शाक्यलाई** जीवित देवी कुमारी पदमा नवनियुक्त गरिएको हो। गुठी संस्थानको २०८२ असोज ९ गतेको निर्णय अनुसार उनलाई नियुक्त गरिएको थियो।\nनोट: परम्परा अनुसार यसअघिकी कुमारी तृष्णा शाक्यको कुमारी बस्ने औसत उमेर १२ वर्ष पूरा भएकोले दशैंको महाअष्टमीका दिन कुमारीघर वसन्तपुरमा नयाँ कुमारी भित्र्याइएको थियो।', 'nepali'),
      (v_set_id, 11, E'पुरुष तर्फ बालोन डी ओर अवार्ड-२०२४ जित्ने फुटबल खेलाडी को हुन्?', E'आइटाना बोनमटी', E'ओस्मान डेम्बेले', E'रोड्री', E'लियोनल मेस्सी', 'B', E'**सन् २०२४ को पुरुष बालोन डी ओर अवार्ड ओस्मान डेम्बेलेले जितेका थिए।**\nनोट: महिलातर्फ सन् २०२४ को बालोन डी ओर अवार्ड आइटाना बोनमटीले जितेकी थिइन्।', 'nepali'),
      (v_set_id, 12, E'जेनजी आन्दोलनको परिणाम स्वरूप हालै सत्ता परिवर्तन हुन पुगेको अफ्रिकी मुलुक कुन हो ?', E'युगान्डा', E'क्यामरुन', E'माडागास्कर', E'द. अफ्रिका', 'C', E'जेनजी आन्दोलनको परिणाम स्वरूप **माडागास्करमा** सत्ता परिवर्तन भएको हो। सन् २०२५ सेप्टेम्बर २५ देखि सुरु भएको आन्दोलनपछि त्यहाँको एलिट युनिट क्यापसाटले राष्ट्रपति एन्ड्री रजोएलिनालाई पदच्युत गरी सत्ता कब्जा गरेको थियो।', 'nepali'),
      (v_set_id, 13, E'जेनजी पुस्ताद्वारा आन्दोलनका क्रममा काठमाडौँलगायत मुलुकका विभिन्न भागमा मृत्यु भएकालाई सरकारले सहिद घोषणा गर्ने निर्णय कहिले गरेको हो ?', E'२०८२ कात्तिक १५', E'२०८२ कात्तिक १६', E'२०८२ कात्तिक १७', E'२०८२ कात्तिक १८', 'C', E'सरकारले जेनजी पुस्ताद्वारा गरिएको आन्दोलनका क्रममा मृत्यु भएका ४५ जनालाई सहिद घोषणा गर्ने निर्णय **२०८२ कात्तिक १७** गते गरेको हो। राष्ट्र हित, सुशासन तथा भ्रष्टाचार नियन्त्रणको माग राखी २०८२ भदौ २३ र २४ गते प्रदर्शन भएको थियो।', 'nepali'),
      (v_set_id, 14, E'कार्यसम्पादन मूल्यांकन (आर्थिक वर्ष २०८१/८२) मा देशभरिकै उत्कृष्ट कार्यालय बन्न सफल जिल्ला प्रशासन कार्यालय कुन हो ?', E'पर्वत', E'स्याङ्जा', E'कास्की', E'चितवन', 'A', E'आर्थिक वर्ष २०८१/८२ को कार्यसम्पादन मूल्यांकनमा **पर्वत जिल्ला प्रशासन कार्यालय** देशभरिकै उत्कृष्ट बनेको छ। गृह मन्त्रालयको मूल्यांकनमा पर्वतले ९५.७९ अंक प्राप्त गरी पहिलो स्थान हासिल गरेको हो।\nनोट: मूल्यांकनमा भक्तपुर दोस्रो, नुवाकोट तेस्रो, मनाङ चौथो र धनकुटा पाँचौ स्थानमा रहेका थिए।', 'nepali'),
      (v_set_id, 15, E'हाल नेपालसँग दोहोरो करमुक्ति सम्झौता भएका मुलुक कति रहेका छन् ?', E'१० मुलुक', E'११ मुलुक', E'१२ मुलुक', E'१३ मुलुक', 'A', E'हाल नेपालसँग दोहोरो करमुक्ति सम्झौता भएका मुलुकको संख्या **१०** रहेको छ। नेपाल र मौरिससबीचको सम्झौता सन् २०२५ अक्टोबर २९ मा रद्द भएपछि यो संख्या ११ बाट घटेर १० कायम भएको हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०७/२७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_07_30.csv  →  आसमान दैनिक GK — २०८२/०७/३०  (28 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०७/३०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०७/३०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०७/३०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको संविधानको कुन धारामा सर्वोच्च अदालतसँग सम्बन्धी व्यवस्था रहेको छ?', E'धारा १४८', E'धारा १२७', E'धारा १३९', E'धारा १२८', 'D', E'**नेपालको संविधानको धारा १२८ मा सर्वोच्च अदालतसम्बन्धी व्यवस्था रहेको छ।**\n- धारा १२७ मा अदालतहरू सम्बन्धी सामान्य व्यवस्था छ।\n- धारा १३९ मा उच्च अदालतसम्बन्धी व्यवस्था छ।\n- धारा १४८ मा जिल्ला अदालतसम्बन्धी व्यवस्था छ।\nनोट: नेपालको संविधानको भाग-११ न्यायपालिका अन्तर्गत अदालतसम्बन्धी व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 2, E'देहायका सौर्यमण्डलका ग्रहहरू मध्ये आफ्नो अक्षमा सबैभन्दा बढी बेगले घुम्ने ग्रह कुन हो?', E'अरुण', E'शुक्र', E'बुध', E'बृहस्पति', 'D', E'**सौर्यमण्डलका ग्रहहरू मध्ये बृहस्पति आफ्नो अक्षमा सबैभन्दा बढी बेगले घुम्ने ग्रह हो।**\n- बुध सूर्यको वरिपरि घुम्नको लागि सबैभन्दा छोटो दूरी भएकाले, सौर्यमण्डलको सबैभन्दा छोटो वर्ष ८८ दिनको हुन्छ।\n- शुक्र आफ्नो अक्षमा धेरै ढिलो घुम्छ र यसको परिक्रमा अवधि पृथ्वीको भन्दा लामो हुन्छ।\n- वरुणलाई सूर्यको परिक्रमा गर्न लगभग १६४ पृथ्वी वर्ष लाग्छ।\nनोट: बृहस्पति हरेक १० घण्टा (९ घण्टा ५५ मिनेट ३० सेकेन्ड) मा आफ्नो अक्षमा एक फन्को लगाउँछ।', 'nepali'),
      (v_set_id, 3, E'धनी र गरिबीबीचको असमानता देखाउन प्रायः कुन गरिबी प्रयोग हुन्छ?', E'निरपेक्ष गरिबी', E'सापेक्ष गरिबी', E'संरचनात्मक गरिबी', E'मौसमी गरिबी', 'B', E'**धनी र गरिबीबीचको असमानता देखाउन प्रायः सापेक्ष गरिबी प्रयोग गरिन्छ।**\n- निरपेक्ष गरिबीले आधारभूत आवश्यकताहरू (खाना, पानी, आवास) पूरा गर्न नसक्ने अवस्थालाई जनाउँछ।\n- संरचनात्मक गरिबी आर्थिक प्रणालीमा हुने संरचनात्मक समस्याका कारण उत्पन्न हुन्छ।\n- मौसमी गरिबी विशेष मौसम वा समयमा मात्र देखिने गरिबी हो, जस्तै कृषिमा आधारित कामदारहरूमा।\nनोट: UN र विश्व बैंकका अनुसार कम आय भएका अर्थतन्त्रहरूमा चरम गरिबी मापन गर्न प्रयोग गरिने अन्तर्राष्ट्रिय गरिबी रेखा २०२४ को नवीनतम तथ्यांक अनुसार प्रति व्यक्ति प्रति दिन $२.१५ हो।', 'nepali'),
      (v_set_id, 4, E'विश्वकै लामो मानिएको केबलकार नेपालको कुन कुन स्थान जोड्ने गरि निर्माण हुने भएको छ?', E'पोखरादेखि मुक्तिनाथ', E'नवलपुर देखि पोखरा', E'चन्द्रागिरी देखि मनकामना', E'होलेसी देखि पाथिभरा', 'A', E'**पोखरादेखि मुक्तिनाथसम्म विश्वकै लामो केबलकार निर्माण हुने भएको छ।**\n- चन्द्रागिरी केबलकार काठमाडौंको चन्द्रागिरी डाँडामा अवस्थित छ र यसले चन्द्रागिरी मन्दिरसम्म पुर्‍याउँछ।\n- मनकामना केबलकार गोरखा जिल्लामा अवस्थित छ र यसले मनकामना मन्दिरसम्म पुर्‍याउँछ।\n- होलेसी केबलकार खोटाङ जिल्लामा अवस्थित छ र यसले हलेसी महादेव मन्दिरसम्म पुर्‍याउँछ।\nनोट: यो केबलकार करिब ८१ कि.मि. लामो हुनेछ र यसको लागि ५७ अर्ब ६४ करोड लगानी स्वीकृत भएको छ।', 'nepali'),
      (v_set_id, 5, E'संसारको सबैभन्दा अग्लो भवन बुर्ज खलिफा कुन एसियाली मुलुकमा रहेको छ?', E'कतार', E'युएई', E'साउदी अरेबिया', E'चीन', 'B', E'**बुर्ज खलिफा संयुक्त अरब इमिरेट्स (युएई) को दुबईमा अवस्थित संसारको सबैभन्दा अग्लो भवन हो।**\nनोट: यसको उचाइ ८२८ मिटर (२,७१७ फिट) छ।', 'nepali'),
      (v_set_id, 6, E'नेपालको कुल क्षेत्रफलको कति भू-भाग नदीनालाले ओगटेको छ?', E'३.९ प्रतिशत', E'३.०९ प्रतिशत', E'७.०६ प्रतिशत', E'७.६ प्रतिशत', 'A', E'**नेपालको कुल क्षेत्रफलको ३.९ प्रतिशत भू-भाग नदीनालाले ओगटेको छ।**\n- नेपालको स्थलक्षेत्र १२.९४% छ भने जलक्षेत्र ७.०६% रहेको छ।', 'nepali'),
      (v_set_id, 7, E'नेपाल सरकारले नियुक्त गरेका नवनियुक्त नेपाल विद्युत प्राधिकरणको कार्यकारी निर्देशक को हुन्?', E'मनोज सिलवाल', E'हितेन्द्र शाक्य', E'कुलमान घिसिङ', E'रेशम पाण्डे', 'A', E'**नेपाल विद्युत प्राधिकरणको कार्यकारी निर्देशकमा मनोज सिलवाललाई नियुक्त गरिएको छ।**\n- हितेन्द्र शाक्य यसअघिका कार्यकारी निर्देशक थिए जसलाई हटाएर सिलवाललाई नियुक्त गरिएको हो।\n- कुलमान घिसिङ नेपाल विद्युत प्राधिकरणका पूर्व कार्यकारी निर्देशक हुन् र उनी लोडसेडिङ अन्त्य गर्न सफल भएकाले लोकप्रिय छन्।\nनोट: सरकारले २०८२ असोज ५ गतेको मन्त्री परिषद् बैठकबाट यो निर्णय गरेको हो।', 'nepali'),
      (v_set_id, 8, E'पद्मश्री साहित्य पुरस्कार, २०८२ कसलाई प्रदान गरिएको छ?', E'रमेश भुसाल', E'तुलसी दिवस', E'रमा शर्मा', E'अभिनारायण सुवेदी', 'A', E'**पद्मश्री साहित्य पुरस्कार, २०८२ रमेश भुसाललाई उनको कृति ''छलबाटो'' का लागि प्रदान गरिएको छ।**\n- रमा शर्मालाई पद्मश्री साधना सम्मान, २०८२ प्रदान गरिएको छ।\n- प्राडा अभिनारायण सुवेदीलाई पद्मश्री गौरव पुरस्कार, २०८२ प्रदान गरिएको छ।', 'nepali'),
      (v_set_id, 9, E'हे ईश्वर मलाई मेरा मित्रहरूबाट जोगाउ शत्रुसँग म आफै जोगिन्छु यो भनाइ कसको हो?', E'नेपोलियन बोर्नपाट', E'मन्टेस्क्यु', E'भोल्टेयर', E'रुसो', 'C', E'**''हे ईश्वर मलाई मेरा मित्रहरूबाट जोगाउ शत्रुसँग म आफै जोगिन्छु'' भन्ने भनाइ भोल्टेयरको हो।**\n- भोल्टेयरले ''सयओटा मुसाको शासनभन्दा एउटा सिंहको शासन राम्रो हुन्छ'' र ''भ्रष्ट चर्चलाई नष्ट गरिदेऊ'' जस्ता भनाइहरू पनि व्यक्त गरेका थिए।', 'nepali'),
      (v_set_id, 10, E'हड्डीहरूको अध्ययन गर्ने विज्ञानको शास्त्रलाई के भनिन्छ?', E'एग्रोलोजी', E'इकोलोजी', E'एनाटोमी', E'अस्टियोलोजी', 'D', E'**हड्डीहरूको अध्ययन गर्ने विज्ञानको शास्त्रलाई अस्टियोलोजी भनिन्छ।**\n- एनाटोमीले मानवशरीरको संरचनाको अध्ययन गर्छ।\n- इकोलोजीले परिस्थितिको अध्ययन गर्छ।\n- एग्रोलोजीले भूमि (माटो) को अध्ययन गर्छ।', 'nepali'),
      (v_set_id, 11, E'उत्पादकलाई पोषक तत्वहरू प्रदान गरी पुनः उत्पादनमा मद्दत गर्ने कार्य कसको हो?', E'प्राथमिक उपभोक्ता', E'तृतीय उपभोक्ता', E'विच्छेदक', E'अजैविक तत्वको', 'C', E'**उत्पादकलाई पोषक तत्वहरू प्रदान गरी पुनः उत्पादनमा मद्दत गर्ने कार्य विच्छेदकको हो।**\n- प्राथमिक उपभोक्ताले उत्पादकलाई सिधै उपभोग गर्छन्।\n- तृतीय उपभोक्ताले प्राथमिक र द्वितीय उपभोक्तालाई उपभोग गर्छन्।\n- अजैविक तत्वहरूले वातावरणमा भौतिक र रासायनिक घटकहरू समावेश गर्छन्।', 'nepali'),
      (v_set_id, 12, E'Point four program देहायमध्ये केसँग सम्बन्धित छ?', E'राजनीतिक विकास', E'भौतिक विकास', E'आर्थिक विकास', E'मानव विकास', 'C', E'Point Four Program **आर्थिक विकास**सँग सम्बन्धित छ। यो कार्यक्रम सन् १९५१ मा अमेरिकाले नेपाललाई पहिलो पटक $२२००० को आर्थिक सहयोग प्रदान गर्न सुरु गरेको थियो।', 'nepali'),
      (v_set_id, 13, E'देहायका मध्ये कुन जिल्ला साक्षर जिल्ला घोषणा हुन बाँकी रहेको छ?', E'हुम्ला', E'डोल्पा', E'कालिकोट', E'दार्चुला', 'B', E'**नेपालमा डोल्पा जिल्ला साक्षर जिल्ला घोषणा हुन बाँकी रहेको छ।**\n- हुम्ला कर्णाली प्रदेशको आठौं साक्षर जिल्ला हो।\n- कालिकोट कर्णाली प्रदेशको नवौं साक्षर जिल्ला हो।\n- दार्चुला सुदूरपश्चिम प्रदेशको साक्षर जिल्ला हो।\nनोट: हालसम्म कुनै पनि जिल्ला साक्षर घोषणा नभएको प्रदेश मधेश हो।', 'nepali'),
      (v_set_id, 14, E'पहिलो बैंक नोट जारी गर्ने मुलुक कुन हो?', E'चीन', E'स्वीडेन', E'जापान', E'अमेरिका', 'B', E'**विश्वमा पहिलो बैंक नोट जारी गर्ने मुलुक स्वीडेन हो।**\n- चीन कागजी मुद्रा जारी गर्ने पहिलो देश हो।\n- जापान राष्ट्रिय गान प्रचलित गर्ने पहिलो देश हो।\n- संयुक्तराज्य अमेरिका संविधान बनाउने पहिलो देश हो।', 'nepali'),
      (v_set_id, 15, E'बाल्टिक सागर, क्यारिबियन सागर, भूमध्यसागर र मेक्सिकोको खाडी आदि रहेको महासागर कुन हो?', E'आन्ध्र महासागर', E'हिन्द महासागर', E'प्रशान्त महासागर', E'कुमेरु महासागर', 'A', E'**बाल्टिक सागर, क्यारिबियन सागर, भूमध्यसागर र मेक्सिकोको खाडी आन्ध्र महासागरमा रहेका छन्।**\n- हिन्द महासागर विश्वको तेस्रो ठूलो महासागर हो।\n- प्रशान्त महासागर विश्वको सबैभन्दा ठूलो र गहिरो महासागर हो।\n- कुमेरु महासागर अन्टार्कटिका महाद्वीपलाई घेरेको छ।\nनोट: आन्ध्र महासागरमा राइन, सेनेगल, नाइजर, कङ्गो, मिसिसिपी र अमेजन जस्ता प्रमुख नदीहरू मिल्छन्।', 'nepali'),
      (v_set_id, 16, E'नाम्खा पछिको ठूलो गाउँपालिका कुन हो?', E'फक्ताङलुङ', E'चुमनुब्री', E'मुगुम कार्मारोङ', E'खुम्बु पासाङ ल्हामु', 'C', E'**नेपालको सबैभन्दा ठूलो गाउँपालिका नाम्खा (हुम्ला) पछि मुगुम कार्मारोङ (मुगु) हो।**\n- फक्ताङलुङ ताप्लेजुङ जिल्लामा अवस्थित छ।\n- चुमनुब्री गोरखा जिल्लामा अवस्थित छ।\n- खुम्बु पासाङ ल्हामु सोलुखुम्बु जिल्लामा अवस्थित छ।\nनोट: नेपालका ठूला गाउँपालिकाहरूको क्रम नाम्खा (हुम्ला), मुगुम कार्मारोङ (मुगु), फक्ताङलुङ (ताप्लेजुङ), चुमनुब्री (गोरखा) र खुम्बु पासाङ ल्हामु (सोलुखुम्बु) हुन्।', 'nepali'),
      (v_set_id, 17, E'शक्ति पृथकीकरणको सिद्धान्तका प्रतिपादक को हुन्?', E'नेपोलियन बोनापार्ट', E'मन्टेस्क्यु', E'भोल्टेयर', E'रुसो', 'B', E'**शक्ति पृथकीकरणको सिद्धान्तका प्रतिपादक मन्टेस्क्यु हुन्।**\n- नेपोलियन बोनापार्ट फ्रान्सका सम्राट र सैन्य नेता थिए।\n- भोल्टेयर फ्रान्सेली प्रबुद्ध युगका लेखक, इतिहासकार र दार्शनिक थिए।\n- रुसो फ्रान्सेली दार्शनिक थिए जसले सामाजिक सम्झौताको सिद्धान्त प्रतिपादन गरे।\nनोट: मन्टेस्क्युले सन् १७४८ मा ''द स्पिरिट अफ ल'' (The Spirit of Law) नामक पुस्तकमा शक्ति पृथकीकरणको सिद्धान्तबारे विस्तृत व्याख्या गरेका थिए।', 'nepali'),
      (v_set_id, 18, E'ललितपुरमा मानव बस्ती बसाल्ने राजा को हुन्?', E'वरदेव', E'आनन्ददेव', E'शिवदेव', E'गुणकामदेव', 'B', E'**ललितपुरमा मानव बस्ती बसाल्ने राजा आनन्ददेव हुन्।**\n- कान्तिपुरमा गुणकामदेवले मानव बस्ती बसालेका थिए।\n- कीर्तिपुरमा शिवदेव प्रथमले मानव बस्ती बसालेका थिए।\n- वरदेव र गुणकामदेव अन्य महत्वपूर्ण ऐतिहासिक व्यक्तित्व हुन्।\nनोट: भक्तपुरमा पनि आनन्ददेवले नै मानव बस्ती बसालेका थिए।', 'nepali'),
      (v_set_id, 19, E'गौरा पर्व कुन प्रदेशको महत्वपूर्ण धार्मिक एवं सांस्कृतिक पर्व हो?', E'कर्णाली', E'लुम्बिनी', E'सुदूरपश्चिम', E'मधेश', 'C', E'**गौरा पर्व सुदूरपश्चिम प्रदेशको महत्वपूर्ण धार्मिक एवं सांस्कृतिक पर्व हो।**\n- कर्णाली प्रदेशमा देउडा, भुवा, माघे संक्रान्ति जस्ता पर्वहरू मनाइन्छन्।\n- लुम्बिनी प्रदेशमा बुद्ध जयन्ती, माघी, दशैं जस्ता पर्वहरू मनाइन्छन्।\n- मधेश प्रदेशमा छठ पर्व, जुडशीतल, समाचकेवा जस्ता पर्वहरू मनाइन्छन्।\nनोट: गौरा पर्व विशेषगरी डोटीमा परापूर्वकालदेखि मनाइँदै आएको छ र यसमा शिव, पार्वती तथा गणेशको पूजाअर्चना गरिन्छ।', 'nepali'),
      (v_set_id, 20, E'ग्रन्थकुट शैलीलाई कुन शैलीको आधुनिक शैलीका रुपमा चिनिन्छ?', E'स्तूप शैली', E'प्यागोडा शैली', E'शिखर शैली', E'युरोपेली शैली', 'C', E'**ग्रन्थकुट शैलीलाई शिखर शैलीको आधुनिक शैलीका रुपमा चिनिन्छ।**\n- स्तूप शैली बौद्ध धर्मसँग सम्बन्धित वास्तुकला हो।\n- प्यागोडा शैली नेपालको परम्परागत मन्दिर निर्माण शैली हो।\n- युरोपेली शैली युरोपमा विकसित विभिन्न वास्तुकला शैलीहरूलाई जनाउँछ।\nनोट: रानी पोखरीको बीचमा रहेको बाल गोपालेश्वर मन्दिर ग्रन्थकुट शैलीमा निर्माण भएको छ।', 'nepali'),
      (v_set_id, 21, E'एसिया कप टी-२० क्रिकेट, २०२४ को उपाधि कुन मुलुकले प्राप्त गरेको छ?', E'भारत', E'पाकिस्तान', E'बंगलादेश', E'श्रीलंका', 'A', E'**सन् २०२४ को एसिया कप टी-२० क्रिकेटको उपाधि भारतले प्राप्त गरेको थियो।**\n- पाकिस्तान उक्त प्रतियोगितामा उपविजेता बनेको थियो।\n- बंगलादेश र श्रीलंका पनि एसिया कपमा सहभागी हुने प्रमुख टोलीहरू हुन्।\n- अन्य विकल्पहरू यस सन्दर्भमा सही छैनन्।\nनोट: भारतले पाकिस्तानलाई ५ विकेटले पराजित गर्दै उपाधि जितेको थियो।', 'nepali'),
      (v_set_id, 22, E'फिफा विश्वकप,२०३४ कहाँ आयोजना हुने भएको छ ?', E'पोर्चुगल', E'उरुग्वे', E'साउदी अरेबिया', E'क्यानडा', 'C', E'**सन् २०३४ को फिफा विश्वकप फुटबल प्रतियोगिता साउदी अरेबियामा आयोजना हुने भएको छ।**\n- सन् २०२६ को विश्वकप अमेरिका, मेक्सिको र क्यानडामा आयोजना हुनेछ।\n- सन् २०३० को विश्वकप स्पेन, पोर्चुगल, मोरक्को, अर्जेन्टिना, उरुग्वे र पाराग्वेमा आयोजना हुनेछ।', 'nepali'),
      (v_set_id, 23, E'गुडिरहेको बस एक्कासि रोकिँदा बसका यात्रुहरू अगाडितिर धुतितु न्युटनको चालसम्बन्धी कुन नियमसँग सम्बन्धित छ?', E'पहिलो नियम', E'दोस्रो नियम', E'तेस्रो नियम', E'कुनैसँग राख्दैन', 'A', E'**गुडिरहेको बस एक्कासि रोकिँदा यात्रुहरू अगाडितिर धुतितु न्युटनको पहिलो नियमसँग सम्बन्धित छ।**\n- न्युटनको दोस्रो नियम F=MA सँग सम्बन्धित छ र यसले कुनै पनि वस्तुमा उत्पन्न हुने प्रवेग त्यसमा लगाइएको बलसँग समानुपातिक र वस्तुको पिण्डसँग व्युत्क्रमानुपातिक हुन्छ भनी बताउँछ।\n- न्युटनको तेस्रो नियमले हरेक क्रियामा बराबर तर विपरीत प्रतिक्रिया हुन्छ भनी बताउँछ, जस्तै डुङ्गा खियाउँदा वा बन्दुक चलाउँदा।\nनोट: न्युटनको पहिलो नियमलाई जडत्वको नियम पनि भनिन्छ।', 'nepali'),
      (v_set_id, 24, E'नेपालको शान्ति क्षेत्र प्रस्तावलाई तत्काल रूपमा समर्थन गर्ने दुई मुलुक कुन-कुन हुन्?', E'चीन र भारत', E'बेलायत र चीन', E'चीन र बंगलादेश', E'चीन र पाकिस्तान', 'D', E'नेपाललाई शान्ति क्षेत्र घोषणा गर्ने राजा वीरेन्द्रको प्रस्तावलाई तत्काल समर्थन गर्ने दुई मुलुक **चीन र पाकिस्तान** हुन्।\n- भारतले नेपालको शान्ति क्षेत्र प्रस्तावलाई समर्थन गरेको थिएन।\n- बेलायत र बंगलादेशले तत्काल समर्थन गर्ने मुलुकमा पर्दैनन्, यद्यपि पछि अमेरिका, चीन, फ्रान्स र यूकेसहित ११६ भन्दा बढी देशले समर्थन गरेका थिए।\nनोट: राजा वीरेन्द्रले २०३१ फागुन १३ गते प्रधानमन्त्री लोकेन्द्र बहादुर चन्दका पालामा यो प्रस्ताव राखेका थिए।', 'nepali'),
      (v_set_id, 25, E'हाल सबैभन्दा बढी नाफामा रहेका संस्थान कुन हो?', E'निक्षेप तथा कर्जा लगानी कोष', E'नेपाल आयल निगम', E'नेपाल विद्युत प्राधिकरण', E'नेपाल दूरसञ्चार कम्पनी लि.', 'C', E'हाल **नेपाल विद्युत प्राधिकरण** सबैभन्दा बढी नाफामा रहेको संस्थान हो।\n- सार्वजनिक संस्थानहरूमध्ये नाफाका आधारमा शीर्ष ५ यस प्रकार छन्:\n| स्थान | संस्थान |\n| --- | --- |\n| १ | नेपाल विद्युत प्राधिकरण |\n| २ | नेपाल आयल निगम |\n| ३ | नेपाल दूरसञ्चार कम्पनी लि. |\n| ४ | निक्षेप तथा कर्जा लगानी कोष |\n| ५ | नेपाल नागरिक उड्डयन प्राधिकरण |', 'nepali'),
      (v_set_id, 26, E'दरबार हाइस्कुलको स्थापना कहिले भएको हो?', E'वि.सं. १९१०', E'वि.सं. १९१२', E'वि.सं. १९१४', E'वि.सं. १९१६', 'A', E'दरबार हाइस्कुलको स्थापना **वि.सं. १९१०** मा भएको थियो। जंगबहादुर राणाले यसको स्थापना गरेका थिए।\nनोट: वीरशमशेरले सर्वसाधारणका छोराछोरीले दरबार हाइस्कुलमा पढ्न पाउने व्यवस्था गरेका थिए।', 'nepali'),
      (v_set_id, 27, E'पशुपतिमा महास्नान गर्ने चलन चलाउने राजा को हुन्?', E'यक्ष मल्ल', E'अंशुवर्मा', E'शिवदेव', E'अभय मल्ल', 'D', E'**पशुपतिमा महास्नान गर्ने चलन चलाउने राजा अभय मल्ल हुन्।**\n- यक्ष मल्लले पशुपतिमा भट्ट पुजारी राख्ने चलन चलाएका थिए।\n- अंशुवर्माले पशुपतिलाई राजमान्यता दिएका थिए।\n- शिवदेवले पशुपतिनाथमा सुनको छाना चढाएका थिए।\nनोट: प्रचण्डदेवले पशुपतिनाथको मन्दिर बनाएका थिए भने भास्कर वर्माले पशुपतिनाथलाई स्वर्णमय बनाएका थिए।', 'nepali'),
      (v_set_id, 28, E'वातावरणीय भविष्य सम्बन्धी हेलेन्स्कीको सम्मेलन कहाँ भएको थियो?', E'स्वीडेन', E'फिनल्याण्ड', E'नर्वे', E'बेलायत', 'B', E'**फिनल्याण्ड।**\n- वातावरणीय भविष्य सम्बन्धी हेलेन्स्कीको सम्मेलन सन् १९७९ मा भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०७/३०', 28;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_01.csv  →  आसमान दैनिक GK — २०८२/०८/०१  (16 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/०१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/०१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/०१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको संविधानको कुन धारामा सञ्चारको हक सम्बन्धित व्यवस्था गरेको छ?', E'धारा ३१', E'धारा २७', E'धारा १९', E'धारा २४', 'C', E'**नेपालको संविधानको धारा १९ मा सञ्चारको हक सम्बन्धी व्यवस्था गरिएको छ।**\n- धारा ३१ ले शिक्षा सम्बन्धी हकको व्यवस्था गर्दछ।\n- धारा २७ मा सूचनाको हकको व्यवस्था छ।\n- धारा २४ ले छुवाछुत तथा भेदभाव विरुद्धको हकको सुनिश्चितता गर्दछ।\nनोट: सञ्चारको हक अन्तर्गत प्रत्येक नागरिकलाई सूचना, प्रकाशन तथा प्रसारणको स्वतन्त्रता प्रदान गरिएको छ।', 'nepali'),
      (v_set_id, 2, E'देहायका मध्ये कुन प्राकृतिक उपग्रह होइन?', E'युरोपा', E'क्यालिस्टो', E'फोबोस', E'स्पुतनिक', 'D', E'**स्पुतनिक प्राकृतिक उपग्रह नभई कृत्रिम (मानव निर्मित) उपग्रह हो।**\n- युरोपा, क्यालिस्टो र फोबोस प्राकृतिक उपग्रहहरू हुन्।\n- चन्द्रमा, ग्यानिमेड र ट्राइटन पनि प्राकृतिक उपग्रहका उदाहरण हुन्।\nनोट: स्पुतनिक १ सन् १९५७ मा सोभियत संघद्वारा प्रक्षेपण गरिएको विश्वको पहिलो कृत्रिम उपग्रह थियो।', 'nepali'),
      (v_set_id, 3, E'सोह्रौं योजनाको अन्त्य सम्म नेपालको गरिबीको रेखा मुनि रहेको जनसंख्या (निरपेक्ष गरिबी) कति पुऱ्याउने लक्ष्य रहेको छ?', E'१२ प्रतिशत', E'११ प्रतिशत', E'० प्रतिशत', E'५ प्रतिशत', 'D', E'सोह्रौं योजनाको अन्त्यसम्म नेपालको गरिबीको रेखा मुनि रहेको जनसंख्या (निरपेक्ष गरिबी) **५ प्रतिशत**मा झार्ने लक्ष्य राखिएको छ।\nनोट: सोह्रौं योजनाले आर्थिक वर्ष २०८५/८६ सम्म निरपेक्ष गरिबी १२.० प्रतिशतमा झार्ने लक्ष्य लिएको छ भने आर्थिक वर्ष २९००/०१ सम्म निरपेक्ष गरिबी ० प्रतिशत र बहुआयामिक गरिबी ३ प्रतिशतमा झार्ने दीर्घकालीन लक्ष्य राखेको छ।', 'nepali'),
      (v_set_id, 4, E'बीउ बिजन र कृषि प्रजातिको छनौट र संरक्षण सम्बन्धि व्यवस्था कुन धारामा रहेको छ?', E'धारा ४०', E'धारा ४१', E'धारा ४२', E'धारा ४३', 'C', E'नेपालको संविधानको धारा **४२** मा बीउ बिजन र कृषि प्रजातिको छनौट र संरक्षण सम्बन्धि व्यवस्था रहेको छ। यो सामाजिक न्यायको हक अन्तर्गत पर्दछ, जसले प्रत्येक किसानलाई कृषि कार्यका लागि भूमिमा पहुँच, परम्परागत रूपमा प्रयोग र अवलम्बन गरिएको स्थानीय बीउ बिजन र कृषि प्रजातिको छनौट र संरक्षणको हक सुनिश्चित गर्दछ।', 'nepali'),
      (v_set_id, 5, E'अष्ट्रेलिया कसले पत्ता लगाएका थिए?', E'जोन डेभिस', E'जेम्स कुक', E'तसमान', E'कोर्निलियस ट्रेबल', 'B', E'**जेम्स कुकले सन् १७६८ मा अष्ट्रेलिया पत्ता लगाएका थिए।**\n- जोन डेभिसले सन् १९२९ मा अन्टार्कटिका पत्ता लगाएका थिए।\n- तसमानले सन् १६४२ मा न्युजिल्यान्ड पत्ता लगाएका थिए।\n- कोर्निलियस ट्रेबलले सन् १७२० मा थेम्स नदी पत्ता लगाएका थिए।', 'nepali'),
      (v_set_id, 6, E'आठ हजार मिटर भन्दा अग्ला आठवटा हिमाल मध्ये गण्डकी प्रदेशमा अवस्थित हिमालको संख्या कति रहेको छ?', E'५ वटा', E'४ वटा', E'३ वटा', E'२ वटा', 'C', E'नेपालमा रहेका आठ हजार मिटर भन्दा अग्ला आठवटा हिमालमध्ये गण्डकी प्रदेशमा **३ वटा** हिमाल अवस्थित छन्।\n- गण्डकी प्रदेशमा धवलागिरी, मनास्लु र अन्नपूर्ण हिमाल रहेका छन्।\n- बाँकी पाँचवटा हिमाल (सगरमाथा, कञ्चनजङ्घा, ल्होत्से, मकालु, चोओयु) कोशी प्रदेशमा रहेका छन्।', 'nepali'),
      (v_set_id, 7, E'मिस नेपालको ३१ औं संस्करण, २०२५ उपाधि जित्ने सुन्दरी को हुन्?', E'लुना लुइटेल', E'दीपशिखा नेपाल', E'उरुशा भण्डारी', E'सोनी घले', 'A', E'**मिस नेपालको ३१ औं संस्करण, २०२५ को उपाधि लुना लुइटेलले जितिन्।**\n- दीपशिखा नेपाल मिस नेपाल कस्मोको ताजसहित पहिलो उपविजेता बनिन्।\n- उरुशा भण्डारीले मिस नेपाल इन्टरनेसनलको ताज जितिन्।\n- सोनी घले प्रतियोगितामा मिस नेपाल अर्थ घोषित भइन्।\nनोट: मिस नेपाल युनिभर्स २०२५ को उपाधि सान्या अधिकारीले जितिन्।', 'nepali'),
      (v_set_id, 8, E'काठमाडौंमा सम्पन्न सगरमाथा संवाद, २०२५ मा कति बुँदे घोषणापत्र जारी भएको छ?', E'२१ बुँदे', E'२५ बुँदे', E'२७ बुँदे', E'२९ बुँदे', 'B', E'काठमाडौंमा सम्पन्न सगरमाथा संवाद, २०२५ मा **२५ बुँदे** सगरमाथा कार्य आह्वान जारी भएको छ।\n- नेपाल सरकारले पहिलो पटक आयोजना गरेको यो संवाद वि.स. २०८२ जेठ २-४ मा सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 9, E'विश्वको इतिहासमा पहिलो राजनीतिक क्रान्ति भनेर कुन क्रान्तिलाई चिनिन्छ?', E'औद्योगिक क्रान्ति', E'गौरवमय क्रान्ति', E'फ्रान्सेली क्रान्ति', E'रुसी क्रान्ति', 'B', E'विश्वको इतिहासमा पहिलो राजनीतिक क्रान्ति बेलायतको **गौरवमय क्रान्ति** हो।\n- औद्योगिक क्रान्तिले १८औं शताब्दीमा उत्पादन र प्रविधिमा ठूलो परिवर्तन ल्यायो।\n- फ्रान्सेली क्रान्ति सन् १७८९ मा सुरु भयो र यसले राजतन्त्रको अन्त्य गरी गणतन्त्र स्थापना गर्‍यो।\n- रुसी क्रान्ति सन् १९१७ मा भएको थियो, जसले जार शासनको अन्त्य गरी सोभियत संघको स्थापना गर्‍यो।\nनोट: गौरवमय क्रान्ति सन् १६८८ मा भएको थियो र यसमा रगत नबगेकाले यसलाई ''रक्तविहीन क्रान्ति'' (Glorious Revolution) पनि भनिन्छ।', 'nepali'),
      (v_set_id, 10, E'देहाएका पर्व हरु मध्ये सबैभन्दा पहिला घटेको पर्व कुन हो?', E'३८ सालको पर्व', E'भण्डारखाल पर्व', E'अलौ पर्व', E'कोत पर्व', 'D', E'दिइएका पर्वहरूमध्ये सबैभन्दा पहिले कोत पर्व घटेको थियो।\nयी पर्वहरूको कालक्रम यसप्रकार छ:\n- कोत पर्व: **वि.सं. १९०३ असोज २**\n- भण्डारखाल पर्व: वि.सं. १९०३ कार्तिक १२\n- अलौ पर्व: वि.सं. १९०४\n- ३८ सालको पर्व: वि.सं. १९३८', 'nepali'),
      (v_set_id, 11, E'मुलुकी अपराध संहिता ऐन, २०७४ अनुसार बहुविवाह गर्ने वा गराउने व्यक्तिलाई कति वर्षसम्म कैद सजाय हुन सक्छ?', E'२ वर्षसम्म', E'३ वर्षसम्म', E'४ वर्षसम्म', E'५ वर्षसम्म', 'D', E'मुलुकी अपराध संहिता ऐन, २०७४ अनुसार बहुविवाह गर्ने वा गराउने व्यक्तिलाई **एक वर्षदेखि पाँच वर्षसम्म कैद** र दश हजारदेखि पचास हजार रुपैयाँसम्म जरिवाना हुने व्यवस्था छ।\nनोट: सोही ऐन अनुसार, बीस वर्ष उमेर नपुगी विवाह गर्ने वा गराउने (बालविवाह) लाई तीन वर्षसम्म कैद र तीस हजार रुपैयाँसम्म जरिवाना हुन्छ।', 'nepali'),
      (v_set_id, 12, E'केटि देख्दा बिरामी हुने वैज्ञानिक को हुन्?', E'चार्ल्स डार्बिन', E'अल्फ्रेड नोबेल', E'हेनरी केलिण्डिस', E'स्टेफेन हकिन्स', 'C', E'**केटि देख्दा बिरामी हुने वैज्ञानिक हेनरी केलिण्डिस हुन्।**\n- चार्ल्स डार्बिनले प्राकृतिक छनोटको सिद्धान्त प्रतिपादन गरेका थिए।\n- अल्फ्रेड नोबेलले डाइनामाइटको आविष्कार गरेका थिए र नोबेल पुरस्कारको स्थापना गरेका हुन्।\n- स्टेफेन हकिन्स एक प्रसिद्ध सैद्धान्तिक भौतिकशास्त्री र ब्रह्माण्डविद् थिए।\nनोट: स्कटल्याण्डका नागरिक हेनरी केलिण्डिसले हाइड्रोजन ग्यास र पानीको सूत्र (H2O) पत्ता लगाएका थिए।', 'nepali'),
      (v_set_id, 13, E'यार्सागुम्बाको लागि प्रख्यात नेपाली जिल्ला कुन हो?', E'मनाङ', E'मुगु', E'डोल्पा', E'हुम्ला', 'C', E'**यार्सागुम्बाका लागि नेपालको डोल्पा जिल्ला प्रख्यात छ।**\n- मनाङ जिल्ला अन्नपूर्ण पदयात्रा मार्ग र उच्च हिमाली भूभागका लागि परिचित छ।\n- मुगु जिल्ला नेपालको सबैभन्दा ठूलो ताल रारा तालका लागि प्रसिद्ध छ।\n- हुम्ला जिल्ला नेपालको सबैभन्दा दुर्गम जिल्लाहरू मध्ये एक हो र यसको सिमाना चीनसँग जोडिएको छ।\nनोट: यार्सागुम्बा आधा समय वनस्पति र आधा समय किरा हुने एक बहुमूल्य जडीबुटी हो, जसको सङ्कलन प्रायः जेठ-असार महिनामा गरिन्छ।', 'nepali'),
      (v_set_id, 14, E'नेपालमा जन्म, मृत्यु, विवाह, बसाइँसराइ र सम्बन्ध विच्छेद जस्ता व्यक्तिगत घटना कहिलेदेखि दर्ता गर्न सुरु भएको हो?', E'वि.सं. २०३१', E'वि.सं. २०३२', E'वि.सं. २०३३', E'वि.सं. २०३४', 'D', E'नेपालमा जन्म, मृत्यु, विवाह, बसाइँसराइ र सम्बन्ध विच्छेद जस्ता व्यक्तिगत घटनाहरू दर्ता गर्न **वि.सं. २०३४** देखि सुरु गरिएको हो।\n- यो व्यवस्था २०३४ वैशाख १ गतेबाट लागू भएको थियो।', 'nepali'),
      (v_set_id, 15, E'बिमस्टेकको बडापत्र कहिलेदेखि लागु भएको हो?', E'२०२४ मे २०', E'२०२२ मार्च ३०', E'२०२३ डिसेम्बर २०', E'२०२४ डिसेम्बर ३०', 'A', E'बिमस्टेकको बडापत्र **सन् २०२४ मे २०** देखि लागु भएको हो।\n- सदस्य मुलुकका कार्यकारी प्रमुखहरूले सन् २०२२ मार्च ३० मा बिमस्टेक बडापत्रमा हस्ताक्षर गरेका थिए।\n- बिमस्टेकको बडापत्र २७ पृष्ठ र २६ दफामा रहेको छ।', 'nepali'),
      (v_set_id, 16, E'सोह्रौं योजनाको अन्त्य सम्म नेपालको गरिबीको रेखाभुनी रहेको जनसंख्या (निरपेक्ष गरिबी) कति पुऱ्याउने लक्ष्य रहेको छ?', E'१२ प्रतिशत', E'११ प्रतिशत', E'० प्रतिशत', E'५ प्रतिशत', 'D', E'**सोह्रौं योजनाको अन्त्यसम्म निरपेक्ष गरिबीको रेखाभुनीमा रहेको जनसंख्यालाई **५ प्रतिशतमा झार्ने लक्ष्य राखिएको छ।\n- आर्थिक वर्ष २०८५/८६ सम्म निरपेक्ष गरिबी १२.० प्रतिशतमा झार्ने लक्ष्य छ।\n- आर्थिक वर्ष २९००/०१ सम्म निरपेक्ष गरिबी ० प्रतिशतमा झार्ने लक्ष्य छ।\n- आर्थिक वर्ष २९००/०१ सम्म बहुआयामिक गरिबी ३ प्रतिशतमा झार्ने लक्ष्य छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/०१', 16;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_07.csv  →  आसमान दैनिक GK — २०८२/०८/०७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/०७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/०७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/०७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'बिहारको मुख्यमन्त्री २०२४ मा पुनः निर्वाचित हुन सफल राजनीतिज्ञ को हुन् ?', E'निरोज मानन्धर', E'नितिश कुमार', E'नविन श्रेष्ठ', E'निशान्त अधिकारी', 'B', E'सन् २०२४ नोभेम्बर १५ मा बिहारको मुख्यमन्त्रीमा **नितिश कुमार** पुनः निर्वाचित भएका छन्। उनी लगातार २० वर्षदेखि बिहारको मुख्यमन्त्रीको पदमा रहेका छन्।', 'nepali'),
      (v_set_id, 2, E'दोस्रो सिजनको एभरेष्ट महिला भलिबल लिग, २०८२ को उपाधि कुन टिमले जितेको छ ?', E'कर्णाली याक्सिज', E'ललितपुर क्विन्स', E'बागमती प्राइमक्स', E'गण्डकी मैग्नस', 'A', E'२०८२ कात्तिक २९ गते भएको फाइनल खेलमा ललितपुर क्विन्सलाई पराजित गर्दै **कर्णाली याक्सिजले** लगातार दोस्रो पटक एभरेष्ट महिला भलिबल लिगको उपाधि जितेको हो। यो जितसँगै कर्णाली दोस्रो पटक च्याम्पियन बनेको छ।', 'nepali'),
      (v_set_id, 3, E'सौन्दर्य प्रतियोगिता मिसेस नेपाल वर्ल्ड २०२४ को उपाधि कसले जितेकी छन् ?', E'सृष्टी शर्मा', E'रुबीना केसी', E'रक्षा पन्त', E'अन्जली कार्की', 'C', E'विवाहित महिलाहरूको सौन्दर्य प्रतियोगिता मिसेस नेपाल वर्ल्ड २०२४ को उपाधि बुटवलकी **रक्षा पन्तले** जितेकी छिन्। उनले वि.सं. २०८२ कात्तिक २९ गते राजधानीमा सम्पन्न प्रतिस्पर्धामा २४ प्रतिस्पर्धीलाई पछि पारेकी थिइन्।\nनोट: सोही प्रतियोगितामा सञ्जु भट्टले मिसेस नेपाल इन्टरनेसनल र दिपिका तामाङले एमएस नेपाल इन्टरनेसनलको उपाधि जितेका थिए।', 'nepali'),
      (v_set_id, 4, E'सन् २०२४ मा नेपालले कार्बन उत्सर्जन घटाए वापि विश्व बैंकबाट कति रकम प्राप्त गरेको छ ?', E'३२ करोड', E'३४ करोड', E'३६ करोड', E'३८ करोड', 'A', E'सन् २०२४ मा नेपालले वन संरक्षण मार्फत कार्बन उत्सर्जन घटाए वापि विश्व बैंकबाट **३२ करोड** रुपैयाँ प्राप्त गरेको छ।', 'nepali'),
      (v_set_id, 5, E'गभर्नर प्रा.डा. विश्वनाथ पौडेलले नेपाल राष्ट्र बैंकको आर्थिक वर्ष २०७९-८० को वार्षिक प्रतिवेदन पेस कहिले पेस गर्नुभएको छ ?', E'२०७९ कार्तिक २७', E'२०७९ कार्तिक २८', E'२०७९ कार्तिक २९', E'२०७९ कार्तिक ३०', 'D', E'नेपाल राष्ट्र बैंकका गभर्नर प्रा.डा. विश्वनाथ पौडेलले आर्थिक वर्ष २०७९-८० को वार्षिक प्रतिवेदन **२०७९ कार्तिक ३० गते** पेस गर्नुभएको थियो। उहाँले उक्त प्रतिवेदन अर्थमन्त्री श्री रामेश्वरप्रसाद खनालसमक्ष पेस गर्नुभएको थियो।', 'nepali'),
      (v_set_id, 6, E'कर दिवस २०७९ को अवसरमा आ.व २०७०/७१ मा धेरै कर तिरेर व्यक्तिगततर्फ सबैभन्दा बढी आयकर तिर्ने सम्मानित भएका व्यक्ति को हुन् ?', E'वीरबहादुर सिंह', E'राजबहादुर शाह', E'कुमारबहादुर मल्ल', E'प्रतापबहादुर राणा', 'B', E'कर दिवस २०७९ को अवसरमा आर्थिक वर्ष २०७०/७१ मा व्यक्तिगततर्फ सबैभन्दा बढी आयकर तिरेर सम्मानित हुने व्यक्ति **राजबहादुर शाह** हुन्।\nनोट: कर दिवस २०७९ को अवसरमा आ.व २०७०/७१ मा धेरै कर तिरेर सम्मानित भएका व्यक्ति, संस्था तथा निकायहरू यस प्रकार छन्:\n- १. व्यक्तिगततर्फ सबैभन्दा बढी आयकर तिर्ने — राजबहादुर शाह\n- २. सबैभन्दा बढी आयकर तिर्ने निकायमा — नेपाल दूरसञ्चार प्राधिकरण\n- ३. एक्लोटी फर्म तर्फ — थर्ड आई इन्टरनेसनल\n- ४. वस्तुगत आयकरतर्फ — डाबर नेपाल\n- ५. सूचना-प्रविधितर्फ — भेरिक्स नेपाल प्रा.लि.\n- ६. निर्यात कारोबारतर्फ — डाबर नेपाल प्रा.लि.\n- ७. कृषि/पशुपजन्य — पोषक ब्रिडर\n- ८. बैंक तथा वित्तीय संस्थातर्फ — नेपाल इन्भेष्टमेन्ट बैंक\n- ९. स्वास्थ्य/शिक्षातर्फ — नोबेल मेडिकल कलेज।', 'nepali'),
      (v_set_id, 7, E'कफी दिवस २०८२ को नारा कुन विकल्प सहि रहेको छ ?', E'कफी खेती गरौँ, स्वरोजगार बनौँ', E'स्थानीय कफी, स्थानीय समृद्धि', E'कफी उत्पादन, समृद्धि सुनिश्चित', E'कफी खेती अघि, आत्मनिर्भरता पछि', 'A', E'**कफी खेती गरौँ, स्वरोजगार बनौँ** भन्ने नाराका साथ २१औं राष्ट्रिय कफी दिवस २०८२ मंसिर १ गते मनाइएको थियो।', 'nepali'),
      (v_set_id, 8, E'हालसालै मानवता विरुद्धका अपराधमा कुन सार्क मुलुकको पूर्व राज्य प्रमुखलाई मृत्युदण्ड फैसला सुनाइएको छ ?', E'नेपाल', E'बंगलादेश', E'भारत', E'भुटान', 'B', E'**बंगलादेश**मा हालसालै मानवता विरुद्धका अपराधमा पूर्व राज्य प्रमुखलाई मृत्युदण्डको फैसला सुनाइएको थियो। बंगलादेशको विशेष अदालतले सन् २०२५ नोभेम्बर १७ मा शेख हसिनालाई विद्यार्थी विद्रोह (जुलाई-अगस्ट २०२३) मा भएको हिंसामा संलग्नता, हत्या-हत्या प्रयास, षड्यन्त्र लगायतका ५ मुद्दामा दोषी ठहर गर्दै मृत्युदण्डको फैसला सुनाएको थियो। यसै कसुरमा बंगलादेशी प्रधानमन्त्री शेख हसिना र गृह मन्त्री Asaduzzaman Khan ले पनि मृत्युदण्ड पाएका छन्।', 'nepali'),
      (v_set_id, 9, E'NPL दोस्रो संस्करणमा जम्मा कतिवटा खेलहरु हुनेछन् ?', E'३२ खेल', E'२४ खेल', E'२६ खेल', E'३८ खेल', 'A', E'**NPL को दोस्रो संस्करणमा जम्मा ३२ वटा खेलहरू हुनेछन्।**', 'nepali'),
      (v_set_id, 10, E'पहिलो दृष्टिविहीन महिला टी-२० विश्वकप, २०२५ प्रतियोगिताको आयोजक राष्ट्र कुन हो ?', E'भारत र बंगलादेश', E'भारत र माल्दिभ्स', E'भारत र श्रीलंका', E'भारत र नेपाल', 'C', E'पहिलो दृष्टिविहीन महिला टी-२० विश्वकप, २०२५ को आयोजना **भारत र श्रीलंकाले** संयुक्त रूपमा गरेका थिए।\nनोट: यो प्रतियोगिता सन् २०२५ नोभेम्बर ११ देखि २३ सम्म सञ्चालन भएको थियो।', 'nepali'),
      (v_set_id, 11, E'२२ औं अन्तर्राष्ट्रिय कर सम्मेलन, २०२५ कहाँ सम्पन्न भएको छ ?', E'भारत', E'माल्दिभ्स', E'श्रीलंका', E'नेपाल', 'D', E'२२ औं अन्तर्राष्ट्रिय कर सम्मेलन, २०२५ **नेपालको काठमाडौंमा** सम्पन्न भएको थियो। यो सम्मेलन २०८२ मङ्सिर २ देखि ५ (सन् २०२५ नोभेम्बर १८-२१) सम्म आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 12, E'प्रत्येक वर्ष विश्व मधुमेह दिवस कुन तारिखमा मनाइन्छ ?', E'नोभेम्बर १४', E'नोभेम्बर १२', E'नोभेम्बर १०', E'नोभेम्बर ८', 'A', E'प्रत्येक वर्ष **नोभेम्बर १४** तारिखमा विश्व मधुमेह दिवस मनाइन्छ।\nनोट: सन् २०२५ को नारा ''जीवनको हरेक चरणमा मधुमेह'' (Diabetes across life stages) रहेको थियो।', 'nepali'),
      (v_set_id, 13, E'नेपाल प्रिमियर लिग दोस्रो संस्करणमा पहिलो अर्ध सतक बनाउने खेलाडी को हुन् ?', E'लाहिरु मिलान्था', E'कुशल भुर्तेल', E'मिलिन्द कुमार', E'आसिफ शेख', 'D', E'नेपाल प्रिमियर लिग (NPL) को दोस्रो संस्करणमा पहिलो अर्धशतक बनाउने खेलाडी जनकपुर बोल्ट्सका **आसिफ शेख** हुन्।\n- लाहिरु मिलान्थाले प्रतियोगिताको पहिलो चौका हानेका थिए।\n- मिलिन्द कुमारले प्रतियोगिताको पहिलो विकेट लिएका थिए।\n- कुशल भुर्तेल पनि एक नेपाली राष्ट्रिय क्रिकेट खेलाडी हुन्।\nनोट: आसिफ शेखले नै प्रतियोगिताको पहिलो छक्का पनि प्रहार गरेका थिए।', 'nepali'),
      (v_set_id, 14, E'बुकर पुरस्कार, २०२५ कुन पुस्तकलाई प्रदान गरिएको छ ?', E'Orbital', E'Answer', E'Flesh', E'Roman', 'C', E'सन् २०२५ को बुकर पुरस्कार डेभिड स्जालेद्वारा लिखित पुस्तक **''Flesh''** लाई प्रदान गरिएको छ। यो पुरस्कार Booker Prize Foundation द्वारा संयुक्त अधिराज्य र आयरल्याण्डमा प्रकाशित उत्कृष्ट अंग्रेजी उपन्यासलाई प्रदान गरिन्छ।\nनोट: सन् २०२४ को बुकर पुरस्कार सामन्था हार्वेको पुस्तक ''Orbital'' ले जितेको थियो।', 'nepali'),
      (v_set_id, 15, E'नेपाल प्रिमियर लिग दोस्रो संस्करणमा प्रयोग गरिएको रोबोटिक कुकुरको नाम के दिइएको छ ?', E'चखे', E'चम्पा', E'चम्बक', E'च्याचे', 'A', E'नेपाल प्रिमियर लिग (NPL) को दोस्रो संस्करणमा प्रयोग गरिएको रोबोटिक कुकुरको नाम **चखे** राखिएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/०७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_08.csv  →  आसमान दैनिक GK — २०८२/०८/०८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/०८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/०८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/०८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'बसुन्धराश्री पुरस्कार, २०८२ कसलाई प्रदान गरिएको छ?', E'कवि मञ्जुल', E'तुलसी दिवस', E'तोया गुरुङ', E'ध्रुवचन्द्र गौतम', 'B', E'**बसुन्धराश्री पुरस्कार, २०८२ साहित्यकार तुलसी दिवसलाई प्रदान गरिने घोषणा भएको छ।**\n- कवि मञ्जुलले वि.सं. २०७९ को जगदम्बा-श्री पुरस्कार प्राप्त गरेका थिए।\n- तोया गुरुङलाई मानश्री पुरस्कार, २०८२ प्रदान गरिने भएको छ।\n- ध्रुवचन्द्र गौतमलाई राष्ट्रिय लेखन पुरस्कार, २०८२ प्रदान गरिने भएको छ।', 'nepali'),
      (v_set_id, 2, E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या कति पुगेको छ?', E'४४ वटा', E'४३ वटा', E'४५ वटा', E'४६ वटा', 'C', E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या **४५ वटा** पुगेको छ। वि.सं. २०८१ पुस ११ देखि ४५औं भाषाको रूपमा बाम्बुले राई भाषालाई समावेश गरिएको हो।\nनोट: यसअघि ४४औं भाषाको रूपमा रानाथारु भाषालाई वि.सं. २०८१ असोज २२ मा समावेश गरिएको थियो।', 'nepali'),
      (v_set_id, 3, E'ज्ञान मर्दछ हाँसेर रोई विज्ञान मर्दछ यो भनाइ कसको हो?', E'बालकृष्ण सम', E'वि.पि. कोइराला', E'लेखनाथ पौड्याल', E'लक्ष्मीप्रसाद देवकोटा', 'A', E'**‘ज्ञान मर्दछ हाँसेर, रोई विज्ञान मर्दछ’ भन्ने प्रसिद्ध भनाइ नाट्यसम्राट बालकृष्ण समको हो।**\n- वि.पि. कोइरालाको एक प्रसिद्ध भनाइ ‘मानिस ठूलो दिलले हुन्छ, जातले हुँदैन’ हो।\n- लेखनाथ पौड्याललाई ‘कविशिरोमणि’ उपाधिले चिनिन्छ।\n- लक्ष्मीप्रसाद देवकोटाको भनाइ हो, ‘छोटो किस्सा एउटा सानो भ्याल हो, जहाँबाट एउटा सानो संसारमा चियाइन्छ।’', 'nepali'),
      (v_set_id, 4, E'संयुक्त राष्ट्रसंघको सदस्यता नेपाल सँगै प्राप्त गर्ने सार्क मुलुक कुन हो?', E'भुटान', E'बंगलादेश', E'श्रीलंका', E'पाकिस्तान', 'C', E'**नेपाल र श्रीलंकाले सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता सँगै प्राप्त गरेका थिए।**\n- भुटानले सन् १९७१ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गरेको थियो।\n- बंगलादेशले सन् १९७४ मा सदस्यता प्राप्त गरेको थियो।\n- पाकिस्तानले सन् १९४७ मा सदस्यता प्राप्त गरेको थियो।', 'nepali'),
      (v_set_id, 5, E'राष्ट्रिय जलवायु सम्मेलनसँग सम्बन्धित १० बुँदे गुफा घोषणा पत्र जारी कुन जिल्लामा भएको हो?', E'सोलुखुम्बु', E'दोलखा', E'सिन्धुपाल्चोक', E'संखुवासभा', 'C', E'राष्ट्रिय जलवायु सम्मेलनसँग सम्बन्धित १० बुँदे गुफा घोषणा पत्र **सिन्धुपाल्चोक** जिल्लामा जारी भएको थियो। पहिलो राष्ट्रिय जलवायु सम्मेलन २०७५ पुस १७ (२०१९ जनवरी १) मा सिन्धुपाल्चोकको गुफाडाँडामा सम्पन्न भएको थियो, जसको उद्घाटन तत्कालीन राष्ट्रपति विद्यादेवी भण्डारीले गर्नुभएको थियो।', 'nepali'),
      (v_set_id, 6, E'विश्व स्वास्थ्य सङ्गठन (World Health Organization) को प्रधान कार्यालय कहाँ रहेको छ?', E'रोम', E'जेनेभा', E'न्युयोर्क', E'लण्डन', 'B', E'विश्व स्वास्थ्य सङ्गठन (WHO) को प्रधान कार्यालय **जेनेभा, स्वीट्जरल्याण्डमा** रहेको छ।\n- रोममा खाद्य तथा कृषि सङ्गठन (FAO) को प्रधान कार्यालय छ।\n- न्युयोर्कमा संयुक्त राष्ट्र संघ (UN) को प्रधान कार्यालय अवस्थित छ।\n- लण्डनमा अन्तर्राष्ट्रिय सामुद्रिक सङ्गठन (IMO) को प्रधान कार्यालय रहेको छ।\nनोट: विश्व स्वास्थ्य सङ्गठनको स्थापना ७ अप्रिल १९४८ मा भएको थियो।', 'nepali'),
      (v_set_id, 7, E'साझा पुरस्कार सर्वप्रथम कसलाई प्रदान गरिएको थियो?', E'बालकृष्ण सम', E'सत्यमोहन जोशी', E'माधवप्रसाद घिमिरे', E'भूपि शेरचन', 'D', E'साझा पुरस्कार सर्वप्रथम **भूपि शेरचनलाई** ''घुम्ने मेचमाथि अन्धो मान्छे'' कृतिका लागि प्रदान गरिएको थियो।\n- बालकृष्ण समलाई ''नेपाली साहित्यका शेक्सपियर'' भनेर चिनिन्छ।\n- सत्यमोहन जोशीले ''हाम्रो लोक संस्कृति'' कृतिका लागि वि.सं. २०१३ मा सर्वप्रथम मदन पुरस्कार प्राप्त गर्नुभएको थियो।\n- माधवप्रसाद घिमिरे नेपालका राष्ट्रकवि हुन्।\nनोट: साझा पुरस्कारको स्थापना वि.सं. २०२६ मा भएको थियो।', 'nepali'),
      (v_set_id, 8, E'थेमाङवा कुन जातिमा प्रचलित श्राद्ध हो?', E'राई', E'लिम्बु', E'मगर', E'शेर्पा', 'A', E'थेमाङवा **राई** जातिमा प्रचलित श्राद्ध हो, जुन वर्षमा एकपटक गरिन्छ।\n- लिम्बु जातिमा धान नाच र तोङ्बा जस्ता सांस्कृतिक प्रचलनहरू छन्।\n- मगर जातिमा कौरा नाच र भुमे पूजा जस्ता सांस्कृतिक परम्पराहरू प्रचलित छन्।\n- शेर्पा समुदायले ल्होसार र मणि रिम्दु जस्ता पर्वहरू मनाउँछन्।', 'nepali'),
      (v_set_id, 9, E'नेपाल र किरिबाटी बिच दौत्य सम्बन्ध कहिले कायम भयो ?', E'२०२४ जुलाई १७', E'२०२४ जुलाई १८', E'२०२४ जुन १७', E'२०२४ जुन १८', 'A', E'नेपाल र किरिबाटी बिच **२०२४ जुलाई १७** मा दौत्य सम्बन्ध कायम भएको थियो।\nनोट: किरिबाटी नेपालसँग दौत्य सम्बन्ध कायम गर्ने १८३ औं मुलुक हो।', 'nepali'),
      (v_set_id, 10, E'भारतको वर्तमान राष्ट्रपति द्रौपदी मुर्मु कति औं राष्ट्रपति हुन् ?', E'१३ औं', E'१४ औं', E'१५ औं', E'१२ औं', 'C', E'भारतकी वर्तमान राष्ट्रपति द्रौपदी मुर्मु **१५ औं** राष्ट्रपति हुन्। उनी भारतको पहिलो आदिवासी महिला राष्ट्रपति पनि हुन्, जो सन् २०२२ जुलाई २१ मा निर्वाचित भई जुलाई २५ मा सपथ ग्रहण गरेकी थिइन्।', 'nepali'),
      (v_set_id, 11, E'नेपालमा डिजिटल नागरिक वडापत्रको सुरुवात कुन जिल्लाबाट भएको हो ?', E'रुकुम पश्चिम', E'ललितपुर', E'डडेलधुरा', E'सुर्खेत', 'A', E'नेपालमा डिजिटल नागरिक वडापत्रको सुरुवात **रुकुम पश्चिम** जिल्लाको मुसिकोटबाट भएको हो।\nनोट: यसको सुरुवात वि.सं. २०७३ असोज १६ गते भएको थियो।', 'nepali'),
      (v_set_id, 12, E'प्रजातन्त्रको पुनर्बहालीपश्चात सबैभन्दा लामो समय प्रधानमन्त्रीको कुर्सीमा रहन सफल व्यक्ति को हुन्?', E'गिरिजा प्र. कोइराला', E'शेर बहादुर देउवा', E'नगेन्द्रप्रसाद रिजाल', E'कृष्णप्रसाद भट्टराई', 'A', E'**प्रजातन्त्रको पुनर्बहालीपश्चात सबैभन्दा लामो समय प्रधानमन्त्रीको कुर्सीमा रहन सफल व्यक्ति गिरिजाप्रसाद कोइराला हुन्।**\n- शेरबहादुर देउवालाई नेपालको इतिहासमा सबैभन्दा बढी विवादास्पद प्रधानमन्त्री मध्ये एक मानिन्छ।\n- नगेन्द्रप्रसाद रिजालले नेपालमा प्राथमिक शिक्षालाई निःशुल्क गराउने कार्यको शुभारम्भ गरेका थिए।\n- कृष्णप्रसाद भट्टराईले ''पञ्चायत थर्ड ग्रेडको व्यवस्था हो, म यसलाई मान्दैमान्दिन'' भन्ने अभिव्यक्ति दिएका थिए।', 'nepali'),
      (v_set_id, 13, E'बाराक ओबामा कति औं अमेरिकी राष्ट्रपति हुने व्यक्ति को हुन्?', E'४२ औं', E'४३ औं', E'४४ औं', E'४५ औं', 'C', E'बाराक ओबामा अमेरिकाका **४४ औं** राष्ट्रपति हुन्।\nनोट: उनी अमेरिकाको इतिहासमा राष्ट्रपति पदमा पुग्ने पहिलो अश्वेत व्यक्ति हुन्।', 'nepali'),
      (v_set_id, 14, E'कोसी बाँध (Koshi Barrage) मा जम्मा कतिवटा पानी नियन्त्रण गर्ने ढोका रहेका छन्?', E'५३ वटा', E'५४ वटा', E'५५ वटा', E'५६ वटा', 'D', E'कोसी बाँधमा जम्मा **५६ वटा** पानी नियन्त्रण गर्ने ढोका रहेका छन्। सन् १९५४ मा नेपाल र भारतबीच भएको सम्झौता अनुसार निर्माण भएको यो बाँध सन् १९६२ मा सम्पन्न भएको थियो।\nनोट: यो बाँधको कुल लम्बाइ ३७७० फिट छ र यसलाई भारतले १९९ वर्षका लागि लिजमा लिएको छ।', 'nepali'),
      (v_set_id, 15, E'महाकाली नदीको उद्गम स्थल कुन हिमाल हो ?', E'अपि हिमाल', E'सैपाल हिमाल', E'धौलागिरी हिमाल', E'मुकुट हिमाल', 'A', E'महाकाली नदीको उद्गम स्थल **अपि हिमाल** हो।\n- सैपाल हिमालबाट सेती नदीको उद्गम हुन्छ।\n- धौलागिरी हिमाल सानो भेरी नदीको उद्गम स्थल हो।\n- मुकुट हिमाल ठूलो भेरी नदीको उद्गम स्थल हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/०८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_09.csv  →  आसमान दैनिक GK — २०८२/०८/०९  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/०९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/०९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/०९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'संयुक्त राष्ट्रसंघ (UNO) अध्ययन गर्दै गर्दा देहाएका मध्ये कुन मुलुक Big seven country अन्तर्गत नरहेको पाउनु भयो?', E'रुस', E'जापान', E'फ्रान्स', E'चीन', 'A', E'संयुक्त राष्ट्रसंघको बजेटमा सबैभन्दा बढी योगदान गर्ने ''बिग सेभेन'' मुलुकहरूमा **रुस पर्दैन**।\n- जापानले UN बजेटमा ८.०३३% योगदान गर्दछ।\n- फ्रान्सले UN बजेटमा ४.३१% योगदान गर्दछ।\n- चीन UN बजेटमा १५.२५% योगदान गर्ने दोस्रो ठूलो मुलुक हो।\nनोट: ''बिग सेभेन'' मा अमेरिका, चीन, जापान, जर्मनी, बेलायत, फ्रान्स र इटाली पर्दछन्।', 'nepali'),
      (v_set_id, 2, E'विश्वको सर्वोच्च शिखर सगरमाथा नेपालका ८ हजार मिटर भन्दा अग्ला हिमाल मध्ये पश्चिमबाट कति औं स्थानमा पर्दछ?', E'चौथो', E'पाँचौ', E'तेस्रो', E'छैठौं', 'B', E'नेपालमा रहेका ८,००० मिटरभन्दा अग्ला हिमालहरूलाई पश्चिमबाट पूर्वतर्फ गणना गर्दा सगरमाथा **पाँचौँ स्थानमा** पर्दछ।\nनोट: पूर्वबाट गणना गर्दा भने सगरमाथा चौथो स्थानमा आउँछ।', 'nepali'),
      (v_set_id, 3, E'विश्वको लामो नदी नाइलको दुई प्रमुख सहायक नदीहरु पहिचान गरि देहाएका उक्त नदीहरुको कुन स्थानमा दोभान हुन्छ पहिचान गर्नुहोस्?', E'सुडानको खार्तुम', E'इजिप्टको कायरो', E'तान्जानियाको डोडोमा', E'केन्याको नैरोबी', 'A', E'विश्वको सबैभन्दा लामो नदी नाइलका दुई प्रमुख सहायक नदीहरू, सेतो नाइल (White Nile) र निलो नाइल (Blue Nile), **सुडानको राजधानी खार्तुममा** भेट हुन्छन्।\n- इजिप्टको कायरो नाइल नदीको किनारमा अवस्थित एक प्रमुख शहर हो।\n- तान्जानियाको डोडोमा तान्जानियाको राजधानी हो।\n- केन्याको नैरोबी केन्याको राजधानी हो।', 'nepali'),
      (v_set_id, 4, E'२०७२ सालको भुकम्पमा भत्किएको धरहरालाई कहिले देखि खुला गरिएको छ ?', E'२०८१ असोज १', E'२०८१ असोज २', E'२०८१ असोज ३', E'२०८१ असोज ४', 'C', E'२०७२ सालको भूकम्पमा भत्किएको धरहरालाई **वि.सं. २०८१ असोज ३** देखि सर्वसाधारणका लागि खुला गरिएको थियो।\nनोट: पुनर्निर्मित नयाँ धरहराको उद्घाटन भने तत्कालीन प्रधानमन्त्री केपी शर्मा ओलीले वि.सं. २०७८ वैशाख ११ गते गर्नुभएको थियो।', 'nepali'),
      (v_set_id, 5, E'सर्वप्रथम पृथ्वी केन्द्रित सिद्धान्त (Geo Centric Concept) प्रस्तुत गर्ने वैज्ञानिक को हुन्?', E'गिहार्दिनो ब्रुनो', E'क्लाउडियस टोलेमी', E'निकोलस कोपर्निकस', E'जोहानस केप्लर', 'B', E'**युनानी खगोलशास्त्री क्लाउडियस टोलेमीले सर्वप्रथम पृथ्वी-केन्द्रित सिद्धान्त (Geo-centric Concept) प्रस्तुत गरेका थिए।**\n- गिहार्दिनो ब्रुनो एक इटालेली दार्शनिक थिए जसले कोपर्निकसको सूर्य-केन्द्रित सिद्धान्तको समर्थन गरेका थिए।\n- निकोलस कोपर्निकसले सूर्य-केन्द्रित सिद्धान्त (Helio-centric model) प्रतिपादन गरेका थिए, जसलाई सौर्यमण्डलका पिता पनि भनिन्छ।\n- जोहानस केप्लरले ग्रहहरूको गतिबारे वैज्ञानिक धारणा प्रस्तुत गरेका थिए।', 'nepali'),
      (v_set_id, 6, E'नेपालको इतिहासमा राणा प्रधानमन्त्री मध्ये दोस्रो पुस्ताका अन्तिम राणा प्रधानमन्त्री को हुन्?', E'जुद्ध समसेर', E'रणोद्दिप सिंह', E'पद्म समसेर', E'मोहन समसेर', 'A', E'**नेपालको इतिहासमा राणा प्रधानमन्त्रीहरूमध्ये दोस्रो पुस्ताका अन्तिम प्रधानमन्त्री जुद्ध समसेर हुन्।**\n- रणोद्दिप सिंह जंगबहादुरका भाइ र प्रथम पुस्ताका राणा प्रधानमन्त्री थिए।\n- पद्म समसेर र मोहन समसेर तेस्रो पुस्ताका राणा प्रधानमन्त्रीहरू थिए, जो जुद्ध समसेरपछि क्रमशः प्रधानमन्त्री बने।', 'nepali'),
      (v_set_id, 7, E'देहायका मध्ये कुन मुलुक अल्पविकसित मुलुकको सूचीमा पर्दैन?', E'भ्याटिकन सिटी', E'सान मारिनो', E'मोनाको', E'लेसेथो', 'C', E'**मोनाको एक विकसित देश हो, यो अल्पविकसित मुलुकको सूचीमा पर्दैन।**\n- भ्याटिकन सिटी र सान मारिनो पनि विकसित युरोपेली राष्ट्रहरू हुन्।\n- लेसेथो भने अफ्रिका महादेशमा अवस्थित एक अल्पविकसित राष्ट्र हो।\nनोट: संयुक्त राष्ट्र संघले विभिन्न सामाजिक-आर्थिक सूचकका आधारमा मुलुकहरूलाई अल्पविकसितको सूचीमा राख्ने गर्दछ।', 'nepali'),
      (v_set_id, 8, E'कुनै पनि जीवले आफ्नै जीवनकालका आफ्नै संघर्षबाट प्राप्त गरेको गुणलाई के भनिन्छ?', E'आर्जित गुण', E'बंशाणुगत गुण', E'परिवृति गुण', E'उत्परिवर्तन गुण', 'A', E'**कुनै पनि जीवले आफ्नै जीवनकालमा आफ्नै संघर्षबाट प्राप्त गरेको गुणलाई आर्जित गुण (Acquired Trait) भनिन्छ।**\n- बंशाणुगत गुण भनेको माता-पिताबाट छोराछोरीमा सर्न सक्ने लक्षण हो।\n- परिवृति (Variation) भन्नाले व्यक्ति वा सन्ततिपिच्छे देखा पर्ने फरकपन वा आ-आफ्नोपनलाई बुझाउँछ।\n- उत्परिवर्तन (Mutation) भनेको पुर्खामा नभएको गुण नयाँ पुस्तामा अकस्मात देखा पर्नु हो।', 'nepali'),
      (v_set_id, 9, E'.................. नागरिकलाई नेपालको संविधान अनुसार निःशुल्क शिक्षा पाउने हक हुनेछ।', E'दलित र आर्थिक रुपले विपन्न', E'अपांगता र दलित', E'जनजाति र अपांगता', E'अपांगता र आर्थिक रुपले विपन्न', 'D', E'नेपालको संविधानको धारा ३१ (शिक्षा सम्बन्धी हक) अनुसार **अपांगता भएका र आर्थिक रुपले विपन्न** नागरिकलाई कानून बमोजिम निःशुल्क उच्च शिक्षा पाउने हक हुनेछ।\nनोट: प्रत्येक नागरिकलाई राज्यबाट आधारभूत तहसम्मको शिक्षा अनिवार्य र निःशुल्क तथा माध्यमिक तहसम्मको शिक्षा निःशुल्क पाउने हकको व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 10, E'नेपालको संविधान अनुसार जम्मा संघीय संसद सदस्य कतिजना रहेको छन्?', E'३३४ जना', E'२७५ जना', E'६०१ जना', E'१६५ जना', 'A', E'नेपालको संविधान अनुसार संघीय संसदमा जम्मा **३३४ जना** सदस्य रहने व्यवस्था छ।\nनोट: संघीय संसद अन्तर्गत २७५ सदस्यीय प्रतिनिधि सभा र ५९ सदस्यीय राष्ट्रिय सभा गरी दुई सदन रहेका छन्।', 'nepali'),
      (v_set_id, 11, E'आर्थिक सर्वेक्षण २०८०/८१ अनुसार नेपालको कुल संरक्षित क्षेत्रले मुलुकको कुल भू-भागको लगभग कति प्रतिशत भुभाग ओगटेको छ?', E'२३.४० प्रतिशत', E'२२.४० प्रतिशत', E'२३.६० प्रतिशत', E'२२.६० प्रतिशत', 'A', E'आर्थिक सर्वेक्षण २०८०/८१ अनुसार नेपालको कुल संरक्षित क्षेत्रले मुलुकको कुल भू-भागको लगभग **२३.४० प्रतिशत** भूभाग ओगटेको छ।\nनोट: नेपालमा हाल १२ राष्ट्रिय निकुञ्ज, १ वन्यजन्तु आरक्ष, ६ संरक्षण क्षेत्र र १ शिकार आरक्ष सहित कुल २० वटा संरक्षित क्षेत्रहरू छन्।', 'nepali'),
      (v_set_id, 12, E'विश्व भूगोलमा कर्कट रेखाले काटेको नदी देहायका मध्ये कुन हो ?', E'कंगो नदी', E'लिम्पोपो नदी', E'माही नदी', E'नाइजर नदी', 'C', E'**भारतको माही नदीलाई कर्कट रेखाले काटेको छ।**\n- कंगो नदीलाई भूमध्य रेखाले काटेको छ।\n- लिम्पोपो नदीलाई मकर रेखाले काटेको छ।\n- नाइजर नदी पश्चिम अफ्रिकाको प्रमुख नदी हो, जसलाई कुनै पनि प्रमुख अक्षांश रेखाले काट्दैन।', 'nepali'),
      (v_set_id, 13, E'हालसालै चन्द्रमाको दक्षिणी ध्रुवमा रहेको एउटा क्रेटर नेपाली व्यक्तित्वको नाम बाट नामाकरण गरिएको छ। भन्नुहोस् उहाँको नाम के हो?', E'पासाङ ल्हामु शेर्पा', E'पृथ्वीनारायण शाह', E'महाविर पुन', E'सन्दुक रुईत', 'A', E'चन्द्रमाको दक्षिणी ध्रुवमा रहेको एउटा क्रेटरको नाम सगरमाथा आरोहण गर्ने पहिलो नेपाली महिला **पासाङ ल्हामु शेर्पा**को सम्मानमा ''ल्हामु क्रेटर'' राखिएको छ।\n- पृथ्वीनारायण शाहले आधुनिक नेपालको एकीकरण गरेका थिए।\n- महाविर पुन राष्ट्रिय आविष्कार केन्द्रका संस्थापक हुन्।\n- सन्दुक रुईत तिलगंगा आँखा अस्पतालका संस्थापक र विश्वप्रसिद्ध आँखा विशेषज्ञ हुन्।\nनोट: यो क्रेटर चन्द्रमाको दक्षिणी ध्रुवमा -८६° अक्षांशमा अवस्थित छ।', 'nepali'),
      (v_set_id, 14, E'हिन्द महासागरीय सम्मेलन, २०२४ कहाँ सम्पन्न भएको छ?', E'माडागास्कर', E'भारत', E'बंगलादेश', E'अष्ट्रेलिया', 'D', E'सातौं हिन्द महासागरीय सम्मेलन, २०२४ **अष्ट्रेलियाको पर्थमा** सम्पन्न भएको थियो।\n- छैटौं हिन्द महासागरीय सम्मेलन सन् २०२३ मा बंगलादेशको ढाकामा सम्पन्न भएको थियो।\nनोट: २०२४ को सम्मेलनमा नेपालको तर्फबाट परराष्ट्रमन्त्री नारायणप्रकाश साउदले सहभागिता जनाएका थिए।', 'nepali'),
      (v_set_id, 15, E'नेपालको संविधानको दोस्रो संशोधन कहिले भयो ?', E'२०७६ साउन ४', E'२०७७ साउन ४', E'२०७७ असार ४', E'२०७६ असार ४', 'C', E'नेपालको संविधानको दोस्रो संशोधन **वि.सं. २०७७ असार ४** गते भएको थियो। यो संशोधन नेपालको निशान छाप (अनुसूची-३) मा लिम्पियाधुरा, लिपुलेक र कालापानी समेटिएको नयाँ नक्सा समावेश गर्नका लागि गरिएको थियो।\nनोट: नेपालको संविधानमा पहिलो संशोधन वि.सं. २०७२ फागुन १६ गते भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/०९', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_11.csv  →  आसमान दैनिक GK — २०८२/०८/११  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/११'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/११';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/११', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'२०८२ सालमा मनाइएको सामाजिक सुरक्षा दिवस कति औं हो ?', E'सातौं', E'आठौं', E'नवौं', E'दशौं', 'B', E'२०८२ सालमा **आठौं** सामाजिक सुरक्षा दिवस मनाइएको थियो।\nनोट: यस वर्षको नारा ''सामाजिक सुरक्षा: सर्वव्यापी स्वास्थ्य सेवाको पहुँच, पेन्सनयोग्य समाज र उत्पादकत्व अभिवृद्धि सहित नागरिकको जीवन रक्षा'' रहेको थियो।', 'nepali'),
      (v_set_id, 2, E'भोकमरी सूचकांक, २०२४ अनुसार नेपाल कति औं स्थानमा रहेको छ ?', E'९२ औं', E'७६ औं', E'७२ औं', E'९० औं', 'C', E'भोकमरी सूचकांक, २०२४ अनुसार नेपाल **७२ औं** स्थानमा रहेको छ।\n- विश्व खुसी सूचकांक, २०२४ मा नेपाल ९२ औं स्थानमा छ।\n- विश्व शान्ति सूचकांक, २०२४ मा नेपाल ७६ औं स्थानमा रहेको छ।\n- प्रेस स्वतन्त्रता सूचकांक, २०२४ मा नेपाल ९० औं स्थानमा रहेको छ।', 'nepali'),
      (v_set_id, 3, E'नवनियुक्त मुख्यसचिव सुमनराज अर्याल कति औं नेपाल सरकारको मुख्यसचिव हुन् ?', E'२७ औं', E'२८ औं', E'२९ औं', E'३० औं', 'C', E'नवनियुक्त मुख्यसचिव सुमनराज अर्याल नेपाल सरकारको **२९ औं** मुख्यसचिव हुन्।\nनोट: उहाँलाई वि.सं. २०८२ मङ्सिर ८ गते नियुक्त गरिएको थियो र नेपालको प्रथम मुख्यसचिव चन्द्र बहादुर थापा हुन्।', 'nepali'),
      (v_set_id, 4, E'दृष्टिविहीन महिला टि-२० विश्वकप, २०२४ को उपविजेता मुलुक कुन बनेको छ ?', E'भारत', E'श्रीलंका', E'नेपाल', E'पाकिस्तान', 'C', E'**दृष्टिविहीन महिला टि-२० विश्वकप, २०२४ को उपविजेता नेपाल बनेको छ।**\n- भारत उक्त प्रतियोगिताको विजेता बनेको थियो, जसले फाइनलमा नेपाललाई ७ विकेटले पराजित गर्यो।\n- श्रीलंका भारतसँगै प्रतियोगिताको सह-आयोजक राष्ट्र थियो।\n- पाकिस्तान यस प्रतियोगिताको विजेता वा उपविजेता होइन।\nनोट: यो दृष्टिविहीन महिला टि-२० विश्वकपको पहिलो संस्करण थियो।', 'nepali'),
      (v_set_id, 5, E'संयुक्त राष्ट्र संघको नयाँ प्रतिवेदन, २०२५ अनुसार विश्वको सबैभन्दा ठूलो सहर कुन बन्न सफल भएको छ ?', E'नयाँ दिल्ली', E'जकार्ता', E'ढाका', E'टोकियो', 'B', E'संयुक्त राष्ट्र संघको ''वर्ल्ड अर्बनाइजेसन प्रोस्पेक्ट्स २०२५'' प्रतिवेदन अनुसार इन्डोनेसियाको राजधानी **जकार्ता** विश्वको सबैभन्दा ठूलो सहर बनेको छ।\n- नयाँ दिल्ली, भारत, ३ करोड २ लाख जनसंख्यासहित चौथो स्थानमा छ।\n- ढाका, बंगलादेश, ३ करोड ६६ लाख जनसंख्यासहित दोस्रो स्थानमा छ।\n- टोकियो, जापान, तेस्रो स्थानमा छ।\nनोट: जकार्ताको जनसंख्या ४ करोड १९ लाख रहेको छ।', 'nepali'),
      (v_set_id, 6, E'What is the 2025 theme for World Children''s Day?', E'For Every Child, Every Right', E'My Day, My Rights', E'Children First, Always', E'Every Child, Every Voice', 'B', E'सन् २०२५ को विश्व बाल दिवसको नारा **"My Day, My Rights"** (मेरो दिन, मेरो अधिकार) रहेको छ।\n- यो दिवस हरेक वर्ष नोभेम्बर २० मा मनाइन्छ।', 'nepali'),
      (v_set_id, 7, E'अन्तर्राष्ट्रिय आणविक ऊर्जा एजेन्सीको आयोजनामा एसिया तथा प्रशान्त क्षेत्रका लागि राष्ट्रिय सम्पर्क अधिकारीहरूको बैठक २०२५ डिसेम्बर मा कहाँ हुँदै छ ?', E'नयाँ दिल्ली', E'बेइजिङ', E'ढाका', E'टोकियो', 'B', E'अन्तर्राष्ट्रिय आणविक ऊर्जा एजेन्सी (IAEA) को आयोजनामा एसिया तथा प्रशान्त क्षेत्रका लागि राष्ट्रिय सम्पर्क अधिकारीहरूको बैठक चीनको **बेइजिङमा** सम्पन्न भएको थियो।\nनोट: यो बैठक २०२५ डिसेम्बर १ देखि ५ (वि.सं. २०८२ मंसिर १५-१९) सम्म चलेको थियो।', 'nepali'),
      (v_set_id, 8, E'संघीय मामिला मन्त्रालयको इतिहासमै पहिलोपटक महिला सचिव बन्न सफल नवनियुक्त सचिवको हुनुहुन्छ ?', E'निर्मला शर्मा', E'सविता भण्डारी', E'मनदेवी श्रेष्ठ', E'चन्द्रकला पौडेल', 'D', E'२०८२ मंसिर ८ गतेको मन्त्रिपरिषद् बैठकले **चन्द्रकला पौडेल**लाई संघीय मामिला तथा सामान्य प्रशासन मन्त्रालयको सचिवमा नियुक्त गरेको हो। उहाँ यस मन्त्रालयको इतिहासमा पहिलो महिला सचिव हुनुहुन्छ।', 'nepali'),
      (v_set_id, 9, E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२४ मा शतक हान्ने पहिलो खेलाडी को हुन ?', E'मार्टिन गुप्टिल', E'एन्ड्युज गौस', E'जेम्स निशान', E'मार्क वाट', 'D', E'नेपाल प्रिमियर लिग (NPL) को दोस्रो संस्करणमा पहिलो शतक प्रहार गर्ने खेलाडी कर्णाली याक्सका **मार्क वाट** हुन्। उनले लुम्बिनी विरुद्ध अविजित रहँदै ४४ बलमा ११४ रन बनाएका थिए।\nनोट: NPL को पहिलो संस्करणमा एकमात्र शतक पोखराका एन्ड्युज गौसले प्रहार गरेका थिए।', 'nepali'),
      (v_set_id, 10, E'उद्योग दिवस हरेक वर्ष कुन दिन मनाइन्छ ?', E'मंसिर ७', E'मंसिर ८', E'मंसिर ९', E'मंसिर १०', 'C', E'हरेक वर्ष **मंसिर ९** गते उद्योग दिवस मनाइन्छ। वि.सं. १९९२ मंसिर ९ गते उद्योग परिषद्को स्थापना भएको दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।\nनोट: २०८२ को उद्योग दिवसको नारा ''औद्योगिक वातावरण सुधार: दिगो अर्थतन्त्रको आधार'' रहेको थियो।', 'nepali'),
      (v_set_id, 11, E'प्रत्येक वर्ष कति दिन लैङ्गिक हिंसा विरुद्धको अभियान सञ्चालन हुने गर्दछ ?', E'७ दिने', E'१६ दिने', E'२३ दिने', E'३० दिने', 'B', E'प्रत्येक वर्ष लैङ्गिक हिंसा विरुद्ध **१६ दिने** अभियान सञ्चालन गरिन्छ। यो अभियान हरेक वर्ष नोभेम्बर २५ देखि डिसेम्बर १० सम्म चल्दछ।\nनोट: २०८२ को राष्ट्रिय नारा ''प्रविधिको सहि प्रयोग गरौं : लैङ्गिक हिंसा अन्त्य गरौं'' रहेको थियो भने अन्तर्राष्ट्रिय नारा ''Unite to end digital violence against all women and girls'' थियो।', 'nepali'),
      (v_set_id, 12, E'कोप-३० मा नेपालको तर्फबाट कसले सहभागि जनाएका छन् ?', E'रामचन्द्र पौडेल', E'मदनप्रसाद परिवार', E'जगदीश खरेल', E'महाबिर पुन', 'B', E'नेपालको तर्फबाट कृषि तथा पशुपन्छी विकासमन्त्री डा. **मदनप्रसाद परिवार**ले कोप-३० मा १ सदस्यीय टोलीको नेतृत्व गर्दै सहभागिता जनाएका थिए।', 'nepali'),
      (v_set_id, 13, E'विश्व शौचालय दिवस कहिले मनाइन्छ ?', E'नोभेम्बर १९', E'नोभेम्बर २०', E'नोभेम्बर २१', E'नोभेम्बर २२', 'A', E'विश्व शौचालय दिवस हरेक वर्ष **नोभेम्बर १९** मा मनाइन्छ।\nनोट: सन् २०२४ को लागि यसको नारा ''सेनितेसन इन अ चेन्जिङ वर्ल्ड'' (Sanitation in a changing world) रहेको छ।', 'nepali'),
      (v_set_id, 14, E'९६ औं ओस्कार अवार्ड, २०२६ का लागि नेपालबाट सिफारिस भएको फिल्म कुन हो ?', E'डिग्री माइला', E'एन्जिला', E'शाम्बाला', E'पूर्ण बहादुरको सारंगी', 'B', E'९६ औं ओस्कार अवार्ड, २०२६ का लागि नेपालबाट **एन्जिला** फिल्म सिफारिस भएको थियो। यो मिलन चाम्स निर्देशित चलचित्र राष्ट्रिय महिला फुटबल खेलाडी एन्जिला तुम्बापो सुब्बाको वास्तविक जीवनकथामा आधारित छ।\nनोट: ९७ औं ओस्कार अवार्डका लागि ''शाम्बाला'' सिफारिस भएको छ।', 'nepali'),
      (v_set_id, 15, E'मिस युनिभर्स २०२४ को उपाधि प्राप्त गर्न सफल सुन्दरी को हुन् ?', E'प्रविनर सिंह', E'स्टेफेनी अवसली', E'फतिमा बोस', E'आतिसा मानलो', 'C', E'**फतिमा बोस** (मेक्सिको) ले मिस युनिभर्स २०२४ को उपाधि प्राप्त गरेकी थिइन्।\n- प्रविनर सिंह (थाइल्यान्ड) फर्स्ट रनरअप भएकी थिइन्।\n- स्टेफेनी अवसली (भेनेजुएला) सेकेन्ड रनरअप भएकी थिइन्।\nनोट: मिस युनिभर्स २०२४ को ७४ औं संस्करण थाइल्यान्डमा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 16, E'हालसम्ममा सबैभन्दा थोरै पटक सार्क शिखर सम्मेलन आयोजना गर्ने सार्क मुलुक कुन हो?', E'भुटान', E'श्रीलंका', E'माल्दिभ्स', E'अफगानिस्तान', 'D', E'**अफगानिस्तानले** हालसम्म सार्क शिखर सम्मेलन आयोजना गरेको छैन।\n- भुटानले हालसम्म एकपटक मात्र १६औं सार्क शिखर सम्मेलन (२०१० अप्रिल २६-२९) आयोजना गरेको छ।', 'nepali'),
      (v_set_id, 17, E'दिगो विकासको लक्ष्य कति वर्षिय विश्व विकासको मार्गचित्र हो?', E'१५ वर्षिय', E'२० वर्षिय', E'२५ वर्षिय', E'३० वर्षिय', 'A', E'**१५ वर्षिय**।\n- दिगो विकासका लक्ष्यहरू २०१५ सेप्टेम्बर २५ मा पारित भई २०१६ जनवरी १ देखि २०३० डिसेम्बर ३१ सम्मका लागि १५ वर्षिय विश्वव्यापी मार्गचित्र हुन्।', 'nepali'),
      (v_set_id, 18, E'राता रक्तकोषको आयु करिब कति दिनको हुन्छ?', E'१०० दिन', E'१२० दिन', E'१४० दिन', E'१६० दिन', 'B', E'**१२० दिन**।\n- राता रक्तकोषहरू हड्डीको भित्री भाग ''मासिमा'' (Bone Marrow) उत्पन्न हुन्छन् र यिनीहरूको आयु करिब १२० दिनको हुन्छ।', 'nepali'),
      (v_set_id, 19, E'किरातहरूमा प्रचलित गोरुको सिङबाट बनाईएको बाजालाई के भनिन्छ?', E'पुङ', E'होप्जा', E'फासमुक', E'डम्फु', 'A', E'**किरात समुदायमा गोरुको सिङबाट बनाइने बाजालाई पुङ भनिन्छ।**\n- डम्फु काठमा छाला मोडेर बनाइने तामाङ जातिमा प्रचलित बाजा हो।', 'nepali'),
      (v_set_id, 20, E'अपरेटिङ सिस्टमको उदाहरण कुन हो?', E'किबोर्ड', E'Windows', E'प्रिन्टर', E'HTML', 'B', E'**Windows एक अपरेटिङ सिस्टम हो।**\n- किबोर्ड कम्प्युटरको इनपुट उपकरण हो।\n- प्रिन्टर कम्प्युटरको आउटपुट उपकरण हो।\n- HTML वेबपेजहरू बनाउन प्रयोग गरिने मार्कअप भाषा हो।', 'nepali'),
      (v_set_id, 21, E'माधवप्रसाद घिमिरेद्वारा लिखित कृति देहायको कुन हो?', E'नवमञ्जरी', E'कुहिरो र घाम', E'परिवर्तन', E'अन्तर्मुखी', 'A', E'**माधवप्रसाद घिमिरेद्वारा लिखित कृति नवमञ्जरी हो।**\n- कुहिरो र घाम सिद्धिचरण श्रेष्ठको कृति हो।\n- परिवर्तन भूमेन्द्रमान शेरचनको कृति हो।\n- अन्तर्मुखी विष्णुकुमारी वाइबाको कृति हो।', 'nepali'),
      (v_set_id, 22, E'विश्व शान्ति सूचकांक - २०२४ अनुसार नेपाल कति औं स्थानमा रहेको छ?', E'७४ औं स्थान', E'७५ औं स्थान', E'७६ औं स्थान', E'७७ औं स्थान', 'C', E'सन् २०२४ को विश्व शान्ति सूचकांक अनुसार नेपाल **७६ औं स्थानमा** रहेको छ। यस सूचकांकमा आइसल्याण्ड पहिलो स्थानमा र रूस अन्तिम स्थानमा छन्।\nनोट: दक्षिण एसियामा भुटान सबैभन्दा शान्तिपूर्ण मुलुक हो।', 'nepali'),
      (v_set_id, 23, E'फिफा विश्वकप, २०२६ को बल सार्वजनिक कहिले भएको हो?', E'२०२५ अक्टोबर २', E'२०२५ अक्टोबर ४', E'२०२५ अक्टोबर ६', E'२०२५ अक्टोबर ८', 'A', E'फिफा विश्वकप, २०२६ को बल **२०२५ अक्टोबर २ मा** सार्वजनिक भएको थियो। यस बलको नाम ''ट्रियाण्डा'' हो, जसले तीन आयोजक राष्ट्र (अमेरिका, क्यानडा र मेक्सिको) लाई जनाउँछ।\nनोट: फिफा विश्वकप, २०२६ को लोगो सन् २०२३ मे १५ मा सार्वजनिक भएको थियो।', 'nepali'),
      (v_set_id, 24, E'पाँच पटक प्रधानमन्त्री बनेका प्रधानमन्त्री देहायका को होइनन्?', E'गिरिजाप्रसाद कोइराला', E'शेर बहादुर देउवा', E'लोकेन्द्र बहादुर चन्द', E'सूर्यबहादुर थापा', 'C', E'**लोकेन्द्र बहादुर चन्द पाँच पटक प्रधानमन्त्री बनेका प्रधानमन्त्री होइनन्।**\n- शेर बहादुर देउवा, गिरिजाप्रसाद कोइराला र सूर्यबहादुर थापा पाँच पटक प्रधानमन्त्री बनेका थिए।\n- लोकेन्द्र बहादुर चन्द र केपी ओली चार पटक प्रधानमन्त्री बनेका थिए।\n- कीर्तिनिधि विष्ट र पुष्प कमल दाहाल तीन पटक प्रधानमन्त्री बनेका थिए।', 'nepali'),
      (v_set_id, 25, E'हाल छिमेकी मुलुक भारतका राज्यको संख्या कति रहेको छ?', E'२७ राज्य', E'२८ राज्य', E'२९ राज्य', E'३० राज्य', 'B', E'भारतमा हाल राज्यको संख्या **२८** रहेको छ।\n- सन् २०१४ जुन २ मा तेलंगना राज्य भारतको २९औं राज्यको रूपमा घोषित भएको थियो। पछि, जम्मू कश्मीर राज्यलाई जम्मू र कश्मीर र लद्दाख गरी दुई केन्द्र शासित प्रदेशमा रूपान्तरण गरिएपछि राज्यको संख्या २८ भएको हो।', 'nepali'),
      (v_set_id, 26, E'इन्द्रावती नदी र सुनकोसी नदीको दोभान स्थल कुन विकल्प सहि छ?', E'तुम्लिङटार', E'बराहक्षेत्र', E'बेनिघाट', E'दोलालघाट', 'D', E'**इन्द्रावती नदी र सुनकोसी नदीको दोभान स्थल दोलालघाट हो।**\n- तुम्लिङटार अरुण नदी र सभाखोलाको दोभान स्थल हो।\n- बराहक्षेत्र कोका नदी र कोशी नदीको दोभान स्थल हो।\nनोट: दोलालघाट काभ्रे जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 27, E'जनसंख्या धेरै भएका तीनदला गाउँपालिकाको क्रम कुन सहि छ?', E'बैजनाथ, राप्ती सोनारी, खजुरा', E'राप्ती सोनारी, बैजनाथ, खजुरा', E'बैजनाथ, राप्ती सोनारी, मायादेवी', E'राप्ती सोनारी, बैजनाथ, मायादेवी', 'A', E'जनसंख्या धेरै भएका गाउँपालिकाहरूको सही क्रम **बैजनाथ, राप्ती सोनारी, खजुरा** हो।\n- १. बैजनाथ (बाँके)\n- २. राप्ती सोनारी (बाँके)\n- ३. खजुरा (बाँके)\n- ४. मायादेवी (रुपन्देही)\n- ५. गैडहवा (रुपन्देही)', 'nepali'),
      (v_set_id, 28, E'उचाइको हिसाबले भारतको सबैभन्दा अग्लो झरना कुन हो?', E'जोग', E'नोह्कालिकाइ', E'कुन्चिकल', E'दूधसागर', 'C', E'**कुन्चिकल झरना** उचाइको हिसाबले भारतको सबैभन्दा अग्लो झरना हो।\n- यो झरना कर्नाटकको शिमोगा जिल्लाको वाराही नदीले बनाएको हो र यसको उचाइ लगभग ४५५ मिटर छ।\n- नोह्कालिकाइ झरना भारतको गहिरो झरना हो।', 'nepali'),
      (v_set_id, 29, E'एक प्रकाश वर्ष भन्नाले कति दूरीलाई बुझाउँछ?', E'९.५ लाख कि.मी.', E'९.५ खर्ब कि.मी.', E'३ लाख कि.मी.', E'३० हजार कि.मी.', 'B', E'**९.५ खर्ब कि.मी.**\n- प्रकाश वर्ष भनेको प्रकाशले एक वर्षमा पार गर्ने कुल दूरी हो।', 'nepali'),
      (v_set_id, 30, E'हाल अस्तित्वमा रहेका सार्वजनिक संस्था कतिवटा छन्?', E'४५ वटा', E'४४ वटा', E'४२ वटा', E'४६ वटा', 'A', E'नेपालमा हाल अस्तित्वमा रहेका सार्वजनिक संस्थाको संख्या **४५ वटा** छ। यीमध्ये २८ वटा नाफामा र १२ वटा घाटामा सञ्चालित छन्।\nनोट: २ वटा संस्थानको विवरण प्राप्त भएको छैन।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/११', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_13.csv  →  आसमान दैनिक GK — २०८२/०८/१३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/१३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/१३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/१३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'चिल्लो पदार्थमा ४ भिटामिनहरू घुलन सक्छन्, देहायका भिटामिनका आधारमा उपयुक्त विकल्प छनोट गर्नुहोस्?', E'A, D, E, K', E'A, C, E, K', E'B, C, E, K', E'B, D, E, K', 'A', E'**भिटामिन A, D, E र K** चिल्लो पदार्थमा घुलनशील भिटामिनहरू हुन्।\nनोट: भिटामिन B र C पानीमा घुलनशील भिटामिनहरू हुन्।', 'nepali'),
      (v_set_id, 2, E'नेपालको साहित्य जगत्मा "श्रृंगारिक कवि" को उपनामले कुन साहित्यकारलाई चिनिन्छ?', E'माधवप्रसाद घिमिरे', E'मोतिराम भट्ट', E'सोमनाथ सिग्देल', E'बालकृष्ण सम', 'B', E'**नेपालको साहित्य जगत्मा मोतिराम भट्टलाई "श्रृंगारिक कवि" को उपनामले चिनिन्छ।**\n- माधवप्रसाद घिमिरेलाई राष्ट्रकवि भनिन्छ।\n- सोमनाथ सिग्देललाई विदत शिरोमणीको उपनामले चिनिन्छ।\n- बालकृष्ण समलाई नाट्य सम्राटको उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 3, E'धर्तीको पहिलो तिर्थको उपनामले नेपालको कुन धार्मिक स्थललाई चिनिन्छ?', E'पशुपति', E'स्वयम्भूनाथ', E'पाथिभरा', E'बराह क्षेत्र', 'D', E'**नेपालको बराह क्षेत्रलाई धर्तीको पहिलो तिर्थको उपनामले चिनिन्छ।**\n- पशुपतिनाथ काठमाडौंमा अवस्थित हिन्दुहरूको एक प्रमुख धार्मिक स्थल हो।\n- स्वयम्भूनाथ काठमाडौंमा रहेको एक प्राचीन बौद्ध स्तूपा हो।\n- पाथिभरा मन्दिर ताप्लेजुङ जिल्लामा अवस्थित एक प्रसिद्ध शक्तिपीठ हो।\nनोट: बराह क्षेत्र सुनसरी जिल्लामा कोशी र कोका नदीको संगम स्थलमा पर्दछ, जहाँ विष्णुको बराह अवतारको पूजा गरिन्छ।', 'nepali'),
      (v_set_id, 4, E'नेपालको अन्तिम राजा ज्ञानेन्द्रवीर विक्रम शाहको आमाको नाम के हो?', E'त्रिपुरा राज्य लक्ष्मी', E'राजराज्य लक्ष्मी', E'चन्द्रराज्य लक्ष्मी', E'इन्द्रराज्य लक्ष्मी', 'D', E'**नेपालका अन्तिम राजा ज्ञानेन्द्रवीर विक्रम शाहको आमाको नाम इन्द्रराज्य लक्ष्मी शाह हो।**\n- त्रिपुरा राज्य लक्ष्मी शाह राजा पृथ्वीवीर विक्रम शाहकी रानी थिइन्।\n- राजराज्य लक्ष्मी देवी शाह राजा रणबहादुर शाहकी रानी थिइन्।\n- चन्द्रराज्य लक्ष्मी शाह राजा त्रिभुवनकी रानी थिइन्।', 'nepali'),
      (v_set_id, 5, E'द्वितीय विश्वयुद्ध पछाडि कुन-कुन राष्ट्र शक्तिशाली बने?', E'फ्रान्स र बेलायत', E'अमेरिका र रुस', E'अमेरिका र बेलायत', E'अमेरिका र जर्मनी', 'B', E'**द्वितीय विश्वयुद्धपछि अमेरिका र रुस विश्वका शक्तिशाली राष्ट्रका रूपमा उदाएका थिए।**\n- द्वितीय विश्वयुद्धअघि बेलायत र फ्रान्स प्रमुख शक्तिशाली राष्ट्र थिए।\n- जर्मनी र जापान युद्धमा पराजित भई कमजोर बनेका थिए।\nनोट: शीतयुद्धको समयमा अमेरिका र रुसबीच विश्वव्यापी प्रभावका लागि प्रतिस्पर्धा चलेको थियो।', 'nepali'),
      (v_set_id, 6, E'पहाडबाट पाँच वटा जिल्ला हिमाली क्षेत्रमा स्तरन्नोति पछिको पहाडको नयाँ क्षेत्रफल प्रतिशत कति हुन आउँछ ?', E'२२.५ प्रतिशत', E'२६.५ प्रतिशत', E'२७.२ प्रतिशत', E'२८.५ प्रतिशत', 'C', E'पाँच वटा जिल्लालाई पहाडबाट हिमाली क्षेत्रमा स्तरन्नोति गरेपछि पहाडी क्षेत्रको नयाँ क्षेत्रफल **२७.२ प्रतिशत** हुन आउँछ।\nनोट: यस परिवर्तनपछि हिमाली क्षेत्रको क्षेत्रफल २४.२ प्रतिशत र तराई क्षेत्रको क्षेत्रफल १७ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 7, E'What is the area directly above the earthquake focus called?', E'Seismic center', E'Crust', E'Epicenter', E'Fault line', 'C', E'भूकम्पको केन्द्रबिन्दु (फोकस) को सिधा माथिको पृथ्वीको सतहमा रहेको बिन्दुलाई **इपिसेन्टर (Epicenter)** भनिन्छ।\nनोट: पृथ्वीको भित्री भागमा भूकम्पको कम्पन उत्पत्ति हुने केन्द्रलाई हाइपोसेन्टर वा फोकस पनि भनिन्छ।', 'nepali'),
      (v_set_id, 8, E'भौगोलिक रूपमा कान्छो महादेश कुन हो?', E'एशिया', E'अफ्रिका', E'युरोप', E'उत्तर अमेरिका', 'D', E'**भौगोलिक रूपमा उत्तर अमेरिका महादेशलाई कान्छो महादेश मानिन्छ।**\n- एशिया जनसंख्या र भूगोलको आधारमा सबैभन्दा ठूलो महादेश हो।\n- अफ्रिकालाई मानव जातिको उद्गमस्थल र ''अन्ध महादेश'' पनि भनिन्छ।\n- युरोप क्षेत्रफलका हिसाबले छैटौं ठूलो महादेश हो।', 'nepali'),
      (v_set_id, 9, E'राज्यका ४ वटा निर्देशक सिद्धान्त अनुसार देहायको कुन पर्दैन?', E'राजनीतिक उद्देश्य', E'आर्थिक उद्देश्य', E'वातावरण उद्देश्य', E'अन्तर्राष्ट्रिय सम्बन्ध', 'C', E'**नेपालको संविधानको धारा ५० मा उल्लेखित राज्यका निर्देशक सिद्धान्तहरूमा ''वातावरण उद्देश्य'' पर्दैन।**\n- संविधानको धारा ५० मा राजनीतिक उद्देश्य, सामाजिक र सांस्कृतिक उद्देश्य, आर्थिक उद्देश्य र अन्तर्राष्ट्रिय सम्बन्ध गरी चारवटा निर्देशक सिद्धान्तहरू उल्लेख छन्।\nनोट: यी सिद्धान्तहरू राज्यका नीति निर्माण र कार्यान्वयनका लागि मार्गदर्शक हुन्छन्।', 'nepali'),
      (v_set_id, 10, E'ग्लोबल आईसीटी लिडरसिप फोरम, २०२५ कुन मुलुकमा आयोजना गरिएको छ?', E'द. कोरिया', E'अमेरिका', E'जापान', E'पाकिस्तान', 'A', E'ग्लोबल आईसीटी लिडरसिप फोरम, २०२५ **दक्षिण कोरियाको सिओलमा** आयोजना गरिएको थियो।\nनोट: यो फोरम २०२५ नोभेम्बर १२ मा सञ्चालन भएको ११औं संस्करण थियो।', 'nepali'),
      (v_set_id, 11, E'भारतले हालसालै पाकिस्तान माथि अपरेशन सिन्दुर हमला सुरु कहिले गरेको थियो ?', E'२०२५ मे ७', E'२०२५ मे ८', E'२०२५ मे ९', E'२०२५ मे १०', 'A', E'भारतले **२०२५ मे ७** मा पाकिस्तानमाथि अपरेशन सिन्दुर हमला सुरु गरेको थियो। यो हमला मध्यरातमा पाकिस्तानका विभिन्न शहरमा मिसाइल आक्रमण गरी ३१ पाकिस्तानी नागरिकको मृत्यु भएको थियो।\nनोट: यसको जवाफमा पाकिस्तानले पनि भारतका विभिन्न शहरमा मिसाइल हमला गरेको थियो।', 'nepali'),
      (v_set_id, 12, E'नेपालको राष्ट्रिय चिन्ह (निशानछाप) कहिले निर्धारण गरियो ?', E'२०१ ९ पौष ६', E'२०६३ पौष १५', E'२०७७ जेष्ठ २१', E'२०६४ साउन १८', 'B', E'**नेपालको राष्ट्रिय चिन्ह (निशानछाप) २०६३ पौष १५ गते निर्धारण गरिएको थियो।**\n- २०१ ९ पौष ६ गते नेपालको राष्ट्रिय झण्डा घोषणा गरिएको थियो।\n- २०७७ जेष्ठ २१ गते निशान छाप संशोधन गरी चुच्चे नक्सा राखिएको थियो।\n- २०६४ श्रावण १८ गते नेपालको राष्ट्रिय गान ''सयौं थुँगा'' घोषणा गरिएको थियो।', 'nepali'),
      (v_set_id, 13, E'युरोपेली संघको सर्वोच्च अङ्ग कुन हो ?', E'युरोपेली परिषद', E'युरोपेली आयोग', E'युरोपेली संसद', E'राज्य प्रमुखको बैठक', 'A', E'**युरोपेली संघको सर्वोच्च अङ्ग युरोपेली परिषद हो।**\n- युरोपेली आयोग युरोपेली संघको कार्यकारी अङ्ग हो।\n- युरोपेली संसद युरोपेली संघको प्रत्यक्ष निर्वाचित विधायी अङ्ग हो।\n- राज्य प्रमुखको बैठक युरोपेली परिषदको एक स्वरूप हो, जहाँ सदस्य राष्ट्रका राष्ट्र प्रमुख वा सरकार प्रमुखहरू सहभागी हुन्छन्।', 'nepali'),
      (v_set_id, 14, E'नेपालमा प्रजातन्त्र स्थापना पछि नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो मुलुक कुन हो?', E'बेलायत', E'फ्रान्स', E'रुस', E'चीन', 'D', E'**नेपालमा प्रजातन्त्र स्थापना पछि नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो मुलुक चीन हो।**\n- बेलायत, अमेरिका, भारत र फ्रान्स वि.सं. २००४ साल पूर्व नै नेपालसँग दौत्य सम्बन्ध भएका प्रथम चार राष्ट्रहरू हुन्।', 'nepali'),
      (v_set_id, 15, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा राउटेको जनसंख्या कति रहेको छ?', E'४५० बढी', E'५५० बढी', E'६५० बढी', E'७५० बढी', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा राउटेको जनसंख्या **५५६ जना** रहेको छ।\n- यो संख्या ''५५० बढी'' को श्रेणीमा पर्दछ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/१३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_14.csv  →  आसमान दैनिक GK — २०८२/०८/१४  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/१४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/१४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/१४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'जैविक विविधता संरक्षणका लागि स्थापना गरिएको राष्ट्रिय निकुञ्ज कुन हो?', E'बर्दिया राष्ट्रिय निकुञ्ज', E'कोशी टप्पु वन्यजन्तु आरक्ष', E'शे-फोक्सुण्डो राष्ट्रिय निकुञ्ज', E'खप्तड राष्ट्रिय निकुञ्ज', 'C', E'**शे-फोक्सुण्डो राष्ट्रिय निकुञ्ज जैविक विविधता संरक्षणका लागि स्थापना गरिएको हो।**\n- खप्तड राष्ट्रिय निकुञ्ज योगिहरूको आश्रमका लागि प्रख्यात छ।\n- बर्दिया राष्ट्रिय निकुञ्ज कृष्णसारका लागि प्रख्यात छ।\n- कोशी टप्पु वन्यजन्तु आरक्ष अर्नाका लागि प्रख्यात छ।\nनोट: शे-फोक्सुण्डो राष्ट्रिय निकुञ्जमा नेपालको सबैभन्दा गहिरो ताल (फोक्सुण्डो ताल) रहेको छ।', 'nepali'),
      (v_set_id, 2, E'संयुक्त राष्ट्रसंघको महासभामा अध्यक्ष रहने व्यवस्था कहिले देखि सुरु भएको हो?', E'सन् १९४५', E'सन् १९४६', E'सन् १९४७', E'सन् १९४८', 'B', E'संयुक्त राष्ट्रसंघको महासभामा अध्यक्ष रहने व्यवस्था **सन् १९४६** देखि सुरु भएको हो।\nनोट: महासभाको पहिलो अध्यक्ष बेल्जियमका पाउन हेनरी स्प्याक हुन्, उनी सन् १९४६ मा निर्वाचित भएका थिए।', 'nepali'),
      (v_set_id, 3, E'प्राकृतिक चयनद्वारा विकासको सिद्धान्तको वैज्ञानिक संग सम्बन्धित रहेको छ?', E'चार्ल्स डार्विन', E'आर्किमिडिज', E'ग्यालिलियो ग्यालिलि', E'अल्बर्ट आइन्स्टाइन', 'A', E'**प्राकृतिक चयनद्वारा विकासको सिद्धान्त चार्ल्स डार्विनसँग सम्बन्धित छ।**\n- आर्किमिडिजले उत्प्लावकताको सिद्धान्त र लिभरको नियम पत्ता लगाएका थिए।\n- ग्यालिलियो ग्यालिलिले दूरबीनको सुधार, खगोल विज्ञान र गति विज्ञानमा महत्त्वपूर्ण योगदान दिएका थिए।\n- अल्बर्ट आइन्स्टाइन सापेक्षताको सिद्धान्तका लागि प्रख्यात छन्।\nनोट: डार्विनले प्रजातिको उत्पत्ति, मानिसको वंश, अनुकूलनको अवधारणाको विकास, मानिसको पुर्खा बाँदर सम्बन्धी तथ्य, पृथ्वीमा सबै जीवनको साझा पुर्खाको लागि प्रमाण र यौन चयनको सिद्धान्त प्रस्तुत गरेका थिए।', 'nepali'),
      (v_set_id, 4, E'नेपाल टेलिभिजनबाट समाचार प्रसारण हुन थालेको पछिल्लो भाषा कुन हो?', E'मैथिली', E'नेपाल', E'डोटी', E'लिम्बु', 'B', E'**नेपाल टेलिभिजनबाट समाचार प्रसारण हुन थालेको पछिल्लो भाषा नेपाल भाषा हो।**\n- मैथिली भाषामा पनि नेपाल टेलिभिजनबाट समाचार प्रसारण हुन्छ।\n- डोटी भाषा सुदूरपश्चिम प्रदेशमा बोलिने एक प्रमुख भाषा हो।\n- लिम्बु भाषा किराँत समुदायको एक प्रमुख भाषा हो।\nनोट: नेपाल भाषामा २०७८ साल फागुन २ गतेदेखि नेपाल टेलिभिजनमा समाचार प्रसारण सुरु भएको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपालका वर्तमान राष्ट्रपति रामचन्द्र पौडेल तेस्रो राष्ट्रपतिका रूपमा कहिले निर्वाचित भए?', E'२०७९ पुस १०', E'२०७९ माघ ७', E'२०७९ माघ ५', E'२०७९ फागुन २५', 'D', E'**नेपालका वर्तमान राष्ट्रपति रामचन्द्र पौडेल २०७९ फागुन २५ गते तेस्रो राष्ट्रपतिका रूपमा निर्वाचित भएका थिए।**\n- २०७९ पुस १० गते पुष्पकमल दाहाल (प्रचण्ड) प्रधानमन्त्रीमा निर्वाचित भएका थिए।\n- २०७९ माघ ५ गते देवराज घिमिरे सभामुखका रूपमा निर्वाचित भएका थिए।\n- २०७९ माघ ७ गते इन्दिरा राना उपसभामुखमा निर्वाचित भएकी थिइन्।', 'nepali'),
      (v_set_id, 6, E'देहाएका मध्ये कुन जातिको सम्मानसूचक शब्द सुब्बा हो?', E'क्षेत्री', E'थकाली', E'नेवार', E'गनगाई', 'B', E'**थकाली जातिको सम्मानसूचक शब्द सुब्बा हो।**\n- क्षेत्री जातिको सम्मानसूचक शब्द काजी हो।\n- नेवार जातिको सम्मानसूचक शब्द साहुजी हो।\n- गनगाई जातिको सम्मानसूचक शब्द देउनिया हो।', 'nepali'),
      (v_set_id, 7, E'वीर समसेरले वीर अस्पताल कहिले स्थापना गरे?', E'वि.सं. १९३९', E'वि.सं. १९४७', E'वि.सं. १९५७', E'वि.सं. १९७४', 'B', E'**वीर समसेरले वीर अस्पतालको स्थापना वि.सं. १९४७ मा गरेका थिए।**\n- यो नेपालको पहिलो आधुनिक अस्पताल हो।', 'nepali'),
      (v_set_id, 8, E'नेपालको इतिहासमा मल्लकालिन समयमा प्रधानमन्त्री लाई चौतारा भनिन्थ्यो भने अनुसन्धान अधिकृत लाई के भनिन्थ्यो?', E'खरदार', E'चरदार', E'जिम्वार', E'कोतवाल', 'B', E'**मल्लकालिन समयमा अनुसन्धान अधिकृतलाई चरदार भनिन्थ्यो।**\n- जिम्वाल प्रशासकीय कर्मचारी थिए।\n- कोतवाल शान्ति सुरक्षा हेर्ने अधिकारी थिए।\n- खरदार देशभरिको भ्रमण गरी न्याय दिने अधिकारी थिए।', 'nepali'),
      (v_set_id, 9, E'म नै राज्य हुँ राज्य नै म हो भन्ने फ्रान्सेली राजा को हुन्?', E'लुई चौथो', E'लुई दशौं', E'लुई बाह्रौं', E'लुई सोह्रौं', 'D', E'**लुई सोह्रौं।**\n- उनी फ्रान्सेली राज्य क्रान्ति हुदाँका राजा थिए।', 'nepali'),
      (v_set_id, 10, E'महाभारत पहाडको दोस्रो अग्लो टाकुरा कुन हो?', E'फुलचोकी', E'गाभा', E'शैलुङ', E'द्यामके', 'D', E'**महाभारत पहाडको दोस्रो अग्लो टाकुरा द्यामके हो।**\n- महाभारत पर्वतको सबैभन्दा अग्लो टाकुरा शैलुङ हो।\n- द्यामके खोटाङ र भोजपुर जिल्लाको सिमानामा पर्दछ।', 'nepali'),
      (v_set_id, 11, E'कति रेक्टरस्केल भन्दा माथिको भूकम्पलाई शक्तिशाली भूकम्प भनिन्छ?', E'६ रेक्टर स्केल', E'७ रेक्टर स्केल', E'८ रेक्टर स्केल', E'९ रेक्टर स्केल', 'A', E'**६ रेक्टर स्केल भन्दा माथिको भूकम्पलाई शक्तिशाली भूकम्प भनिन्छ।**\n- ६ देखि ६.९ रेक्टर स्केलको भूकम्पलाई शक्तिशाली भूकम्प मानिन्छ।\n- ७ देखि ७.९ रेक्टर स्केलको भूकम्पलाई ठूलो भूकम्प भनिन्छ।', 'nepali'),
      (v_set_id, 12, E'विश्वको लामो पर्वतमाला एण्डिज देहाएको कुन देशमा अवस्थित छैन?', E'अर्जेन्टिना', E'कोलम्बिया', E'भेनेजुयला', E'ब्राजिल', 'D', E'विश्वको लामो पर्वतमाला एण्डिज **ब्राजिलमा अवस्थित छैन**। यो पर्वतमाला दक्षिण अमेरिकाका ७ देशहरू—पेरु, चिली, अर्जेन्टिना, कोलम्बिया, इक्वेडोर, बोलिभिया र भेनेजुयलामा फैलिएको छ।\nनोट: लगभग ७,२०० किलोमिटर लामो एण्डिज विश्वको सबैभन्दा लामो पर्वत श्रृंखला हो।', 'nepali'),
      (v_set_id, 13, E'नेपालको वर्तमान संविधानको नामाकरण सम्बन्धि व्यवस्था नेपालको संविधानको कुन धारामा उल्लेख छ?', E'धारा ३०७', E'धारा ३०८', E'धारा १', E'धारा २', 'A', E'नेपालको वर्तमान संविधानको नामाकरण सम्बन्धी व्यवस्था **धारा ३०७** मा गरिएको छ, जसमा यस संविधानलाई ''नेपालको संविधान'' भनिने उल्लेख छ। यो संविधान २०७२ साल असोज ३ गतेदेखि प्रारम्भ भएको हो।\nनोट: संविधानको धारा ३०८ ले नेपालको अन्तरिम संविधान, २०६३ लाई खारेज गरेको छ।', 'nepali'),
      (v_set_id, 14, E'राष्ट्रिय धान दिवस, २०८२ कति औं धान दिवस हो?', E'२२ औं', E'२१ औं', E'२० औं', E'१९ औं', 'B', E'राष्ट्रिय धान दिवस, २०८२ लाई **२१ औं** धान दिवसको रूपमा मनाइएको थियो।\nनोट: नेपालमा वि.सं. २०६० मंसिर २९ को निर्णय अनुसार वि.सं. २०६१ असार १५ देखि राष्ट्रिय धान दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 15, E'नेपाली इतिहासमा कुन राणा प्रधानमन्त्रीका पालामा २० वर्षे आवधिक योजना घोषणा गरिएको थियो?', E'चन्द्र शमशेर', E'सुवर्ण शमशेर', E'मोहन शमशेर', E'जुद्ध शमशेर', 'D', E'राणा प्रधानमन्त्री **जुद्ध शमशेर**ले आफ्नो पालामा २० वर्षे आवधिक योजनाको घोषणा गरेका थिए, तर त्यसलाई कार्यान्वयनमा ल्याइएन।\nनोट: नेपालमा योजनाबद्ध विकासको सुरुवात वि.सं. २०१३ सालबाट भएको हो र पहिलो पञ्चवर्षीय योजना प्रधानमन्त्री टंकप्रसाद आचार्यको पालामा ल्याइएको थियो।', 'nepali'),
      (v_set_id, 16, E'काष्ठमण्डपको निर्माण गर्ने मल्ल राजा को हुन् ?', E'विश्वजित मल्ल', E'लक्ष्मीनरसिंह मल्ल', E'जगतप्रकाश मल्ल', E'रणजित मल्ल', 'B', E'काष्ठमण्डपको निर्माण गर्ने मल्ल राजा **लक्ष्मीनरसिंह मल्ल** हुन्। काष्ठमण्डप नेपालमा काठबाट बनेको सबैभन्दा ठूलो मन्दिर हो, जसलाई मरुसत्तल उपनामले समेत चिनिन्छ।', 'nepali'),
      (v_set_id, 17, E'नेपालको इतिहासमा संसदद्वारा महाकाली सन्धि अनुमोदन हुँदा तत्कालीन प्रधानमन्त्री को थिए?', E'मात्रिकाप्रसाद कोइराला', E'गिरिजाप्रसाद कोइराला', E'बि. पि कोइराला', E'शेरबहादुर देउवा', 'D', E'महाकाली सन्धि संसदद्वारा अनुमोदन हुँदा नेपालका प्रधानमन्त्री **शेरबहादुर देउवा** थिए।\n- मात्रिकाप्रसाद कोइराला कोशि सम्झौता हुँदा प्रधानमन्त्री थिए।\n- बि. पि कोइराला गण्डकी सम्झौता हुँदा प्रधानमन्त्री थिए।', 'nepali'),
      (v_set_id, 18, E'नेपालको भूगोल अन्तर्गत नेपालको दक्षिणी विन्दुमा रहेको ठाउँ कुन विकल्प सहि छ?', E'झापाको धुलाबारी', E'झापाको लोदाबारी', E'झापाको गोदावरी', E'झापाको उर्लाबारी', 'B', E'नेपालको दक्षिणी विन्दु **झापाको लोदाबारी** हो।\nनेपालका चार सिमानाका विन्दुहरू यसप्रकार छन्:\n- पूर्वी: ताप्लेजुङको लेलेप\n- पश्चिमी: कन्चनपुरको दोधारा\n- उत्तरी: हुम्लाको च्याङ्ला\n- दक्षिणी: झापाको लोदाबारी', 'nepali'),
      (v_set_id, 19, E'सार्कको शक्तिशाली राष्ट्र भारतमा अंग्रेजले कहिले देखि शासन सुरु गरेका थिए?', E'१७५७ देखि', E'१७४७ देखि', E'१८५७ देखि', E'१९४७ देखि', 'A', E'अङ्ग्रेजले भारतमा सन् **१७५७ देखि** शासन सुरु गरेका थिए। उनीहरूले भारतमा कुल १९० वर्ष (१७५७ देखि १९४७ सम्म) शासन गरेका थिए।', 'nepali'),
      (v_set_id, 20, E'देहायका सौर्यमण्डलका ग्रहहरु मध्ये आफ्नो अक्षमा सबैभन्दा बढी वेगले घुम्ने ग्रह कुन हो?', E'अरुण', E'शुक्र', E'बुध', E'बृहस्पति', 'D', E'**बृहस्पति** सौर्यमण्डलका ग्रहहरूमध्ये आफ्नो अक्षमा सबैभन्दा बढी वेगले घुम्ने ग्रह हो।\n- बुध सूर्यको वरिपरि घुम्नको लागि सबैभन्दा छोटो दूरी भएकाले, सौर्यमण्डलको सबैभन्दा छोटो वर्ष ८८ दिनको हुन्छ।\nनोट: बृहस्पतिको एक दिन लगभग ९ घण्टा ५५ मिनेट ३० सेकेन्डको हुन्छ।', 'nepali'),
      (v_set_id, 21, E'नेपाली इतिहासमा २०३७ सालको जनमत संग्रह बेलाका प्रधानमन्त्री को हुन्?', E'लोकेन्द्र बहादुर चन्द', E'सूर्य बहादुर थापा', E'मरिचमान सिंह', E'कीर्तिनिधि बिष्ट', 'B', E'२०३७ सालको जनमत संग्रह बेलाका प्रधानमन्त्री **सूर्य बहादुर थापा** थिए।\n- जनमत संग्रह पछि प्रधानमन्त्री कीर्तिनिधि बिष्टले आफ्नो पदबाट राजीनामा दिएका थिए।\n- जनमत सङ्ग्रह पछि राष्ट्रिय पञ्चायतले नयाँ प्रधानमन्त्रीमा सूर्यबहादुर थापाको नाम निर्विरोध सिफारिस गरेको थियो।', 'nepali'),
      (v_set_id, 22, E'नेपालको संविधानको कति औं अनुसूचीमा स्थानीय तहको अधिकारको सूची उल्लेख गरिएको छ?', E'अनुसूची १', E'अनुसूची ७', E'अनुसूची ८', E'अनुसूची ६', 'C', E'नेपालको संविधानको **अनुसूची ८** मा स्थानीय तहको अधिकारको सूची उल्लेख गरिएको छ।\n| अनुसूची | अधिकारको सूची | विषय संख्या |\n| --- | --- | --- |\n| ५ | संघको अधिकार सूची | ३५ |\n| ६ | प्रदेशको अधिकार सूची | २१ |\n| ७ | संघ र प्रदेशको साझा अधिकार सूची | २५ |\n| ८ | स्थानीय तहको अधिकार सूची | २२ |\n| ९ | संघ, प्रदेश र स्थानीय तहको अधिकारको साझा सूची | १५ |', 'nepali'),
      (v_set_id, 23, E'नेपालको आर्थिक अवस्थामा चिया क्षेत्र घोषित जिल्लामा कुन पर्दैन?', E'मोरङ', E'झापा', E'धनकुटा', E'पाँचथर', 'A', E'नेपालको आर्थिक अवस्थामा चिया क्षेत्र घोषित जिल्लामा **मोरङ** पर्दैन।\n- चिया क्षेत्र घोषित पाँच जिल्लाहरू इलाम, धनकुटा, तेह्रथुम, झापा र पाँचथर हुन्।', 'nepali'),
      (v_set_id, 24, E'नेपाल संवत्को सुरुवात कहिले देखि भएको थियो?', E'वि.सं. ९३२', E'वि.सं. ९३८', E'वि.सं. ९३४', E'वि.सं. ९३६', 'D', E'नेपाल संवत्को सुरुवात **वि.सं. ९३६** देखि भएको थियो।\n- वि.सं. ९३६ मा राजा राघवदेवका पालामा शंखधर साख्वाले नेपाल संवत् चलाएका थिए।', 'nepali'),
      (v_set_id, 25, E'नेपालको भूगोलमा ल्याचुङ भञ्ज्याङ कुन जिल्लामा रहेको छ?', E'बझाङ', E'संखुवासभा', E'गोर्खा', E'डोल्पा', 'C', E'**ल्याचुङ भञ्ज्याङ गोर्खा जिल्लामा अवस्थित छ।**\n- गोर्खा जिल्लामा थाप्ले भञ्ज्याङ, लार्के भञ्ज्याङ, ग्याला भञ्ज्याङ, मेलाट साचिङ भञ्ज्याङ र याण्डोन भञ्ज्याङ पनि रहेका छन्।\n- बझाङ जिल्लामा साइपाल हिमाल र सुर्मा सरोवर जस्ता महत्वपूर्ण भौगोलिक स्थलहरू छन्।\n- संखुवासभा जिल्लामा मकालु हिमाल र अरुण नदीको उद्गमस्थल पर्दछ।\n- डोल्पा जिल्ला नेपालको सबैभन्दा ठूलो जिल्ला हो र यहाँ शे-फोक्सुण्डो ताल अवस्थित छ।', 'nepali'),
      (v_set_id, 26, E'लिच्छविकालमा प्रहरी प्रमुखलाई के भनिन्थ्यो ?', E'दण्डनायक', E'सर्वदण्डनायक', E'भट्ट', E'बलाध्यक्ष', 'B', E'**लिच्छविकालमा प्रहरी प्रमुखलाई सर्वदण्डनायक भनिन्थ्यो।**\n- दण्डनायक न्याय प्रशासनसँग सम्बन्धित अधिकारी थिए।\n- भट्ट सिपाहीलाई भनिन्थ्यो।\n- बलाध्यक्ष सेनापतिको पद थियो।', 'nepali'),
      (v_set_id, 27, E'कन्काई नदीलाई भारतमा बेरङ भनिन्छ भने महाकालीलाई के भनिन्छ ?', E'घोघरा', E'सरयु', E'महानन्दा', E'शारदा', 'D', E'**महाकाली नदीलाई भारतमा शारदा नामले चिनिन्छ।**\n- मेची नदीलाई भारतमा महानन्दा भनिन्छ।\n- बबई नदीलाई भारतमा सरयु भनिन्छ।\n- घोघरा भारतमा कर्णाली नदीको नाम हो।', 'nepali'),
      (v_set_id, 28, E'लिच्छविकालिन आकाशको पूर्ण चन्द्र भनी चिनिने राजा को हुन् ?', E'सुपुष्प', E'नरेन्द्रदेव', E'शिवदेव', E'प्रचण्डदेव', 'B', E'**लिच्छविकालिन राजा नरेन्द्रदेवलाई ''आकाशको पूर्ण चन्द्र'' भनी चिनिन्छ।**\n- सुपुष्प लिच्छवि वंशका संस्थापक मानिन्छन्।\n- शिवदेव प्रथम लिच्छविकालका एक शक्तिशाली राजा थिए।\n- प्रचण्डदेव लिच्छविकालका एक धार्मिक राजा थिए।', 'nepali'),
      (v_set_id, 29, E'नेपाली इतिहासमा "कार्यालय समय फागुनदेखि कार्तिक सम्म १०-५ र मंसिरदेखि माघसम्म १०-४ बनाउने" निर्धारण कसले गरेका हुन्?', E'देवशमशेर', E'वीरशमशेर', E'भीमशमशेर', E'पद्मशमशेर', 'D', E'**नेपाली इतिहासमा पद्मशमशेरले कार्यालय समय फागुनदेखि कार्तिकसम्म १०-५ र मंसिरदेखि माघसम्म १०-४ बनाउने निर्धारण गरेका थिए।**\n- भीमशमशेरले कार्यालय समय १०-४ निर्धारण गरेका थिए।\n- देवशमशेरले सरकारी समय १०-५ बजे निर्धारण गरेका थिए।\n- वीरशमशेरले नेपालमा पहिलो पटक जनगणनाको सुरुवात गरेका थिए।', 'nepali'),
      (v_set_id, 30, E'लोकसेवा आयोगका पदाधिकारीहरूको पदावधि कतिवर्षको रहेको छ ?', E'६ वर्ष', E'५ वर्ष', E'४ वर्ष', E'३ वर्ष', 'A', E'लोकसेवा आयोगका अध्यक्ष र सदस्यहरूको पदावधि नियुक्ति भएको मितिले **छ वर्षको** हुनेछ। नेपालको संविधानको भाग-२३ को धारा २४२ मा लोक सेवा आयोगको गठन र पदाधिकारीहरूको पदावधि सम्बन्धी व्यवस्था उल्लेख गरिएको छ।\nनोट: लोक सेवा आयोगमा एक अध्यक्ष र अन्य चार जना सदस्य रहने व्यवस्था छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/१४', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_18.csv  →  आसमान दैनिक GK — २०८२/०८/१८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/१८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/१८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/१८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा थोरै साक्षरता दर भएको प्रदेश मधेशमा साक्षरता दर कति रहेको छ?', E'८३.६ प्रतिशत', E'६९.४४ प्रतिशत', E'८२.१ प्रतिशत', E'६३.५ प्रतिशत', 'D', E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम साक्षरता दर भएको प्रदेश मधेश प्रदेश हो, जहाँ साक्षरता दर **६३.५ प्रतिशत** रहेको छ।\nनोट: यसै जनगणना अनुसार, सबैभन्दा बढी साक्षरता दर बागमती प्रदेशमा ८२.१% रहेको छ भने समग्र देशको साक्षरता दर ७६.२% छ।', 'nepali'),
      (v_set_id, 2, E'संसारमा सबैभन्दा धेरै बाँच्ने चरा हो?', E'अल्बाट्रस', E'हेरिकुल', E'सेरिम्बा', E'तित्रा', 'A', E'**संसारमा सबैभन्दा धेरै बाँच्ने चरा अल्बाट्रस हो।**\n- हेरिकुल मुखबाट पिसाब फेर्ने चरा हो।\n- सेरिम्बा कुकुर जस्तै भुक्ने चरा हो।\n- तित्रा धेरै फुल पार्ने चरा हो।', 'nepali'),
      (v_set_id, 3, E'औलो रोग कुन लामखुट्टेको टोकाइबाट सर्ने गर्दछ?', E'क्युलेक्स', E'फाटिन्गन्स', E'एनोफिलिस', E'एडिज', 'C', E'औलो रोग (Malaria) **एनोफिलिस (Anopheles)** जातको लामखुट्टेको टोकाइबाट सर्ने गर्दछ।\n- क्युलेक्स (Culex) लामखुट्टेले फाइलेरियासिस (हात्तीपाइले) र इन्सेफलाइटिस जस्ता रोगहरू सार्दछ।\n- फाटिन्गन्स (fatigans) क्युलेक्स जातको एक प्रजाति हो जसले मुख्यतया हात्तीपाइले रोग सार्दछ।\n- एडिज (Aedes) लामखुट्टेको टोकाइबाट डेंगु, पीतज्वर (yellow fever) र इन्सेफलाइटिस जस्ता रोगहरू सर्दछन्।', 'nepali'),
      (v_set_id, 4, E'नेपालको पहिलो इन्टरनेटमा राखिएको चलचित्र कुन हो?', E'गौंथली', E'बादलपारी', E'श्री स्वस्थानी', E'परालको आगो', 'B', E'नेपालको पहिलो इन्टरनेटमा राखिएको चलचित्र **बादलपारी** हो।\n- गौंथली नेपालको पहिलो गिति चलचित्र हो।\n- श्री स्वस्थानी नेपालको पहिलो पौराणिक चलचित्र हो।\n- परालको आगो पहिलो महिला संगीतकार भएको चलचित्र हो।', 'nepali'),
      (v_set_id, 5, E'देहाएका मध्ये कुन घटना जुद्ध समसेरको पालामा भएको हैन?', E'प्रथम जनगणना सुरु', E'कागजि नोट सुरु', E'SLC बोर्ड स्थापना', E'पहिलो बैंक स्थापना', 'A', E'नेपालमा **प्रथम जनगणनाको सुरुवात** वि.सं. १९६८ मा चन्द्र समसेरको पालामा भएको थियो, जुद्ध समसेरको पालामा होइन।\n- कागजी नोटको सुरुवात वि.सं. २००२ मा जुद्ध समसेरको पालामा भएको थियो।\n- SLC बोर्डको स्थापना वि.सं. १९९० मा जुद्ध समसेरले गरेका थिए।\n- पहिलो बैंक (नेपाल बैंक लिमिटेड) को स्थापना वि.सं. १९९४ मा जुद्ध समसेरकै पालामा भएको थियो।', 'nepali'),
      (v_set_id, 6, E'पर्यटनका लागि साहित्य : गोरखापत्र साहित्य सम्मेलन नेपालको कुन जिल्लामा सञ्चालन भएको छ ?', E'काभ्रे', E'दोलखा', E'ललितपुर', E'कैलाली', 'B', E'पर्यटनका लागि साहित्य : गोरखापत्र साहित्य सम्मेलन **दोलखा** जिल्लामा सञ्चालन भएको थियो।\nनोट: यो सम्मेलन २०८२ मंसिर ५-६ गते दोलखाको शैलुङमा सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 7, E'बानिरा प्रज्ञा पुरस्कार, २०८१ कसलाई प्रदान गरिएको छ ?', E'शशी शाह', E'जीवा लामिछाने', E'रामकुमार पाण्डे', E'कविमल वैद्य', 'C', E'बानिरा प्रज्ञा पुरस्कार, २०८१ **रामकुमार पाण्डे**लाई प्रदान गरिएको थियो।\n- शशी शाहलाई बानिरा शंकर पुरस्कार, २०८१ प्रदान गरिएको थियो।\n- जीवा लामिछानेलाई उनको कृति ''अक्षत अन्टार्कटिका'' का लागि उत्तम शान्ति पुरस्कार, २०८१ प्रदान गरिएको थियो।\n- कविमल वैद्य, मानबहादुर मुखिया र सन्ध्या पहाडीलाई संयुक्त रूपमा वासुशी साहित्य पुरस्कार, २०८१ प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 8, E'२०८२ मा पहिलो पटक याक दिवस कहिले मनाइएको छ ?', E'वैशाख २', E'वैशाख ४', E'वैशाख ५', E'वैशाख ७', 'D', E'नेपालमा पहिलो पटक राष्ट्रिय याक दिवस २०८२ साल **वैशाख ७** गते मनाइएको थियो।\nनोट: नेपाल सरकारले प्रत्येक वर्ष वैशाख ७ लाई राष्ट्रिय याक दिवसको रूपमा मनाउने निर्णय गरेको छ।', 'nepali'),
      (v_set_id, 9, E'संयुक्त राष्ट्रसंघको हाल सक्रिय अंग कतिवटा रहेका छन्?', E'४ वटा', E'५ वटा', E'६ वटा', E'७ वटा', 'B', E'संयुक्त राष्ट्रसंघका ६ प्रमुख अंगहरूमध्ये हाल **५ वटा** सक्रिय रहेका छन्। जिम्माजमानी परिषद् (Trusteeship Council) हाल निष्क्रिय रहेको छ।\nनोट: संयुक्त राष्ट्रसंघका ६ प्रमुख अंगहरू महासभा, सुरक्षा परिषद्, आर्थिक तथा सामाजिक परिषद्, जिम्माजमानी परिषद्, अन्तर्राष्ट्रिय न्यायालय र सचिवालय हुन्।', 'nepali'),
      (v_set_id, 10, E'प्रथम विश्वयुद्ध करिब कति समय चलेको थियो?', E'३ वर्ष', E'४ वर्ष', E'५ वर्ष', E'६ वर्ष', 'B', E'प्रथम विश्वयुद्ध करिब **४ वर्ष** चलेको थियो। यो युद्ध ४ वर्ष ३ महिना र ११ दिनसम्म (सन् १९१४ जुलाई २८ देखि १९१८ नोभेम्बर ११ सम्म) चलेको थियो।', 'nepali'),
      (v_set_id, 11, E'नेपालको नैनिताल भनेर कुन स्थानलाई चिनिन्छ?', E'त्रिवेणी धाम', E'लोमान्थाङ', E'जुम्ला', E'मनास्लु', 'A', E'**नवलपरासीको त्रिवेणी धामलाई नेपालको नैनिताल भनेर चिनिन्छ।**\n- लोमान्थाङ (मुस्ताङ) लाई नेपालको माटोको शहर भनिन्छ।\n- जुम्लालाई नेपालको दार्जिलिङ र नेपालको काश्मिर उपनामले चिनिन्छ।\n- मनास्लुलाई नेपालको माउन्ट फुजी भनिन्छ।', 'nepali'),
      (v_set_id, 12, E'इटालीको राजधानी रोम कुन नदीको किनारमा अवस्थित रहेको छ?', E'टिबर नदी', E'टेम्स नदी', E'दोन नदी', E'पो नदी', 'A', E'**इटालीको राजधानी रोम टिबर नदीको किनारमा अवस्थित छ।**\n- टेम्स नदीको किनारमा इंग्ल्याण्डको राजधानी लन्डन अवस्थित छ।\n- दोन नदी रुसको एक मुख्य नदी हो।\n- पो नदी इटालीमा बग्ने मुख्य नदी हो, जसलाई ''इटालीको गंगा'' पनि भनिन्छ।', 'nepali'),
      (v_set_id, 13, E'पृथ्वी सौर्यमण्डलको कति औं सानो ग्रह हो?', E'तेस्रो', E'पाँचौ', E'छैटौं', E'चौथो', 'B', E'आकारको आधारमा पृथ्वी सौर्यमण्डलको **पाँचौँ** ठूलो ग्रह हो। सौर्यमण्डलको सबैभन्दा ठूलो ग्रह बृहस्पति र सबैभन्दा सानो ग्रह बुध हो।\nनोट: सूर्यबाट दूरीको आधारमा पृथ्वी तेस्रो ग्रहमा पर्दछ।', 'nepali'),
      (v_set_id, 14, E'सर्वोच्च अदालतमा नेपालको प्रधान न्यायाधीशका अतिरिक्त बढीमा कति जना न्यायाधीश रहने व्यवस्था रहेको छ?', E'१५ जना', E'२० जना', E'१० दिन', E'२५ दिन', 'B', E'नेपालको संविधानको धारा १२९ अनुसार सर्वोच्च अदालतमा प्रधान न्यायाधीशका अतिरिक्त बढीमा **२० जना** अन्य न्यायाधीश रहने व्यवस्था छ।', 'nepali'),
      (v_set_id, 15, E'WTO को कान्छो सदस्य कुन हो?', E'अफगानिस्तान', E'लाइबेरिया', E'कोमोरोस', E'टिमोर लिस्टे', 'D', E'विश्व व्यापार संगठन (WTO) को सबैभन्दा कान्छो सदस्य राष्ट्र **टिमोर लिस्टे** हो, जुन सन् २०२४ अगष्ट ३० मा १६६ औं सदस्य बनेको थियो।\n- कोमोरोस सन् २०२४ अगष्ट २१ मा १६५ औं सदस्य बनेको थियो।\n- अफगानिस्तान सन् २०१६ जुलाई २९ मा १६४ औं सदस्य बनेको थियो।\n- लाइबेरिया सन् २०१६ जुलाई १४ मा १६३ औं सदस्य बनेको थियो।\nनोट: विश्व व्यापार संगठन (WTO) को स्थापना सन् १९९५ जनवरी १ मा भएको हो र यसको प्रधान कार्यालय स्विट्जरल्याण्डको जेनेभामा रहेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/१८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_19.csv  →  आसमान दैनिक GK — २०८२/०८/१९  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/१९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/१९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/१९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'पहिचान सम्मान पुरस्कार, २०८२ कसलाई प्रदान गरिएको छ ?', E'गणेश कुमार राई', E'बैरागी काइँला', E'नीलकण्ठ न्यौपाने', E'गोविन्द भट्टराई', 'B', E'पहिचान सम्मान पुरस्कार, २०८२ **बैरागी काइँला**लाई प्रदान गरिएको थियो।\n- गणेश कुमार राईले पहिलो पटक पहिचान युवा सम्मान, २०८२ प्राप्त गरेका थिए।\n- नीलकण्ठ न्यौपानेले साहित्य पुरस्कार, २०८२ प्राप्त गरेका थिए।\n- गोविन्द भट्टराईलाई ग्रामीण पत्रकारिता पुरस्कार, २०८२ प्रदान गरिएको थियो।\nनोट: पहिचान सम्मान पुरस्कारको राशि पाँच लाख दुई हजार दुई रुपैयाँ रहेको थियो।', 'nepali'),
      (v_set_id, 2, E'२०२५ मा मनाइएको विश्व एड्स दिवस कति औं एड्स दिवस हो ?', E'३५ औं', E'३६ औं', E'३७ औं', E'३८ औं', 'D', E'सन् २०२५ डिसेम्बर १ मा मनाइएको विश्व एड्स दिवस **३८ औं** संस्करणको थियो। यो दिवस सन् १९८८ देखि मनाउन थालिएको हो।\nनोट: सन् २०२५ को राष्ट्रिय नारा ''अवरोधहरू पार गरौं, एड्स प्रतिकार्य रूपान्तरण गरौं'' रहेको थियो।', 'nepali'),
      (v_set_id, 3, E'भूमि समस्या समाधान आयोग खारेज गर्ने सरकार को निर्णय सर्वोच्च अदालत बाट बदर कहिले भएको छ ?', E'२०८२ मंसिर १४', E'२०८२ मंसिर १५', E'२०८२ मंसिर १६', E'२०८२ मंसिर १७', 'B', E'सरकारले भूमि समस्या समाधान आयोग खारेज गर्ने निर्णयलाई सर्वोच्च अदालतले **२०८२ मंसिर १५** गते बदर गरेको हो।\nनोट: सरकारले भने २०८२ असोज २३ गते आयोग खारेज गर्ने निर्णय गरेको थियो।', 'nepali'),
      (v_set_id, 4, E'एसिसी यू-१९ प्रिमियर कपको उपाधि कुन मुलुकले प्राप्त गरेको छ ?', E'कतार', E'नेपाल', E'युएई', E'बंगलादेश', 'C', E'**एसिसी यू-१९ प्रिमियर कपको उपाधि युएईले प्राप्त गरेको छ।**\n- नेपाल उपविजेता बनेको थियो।\n- कतार र बंगलादेश पनि प्रतियोगितामा सहभागी राष्ट्रहरू थिए।\nनोट: प्रतियोगितामा १४ टोली सहभागी थिए र युएईले नै आयोजना गरेको थियो।', 'nepali'),
      (v_set_id, 5, E'हाल सालै भीषण बाढीपहिरोका कारण आपतकाल घोषणा भएको सार्क मुलुक कुन हो ?', E'श्रीलंका', E'भारत', E'माल्दिभ्स', E'बंगलादेश', 'A', E'हालै भीषण बाढीपहिरोका कारण **श्रीलंकामा** आपतकाल घोषणा गरिएको छ।\n- भारत, माल्दिभ्स र बंगलादेश पनि सार्क सदस्य राष्ट्रहरू हुन् तर आपतकाल श्रीलंकामा घोषणा भएको हो।\nनोट: श्रीलंकाका राष्ट्रपति अनुरा कुमार दिसानायकेले सार्वजनिक आपतकालको घोषणा गरेका थिए।', 'nepali'),
      (v_set_id, 6, E'२०८२ मंसिर १५ गतेको मन्त्रीपरिषदले एकपटकमा कति रूपियाँ भन्दा बढी कारोबार गर्दा वित्तीय संस्था वा बैंकिङ उपकरणमार्फत गर्नुपर्ने गरी नगद कारोबारको सीमा निर्धारण गरेको छ ?', E'४ लाख', E'५ लाख', E'६ लाख', E'७ लाख', 'B', E'२०८२ मंसिर १५ गतेको मन्त्रिपरिषद्को निर्णयले एकपटकमा **५ लाख रूपियाँ** वा सोभन्दा बढी मूल्यको कारोबार गर्दा वित्तीय संस्था वा बैंकिङ उपकरणमार्फत गर्नुपर्ने गरी नगद कारोबारको सीमा निर्धारण गरेको छ।\nनोट: यो निर्णय २०८२ माघ १ गतेदेखि लागू हुनेछ।', 'nepali'),
      (v_set_id, 7, E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या कति पुगेको छ ?', E'४४ वटा', E'४३ वटा', E'४५ वटा', E'४६ वटा', 'D', E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या **४६ वटा** पुगेको छ।\nनोट: २०८२ मंसिर १६ गतेदेखि ४६ औं भाषाको रूपमा कुलुङ भाषालाई समावेश गरिएको हो।', 'nepali'),
      (v_set_id, 8, E'हालसालै भारत सरकारले प्रधानमन्त्री कार्यालयको नाम परिवर्तन गरी के राखेको छ ?', E'लोक भवन', E'सेवा तीर्थ', E'कर्तव्य भवन', E'मोदी राज', 'B', E'भारत सरकारले प्रधानमन्त्री कार्यालयको नाम परिवर्तन गरी **सेवा तीर्थ** राखेको छ।\n- देशभरका राजभवनलाई अब लोक भवन भनिनेछ।\n- केन्द्रीय सचिवालयलाई कर्तव्य भवनको नामले चिनिने भएको छ।\nनोट: यो निर्णय डिसेम्बर २, २०२५ मा गरिएको थियो।', 'nepali'),
      (v_set_id, 9, E'सरकारले प्रत्येक वर्ष कुन दिनलाई जेनजी सहिद दिवसको रूपमा मनाउने निर्णय गरेको छ ?', E'भाद्र २३', E'भाद्र २४', E'भाद्र २५', E'भाद्र २६', 'A', E'सरकारले प्रत्येक वर्ष **भाद्र २३** लाई जेनजी सहिद दिवसको रूपमा मनाउने निर्णय गरेको छ।\nनोट: यो निर्णय वि.सं. २०८२ भदौ १५ गतेको मन्त्रिपरिषद्को बैठकले गरेको हो।', 'nepali'),
      (v_set_id, 10, E'साउथ एसियन फेडेरेसन अफ एकाउन्टेन्ट (साफा) अवार्ड २०२४ बाट सम्मानित हुन सफल नेपाली बैंक कुन हो ?', E'नबिल बैंक लि.', E'ग्लोबल आइएमई बैंक', E'कुमारी बैंक लि.', E'कामना सेवा विकास बैंक', 'D', E'साउथ एसियन फेडेरेसन अफ एकाउन्टेन्ट (साफा) अवार्ड २०२४ बाट **कामना सेवा विकास बैंक** सम्मानित भएको छ।', 'nepali'),
      (v_set_id, 11, E'२०२६ मा कोप ३१ कुन मुलुकमा आयोजना हुने भनिएको छ ?', E'अष्ट्रेलिया', E'ब्राजिल', E'टर्की', E'भारत', 'C', E'सन् २०२६ मा हुने जलवायु परिवर्तनसम्बन्धी संयुक्त राष्ट्रसंघीय सम्मेलन (कोप ३१) **टर्कीको** अन्टल्यामा आयोजना हुनेछ।\nनोट: यस सम्मेलनको अध्यक्षता टर्कीले गर्नेछ भने अष्ट्रेलियाले वार्ताको नेतृत्व गर्नेछ।', 'nepali'),
      (v_set_id, 12, E'नेपाल प्रिमियर लिगमा कप्तानी गर्ने पहिलो विदेशी खेलाडी को हुन् ?', E'मार्टिन गुप्टिल', E'बेन पार्नेल', E'एडम रोसिङ्टन', E'मार्क वाट', 'B', E'दक्षिण अफ्रिकाका अलराउन्डर **बेन पार्नेल** नेपाल प्रिमियर लिगमा कप्तानी गर्ने पहिलो विदेशी खेलाडी बनेका छन्।\nनोट: उनले नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा जनकपुर बोल्ट्सबाट सुदूरपश्चिम विरुद्धको खेलमा कप्तानी गरेका थिए।', 'nepali'),
      (v_set_id, 13, E'चुच्चे नक्सा सहितको रू.१०० को नोट कहिले देखि प्रकाशनमा आएको छ ?', E'२०८२ मङ्सिर १०', E'२०८२ मङ्सिर ११', E'२०८२ मङ्सिर १२', E'२०८२ मङ्सिर १३', 'B', E'चुच्चे नक्सा सहितको रू.१०० को नोट **२०८२ मङ्सिर ११** देखि प्रकाशनमा आएको छ। तत्कालीन पुष्पकमल दाहाल ''प्रचण्ड'' नेतृत्वको मन्त्रिपरिषदले २०८१ वैशाख २० गते यो निर्णय गरेको थियो।\nनोट: उक्त नोटमा पूर्व गभर्नर महाप्रसाद अधिकारीको हस्ताक्षर रहेको छ।', 'nepali'),
      (v_set_id, 14, E'हालसालै सेनाको हस्तक्षेप पछि नागरिक सरकार अपदस्थ भएको अफ्रिकी मुलुक कुन हो ?', E'गिनी-बिसाउ', E'नाइजेरिया', E'बुर्किना फासो', E'इस्वातिनि', 'A', E'हालसालै पश्चिम अफ्रिकी मुलुक **गिनी-बिसाउमा** सेनाले हस्तक्षेप गरी नागरिक सरकार अपदस्थ गरेको छ। राष्ट्रपति चुनावको नतिजा सार्वजनिक हुनुभन्दा एक दिन अगाडि सेनाले सत्ता कब्जा गरेको थियो।\nनोट: पछिल्ला पाँच वर्षमा पश्चिम र मध्य अफ्रिकामा भएको यो नवौं सैनिक ''कू'' हो।', 'nepali'),
      (v_set_id, 15, E'यू-१७ विश्वकप २०२५ को उपाधि कुन मुलुकले प्राप्त गरेको छ ?', E'कतार', E'अस्ट्रिया', E'पोर्चुगल', E'स्पेन', 'C', E'**यू-१७ विश्वकप २०२५ को उपाधि पोर्चुगलले जितेको छ।**\n- कतारले यो प्रतियोगिता आयोजना गरेको थियो।\n- अस्ट्रिया फाइनलमा पोर्चुगलसँग १-० गोल अन्तरले पराजित भई उपविजेता बनेको थियो।\n- स्पेन प्रतियोगितामा सहभागी एक राष्ट्र थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/१९', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_22.csv  →  आसमान दैनिक GK — २०८२/०८/२२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/२२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/२२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/२२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाली इतिहासको पहिलो संविधान कुन प्रधानमन्त्री को पालामा निर्माण भएको थियो?', E'पद्म शमशेर', E'मोहन शमशेर', E'भीम शमशेर', E'भिमसेन थापा', 'A', E'नेपाली इतिहासको पहिलो संविधान, ''नेपाल सरकारको वैधानिक कानुन, २००४'', **पद्म शमशेरको** पालामा निर्माण भएको थियो।\n- मोहन शमशेर नेपालका अन्तिम राणा प्रधानमन्त्री थिए।\n- भीम शमशेर पनि एक राणा प्रधानमन्त्री थिए।\n- भिमसेन थापा नेपालका प्रथम मुख्तियार (प्रधानमन्त्री) थिए।\nनोट: यो संविधान २००४ माघ १३ गते जारी भए पनि पूर्ण रूपमा लागू हुन सकेन।', 'nepali'),
      (v_set_id, 2, E'राज्यको संप्रभुता राजाको दैवी सिद्धान्तमा हैन जनताको इच्छामा भर पर्छ यो भनाइ कसको हो?', E'केटलबी', E'रुसो', E'भोल्तेयर', E'लुई सोह्रौं', 'B', E'"राज्यको संप्रभुता राजाको दैवी सिद्धान्तमा हैन जनताको इच्छामा भर पर्छ" भन्ने भनाइ **रुसोको** हो।\n- केटलबी यस राजनीतिक दर्शनको सन्दर्भमा सम्बन्धित व्यक्तित्व होइनन्।\n- भोल्तेयर वाक् स्वतन्त्रता र धर्मनिरपेक्षताका पक्षपाती फ्रान्सेली दार्शनिक थिए।\n- लुई सोह्रौं फ्रान्सका राजा थिए जसको शासनकालमा फ्रान्सेली राज्यक्रान्ति भएको थियो।\nनोट: रुसो "सामाजिक सम्झौता" (The Social Contract) नामक प्रसिद्ध पुस्तकका लेखक हुन्।', 'nepali'),
      (v_set_id, 3, E'बैदाम तालको उपनामले कुन ताललाई चिनिन्छ?', E'सुर्मासरोवर ताल', E'फेवाताल', E'पन्चासे ताल', E'विष्णुतीर्थ ताल', 'B', E'**फेवाताललाई** बैदाम तालको उपनामले चिनिन्छ।\n- सुर्मासरोवर ताललाई ''आँखा आकारको ताल'' उपनामले चिनिन्छ।\n- पन्चासे ताललाई ''सफेदमा पात रहने ताल'' भनेर चिनिन्छ।\n- विष्णुतीर्थ ताल रानी पोखरीको अर्को नाम हो।', 'nepali'),
      (v_set_id, 4, E'देइएका विश्वका ठुला सागर मध्ये औसत गहिराइ सबैभन्दा धेरै भएको सागर कुन हो?', E'क्यारेबियन सी', E'साउथ चाइना सी', E'भुमध्य सागर', E'बेरिङ सी', 'A', E'दिएका सागरहरूमध्ये **क्यारेबियन सी (Caribbean Sea)** को औसत गहिराइ सबैभन्दा धेरै छ।', 'nepali'),
      (v_set_id, 5, E'एसिया र युरोपको सिमाना छुट्याउने पर्वतमाला कुन हो?', E'काकेशश', E'युराल', E'आल्प्स', E'अलस्का', 'B', E'एसिया र युरोपको सिमाना छुट्याउने पर्वतमाला **युराल** हो। यो पर्वतमाला रुस र काजकिस्तानमा एसिया र युरोपको सिमानामा रहेको छ।\nनोट: यस पर्वतमालाको अग्लो हिमाल रुसको नरोदनाया पर्वत (१८६४ मिटर) हो।', 'nepali'),
      (v_set_id, 6, E'पर्यावरणीय पर्यटनका प्रथम प्रयोगकर्ता को हुन्?', E'अर्नेस्ट ह्याकेल', E'हेक्टर सेवालस लास्कुरेन', E'कार्ल एरेली', E'अकिले गुड्लार्ड', 'B', E'**हेक्टर सेवालस लास्कुरेन** पर्यावरणीय पर्यटनका प्रथम प्रयोगकर्ता हुन्।\n- अर्नेस्ट ह्याकेलले ''इकोलोजी'' (Ecology) शब्दको पहिलो पटक प्रयोग गरेका थिए।\n- कार्ल एरेली जैविक प्रविधिका प्रथम प्रयोगकर्ता हुन्।\n- अकिले गुड्लार्ड जनसांख्यिकीका प्रथम प्रयोगकर्ता मानिन्छन्।', 'nepali'),
      (v_set_id, 7, E'''कुनै एक पुस्ताका जीवमा आर्जित भएको गुण वा परिवर्तन अर्को पुस्ताका सन्तानमा सर्दै जान्छ'' यो सिद्धान्त कोसँग सम्बन्धित छ?', E'मेण्डलको', E'डार्विनको', E'लेमार्कको', E'ग्रेगरको', 'C', E'कुनै एक पुस्ताका जीवमा आर्जित भएको गुण वा परिवर्तन अर्को पुस्ताका सन्तानमा सर्दै जान्छ भन्ने सिद्धान्त **लेमार्कको** हो। यसलाई ''आर्जित गुणको वंशाणुगत सिद्धान्त'' (Inheritance of Acquired Characteristics) पनि भनिन्छ।\nनोट: यस सिद्धान्त अनुसार, सक्रिय अंग बढी विकसित र निष्क्रिय अंग कम विकसित हुँदै जान्छन्।', 'nepali'),
      (v_set_id, 8, E'अघिल्लो जन्ममा स्त्री र पछिल्लो जन्ममा पुरुष हुने महाभारतको पात्र को हुन्?', E'द्रौपदी', E'शिखण्डी', E'अश्वत्थामा', E'विभीषण', 'B', E'महाभारतमा अघिल्लो जन्ममा स्त्री (अम्बा) र पछिल्लो जन्ममा पुरुष हुने पात्र **शिखण्डी** हुन्।\n- द्रौपदी पाण्डवहरूका पाँच भाइ छोराहरूकी श्रीमती थिइन्।\n- अश्वत्थामाले पाण्डवहरूका पाँच भाइ छोराहरूलाई निदाएको बेला मारेका थिए।\n- विभीषण रामायणका पात्र हुन्, जो रावणलाई मारेपछि लंकाका राजा बनेका थिए।', 'nepali'),
      (v_set_id, 9, E'सरकारले राष्ट्रिय सभामा रिक्त सदस्य पूर्तिका लागि कुन मितिमा निर्वाचन गर्ने निर्णय गरेको छ ?', E'२०८२ माघ १०', E'२०८२ माघ ११', E'२०८२ माघ १२', E'२०८२ माघ १३', 'B', E'सरकारले राष्ट्रिय सभामा रिक्त सदस्य पूर्तिका लागि **२०८२ माघ ११** गते निर्वाचन गर्ने निर्णय गरेको छ।\nनोट: यो निर्णय वि.सं. २०८२ कार्तिक १२ गते बसेको मन्त्रिपरिषद् बैठकले गरेको हो।', 'nepali'),
      (v_set_id, 10, E'देहायका मध्ये कुन आसियानको सदस्य हैन?', E'भियतनाम', E'ब्रुनाइ', E'ताइवान', E'पूर्वी टिमोर', 'C', E'**ताइवान आसियानको सदस्य राष्ट्र होइन।**\n- भियतनाम, ब्रुनाइ र पूर्वी टिमोर आसियानका सदस्य राष्ट्रहरू हुन्।\nनोट: आसियानमा इन्डोनेशिया, मलेसिया, फिलिपिन्स, सिंगापुर, थाइल्याण्ड, ब्रुनाइ, भियतनाम, म्यानमार, लाओस, कम्बोडिया र पूर्वी टिमोर गरी जम्मा ११ सदस्य राष्ट्रहरू छन्।', 'nepali'),
      (v_set_id, 11, E'सार्कको वडापत्रमा हस्ताक्षर गर्ने एकमात्र प्रधानमन्त्री कुन मुलुकका हुन?', E'श्रीलंका', E'भुटान', E'भारत', E'अफगानिस्तान', 'C', E'**सार्कको वडापत्रमा हस्ताक्षर गर्ने एकमात्र प्रधानमन्त्री भारतका राजीव गान्धी थिए।**\n- श्रीलंकाबाट राष्ट्रपतिले हस्ताक्षर गरेका थिए।\n- भुटानबाट राजा जिग्मे सिङ्गे वाङचुकले हस्ताक्षर गरेका थिए।\n- अफगानिस्तान सार्कको संस्थापक सदस्य नभई पछिबाट सदस्य बनेको राष्ट्र हो।\nनोट: वडापत्रमा हस्ताक्षर गर्नेहरूमा नेपालका राजा वीरेन्द्र शाह पनि थिए।', 'nepali'),
      (v_set_id, 12, E'सौर्यमण्डलको कुन ग्रहलाई ''Earth sister planet'' को उपनामले समेत चिनिन्छ?', E'शुक्र ग्रह', E'शनि ग्रह', E'मंगल ग्रह', E'बुध ग्रह', 'A', E'**शुक्र ग्रहलाई ''Earth sister planet'' (पृथ्वीको बैनी ग्रह) को उपनामले चिनिन्छ।**\n- शनि ग्रहलाई ''Ringed Planet'' (रिङ भएको ग्रह) भनिन्छ।\n- मंगल ग्रहलाई ''Red Planet'' (रातो ग्रह) भनेर चिनिन्छ।\n- बुध ग्रह सौर्यमण्डलको सबैभन्दा सानो र सूर्यको सबैभन्दा नजिकको ग्रह हो।\nनोट: शुक्र ग्रहलाई Morning Star (बिहानको तारा) र Evening Star (साँझको तारा) पनि भनिन्छ।', 'nepali'),
      (v_set_id, 13, E'नेपालको संविधान बमोजिम सम्मानपूर्वक बाँच्न पाउने हक कसलाई प्राप्त हुन्छ?', E'प्रत्येक व्यक्तिलाई', E'प्रत्येक नागरिकलाई', E'हरेक व्यक्तिलाई', E'सबै नागरिकलाई', 'A', E'नेपालको संविधानको धारा १६ मा **प्रत्येक व्यक्तिलाई** सम्मानपूर्वक बाँच्न पाउने हकको व्यवस्था गरिएको छ। यो हक नागरिकलाई मात्र नभई नेपालको भूभागमा रहेका सबै व्यक्तिहरूलाई प्राप्त हुन्छ।\nनोट: नागरिकता नभएका व्यक्तिले पनि यो मौलिक हक उपभोग गर्न पाउँछन्।', 'nepali'),
      (v_set_id, 14, E'उखुको लागि प्रसिद्ध ठाँउ कुन हो?', E'धुनिबेशी', E'सिन्धुली', E'मालनेटा', E'फर्पिङ्ग', 'B', E'**उखु खेतीका लागि सिन्धुली जिल्ला प्रसिद्ध छ।**\n- मालनेटा अदुवाको लागि प्रसिद्ध छ।\n- फर्पिङ्ग नासपातिको लागि प्रसिद्ध छ।\nनोट: अन्य प्रसिद्ध स्थानहरूमा तेलको लागि खोकना, दहीको लागि भक्तपुर, र खुवाको लागि ठेचो (ललितपुर) पर्दछन्।', 'nepali'),
      (v_set_id, 15, E'हाल नेपालसँग दोहोरो करमुक्ति सम्झौता भएका मुलुक कति रहेका छन् ?', E'१० मुलुक', E'११ मुलुक', E'१२ मुलुक', E'१३ मुलुक', 'A', E'हाल नेपालसँग दोहोरो करमुक्ति सम्झौता भएका मुलुकको संख्या **१०** रहेको छ। नेपाल र मौरिससबीच सन् १९९९ अगस्ट ३ मा भएको सम्झौता २०८२ कार्तिक १२ गते रद्द भएसँगै यो संख्या ११ बाट घटेर १० कायम भएको हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/२२', 15;
END $$;

