      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आसियानका २ वटा पर्यवेक्षक मुलुक कुन-कुन हुन्?', E'पपुवा न्युगिनी र पूर्वी टिमोर', E'भ्याटिकन सिटी र पपुवा न्युगिनी', E'भ्याटिकन सिटी र ताइवान', E'भ्याटिकन सिटी र प्यालेस्टाइन', 'A', E'**पपुवा न्युगिनी र पूर्वी टिमोर आसियानका दुई पर्यवेक्षक मुलुक हुन्।**\n- भ्याटिकन सिटी संयुक्त राष्ट्र संघमा होलेसी (Holy See) को रूपमा चिनिन्छ।\n- ताइवानलाई संयुक्त राष्ट्र संघमा होलेसीको रूपमा चिनिन्छ।\n- प्यालेस्टाइन संयुक्त राष्ट्र संघमा पर्यवेक्षक मुलुकको रूपमा चिनिन्छ।', 'nepali'),
      (v_set_id, 2, E'जैविक जीव, वनस्पतिबीचको भिन्नता, सङ्ख्या र अन्तरसम्बन्धलाई के भनिन्छ?', E'जनसंख्या', E'दिगो विकास', E'जैविक विविधता', E'जलवायु परिवर्तन', 'C', E'**जैविक जीव र वनस्पतिबीचको भिन्नता, सङ्ख्या र अन्तरसम्बन्धलाई जैविक विविधता भनिन्छ।**\n- जनसंख्याले कुनै निश्चित क्षेत्रमा बस्ने जीवहरूको कुल सङ्ख्यालाई जनाउँछ।\n- दिगो विकासले वर्तमान पुस्ताको आवश्यकता पूरा गर्दै भविष्यका पुस्ताको आवश्यकतामा सम्झौता नगर्ने विकासलाई बुझाउँछ।\n- जलवायु परिवर्तन पृथ्वीको मौसम प्रणालीमा हुने दीर्घकालीन परिवर्तन हो।', 'nepali'),
      (v_set_id, 3, E'''गोरी आमा र कालो बुवा बीच प्रजनन हुँदा पहिलो वंश को सन्तान गोरो जन्मिएछ'' माथिको कथन कुन विकल्प सँग सम्बन्धित छ?', E'स्वतन्त्र गुण', E'लुप्त गुण', E'डिमाहा गुण', E'प्रबल गुण', 'D', E'**गोरी आमा र कालो बुवा बीच प्रजनन हुँदा पहिलो वंशको सन्तान गोरो जन्मिनु प्रबल गुणसँग सम्बन्धित छ।**\n- लुप्त गुण भनेको पहिलो वंशमा प्रकट नहुने गुण हो।\n- स्वतन्त्र गुणले एक गुणको वंशाणु अर्को गुणको वंशाणुबाट स्वतन्त्र रूपमा सर्ने प्रक्रियालाई जनाउँछ।\n- डिमाहा गुणले दुई फरक गुणहरूको मिश्रणबाट बन्ने मध्यवर्ती गुणलाई बुझाउँछ।\nनोट: प्रबलताको नियमले प्रबल गुणले लुप्त गुणलाई ढाक्ने कुरा बताउँछ।', 'nepali'),
      (v_set_id, 4, E'मधुवानी कुन चित्रकलासँग सम्बन्धित रहेको छ?', E'थाङ्का चित्र', E'पिछवाई चित्र', E'ग्रन्थ चित्र', E'मिथिला चित्र', 'D', E'**मधुवानी चित्रकला मिथिला चित्रकलासँग सम्बन्धित छ।**\n- थाङ्का चित्र खसो कपडामा बनाइने पौभा चित्रकला हो।\n- पिछवाई चित्रकला भगवान कृष्णको जीवनीसँग सम्बन्धित छ।\n- ग्रन्थ चित्र बौद्ध धर्ममा प्रचलित छ र पुस्तकको पाना वा गाथामा लेखिएको चित्र हो।\nनोट: मिथिला चित्रकारलाई मधुवानी चित्रकार पनि भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'सिंहदरबार विद्रोह नेपालमा कहिले भयो?', E'२००३ कार्तिक २५', E'२००८ कार्तिक २५', E'२००९ कार्तिक २५', E'२०१० कार्तिक २५', 'B', E'**२००८ कार्तिक २५ गते।**\n- सिंहदरबार विद्रोहको नेतृत्व डा. के. आई सिंहले गरेका थिए।\nनोट: सिंहदरबार आगलागी २०३० असार २५ गते कीर्तिनिधि बिष्टको पालामा भएको थियो।', 'nepali'),
      (v_set_id, 6, E'प्रथम विश्व युद्धमा नेपाली सेनाको नेतृत्व कसले गरेका थिए?', E'देव शमशेर', E'वीर शमशेर', E'चन्द्र शमशेर', E'बबर शमशेर', 'D', E'**प्रथम विश्व युद्धमा नेपाली सेनाको नेतृत्व बबर शमशेरले गरेका थिए।**\n- चन्द्र शमशेर प्रथम विश्व युद्धको समयमा नेपालका तत्कालीन प्रधानमन्त्री थिए।\n- दोस्रो विश्व युद्धमा नेपाली सेनाको नेतृत्व बहादुर शमशेरले गरेका थिए।\nनोट: प्रथम विश्व युद्धमा १९१४-१९४४ जना नेपाली सेना सहभागी भएका थिए।', 'nepali'),
      (v_set_id, 7, E'नेपालको भूगोलमा भोकारी दह कुन जिल्लामा पर्दछ?', E'सिराहा', E'सप्तरी', E'सर्लाही', E'धनुषा', 'B', E'**भोकारी दह सप्तरी जिल्लामा पर्दछ।**\n- सिराहा जिल्लामा पतर पोखरी रहेको छ।\n- सर्लाही जिल्लामा भरत ताल पर्दछ।\n- धनुषा जिल्लामा गढगासागर, रामसागर र रत्नसागर तालहरू छन्।\nनोट: सप्तरी जिल्लामा ठाकुरबाबा दह पनि अवस्थित छ।', 'nepali'),
      (v_set_id, 8, E'अन्टार्कटिका महादेशको सबैभन्दा ठूलो ताल कुन हो?', E'आइरा ताल', E'भिक्टोरिया ताल', E'बैकाल ताल', E'भोस्टोक ताल', 'D', E'**अन्टार्कटिका महादेशको सबैभन्दा ठूलो ताल भोस्टोक ताल हो।**\n- आइरा ताल अष्ट्रेलियाको सबैभन्दा ठूलो ताल हो।\n- भिक्टोरिया ताल अफ्रिका महादेशको सबैभन्दा ठूलो ताल हो।\n- बैकाल ताल एसियाको सबैभन्दा गहिरो ताल हो।\nनोट: युरोपको सबैभन्दा ठूलो ताल लाडोगा ताल (रुस) हो भने उत्तर अमेरिकाको सुपिरियर ताल सबैभन्दा ठूलो हो।', 'nepali'),
      (v_set_id, 9, E'पृथ्वी नारायण शाहको आमा कौशल्यावती कहाँको राजकुमारी थिइन्?', E'पाल्पा', E'नुवाकोट', E'पर्वत', E'कास्की', 'A', E'**पृथ्वी नारायण शाहकी आमा कौशल्यावती पाल्पाकी राजकुमारी थिइन्।**\n- नुवाकोट पृथ्वी नारायण शाहले विजय गरेका महत्वपूर्ण राज्यहरू मध्ये एक थियो।\n- पर्वत र कास्की पनि नेपाल एकीकरण अभियानका क्रममा महत्वपूर्ण राज्यहरू थिए।\nनोट: पृथ्वी नारायण शाहका बुबा नरभूपाल शाह हुन्।', 'nepali'),
      (v_set_id, 10, E'इस्लाम धर्ममा प्रचलित केटो शिशुको सानै उमेरमा यौनअंग काट्ने कार्यलाई के भनिन्छ?', E'मदरसा', E'खतना', E'आयुवक्र', E'आदम', 'B', E'**इस्लाम धर्ममा केटो शिशुको सानै उमेरमा यौनअंग काट्ने कार्यलाई खतना भनिन्छ।**\n- मदरसा मुसलमानहरूको धार्मिक र शैक्षिक संस्था हो।\n- आयुवक्र इस्लाम धर्ममा पहिलो खलिफालाई बुझाउँछ।\n- आदम र हौवा अल्लाहका प्रथम मानिसहरू हुन्।', 'nepali'),
      (v_set_id, 11, E'पृथ्वीलाई आफ्नो अक्षमा घुम्न लाग्ने समय कुन विकल्प सहि छ?', E'२३ घ.५ मि.४.०९ से.', E'२४ घ.५ मि.४.०९ से.', E'२३ घ.५६ मि.४.०९ से.', E'२४ घ.५६ मि.४.०९ से.', 'C', E'पृथ्वीलाई आफ्नो अक्षमा एक परिक्रमा पूरा गर्न **२३ घण्टा ५६ मिनेट ४.०९ सेकेन्ड** लाग्छ। यो पृथ्वीको परिभ्रमण गति हो, जुन पश्चिमबाट पूर्व (घडीको विपरीत दिशामा) हुन्छ।\nनोट: पृथ्वीको अण्डाकार मार्गमा सूर्यको वरिपरि घुम्ने गतिलाई परिक्रमण गति भनिन्छ, जुन ऋतु परिवर्तनको कारण हो।', 'nepali'),
      (v_set_id, 12, E'नेपालको संविधानको कुन धारामा राष्ट्रपति र उपराष्ट्रपति फरक फरक लिंग वा समुदायको हुने सम्बन्धि व्यवस्था गरेको छ?', E'धारा ७०', E'धारा ७१', E'धारा ७२', E'धारा ७३', 'A', E'**नेपालको संविधानको धारा ७० मा राष्ट्रपति र उपराष्ट्रपति फरक फरक लिंग वा समुदायको हुनुपर्ने व्यवस्था गरिएको छ।**\n- धारा ७१ अनुसार राष्ट्रपतिले प्रधान न्यायाधीश समक्ष र उपराष्ट्रपतिले राष्ट्रपति समक्ष पद तथा गोपनीयताको शपथ लिनुपर्नेछ।', 'nepali'),
      (v_set_id, 13, E'२०८२ सालबाट कुन दिन राष्ट्रिय चलचित्र दिवस मनाउने मन्त्रिपरिषदको निर्णय गरेको छ?', E'असोज १', E'असोज १३', E'असोज १५', E'असोज २५', 'C', E'२०८२ असार १३ को मन्त्रिपरिषदको निर्णय अनुसार नेपालमा निर्माण भएको पहिलो चलचित्र ''आमा'' को प्रदर्शन मितिलाई ध्यानमा राखी २०८२ सालबाट राष्ट्रिय चलचित्र दिवस **असोज १५** गते मनाउने निर्णय गरिएको छ।\nनोट: यसअघि चलचित्र दिवस असोज १ गते मनाइँदै आएको थियो।', 'nepali'),
      (v_set_id, 14, E'मुलुककै पहिलो लाइओभर ग्वार्कोको लाइओभरको उद्घाटन कहिले भएको हो?', E'२०८२ असार ३', E'२०८२ असार ४', E'२०८२ असार ६', E'२०८२ असार ८', 'C', E'ग्वार्को लाइओभरको उद्घाटन **२०८२ असार ६ गते** भएको थियो। यसको निर्माण कार्य २०७८ फागुन १२ गते २ वर्षमा सक्ने गरी सम्झौता भई अघि बढेको थियो।', 'nepali'),
      (v_set_id, 15, E'''Zero Net Aid'' refers to:', E'A situation where all foreign aid is doubled', E'A situation where does not require foreign aid', E'A situation where only military aid is accepted', E'A situation where aid is given but not recorded', 'B', E'''जिरो नेट एड'' भन्नाले अर्थव्यवस्था सबल भई **विदेशी सहयोग नचाहिने अवस्था**लाई बुझिन्छ।', 'nepali'),
      (v_set_id, 16, E'महाराजाधिराज परम भट्टारक पदवी धारण गर्ने प्रथम लिच्छवि राजा को हुन्?', E'उदयदेव', E'अंशुवर्मा', E'मानदेव', E'नरेन्द्रदेव', 'B', E'**अंशुवर्मा लिच्छवि कालमा सर्वप्रथम महाराजाधिराजको पदवी धारण गर्ने राजा हुन्।**\n- मानदेव लिच्छवि वंशका एक शक्तिशाली राजा थिए जसले नेपालमा पहिलो पटक मुद्रा प्रचलनमा ल्याएका थिए।\n- उदयदेव मानदेवका नाति थिए, जसलाई नरेन्द्रदेवले पदच्युत गरेका थिए।\n- नरेन्द्रदेवले सर्वप्रथम महाराजाधिराज परम भट्टारक पदवी धारण गरेका थिए।', 'nepali'),
      (v_set_id, 17, E'ग्रन्थकुट शैलीलाई कुन शैलीको आधुनिक शैलीका रुपमा चिनिन्छ?', E'स्तूप शैली', E'प्यागोडा शैली', E'शिखर शैली', E'युरोपेली शैली', 'C', E'**ग्रन्थकुट शैलीलाई शिखर शैलीको आधुनिक रूपका रूपमा चिनिन्छ।**\n- रानी पोखरीको बीचमा रहेको बाल गोपालेश्वर मन्दिर ग्रन्थकुट शैलीमा निर्माण भएको छ।\n- स्तूप शैली बौद्ध धर्मसँग सम्बन्धित वास्तुकला हो।\n- प्यागोडा शैली नेपालको मौलिक वास्तुकला शैली हो।', 'nepali'),
      (v_set_id, 18, E'हड्डीहरुको अध्ययन गर्ने विज्ञानको शास्त्रलाई के भनिन्छ?', E'एग्रोलोजी', E'इकोलोजी', E'एनाटोमी', E'अस्टियोलोजी', 'D', E'**हड्डीहरूको अध्ययन गर्ने विज्ञानको शास्त्रलाई अस्टियोलोजी भनिन्छ।**\n- एनाटोमी मानव शरीरको संरचनाको अध्ययन हो।\n- इकोलोजी परिस्थितिको अध्ययन हो।\n- एग्रोलोजी भूमि (माटो) को अध्ययन हो।', 'nepali'),
      (v_set_id, 19, E'नेपालमा उत्पादित विद्युत पहिलोपल्ट बंगलादेश कहिले निर्यात गरियो ?', E'२०८१ कात्तिक ३०', E'२०८१ कात्तिक १९', E'२०८१ असोज १७', E'२०८१ असोज २०', 'A', E'नेपालले पहिलोपटक बंगलादेशमा **२०८१ कात्तिक ३०** गतेदेखि विद्युत निर्यात सुरु गरेको हो। नेपाल, भारत र बंगलादेशबीच २०८१ असोज १७ मा भएको त्रिपक्षीय सम्झौता अनुसार नेपालले ४० मेगावाट विद्युत ५ वर्षका लागि बंगलादेशलाई बिक्री गर्नेछ।\nनोट: यो सम्झौताबाट नेपाललाई प्रतिवर्ष करिब १२ लाख अमेरिकी डलर आम्दानी हुने अनुमान छ।', 'nepali'),
      (v_set_id, 20, E'देहाएका मध्ये कुन रोग जीवाणु समूह (Bacterial Group) अन्तर्गत पर्ने रोग हैन । पहिचान गर्नुहोस्', E'लहरे खोकी', E'दादुरा', E'हैजा', E'निमोनिया', 'B', E'**दादुरा (Measles) विषाणु (Virus) समूह अन्तर्गत पर्ने रोग हो, जीवाणु समूह अन्तर्गत होइन।**\n- लहरे खोकी जीवाणु (Bacteria) बाट लाग्ने रोग हो।\n- हैजा जीवाणु (Bacteria) बाट लाग्ने रोग हो।\n- निमोनिया पनि जीवाणु (Bacteria) बाट लाग्ने रोग हो।\nनोट: जीवाणुबाट लाग्ने अन्य प्रमुख रोगहरूमा क्षयरोग, धनुष्टंकार, र कुष्ठरोग पर्दछन् भने विषाणुबाट लाग्नेमा रेबिज, हेपाटाइटिस र इन्फ्लुएन्जा पर्दछन्।', 'nepali'),
      (v_set_id, 21, E'भारतले संयुक्त राष्ट्रसंघको बजेटमा कति प्रतिशत योगदान गरेको छ ?', E'१.०१० प्रतिशत', E'१.११४ प्रतिशत', E'१.०४४ प्रतिशत', E'१.०४१ प्रतिशत', 'C', E'भारतले संयुक्त राष्ट्रसंघको नियमित बजेटमा **१.०४४ प्रतिशत** योगदान गरेको छ। सार्क राष्ट्रहरूमध्ये यो सबैभन्दा धेरै योगदान हो।\nनोट: संयुक्त राष्ट्रसंघको बजेटमा सबैभन्दा धेरै योगदान गर्ने मुलुक अमेरिका (२२ प्रतिशत) हो भने नेपालको योगदान ०.०१० प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 22, E'Inner Six मा देहाएको मध्ये कुन मुलुक पर्दैन ?', E'पोल्यान्ड', E'इटाली', E'बेल्जियम', E'लक्जमवर्ग', 'A', E'**पोल्यान्ड युरोपेली संघ (EU) को संस्थापक सदस्य अर्थात् ''Inner Six'' मा पर्दैन।**\n- इटाली EU को संस्थापक सदस्य हो।\n- बेल्जियम EU को संस्थापक सदस्य हो।\n- लक्जमवर्ग EU को संस्थापक सदस्य हो।\nनोट: EU का संस्थापक ६ मुलुकहरू (Inner Six) बेल्जियम, फ्रान्स, जर्मनी, इटाली, लक्जमवर्ग र नेदरल्यान्ड्स हुन्।', 'nepali'),
      (v_set_id, 23, E'दुखाई मापन गर्ने यन्त्र देहाएका मध्ये कुन हो ?', E'अल्टीमिटर', E'एल्गोमिटर', E'ब्रेथलाइजर', E'पोलिग्राफ', 'B', E'**दुखाई मापन गर्ने यन्त्रलाई एल्गोमिटर (Algometer) भनिन्छ।**\n- अल्टीमिटरले उचाइ मापन गर्दछ।\n- ब्रेथलाइजरले चालकले मादक पदार्थ सेवन गरे/नगरेको जाँच्न प्रयोग गरिन्छ।\n- पोलिग्राफ (Lie Detector) झुट बोलेको पत्ता लगाउन प्रयोग हुने यन्त्र हो।', 'nepali'),
      (v_set_id, 24, E'यमग्रहको खोज गर्ने वैज्ञानिक को हुन् ?', E'निकोलास कोपर्निकस', E'क्लाउड टम्बाग', E'जोहन गाल', E'विलियम हर्सेल', 'B', E'**यमग्रहको खोज खगोलविद् क्लाउड टम्बागले गरेका थिए।**\n- निकोलास कोपर्निकसलाई ब्रह्माण्डको खोज गर्ने वैज्ञानिक (सौर्यमण्डलका पिता) मानिन्छ।\n- जोहन गालले वरुण ग्रह पत्ता लगाएका हुन्।\n- विलियम हर्सेलले अरुण ग्रह पत्ता लगाएका हुन्।', 'nepali'),
      (v_set_id, 25, E'सर्वप्रथम दिगो विकास शब्दको प्रयोग कहिले गरियो ?', E'सन् १९८७', E'सन् १९८३', E'सन् १९७२', E'सन् २०१५', 'A', E'सर्वप्रथम दिगो विकास शब्दको प्रयोग **सन् १९८७ मा ब्रुटल्यान्ड प्रतिवेदनमा** गरिएको थियो।\nनोट: ब्रुटल्यान्ड आयोगको गठन सन् १९८३ मा भएको थियो भने स्वीडेनको स्टकहोम सम्मेलन सन् १९७२ जुन ५ देखि १६ सम्म चलेको थियो।', 'nepali'),
      (v_set_id, 26, E'पृथ्वीनारायण शाहले भाई शुर प्रताप शाहका आँखा फुटेको घटना कति औं कीर्तिपुर आक्रमणसँग सम्बन्धित रहेको छ ?', E'दोस्रो', E'तेस्रो', E'पहिलो', E'चौथो', 'A', E'पृथ्वीनारायण शाहले भाई शुर प्रताप शाहका आँखा फुटेको घटना **दोस्रो कीर्तिपुर आक्रमणसँग** सम्बन्धित छ।\n- पहिलो कीर्तिपुर आक्रमण वि.सं. १७९४ मा भएको थियो र यसमा काजी कालु पाँडेको निधन भएको थियो।\n- दोस्रो कीर्तिपुर आक्रमण १८४१ असोज ४ मा भएको थियो र यसमा शुर प्रताप शाहका आँखा फुटेका थिए।\n- तेस्रो कीर्तिपुर आक्रमण १८४२ चैत ३ मा भएको थियो र यसमा पृथ्वीनारायण शाहले विजय हासिल गरेका थिए।', 'nepali'),
      (v_set_id, 27, E'२०७८ सालको जनगणना अनुसार भोजपुरी भाषा बोल्ने जनसंख्या कति प्रतिशत रहेको छ ?', E'६.२४ प्रतिशत', E'४.८८ प्रतिशत', E'५.८८ प्रतिशत', E'११.०५ प्रतिशत', 'A', E'२०७८ सालको जनगणना अनुसार भोजपुरी भाषा बोल्ने जनसंख्या **६.२४ प्रतिशत** रहेको छ।\n- नेपाली भाषा बोल्ने जनसंख्या ४४.६४%, मैथिली ११.०५%, थारु ५.८८% र तामाङ ४.८८% रहेको छ।', 'nepali'),
      (v_set_id, 28, E'माथिल्लो सगरमाथा भनेर चिनिने तीन जिल्लामा देहाएको कुन जिल्ला पर्दैन ?', E'ओखलढुङ्गा', E'सोलुखुम्बु', E'सङ्खुवासभा', E'खोटाङ', 'C', E'**सङ्खुवासभा जिल्ला माथिल्लो सगरमाथा क्षेत्रमा पर्दैन।**\n- माथिल्लो सगरमाथा भनेर सोलुखुम्बु, ओखलढुङ्गा र खोटाङ जिल्लालाई चिनिन्छ।', 'nepali'),
      (v_set_id, 29, E'नेपाल प्रिमियर लिग (NPL) को पहिलो संस्करण कहिले सुरु भएको हो ?', E'३० नोभेम्बर २०२४', E'२८ नोभेम्बर २०२४', E'१ डिसेम्बर २०२४', E'५ डिसेम्बर २०२४', 'A', E'नेपाल प्रिमियर लिग (NPL) को पहिलो संस्करण **३० नोभेम्बर २०२४** मा सुरु भएको थियो। यो प्रतियोगिता ३० नोभेम्बरदेखि २१ डिसेम्बर २०२४ (२०८१ मंसिर १५ देखि पुस ६) सम्म सञ्चालन भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/२३', 29;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_25.csv  →  आसमान दैनिक GK — २०८२/०८/२५  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/२५'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/२५';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/२५', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'षडानन्द राष्ट्रिय पुरस्कार २०८२ को उपाधि कसलाई प्रदान गरिएको छ ?', E'तिलविक्रम नेम्वाङ', E'कुमार नगरकोटी', E'काशीनाथ तमोट', E'वसन्त पन्त', 'A', E'**षडानन्द राष्ट्रिय पुरस्कार २०८२ तिलविक्रम नेम्वाङ (बैरागी काइँला) लाई प्रदान गरिएको थियो।**\n- कुमार नगरकोटीलाई महानन्द साहित्य सम्मान-२०८५ प्रदान गरिएको थियो।\n- काशीनाथ तमोटले षडानन्द क्षेत्रीय पुरस्कार प्राप्त गरेका थिए।\n- डा. वसन्त पन्तलाई नेपाल विज्ञान तथा प्रविधि प्रज्ञा-प्रतिष्ठानले कुलपति राष्ट्रिय प्रवर्तन पुरस्कार २०८२ प्रदान गरेको थियो।\nनोट: षडानन्द राष्ट्रिय पुरस्कारको राशि एक लाख रुपैयाँ हो।', 'nepali'),
      (v_set_id, 2, E'हालसालै रुसका राष्ट्रपति भ्लादिमिर पुटिनद्वारा भारतको औपचारिक भ्रमणका लागि कहिले भारत प्रस्थान गरेका हुन् ?', E'२०२५ डिसेम्बर ३', E'२०२५ डिसेम्बर ४', E'२०२५ डिसेम्बर ५', E'२०२५ डिसेम्बर ६', 'B', E'**सन् २०२५ डिसेम्बर ४ मा रुसका राष्ट्रपति भ्लादिमिर पुटिनले भारतको औपचारिक भ्रमणका लागि प्रस्थान गरेका थिए।**\n- यो भ्रमण डिसेम्बर ४-५ सम्म चलेको थियो र यस क्रममा दीर्घकालीन आर्थिक रणनीति अन्तर्गत स्ट्र्याटेजिक एरियाज अफ इकोनोमिक कोअपरेसन नामक कार्यक्रम सार्वजनिक गरिएको थियो।', 'nepali'),
      (v_set_id, 3, E'२०८२ मा सञ्चालित बाघ गणना कति औं बाघ गणना हो ?', E'चौंथो', E'पाँचौं', E'छैठौं', E'सातौं', 'B', E'वि.सं. २०८२ मा सञ्चालित बाघ गणना **पाँचौं** बाघ गणना हो। यो गणना २०८२ पुस १ देखि फागुनसम्म ३ महिना सञ्चालन हुनेछ।\nनोट: यसअघिको चौंथो बाघ गणना अनुसार नेपालमा ३५५ वटा बाघ रहेका थिए।', 'nepali'),
      (v_set_id, 4, E'राष्ट्रिय बालसाहित्य सम्मेलन २०८२ कुन जिल्लामा सञ्चालन भएको छ ?', E'रोल्पा', E'सल्यान', E'दाङ', E'दोलखा', 'A', E'नेपाल बालसाहित्य समाजको आयोजनामा ३० औं राष्ट्रिय बालसाहित्य सम्मेलन २०८२ **रोल्पा** जिल्लाको लिबाङमा सम्पन्न भएको हो। यो सम्मेलन २०८२ मंसिर १८ र १९ गते आयोजना गरिएको थियो।', 'nepali'),
      (v_set_id, 5, E'अन्तर्दृष्टि नमुना शिक्षक पुरस्कार २०८२ कुन नेपाली शिक्षकलाई प्रदान गरिएको छ ?', E'कुलबहादुर खत्री', E'क्षेत्रबहादुर बुढाथोकी', E'ज्ञानबहादुर थापा', E'मणिबहादुर गुरुङ', 'B', E'अन्तर्दृष्टि नमुना शिक्षक पुरस्कार २०८२ काठमाडौँको ल्याबोरेटरी माध्यमिक विद्यालयमा अध्यापनरत शिक्षक **क्षेत्रबहादुर बुढाथोकी**लाई प्रदान गरिएको छ। यो पुरस्कार ३४ औं अन्तर्राष्ट्रिय अपांगता दिवस, डिसेम्बर ३, २०२५ को अवसरमा प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 6, E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ को फाइनल खेल कुन कुन टिम बिच हुने भएको छ ?', E'लुम्बिनी र सुदुर प.', E'काठमाडौं र सुदुर प.', E'विराटनगर र सुदुर प.', E'जनकपुर र सुदुर प.', 'A', E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ को फाइनल खेल **लुम्बिनी र सुदुर पश्चिम** बिच भएको थियो।\nनोट: पहिलो संस्करण, २०२४ को फाइनलमा जनकपुर बोल्ट्स र सुदुर प. रोयल्स पुगेका थिए।', 'nepali'),
      (v_set_id, 7, E'काठमाडौं विश्वविद्यालयद्वारा आयोजित २०८२ को कति औं दीक्षान्त कार्यक्रम हो ?', E'२८ औं', E'२९ औं', E'३० औं', E'३१ औं', 'D', E'काठमाडौं विश्वविद्यालयद्वारा २०८२ मंसिर २४ गते आयोजित दीक्षान्त कार्यक्रम **३१ औं** संस्करणको हो। यस दीक्षान्त कार्यक्रमको पहिलो चरणमा २,२०९ जना विद्यार्थी दीक्षित भएका थिए।', 'nepali'),
      (v_set_id, 8, E'हालसालै २०२४ मा कुन मुलुकले १६ वर्षभन्दा कम उमेरका प्रयोगकर्तालाई सामाजिक सञ्जालमा पहुँच रोक्न नियम कार्यान्वयन गरेको छ ?', E'अष्ट्रेलिया', E'अमेरिका', E'चीन', E'जापान', 'A', E'**अष्ट्रेलियाले** सन् २०२४ मा १६ वर्षभन्दा कम उमेरका प्रयोगकर्तालाई सामाजिक सञ्जालमा पहुँच रोक्न नियम कार्यान्वयन गरेको छ।\n- यो नियम २०२४ डिसेम्बर १० बाट लागू भएको हो, जुन २०२४ को नोभेम्बरमा पारित अनलाइन सेफ्टी अमेन्डमेन्ट (सोसल मिडिया मिनिमम एज) ऐन अन्तर्गत पर्दछ।', 'nepali'),
      (v_set_id, 9, E'हालसम्म नेपाली भाषाको अतिरिक्त अन्य भाषालाई सरकारी कामकाजको भाषा तोक्ने प्रदेशहरु कुन कुन हुन् ?', E'बागमती र मधेस', E'बागमती र गण्डकी', E'बागमती र कर्णाली', E'बागमती र कोशी', 'B', E'नेपाली भाषाको अतिरिक्त सरकारी कामकाजको भाषा तोक्ने प्रदेशहरू **बागमती र गण्डकी** हुन्। बागमती प्रदेशले २०७९ बैशाख २४ मा नेपाल भाषा र तामाङ भाषालाई सरकारी कामकाजको भाषा तोकेको थियो भने गण्डकी प्रदेशले २०८२ असार २४ मा मगर र गुरुङ भाषालाई सरकारी कामकाजको भाषा तोकेको छ।\nनोट: नेपालको संविधानको धारा ७ को उपधारा (२) मा प्रदेशले नेपाली भाषाको अतिरिक्त बहुसंख्यक जनताले बोल्ने अन्य राष्ट्र भाषाहरूलाई सरकारी कामकाजको भाषा निर्धारण गर्न सक्ने व्यवस्था छ।', 'nepali'),
      (v_set_id, 10, E'सर्वोच्च अदालतले हितेन्द्र देव शाक्यलाई विद्युत प्राधिकरणको कार्यकारी निर्देशकमा फर्काउने गरी परमादेश जारी कहिले गरेको छ ?', E'२०८२ मंसिर २०', E'२०८२ मंसिर २१', E'२०८२ मंसिर २२', E'२०८२ मंसिर २३', 'C', E'सर्वोच्च अदालतले हितेन्द्र देव शाक्यलाई विद्युत प्राधिकरणको कार्यकारी निर्देशकमा फर्काउने गरी परमादेश **२०८२ मंसिर २२** मा जारी गरेको थियो।\n- यसअघि २०८२ असोज ५ गते बसेको मन्त्री परिषद बैठकले हितेन्द्र शाक्यलाई हटाएर मनोज सिलवाललाई नियुक्त गर्ने निर्णय गरेको थियो।', 'nepali'),
      (v_set_id, 11, E'पहिलो "फिफा शान्ति पुरस्कार-२०२४" बाट सम्मानित भएका व्यक्ति को हुन् ?', E'भ्लादिमिर जेलेन्स्की', E'लियोनल मेस्सी', E'एलन मस्क', E'डोनाल्ड ट्रम्प', 'D', E'पहिलो "फिफा शान्ति पुरस्कार-२०२४" बाट **डोनाल्ड ट्रम्प** सम्मानित भएका हुन्।\n- उनलाई २०२४ डिसेम्बर ५ मा फिफा विश्वकप २०२६ को समूह चरणको खेल तालिका सार्वजनिक समारोहमा यो पुरस्कार प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 12, E'विश्व माटो दिवस २०२४ को नारा के रहेको छ ?', E'Healthy Soils for Healthy Cities', E'Healthy Soils for Healthy Lifes', E'Healthy Soils for Caring for soils', E'Healthy Soils for Environment', 'A', E'विश्व माटो दिवस २०२४ को नारा **"Healthy Soils for Healthy Cities"** रहेको छ।\n- संयुक्त राष्ट्रसंघको ६८ औं महासभाको निर्णयले सन् २०१३ डिसेम्बर ५ देखि विश्व माटो दिवस मनाउन सुरु गरिएको हो।', 'nepali'),
      (v_set_id, 13, E'Bank of the year-2025 को अवार्डबाट सम्मानित भएको नेपाली बैंक कुन हो ?', E'नबिन बैंक लि.', E'ग्लोबल आइएमई बैंक', E'कुमारी बैंक लि.', E'सिटिजन्स बैंक इन्टरनेसनल', 'D', E'**लन्डनस्थित द फाइनान्सियल टाइम्सले सिटिजन्स बैंक इन्टरनेसनललाई बैंक अफ द इयर २०२५ को अवार्ड प्रदान गरेको थियो।**\n- ग्लोबल आइएमई बैंकलाई सन् २०२५ को ''बेस्ट बैंक अवार्ड'' बाट सम्मानित गरिएको थियो।\nनोट: यो अवार्ड बैंकको वित्तीय प्रदर्शन, ग्राहक सेवा, र नवीनताका आधारमा प्रदान गरिन्छ।', 'nepali'),
      (v_set_id, 14, E'नेपाल विज्ञान तथा प्रविधि-प्रतिष्ठान (नास्ट) ले नेपालको कुन स्थानीय तहलाई भुवनेश्वर प्रविधि पुरस्कार-२०८२ बाट सम्मान गर्ने भएको छ ?', E'दिक्तेल रुपाकोट मझुवागढी न.पा.', E'सिन्धुली माझिमिगाढी न.पा.', E'कागेश्वरी मनोहारा न.पा.', E'दोधारा चाँदनी न.पा.', 'A', E'**नेपाल विज्ञान तथा प्रविधि-प्रतिष्ठान (नास्ट) ले दिक्तेल रुपाकोट मझुवागढी नगरपालिकालाई भुवनेश्वर प्रविधि पुरस्कार-२०८२ बाट सम्मान गर्ने भएको छ।**\n- दिक्तेल रुपाकोट मझुवागढी नगरपालिका खोटाङ जिल्लाको सदरमुकाममा अवस्थित छ।\nनोट: यो पुरस्कार स्थानीय तहमा प्रविधिको प्रयोग र विकासमा योगदान पुर्‍याएबापत प्रदान गरिन्छ।', 'nepali'),
      (v_set_id, 15, E'एसियाली विकास बैंक (एडीबी) ले सार्वजनिक गरेको (एसियन वाटर डेभलपमेन्ट आउटलुक) २०२५ अनुसार कति प्रतिशत घरधुरीमा मात्र प्रदूषणरहित वा सुरक्षित पानीको पहुँच पुगेको छ ?', E'१० प्रतिशत', E'१४ प्रतिशत', E'१८ प्रतिशत', E'२२ प्रतिशत', 'B', E'**एसियाली विकास बैंक (एडीबी) को एसियन वाटर डेभलपमेन्ट आउटलुक २०२५ अनुसार नेपालको १४ प्रतिशत घरधुरीमा मात्र प्रदूषणरहित वा सुरक्षित पानीको पहुँच पुगेको छ।**\n- नेपालमा पानीका स्रोत प्रदूषण हुनु मुख्य चुनौतीका रूपमा देखिएको छ।\nनोट: नेपालले उपलब्ध पानीको ८ प्रतिशत हाराहारी मात्र आर्थिक उपार्जनमा प्रयोग गरिरहेको छ।', 'nepali'),
      (v_set_id, 16, E'स्थापनाकालीन समयमा राष्ट्रसंघ कति सदस्य थिए?', E'३२ देश', E'४२ देश', E'६२ देश', E'५१ देश', 'B', E'राष्ट्रसंघको स्थापनाकालीन समयमा **४२ देश** सदस्य थिए।\n- राष्ट्र संघको स्थापना १० जनवरी, १९२० मा भएको थियो।\n- यसको विघटन २० अप्रिल, १९४६ मा भयो।\nनोट: राष्ट्रसंघको विघटन हुँदा ३३ देश सदस्य थिए भने बीचमा ६२ देशसम्म पुगेका थिए। संयुक्त राष्ट्र संघका संस्थापक सदस्य मुलुक ५१ हुन्।', 'nepali'),
      (v_set_id, 17, E'पञ्चधातु र पञ्चरत्न दुवै समूहमा पर्ने धातु कुन हो ?', E'चाँदी', E'तामा', E'हिरा', E'सुन', 'D', E'पञ्चधातु र पञ्चरत्न दुवै समूहमा पर्ने धातु **सुन** हो।\n- पञ्चधातुमा चाँदी, तामा, फलाम, पित्तल र सुन पर्दछन्।\n- पञ्चरत्नमा हिरा, मोती, मुगा, पधरागमणि र सुन पर्दछन्।', 'nepali'),
      (v_set_id, 18, E'३५ औं नेटो सम्मेलन, २०२५ कहाँ सम्पन्न भएको हो ?', E'नेदरल्यान्ड्स', E'अमेरिका', E'स्विडेन', E'बेलायत', 'A', E'सन् २०२५ जुन २४-२६ मा सम्पन्न भएको ३५ औं नेटो सम्मेलन **नेदरल्यान्ड्सको हेगमा** भएको थियो।\nनोट: ३४ औं नेटो सम्मेलन सन् २०२४ जुलाई ९-११ मा अमेरिकामा सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 19, E'ल्याण्ड अफ आइरनको उपनामले कुन सार्क मुलुकलाई चिनिन्छ ?', E'भारत', E'श्रीलंका', E'अफगानिस्तान', E'पाकिस्तान', 'C', E'**अफगानिस्तानलाई ''ल्याण्ड अफ आइरन'' उपनामले चिनिन्छ।**\n- भारतलाई ''पूर्वको भेनिस'' भनिन्छ।\n- श्रीलंकालाई ''हिन्द महासागरका मोती'' वा ''पूर्वको मोती'' भनिन्छ।\n- पाकिस्तानलाई ''ल्याण्ड अफ गोल्डेन फाइबर'' उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 20, E'निजी क्षेत्रको सबैभन्दा ठूलो जलविद्युत आयोजना सोलुखोलाको विद्युत उत्पादन क्षमता कति रहेको छ ?', E'९३ मेगावाट', E'६० मेगावाट', E'८६ मेगावाट', E'७४ मेगावाट', 'C', E'**८६ मेगावाट।**\n- निजी क्षेत्रको सबैभन्दा ठूलो जलविद्युत आयोजना सोलुखोला (दुधकोशी) सोलुखुम्बु जिल्लामा अवस्थित छ र यसको उद्घाटन २०७९ फागुन २३ गते पुष्प कमल दाहाल प्रचण्डले गरेका थिए।\nनोट: यो आयोजना निर्माण हुनुअघि खिम्ती (६० मेगावाट) निजी क्षेत्रको सबैभन्दा ठूलो जलविद्युत आयोजना थियो जुन दोलखा जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 21, E'''जीवहरु बाँच्नका लागि संघर्ष गर्छन्'' माथिको कथन कुन सिद्धान्तसँग सम्बन्धित रहेको छ ?', E'मेण्डल', E'लेमार्क', E'डार्बिन', E'डिभ्रिज', 'C', E'**''जीवहरु बाँच्नका लागि संघर्ष गर्छन्'' भन्ने कथन डार्बिनको सिद्धान्तसँग सम्बन्धित छ।** डार्बिनको सिद्धान्तका मुख्य बुँदाहरूमा अत्यधिक प्रजनन, बाँच्नका लागि संघर्ष, परिवृत्ति र वंशज, प्राकृतिक छनौट, सक्षमहरु मात्र बाँच्ने र नयाँ जीवको उत्पत्ति पर्दछन्।', 'nepali'),
      (v_set_id, 22, E'भिमसेन थापाका पालामा नेपालको भौगोलिक विभाजन कति जिल्लामा रहेको थियो ?', E'३९ जिल्ला', E'३५ जिल्ला', E'३७ जिल्ला', E'६९ जिल्ला', 'A', E'**३९ जिल्ला।**\n- भीमसेन थापाको पालामा नेपालको भौगोलिक विभाजन ३९ जिल्लामा रहेको थियो।\n- जंगबहादुर राणाको पालामा ६९ एकाइ र वीर शमशेरको पालामा ३५ जिल्ला (पहाडी २३, तराई १२) मा विभाजन गरिएको थियो।', 'nepali'),
      (v_set_id, 23, E'नेपालको आठ हजार मिटर भन्दा अग्ला ८ वटा हिमाल मध्ये सबैभन्दा पश्चिममा रहेको हिमाल कुन हो ?', E'अन्नपूर्ण', E'धौलागिरी', E'मनास्लु', E'कन्चनजंघा', 'B', E'**नेपालको आठ हजार मिटर भन्दा अग्ला हिमालहरू मध्ये सबैभन्दा पश्चिममा धौलागिरी हिमाल रहेको छ।**\n- पूर्वबाट पश्चिमको क्रममा कन्चनजंघा, मकालु, ल्होत्से, सगरमाथा, चोयु, मनास्लु, अन्नपूर्ण र धौलागिरी पर्दछन्।', 'nepali'),
      (v_set_id, 24, E'अन्तिम राणा प्रधानमन्त्री मोहन समसेर कसका छोरा हुन् ?', E'भीम समसेर', E'पद्म समसेर', E'जुद्ध समसेर', E'चन्द्र समसेर', 'D', E'**अन्तिम राणा प्रधानमन्त्री मोहन समसेर चन्द्र समसेरका छोरा हुन्।**\n- भीम समसेर धीर समसेरका छोरा र पद्म समसेरका बुबा हुन्।\n- पद्म समसेर भीम समसेरका छोरा र तेस्रो पुस्ताका पहिलो राणा प्रधानमन्त्री हुन्।\n- जुद्ध समसेर धीर समसेरका छोरा र दोस्रो पुस्ताका अन्तिम राणा प्रधानमन्त्री हुन्।', 'nepali'),
      (v_set_id, 25, E'EU का कति राष्ट्रमा सन् २००२ को जनवरीदेखि एकल युरो मुद्रा प्रचलनमा आएको हो?', E'१२ मुलुक', E'१३ मुलुक', E'१४ मुलुक', E'१५ मुलुक', 'A', E'सन् २००२ जनवरी १ देखि **१२ मुलुकमा** एकल युरो मुद्रा प्रचलनमा आएको थियो। युरो मुद्राको अवधारणापत्र सन् १९९९ जनवरी १ मा पारित भएको थियो।\nनोट: हाल EU का २७ सदस्य देशहरूमध्ये २० मुलुकमा युरो आधिकारिक मुद्राको रूपमा प्रयोग गरिन्छ, जसमा २० औं मुलुक क्रोएसिया १ जनवरी २०२३ बाट थपिएको हो।', 'nepali'),
      (v_set_id, 26, E'सार्कको कार्यकारी अंग देहायका मध्ये कुन हो ?', E'शिखर सम्मेलन', E'मन्त्रिपरिषद्', E'सचिवालय', E'कार्यकारी समिति', 'B', E'**सार्कको कार्यकारी अंग मन्त्रिपरिषद् हो।**\n- शिखर सम्मेलन सार्कको ठूलो अंग हो, जुन सार्क वडापत्रको धारा ३ मा उल्लेख छ।\n- सचिवालय सार्कको प्रशासनिक अंग हो, जुन सार्क वडापत्रको धारा ५ मा उल्लेख छ।', 'nepali'),
      (v_set_id, 27, E'आसियानको वडापत्रमा जम्मा कतिवटा धाराहरु रहेको छन् ?', E'धारा ४५', E'धारा ३५', E'धारा ५५', E'धारा ६५', 'C', E'आसियानको वडापत्रमा जम्मा **५५ वटा धाराहरु** रहेका छन्। यस वडापत्रमा २००७ नोभेम्बर २० मा हस्ताक्षर गरिएको थियो र २००८ डिसेम्बर १५ बाट लागू भएको थियो।\nनोट: आसियान वडापत्र १३ औं आसियान सम्मेलन (२००७, सिंगापुर) बाट निर्माण भएको थियो र यसमा १५ वटा उद्देश्यहरू छन्।', 'nepali'),
      (v_set_id, 28, E'''सम्पत्ति तथा पारिवारिक मामिलामा दम्पतीको समान हक हुनेछ'' यो कुरा कुन मौलिक हक अन्तर्गत रहेको छ?', E'न्याय सम्बन्धी हक', E'समानताको हक', E'सम्पत्तिको हक', E'महिलाको हक', 'D', E'**नेपालको संविधान अनुसार, सम्पत्ति तथा पारिवारिक मामिलामा दम्पतीको समान हक हुनेछ भन्ने कुरा महिलाको हक अन्तर्गत पर्दछ।**\n- न्याय सम्बन्धी हकले निष्पक्ष सुनुवाइ र कानुनी उपचारको अधिकार सुनिश्चित गर्दछ।\n- समानताको हकले पैतृक सम्पत्तिमा लैंगिक भेदभाव बिना सबै सन्तानको समान हक हुने व्यवस्था गर्दछ।\n- सम्पत्तिको हकले प्रत्येक नागरिकलाई कानुनको अधीनमा रही सम्पत्ति आर्जन गर्ने, भोग गर्ने, बेचबिखन गर्ने र अन्य कारोबार गर्ने अधिकार प्रदान गर्दछ।', 'nepali'),
      (v_set_id, 29, E'नेपालका लागि सान्दर्भिक नभएको दिगो विकासको लक्ष्य कुन हो?', E'लक्ष्य १४', E'लक्ष्य १२', E'लक्ष्य १३', E'लक्ष्य १६', 'A', E'**नेपालका लागि सान्दर्भिक नभएको दिगो विकासको लक्ष्य लक्ष्य १४ हो, जुन सामुन्द्रिक जैविक विविधता (जलमुनिको जीवन) सँग सम्बन्धित छ।**\n- नेपाल भूपरिवेष्ठित राष्ट्र भएकाले सामुन्द्रिक जीवनसँग प्रत्यक्ष सरोकार राख्दैन।\n- लक्ष्य १३ जलवायु परिवर्तन र यसका प्रभाव न्यूनीकरण र पहलसँग सम्बन्धित छ।\n- लक्ष्य १५ जमिन माथिको जीवनसँग सम्बन्धित छ।\n- लक्ष्य १६ न्याय, शान्ति र सक्षम निकायसँग सम्बन्धित छ।', 'nepali'),
      (v_set_id, 30, E'बिमस्टेकको पाँचौ शिखर सम्मेलन २०२२ कुन देशमा सम्पन्न भएको थियो?', E'पाकिस्तान', E'भुटान', E'भारत', E'श्रीलंका', 'D', E'**बिमस्टेकको पाँचौ शिखर सम्मेलन सन् २०२२ मार्च ३० मा श्रीलंकाको कोलम्बोमा सम्पन्न भएको थियो।**\n- पाकिस्तान बिमस्टेकको सदस्य राष्ट्र होइन।\n- भुटान र भारत बिमस्टेकका सदस्य राष्ट्र हुन् तर पाँचौ शिखर सम्मेलन आयोजना गरेका थिएनन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/२५', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_08_29.csv  →  आसमान दैनिक GK — २०८२/०८/२९  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०८/२९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०८/२९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०८/२९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'हुम्ला, जुम्ला, मुगु, डोल्पा, मुस्ताङ र मनाङ लगायतका हिमाली उपत्यका देहायका मध्ये कुन हिमाली क्षेत्रमा रहेको छ?', E'मुख्य हिमाली क्षेत्र', E'भित्री हिमाली क्षेत्र', E'सीमान्त हिमाली क्षेत्र', E'हिमाल हिमाली क्षेत्र', 'B', E'हुम्ला, जुम्ला, मुगु, डोल्पा, मुस्ताङ र मनाङ लगायतका हिमाली उपत्यकाहरू **भित्री हिमाली क्षेत्रमा** पर्दछन्। यो क्षेत्र मुख्य हिमालयबाट उत्तर र तिब्बतको तटवर्ती क्षेत्रबाट दक्षिणतिर अवस्थित छ।', 'nepali'),
      (v_set_id, 2, E'टोड्के झरना कुन जिल्लामा रहेको छ पहिचान गर्नुहोस्?', E'डोल्पा', E'धादिङ', E'इलाम', E'ओखलढुंगा', 'C', E'**टोड्के झरना इलाम जिल्लामा अवस्थित छ।**\n- डोल्पा जिल्लामा सुलिगाड झरना रहेको छ।\n- धादिङ जिल्लामा गंगा जमुना झरना छ।\n- ओखलढुंगा जिल्लामा रातमाटे झरना रहेको छ।', 'nepali'),
      (v_set_id, 3, E'चिनिको कचौरा (bowl of sugar) भनेर कुन मुलुकलाई चिनिन्छ?', E'टर्की', E'क्युबा', E'युनान', E'बेल्जियम', 'B', E'**क्युबालाई चिनिको कचौरा (bowl of sugar) भनेर चिनिन्छ।**\n- टर्कीलाई युरोपको बिरामी भनेर चिनिन्छ।\n- युनानलाई इतिहासको बत्ती उपनामले चिनिन्छ।\n- बेल्जियमलाई युरोपको कारखाना उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 4, E'देहायको कुन जिल्लामा बाँके राष्ट्रिय निकुञ्ज अवस्थित छैन?', E'दाङ', E'बर्दिया', E'बाँके', E'सल्यान', 'D', E'**बाँके राष्ट्रिय निकुञ्ज सल्यान जिल्लामा अवस्थित छैन।**\n- यो निकुञ्ज २०६७ सालमा स्थापना भएको थियो र यसको क्षेत्रफल ५५० वर्ग कि.मि. रहेको छ।\n- बाँके, दाङ र बर्दिया जिल्लामा यस निकुञ्जको विस्तार रहेको छ।', 'nepali'),
      (v_set_id, 5, E'दुर्घटनाग्रस्त जहाजहरूको कारण पत्ता लगाउन प्रयोग गरिने यन्त्र कुन हो?', E'Black box', E'White box', E'Yellow box', E'Orange box', 'A', E'**दुर्घटनाग्रस्त जहाजहरूको कारण पत्ता लगाउन ब्ल्याक बक्स (Black box) प्रयोग गरिन्छ।**\nनोट: यो यन्त्र सुन्तला रङको हुन्छ, यद्यपि यसलाई ''ब्ल्याक बक्स'' भनिन्छ।', 'nepali'),
      (v_set_id, 6, E'भाषा आयोगले कर्णाली प्रदेशमा कामकाजको लागि सिफारिस गरेको भाषा कुन हो?', E'तामाङ', E'थारु', E'मगर', E'गुरुङ', 'C', E'**भाषा आयोगले कर्णाली प्रदेशमा कामकाजको लागि मगर भाषा सिफारिस गरेको छ।**\n- कोशी प्रदेशमा मैथिली र लिम्बु भाषा सिफारिस गरिएको छ।\n- मधेश प्रदेशमा मैथिली, भोजपुरी र बज्जिका भाषा सिफारिस गरिएको छ।\n- बागमती प्रदेशमा तामाङ र नेवार भाषा सिफारिस गरिएको छ।\n- गण्डकी प्रदेशमा मगर, गुरुङ र भोजपुरी भाषा सिफारिस गरिएको छ।\n- लुम्बिनी प्रदेशमा थारु र अवधी भाषा सिफारिस गरिएको छ।\n- सुदूरपश्चिम प्रदेशमा डोटेली र थारु भाषा सिफारिस गरिएको छ।', 'nepali'),
      (v_set_id, 7, E'विश्वको इतिहासमा पहिलो राजनीतिक क्रान्ति भनेर कुन क्रान्तिलाई चिनिन्छ?', E'औद्योगिक क्रान्ति', E'गौरवमय क्रान्ति', E'फ्रान्सेली क्रान्ति', E'रुसी क्रान्ति', 'B', E'**विश्वको इतिहासमा पहिलो राजनीतिक क्रान्ति भनेर गौरवमय क्रान्ति (Glorious Revolution) लाई चिनिन्छ।**\n- औद्योगिक क्रान्तिले उत्पादन प्रणालीमा ठूलो परिवर्तन ल्याएको थियो।\n- फ्रान्सेली क्रान्तिले राजतन्त्रको अन्त्य गरी गणतन्त्र स्थापना गरेको थियो।\n- रुसी क्रान्तिले जारशाहीको अन्त्य गरी सोभियत संघको स्थापना गरेको थियो।\nनोट: गौरवमय क्रान्तिलाई रक्तविहीन क्रान्ति पनि भनिन्छ, जुन सन् १६८८ मा बेलायतमा भएको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपाली इतिहासमा शाहकालीन समयमा लेखापरीक्षण कार्य कुन प्रशासनिक अड्डाले गर्थ्यो?', E'मुन्सीखाना', E'खड्ग निशान', E'कुमारी चोक', E'कन्देल चोक', 'C', E'**नेपाली इतिहासमा शाहकालीन समयमा लेखापरीक्षण र नियन्त्रणसँग सम्बन्धित कार्य कुमारी चोकले गर्थ्यो।**\n- खड्ग निशान श्री ३ को सचिवालय वा प्रधानमन्त्रीको कार्यालय (चन्द्रशमशेरको पालामा) थियो।\n- मुन्सीखाना परराष्ट्र मामिलासम्बन्धी कार्य गर्ने अड्डा थियो (भीमसेन थापा र रणबहादुर शाहको पालामा)।\n- कन्देल चोकले गरगहनाको व्यवस्था गर्ने कार्य गर्थ्यो (जंगबहादुर राणाको पालामा)।', 'nepali'),
      (v_set_id, 9, E'१० औं राष्ट्रिय खेलकुद प्रतियोगिता कुन प्रदेशमा आयोजना हुँदैछ?', E'लुम्बिनी', E'मधेश', E'कर्णाली', E'गण्डकी', 'C', E'**१० औं राष्ट्रिय खेलकुद प्रतियोगिता कर्णाली प्रदेशमा आयोजना हुने तय भएको छ।**\n- नवौं राष्ट्रिय खेलकुद प्रतियोगिता गण्डकी प्रदेशमा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 10, E'हालको संस्थान मध्ये नेपाल सरकारको पूर्ण स्वामित्वमा रहेका सार्वजनिक संस्थानको संख्या कति रहेको छ?', E'१८ वटा', E'१९ वटा', E'२० वटा', E'२१ वटा', 'C', E'नेपाल सरकारको पूर्ण स्वामित्वमा रहेका सार्वजनिक संस्थानहरूको संख्या **२० वटा** रहेको छ। कुल ४५ सार्वजनिक संस्थानहरूमध्ये २५ वटामा सरकारको अधिकांश स्वामित्व रहेको छ।', 'nepali'),
      (v_set_id, 11, E'सार्कको पर्यवेक्षक मुलुक कति वटा रहेको छन्?', E'१० वटा', E'९ वटा', E'८ वटा', E'७ वटा', 'C', E'सार्कका पर्यवेक्षक मुलुकहरूको संख्या **८ वटा** रहेको छ। ती मुलुकहरू जापान, इरान, चीन, दक्षिण कोरिया, म्यानमार, अमेरिका, मरिसस र अस्ट्रेलिया हुन्।\nनोट: युरोपेली संघ (EU) पनि सार्कको एक पर्यवेक्षक संस्था हो, जसलाई गणना गर्दा कुल पर्यवेक्षकको संख्या ९ पुग्छ।', 'nepali'),
      (v_set_id, 12, E'पेरिस सम्झौता अनुमोदन गर्ने नेपाल सार्कको कति औं मुलुक हो?', E'पहिलो', E'दोस्रो', E'तेस्रो', E'चौथो', 'C', E'पेरिस सम्झौता अनुमोदन गर्ने नेपाल सार्कको **तेस्रो** मुलुक हो।\n- सार्क राष्ट्रहरूमध्ये यो सम्झौता अनुमोदन गर्ने पहिलो मुलुक माल्दिभ्स र दोस्रो मुलुक भारत हो।', 'nepali'),
      (v_set_id, 13, E'सूर्यमा हाइड्रोजन पछि सबैभन्दा धेरै कुन तत्व हुने गर्छ?', E'कार्बन', E'अक्सिजन', E'नाइट्रोजन', E'हिलियम', 'D', E'सूर्यमा हाइड्रोजन पछि सबैभन्दा धेरै पाइने तत्व **हिलियम** हो। सूर्यको संरचनामा लगभग ७०.६% हाइड्रोजन र २७.४% हिलियम रहेको हुन्छ।', 'nepali'),
      (v_set_id, 14, E'नेपालको नागरिक आमाबाट जन्म भई बाबुको पहिचान हुन नसकेको व्यक्तिले कुन आधारमा नागरिकता प्राप्त गर्दछ?', E'अंगीकृत', E'वंशज', E'गैरआवासीय', E'सम्मानार्थ', 'B', E'नेपालको नागरिक आमाबाट नेपालमा जन्म भई नेपालमा नै बसोबास गरेको र बाबुको पहिचान हुन नसकेको व्यक्तिलाई **वंशजको आधारमा** नागरिकता प्रदान गरिनेछ। तर, नागरिकता प्राप्त गर्दाका बखत बाबु विदेशी नागरिक भएको ठहरेमा त्यस्तो व्यक्तिको नागरिकता संघीय कानून बमोजिम अंगीकृत नागरिकतामा परिणत हुनेछ।\nनोट: विदेशी नागरिकसँग विवाह गरेकी नेपाली महिलाबाट नेपालमा जन्मिएको व्यक्तिले नेपालमा स्थायी बसोबास गरेको र विदेशी नागरिकता नलिएको खण्डमा संघीय कानून बमोजिम अंगीकृत नागरिकता प्राप्त गर्न सक्नेछ।', 'nepali'),
      (v_set_id, 15, E'नेपालको शैक्षिक इतिहासमा वीर पुस्तकालय स्थापना कहिले भयो?', E'वि.सं. १९४३', E'वि.सं. १९७२', E'वि.सं. १९५७', E'वि.सं. १९६९', 'C', E'**वीर पुस्तकालयको स्थापना वि.सं. १९५७ मा भएको थियो।**\n- तीन धारा संस्कृत पाठशालाको स्थापना वि.सं. १९४३ बैशाख ४ गते भएको थियो।\n- चन्द्र मिडिल स्कुलको स्थापना वि.सं. १९७२ मा भएको थियो।\n- गोर्खा भाषा प्रकाशिनी समितिको स्थापना वि.सं. १९६९ मा भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०८/२९', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_02.csv  →  आसमान दैनिक GK — २०८२/०९/०२  (27 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/०२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/०२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/०२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको संविधानमा कुन धारामा राज्यको संरचनासँग सम्बन्धित व्यवस्था गरिएको छ ?', E'धारा ५५', E'धारा ५६', E'धारा ५७', E'धारा ५८', 'B', E'नेपालको संविधानको **धारा ५६** मा राज्यको संरचनासम्बन्धी व्यवस्था गरिएको छ। संविधानको भाग ५ मा ''राज्यको संरचना र राज्यशक्तिको बाँडफाँड'' अन्तर्गत यस धाराले संघीय लोकतान्त्रिक गणतन्त्र नेपालको मूल संरचना संघ, प्रदेश र स्थानीय तह गरी तीन तहको हुने उल्लेख गरेको छ।', 'nepali'),
      (v_set_id, 2, E'काठबाट बनेको नेपालको सबैभन्दा ठूलो मन्दिर पहिचान गरी उक्त मन्दिर कुन क्षेत्रमा अवस्थित रहेको पाउनु भयो ?', E'हनुमानढोका दरबार क्षेत्र', E'पाटन दरबार क्षेत्र', E'भक्तपुर दरबार क्षेत्र', E'लुम्बिनी क्षेत्र', 'A', E'काठबाट बनेको नेपालको सबैभन्दा ठूलो मन्दिर, काष्ठमण्डप, **हनुमानढोका दरबार क्षेत्रमा** अवस्थित छ।\n- पाटन दरबार क्षेत्रमा प्रसिद्ध कृष्ण मन्दिर रहेको छ।\n- भक्तपुर दरबार क्षेत्रमा पचपन्न झ्याले दरबार र न्यातपोल मन्दिर जस्ता सम्पदाहरू छन्।\n- लुम्बिनी क्षेत्रमा मायादेवी मन्दिर अवस्थित छ, जुन गौतम बुद्धको जन्मस्थल हो।', 'nepali'),
      (v_set_id, 3, E'नेपाली साहित्यको विकासक्रममा आधुनिक कालका प्रवर्तकका रूपमा चिनिने साहित्यकार को हुन् ?', E'मोतिराम भट्ट', E'लेखनाथ पौड्याल', E'लक्ष्मीप्रसाद देवकोटा', E'बालकृष्ण सम', 'B', E'नेपाली साहित्यको विकासक्रममा आधुनिक कालका प्रवर्तकका रूपमा **लेखनाथ पौड्याल** लाई चिनिन्छ।\n- मोतिराम भट्टलाई माध्यमिक कालका प्रवर्तक तथा ''युवाकवि'' का रूपमा चिनिन्छ।\n- लक्ष्मीप्रसाद देवकोटालाई ''महाकवि'' को उपाधिले चिनिन्छ।\n- बालकृष्ण समलाई ''नाट्यसम्राट्'' का रूपमा चिनिन्छ।\nनोट: लेखनाथ पौड्याललाई ''कविशिरोमणि'' को उपाधिले पनि सम्मान गरिन्छ।', 'nepali'),
      (v_set_id, 4, E'दोस्रो विश्व युद्धमा आत्मसमर्पण गर्ने प्रथम राष्ट्र कुन हो ?', E'जर्मनी', E'इटाली', E'जापान', E'बेलायत', 'B', E'**दोस्रो विश्व युद्धमा सर्वप्रथम आत्मसमर्पण गर्ने राष्ट्र इटाली हो।**\n- जर्मनीले १९४५ मे ७ मा आत्मसमर्पण गरेको थियो, जुन आत्मसमर्पण गर्ने दोस्रो राष्ट्र थियो।\n- जापानले १९४५ अगस्त १४ मा आत्मसमर्पण गरी दोस्रो विश्व युद्धको अन्त्य भएको थियो, जुन आत्मसमर्पण गर्ने अन्तिम राष्ट्र थियो।\n- बेलायत दोस्रो विश्व युद्धमा मित्र राष्ट्रहरूको पक्षमा लडेको थियो।', 'nepali'),
      (v_set_id, 5, E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार महानगरपालिका हुन कम्तीमा कति स्थायी बासिन्दा भएको हुनु पर्दछ ?', E'पाँच लाख', E'चार लाख', E'तीन लाख', E'दुई लाख', 'A', E'**स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार महानगरपालिका हुन कम्तीमा पाँच लाख स्थायी बासिन्दा हुनुपर्दछ।**\n- उपमहानगरपालिकाका लागि कम्तीमा दुई लाख स्थायी बासिन्दा आवश्यक पर्दछ।\n- नगरपालिकाका लागि भौगोलिक क्षेत्र अनुसार १० हजार देखि १ लाखसम्म स्थायी बासिन्दाको मापदण्ड तोकिएको छ।', 'nepali'),
      (v_set_id, 6, E'अमेरिकी नवनिर्वाचित राष्ट्रपति डोनाल्ड ट्रम्पले कहिले शपथ लिएका हुन् ?', E'२०२५ जनवरी १', E'२०२५ जनवरी ५', E'२०२५ जनवरी १०', E'२०२५ जनवरी २०', 'D', E'**अमेरिकी नवनिर्वाचित राष्ट्रपति डोनाल्ड ट्रम्पले २०२५ जनवरी २० मा शपथ लिएका थिए।**\n- अमेरिकामा राष्ट्रपतिको निर्वाचन २०२४ नोभेम्बर ५ मा सम्पन्न भएको थियो।\n- डोनाल्ड ट्रम्प रिपब्लिकन पार्टीका उम्मेदवार हुन् र उनले ३१२ इलेक्टोरल भोट प्राप्त गरेका थिए।\nनोट: उनी अमेरिकाका ४७ औं राष्ट्रपति हुन्।', 'nepali'),
      (v_set_id, 7, E'बागमती प्रदेशमा उपमहानगरपालिकाको संख्या कति रहेको छ ?', E'१ वटा', E'२ वटा', E'३ वटा', E'४ वटा', 'A', E'**बागमती प्रदेशमा उपमहानगरपालिकाको संख्या १ वटा रहेको छ, जुन हेटौँडा उपमहानगरपालिका हो।**\n- नेपालमा कुल ११ उपमहानगरपालिका छन्।\n- लुम्बिनी प्रदेशमा सबैभन्दा धेरै ४ वटा (बुटवल, नेपालगञ्ज, घोराही र तुलसीपुर) उपमहानगरपालिका छन्।\n- मधेश प्रदेशमा ३ वटा (कलैया, जीतपुर-सिमरा र जनकपुर) र कोशी प्रदेशमा २ वटा (धरान, इटहरी) उपमहानगरपालिका छन्।', 'nepali'),
      (v_set_id, 8, E'विश्वमा जापान पछि दोस्रो धेरै भूकम्प जाने मुलुक कुन हो ?', E'टर्की', E'मेक्सिको', E'इण्डोनेसिया', E'आर्मेनिया', 'C', E'विश्वमा जापान पछि दोस्रो धेरै भूकम्प जाने मुलुक **इण्डोनेसिया** हो।\n- टर्की तेस्रो धेरै भूकम्प जाने मुलुक हो।\n- मेक्सिको चौथो धेरै भूकम्प जाने मुलुक हो।\n- आर्मेनिया भूकम्पीय जोखिम भएको देश भए तापनि शीर्ष ५ मा पर्दैन, पाँचौं स्थानमा एल साल्भाडोर पर्दछ।', 'nepali'),
      (v_set_id, 9, E'राष्ट्र संघ (league of nations) को प्रधान कार्यालय कुन ठाउँमा रहेको छ ?', E'New york', E'Geneva', E'Manela', E'Washington DC', 'B', E'राष्ट्र संघ (League of Nations) को प्रधान कार्यालय **जेनेभा, स्वीट्जरल्याण्डमा** रहेको थियो।\n- New york मा संयुक्त राष्ट्र संघ (UN) को प्रधान कार्यालय रहेको छ।\n- Manela (मनिला) फिलिपिन्सको राजधानी हो, जहाँ एसियाली विकास बैंक (ADB) को मुख्यालय छ।\n- Washington DC मा विश्व बैंक समूह र अन्तर्राष्ट्रिय मुद्रा कोष (IMF) को मुख्यालय रहेको छ।\nनोट: राष्ट्र संघको स्थापना १० जनवरी १९२० मा भएको थियो र यसको विघटन २० अप्रिल १९४६ मा भयो।', 'nepali'),
      (v_set_id, 10, E'दक्षिण एसियाली क्षेत्रीय सहयोग संगठन (SAARC) को स्थापना कालका सदस्य संख्या कति रहेको छ ?', E'६ वटा', E'८ वटा', E'७ वटा', E'५ वटा', 'C', E'दक्षिण एसियाली क्षेत्रीय सहयोग संगठन (SAARC) को स्थापना हुँदा यसका सदस्य राष्ट्रहरूको संख्या **७** थियो। स्थापनाकालीन सदस्यहरूमा नेपाल, भारत, पाकिस्तान, बंगलादेश, श्रीलंका, भुटान र माल्दिभ्स थिए।\nनोट: सन् २००७ मा अफगानिस्तानले सदस्यता लिएपछि सार्कको सदस्य संख्या ८ पुगेको हो।', 'nepali'),
      (v_set_id, 11, E'रामसारमा सूचीकृत नेपालका सिमसार क्षेत्रहरु मध्ये सबैभन्दा सानो क्षेत्र कुन हो ?', E'गोक्यो ताल', E'रारा ताल', E'बीस हजारी ताल', E'माई पोखरी', 'D', E'रामसारमा सूचीकृत नेपालका सिमसार क्षेत्रहरूमध्ये सबैभन्दा सानो **माई पोखरी** हो, जुन इलाम जिल्लामा पर्दछ र यसको क्षेत्रफल ९० हेक्टर छ।\n- गोक्यो ताल (सोलुखुम्बु) ७,७७० हेक्टर क्षेत्रफलमा फैलिएको छ।\n- रारा ताल (मुगु) १,५८३ हेक्टर क्षेत्रफलमा फैलिएको छ।\n- बीस हजारी ताल (चितवन) ३,२०० हेक्टर क्षेत्रफलमा फैलिएको छ।\nनोट: नेपालको सबैभन्दा ठूलो रामसार क्षेत्र पोखरा उपत्यकाका ९ वटा तालहरूको समूह हो, जसको कुल क्षेत्रफल २६,१०६ हेक्टर छ।', 'nepali'),
      (v_set_id, 12, E'४२ सालको पर्व पछिका प्रथम प्रधानमन्त्री को हुन् ?', E'देव शमशेर', E'रणोदिप सिंह', E'वीर शमशेर', E'भिम शमशेर', 'C', E'वि.सं. १९४२ सालको पर्वपछि **वीर शमशेर** प्रधानमन्त्री बनेका थिए। यो पर्वमा धीर शमशेरका छोराहरूले आफ्ना काका तथा तत्कालीन प्रधानमन्त्री रणोदीप सिंहको हत्या गरेका थिए।\n- देव शमशेर वीर शमशेरपछिका प्रधानमन्त्री थिए।\n- रणोदीप सिंह ४२ सालको पर्वमा हत्या गरिएका प्रधानमन्त्री हुन्।\n- भिम शमशेर चन्द्र शमशेरपछिका प्रधानमन्त्री थिए।', 'nepali'),
      (v_set_id, 13, E'नेपाल र अंग्रेज बिच भएको सुगौली सन्धिमा हस्ताक्षर कहिले भएको थियो ?', E'१८७६ मार्च ३', E'१८७२ मार्च ३', E'१८७२ डिसेम्बर २', E'१८७६ डिसेम्बर २', 'A', E'**सन् १८७६ मार्च ३ (विक्रम संवत् १८७२ फागुन २४) मा नेपाल र अंग्रेजबीच सुगौली सन्धिमा हस्ताक्षर भएको थियो।**\n- नेपालको तर्फबाट गजराज मिश्र र अंग्रेजको तर्फबाट लेफ्टिनेन्ट ब्राडशले हस्ताक्षर गरेका थिए।\n- सन्धिमा १ धारा उल्लेख छ र त्यसबेला नेपालका राजा गिर्वाणयुद्ध विक्रम शाह थिए।', 'nepali'),
      (v_set_id, 14, E'नेपालको राणाकालीन अड्डा हरु अन्तर्गत कर्मचारी अभिलेख हेर्ने अड्डालाई भनिन्थ्यो?', E'कौशी तोषाखाना', E'दफ्तरखाना', E'छडेल खाना', E'जैशी कोठी', 'B', E'**नेपालको राणाकालीन समयमा कर्मचारी अभिलेख हेर्ने अड्डालाई दफ्तरखाना भनिन्थ्यो।**\n- कौशी तोषाखानाले तलब, भत्ता र पेन्सन सम्बन्धी काम हेर्थ्यो।\n- छडेल खाना निर्माण सम्बन्धी काममा संलग्न थियो।\n- जैशी कोठीले तिब्बत मामिला हेर्ने काम गर्थ्यो।', 'nepali'),
      (v_set_id, 15, E'सन् १९८३ मा गठन भएको दिगो विकास अवधारणा ल्याएको आयोगको नाम के हो?', E'हेलसिन्क आयोग', E'कोप आयोग', E'ब्रुटल्याण्ड आयोग', E'स्टकहोम आयोग', 'C', E'**सन् १९८३ मा गठन भएको ब्रुटल्याण्ड आयोगले सर्वप्रथम दिगो विकासको अवधारणा ल्याएको थियो।**\n- यो आयोग ग्रो हालेम ब्रुटल्याण्डको अध्यक्षतामा गठन गरिएको थियो।\nनोट: वातावरणीय मुद्दाहरूमा पहिलो प्रमुख अन्तर्राष्ट्रिय सम्मेलन स्टकहोम (स्वीडेन) मा सन् १९७२ जुन ५ देखि १६ सम्म भएको थियो।', 'nepali'),
      (v_set_id, 16, E'देहायका जोडा मध्ये कुन मिति गलत रहेको छ?', E'क', E'ख', E'ग', E'घ', 'D', E'**अध्यागमन विभागद्वारा ई-भिसा सेवाको शुभारम्भ वि.सं. २०८० माघ २६ गते भएको हो।**\n- सरकारले भूमि समस्या समाधान आयोग खारेज गर्ने निर्णय वि.सं २०७८ असोज २३ मा गरेको थियो।\n- इजरायल र हमासबीच युद्धविराम सम्झौता सन् २०२२ अक्टोबर ११ मा लागु भएको थियो।\n- कोशी प्रदेश पर्यटन वर्ष २०८२ घोषणा वि.सं. २०८१ चैत २७ मा गरिएको थियो।', 'nepali'),
      (v_set_id, 17, E'तलका कथनहरु बारे विचार गर्नुहोस्। घनत्वका आधारमा कुन चाहिँ ग्रहहरुको क्रम सही छ?', E'क', E'ख', E'ग', E'घ', 'B', E'घनत्वका आधारमा ग्रहहरूको सही क्रम **पृथ्वी, बुध, शुक्र, मंगल, वरुण, बृहस्पति, अरुण, शनि** हो।\nनोट: ग्रहहरूको घनत्व तिनीहरूको संरचना र आकारमा निर्भर गर्दछ।', 'nepali'),
      (v_set_id, 18, E'तलको जोडााहरुमा नमिल्दो जोडा छान्नुहोस्?', E'१ र २ मात्र', E'१ र ३ मात्र', E'२ र ४ मात्र', E'माथिका सबै', 'C', E'**आन्द्र महासागरको गहिरो स्थान पोर्टोरिको ट्रेन्च हो र सुमेरु महासागरको गहिरो स्थान मोलि डिप हो।**\n- प्रशान्त महासागरको गहिरो स्थान मारियाना ट्रेन्च हो।\n- हिन्द महासागरको गहिरो स्थान जाभा ट्रेन्च हो।', 'nepali'),
      (v_set_id, 19, E'नेपालको क्षेत्रफलका सम्बन्धमा तल केहि जोडाहुहरु दिइएको छ। उक्त जोडाको अध्ययन गरी गलत जोडाहुहरु कुन-कुन हुन? पत्ता लगाउनुहोस्।', E'२ मात्र गलत', E'३ मात्र गलत', E'२,३,४ गलत', E'२, ३ मात्र गलत', 'D', E'**नेपालको क्षेत्रफल वर्गमाइलमा ५६,८२७ र चीन भन्दा करिब ६५.२ गुणा सानो रहेको छ।**\n- नेपालको क्षेत्रफल १,४७,१८१ वर्ग कि.मि. हो।\n- नेपाल भारत भन्दा करिब २२.३३ गुणा सानो छ।', 'nepali'),
      (v_set_id, 20, E'जोडा मिलाउनुहोस्: नदी: (a) तमोर, (b) दुधकोशी, (c) लिखु, (d) इन्द्रावती उदगमस्थल: 1. रोल्वालिङ, 2. जुगल, 3. कुम्भकर्ण हिमाल, 4. दुधकुण्ड', E'a3, b2, c1, d4', E'a3, b1, c2, d4', E'a2, b3, c4, d1', E'a3, b4, c1, d2', 'D', E'नेपालका प्रमुख नदीहरूको उद्गमस्थल यसप्रकार रहेको छ: **तमोर नदीको कुम्भकर्ण हिमाल, दुधकोशीको दुधकुण्ड, लिखुको रोल्वालिङ र इन्द्रावतीको जुगल हिमाल।**', 'nepali'),
      (v_set_id, 21, E'तलकामध्ये कुन चाहीँ सही हो? पहिचान गर्नुहोस्। i. गौरवमय क्रान्तिको समयमा राजा जेम्स द्वितीय भागेर गएको देश बेलायत हो। ii. जेम्स द्वितीय स्टुअर्ट राजवंशका थिए। iii. जेम्स द्वितीय भन्दा अघि बेलायतका राजा जेम्स प्रथम थिए। iv. बेलायतलाई संसदको जननी भनिन्छ।', E'ii र iv मात्र सही', E'i, ii र iv मात्र सही', E'माथिका सबै सही', E'i र iv मात्र सही', 'A', E'**जेम्स द्वितीय स्टुअर्ट राजवंशका थिए र बेलायतलाई ''संसदको जननी'' भनेर चिनिन्छ।**\n- गौरवमय क्रान्तिको समयमा राजा जेम्स द्वितीय बेलायतबाट भागेर फ्रान्स गएका थिए।\n- जेम्स द्वितीयभन्दा अघि बेलायतका राजा उनका दाजु चार्ल्स द्वितीय थिए, जेम्स प्रथम होइनन्।', 'nepali'),
      (v_set_id, 22, E'किराँत वंश सन्दर्भमा दिएकामध्ये सही कुन हो पहिचान गर्नुहोस्। (i) किराँत वंश शैव धर्म मान्थे भने मुन्धुमलाई आधार मानी शासन व्यवस्था चलाउँथे। (ii) द्वापरयुगको अन्त्य वा कलियुगको प्रारम्भतिर छैटौं शताब्दीमा शासन गरेको। (iii) किराँत वंशमा राजालाई तुम्थ्याङ भनिन्थ्यो। (iv) किराँतीहरू कृष्णका सन्तान थिए।', E'i, iii र iv मात्र ठीक', E'i, iii मात्र ठीक', E'i, ii, मात्र ठीक', E'माथिका सबै ठीक', 'C', E'**किराँत वंशले शैव धर्म मान्दै मुन्धुमलाई आधार मानेर शासन गर्थे र उनीहरूले द्वापरयुगको अन्त्यतिर शासन गरेको मानिन्छ।**\n- किराँत वंशमा राजालाई ''हाङ'' र मन्त्रीलाई ''तुम्थ्याङ'' भनिन्थ्यो।\n- किराँतीहरूलाई महादेवको सन्तान मानिन्छ, कृष्णको होइन।', 'nepali'),
      (v_set_id, 23, E'जोडा मिलाउनुहोस्।', E'१ग, २घ, ३ख, ४क', E'१ग, २क, ३घ, ४ख', E'१ग, २ख, ३घ, ४क', E'१ग, २क, ३ख, ४घ', 'B', E'**छापाखानाको आविष्कारक जोहानेस गुटेनबर्ग, मोबाइल फोनको आविष्कारक मार्टिन कुपर, डाइनामाइटको आविष्कारक अल्फ्रेड नोबेल र टेलिभिजनको आविष्कारक जोन वियर्ड हुन्।**', 'nepali'),
      (v_set_id, 24, E'तल दिइएका भनाइहरू मध्ये कुन भनाइ सही छ? विचार गर्नुहोस्।', E'२ र ४', E'१, २ र ३', E'२, ३ र ४', E'माथिका सबै', 'A', E'**पारिस्थितिक पद्धतिमा उपभोक्तालाई मुख्यत: प्राथमिक, द्वितीय र तृतीय गरी ३ भागमा विभाजन गरिन्छ र भोलभक्स (Volvox) तथा हाइड्रीला (Hydrilla) उत्पादक हुन्।**\n- उपभोक्ताले आफ्नो खाना आफैँ बनाउन सक्दैनन्, उत्पादकले प्रकाश संश्लेषण प्रक्रिया मार्फत खाना उत्पादन गर्छन्।\n- फङ्गि र ब्याक्टेरिया जस्ता सेप्रोफाइटहरू अजैविक तत्व नभई विच्छेदक (decomposers) हुन्।', 'nepali'),
      (v_set_id, 25, E'संयुक्त राष्ट्रसंघको विशिष्टीकृत संस्था र सो संस्था रहेको स्थानबीच जोडा मिलाउनुहोस् र कोडबाट सही उत्तर छान्नुहोस्। १. रोम २. जेनेभा ३. वासिङ्टन ४. म्याड्रिड, स्पेन  (क) अन्तर्राष्ट्रिय दूर सञ्चार संघ (ख) विश्व जलवायु विज्ञान सङ्गठन (ग) विश्व पर्यटन सङ्गठन (UNWTO) (घ) अन्तर्राष्ट्रिय कृषि विकास', E'१क, २ख, ३ग, ४घ', E'१घ, २ख, ३क, ४ग', E'१ग, २घ, ३क, ४ख', E'१घ, २क, ३ख, ४ग', 'B', E'**संयुक्त राष्ट्रसंघका विशिष्टीकृत संस्थाहरू र तिनीहरूका मुख्यालयहरू निम्नअनुसार छन्:**\n- अन्तर्राष्ट्रिय कृषि विकास कोष (IFAD) को मुख्यालय रोममा रहेको छ।\n- विश्व जलवायु विज्ञान सङ्गठन (WMO) को मुख्यालय जेनेभामा रहेको छ।\n- अन्तर्राष्ट्रिय दूर सञ्चार संघ (ITU) को मुख्यालय वासिङ्टनमा रहेको छ।\n- विश्व पर्यटन सङ्गठन (UNWTO) को मुख्यालय म्याड्रिड, स्पेनमा रहेको छ।', 'nepali'),
      (v_set_id, 26, E'नेपालको संविधानमा उल्लेखित संवैधानिक अंग र भाग अनुसारको जोडा मिलाउनुहोस्। (a) लोक सेवा आयोग (b) अख्तियार दुरुपयोग अनुसन्धान आयोग (c) निर्वाचन आयोग (d) महालेखापरीक्षकको कार्यालय  1. 21 2. 22 3. 23 4. 24', E'a3, b1, c4, d2', E'a3, b2, c4, d1', E'a1, b2, c3, d4', E'a4, b1, c2, d3', 'A', E'**नेपालको संविधानमा लोक सेवा आयोग भाग २३ मा उल्लेखित छ।**\n- अख्तियार दुरुपयोग अनुसन्धान आयोग संविधानको भाग २१ मा पर्दछ।\n- निर्वाचन आयोगको व्यवस्था संविधानको भाग २४ मा गरिएको छ।\n- महालेखापरीक्षकको कार्यालय संविधानको भाग २२ मा उल्लेखित छ।', 'nepali'),
      (v_set_id, 27, E'तलकामध्ये कुन चाहिँ सही छैन? पहिचान गर्नुहोस्। i. नेपालमा पहिलो पटक प्रकाशित नोटमा हस्ताक्षर गर्ने जनकराज पाण्डे थिए। ii. बैंकिङ प्रबर्द्धन समितिको स्थापना वि.सं. २०२५ मा भएको थियो। iii. नेपाल राष्ट्र बैंकको स्थापना नेपाल राष्ट्र बैंक ऐन २०१३ अनुसार भएको हो। iv. नेपाली रुपैयाँको विदेशी विनिमय दर निर्धारण गर्ने अधिकार नेपाल सरकारलाई छ।', E'ii र iii मात्र सही', E'i, ii र iii मात्र सही', E'ii मात्र सही', E'माथिका सबै सही', 'C', E'**बैंकिङ प्रबर्द्धन समितिको स्थापना वि.सं. २०२५ मा भएको थियो।**\n- नेपालमा पहिलो पटक प्रकाशित नोटमा हस्ताक्षर गर्ने खजाञ्ची नरेन्द्रराज पाण्डे थिए।\n- नेपाल राष्ट्र बैंकको स्थापना नेपाल राष्ट्र बैंक ऐन २०१२ अनुसार भएको हो।\n- नेपाली रुपैयाँको विदेशी विनिमय दर निर्धारण गर्ने अधिकार नेपाल राष्ट्र बैंकलाई छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/०२', 27;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_03.csv  →  आसमान दैनिक GK — २०८२/०९/०३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/०३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/०३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/०३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'विश्वको पहिलो Cashless (नगदरहित) देश कुन मुलुक बनेको छ?', E'इजरायल', E'अमेरिका', E'अष्ट्रेलिया', E'स्वीडेन', 'D', E'**स्वीडेन विश्वको पहिलो नगदरहित (Cashless) देश बनेको छ।**\n- इजरायलले २०२३ फेब्रुअरी २ देखि प्राथमिक विद्यालयमा मोबाइल फोन प्रयोगमा प्रतिबन्ध लगाएको थियो।\n- अष्ट्रेलिया १६ वर्ष मुनिकालाई सामाजिक सञ्जाल प्रयोगमा प्रतिबन्ध लगाउने पहिलो देश हो।\n- अमेरिका डिजिटल भुक्तानीमा अग्रणी भए पनि पूर्ण नगदरहित देश बनेको छैन।\nनोट: स्वीडेनमा २०१२ मा ''Swish'' नामक मोबाइल पेमेन्ट एप सुरु भएपछि २०२४ सम्म नगदको प्रयोग लगभग नगण्य बनिसकेको छ।', 'nepali'),
      (v_set_id, 2, E'नेपाल सरकारद्वारा उपहारस्वरूप कतार पठाइएका दुई हात्तीहरू कुन-कुन हुन्?', E'रुद्रकली र खगेन्द्रप्रसाद', E'सेलिफकली र रुद्रकली', E'खगेन्द्रप्रसाद र रुद्रकली', E'बिजुली कली र खगेन्द्रप्रसाद', 'A', E'**नेपाल सरकारद्वारा कतारलाई उपहारस्वरूप पठाइएका दुई हात्तीहरू रुद्रकली र खगेन्द्रप्रसाद हुन्।** यी हात्तीहरू रोनाल्डो हात्तीका सन्तान हुन् र सौरहाको हात्ती प्रजनन तथा तालिम केन्द्र खोरसोरमा जन्मेहुर्केका थिए।\nनोट: यी हात्तीहरू २०७२ पुस २ गते कतार पठाइएका थिए।', 'nepali'),
      (v_set_id, 3, E'एसियाली युथ पारा गेम्स तेक्वान्दोमा कांस्य पदक जित्ने नेपाली खेलाडी को हुन्?', E'कविता नेपाली', E'प्रिति राई', E'रेणु तामाङ', E'आस्मा के सी', 'C', E'**रेणु तामाङ।**\n- उनले एसियाली युथ पारा गेम्स तेक्वान्दोमा कांस्य पदक जितेकी थिइन्।', 'nepali'),
      (v_set_id, 4, E'विश्व मानव अधिकार दिवस प्रत्येक वर्ष कुन दिन मनाइन्छ ?', E'डिसेम्बर १०', E'डिसेम्बर ११', E'डिसेम्बर १२', E'डिसेम्बर १३', 'A', E'विश्व मानव अधिकार दिवस हरेक वर्ष **डिसेम्बर १०** मा मनाइन्छ। संयुक्त राष्ट्रसंघको महासभाले सन् १९४८ डिसेम्बर १० मा मानव अधिकारको विश्वव्यापी घोषणा अनुमोदन गरी स्वीकृत गरेको सम्झनामा यो दिवस मनाइन्छ।\nनोट: सन् २०२४ मा ७६औं मानव अधिकार दिवस ''Human Rights, Our Everyday Essentials (मानव अधिकार, हामी सबैको अपरिहार्य आधार)'' नाराका साथ मनाइएको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपाल प्रिमियर लिगको इतिहासकै ह्याट्रिक विकेट लिने पहिलो बलर को बनेका छन् ?', E'शाहब आलम', E'सन्दीप लामिछाने', E'एडम रोसिङ्टन', E'ललित राजवंशी', 'A', E'काठमाडौँ गोर्खाजका स्पिनर **शाहब आलम** नेपाल प्रिमियर लिगको इतिहासकै ह्याट्रिक विकेट लिने पहिलो बलर बनेका छन्।\nनोट: रोहित पौडेल नेपाल प्रिमियर लिगमा ह्याट्रिक विकेट लिने दोस्रो बलर हुन्।', 'nepali'),
      (v_set_id, 6, E'१० औं पर्वतीय महोत्सव नेपालको कुन जिल्लामा आयोजना भएको छ ?', E'कास्की', E'काठमाडौँ', E'सोलुखुम्बु', E'धनकुटा', 'A', E'१० औं पर्वतीय महोत्सव नेपालको **कास्की** जिल्लाको पोखरामा आयोजना भएको थियो।\nनोट: यो महोत्सव अन्तर्राष्ट्रिय पर्वत दिवस २०२४ डिसेम्बर ११ को अवसर पारेर वि.सं. २०८२ मंसिर २५ देखि २७ सम्म सञ्चालन भएको थियो।', 'nepali'),
      (v_set_id, 7, E'डा. अम्बेडकर अन्तर्राष्ट्रिय अवार्ड कुन नेपाली राजनीतिज्ञलाई प्रदान गरिएको छ ?', E'ज्ञानेन्द्र शाही', E'केपि शर्मा वली', E'कुलमान घिसिङ', E'सन्तोष परियार', 'D', E'डा. अम्बेडकर अन्तर्राष्ट्रिय अवार्ड नेपाली राजनीतिज्ञ **सन्तोष परियार**लाई प्रदान गरिएको छ।\nनोट: यो पुरस्कार भारतको संविधान निर्माता तथा दलित आन्दोलनका नेता बाबासाहेब डा. भीमराव अम्बेडकरको नाउँमा स्थापित डा. अम्बेडकर फाउन्डेसनले सामाजिक न्याय र सशक्तीकरणको क्षेत्रमा काम गर्नेहरूलाई हरेक वर्ष प्रदान गर्दछ।', 'nepali'),
      (v_set_id, 8, E'योजना आयोगको नवनियुक्त उपाध्यक्ष डा. प्रकाशकुमार श्रेष्ठले पद तथा गोपनीयताको शपथ ग्रहण कहिले लिएका छन् ?', E'२०८२ मंसिर २९', E'२०८२ मंसिर ३०', E'२०८२ पुस १', E'२०८२ पुस २', 'C', E'योजना आयोगका नवनियुक्त उपाध्यक्ष डा. प्रकाशकुमार श्रेष्ठले पद तथा गोपनीयताको शपथ ग्रहण **२०८२ पुस १** गते लिएका छन्।', 'nepali'),
      (v_set_id, 9, E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ को विजेता उपाधि कुन टिमले प्राप्त गरेको छ ?', E'लुम्बिनी लायन्स', E'सुदूरपश्चिम रोयल्स', E'विराटनगर किंग', E'जनकपुर बोल्ट्स', 'A', E'**नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ को विजेता उपाधि लुम्बिनी लायन्सले प्राप्त गरेको थियो।**\n- सुदूरपश्चिम रोयल्स उपविजेता बनेको थियो।\n- विराटनगर किङ्स र काठमाडौँ गोर्खाज अन्तिम चारमा पुगेका अन्य टोलीहरू हुन्।', 'nepali'),
      (v_set_id, 10, E'चालु आर्थिक वर्षको पाँच महिना (साउन-मंसिर) मा सरकारले कति राजस्व संकलन गरेको प्रारम्भिक प्रतिवेदनले देखाएको छ ?', E'४ खर्ब १ अर्ब ७८ करोड', E'५ खर्ब १ अर्ब ७८ करोड', E'६ खर्ब १ अर्ब ७८ करोड', E'७ खर्ब १ अर्ब ७८ करोड', 'A', E'**चालु आर्थिक वर्षको पाँच महिना (साउन-मंसिर) मा सरकारले ४ खर्ब १ अर्ब ७८ करोड राजस्व संकलन गरेको थियो।**\nनोट: यो वार्षिक लक्ष्यको २७.४५ प्रतिशत हो, जसमा सरकारले १४ खर्ब ८० अर्ब रुपैयाँ संकलन गर्ने लक्ष्य तय गरेको छ।', 'nepali'),
      (v_set_id, 11, E'२०२५ मा सञ्चालित बाघ गणनाको उद्घाटन को द्वारा भएको छ ?', E'माधव प्रसाद चौलागाईं', E'मदन प्रसाद परियार', E'सुशिला कार्की', E'जगदीश खरेल', 'A', E'**वन तथा वातावरण मन्त्री माधव प्रसाद चौलागाईंले २०२५ पुस १ गते राष्ट्रिय बाघ गणनाको औपचारिक उद्घाटन गरेका थिए।**\nनोट: यो नेपालको पाँचौ बाघ गणना हो, जुन प्रत्येक चार वर्षको अन्तरालमा गरिन्छ।', 'nepali'),
      (v_set_id, 12, E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा जम्मा कति वटा चौका प्रहार भएको थियो?', E'४२७ वटा', E'५०५ वटा', E'५२७ वटा', E'६०५ वटा', 'D', E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा जम्मा **६०५ वटा** चौका प्रहार भएको थियो।\n- यस संस्करणमा जम्मा २२ खेल खेलिएको थियो र कुल ४२७ वटा छक्का प्रहार भएका थिए।', 'nepali'),
      (v_set_id, 13, E'नेपाल क्रिकेट संघ (क्यान) ले नेपाल राष्ट्रिय महिला क्रिकेट टिमको मुख्य प्रशिक्षकमा कसलाई नियुक्त गरेको छ?', E'स्टुवार्ट ल', E'हर्षल पाठक', E'मोटी देसाई', E'जगत टमाटा', 'B', E'**नेपाल क्रिकेट संघ (क्यान) ले २०८२ पुस १ गते भारतका हर्षल पाठकलाई नेपाल राष्ट्रिय महिला क्रिकेट टिमको मुख्य प्रशिक्षकमा नियुक्त गरेको छ।**\n- स्टुवार्ट ललाई नेपाल क्रिकेट संघ (क्यान) ले २०८१ चैत्र १५ मा राष्ट्रिय पुरुष टोली क्रिकेटको मुख्य प्रशिक्षकमा नियुक्त गरेको थियो।\n- मोटी देसाई नेपाल राष्ट्रिय पुरुष क्रिकेट टोलीका पूर्व मुख्य प्रशिक्षक हुन्।\n- जगत टमाटा नेपाल राष्ट्रिय महिला क्रिकेट टोलीका पूर्व मुख्य प्रशिक्षक हुन्।', 'nepali'),
      (v_set_id, 14, E'२०२५ मा नेपालमा मनाइएको राष्ट्रिय झण्डा दिवस कति औं राष्ट्रिय झण्डा दिवस हो?', E'८ औं', E'९ औं', E'१० औं', E'११ औं', 'B', E'विसं २०२५ मा नेपालमा मनाइएको राष्ट्रिय झण्डा दिवस **९ औं** संस्करणको हो।\n- नेपालमा राष्ट्रिय झण्डा दिवस हरेक वर्ष पुस १ गते मनाइन्छ।\n- यो दिवस सन् १९६२ डिसेम्बर १६ (विसं २०१ ९ पुस १ गते) मा संयुक्त राष्ट्रसंघमा नेपालको राष्ट्रिय झण्डालाई विश्वव्यापी रूपमा अंगीकृत गरेको दिनको स्मरणमा विसं २०७५ देखि मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 15, E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा सर्वाधिक रन बनाउने नेपाली खेलाडी को हुन्?', E'विनोद भण्डारी', E'कुशल भुर्तेल', E'सन्दीप लामिछाने', E'रोहित पौडेल', 'D', E'**नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा सर्वाधिक रन बनाउने नेपाली खेलाडी रोहित पौडेल हुन्।**\n- विनोद भण्डारीले २६४ रन बनाएर सर्वाधिक रन बनाउने नेपाली खेलाडीमध्ये तेस्रो स्थानमा रहेका थिए।\n- सन्दीप लामिछानेले १७ विकेट लिएर सर्वाधिक विकेट लिने खेलाडीको सूचीमा प्रथम स्थान हासिल गरेका थिए।\n- कुशल भुर्तेलले यस संस्करणमा सर्वाधिक रन बनाउने शीर्ष तीन नेपाली खेलाडीमा स्थान बनाउन सकेनन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/०३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_06.csv  →  आसमान दैनिक GK — २०८२/०९/०६  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/०६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/०६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/०६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'माछापुच्छ्रे हिमालको उचाइ कति रहेको छ ?', E'६९९३ मिटर', E'६९९७ मिटर', E'७०५९ मिटर', E'७०३५ मिटर', 'A', E'माछापुच्छ्रे हिमालको उचाइ **६९९३ मिटर** रहेको छ। यो अन्नपूर्ण हिमशृंखला अन्तर्गत कास्की जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 2, E'विशाल नेपालको सिमाना कसको पालामा मेचीदेखि महाकालीसम्म खुम्चिएको थियो ?', E'गिर्वाणयुद्ध शाह', E'रणोदिप सिंह', E'जंग बहादुर राणा', E'पृथ्वी नारायण शाह', 'A', E'विशाल नेपालको सिमाना मेचीदेखि महाकालीसम्म खुम्चिने कार्य **गिर्वाणयुद्ध शाह**को पालामा भएको थियो। यो सन् १८१६ मार्च ३ (१८७२ फागुन २४) मा भएको सुगौली सन्धिपश्चात् भएको हो।\nनोट: सुगौली सन्धिमा नेपालको तर्फबाट गजराज मिश्र र अङ्ग्रेजको तर्फबाट लेफ्टिनेन्ट ब्राड्सले हस्ताक्षर गरेका थिए।', 'nepali'),
      (v_set_id, 3, E'संयुक्त राष्ट्र संघमा मान्यता प्राप्त ६ भाषाको सूचीमा देहायको कुन भाषा पर्दैन ?', E'फ्रेन्च', E'स्पेनीस', E'जापानीज', E'अरबी', 'C', E'संयुक्त राष्ट्र संघमा मान्यता प्राप्त ६ भाषाको सूचीमा **जापानीज** भाषा पर्दैन।\n- संयुक्त राष्ट्र संघका आधिकारिक भाषाहरू स्पेनीस, रुसी, फ्रेन्च, अरबी, चिनियाँ र अंग्रेजी हुन्।', 'nepali'),
      (v_set_id, 4, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा लैङ्गिक अनुपात कति रहेको छ ?', E'९५.२९ अनुपात', E'९५.१६ अनुपात', E'९४.९६ अनुपात', E'९४.२९ अनुपात', 'A', E'नेपालको राष्ट्रिय जनगणना, २०७८ अनुसार लैङ्गिक अनुपात **९५.२९** रहेको छ।\n- यस जनगणना अनुसार महिलाको जनसंख्या ५१.३३% (१ करोड ४९ लाख ११ हजार २७७) र पुरुषको जनसंख्या ४८.६७% (१ करोड ४२ लाख ५३ हजार ५५१) रहेको छ।', 'nepali'),
      (v_set_id, 5, E'Father of botany (वनस्पति विज्ञानका पिता)का रुपमा कुन वैज्ञानिकलाई चिनिन्छ ?', E'चार्ल्स डार्विन', E'एरिस्टोटल', E'रोबर्ट बोइल', E'थियोफ्रेक्टस', 'D', E'**थियोफ्रेक्टसलाई** वनस्पति विज्ञानका पिताका रुपमा चिनिन्छ।\n- चार्ल्स डार्विनलाई विकासवादका पिताका रुपमा चिनिन्छ।\n- एरिस्टोटललाई जीवविज्ञान, प्राणीविज्ञान र राजनीति विज्ञानका पिताका रुपमा चिनिन्छ।\n- रोबर्ट बोइललाई रसायन विज्ञानका पिताका रुपमा चिनिन्छ।', 'nepali'),
      (v_set_id, 6, E'लिच्छवि राजा गुणकामदेवले चलाएका जात्राहरु अन्तर्गत देहायको कुन जात्रा पर्दैन ?', E'श्रीभेरी जात्रा', E'कृष्ण जात्रा', E'हिले जात्रा', E'विस्केट जात्रा', 'D', E'लिच्छवि राजा गुणकामदेवले चलाएका जात्राहरु अन्तर्गत **विस्केट जात्रा** पर्दैन।\n- श्रीभेरी जात्रा, कृष्ण जात्रा र हिले जात्रा गुणकामदेवले चलाएका जात्राहरु हुन्।\n- विस्केट जात्रा जगज्योतिर्मल्लले चलाएको जात्रा हो।', 'nepali'),
      (v_set_id, 7, E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनसंख्याले बोल्ने भाषा कुन हो ?', E'नुराङ', E'कुसुन्डा', E'बनकारिया', E'राउटे', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनसंख्याले बोल्ने भाषा **कुसुन्डा** हो।\n- कुसुन्डा भाषा बोल्नेको संख्या २३ जना रहेको छ।\n- नुराङ नेपालमा सबैभन्दा कम जनसंख्या भएको जाति हो, जसको संख्या ३६ जना छ।', 'nepali'),
      (v_set_id, 8, E'हिमाली जिल्लामा स्तरोन्नति हुने सबैभन्दा पछिल्लो (कान्छो) हिमाली जिल्ला कुन हो ?', E'म्याग्दी', E'रुकुम पूर्व', E'गोर्खा', E'धादिङ', 'A', E'हिमाली जिल्लामा स्तरोन्नति हुने सबैभन्दा पछिल्लो (कान्छो) हिमाली जिल्ला **म्याग्दी** हो।\n- म्याग्दी जिल्ला २०७५ फागुन ११ गते पहाडी जिल्लाबाट हिमाली जिल्लामा स्तरोन्नति भएको थियो।\n- रामेछाप, धादिङ, गोर्खा र पूर्वी रुकुम जिल्लाहरू २०७४ भदौ २८ गते पहाडबाट हिमालमा स्तरोन्नति भएका थिए।', 'nepali'),
      (v_set_id, 9, E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार नेपालमा पहाडी जिल्लाका रुपमा कति जिल्ला सुनिश्चित गरेको छ ?', E'३५ जिल्ला', E'२१ जिल्ला', E'२८ जिल्ला', E'३२ जिल्ला', 'C', E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार नेपालमा पहाडी जिल्लाका रुपमा **२८ जिल्ला** सुनिश्चित गरिएको छ।\n- यो ऐन २०७४ असोज २९ गते प्रमाणीकरण भएको थियो।', 'nepali'),
      (v_set_id, 10, E'नेपालको प्रमाणिक समय सन्दर्भमा गौरीशंकर हिमाललाई काटेर गएको कति ° देशान्तरलाई आधार मानिएको छ?', E'86° 15''', E'85° 15''', E'85° 25''', E'86° 25''', 'D', E'नेपालको प्रमाणिक समय गौरीशंकर हिमाललाई काटेर गएको **८६° २५''** पूर्वी देशान्तरलाई आधार मानिएको छ। यो समय वि.सं. २०४२ साल वैशाख १ गतेबाट लागू भएको हो।\nनोट: गौरीशंकर हिमालको उचाइ ७,१३४ मिटर रहेको छ र यो दोलखा जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 11, E'प्रसिद्ध मन्दिर बौद्धनाथको स्थापना गर्ने लिच्छवि राजा को हुन्?', E'शिवदेव', E'नरेन्द्रदेव', E'प्रचण्डदेव', E'अंशुवर्मा', 'A', E'**प्रसिद्ध बौद्धनाथ मन्दिरको स्थापना लिच्छवि राजा शिवदेवले गरेका थिए।**\n- अंशुवर्माले कैलाशकुट भवनको निर्माण गरेका थिए।\n- नरेन्द्रदेवले प्रसिद्ध भद्राधिवासको भवनको निर्माण गरेका थिए।\n- प्रचण्डदेव पशुपतिनाथको मन्दिर स्थापना गर्ने राजाका रूपमा चिनिन्छन्।', 'nepali'),
      (v_set_id, 12, E'लेप्चा जातिको मुख्य बसोबास क्षेत्र जिल्ला कुन हो?', E'दोलखा', E'ताप्लेजुङ', E'धनकुटा', E'इलाम', 'D', E'लेप्चा जातिको मुख्य बसोबास क्षेत्र **इलाम** जिल्ला हो।\nनोट: लेप्चा जातिमा दुलहाले ६ महिनासम्म ससुरालीमै बस्नुपर्ने, तेस्रो दिनमा रक्सी खुवाएर सुत्केरी चोख्याउने र ढोली प्रथा प्रचलनमा रहेको छ।', 'nepali'),
      (v_set_id, 13, E'द लास्ट जजमेन्टको द्वारा निर्मित विश्व प्रख्यात चित्र हो?', E'माइकल एन्जेलो', E'लियोनार्दो दा भिन्ची', E'मेकियाभेली', E'दाँते', 'A', E'**द लास्ट जजमेन्ट (The Last Judgment) माइकल एन्जेलोद्वारा निर्मित विश्व प्रख्यात चित्र हो।**\n- लियोनार्दो दा भिन्चीले द लास्ट सपर (The Last Supper) र मोनालिसा (Mona Lisa) जस्ता चित्रहरू बनाएका थिए।\n- मेकियाभेली द प्रिन्स (The Prince) नामक पुस्तकका लेखक हुन्।\n- दाँते डिभाइन कमेडी (Divine Comedy) का लेखक हुन्।', 'nepali'),
      (v_set_id, 14, E'नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो आसियान मुलुक कुन हो?', E'सिंगापुर', E'मलेसिया', E'थाइल्यान्ड', E'इन्डोनेसिया', 'C', E'नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो आसियान मुलुक **थाइल्यान्ड** हो।\nनोट: नेपालले थाइल्यान्डसँग सन् १९५९ नोभेम्बर ३० मा दौत्य सम्बन्ध कायम गरेको थियो। ब्रुनाई नेपालसँग दौत्य सम्बन्ध राख्ने अन्तिम आसियान मुलुक हो, जससँग सन् १९८४ फेब्रुअरी ३ मा सम्बन्ध कायम भएको थियो।', 'nepali'),
      (v_set_id, 15, E'आर्थिक तथा सामाजिक परिषदका सदस्य मध्ये कति सदस्यहरु एसिया महादेशका रहेको हुन्छन् ?', E'१२ मुलुक', E'११ मुलुक', E'१३ मुलुक', E'१४ मुलुक', 'B', E'संयुक्त राष्ट्रसंघको आर्थिक तथा सामाजिक परिषद (ECOSOC) मा एसिया महादेशबाट **११ मुलुक** सदस्य रहेका छन्। यस परिषदमा कुल ५४ सदस्य राष्ट्रहरू हुन्छन्।\nनोट: सदस्य राष्ट्रहरूको क्षेत्रीय वितरण यस प्रकार छ:\n- अफ्रिका: १४ मुलुक\n- पश्चिम युरोप तथा अन्य: १३ मुलुक\n- एसिया: ११ मुलुक\n- ल्याटिन अमेरिका: १० मुलुक\n- पूर्वी युरोप: ६ मुलुक', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/०६', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_07.csv  →  आसमान दैनिक GK — २०८२/०९/०७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/०७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/०७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/०७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'तलका मध्ये कुन महादेशमा भूपरिवेष्ठित मुलुक छैनन् ?', E'युरोप', E'अफ्रिका', E'दक्षिण अमेरिका', E'उत्तर अमेरिका', 'D', E'**उत्तर अमेरिका महादेशमा भूपरिवेष्ठित मुलुक छैनन्।**\n- अफ्रिका महादेशमा १६ वटा भूपरिवेष्ठित मुलुक छन्।\n- दक्षिण अमेरिका महादेशमा २ वटा भूपरिवेष्ठित मुलुक छन् (बोलिभिया र पाराग्वे)।\n- युरोप महादेशमा १९ वटा भूपरिवेष्ठित मुलुक छन्।\nनोट: अन्टार्कटिका र अष्ट्रेलिया पनि भूपरिवेष्ठित राष्ट्रविहीन महादेश हुन्।', 'nepali'),
      (v_set_id, 2, E'कुन किरात राजाका पालामा गौतम बुद्ध काठमाडौँ आएका थिए ?', E'यलम्बर', E'जितेदास्ति', E'स्थंको', E'हुमती', 'B', E'**गौतम बुद्ध किरात राजा जितेदास्तिको पालामा काठमाडौँ आएका थिए।**\n- यलम्बर किरात वंशका प्रथम राजा थिए।\n- स्थंको किरात वंशका २३औं राजा थिए।\n- हुमती किरात वंशका २८औं राजा थिए।\nनोट: भाषा वंशावलीहरूले जितेदास्तिलाई सातौँ क्रममा राखेका छन् र उनको समयमा गौतम बुद्ध काठमाडौँ आएको चर्चा वंशावलीमा गरिएको छ।', 'nepali'),
      (v_set_id, 3, E'नेपाल सरकार र माओवादी बीच विस्तृत शान्ति सम्झौता कहिले भयो ?', E'२०६३ मंसिर ५', E'२०६३ बैशाख ११', E'२०६३ माघ १', E'२०६३ चैत २८', 'A', E'नेपाल सरकार र तत्कालीन नेकपा (माओवादी) बीच विस्तृत शान्ति सम्झौता **२०६३ मंसिर ५** गते भएको थियो। यस सम्झौताले नेपालमा दशक लामो सशस्त्र द्वन्द्वको अन्त्य गरेको थियो।', 'nepali'),
      (v_set_id, 4, E'दिगो विकासको लक्ष्य नं. ५ के सँग सम्बन्धित रहेको छ ?', E'गरिबीको अन्त्य', E'गुणस्तरीय शिक्षा', E'लैंगिक समानता', E'सु स्वास्थ्य जीवन', 'C', E'**दिगो विकासको लक्ष्य नं. ५ लैंगिक समानता र महिला तथा बालबालिकाको सशक्तीकरणसँग सम्बन्धित छ।**\n- गरिबीको अन्त्य दिगो विकासको लक्ष्य नं. १ हो।\n- गुणस्तरीय शिक्षा दिगो विकासको लक्ष्य नं. ४ हो।\n- सु स्वास्थ्य जीवन दिगो विकासको लक्ष्य नं. ३ हो।', 'nepali'),
      (v_set_id, 5, E'कुन समुद्रको सिमानाले तीनवटा महादेश छोएको छ ?', E'क्यारेबियन सागर', E'मेडिटेरियन सागर', E'क्यास्पियन सागर', E'ब्ल्याक सागर', 'B', E'**मेडिटेरियन सागरको सिमानाले अफ्रिका, एसिया र युरोप गरी तीनवटा महादेश छोएको छ।**\n- क्यारेबियन सागरले उत्तर र दक्षिण अमेरिका महादेशलाई छुन्छ।\n- क्यास्पियन सागर युरोप र एसियाको बीचमा अवस्थित छ।\n- ब्ल्याक सागरले युरोप र एसिया महादेशलाई छुन्छ।', 'nepali'),
      (v_set_id, 6, E'सरयै नाच के सँग सम्बन्धित रहेको छ ?', E'माया तथा प्रेम', E'खेतीपाती भित्र्याउने', E'विवाह व्रतबन्ध', E'युद्ध अभ्यास', 'D', E'**सरयै नाच युद्ध अभ्याससँग सम्बन्धित एक परम्परागत नाच हो।**\n- यो नाच गुल्मी, अर्घाखाँची, प्युठान, पाल्पा र कपिलवस्तुका शक्तिपीठमा दशैंको भोलिपल्टबाट पूर्णिमासम्म नाच्ने प्रचलन छ।', 'nepali'),
      (v_set_id, 7, E'कुन संरक्षण क्षेत्र वन्यजन्तु आरक्ष अन्तर्गत पर्दछ ?', E'गौरीशंकर', E'कोशीटप्पु', E'खप्तड', E'ढोरपाटन', 'B', E'**कोशीटप्पु वन्यजन्तु आरक्ष नेपालको एक वन्यजन्तु आरक्ष हो।**\n- गौरीशंकर संरक्षण क्षेत्र, खप्तड राष्ट्रिय निकुञ्ज र ढोरपाटन शिकार आरक्ष अन्य प्रकारका संरक्षण क्षेत्र हुन्।\nनोट: कोशीटप्पु वन्यजन्तु आरक्ष सुनसरी जिल्लामा पर्दछ र यसको स्थापना २०३२ सालमा भएको थियो।', 'nepali'),
      (v_set_id, 8, E'गुरुँस हिमश्रृंखला अन्तर्गत कुन हिमाल पर्छ ?', E'गणेश', E'चामर', E'अपि', E'तिलिचो', 'C', E'**अपि हिमाल गुरुँस हिमश्रृंखला अन्तर्गत पर्दछ।**\n- गणेश हिमाल लाङटाङ हिमश्रृंखलामा पर्दछ।\n- चामर हिमाल धौलागिरी हिमश्रृंखलामा पर्दछ।\n- तिलिचो हिमाल अन्नपूर्ण हिमश्रृंखलामा पर्दछ।\nनोट: अपि हिमाल दार्चुला जिल्लाको सबैभन्दा अग्लो भाग हो र यसको उचाई ७,१३२ मिटर (२३,३९९ फिट) रहेको छ।', 'nepali'),
      (v_set_id, 9, E'UNO बडापत्र कहिले देखि कार्यान्वयनमा आएको हो ?', E'२६ जुन १९४५', E'२४ सेप्टेम्बर १९४६', E'१५ अक्टोबर १९४५', E'२४ अक्टोबर १९४५', 'D', E'संयुक्त राष्ट्र संघको बडापत्र **२४ अक्टोबर १९४५** देखि कार्यान्वयनमा आएको हो। यो बडापत्र संयुक्त राष्ट्र संघको संस्थापक दस्तावेज हो।\nनोट: यो बडापत्र २६ जुन १९४५ मा सान फ्रान्सिस्कोमा संयुक्त राष्ट्र संघको अन्तर्राष्ट्रिय संगठन सम्मेलनको समापनमा हस्ताक्षर भएको थियो।', 'nepali'),
      (v_set_id, 10, E'संयुक्त राष्ट्रसंघको कुन विशिष्टीकृत संस्था त्रिपक्षीय संयन्त्रमा आधारित रहेको छ ?', E'खाद्य तथा कृषि संगठन', E'अन्तर्राष्ट्रिय श्रम संगठन', E'विश्व स्वास्थ्य संगठन', E'शैक्षिक वैज्ञानिक तथा सांस्कृतिक संगठन', 'B', E'**अन्तर्राष्ट्रिय श्रम संगठन (ILO) त्रिपक्षीय संयन्त्रमा आधारित संयुक्त राष्ट्र संघको एकमात्र विशिष्टीकृत संस्था हो।**\n- खाद्य तथा कृषि संगठन (FAO) खाद्य सुरक्षा र कृषि विकासमा केन्द्रित छ।\n- विश्व स्वास्थ्य संगठन (WHO) अन्तर्राष्ट्रिय जनस्वास्थ्यको समन्वय गर्दछ।\n- शैक्षिक वैज्ञानिक तथा सांस्कृतिक संगठन (UNESCO) शिक्षा, विज्ञान र संस्कृतिको क्षेत्रमा काम गर्दछ।\nनोट: अन्तर्राष्ट्रिय श्रम संगठनमा सरकार, रोजगारदाता र कामदार प्रतिनिधिहरू सहभागी हुन्छन्।', 'nepali'),
      (v_set_id, 11, E'नेपालको देहायको कुन मुलुकसँग बिप्पा सम्झौता भएको छैन ?', E'चीन', E'जर्मनी', E'भारत', E'बेलायत', 'A', E'**नेपालको चीनसँग बिप्पा (BIPPA) सम्झौता भएको छैन।**\n- जर्मनीसँग नेपालको बिप्पा सम्झौता भएको छ।\n- भारतसँग नेपालको बिप्पा सम्झौता भएको छ।\n- बेलायतसँग नेपालको बिप्पा सम्झौता भएको छ।\nनोट: नेपालले हालसम्म फ्रान्स, भारत, फिनल्याण्ड, मौरिसस, जर्मनी र बेलायत गरी ६ वटा मुलुकसँग मात्र बिप्पा सम्झौता गरेको छ।', 'nepali'),
      (v_set_id, 12, E'नेपालको प्रमाणिक समय कुन हो ?', E'UTC +6:00', E'UTC +5:45', E'UTC +5:30', E'UTC +4:45', 'B', E'नेपालको प्रमाणिक समय **UTC +5:45** हो।\n- नेपालको समय ग्रीनवीचको समयभन्दा ५ घण्टा ४५ मिनेट चलाख रहेको छ।\nनोट: यो समय वि.सं. २०४२ साल वैशाख १ गतेबाट लागू भएको हो र गौरीशंकर हिमाललाई आधार मानेर निर्धारण गरिएको छ।', 'nepali'),
      (v_set_id, 13, E'सबैभन्दा कम उमेरमा प्रधानमन्त्री भएका नेपालका राणा प्रधानमन्त्री को हुन् ?', E'जंग ब राणा', E'देव सम्सेर', E'मोहन सम्सेर', E'भीमसेन थापा', 'A', E'**जंगबहादुर राणा नेपालका राणा प्रधानमन्त्रीहरूमध्ये सबैभन्दा कम उमेरमा (२८ वर्षको उमेरमा) प्रधानमन्त्री बनेका थिए।**\n- देव शमशेर राणा प्रधानमन्त्रीहरूमध्ये सबैभन्दा छोटो कार्यकाल (११४ दिन) भएका प्रधानमन्त्री हुन्।\n- मोहन शमशेर राणा शासनका अन्तिम प्रधानमन्त्री थिए।\n- भीमसेन थापा नेपालका प्रथम मुख्तियार तथा सबैभन्दा लामो समयसम्म प्रधानमन्त्री पदमा रहेका व्यक्ति हुन्।', 'nepali'),
      (v_set_id, 14, E'देहायका मध्ये कुन कुण्ड बझाङ जिल्लामा अवस्थित रहेको छ ?', E'पाप कुण्ड', E'नारद कुण्ड', E'निहारी कुण्ड', E'ज्ञान कुण्ड', 'C', E'**निहारी कुण्ड बझाङ जिल्लामा अवस्थित छ।**\n- पाप कुण्ड मुगु जिल्लामा रहेको छ।\n- नारद कुण्ड गोरखा जिल्लामा पर्दछ।\n- ज्ञान कुण्ड धनुषा जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 15, E'राष्ट्रिय जनगणना अनुसार, नेपालको जनसंख्या बृद्धिदर कति प्रतिशत रहेको छ ?', E'२.२५ %', E'१.३५ %', E'०.९२ %', E'०.८२ %', 'C', E'**राष्ट्रिय जनगणना २०७८ अनुसार नेपालको जनसंख्या वृद्धिदर **०.९२ प्रतिशत रहेको छ।\n- जनगणना २०६८ मा नेपालको जनसंख्या २,६४,९४,५०४ थियो भने जनगणना २०७८ मा २,९१,६४,५७८ पुगेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/०७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_08.csv  →  आसमान दैनिक GK — २०८२/०९/०८  (14 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/०८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/०८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/०८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'समसामयिक विशेष सम्बन्धमा तलकामध्ये कुन चाहीँ सही हो? पहिचान गर्नुहोस्। i. २०७२ पुस १ गते देखि बाघ गणना २०७२ सञ्चालित भएको छ। ii. २०७२ मा सञ्चालित बाघ गणना चौथो हो। iii. नेपालमा प्रत्येक ४ वर्षमा बाघको गणना हुने गर्छ। iv. हाल नेपालमा सबैभन्दा धेरै बाघ पाइने राष्ट्रिय निकुञ्ज बर्दिया हो।', E'iii र iv मात्र सही', E'i, iii र iv मात्र सही', E'i, ii र iv मात्र सही', E'i र iii मात्र सही', 'D', E'नेपालमा बाघ गणना प्रत्येक **४ वर्षमा** हुने गर्छ। २०७२ पुस १ गतेदेखि फागुनसम्म सञ्चालित बाघ गणना पाँचौँ हो। हाल नेपालमा सबैभन्दा धेरै बाघ चितवन राष्ट्रिय निकुञ्जमा पाइन्छन्।', 'nepali'),
      (v_set_id, 2, E'वि.सं. २००७ साल पूर्व नेपालको दौत्य सम्बन्ध भएका मुलुकहरू बिच जोडा मिलाउनुहोस्। १. बेलायत २. अमेरिका ३. भारत ४. फ्रान्स (क) वि.सं. २००६ वैशाख ८ (ख) वि.सं. २००४ जेठ ३१ (ग) वि.सं. २००४ वैशाख १२ (घ) वि.सं. १९८९', E'१क, २ख, ३ग, ४घ', E'१घ, २ख, ३ग', E'१ग, २घ, ३ख, ४क', E'१घ, २ग, ३ख, ४क', 'B', E'नेपाल र बेलायतबीच वि.सं. **१९८९** मा दौत्य सम्बन्ध स्थापित भएको थियो।\n- नेपाल र अमेरिकाबीच वि.सं. २००४ जेठ ३१ मा दौत्य सम्बन्ध कायम भएको थियो।\n- नेपाल र भारतबीच वि.सं. २००४ वैशाख १२ मा दौत्य सम्बन्ध कायम भएको थियो।\n- नेपाल र फ्रान्सबीच वि.सं. २००६ वैशाख ८ मा दौत्य सम्बन्ध कायम भएको थियो।', 'nepali'),
      (v_set_id, 3, E'एउटा वयस्क मानव शरीरको तात्विक संरचना पिण्ड अनुसार निम्नमध्ये कुन क्रम सही हो?', E'अक्सिजन, कार्बन, नाइट्रोजन, हाइड्रोजन', E'कार्बन, नाइट्रोजन, हाइड्रोजन, अक्सिजन', E'कार्बन, हाइड्रोजन, नाइट्रोजन, अक्सिजन', E'अक्सिजन, कार्बन, हाइड्रोजन, नाइट्रोजन', 'D', E'मानव शरीरमा पिण्डको आधारमा पाइने प्रमुख तत्वहरूको सही क्रम **अक्सिजन, कार्बन, हाइड्रोजन र नाइट्रोजन** हो। अक्सिजनले शरीरको लगभग ६५% र कार्बनले १८.५% हिस्सा ओगटेको हुन्छ।\nनोट: यी चार तत्वहरूले मात्र मानव शरीरको कुल पिण्डको लगभग ९६% हिस्सा ओगट्छन्।', 'nepali'),
