    VALUES
      (v_set_id, 1, E'विश्व भूगोलका महासागर मध्ये दोस्रो गहिरो महासागर कुन हो?', E'हिन्द', E'आन्द्र', E'कुमेरु', E'सुमेरु', 'B', E'**आन्द्र महासागर** विश्व भूगोलका महासागरहरू मध्ये दोस्रो गहिरो महासागर हो। प्रशान्त महासागरको औसत गहिराइ ४३०० मिटर, आन्द्र महासागरको ३७०० मिटर र हिन्द महासागरको ३९०० मिटर रहेको छ।', 'nepali'),
      (v_set_id, 2, E'फागुन शुक्ल पूर्णिमामा देहायका मध्ये कुन पर्व मनाईन्छ?', E'श्रीपञ्चमी', E'होली', E'महाशिवरात्री', E'घोडेजात्रा', 'B', E'**फागुन शुक्ल पूर्णिमामा होली पर्व मनाइन्छ।**\n- श्रीपञ्चमी वा सरस्वती जयन्ती माघ शुक्ल पञ्चमीमा मनाइन्छ।\n- महाशिवरात्री फागुन कृष्ण चतुर्दशीमा पर्दछ।\n- घोडेजात्रा चैत्र कृष्ण चतुर्दशीमा मनाइन्छ।', 'nepali'),
      (v_set_id, 3, E'लोकसेवा आयोगको सदस्यहरूको सिफारिस कसले गर्ने गर्दछ ?', E'प्रधानमन्त्री', E'राष्ट्रपति', E'संवैधानिक परिषद', E'आयोग अध्यक्ष', 'C', E'लोकसेवा आयोगका सदस्यहरूको सिफारिस **संवैधानिक परिषदले** गर्ने गर्दछ।\n- संवैधानिक परिषदको सिफारिसमा राष्ट्रपतिले लोकसेवा आयोगका अध्यक्ष र सदस्यहरूलाई नियुक्त गर्दछन्।', 'nepali'),
      (v_set_id, 4, E'नेपालमा उर्जा दिवस कहिले मनाइन्छ ?', E'जेठ ९', E'जेठ १०', E'जेठ ११', E'जेठ १२', 'A', E'**नेपालमा उर्जा दिवस जेठ ९ गते मनाइन्छ।**\n- नेपालमा पहिलो बिजुली बत्ती वि.सं. १९६८ जेठ ९ गते बलेको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपालमा हालसम्म Plan Holiday वर्ष कति वटा रहेको छ ?', E'१ वटा', E'२ वटा', E'४ वटा', E'३ वटा', 'D', E'**नेपालमा हालसम्म ३ वटा Plan Holiday वर्ष रहेका छन्।**\n- पहिलो Plan Holiday वर्ष २०१७ मा थियो भने दोस्रो र तेस्रो Plan Holiday वर्ष क्रमशः २०४७ र २०४८ मा थिए।', 'nepali'),
      (v_set_id, 6, E'Rio+5 सम्मेलन कुन मुलुकमा सम्पन्न भएको हो ?', E'दक्षिण अफ्रिका', E'ब्राजिल', E'जापान', E'इन्डोनेसिया', 'C', E'**Rio+5 सम्मेलन जापानको क्योटोमा सन् १९९७ मा सम्पन्न भएको थियो।**\n- ब्राजिलको रियो दि जेनेरियोमा सन् १९९२ मा Rio सम्मेलन र सन् २०१२ मा Rio+20 सम्मेलन भएको थियो।\n- दक्षिण अफ्रिकाको जोहानसवर्गमा सन् २००२ मा Rio+10 सम्मेलन सम्पन्न भएको थियो।\n- इन्डोनेसियाको बालिमा सन् २००७ मा Rio+15 सम्मेलन सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 7, E'सार्क बडापत्रमा कति मुलुकको हस्ताक्षर रहेको छ ?', E'६ मुलुक', E'८ मुलुक', E'७ मुलुक', E'५ मुलुक', 'C', E'**सार्क बडापत्रमा ७ मुलुकका प्रतिनिधिले हस्ताक्षर गरेका थिए।**\n- सार्कको स्थापनाकालिन ७ सदस्य राष्ट्रका प्रतिनिधिले सन् १९८५ डिसेम्बर ८ मा बडापत्रमा हस्ताक्षर गरेका हुन्।', 'nepali'),
      (v_set_id, 8, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा बसाईंसराई गरेको जनसंख्या प्रतिशत कति रहेको छ ?', E'३५.०३ प्रतिशत', E'३३.०३ प्रतिशत', E'३४.०३ प्रतिशत', E'३२.०३ प्रतिशत', 'D', E'**राष्ट्रिय जनगणना २०७८ अनुसार नेपालमा ३२.०३ प्रतिशत जनसंख्याले बसाईं सरेको देखिन्छ।**\n- बसाईंसराई गर्नेको कुल संख्या ९३,४१,४०८ रहेको छ र यसको मुख्य कारण विवाह (३६.२%) रहेको छ।', 'nepali'),
      (v_set_id, 9, E'हालसम्ममा नेपालमा भएका जनगणना मध्ये सबैभन्दा धेरै जनसंख्या वृद्धिरदर रहेको जनगणना कुन हो ?', E'२०३८ सालको', E'२००८ सालको', E'२०६८ सालको', E'२०७८ सालको', 'A', E'नेपालमा हालसम्म भएका जनगणनाहरूमध्ये **२०३८ सालको जनगणनामा** सबैभन्दा धेरै जनसंख्या वृद्धिदर (२.६२ प्रतिशत) रहेको थियो।\nनोट: २०७८ सालको जनगणना अनुसार नेपालको जनसंख्या वृद्धिदर ०.९२ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 10, E'सबैभन्दा धेरै अवधी महासचिव भएका संयुक्त राष्ट्रसंघका महासचिव को हुन् ?', E'ट्रिभेली', E'कोफी अन्नान', E'उथान्त', E'बुक्रोस बुक्रोस घाली', 'C', E'**उथान्त संयुक्त राष्ट्रसंघका सबैभन्दा धेरै अवधिसम्म महासचिव रहेका व्यक्ति हुन्।**\n- कोफी अन्नान कार्यकाल समाप्त भएपछि अवकाश पाउने महासचिव हुन्।\n- ट्रिभेली संयुक्त राष्ट्रसंघमा राजिनामा दिने पहिलो महासचिव हुन्।\n- बुक्रोस बुक्रोस-घालीको कार्यकाल थप नभएको र छोटो समय महासचिव रहेका थिए।\nनोट: उथान्त ११ वर्षसम्म संयुक्त राष्ट्रसंघको महासचिव रहेका थिए।', 'nepali'),
      (v_set_id, 11, E'शाहवंशीय राजाहरूमा नामको पछाडि विक्रम थप्ने पहिलो राजा को हुन् ?', E'गिर्वाणयुद्ध विक्रम शाह', E'त्रैलोक्य विक्रम शाह', E'राजेन्द्र विक्रम शाह', E'त्रिभुवन विक्रम शाह', 'A', E'**शाहवंशीय राजाहरूमा नामको पछाडि ''विक्रम'' थप्ने पहिलो राजा गिर्वाणयुद्ध विक्रम शाह हुन्।**\n- राजेन्द्र विक्रम शाह नेपालका एक महत्वपूर्ण शाहवंशीय राजा थिए, जसको पालामा कोत पर्व भएको थियो।\n- त्रिभुवन विक्रम शाह नेपालका दशौं शाहवंशीय राजा हुन्, जसले राणा शासनको अन्त्यमा महत्वपूर्ण भूमिका खेलेका थिए।\n- त्रैलोक्य विक्रम शाह युवराज थिए र उनको निधनपछि उनका छोरा पृथ्वीवीर विक्रम शाह राजा बनेका थिए।\nनोट: सुगौली सन्धि गिर्वाणयुद्ध विक्रम शाहकै पालामा भएको थियो।', 'nepali'),
      (v_set_id, 12, E'नेपालको भूगोलमा देहायका धेरै खेतीयोग्य भूमि रहेको माटो कुन हो ?', E'तल्लैया माटो', E'पाँगो माटो', E'हिमाली माटो', E'बलौटे माटो', 'B', E'**नेपालको भूगोलमा पाँगो माटोमा धेरै खेतीयोग्य भूमि रहेको पाइन्छ।**\n- बलौटे पथ्थरिलो माटो भावर प्रदेश, भित्री मधेस र चुरे पहाडमा पाइन्छ।\n- रातो फुस्रो माटो महाभारतका टाढा भिरहरूमा पाइन्छ।\n- तल्लैया माटो उपत्यकामा पाइन्छ।\n- हिमाली माटो हिमाली क्षेत्रमा पाइन्छ।', 'nepali'),
      (v_set_id, 13, E'ठूलोभेरी नदिको उद्गम देहायका मध्ये कुन हिमालबाट हुने गर्दछ ?', E'अपि हिमाल', E'धौलागिरी हिमाल', E'सैपाल हिमाल', E'मुकुट हिमाल', 'D', E'ठूलोभेरी नदीको उद्गम **मुकुट हिमालबाट** हुने गर्दछ।\n- सानो भेरी नदीको उद्गम धौलागिरी हिमालबाट हुन्छ।', 'nepali'),
      (v_set_id, 14, E'विश्व व्यापार संगठन (WTO) को प्रधान कार्यालय कहाँ रहेको छ ?', E'हेग', E'न्युयोर्क', E'पेरिस', E'जेनेभा', 'D', E'**विश्व व्यापार संगठन (WTO) को प्रधान कार्यालय स्वीट्जरल्याण्डको जेनेभामा रहेको छ।**\n- हेगमा अन्तर्राष्ट्रिय न्यायालय (International Court of Justice) को प्रधान कार्यालय छ।\n- न्युयोर्कमा संयुक्त राष्ट्र संघ (United Nations) को प्रधान कार्यालय छ।\n- पेरिसमा संयुक्त राष्ट्र शैक्षिक, वैज्ञानिक तथा सांस्कृतिक संगठन (UNESCO) को प्रधान कार्यालय छ।\nनोट: विश्व व्यापार संगठनको स्थापना १ जनवरी १९९५ मा भएको थियो र नेपाल यसको १४७औँ सदस्य मुलुकको रूपमा २३ अप्रिल २००४ मा आबद्ध भएको थियो।', 'nepali'),
      (v_set_id, 15, E'अति सिमान्तकृत समूहमा सुचिकृत जनजातिको संख्या कति रहेको छ ?', E'१५ जनजाति', E'२१ जनजाति', E'१२ जनजाति', E'१० जनजाति', 'C', E'**आदिवासी जनजाति उत्थान प्रतिष्ठान ऐन, २०५८ अनुसार अति सिमान्तकृत समूहमा **१२ जनजाति सूचीकृत छन्।\n| समूह | संख्या |\n| --- | --- |\n| लोपोन्मुख समूह | १० |\n| अति सिमान्तकृत समूह | १२ |\n| सिमान्तकृत समूह | २० (र अन्य १ राणाथारु) |\n| सुविधाविहिन समूह | १५ |\n| उन्नत समूह | २ (थकाली र नेवारी) |\nनोट: उक्त ऐनले जम्मा ६० जनजाति समूहलाई विभिन्न वर्गमा वर्गीकरण गरेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/१०', 15;
END $$;

