  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/११', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाल सरकारद्वारा उपहारस्वरूप कतार पठाइएका दुई हात्तीहरू रुद्रकली र खगेन्द्रप्रसाद कतारको कुन स्थानमा राखिने भएको छ ?', E'एस्पायर पार्क', E'बलदना पार्क', E'अलखोर पार्क', E'बल बिदा पार्क', 'C', E'नेपाल सरकारले कतारका राजा अमिर शेख तममिम बिन हमाद अल थानीको नेपाल भ्रमणका अवसरमा उपहार दिएका रुद्रकली र खगेन्द्रप्रसाद नामक दुई हात्तीहरू कतारको **अलखोर पार्क** स्थित चिडियाखानामा राखिएका छन्। यी हात्तीहरू सौराहाको हात्ती प्रजनन तथा तालिम केन्द्र खोरसोरमा जन्मेहुर्केका रोनाल्डो हात्तीका सन्तान हुन्।', 'nepali'),
      (v_set_id, 2, E'फिफाको उत्कृष्ट खेलाडी,२०२५ घोषित हुन सफल खेलाडी को हुन्?', E'भिनिसियस जुनियर', E'ओसमान डेम्बेले', E'रोड्री', E'लियोनल मेस्सी', 'B', E'कतारमा आयोजित कार्यक्रमबीच फ्रान्सेली खेलाडी **ओसमन डेम्बेले** फिफाको उत्कृष्ट खेलाडी, २०२५ घोषित भएका थिए। महिलातर्फ बार्सिलोनाकी आइटना बोनमती उत्कृष्ट खेलाडी रहिन्।', 'nepali'),
      (v_set_id, 3, E'फिफा अरब कप, २०२४ को उपाधि कुन मुलुकले प्राप्त गरेको छ ?', E'जोर्डन', E'मोरक्को', E'इराक', E'कतार', 'B', E'**सन् २०२४ को फिफा अरब कपको उपाधि मोरक्कोले जितेको थियो।**\n- जोर्डन उपविजेता बनेको थियो, फाइनलमा मोरक्कोसँग ३-२ ले पराजित भएको थियो।\n- इराकले सर्वाधिक ४ पटक फिफा अरब कपको उपाधि जितेको छ।\n- कतारले सन् २०२४ नोभेम्बर २५ देखि डिसेम्बर १९ सम्म फिफा अरब कप २०२४ को आयोजना गरेको थियो।', 'nepali'),
      (v_set_id, 4, E'विश्व ध्यान दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'डिसेम्बर २१', E'डिसेम्बर २२', E'डिसेम्बर २३', E'डिसेम्बर २४', 'A', E'विश्व ध्यान दिवस प्रत्येक वर्ष **डिसेम्बर २१** तारिखमा मनाइन्छ।\n- संयुक्त राष्ट्रसंघले सन् २०२४ डिसेम्बर ७ तारिखमा डिसेम्बर २१ लाई आधिकारिक रूपमा विश्व ध्यान दिवसको मान्यता दिएको थियो र सन् २०२४ देखि यो दिवस मनाउन थालिएको हो।\nनोट: दोस्रो ध्यान दिवस २०२५ को नारा ''Inner Peace – Outer Peace World Peace'' रहेको छ।', 'nepali'),
      (v_set_id, 5, E'पहिलो साफ महिला क्लब च्याम्पियनसिप, २०२४ को विजेता टिम कुन हो ?', E'इस्ट बंगाल, भारत', E'एपीएफ, नेपाल', E'मुम्बई क्लब, भारत', E'नेपाल आर्मी क्लब', 'A', E'**पहिलो साफ महिला क्लब च्याम्पियनसिप, २०२४ को विजेता इस्ट बंगाल क्लब, भारत हो।**\n- एपीएफ, नेपाल उपविजेता बनेको थियो, फाइनलमा इस्ट बंगाल क्लबसँग ३-० ले पराजित भएको थियो।\n- यो च्याम्पियनसिप सन् २०२४ डिसेम्बर ५ देखि डिसेम्बर २० सम्म काठमाडौं, नेपालमा सञ्चालन भएको थियो।\nनोट: यस प्रतियोगितामा कुल ५ टिम सहभागी थिए र सर्वाधिक गोलकर्ता फजिला इक्वापुट (९ गोल) थिइन्।', 'nepali'),
      (v_set_id, 6, E'एसिसी यु-१९ एसिया कप, २०२५ को उपाधि कुन मुलुकले प्राप्त गरेको छ?', E'पाकिस्तान', E'भारत', E'बंगलादेश', E'श्रीलंका', 'A', E'**सन् २०२५ को एसिसी यु-१९ एसिया कपको उपाधि पाकिस्तानले जितेको थियो।**\n- भारत उपविजेता बनेको थियो, जसलाई पाकिस्तानले फाइनलमा १११ रनले पराजित गरेको थियो।\n- बंगलादेश र श्रीलंका सेमिफाइनलमा पुग्ने अन्य राष्ट्रहरू थिए।\nनोट: यो प्रतियोगिता सन् २०२५ डिसेम्बर १२-२१ सम्म युएईमा सञ्चालन भएको थियो।', 'nepali'),
      (v_set_id, 7, E'नेपाल सरकारद्वारा १०० भन्दा ठूला दरका भारु नोट सञ्चालनमा ल्याउने निर्णय कहिले भएको हो?', E'२०८२ मंसिर २६', E'२०८२ मंसिर २७', E'२०८२ मंसिर २८', E'२०८२ मंसिर २९', 'D', E'नेपाल सरकारले १०० भन्दा ठूला दरका भारु नोट सञ्चालनमा ल्याउने निर्णय **२०८२ मंसिर २९** गते गरेको थियो।\nनोट: २०८२ मंसिर २९ गते बसेको मन्त्री परिषद् बैठकले सरकारले सन् २०१६ नोभेम्बरपछि निष्कासन भएका २०० तथा ५०० दरका भारतीय नोट राख्न फुकुवा गरेको हो।', 'nepali'),
      (v_set_id, 8, E'राष्ट्रिय आर्टिफिसियल इन्टेलिजेन्स नीति २०८२ कहिले जारी भएको हो?', E'२०८२ असार २३', E'२०८२ असार ९', E'२०८२ साउन २६', E'२०८२ बैशाख २१', 'C', E'राष्ट्रिय आर्टिफिसियल इन्टेलिजेन्स नीति **२०८२ साउन २६** गते जारी भएको थियो।\n- राष्ट्रिय जनगणना नीति २०८२ असार २३ गते पारित भएको थियो।\n- राष्ट्रिय खेलकुद नीति २०८२ असार ९ गते जारी भएको थियो।\n- वैदेशिक सहायता परिचालन नीति २०८२ बैशाख २१ गते जारी भएको थियो।', 'nepali'),
      (v_set_id, 9, E'राष्ट्रिय युवा नीति, २०८२ ले कति वर्ष सम्मको उमेरलाई युवा भनेर परिभाषा गरेको छ?', E'३० वर्ष', E'३५ वर्ष', E'४० वर्ष', E'४५ वर्ष', 'B', E'राष्ट्रिय युवा नीति, २०८२ ले **१५ देखि ३५ वर्ष** सम्मको उमेर समूहका मानिसलाई युवा भनेर परिभाषा गरेको छ।\nनोट: यो नीति २०८२ भदौ ०४ मा जारी भएको थियो। यसअघिको राष्ट्रिय युवा नीति-२०७२ मा युवाको उमेर समूह १६-४० वर्ष थियो।', 'nepali'),
      (v_set_id, 10, E'नेपाल हालसालै देहायको कुन संगठनको कार्यकारी सदस्यमा निर्वाचित भएको छ ?', E'FAO', E'ILO', E'WHO', E'WTO', 'C', E'**नेपाल सन् २०२५ मे २३ मा विश्व स्वास्थ्य संगठन (WHO) को कार्यकारी सदस्यमा निर्वाचित भएको थियो।**\n- नेपाल २०२५ देखि २०२७ सम्म ३ वर्षको लागि WHO को कार्यकारी सदस्यको रूपमा रहनेछ।', 'nepali'),
      (v_set_id, 11, E'सुन्तला महोत्सव, २०८२ नेपालको कुन जिल्लामा आयोजना भएको छ ?', E'कास्की', E'सिन्धुली', E'सल्यान', E'धनकुटा', 'A', E'**सुन्तला महोत्सव, २०८२ कास्की जिल्लाको पोखरामा आयोजना भएको थियो।**\n- यो महोत्सव २०८२ पुस १० गते सम्पन्न भएको थियो।\nनोट: सुन्तला महोत्सवको नारा ''सुन्तलाको उपभोग, स्थानीय उत्पादन, पर्यटन र अर्थतन्त्रमा सहयोग'' रहेको थियो।', 'nepali'),
      (v_set_id, 12, E'प्रारम्भिक प्रतिवेदन अनुसार २०८२ मंसिर सम्ममा नेपालको जम्मा सार्वजनिक ऋण कति पुगेको छ ?', E'२४ खर्ब ८८ अर्ब ५३ करोड', E'२५ खर्ब ८८ अर्ब ५३ करोड', E'२६ खर्ब ८८ अर्ब ५३ करोड', E'२७ खर्ब ८८ अर्ब ५३ करोड', 'D', E'**२०८२ मंसिर सम्ममा नेपालको जम्मा सार्वजनिक ऋण २७ खर्ब ८८ अर्ब ५३ करोड पुगेको छ।**\n- यो कुल गार्हस्थ्य उत्पादन (GDP) को ४५.६६% हो।\nनोट: यसमध्ये आन्तरिक ऋण १३ खर्ब १ अर्ब ६३ करोड (GDP को २१.३१%) र बाह्य ऋण १४ खर्ब ८७ अर्ब ९० करोड (GDP को २४.३५%) रहेको छ।', 'nepali'),
      (v_set_id, 13, E'पाँचौ साक्षर प्रदेशका रुपमा साक्षरता घोषणा हुने नेपालको प्रदेश कुन हो ?', E'कोशी', E'लुम्बिनी', E'सुदुर पश्चिम', E'कर्णाली', 'B', E'**लुम्बिनी प्रदेश पाँचौ साक्षर प्रदेशका रुपमा घोषणा भएको हो।**\n- नेपालमा हालसम्म ५ वटा प्रदेश साक्षर घोषणा भएका छन्:\n- १. बागमती (२०७८ असोज ११)\n- २. गण्डकी (२०७८ असोज २४)\n- ३. कोशी (२०७९ भदौ २३)\n- ४. सुदुर पश्चिम (२०८२ असार १२)\n- ५. लुम्बिनी (२०८२ पुस १३)\nनोट: कर्णाली प्रदेशमा अब डोल्पा जिल्ला साक्षर हुन बाँकी छ भने मधेश प्रदेशमा हालसम्म कुनै पनि जिल्ला साक्षर घोषणा भएको छैन।', 'nepali'),
      (v_set_id, 14, E'प्रगतिशील लेखक संघले प्रलेस युवा पुरस्कार, २०८२ बाट कसलाई पुरस्कृत गरेको छ ?', E'ईश्वरचन्द्र ज्ञवाली', E'रूपक अलंकार', E'अनिल शर्मा', E'सुशीला प्रधानांग', 'B', E'**प्रगतिशील लेखक संघले २०८२ सालको प्रलेस युवा पुरस्कार रूपक अलंकारलाई प्रदान गरेको थियो।**\n- ईश्वरचन्द्र ज्ञवालीलाई श्यामप्रसाद स्मृति पुरस्कार प्रदान गरिएको थियो।\n- अनिल शर्मालाई प्रलेस प्रतिभा पुरस्कारबाट सम्मानित गरिएको थियो।\n- सुशीला प्रधानांगलाई प्रलेस बालसाहित्य पुरस्कार प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 15, E'वातावरण दिवस, २०२५ को आयोजक मुलुक कुन हो ?', E'दक्षिण कोरिया', E'स्वीडेन', E'ब्राजिल', E'इन्डोनेसिया', 'A', E'**सन् २०२५ को विश्व वातावरण दिवस दक्षिण कोरियाले आयोजना गरेको थियो।**\n- विश्व वातावरण दिवस हरेक वर्ष जुन ५ मा मनाइन्छ।\n- सन् २०२४ को विश्व वातावरण दिवसको नारा ''Our land. Our future.'' थियो।\n- सन् २०२३ को विश्व वातावरण दिवसको नारा ''Beat Plastic Pollution'' थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/११', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_15.csv  →  आसमान दैनिक GK — २०८२/०९/१५  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/१५'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/१५';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/१५', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको संविधानको कुन धारामा स्वास्थ्य सम्बन्धी हक सम्बन्धी व्यवस्था गरेको छ?', E'धारा ३४', E'धारा ३५', E'धारा ३६', E'धारा ३७', 'B', E'**नेपालको संविधानको धारा ३५ मा स्वास्थ्य सम्बन्धी हकको व्यवस्था गरिएको छ।**\n- धारा ३४ मा श्रमको हकको व्यवस्था छ।\n- धारा ३६ मा खाद्य सम्बन्धी हकको व्यवस्था छ।\n- धारा ३७ मा आवासको हकको व्यवस्था छ।', 'nepali'),
      (v_set_id, 2, E'भौगोलिक रुपमा कान्छो महादेश कुन हो?', E'एसिया', E'अफ्रिका', E'युरोप', E'उत्तर अमेरिका', 'A', E'**भौगोलिक रुपमा एसिया महादेशलाई कान्छो महादेश मानिन्छ।**\n- अफ्रिका महादेशलाई मानव जातिको उद्गमस्थल र अन्धमहादेश भनिन्छ।\n- युरोप महादेशलाई प्रायद्वीपहरूको प्रायद्वीप र समतल भूमिको महादेश भनिन्छ।\n- उत्तर अमेरिका महादेशलाई नयाँ संसारको महादेश भनिन्छ।\nनोट: एसिया जनसंख्या र भूगोलको आधारमा सबैभन्दा ठूलो महादेश हो र यसलाई विविधताको महादेश पनि भनिन्छ।', 'nepali'),
      (v_set_id, 3, E'अक्षांशका हिसाबले नेपाल कुन गोलाद्र्धमा रहेको छ?', E'पूर्वी गोलाद्र्धमा', E'पश्चिमी गोलाद्र्धमा', E'उत्तरी गोलाद्र्धमा', E'दक्षिणी गोलाद्र्धमा', 'C', E'**अक्षांशका हिसाबले नेपाल उत्तरी गोलाद्र्धमा अवस्थित छ।**\n- नेपाल २६ डिग्री २२ मिनेट उत्तरी अक्षांशदेखि ३० डिग्री २७ मिनेट उत्तरी अक्षांशसम्म फैलिएको छ।', 'nepali'),
      (v_set_id, 4, E'खैराबाङ भगवती मन्दिर नेपालको भूगोलको कुन जिल्लामा अवस्थित प्रसिद्ध धार्मिक स्थानको नाम हो?', E'सल्यान', E'दाङ', E'सुर्खेत', E'प्युठान', 'A', E'**खैराबाङ भगवती मन्दिर सल्यान जिल्लामा अवस्थित प्रसिद्ध धार्मिक स्थल हो।**\n- दाङ जिल्लामा धारापानी मन्दिर छ।\n- सुर्खेत जिल्लामा देउती बज्यै मन्दिर छ।\n- प्युठान जिल्लामा स्वर्गद्वारी आश्रम छ।', 'nepali'),
      (v_set_id, 5, E'गोर्खा राज्यका संस्थापक राजा द्रव्य शाह कसका छोरा हुन्?', E'कुलमण्डन खाँ', E'यशोब्रह्म शाह', E'पुरन्दर शाह', E'डम्बर शाह', 'B', E'**गोर्खा राज्यका संस्थापक राजा द्रव्य शाह यशोब्रह्म शाहका छोरा हुन्।**\n- शाह वंशका प्रथम राजा कुलमण्डन खान थिए।\n- पुरन्दर शाह द्रव्य शाहका छोरा हुन्।\n- डम्बर शाह गोर्खा राज्यको इतिहासमा उल्लेखित एक महत्वपूर्ण व्यक्ति हुन्।', 'nepali'),
      (v_set_id, 6, E'नेपालका चार धाम अन्तर्गत देहायको कुन पर्दैन?', E'जनकपुर', E'मुक्तिनाथ', E'दामोदर', E'स्वर्गद्वारी', 'D', E'**नेपालका चार धाम अन्तर्गत स्वर्गद्वारी पर्दैन।**\n- जनकपुर, मुक्तिनाथ (दामोदर कुण्ड), पशुपतिनाथ र बराहक्षेत्र नेपालका चार धाम हुन्।\n- स्वर्गद्वारी प्युठान जिल्लामा अवस्थित एक प्रसिद्ध धार्मिक स्थल हो।', 'nepali'),
      (v_set_id, 7, E'नेपालको राष्ट्रिय आविष्कार केन्द्रको स्थापना कहिले भयो?', E'२०७६ वैशाख ५', E'२०७६ असोज ५', E'२०७६ कार्तिक १', E'२०६५ मंसिर २१', 'C', E'**नेपालको राष्ट्रिय आविष्कार केन्द्रको स्थापना वि.सं. २०७६ कार्तिक १ गते भएको थियो।**\n- यस केन्द्रका संस्थापक महावीर पुन हुन्।\n- नेपाल अन्तरिक्ष युगमा वि.सं. २०७६ वैशाख ५ गते प्रवेश गरेको थियो, जतिबेला नेपाली स्याट-१ नामक भू-उपग्रह प्रक्षेपण गरिएको थियो।', 'nepali'),
      (v_set_id, 8, E'बालबालिकालाई क्षयरोग विरुद्ध दिइने खोपको नाम के हो?', E'OPV', E'PCV', E'BCG', E'DPT', 'C', E'**बालबालिकालाई क्षयरोग विरुद्ध दिइने खोपको नाम BCG हो।**\n- OPV पोलियो रोग विरुद्ध दिइने खोप हो।\n- DPT भ्यागुते रोग, लहरे खोकी र धनुष्टंकार विरुद्ध दिइने खोप हो।\n- PCV निमोनिया रोग विरुद्ध दिइने खोप हो।', 'nepali'),
      (v_set_id, 9, E'देहायका मध्ये कुन पिरामिड उल्टो/घोप्टो हुन्छ?', E'जीव संख्या', E'स्थलीय जीव पिण्ड', E'समुद्री जीव पिण्ड', E'जीव ऊर्जा/शक्ति', 'C', E'**समुद्री जीव पिण्डको पिरामिड उल्टो वा घोप्टो हुन्छ।**\n- जीव संख्याको पिरामिड सामान्यतया सीधा हुन्छ, तर केही अवस्थामा उल्टो पनि हुन सक्छ।\n- स्थलीय जीव पिण्डको पिरामिड सामान्यतया सीधा हुन्छ।\n- जीव ऊर्जा/शक्तिको पिरामिड सधैं सीधा हुन्छ।', 'nepali'),
      (v_set_id, 10, E'राष्ट्रिय जनगणना, २०७८ अनुसार अपाङ्गता भएका व्यक्ति मध्ये पुरुष कति प्रतिशत रहेको छ?', E'५४.२ प्रतिशत', E'४५.८ प्रतिशत', E'४९.३१ प्रतिशत', E'५१.३४ प्रतिशत', 'A', E'**राष्ट्रिय जनगणना, २०७८ अनुसार अपाङ्गता भएका व्यक्ति मध्ये पुरुष ५४.२ प्रतिशत रहेका छन्।**\n- अपाङ्गता भएका व्यक्ति मध्ये महिला ४५.८ प्रतिशत रहेका छन्।\n- कुल जनसंख्याको २.२ प्रतिशत व्यक्तिमा कुनै न कुनै प्रकारको अपाङ्गता रहेको छ।', 'nepali'),
      (v_set_id, 11, E'सार्क सांस्कृतिक केन्द्र कहाँ रहेको छ?', E'नेपाल', E'भारत', E'पाकिस्तान', E'श्रीलङ्का', 'D', E'सार्क सांस्कृतिक केन्द्र **श्रीलङ्काको कोलम्बो** मा रहेको छ।\n- नेपालमा सार्क सूचना केन्द्र, सार्क क्षयरोग र एचआईभी/एड्स केन्द्र रहेका छन्।\n- भारतमा सार्क विपद् व्यवस्थापन केन्द्र रहेको छ।\n- पाकिस्तानमा सार्क वातावरण तथा ऊर्जा केन्द्र रहेको छ।', 'nepali'),
      (v_set_id, 12, E'बढी ब्याज कमाउने मुद्रालाई के भनिन्छ?', E'निक्षेप मनी', E'फिडो मनी', E'हट मनी', E'कर्जा मनी', 'C', E'**बढी ब्याज कमाउने मुद्रालाई **हट मनी भनिन्छ।\n- निक्षेप मनी भन्नाले बैंक वा वित्तीय संस्थामा जम्मा गरिएको रकमलाई बुझिन्छ।\n- फिडो मनी भनेको टक्सार विभागबाट गलत भएको सिक्का हो।\n- कर्जा मनी भनेको ऋणको रूपमा दिइने मुद्रा हो।', 'nepali'),
      (v_set_id, 13, E'आर्थिक सर्वेक्षण २०७९/८० अनुसार कम खेती योग्य जमिन भएको जिल्ला कुन हो?', E'मनाङ', E'मुस्ताङ', E'डोल्पा', E'रसुवा', 'A', E'**आर्थिक सर्वेक्षण २०७९/८० अनुसार नेपालमा सबैभन्दा कम खेती योग्य जमिन भएको जिल्ला **मनाङ हो।\n- कम खेती योग्य जमिन भएका जिल्लाहरू क्रम: मनाङ, मुस्ताङ, डोल्पा, रसुवा र हुम्ला हुन्।\n- बढी खेती योग्य जमिन भएका जिल्लाहरू क्रम: मोरङ, झापा, सर्लाही, सिराहा र सप्तरी हुन्।', 'nepali'),
      (v_set_id, 14, E'भ्रष्टाचार सूचकांक, २०२४ अनुसार विश्वमा कम भ्रष्टाचार हुने मुलुक कुन हो?', E'डेनमार्क', E'स्वीडेन', E'भुटान', E'द. सुडान', 'A', E'**भ्रष्टाचार सूचकांक, २०२४ अनुसार विश्वमा सबैभन्दा कम भ्रष्टाचार हुने मुलुक **डेनमार्क हो, जसले ९० अंक प्राप्त गरेको छ।\n- सबैभन्दा बढी भ्रष्टाचार हुने मुलुक द. सुडान (८ अंक) हो।\n- सार्क मुलुकहरूमध्ये कम भ्रष्टाचार गर्ने भुटान (१५औं स्थान, ७२ अंक) र बढी भ्रष्टाचार गर्ने अफगानिस्तान (१६२औं स्थान, १७ अंक) हुन्।', 'nepali'),
      (v_set_id, 15, E'नरेन्द्र मोदी पुनः भारतका प्रधानमन्त्री कहिले बने?', E'सन् २०२४ जुन ७', E'सन् २०२४ जुन ८', E'सन् २०२४ जुन ९', E'सन् २०२४ जुन १०', 'C', E'**नरेन्द्र मोदी सन् **२०२४ जुन ९ मा पुनः भारतका प्रधानमन्त्री बनेका हुन्।\n- यो उनको तेस्रो कार्यकाल हो र उनी भारतीय जनता पार्टीका नेता हुन्।\n- उनले सन् २०२४ जुन ९ मा द्रौपदी मुर्मुबाट शपथ लिएका थिए।\n- कार्यकालका आधारमा उनी स्वतन्त्र भारतका १५औं प्रधानमन्त्री हुन् (व्यक्तिगत आधारमा २०औं)।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/१५', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_16.csv  →  आसमान दैनिक GK — २०८२/०९/१६  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/१६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/१६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/१६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'सार्कको स्थापना संयुक्त राष्ट्रसंघ वडापत्रको कुन धाराको आधारमा भएको हो?', E'धारा २५', E'धारा ५२', E'धारा ५०', E'धारा ५६', 'B', E'**सार्कको स्थापना संयुक्त राष्ट्रसंघ वडापत्रको धारा ५२ को आधारमा भएको हो।**\n- संयुक्त राष्ट्रसंघको वडापत्रको धारा २५ ले सुरक्षा परिषद्का निर्णयहरू सदस्य राष्ट्रहरूका लागि बाध्यकारी हुने व्यवस्था गर्दछ।\n- संयुक्त राष्ट्रसंघको वडापत्रको धारा ५० ले सुरक्षा परिषद्ले कुनै देशविरुद्ध निवारक वा प्रवर्तन कार्य गरेमा त्यसबाट उत्पन्न विशेष आर्थिक समस्याहरूको सामना गर्ने राज्यहरूलाई परामर्श दिने अधिकार दिन्छ।\n- संयुक्त राष्ट्रसंघको वडापत्रको धारा ५६ ले सदस्य राष्ट्रहरूले संयुक्त र छुट्टाछुट्टै रूपमा संयुक्त राष्ट्रसंघको उद्देश्य प्राप्तिका लागि कार्य गर्ने प्रतिबद्धता जनाउँछ।\nनोट: क्षेत्रीय संगठनहरूको स्थापना र कार्यका लागि संयुक्त राष्ट्रसंघको वडापत्रको धारा ५२ ले मार्गदर्शन गर्दछ।', 'nepali'),
      (v_set_id, 2, E'नेपालले कहिलेबाट कोप सम्मेलनमा निरन्तरता रुपमा सहभागी हुँदै आएको छ?', E'सन् २०११', E'सन् २०१२', E'सन् २०१३', E'सन् २०१४', 'A', E'नेपालले सन् **२०११** मा दक्षिण अफ्रिकाको डरबनमा सम्पन्न कोप-१७ सम्मेलनदेखि कोप सम्मेलनमा निरन्तरताका साथ सहभागी हुँदै आएको छ।\nनोट: कोप सम्मेलन जलवायु परिवर्तनसम्बन्धी संयुक्त राष्ट्रसंघीय फ्रेमवर्क महासन्धि (UNFCCC) का पक्ष राष्ट्रहरूको वार्षिक बैठक हो।', 'nepali'),
      (v_set_id, 3, E'उत्परिवर्तनका पिता (Father of mutation) को रुपमा कुन वैज्ञानिकलाई चिनिन्छ?', E'चार्ल्स डार्विन', E'हुयुगो डिभ्रिज', E'जोन गेगर मेण्डल', E'जीन-ब्याप्टिस्ट लेमार्क', 'B', E'**हुयुगो डिभ्रिजलाई उत्परिवर्तनका पिता (Father of mutation) को रुपमा चिनिन्छ।**\n- चार्ल्स डार्विनलाई प्राकृतिक छनोटद्वारा विकासवादको सिद्धान्तका लागि चिनिन्छ।\n- जोन गेगर मेण्डललाई आनुवंशिकीका पिता (Father of Genetics) को रुपमा चिनिन्छ।\n- जीन-ब्याप्टिस्ट लेमार्कलाई विकासवादको प्रारम्भिक सिद्धान्त (acquired characteristics) प्रस्तुत गर्ने वैज्ञानिकका रुपमा चिनिन्छ।\nनोट: उत्परिवर्तन भनेको पुर्खामा नभएको गुण पुस्तामा अकस्मात देखा पर्नु हो।', 'nepali'),
      (v_set_id, 4, E'नेपाली इतिहासमा संस्कृत भाषाको पहिलो चलचित्र "गुरु दक्षिण" हो भने शेर्पा भाषाको पहिलो चलचित्र कुन हो?', E'साइबुङ', E'खाङ्ग्री', E'नामास्या न्होरी', E'जितभुज', 'B', E'**शेर्पा भाषाको पहिलो चलचित्र खाङ्ग्री हो।**\n- राई भाषाको पहिलो चलचित्र साइबुङ हो।\n- गुरुङ भाषाको पहिलो चलचित्र नामास्या न्होरी हो।\n- थारु भाषाको पहिलो चलचित्र जितभुज हो।\nनोट: संस्कृत भाषाको पहिलो चलचित्र ''गुरु दक्षिण'' हो भने नेवारी भाषाको पहिलो चलचित्र ''शिलु'' हो।', 'nepali'),
      (v_set_id, 5, E'पृथ्वीनारायण शाहले उपत्यका विजयको लागि कस्तो नीति अवलम्वन गरेका थिए?', E'आर्थिक नाकाबन्दी', E'खानगी', E'मरेमट', E'मित नीति', 'A', E'पृथ्वीनारायण शाहले उपत्यका विजयको लागि **आर्थिक नाकाबन्दीको** नीति अवलम्वन गरेका थिए। उनले उपत्यकालाई चारैतर्फबाट घेरी नाकाबन्दी गरेकाले चरम आर्थिक संकट छाएको थियो र कान्तिपुरमाथि विजय हासिल गर्न सहज भयो।\nनोट: उनले सैनिकहरूका लागि खानगी (जग्गा तथा आर्थिक सहायता) र मरेमट (लडाइँमा मरेका सिपाहीका परिवारलाई सहयोग) जस्ता नीतिहरू पनि लागू गरेका थिए।', 'nepali'),
      (v_set_id, 6, E'नवनियुक्त नेपाल प्रहरीको महानिरीक्षक (आइजिपी) चन्द्र कुवेर खापुङ कति औं महानिरीक्षक हुन्?', E'३१ औं', E'३२ औं', E'३३ औं', E'३४ औं', 'B', E'चन्द्र कुवेर खापुङ नेपाल प्रहरीको **३२ औं** महानिरीक्षक हुन्। उनी वि.सं. २०८२ भाद्र १३ गते (भदौ १९ गतेबाट लागू हुने गरी) महानिरीक्षक नियुक्त भएका हुन्।\nनोट: उनीभन्दा अघि ३१ औं महानिरीक्षक दीपक थापा थिए।', 'nepali'),
      (v_set_id, 7, E'तराई क्षेत्रमा जम्मा प्रतिनिधि सभा निर्वाचन क्षेत्र कति रहेको छ?', E'७८ वटा', E'७९ वटा', E'८० वटा', E'८१ वटा', 'A', E'प्रतिनिधि सभा निर्वाचनका लागि तराई क्षेत्रमा जम्मा **७८ वटा** निर्वाचन क्षेत्र रहेको छ।\nनोट: नेपालमा जम्मा १६५ निर्वाचन क्षेत्रहरू छन्, जसमध्ये हिमाली क्षेत्रमा २४ र पहाडी क्षेत्रमा ६३ वटा रहेका छन्।', 'nepali'),
      (v_set_id, 8, E'नेपालमा फेसबुक लगायत सूचीकरण नभएका २६ ओटा सामाजिक सञ्जाललाई बन्द गर्ने निर्णय नेपाल सरकारले कहिले गरेको हो?', E'२०८२ भदौ १८', E'२०८२ भदौ १९', E'२०८२ भदौ २०', E'२०८२ भदौ २१', 'B', E'नेपाल सरकारले सूचीकरण नभएका २६ ओटा सामाजिक सञ्जाललाई बन्द गर्ने निर्णय **वि.सं. २०८२ भदौ १९** गते गरेको थियो।\nनोट: बन्द गरिएका सामाजिक सञ्जालहरूमा फेसबुक, म्यासेन्जर, इन्स्टाग्राम, युट्युब, र ट्वीटर (एक्स) लगायतका प्रमुख प्लेटफर्महरू समावेश थिए।', 'nepali'),
      (v_set_id, 9, E'द्वितीय विश्वयुद्धमा मुसोलिनीले कुन मुलुकको नेतृत्व गरेका थिए?', E'जर्मनी', E'फ्रान्स', E'बेलायत', E'इटाली', 'D', E'**द्वितीय विश्वयुद्धमा बेनिटो मुसोलिनीले इटालीको नेतृत्व गरेका थिए।**\n- जर्मनीको नेतृत्व एडोल्फ हिटलरले गरेका थिए।\n- फ्रान्स र बेलायत मित्र राष्ट्रका प्रमुख सदस्य थिए।\nनोट: मुसोलिनी फासीवादका प्रणेता थिए।', 'nepali'),
      (v_set_id, 10, E'चन्द्रनहर सिँचाइ आयोजना कुन जिल्लामा सञ्चालित रहेको छ?', E'नुवाकोट', E'कैलाली', E'कपिलवस्तु', E'सप्तरी', 'D', E'**चन्द्रनहर सिँचाइ आयोजना सप्तरी जिल्लामा सञ्चालित छ।**\n- कैलाली जिल्लामा मोहना सिँचाइ आयोजना रहेको छ।\n- कपिलवस्तु जिल्लामा बाणगंगा सिँचाइ आयोजना सञ्चालित छ।\n- नुवाकोट जिल्लामा बटटार सिँचाइ आयोजना रहेको छ।\nनोट: चन्द्रनहर नेपालको पहिलो नहर हो, जसको निर्माण वि.सं. १९६९ मा भएको थियो।', 'nepali'),
      (v_set_id, 11, E'आ.व. २०८२/८३ को कुल बजेट कति रहेको छ?', E'२० खर्ब ६० अर्ब १० करोड', E'२० खर्ब ६० अर्ब २० करोड', E'१९ खर्ब ६४ अर्ब १० करोड', E'१९ खर्ब ६४ अर्ब ११ करोड', 'D', E'**आ.व. २०८२/८३ को कुल बजेट १९ खर्ब ६४ अर्ब ११ करोड रहेको छ।**\n- यसमध्ये चालुतर्फ ११ खर्ब ८० अर्ब १९ करोड (६०.१ प्रतिशत) र पुँजीगततर्फ ४ खर्ब ९ अर्ब ८९ करोड (२०.८ प्रतिशत) विनियोजन गरिएको छ।\nनोट: वित्तीय व्यवस्थातर्फ ३ खर्ब ७४ अर्ब २४ करोड (१९.१ प्रतिशत) र वित्तीय हस्तान्तरणतर्फ ४ खर्ब १७ अर्ब ८३ करोड (२१ प्रतिशत) रहेको छ।', 'nepali'),
      (v_set_id, 12, E'छायाँ नदेखिने नदीको उपनामले विश्वको कुन नदिलाई चिनिन्छ?', E'यमुना नदी', E'जोर्डन नदी', E'माही नदी', E'अरास नदी', 'B', E'**जोर्डन नदीलाई ''छायाँ नदेखिने नदी'' को उपनामले चिनिन्छ।**\n- यमुना नदी भारतको एक प्रमुख नदी हो, जुन गंगा नदीको सहायक नदी हो।\n- माही नदी भारतको पश्चिमी भागमा बग्ने नदी हो।\n- अरास नदी टर्की, आर्मेनिया, अजरबैजान र इरान हुँदै बग्ने नदी हो।\nनोट: जोर्डन नदी इजरायल र जोर्डनको सिमानामा बग्छ र मृतसागरबाट निस्किएको नदी हो।', 'nepali'),
      (v_set_id, 13, E'सूर्य ग्रहण लाग्दा सूर्यको कुन भाग पहिले ढाकिन्छ?', E'पश्चिमी भाग', E'पूर्वी भाग', E'उत्तरी भाग', E'दक्षिणी भाग', 'A', E'**सूर्य ग्रहण लाग्दा सूर्यको पश्चिमी भाग पहिले ढाकिन्छ।**\n- सूर्य ग्रहण तब लाग्छ जब चन्द्रमा सूर्य र पृथ्वीको बीचमा आउँछ र सूर्यको प्रकाशलाई पृथ्वीमा पुग्नबाट रोक्छ।', 'nepali'),
      (v_set_id, 14, E'संविधान सभाबाट संविधान जारी गर्ने विश्वको पहिलो संविधान कुन मुलुकको हो?', E'फ्रान्स', E'अमेरिका', E'बेलायत', E'भारत', 'B', E'**संविधान सभाबाट संविधान जारी गर्ने विश्वको पहिलो मुलुक अमेरिका हो।**\n- फ्रान्सले सन् १७९१ मा आफ्नो पहिलो लिखित संविधान जारी गरेको थियो।\n- बेलायतको लिखित संविधान छैन, यसको संविधान परम्परा र कानुनमा आधारित छ।\n- भारत विश्वको सबैभन्दा लामो लिखित संविधान भएको देश हो।\nनोट: अमेरिकाको संविधान सन् १७८७ मा फिलाडेल्फियामा सम्पन्न संविधान सभाबाट पारित भएको थियो।', 'nepali'),
      (v_set_id, 15, E'एक गाउँ एक उत्पादन कार्यक्रम (OVOP) अन्तर्गत अकबरे खुर्सानीको लागि छनोट जिल्ला कुन हो?', E'पाँचथर', E'बर्दिया', E'सिन्धुली', E'मकवानपुर', 'A', E'**एक गाउँ एक उत्पादन कार्यक्रम (OVOP) अन्तर्गत अकबरे खुर्सानीको लागि छनोट जिल्ला पाँचथर हो।**\n- सिन्धुली जिल्ला जुनार उत्पादनका लागि छनोट भएको छ।\n- मकवानपुर जिल्ला किवी खेतीका लागि छनोट भएको छ।\n- बर्दिया जिल्ला बेल उत्पादनका लागि छनोट भएको छ।\nनोट: एक गाउँ एक उत्पादन कार्यक्रम (OVOP) ले स्थानीय विशिष्ट उत्पादनको प्रवर्द्धनमा जोड दिन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/१६', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_17.csv  →  आसमान दैनिक GK — २०८२/०९/१७  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/१७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/१७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/१७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'दरबार हाईस्कूलमा प्रथम महिला प्रधानाध्यापकको रुपमा को नियुक्त हुनुभएको छ ?', E'शारदा कुमारी पौडेल', E'बीमला कुमारी पौडेल', E'कमला कुमारी पौडेल', E'पद्मा कुमारी पौडेल', 'A', E'दरबार हाईस्कूलको प्रथम महिला प्रधानाध्यापकको रुपमा **शारदा कुमारी पौडेल** नियुक्त हुनुभएको हो। उहाँको नियुक्ति वि.सं. २०८२ मंसिर ४ मा भएको थियो।\nनोट: वि.सं. १९१० असोज २७ मा जंगबहादुर राणाको पालामा स्थापना भएको दरबार हाईस्कूल नेपालको सबैभन्दा पुरानो स्कूल हो। यसको प्रथम प्रधानाध्यापक मिस्टर क्यानिङ र प्रथम नेपाली प्रधानाध्यापक रुद्रराज पाण्डे हुन्।', 'nepali'),
      (v_set_id, 2, E'नेपालमा करदाता सेवा दिने पहिलो स्थानीय तह कुन बनेको छ ?', E'पाँचखाल गाउँपालिका', E'गैंडहवा गाउँपालिका', E'केराबारी गाउँपालिका', E'सिस्ने गाउँपालिका', 'C', E'नेपालमा करदाता सेवा दिने पहिलो स्थानीय तह **केराबारी गाउँपालिका** बनेको छ। मोरङ जिल्ला, कोशी प्रदेशमा पर्ने यो गाउँपालिकामा वि.सं. २०८२ पुस ०९ देखि सेवा शुभारम्भ भएको हो।\nनोट: उक्त सेवाको शुभारम्भ अर्थ मन्त्री रामेश्वरप्रसाद खनालद्वारा गरिएको थियो।', 'nepali'),
      (v_set_id, 3, E'पहिलो राष्ट्रिय च्याउ दिवस, २०८२ कहिले मनाइएको छ ?', E'पुस १३', E'पुस १५', E'पुस १७', E'पुस १९', 'B', E'नेपाल सरकारले हरेक वर्ष **पुस १५** गतेलाई राष्ट्रिय च्याउ दिवसका रूपमा मनाउने निर्णय गरेको छ।\nनोट: यो निर्णय २०८२ पुस ११ गतेको मन्त्रिपरिषद् बैठकले गरेको हो।', 'nepali'),
      (v_set_id, 4, E'चितवन हात्ती तथा पर्यटन महोत्सव २०८२ मा हात्ती सुन्दरी प्रतियोगिताको उपाधि जित्ने हात्ती कुन हो?', E'सेल्लिफ कली', E'रुद्र कली', E'पुनम कली', E'बिजुली कली', 'C', E'**चितवन हात्ती तथा पर्यटन महोत्सव २०८२ मा पुनम कलीले हात्ती सुन्दरी प्रतियोगिताको उपाधि जितेकी थिइन्।**\n- बिजुली कलीले २०८१ मा हात्ती सुन्दरी प्रतियोगिताको उपाधि जितेकी थिइन्।\n- सेल्लिफ कलीले २०८० मा हात्ती सुन्दरी प्रतियोगिताको उपाधि जितेकी थिइन्।\n- रुद्र कली कतारलाई उपहार दिइएका दुई हात्तीमध्ये एकको नाम हो।', 'nepali'),
      (v_set_id, 5, E'नेपाल प्रिमियर लिग (NPL) को ट्रफी बनाउन कुन ठाउँ बाट ढुंगा लिइ प्रयोगमा ल्याइयो? (कोशी सातो, २०८२)', E'रसुवा', E'लिपुलेख', E'कालापत्थर', E'कालीगण्डकी', 'C', E'नेपाल प्रिमियर लिग (NPL) को ट्रफी बनाउन सगरमाथा क्षेत्रको **कालापत्थरबाट** ढुंगा लिइ प्रयोगमा ल्याइएको थियो।\nनोट: यो ट्रफी २०८१ मंसिर १० गते धरहराबाट सार्वजनिक गरिएको थियो।', 'nepali'),
      (v_set_id, 6, E'Oxford Dictionary अनुसार यो वर्षको शब्द Word Of The Year,2025 घोषणा हुन सफल शब्द कुन हो ?', E'Rage Bait', E'six-seven', E'Parasocial', E'AI Power', 'A', E'**Oxford Dictionary अनुसार २०२५ को Word Of The Year ''Rage Bait'' घोषणा भएको छ।**\n- Dictionary.com अनुसार ''six-seven'' वर्षको शब्द हो।\n- Cambridge Dictionary अनुसार ''Parasocial'' वर्षको शब्द हो, जसको अर्थ सेलिब्रेटी, पोडकास्टर र एआई जस्ता अनलाइन व्यक्तिसँग महसुस गर्ने एकतर्फी भावनात्मक सम्बन्ध हो।\nनोट: ''Rage Bait'' को अर्थ मानिसमा रिस उठाउने, सञ्जालको सामग्री उक्साउने र विवादमा निम्त्याउने उद्देश्यले जानी जानी बनाइने सामाजिक सामग्री हो।', 'nepali'),
      (v_set_id, 7, E'ग्लोब स्कोर अवार्ड्स, २०२४ मध्य पूर्वको सर्वश्रेष्ठ खेलाडीको उपाधि प्राप्त गर्ने फुटबल खेलाडी को हुन् ?', E'ओस्मान डेम्बेले', E'क्रिस्टियानो रोनाल्डो', E'रोड्रि', E'लियोनल मेस्सी', 'B', E'पोर्चुगिज फुटबलर **क्रिस्टियानो रोनाल्डोले** ग्लोब सकर अवार्ड्स, २०२४ मा मध्य पूर्वको सर्वश्रेष्ठ खेलाडी (Best Middle East Player) को उपाधि जितेका छन्।', 'nepali'),
      (v_set_id, 8, E'वर्ल्ड इको आउटलुकको प्रतिवेदन, २०२४ अनुसार विश्वको तेस्रो ठूलो अर्थतन्त्र भएको मुलुक कुन हो ?', E'जापान', E'चीन', E'जर्मनी', E'भारत', 'C', E'वर्ल्ड इको आउटलुकको प्रतिवेदन, २०२४ अनुसार **जर्मनी** विश्वको तेस्रो ठूलो अर्थतन्त्र भएको मुलुक हो।\n- जापान चौथो स्थानमा रहेको छ।\n- चीन दोस्रो स्थानमा रहेको छ।\n- भारत पाँचौं स्थानमा रहेको छ।\nनोट: अमेरिका विश्वको सबैभन्दा ठूलो अर्थतन्त्र हो।', 'nepali'),
      (v_set_id, 9, E'नगरपालिका भन्दा उपमहानगरपालिका बढि भएको नेपालको एकमात्र जिल्ला कुन हो ?', E'कास्की', E'बारा', E'दाङ', E'सुनसरी', 'C', E'**दाङ** नेपालको एकमात्र जिल्ला हो जहाँ नगरपालिकाभन्दा उपमहानगरपालिकाको संख्या बढी छ।\nनोट: दाङ जिल्लामा २ उपमहानगरपालिका (घोराही, तुलसीपुर) र १ नगरपालिका (लमही) रहेका छन्।', 'nepali'),
      (v_set_id, 10, E'अन्तर्राष्ट्रिय मैथिली सम्मेलन-२०२४ नेपालको कुन स्थानमा आयोजना भएको छ ?', E'काठमाडौं', E'विराटनगर', E'विरगञ्ज', E'पोखरा', 'B', E'अन्तर्राष्ट्रिय मैथिली सम्मेलन-२०२४ **विराटनगरमा** आयोजना भएको थियो।\nनोट: यो सम्मेलन मैथिली एसोसिएसन नेपालद्वारा २०८१ पुस १२ र १३ गते (२०२४ डिसेम्बर २७ र २८) सम्पन्न भएको हो।', 'nepali'),
      (v_set_id, 11, E'अमेरिकाको न्यूयोर्क सहरमा हालसालै मेयर चुनावमा निर्वाचित चर्चित राजनीतिज्ञको हुन् ?', E'एन्ड्रयु कुमो', E'जोहरान ममदानी', E'कर्टिस सिल्वा', E'मिरा नायर', 'B', E'**जोहरान ममदानी** हालसालै अमेरिकाको न्यूयोर्क सहरको मेयर चुनावमा निर्वाचित भएका छन्।\n- एन्ड्रयु कुमो न्यूयोर्कका पूर्व गभर्नर हुन्, जसलाई ममदानीले चुनावमा पराजित गरे।\n- कर्टिस सिल्वा रिपब्लिकन पार्टीका उम्मेदवार थिए, जो चुनावमा पराजित भए।\n- मिरा नायर एक चर्चित भारतीय फिल्म निर्देशक र जोहरान ममदानीकी आमा हुन्।\nनोट: जोहरान ममदानी न्यूयोर्कको पहिलो मुस्लिम मेयर बनेका छन्।', 'nepali'),
      (v_set_id, 12, E'लेखनाथ पुरस्कार, २०२८ कसलाई प्रदान गरिएको छ?', E'घनश्याम कँडेल', E'गंगा कर्मचारी पौडेल', E'नवराज अधिकारी', E'प्रवीण रेग्मी', 'A', E'**लेखनाथ पुरस्कार, २०२८ घनश्याम कँडेललाई प्रदान गरिएको छ।**\n- गंगा कर्मचारी पौडेललाई कुन्तिदेवी साहित्य पुरस्कार प्रदान गरिएको थियो।\n- नवराज अधिकारीलाई लेखनाथ सांस्कृतिक पुरस्कार प्रदान गरिएको थियो।\nनोट: लेखनाथ पुरस्कारको राशी एक लाख रुपैयाँ रहेको छ।', 'nepali'),
      (v_set_id, 13, E'२०२५ मा मनाइएको अन्तर्राष्ट्रिय आप्रवासन दिवस कति औं हो?', E'२३ औं', E'२४ औं', E'२५ औं', E'२६ औं', 'C', E'सन् २०२५ मा मनाइने अन्तर्राष्ट्रिय आप्रवासन दिवस **२५ औं संस्करण** हो।\n- अन्तर्राष्ट्रिय आप्रवासन दिवस हरेक वर्ष डिसेम्बर १८ मा मनाइन्छ। २०२५ को नारा ''श्रम आप्रवासनको चक्रमा सुशासन: सुरक्षित, मर्यादित र सिपयुक्त आप्रवासन'' रहेको छ।', 'nepali'),
      (v_set_id, 14, E'हिमालय रोडिज सिजन ७ को उपाधि कसले प्राप्त गरेका छन्?', E'विकास श्रेष्ठ', E'अनिश तामाङ', E'दिपक रेग्मी', E'प्रिन्स मगर', 'B', E'**हिमालय रोडिजको सातौं सिजनको उपाधि अनिश तामाङले प्राप्त गरेका छन्।**\n- यो उपाधि २०८२ पुस १४ मा सम्पन्न फाइनलमा प्राप्त भएको थियो।\nनोट: हिमालय रोडिज नेपालको एक लोकप्रिय साहसिक रियालिटी शो हो।', 'nepali'),
      (v_set_id, 15, E'नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा सर्वोत्कृष्ट इमर्जिङ प्लेयर अफ द टुर्नामेन्ट कसले प्राप्त गरेका हुन्?', E'शेर मल्ल', E'सन्दीप लामिछाने', E'अबिनास बोहरा', E'रुबेन ट्रम्पलम्यान', 'A', E'**नेपाल प्रिमियर लिगको दोस्रो संस्करण, २०२५ मा शेर मल्लले सर्वोत्कृष्ट इमर्जिङ प्लेयर अफ द टुर्नामेन्टको उपाधि प्राप्त गरेका हुन्।**\n- सन्दीप लामिछानेले सर्वोत्कृष्ट बलरको उपाधि प्राप्त गरेका थिए।\n- रोहित पौडेलले सर्वोत्कृष्ट नेपाली खेलाडी तथा सर्वोत्कृष्ट ब्याटरको उपाधि प्राप्त गरेका थिए।\n- अबिनास बोहराले इनर्जेटिक (Energetic) प्लेयर अफ द टुर्नामेन्टको उपाधि प्राप्त गरेका थिए।\n- रुबेन ट्रम्पलम्यानले सर्वोत्कृष्ट खेलाडीको उपाधि प्राप्त गरेका थिए।', 'nepali'),
      (v_set_id, 16, E'देहायका मध्ये कुन विमानस्थल गोर्खा जिल्लामा अवस्थित प्रसिद्ध विमानस्थल हो?', E'रुम्जाटार', E'पालुङटार', E'चन्दननाथ', E'राँझा', 'B', E'**पालुङटार विमानस्थल गोर्खा जिल्लामा अवस्थित छ।**\n- रुम्जाटार विमानस्थल ओखलढुंगा जिल्लामा पर्दछ।\n- चन्दननाथ विमानस्थल जुम्ला जिल्लामा रहेको छ।\n- राँझा विमानस्थल बाँके जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 17, E'नेपालको संविधानको कति धारा देखि कति सम्म ३१ वटा मौलिक हकको व्यवस्था गरिएको छ?', E'धारा १६ देखि ४६', E'धारा १६ देखि ४७', E'धारा १७ देखि ४७', E'धारा १७ देखि ४८', 'A', E'नेपालको संविधानको भाग ३: मौलिक हक र कर्तव्य अन्तर्गत **धारा १६ देखि धारा ४६ सम्म** ३१ वटा मौलिक हकहरू रहेका छन्।', 'nepali'),
      (v_set_id, 18, E'अन्तरिक्षमा तारामण्डलहरू कतिवटा रहेको पाइएको छ?', E'६८ वटा', E'८८ वटा', E'५८ वटा', E'७८ वटा', 'B', E'अन्तरिक्षमा हालसम्म **८८ वटा** तारामण्डलहरू रहेको पाइएको छ।\nनोट: ज्योतिर्विद्हरूले नामाकरण गरेका यी ८८ तारामण्डलहरूमा १२ राशि, २७ नक्षत्र र अन्य ४९ पिण्डहरू (जस्तै: उर्सा मेजर, एन्ड्रोमेडा) पर्दछन्।', 'nepali'),
      (v_set_id, 19, E'नेपाललाई भारतका कतिवटा प्रान्तले छोएको छ?', E'६ वटा', E'५ वटा', E'७ वटा', E'८ वटा', 'B', E'**नेपाललाई भारतका पाँचवटा प्रान्तले छोएको छ।**\n- यी प्रान्तहरू पूर्वबाट क्रमशः सिक्किम, पश्चिम बङ्गाल (दार्जिलिङ), बिहार, उत्तर प्रदेश र उत्तराखण्ड हुन्।\nनोट: बिहारले सबैभन्दा बढी र सिक्किमले सबैभन्दा कम सिमाना छोएको छ।', 'nepali'),
      (v_set_id, 20, E'अस्ट्रेलिया महादेशको सबैभन्दा होचो भूभाग कुन हो?', E'आयरा ताल', E'मृत सागर', E'क्यास्पियन सागर', E'असाल ताल', 'A', E'**अस्ट्रेलिया महादेशको सबैभन्दा होचो भूभाग आयरा ताल हो।**\n- मृत सागर एसिया महादेशको सबैभन्दा होचो भूभाग हो।\n- क्यास्पियन सागर युरोप महादेशको सबैभन्दा होचो भूभाग हो।\n- असाल ताल अफ्रिका महादेशको सबैभन्दा होचो भूभाग हो।', 'nepali'),
      (v_set_id, 21, E'Transparency International, 2025 ले सार्वजनिक भ्रष्टाचार सूचकांक, २०२४ अनुसार नेपाल कति औं स्थानमा रहेको छ?', E'१०७ औं', E'१०८ औं', E'१०९ औं', E'११० औं', 'A', E'Transparency International को सार्वजनिक भ्रष्टाचार सूचकांक, २०२४ अनुसार नेपाल **१०७ औं स्थानमा** रहेको छ।\nनोट: नेपालले यस सूचकांकमा ३४ अंक प्राप्त गरेको छ। भ्रष्टाचार अवधारणा सूचकांक २०२३ अनुसार नेपाल १०८ औं स्थानमा थियो।', 'nepali'),
      (v_set_id, 22, E'२०८२ बाट लागु हुने गरि नेपालमा श्रमिकको न्यूनतम पारिश्रमिक मासिक कति निर्धारण गरिएको छ?', E'रु. १९, १२०', E'रु. १९, ५५०', E'रु. २०, १५०', E'रु. २०, ५५०', 'B', E'२०८२ साउन १ बाट लागु हुने गरि नेपालमा श्रमिकको न्यूनतम मासिक पारिश्रमिक **रु. १९, ५५०** निर्धारण गरिएको छ।\n- यसमा आधारभूत पारिश्रमिक रु. १२, १७० र महँगी भत्ता रु. ७,३८० समावेश छ।\nनोट: श्रम ऐन, २०७४ अनुसार प्रत्येक दुई वर्षमा न्यूनतम पारिश्रमिक निर्धारण गर्नुपर्ने प्रावधान छ।', 'nepali'),
      (v_set_id, 23, E'० डिग्री देशान्तर रेखा देखि १८० डिग्री देशान्तर बीच कति समयको फरक हुन्छ?', E'१० घण्टा', E'१२ घण्टा', E'१ घण्टा', E'२४ घण्टा', 'B', E'० डिग्री देशान्तर रेखा (प्रधानमध्याह्न रेखा) देखि १८० डिग्री देशान्तरसम्मको समय फरक **१२ घण्टा** हुन्छ। पृथ्वीको दैनिक गति र गोलाकार स्वरूपका कारण प्रत्येक १५ डिग्री देशान्तरमा १ घण्टाको समय फरक पर्छ।', 'nepali'),
      (v_set_id, 24, E'सोह्रौं योजनाको अन्त्य सम्म राष्ट्रिय परिचय-पत्र नम्बर प्राप्त पुर्याउने लक्ष्य रहेको छ?', E'७० प्रतिशत', E'८० प्रतिशत', E'९० प्रतिशत', E'१०० प्रतिशत', 'C', E'सोह्रौं योजनाको अन्त्यसम्म राष्ट्रिय परिचय-पत्र नम्बर प्राप्त गर्ने नेपाली नागरिकको लक्ष्य **९० प्रतिशत** रहेको छ।\n- निर्वाचनमा मतदाताको सहभागिता ६५ प्रतिशत पुर्याउने लक्ष्य छ।\n- अदालतमा दर्ता भएका मुद्दाको फछ्र्यौट ७५ प्रतिशत पुर्याउने लक्ष्य छ।\n- कुल विनियोजनमा खर्चको अनुपात ९० प्रतिशत पुर्याउने लक्ष्य छ।', 'nepali'),
      (v_set_id, 25, E'भागवत पुराणका लेखक को हुन्?', E'रत्नकार', E'शंकराचार्य', E'महर्षि वाल्मीकि', E'वेद व्यास', 'D', E'**भागवत पुराणका लेखक वेद व्यास हुन्।**\n- रत्नकार महर्षि वाल्मीकिको वास्तविक नाम हो।\n- शंकराचार्य हिन्दु धर्मका एक प्रमुख प्रचारक हुन्।\n- महर्षि वाल्मीकिले रामायणको रचना गरेका हुन्।\nनोट: द्वैपायन भन्नाले वेदव्यासलाई बुझिन्छ।', 'nepali'),
      (v_set_id, 26, E'कम्प्युटर-सम्बन्धित Bcc को पुरा रुप के हो?', E'Blind Carbon Copy', E'Blind Carbon Computer', E'Black Carbon Copy', E'Black Carbon Computer', 'A', E'कम्प्युटर-सम्बन्धित Bcc को पूरा रूप **Blind Carbon Copy** हो।\nनोट: यो इमेल पठाउँदा प्रयोग गरिने एक सुविधा हो, जहाँ प्राप्तकर्ताहरूले Bcc मा राखिएका अन्य प्राप्तकर्ताहरूलाई देख्न सक्दैनन्। Cc को पूरा रूप Carbon Copy हो।', 'nepali'),
      (v_set_id, 27, E'सुदूरपश्चिम प्रदेशको प्रसिद्ध राष्ट्रिय निकुञ्ज खप्तड राष्ट्रिय निकुञ्ज देहायका मध्ये कुन जिल्लामा अवस्थित छैन?', E'बैतडी', E'बझाङ', E'बाजुरा', E'डोटी', 'A', E'**खप्तड राष्ट्रिय निकुञ्ज बैतडी जिल्लामा अवस्थित छैन।**\n- खप्तड राष्ट्रिय निकुञ्ज बझाङ, बाजुरा, डोटी र अछाम जिल्लामा फैलिएको छ।\nनोट: खप्तड राष्ट्रिय निकुञ्जको स्थापना २०४२ सालमा भएको थियो र यसको क्षेत्रफल २२५ वर्ग कि.मि. छ।', 'nepali'),
      (v_set_id, 28, E'आर्थिक तथा सामाजिक परिषद सदस्यमा नेपाल हालसम्म कतिपटक निर्वाचित भएको छ?', E'३ पटक', E'४ पटक', E'५ पटक', E'२ पटक', 'B', E'नेपाल हालसम्म आर्थिक तथा सामाजिक परिषद (ECOSOC) को सदस्यमा **४ पटक** निर्वाचित भएको छ।\nनोट: नेपाल सन् १९६०-१९६२, २००१-२००३, २०१३-२०१५ र २०२४-२०२६ गरी चार कार्यकालका लागि निर्वाचित भएको हो।', 'nepali'),
      (v_set_id, 29, E'रेड टेर विश्व इतिहासको कुन क्रान्तिसँग सम्बन्धित रहेको छ?', E'फ्रान्सेली राज्य', E'रुसी राज्य', E'औद्योगिक', E'गौरवमय', 'A', E'**रेड टेर (The Reign of Terror) फ्रान्सेली राज्य क्रान्तिसँग सम्बन्धित छ।**\n- रुसी राज्य क्रान्ति (अक्टोबर क्रान्ति) सन् १९१७ मा भएको थियो।\n- औद्योगिक क्रान्ति १८औं शताब्दीको मध्यतिर बेलायतबाट सुरु भएको थियो।\n- गौरवमय क्रान्ति (Glorious Revolution) सन् १६८८ मा बेलायतमा भएको थियो।\nनोट: रेड टेरको समयमा सन् १७९३ देखि १७९४ सम्म हजारौं मानिसहरूलाई फाँसी दिइएको थियो।', 'nepali'),
      (v_set_id, 30, E'नेपालको प्रमाणिक राजा मानिने राजा पहिचान गरि सोही आधारमा टेकेर उनी कति औं लिच्छवि राजा हुन् पत्ता लगाउनुहोस्?', E'४१ औं', E'३९ औं', E'४० औं', E'४२ औं', 'B', E'नेपालको प्रमाणिक राजा मानिने राजा मानदेव लिच्छवि वंशका **३९ औं राजा** हुन्।\nनोट: राजा मानदेवले ४१ वर्ष (वि.सं. ५२१-५६२, ई.सं. ४६४-५०५) सम्म शासन गरेका थिए र उनी १६ औं पुस्ताका राजा हुन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/१७', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_20.csv  →  आसमान दैनिक GK — २०८२/०९/२०  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'चन्द्रमाको प्रकाश पृथ्वीमा आइपुग्न कति समय लाग्छ?', E'1.3 min', E'1.3 sec', E'8 Min 20 sec', E'8.2 sec', 'B', E'**१.३ सेकेण्ड।**\n- सूर्यको प्रकाश पृथ्वीमा आइपुग्न करिब ८ मिनेट २० सेकेण्ड (५०० सेकेण्ड) लाग्छ।\n- सूर्यको प्रकाश वृहस्पतिमा पुग्न करिब ४३ मिनेट लाग्छ।', 'nepali'),
      (v_set_id, 2, E'नेपाल र भारतको विवादित क्षेत्र लिम्पियाधुराको क्षेत्रफल कति रहेको छ?', E'३२४ वर्ग कि. मी.', E'३३५ वर्ग कि. मी.', E'३४५ वर्ग कि. मी.', E'३९५ वर्ग कि. मी.', 'B', E'नेपाल र भारतबीच विवादित क्षेत्र लिम्पियाधुराको क्षेत्रफल **३३५ वर्ग कि. मी.** रहेको छ।\nनोट: दार्चुला जिल्लाका लिम्पियाधुरा, कालापानी र लिपुलेक इलाकामा रहेका गुन्जी, नाभी, कुटी लगायतका केही भूभाग नेपालको क्षेत्रफलमा समावेश नभएको मानिन्छ। यी इलाका थप गर्दा नेपालको कुल क्षेत्रफल करिब १,४७,५१६ वर्ग कि.मि. पुग्ने अनुमान गरिएको छ।', 'nepali'),
      (v_set_id, 3, E'विश्व सबैभन्दा गहिरो नदी कङ्गो नदी (जायर नदी) को गहिराई लगभग कति रहेको छ?', E'लगभग २२० मिटर', E'लगभग ३२० मिटर', E'लगभग ४२० मिटर', E'लगभग ५२० मिटर', 'A', E'कङ्गो नदी (जायर नदी) विश्वको सबैभन्दा गहिरो नदी हो, जसको गहिराई लगभग **२२० मिटर** रहेको छ। यो नदी अफ्रिकाको दोस्रो लामो नदी पनि हो, जसको लम्बाई करिब ४७०० किलोमिटर छ। कङ्गो नदीले भूमध्य रेखालाई दुई पटक पार गर्छ।\nनोट: कङ्गो नदीको उत्पत्ति लौलाव र लौपुला नदीको दोभानमा (टैगाइकामा) हुने गर्दछ भने अन्य आन्ध्र महासागरमा हुन्छ।', 'nepali'),
      (v_set_id, 4, E'पर्यटन नीति-२०७२ कहिले सार्वजनिक गरिएको हो?', E'२०७२ साउन १२', E'२०७२ साउन १४', E'२०७२ साउन १६', E'२०७२ साउन १९', 'A', E'पर्यटन नीति-२०७२ **२०७२ साउन १२** गते सार्वजनिक गरिएको थियो।\nनोट: राष्ट्रिय पर्यटन नीति, २०७२ वि.सं. २०७२ असार १३ गते स्वीकृत भएको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपालको संविधान अनुसार देहायको कुन पदलाई महाभियोग लाग्दैन?', E'राष्ट्रपति', E'प्रधान न्यायाधीश', E'संवैधानिक निकायका प्रमुख', E'प्रधानमन्त्री', 'D', E'नेपालको संविधान अनुसार **प्रधानमन्त्री**लाई महाभियोग लाग्दैन।\n- राष्ट्रपति वा उपराष्ट्रपतिलाई महाभियोग लाग्न सक्छ।\n- प्रधान न्यायाधीश वा सर्वोच्च अदालतका न्यायाधीशलाई महाभियोग लाग्न सक्छ।\n- संवैधानिक निकायका प्रमुख वा पदाधिकारीका विरुद्ध (१३ वटा निकाय) महाभियोग लाग्न सक्छ।', 'nepali'),
      (v_set_id, 6, E'राष्ट्रिय गौरवको आयोजना मध्येको एक रानी जमरा कुलरिया सिँचाइ आयोजनाको उद्घाटन कहिले भएको हो?', E'२०७२ जेठ १३', E'२०७२ असार १३', E'२०७२ साउन १३', E'२०७२ भदौ १३', 'C', E'राष्ट्रिय गौरवको आयोजना मध्येको एक रानी जमरा कुलरिया सिँचाइ आयोजनाको उद्घाटन वि.सं. **२०७२ साउन १३** गते भएको थियो। यसको उद्घाटन तत्कालीन प्रधानमन्त्री केपी शर्मा ओलीद्वारा गरिएको थियो।\nनोट: यस आयोजनाबाट करिब २४ हजार ३०० हेक्टर जमिनमा सिँचाइ सुविधा उपलब्ध हुनेछ र यसको तेस्रो चरणको काम २०८५/८६ सम्म सम्पन्न गर्ने लक्ष्य रहेको छ।', 'nepali'),
      (v_set_id, 7, E'आ.व. २०८२/८३ को बजेट अघिल्लो आर्थिक वर्षको विनियोजनको तुलनामा कति ले बढी हो?', E'५.६ प्रतिशत', E'६.६ प्रतिशत', E'७.६ प्रतिशत', E'८.६ प्रतिशत', 'A', E'आ.व. २०८२/८३ को बजेट अघिल्लो आर्थिक वर्षको विनियोजनको तुलनामा **५.६ प्रतिशत**ले बढी हो।\nनोट: यो बजेट २०८२ जेठ १५ गते उपप्रधान तथा अर्थमन्त्री विष्णुप्रसाद पौडेलले संघीय संसदमा प्रस्तुत गरेका थिए।', 'nepali'),
      (v_set_id, 8, E'आर्थिक सर्वेक्षण, २०८१/८२ अनुसार प्रति हजार जनसंख्यामा कति चिकित्सक रहेको छन्?', E'१.१ चिकित्सक', E'१.२ चिकित्सक', E'१.३ चिकित्सक', E'१.४ चिकित्सक', 'A', E'आर्थिक सर्वेक्षण, २०८१/८२ अनुसार प्रति हजार जनसंख्यामा **१.१ चिकित्सक** रहेका छन्।\n- सोही सर्वेक्षण अनुसार प्रति हजार जनसंख्यामा २.८६ नर्स रहेका छन्।', 'nepali'),
      (v_set_id, 9, E'कर्मचारी सञ्चय कोषको स्थापना देहायका मध्ये कुन मितिमा भएको हो?', E'२०११ जेठ २५', E'२०११ चैत ४', E'२०११ भदौ ३१', E'२०११ पुस १', 'C', E'कर्मचारी सञ्चय कोषको स्थापना **२०११ भदौ ३१** मा भएको थियो।\n| संस्था | स्थापना मिति |\n| --- | --- |\n| राष्ट्रिय बीमा संस्थान | २०२४ पुस १ |\n| नागरिक लगानी कोष | २०४३ चैत ४ |\n| राष्ट्रिय बीमा कम्पनी लि. | २०३१ जेठ २८ |\n| नेपाल धितोपत्र बोर्ड | २०५० जेठ २५ |\n| सामाजिक सुरक्षा कोष | २०६७ चैत ७ |', 'nepali'),
      (v_set_id, 10, E'विश्व इतिहासमा औद्योगिक क्रान्ति कति वर्ष चलेको थियो?', E'६० वर्ष', E'७५ वर्ष', E'८५ वर्ष', E'९० वर्ष', 'A', E'विश्व इतिहासमा औद्योगिक क्रान्ति करिब **६० वर्ष** चलेको थियो।\n- विश्वको पहिलो औद्योगिक क्रान्ति बेलायतमा भएको थियो।', 'nepali'),
      (v_set_id, 11, E'प्रताप मल्ल नेपालमा कति वर्ष राजा बने?', E'३३ वर्ष', E'३५ वर्ष', E'३७ वर्ष', E'३९ वर्ष', 'A', E'कान्तिपुरका मल्ल राजा प्रताप मल्लले वि.सं. १६९६ देखि १७२९ सम्म गरी **३३ वर्ष** शासन गरेका थिए। उनी लक्ष्मीनरसिंह मल्लका छोरा थिए।', 'nepali'),
      (v_set_id, 12, E'रामायणको पात्र अनुसार रावणकी बहिनीको नाम के हो?', E'बज्रज्वाला', E'शूर्पणखा', E'मन्दोदरी', E'मकरध्वज', 'B', E'**रामायणका पात्र अनुसार रावणकी बहिनीको नाम शूर्पणखा हो।**\n- बज्रज्वाला रावणको भाइ कुम्भकर्णकी पत्नी हुन्।\n- मन्दोदरी रावणकी पत्नी हुन्।\n- मकरध्वज हनुमानका छोरा हुन्।', 'nepali'),
      (v_set_id, 13, E'मानव शरीरको कति प्रतिशत भाग खनिज पदार्थले बनेको हुन्छ?', E'२ प्रतिशत', E'४ प्रतिशत', E'७ प्रतिशत', E'९ प्रतिशत', 'B', E'मानव शरीरको कुल भागमध्ये **४ प्रतिशत** खनिज पदार्थले बनेको हुन्छ।\n- बाँकी ९६ प्रतिशत भाग पानी, कार्बोहाइड्रेट्स, प्रोटिन र चिल्लो पदार्थले बनेको हुन्छ।', 'nepali'),
      (v_set_id, 14, E'हाल नेपालमा संरक्षित घस्रने वन्यजन्तुको संख्या कति रहेको छ?', E'३ वटा', E'४ वटा', E'५ वटा', E'६ वटा', 'B', E'नेपालमा हाल संरक्षित घस्रने वन्यजन्तुको संख्या **४ वटा** रहेको छ।\n- यसमा अजिङ्गर, घडियाल गोही र सुन गोहोरो पर्दछन्।', 'nepali'),
      (v_set_id, 15, E'संयुक्त राष्ट्रसंघको सुरक्षा परिषदका अस्थायी राष्ट्रहरू मध्ये अफ्रो एसियाली (अफ्रिका र एसिया) क्षेत्रबाट कति सदस्य हुने गर्दछन्?', E'४ सदस्य', E'५ सदस्य', E'६ सदस्य', E'७ सदस्य', 'B', E'संयुक्त राष्ट्रसंघको सुरक्षा परिषदमा अफ्रो एसियाली (अफ्रिका र एसिया) क्षेत्रबाट **५ सदस्य** अस्थायी राष्ट्रहरू हुने गर्दछन्।\n- सुरक्षा परिषदका १० अस्थायी राष्ट्रहरूको क्षेत्रीय वितरण यस प्रकार छ:\n| स्थान | क्षेत्र | सदस्य संख्या |\n| --- | --- | --- |\n| १ | अफ्रो एसियाली (अफ्रिका र एसिया) | ५ |\n| २ | ल्याटिन अमेरिकी | २ |\n| ३ | पूर्वी युरोप | १ |\n| ४ | पश्चिम युरोप र अन्य | २ |', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२०', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_21.csv  →  आसमान दैनिक GK — २०८२/०९/२१  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'निर्माण सम्पन्न मध्ये नेपालको सबैभन्दा ठूलो जलविद्युत आयोजना पहिचान गरि सो कुन जिल्लामा अवस्थित रहेको छ पत्ता लगाउनुहोस्?', E'लमजुङ', E'स्याङ्जा', E'दोलखा', E'सोलुखुम्बु', 'C', E'**नेपालको सबैभन्दा ठूलो जलविद्युत आयोजना माथिल्लो तामाकोशी जलविद्युत आयोजना हो, जुन दोलखा जिल्लामा अवस्थित छ।**\n- स्याङ्जा जिल्लामा कालीगण्डकी ''ए'' जलविद्युत आयोजना (१४४ मेगावाट) रहेको छ।\n- लमजुङ जिल्लामा मध्य-मर्स्याङ्दी जलविद्युत आयोजना (७० मेगावाट) र माथिल्लो मर्स्याङ्दी ''ए'' जलविद्युत आयोजना (५० मेगावाट) जस्ता आयोजनाहरू छन्।\n- सोलुखुम्बु जिल्लामा सोलु खोला (दूधकोशी) जलविद्युत आयोजना (८६ मेगावाट) लगायतका आयोजनाहरू छन्।\nनोट: माथिल्लो तामाकोशी जलविद्युत आयोजनाको क्षमता ४५६ मेगावाट हो।', 'nepali'),
      (v_set_id, 2, E'नेपालको वर्तमान संविधानको कुन धारामा स्वच्छ वातावरणको हक उल्लेख गरेको छ?', E'धारा ३०', E'धारा ३२', E'धारा ३४', E'धारा २८', 'A', E'**नेपालको वर्तमान संविधानको धारा ३० मा स्वच्छ वातावरणको हक उल्लेख गरिएको छ।**\n- धारा २८ मा गोपनीयताको हकको व्यवस्था छ।\n- धारा ३२ मा भाषा तथा संस्कृतिको हकको व्यवस्था छ।\n- धारा ३४ मा श्रमको हकको व्यवस्था छ।', 'nepali'),
      (v_set_id, 3, E'सौर्यमण्डलको कुन ग्रहलाई ''Earth sister planet'' को उपनामले समेत चिनिन्छ?', E'शुक्र ग्रह', E'शनि ग्रह', E'मंगल ग्रह', E'बुध ग्रह', 'A', E'**शुक्र ग्रहलाई ''Earth sister planet'' (पृथ्वीको जुम्ल्याहा ग्रह) को उपनामले चिनिन्छ।**\n- शनि ग्रहलाई सौर्यमण्डलको दोस्रो ठूलो ग्रह र यसको सुन्दर घेराका लागि चिनिन्छ।\n- मंगल ग्रहलाई रातो ग्रह (Red Planet) भनिन्छ।\n- बुध ग्रह सौर्यमण्डलको सबैभन्दा सानो र सूर्यको सबैभन्दा नजिकको ग्रह हो।\nनोट: शुक्र ग्रहलाई बिहानको तारा (Morning Star) र साँझको तारा (Evening Star) पनि भनिन्छ।', 'nepali'),
      (v_set_id, 4, E'सबैभन्दा धेरै पिछडिएको स्थानीय तहमा सुचिकृत स्थानीय तहहरु कुन जिल्लामा अवस्थित रहेको छ?', E'बझाङ', E'बैतडी', E'अछाम', E'डोटी', 'A', E'**नेपालमा सबैभन्दा धेरै पिछडिएका स्थानीय तहहरू बझाङ जिल्लामा अवस्थित छन्।**\n- बैतडी जिल्ला सुदूरपश्चिम प्रदेशमा पर्ने एक पहाडी जिल्ला हो।\n- अछाम जिल्ला पनि सुदूरपश्चिम प्रदेशको एक पहाडी जिल्ला हो।\n- डोटी जिल्ला सुदूरपश्चिम प्रदेशमा पर्ने एक पहाडी जिल्ला हो।\nनोट: नेपालमा पिछडिएका स्थानीय तहको कुल सङ्ख्या २७ छ, जसमध्ये बझाङमा ६ वटा छन्।', 'nepali'),
      (v_set_id, 5, E'पहिलो साक्षर जिल्ला सिन्धुपाल्चोकलाई कहिले साक्षर जिल्लाको रुपमा घोषणा गरिएको हो?', E'२०७१ असार ४', E'२०७१ असार ८', E'२०७१ असार ६', E'२०७१ असार २', 'D', E'**सिन्धुपाल्चोकलाई २०७१ असार २ गते नेपालको पहिलो साक्षर जिल्लाको रूपमा घोषणा गरिएको थियो।**\n- हालसम्म नेपालका ६८ वटा जिल्लालाई साक्षर घोषणा गरिएको छ।\nनोट: पूर्ण साक्षर जिल्ला ललितपुर हो भने हालसम्मको अन्तिम साक्षर जिल्ला कालीकोट (२०८२ असोज ९) हो।', 'nepali'),
      (v_set_id, 6, E'आर्थिक सर्वेक्षण, २०७९/८० अनुसार नेपालको व्यापार घाटा रहेको छ?', E'१० खर्ब ७८ अर्ब ३१ करोड', E'१० खर्ब ८७ अर्ब २९ करोड', E'९ खर्ब ७८ अर्ब ३१ करोड', E'९ खर्ब ८७ अर्ब २९ करोड', 'D', E'**आर्थिक सर्वेक्षण, २०७९/८० अनुसार नेपालको व्यापार घाटा ९ खर्ब ८७ अर्ब २९ करोड रहेको छ।**\n- यो व्यापार घाटा अघिल्लो वर्षको तुलनामा ६.२ प्रतिशतले वृद्धि भएको हो।\nनोट: निर्यात व्यापारभन्दा आयात व्यापार बढी भएको अवस्थालाई व्यापार घाटा भनिन्छ।', 'nepali'),
      (v_set_id, 7, E'विश्व शान्ति सूचकांक २०२४ मा नेपाल कतिऔं स्थानमा रहेको छ?', E'७५ औं', E'७६ औं', E'७७ औं', E'७८ औं', 'B', E'**विश्व शान्ति सूचकांक २०२४ मा नेपाल ७६ औं स्थानमा रहेको छ।**\n- यो सूचकांक अस्ट्रेलियास्थित इन्स्टिच्युट फर इकोनोमिक्स एन्ड पिस (आईईपी) ले १६३ मुलुकको अध्ययन गरी सार्वजनिक गरेको हो।\nनोट: सार्क मुलुकमध्ये भुटान २१ औं स्थानमा रही पहिलो स्थानमा छ भने अफगानिस्तान १६३ औं स्थानमा रही अन्तिममा छ।', 'nepali'),
      (v_set_id, 8, E'पुस्तकालय दिवस, २०८२ को नारा के रहेको छ?', E'ज्ञानको केन्द्र: पुस्तकालय', E'पुस्तकालय: शिक्षा र सबलीकरण', E'हाम्रो पुस्तकालय: हाम्रो भविष्य', E'पुस्तकालय र प्रविधि हात हातमा', 'C', E'**सन् २०८२ को पुस्तकालय दिवसको नारा ''हाम्रो पुस्तकालय: हाम्रो भविष्य'' रहेको छ।**\n- नेपालमा भदौ १५ गतेलाई पुस्तकालय दिवसको रुपमा मनाइन्छ। वि.सं. २०६५ देखि मनाउन सुरु भएको यो दिवस २०८२ मा १६ औं पटक मनाइएको थियो।', 'nepali'),
      (v_set_id, 9, E'चिम्बोरोजो, कोटोपेक्सी (Cotopaxi) कुन मुलुकमा रहेको प्रसिद्ध शिखर हो?', E'अर्जेन्टिना', E'इक्वेडर', E'चिली', E'पेरू', 'B', E'**चिम्बोरोजो र कोटोपेक्सी दुवै इक्वेडरमा रहेका प्रसिद्ध शिखरहरू हुन्।**\n- अर्जेन्टिनामा एकोन्कागुवा (Aconcagua) हिमाल रहेको छ, जुन दक्षिण अमेरिकाको सबैभन्दा अग्लो शिखर हो।\n- चिलीमा ओजोस डेल सालाडो (Ojos del Salado) ज्वालामुखी पर्वत रहेको छ।\n- पेरूमा हुवास्करान (Huascarán) हिमाल रहेको छ।\nनोट: चिम्बोरोजो इक्वेडरको सबैभन्दा अग्लो हिमाल (६३१० मिटर) हो भने कोटोपेक्सी इक्वेडरको दोस्रो सबैभन्दा अग्लो ज्वालामुखी पहाड (५८९७ मिटर) हो। यी दुवै एन्डिज पर्वतमालामा पर्दछन्।', 'nepali'),
      (v_set_id, 10, E'विश्व इतिहासमा रोमको सभ्यता कुन नदी किनारमा विकास भएको थियो?', E'नाइल नदी', E'सिन्धु नदी', E'टाइबर नदी', E'टिग्रिस नदि', 'C', E'**रोमको सभ्यता टाइबर नदीको किनारमा विकसित भएको थियो।**\n- नाइल नदीको किनारमा मिश्रको सभ्यता विकसित भएको थियो।\n- सिन्धु नदी र रावी नदीको किनारमा सिन्धुघाँटीको सभ्यता विकसित भएको थियो।\n- टिग्रिस तथा युफ्रेटस नदीको किनारमा मेसोपोटामियाको सभ्यता विकसित भएको थियो।\nनोट: चिनियाँ सभ्यता ह्वाङ्हो नदी र याङ्सिक्याङ नदीको किनारमा विकसित भएको थियो।', 'nepali'),
      (v_set_id, 11, E'२९ औं किराँती राजा को हुन्?', E'हुमति', E'पटुको', E'गस्ती', E'स्थुको', 'B', E'**किराँत वंशका २९ औं राजा पटुको थिए।**\n- हुमति छैटौं किराँती राजा थिए।\n- जितेदास्तीलाई भाषा वंशावलीहरूले सातौं क्रममा राखेका छन्।\n- स्थुको चौथो पुस्तकका किराँती राजा थिए।\nनोट: पटुकोको पालामा किराँत काल विभाजन भएको थियो।', 'nepali'),
      (v_set_id, 12, E'चिण्डुके पर्व, डुक्के पर्व कुन समुदायमा प्रचलित रहेको छ?', E'मैथिली', E'मगर', E'गुरुङ', E'शेर्पा', 'B', E'**चिण्डुके पर्व र डुक्के पर्व मगर समुदायमा प्रचलित रहेका छन्।**\n- मैथिली समुदायमा जुडशीतल, फुलबारिया, डोरा पर्व, भुला पर्व र तुसरी समाचखेवा पर्व प्रचलित छन्।\n- गुरुङ समुदायमा ट्होटे पर्व र तमु ल्होसार मनाइन्छ।\n- शेर्पा समुदायमा डुम्जे पर्व र ग्याल्पो पर्व प्रचलित छन्।', 'nepali'),
      (v_set_id, 13, E'अल्बर्ट आइन्स्टाईनले कुन मुलुकको राष्ट्रपति बन्ने प्रस्तावलाई इन्कार गरेका थिए?', E'जर्मनी', E'इजरायल', E'भारत', E'अमेरिका', 'B', E'**अल्बर्ट आइन्स्टाईनले इजरायलको राष्ट्रपति बन्ने प्रस्तावलाई इन्कार गरेका थिए।**\n- जर्मनी अल्बर्ट आइन्स्टाईनको जन्मभूमि हो।\n- भारतले स्वतन्त्रता संग्राममा महात्मा गान्धी जस्ता महान् नेताहरू जन्माएको छ।\n- अमेरिकामा आइन्स्टाईनले आफ्नो जीवनको अन्तिम वर्षहरू बिताएका थिए र प्रिन्सटन विश्वविद्यालयमा काम गरेका थिए।\nनोट: आइन्स्टाईनलाई सन् १९५२ मा इजरायलको दोस्रो राष्ट्रपति बन्ने प्रस्ताव गरिएको थियो।', 'nepali'),
      (v_set_id, 14, E'विश्व सम्पदा सूचीमा परेका नेपालको राष्ट्रिय निकुञ्ज कतिवटा रहेका छन्?', E'१० वटा', E'४ वटा', E'३ वटा', E'२ वटा', 'D', E'**२ वटा।**\n- नेपालका सगरमाथा राष्ट्रिय निकुञ्ज र चितवन राष्ट्रिय निकुञ्ज विश्व सम्पदा सूचीमा परेका छन्।', 'nepali'),
      (v_set_id, 15, E'कुनै पनि सैनिक गुटमा आवद्ध नभइ अन्तर्राष्ट्रिय शान्तिको मान्यतालाई आत्मसात गरी तटस्थ रहने नीतिलाई के भनिन्छ?', E'सैनिक गुट नीति', E'शान्ति नीति', E'असंलग्नता नीति', E'असल छिमेकी नीति', 'C', E'**कुनै पनि सैनिक गुटमा आवद्ध नभइ अन्तर्राष्ट्रिय शान्तिको मान्यतालाई आत्मसात गरी तटस्थ रहने नीतिलाई असंलग्नता नीति भनिन्छ।**\n- सैनिक गुट नीतिले राष्ट्रहरूलाई सैन्य गठबन्धनमा सामेल गराउँछ।\n- शान्ति नीतिले द्वन्द्व समाधान र अन्तर्राष्ट्रिय सहयोगमा जोड दिन्छ।\n- असल छिमेकी नीतिले छिमेकी राष्ट्रहरूसँगको सम्बन्ध सुदृढ गर्नमा केन्द्रित हुन्छ।\nनोट: दोस्रो विश्वयुद्धपछि विश्व दुई ध्रुवमा विभक्त हुँदा साना राष्ट्रहरूको स्वतन्त्रता र अस्तित्व कायम राख्न असंलग्न आन्दोलनको प्रादुर्भाव भएको थियो। नेपालले सन् १९५५ को बाङडुङ सम्मेलनपछि यस नीतिको समर्थन गर्दै आएको छ।', 'nepali'),
      (v_set_id, 16, E'सिंहदरबारको स्थापना कुन राणा प्रधानमन्त्रीको पालामा भएको थियो?', E'देव समसेर', E'भिम समसेर', E'वीर समसेर', E'चन्द्र समसेर', 'D', E'सिंहदरबारको स्थापना प्रधानमन्त्री **चन्द्र समसेरको** पालामा भएको थियो।\n- देव समसेरले गोरखापत्रको प्रकाशन र ''श्री ३ महाराज देवशमशेर'' नामको सिक्का प्रचलनमा ल्याएका थिए।\n- भिम समसेरले काठमाडौंमा खानेपानीको लागि पाइपलाइन विस्तार र चारखाल अड्डाको स्थापना गरेका थिए।\n- वीर समसेरले नारायणहिटी राजदरबार, लालदरबार र सेतो दरबारको निर्माण गराएका थिए।\nनोट: चन्द्र समसेरले सिंहदरबारका साथै मिलिटरी अस्पताल र सैनिक अस्पतालको पनि स्थापना गरेका थिए।', 'nepali'),
      (v_set_id, 17, E'हिन्दु धर्मका १६ संस्कार मध्ये कति संस्कार जन्म पूर्व नै गरिन्छ?', E'३ संस्कार', E'४ संस्कार', E'५ संस्कार', E'६ संस्कार', 'A', E'हिन्दु धर्मका १६ संस्कार मध्ये **३ वटा संस्कार** जन्म पूर्व नै गरिन्छ।\nती संस्कारहरू निम्नानुसार छन्:\n- १. गर्भाधान संस्कार\n- २. पुंसवन संस्कार\n- ३. सिमन्तोन्नयन संस्कार\nनोट: हिन्दु धर्ममा कुल १६ संस्कारहरू रहेका छन्, जसमध्ये बाँकी १३ वटा जन्मेपछि गरिन्छ।', 'nepali'),
      (v_set_id, 18, E'विश्वमा सर्वप्रथम Tissue culture कसमा प्रयोग गरिएको थियो?', E'च्याउ', E'आलु', E'भेडा', E'टमाटर', 'B', E'विश्वमा सर्वप्रथम टिस्यु कल्चरको प्रयोग **आलुमा** गरिएको थियो। यो प्रविधि बोटबिरुवाको सानो तन्तु वा कोषबाट प्रयोगशालामा पूरै बोट विकास गर्न प्रयोग गरिन्छ।', 'nepali'),
      (v_set_id, 19, E'Lady jackson उपनामले कुन वातावरणशास्त्रीलाई चिनिन्छ?', E'ए जी टान्सली', E'बार्बरा वार्ड', E'ग्रो हार्लेम', E'कार्ल एलेरी', 'B', E'''लेडी ज्याक्सन'' उपनामले बेलायती वातावरणशास्त्री **बार्बरा वार्ड**लाई चिनिन्छ। उनले ''दिगो विकास'' (Sustainable Development) शब्दको सबैभन्दा पहिले प्रयोग गरेकी थिइन्।\nनोट: वार्डले सन् १९७२ मा प्रकाशित आफ्नो पुस्तक ''The Only Earth'' मार्फत यो अवधारणालाई अगाडि बढाएकी थिइन्, जबकि दिगो विकासको अवधारणाले सन् १९८० को दशकबाट व्यापकता पाएको हो।', 'nepali'),
      (v_set_id, 20, E'विश्व शान्ति सूचकांक - २०२४ अनुसार नेपाल कति औं स्थानमा रहेको छ?', E'७४ औं स्थान', E'७५ औं स्थान', E'७६ औं स्थान', E'७७ औं स्थान', 'C', E'विश्व शान्ति सूचकांक (Global Peace Index) २०२४ अनुसार नेपाल **७६ औं स्थानमा** रहेको छ। यस सूचकांकमा नेपालले १.९८७ अंक प्राप्त गरेको छ।\nनोट: २०२४ को सूचकांकमा पहिलो स्थानमा आइसल्याण्ड र अन्तिम स्थानमा रुस रहेका छन्।', 'nepali'),
      (v_set_id, 21, E'विश्व इतिहासलाई हेरोडोटसले कति भागमा विभाजन गरेका थिए?', E'३ वटा', E'४ वटा', E'५ वटा', E'६ वटा', 'C', E'इतिहासका पिता मानिने हेरोडोटसले विश्व इतिहासलाई **५ वटा** भागमा विभाजन गरेका थिए। ती ५ भागहरू प्राग ऐतिहासिक युग, प्राचिन युग, मध्यकालिन युग, आधुनिक युग र समकालिन युग हुन्।', 'nepali'),
      (v_set_id, 22, E'एसिया कप टी-२० क्रिकेट, २०२४ को उपाधी कुन मुलुकले प्राप्त गरेको छ?', E'भारत', E'पाकिस्तान', E'बंगलादेश', E'श्रीलंका', 'A', E'**एसिया कप टी-२० क्रिकेट, २०२४ को उपाधि भारतले जितेको हो।** फाइनलमा भारतले पाकिस्तानलाई ५ विकेटले पराजित गरेको थियो।\n- पाकिस्तान उपविजेता बनेको थियो।\n- बंगलादेश र श्रीलंका सुपर ४ चरणसम्म पुगेका अन्य टोलीहरू थिए।\nनोट: यो प्रतियोगिता सन् २०२४ सेप्टेम्बर ९ देखि २८ सम्म संयुक्त अरब इमिरेट्स (UAE) मा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 23, E'आर्थिक सर्वेक्षण, २०७९/८० अनुसार सबैभन्दा धेरै आर्थिक वृद्धि भएको प्रदेश कुन हो?', E'कोशी प्रदेश', E'लुम्बिनी प्रदेश', E'गण्डकी प्रदेश', E'बागमती प्रदेश', 'C', E'आर्थिक सर्वेक्षण, २०७९/८० अनुसार सबैभन्दा धेरै आर्थिक वृद्धि **गण्डकी प्रदेशमा** भएको छ, जसको वृद्धिदर ५.५१% रहने अनुमान छ।\n- कोशी प्रदेशको आर्थिक वृद्धिदर ३.३६% रहने अनुमान छ।\n- लुम्बिनी प्रदेशको आर्थिक वृद्धिदर ४.७०% रहने अनुमान छ।\n- बागमती प्रदेशको आर्थिक वृद्धिदर ५.१८% रहने अनुमान छ।\nनोट: यस सर्वेक्षण अनुसार सबैभन्दा कम आर्थिक वृद्धिदर सुदूरपश्चिम प्रदेशको (३.३२%) रहने अनुमान गरिएको छ।', 'nepali'),
      (v_set_id, 24, E'राष्ट्रिय जनगणना, २०७८ अनुसार हाल नेपालमा महिलाको साक्षरता दर कति रहेको छ?', E'६९.४ प्रतिशत', E'६५.८ प्रतिशत', E'७६.२ प्रतिशत', E'८३.६ प्रतिशत', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा महिलाको साक्षरता दर **६९.४ प्रतिशत** रहेको छ। सोही जनगणना अनुसार पुरुष साक्षरता दर ८३.६ प्रतिशत र देशको कुल साक्षरता दर ७६.२ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 25, E'नेपाल संघीय लोकतान्त्रिक गणतन्त्रात्मक राज्य हो भन्ने कुरा नेपालको संविधानको कुन धारामा उल्लेख गरेको छ?', E'धारा १', E'धारा २', E'धारा ३', E'धारा ४', 'D', E'नेपालको संविधानको **धारा ४** मा नेपाललाई ''स्वतन्त्र, अविभाज्य, सार्वभौमसत्तासम्पन्न, धर्मनिरपेक्ष, समावेशी, लोकतन्त्रात्मक, समाजवाद उन्मुख, संघीय लोकतान्त्रिक गणतन्त्रात्मक राज्य'' को रूपमा परिभाषित गरिएको छ।', 'nepali'),
      (v_set_id, 26, E'सबैभन्दा टाढाको ग्रह बरुण सूर्यबाट कति दुरीमा रहेको छ?', E'४.५ बिलियन कि.मि.', E'५.५ बिलियन कि.मि.', E'६.५ बिलियन कि.मि.', E'७.५ बिलियन कि.मि.', 'A', E'सूर्यबाट सबैभन्दा टाढाको ग्रह बरुण (Neptune) को दुरी **४.५ बिलियन किलोमिटर** (२.८ बिलियन माइल) रहेको छ।\nनोट: बरुण हाम्रो सौर्यमण्डलको आठौं ग्रह र चौथो ठूलो ग्रह हो।', 'nepali'),
      (v_set_id, 27, E'सबैभन्दा थोरै नगरपालिका भएको प्रदेश कर्णालीमा जम्मा कतिवटा नगरपालिका रहेको छन्?', E'२७ वटा', E'२५ वटा', E'२९ वटा', E'२४ वटा', 'B', E'कर्णाली प्रदेशमा जम्मा **२५ वटा** नगरपालिकाहरू रहेका छन्, जुन नेपालका सात प्रदेशमध्ये सबैभन्दा कम हो।\nनोट: कर्णाली प्रदेशमा स्थानीय तहको संख्या पनि सबैभन्दा कम (७९) रहेको छ।', 'nepali'),
      (v_set_id, 28, E'उत्तर अमेरिकाको सबैभन्दा ठूलो मुलुक कुन हो?', E'क्यानाडा', E'अमेरिका', E'मेक्सिको', E'ब्राजिल', 'A', E'उत्तर अमेरिका महादेशको सबैभन्दा ठूलो मुलुक **क्यानाडा** हो। यस महादेशको सबैभन्दा सानो मुलुक सेन्ट किट्स र नेभिस हो।\nनोट: दक्षिण अमेरिकाको सबैभन्दा ठूलो मुलुक ब्राजिल र सानो मुलुक त्रिनिडाड र टोबागो हो।', 'nepali'),
      (v_set_id, 29, E'संयुक्त राष्ट्रसंघको सदस्यताका लागि नेपालले निवेदन दिँदा नेपालका प्रधानमन्त्री को थिए?', E'वि पि कोइराला', E'टंक प्र. आचार्य', E'मोहन सम्सेर', E'मातृका प्र कोइराला', 'C', E'नेपालले सन् १९४९ फेब्रुअरी १३ मा संयुक्त राष्ट्रसंघको सदस्यताका लागि निवेदन दिँदा प्रधानमन्त्री **मोहन शमसेर** थिए।\n- टंक प्रसाद आचार्य नेपालले सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गर्दाका प्रधानमन्त्री थिए।\n- वि पि कोइराला नेपालका प्रथम जननिर्वाचित प्रधानमन्त्री हुन्।\n- मातृका प्रसाद कोइराला नेपालका प्रथम गैर-राणा प्रधानमन्त्री थिए।', 'nepali'),
      (v_set_id, 30, E'भित्रि मधेशको अवस्थिति देहाएका मध्ये कुन विकल्प सहि छ?', E'चुरे र भावर विचमा', E'चुरे र महाभारत विचमा', E'महाभारत र भावर विचमा', E'महाभारत र मध्यभूमी विचमा', 'B', E'भित्री मधेश **चुरे र महाभारत पर्वत श्रेणीको बीचमा** अवस्थित छ। समुन्द्र सतहदेखि ६१० मिटरको उचाइसम्म चारैतिर पहाड पर्वतले घेरिएर फैलिएका विशाल फाँटलाई भित्री मधेश वा दून क्षेत्र भनिन्छ।\nनोट: यो क्षेत्रले मुलुकको कुल क्षेत्रफलको ८.५ प्रतिशत भू-भाग समेटेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२१', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_22.csv  →  आसमान दैनिक GK — २०८२/०९/२२  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'ज्योतिषशास्त्र वा नक्षत्रशास्त्रको अध्ययन गर्ने विज्ञानलाई के भनिन्छ?', E'Astronomy', E'Astrology', E'Astronomer', E'Cosmology', 'B', E'ज्योतिषशास्त्र वा नक्षत्रशास्त्रको अध्ययन गर्ने विज्ञानलाई **Astrology** भनिन्छ।\n- Astronomy अन्तरिक्ष विज्ञान हो, जसले आकाशीय पिण्डहरूको बारेमा अध्ययन गर्दछ।\n- Astronomer भनेको अन्तरिक्षविद् वा खगोलविद् (Astronauts) हो।\n- Cosmology ले ब्रह्माण्ड, यसको सृष्टि, उत्पत्ति र विकासको अध्ययन गर्दछ।', 'nepali'),
      (v_set_id, 2, E'भूगोल (Geography) शब्दमा Geo को शाब्दिक अर्थ के हो?', E'महादेश', E'भूमी', E'पृथ्वी', E'माटो', 'C', E'भूगोल (Geography) शब्दमा ''Geo'' को शाब्दिक अर्थ **पृथ्वी (Earth)** हो। यो शब्द ग्रिक भाषाबाट आएको हो, जहाँ ''Geo'' को अर्थ पृथ्वी र ''Graphy'' को अर्थ वर्णन (Description) हुन्छ।\nनोट: ग्रिक नागरिक इरेटोस्थनिजले पृथ्वीको अध्ययन गर्ने शास्त्रलाई भूगोल (Geography) नाम दिएका हुन्।', 'nepali'),
      (v_set_id, 3, E'नेपालको इतिहासमा पोलिमरको मुद्रा प्रचलनमा ल्याउने राजा को हुन्?', E'पृथ्वी विक्रम', E'त्रिभुवन शाह', E'ज्ञानेन्द्र शाह', E'प्रताप मल्ल', 'C', E'नेपालको इतिहासमा **पोलिमर र प्लास्टिकको नोट** प्रचलनमा ल्याउने राजा ज्ञानेन्द्र शाह हुन्।\n- पृथ्वी विक्रमले बीचमा प्वाल परेको मुद्रा प्रचलनमा ल्याएका थिए।\n- त्रिभुवन शाहले कागजी नोटको सुरुवात गरेका थिए।\n- प्रताप मल्लले चारकुने मुद्रा (डबल) प्रचलनमा ल्याएका थिए।', 'nepali'),
      (v_set_id, 4, E'डोलाजी प्रथाको माध्यमबाट राजा बनेका राजाको हुन्?', E'भुपातिन्द्र मल्ल', E'लक्ष्मीनरसिंह मल्ल', E'सिद्धिनरसिंह मल्ल', E'जयस्थिती मल्ल', 'D', E'महारानी देवलदेवीले **जयस्थिति मल्लको डोला झिकाई** राजल्लदेवीसँग विवाह गराइदिएपछि उनी राजा बनेका थिए। डोलाजी प्रथा अनुसार, डोला झिकाएर विवाह गरिएको पुरुषको वंश परिवर्तन नभई छोरासरह सम्पत्ति र राजकाजमा अधिकार कायम हुन्थ्यो।', 'nepali'),
      (v_set_id, 5, E'२०८१ सालको मदन पुरस्कारका लागि छनोटमा परेका पुस्तक छालबाटो कसको कृति हो?', E'छुटेन काविमा', E'रमेश भुसाल', E'कुमारी लामा', E'श्रेयज सुवेदी', 'B', E'२०८१ सालको मदन पुरस्कारका लागि छनोटमा परेको पुस्तक ''छालबाटो'' का लेखक **रमेश भुसाल** हुन्।\n- छुटेन काविमा ''उरमाल'' कृतिका लेखक हुन्।\n- कुमारी लामा ''दर्ज्यु संलाप'' कृतिकी लेखिका हुन्।\n- श्रेयज सुवेदी ''बहुरूपी'' कृतिका लेखक हुन्।', 'nepali'),
      (v_set_id, 6, E'सोह्रौं योजनाको अन्त्य सम्म मातृमृत्युदर (प्रतिलाख जीवित जन्ममा) कति पुर्याउने लक्ष्य रहेको छ?', E'७५ जना', E'८५ जना', E'९५ जना', E'६५ जना', 'B', E'सोह्रौं योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्ममा मातृमृत्युदर प्रतिलाख जीवित जन्ममा **८५ जनामा** झार्ने लक्ष्य राखिएको छ।\nनोट: सोही योजनाले नवजात शिशुमृत्युदर प्रतिहजार जीवित जन्ममा १३ जना र बालमृत्युदर प्रतिहजार जीवित जन्ममा २२ जनामा झार्ने लक्ष्य लिएको छ।', 'nepali'),
      (v_set_id, 7, E'गोपालप्रसाद रिमाल पुरस्कार, २०८२ बाट सम्मानित हुने स्रष्टा को हुनुहुन्छ?', E'आङ छिरिङ शेर्पा', E'मेघराज शर्मा', E'सजना धिमाल', E'मोहन दुवाल', 'B', E'गोपालप्रसाद रिमाल पुरस्कार, २०८२ बाट कवि मञ्जुल अर्थात् **मेघराज शर्मा (नेपाल)** सम्मानित हुने भएका छन्।\n- आङ छिरिङ शेर्पाले मदन भण्डारी राष्ट्रिय पुरस्कार, २०८२ प्राप्त गर्नेछन्।\n- डा. सजना धिमालले धिमाल युवा प्रतिभा पुरस्कार, २०८२ प्राप्त गर्नेछिन्।\n- साहित्यकार मोहन दुवालले कमल राष्ट्रिय सुकर्म पुरस्कार, २०८१ प्राप्त गरेका थिए।', 'nepali'),
      (v_set_id, 8, E'नेपालको संविधान अनुसार राष्ट्रिय झण्डा कति कोणयुक्त सूर्य हुने व्यवस्था रहेको छ?', E'दश', E'आठ', E'बाह्र', E'सोह्र', 'C', E'नेपालको संविधान अनुसार राष्ट्रिय झण्डाको तल्लो भागमा रहने सूर्य **बाह्र कोणयुक्त** हुने व्यवस्था छ। झण्डाको माथिल्लो भागमा रहने चन्द्रमामा भने सोह्रमध्ये आठ कोण देखिने सेतो आकार रहेको हुन्छ।\nनोट: राष्ट्रिय झण्डा सम्बन्धी यो व्यवस्था संविधानको धारा ८ मा उल्लेख गरिएको छ।', 'nepali'),
      (v_set_id, 9, E'स्वास्थ्य क्षेत्रका घोषणाहरू मध्ये नेपालमा पोलियो मुक्त घोषणा कहिले भएको थियो?', E'२०७० चैत्र १३', E'२०६६ माघ ५', E'२०७४ जेठ २८', E'२०३४ वैशाख १', 'A', E'**नेपालमा पोलियो मुक्त घोषणा २०७० चैत्र १३ मा भएको थियो।**\n- २०६६ माघ ५ मा नेपाललाई कुष्ठरोग मुक्त घोषणा गरिएको थियो।\n- २०७४ जेठ २८ मा नेपाललाई बर्डफ्लू मुक्त घोषणा गरिएको थियो।\n- २०३४ वैशाख १ मा नेपालबाट बिफर उन्मूलनको घोषणा भएको थियो।', 'nepali'),
      (v_set_id, 10, E'अन्टार्कटिका महादेशमा घुसेका दुई समुन्द्रहरू कुन-कुन हुन्?', E'रोस र लाल', E'बेरिङ र वेडेल', E'रोस र बेरिङ', E'रोस र वेडेल', 'D', E'अन्टार्कटिका महादेशमा घुसेका दुई प्रमुख समुन्द्रहरू **रोस र वेडेल** हुन्। रोस सागर प्रशान्त महासागरको भाग हो भने वेडेल सागर आन्ध्र महासागरको भाग हो।\nनोट: वेडेल सागरलाई विश्वको सबैभन्दा स्वच्छ पानीको समुन्द्र मानिन्छ।', 'nepali'),
      (v_set_id, 11, E'नेपालको अन्नपूर्ण हिमाल विश्वको कति औं अग्लो शिखर हो?', E'नवौं', E'आठौं', E'दशौं', E'एघारौं', 'C', E'अन्नपूर्ण हिमाल विश्वको **दशौं** अग्लो शिखर हो, जसको उचाइ ८,०९१ मिटर छ। यो हिमाल नेपालको भने आठौं अग्लो शिखर हो।\nनोट: विश्वको नवौं अग्लो शिखर पाकिस्तानमा अवस्थित नंगा पर्वत हो।', 'nepali'),
      (v_set_id, 12, E'गौरवमय क्रान्तिका समयमा बेलायतका राजा को थिए?', E'जेम्स द्वितीय', E'निकोलस द्वितीय', E'चार्ल्स द्वितीय', E'जोन द्वितीय', 'A', E'सन् १६८८ मा बेलायतमा भएको गौरवमय क्रान्तिका समयमा त्यहाँका राजा **जेम्स द्वितीय** थिए।\nनोट: रुसी राज्यक्रान्तिको बेला भने रुसका राजा (जार) निकोलस द्वितीय थिए।', 'nepali'),
      (v_set_id, 13, E'कम्प्युटर हार्डवेयर भन्नाले के जनाउँछ?', E'कम्प्युटरको सफ्टवेयर भाग', E'देख्न र छुन नसकिने भाग', E'देख्न र छुन सकिने भौतिक उपकरणहरू', E'इन्टरनेट सेवा', 'C', E'कम्प्युटर हार्डवेयर भन्नाले कम्प्युटरका **देख्न र छुन सकिने भौतिक उपकरणहरू** जस्तै किबोर्ड, माउस, मनिटर, प्रिन्टर आदिलाई जनाउँछ। यसको विपरित, सफ्टवेयर भनेको देख्न र छुन नसकिने प्रोग्रामहरूको समूह हो।', 'nepali'),
      (v_set_id, 14, E'मकालु बरुण राष्ट्रिय निकुञ्ज कुन कुन जिल्लामा अवस्थित रहेको छ?', E'रसुवा र सिन्धुपाल्चोक', E'संखुवासभा र ताप्लेजुङ', E'नुवाकोट र सिन्धुपाल्चोक', E'संखुवासभा र सोलुखुम्बु', 'D', E'मकालु बरुण राष्ट्रिय निकुञ्ज **संखुवासभा र सोलुखुम्बु** जिल्लामा अवस्थित छ। यो निकुञ्ज वि.सं. २०४८ मा स्थापना भएको हो र यसको क्षेत्रफल १५०० वर्ग किलोमिटर रहेको छ।\nनोट: यस निकुञ्जमा २० प्रकारको पारिस्थितिक प्रणाली पाइन्छ।', 'nepali'),
      (v_set_id, 15, E'संयुक्त राष्ट्रसंघका लागि सबैभन्दा धेरै शान्ति सैनिक पठाउने देशमा हाल नेपालको स्थान कतिमा रहेको छ?', E'पहिलो', E'दोस्रो', E'तेस्रो', E'चौथो', 'A', E'संयुक्त राष्ट्रसंघका लागि सबैभन्दा धेरै शान्ति सैनिक पठाउने देशमा हाल नेपाल **पहिलो** स्थानमा रहेको छ। नेपालले ५,८६५ सैनिकसहित कुल ६,२४७ सुरक्षाकर्मी १५ वटा शान्ति अभियानमा खटाएकाले अघिल्लो वर्ष पहिलो स्थानमा रहेको बंगलादेशलाई पछि पारेको हो।', 'nepali'),
      (v_set_id, 16, E'नेपालको पहिलो औपचारिक होम स्टे कुन हो?', E'चल्ले गाउँ', E'भादा गाउँ', E'सिरुबारी', E'नगरकोट', 'C', E'स्याङ्जाको सिरुबारी नेपालको पहिलो औपचारिक होम स्टे हो। नेपालमा औपचारिक रुपमा होम स्टेको सुरुवात **वि.सं. २०६७ भाद्र १** गतेबाट भएको थियो।', 'nepali'),
      (v_set_id, 17, E'गैरआवासीय नागरिकता प्राप्त गरेको व्यक्तिले कुन अधिकार उपभोग गर्न पाउँदैन?', E'सामाजिक', E'सांस्कृतिक', E'राजनैतिक', E'आर्थिक', 'C', E'नेपालको संविधान अनुसार, गैरआवासीय नागरिकता प्राप्त व्यक्तिले आर्थिक, सामाजिक र सांस्कृतिक अधिकार उपभोग गर्न पाउँछन् तर **राजनैतिक अधिकार** उपभोग गर्न पाउँदैनन्। सार्क मुलुक बाहेक अन्य देशमा बसोबास गर्ने र पहिले वंशज वा जन्मको आधारमा नेपाली नागरिक रहेका व्यक्ति वा तिनका सन्ततिले यस्तो नागरिकता प्राप्त गर्न सक्छन्।', 'nepali'),
      (v_set_id, 18, E'हाम्रो सौर्यमण्डलको सबैभन्दा नजिकको तारा कुन हो?', E'UY scuit', E'प्रोक्सिमा सेन्चुरी', E'साइरस', E'ध्रुवतारा', 'B', E'हाम्रो सौर्यमण्डलको सबैभन्दा नजिकको तारा **प्रोक्सिमा सेन्चुरी** हो।\n- UY scuit (स्कुट) ब्रह्माण्डमा ज्ञात सबैभन्दा ठूलो ताराहरू मध्ये एक हो।\n- साइरस पृथ्वीको रात्रि आकाशमा देखिने सबैभन्दा चम्किलो तारा हो।\n- ध्रुवतारा (Polaris) उत्तरी ध्रुवको आकाशमा देखिने तारा हो, जसले दिशा पत्ता लगाउन मद्दत गर्छ।', 'nepali'),
      (v_set_id, 19, E'सबैभन्दा बढी क्षति कुन प्रकारको भूकम्पको तरङ्गले गर्दछ?', E'D wave', E'P wave', E'S wave', E'L wave', 'D', E'भूकम्पमा सबैभन्दा बढी क्षति **L wave (धरातलीय तरङ्ग)** ले गर्दछ।\n- P wave (प्राथमिक तरङ्ग) सबैभन्दा तीव्र गतिमा यात्रा गर्छ तर यसले सबैभन्दा कम क्षति पुर्याउँछ।\n- S wave (द्वितीय तरङ्ग) P wave भन्दा ढिलो हुन्छ र यसले औषत क्षति गर्दछ।\n- D wave भूकम्पको तरङ्गको मानक प्रकार होइन।\nनोट: L तरङ्गहरू पृथ्वीको सतहमा मात्र यात्रा गर्छन् र यिनीहरूको ''amplitude'' ठूलो हुने भएकाले सबैभन्दा विनाशकारी हुन्छन्।', 'nepali'),
      (v_set_id, 20, E'नेपालको भूगोलमा २ उपमहानगरपालिका भएको जिल्लाको संख्या कति रहेको छ?', E'३ वटा', E'६ वटा', E'५ वटा', E'४ वटा', 'A', E'नेपालमा २ वटा उपमहानगरपालिका भएका जिल्लाहरूको संख्या **३ वटा** रहेको छ।\nनोट: ती जिल्लाहरू सुनसरी (धरान र इटहरी), बारा (कलैया र जितपुर सिमरा), र दाङ (तुलसीपुर र घोराहि) हुन्।', 'nepali'),
      (v_set_id, 21, E'वर्ल्ड इको आउटलुकको प्रतिवेदन, २०२४ अनुसार विश्वको तेस्रो ठूलो अर्थतन्त्र भएको मुलुक कुन हो?', E'जापान', E'चीन', E'जर्मनी', E'भारत', 'C', E'वर्ल्ड इको आउटलुक, २०२४ अनुसार **जर्मनी** विश्वको तेस्रो ठूलो अर्थतन्त्र भएको मुलुक हो।\n- चीन विश्वको दोस्रो ठूलो अर्थतन्त्र हो।\n- जापान विश्वको चौथो ठूलो अर्थतन्त्रमा झरेको छ।\n- भारत विश्वको पाँचौं ठूलो अर्थतन्त्र हो।\nनोट: सो प्रतिवेदन अनुसार संयुक्त राज्य अमेरिका (३०.५०७ ट्रिलियन डलर) विश्वको सबैभन्दा ठूलो अर्थतन्त्र हो।', 'nepali'),
      (v_set_id, 22, E'१० औं राष्ट्रिय खेलकुदको लोगो र मस्कट सार्वजनिक कहिले गरिएको हो ?', E'२०८१ चैत ४', E'२०८१ चैत ५', E'२०८१ चैत ६', E'२०८१ चैत ७', 'B', E'१० औं राष्ट्रिय खेलकुदको लोगो र मस्कट **२०८१ चैत ५** गते सार्वजनिक गरिएको थियो।\nनोट: उक्त खेलकुद २०८२ फागुन १ देखि ७ सम्म कर्णाली प्रदेशको सुर्खेतमा आयोजना हुनेछ र यसको लोगो र मस्कट विकास तमकुजुले बनाएका हुन्।', 'nepali'),
      (v_set_id, 23, E'आर्थिक सर्वेक्षण २०८०/८१ अनुसार हाल नेपालमा मातृमृत्युदर कति रहेको छ?', E'१५१ प्रतिलाख', E'१६१ प्रतिलाख', E'१७१ प्रतिलाख', E'१८१ प्रतिलाख', 'A', E'आर्थिक सर्वेक्षण २०८०/८१ अनुसार हाल नेपालमा मातृमृत्युदर **१५१ प्रतिलाख** (प्रति एक लाख जीवित जन्ममा) रहेको छ।\nनोट: सोही सर्वेक्षण अनुसार नवजात शिशु मृत्युदर प्रति हजार जीवित जन्ममा २१ रहेको छ।', 'nepali'),
      (v_set_id, 24, E'विश्वमा शासक र सम्राटको उदय कुन मानव सभ्यताको देन हो?', E'मिश्रको सभ्यता', E'युनानी सभ्यता', E'मेसोपोटामिया सभ्यता', E'सिन्धुघाँटीको सभ्यता', 'C', E'विश्वमा शासक र सम्राटको उदय **मेसोपोटामिया सभ्यताको** देन हो।\n- मिश्रको सभ्यता पिरामिड र फारो (Pharaoh) शासकहरूका लागि परिचित छ।\n- युनानी सभ्यता प्रजातन्त्र, दर्शन र ओलम्पिक खेलको सुरुवातका लागि चिनिन्छ।\n- सिन्धुघाँटीको सभ्यता आफ्नो व्यवस्थित शहरी योजना र जल निकास प्रणालीका लागि प्रख्यात थियो।\nनोट: मेसोपोटामियाको सुमेरियनकालमा राजालाई ''पटेसी'' भनिन्थ्यो र यहाँ ''जस्तालाई तस्तै'' (Eye for eye, tooth for tooth) भन्ने न्याय व्यवस्था थियो।', 'nepali'),
      (v_set_id, 25, E'कवि चुडामणी सम्राट उपनामले कुन मल्ल राजालाई चिनिन्छ?', E'प्रताप मल्ल', E'यक्ष मल्ल', E'जयस्थिती मल्ल', E'भुपालेन्द्र मल्ल', 'D', E'कवि चुडामणी सम्राट उपनामले **भुपालेन्द्र मल्ललाई** चिनिन्छ।\n- प्रताप मल्ललाई ''कविन्द्र'' उपनामले चिनिन्छ र उनी १५ भाषाका ज्ञाता थिए।\n- यक्ष मल्ललाई ''नेपाल मण्डलेश्वर'' उपनाम दिइएको थियो।\n- जयस्थिती मल्ललाई एक समाज सुधारक राजाको रूपमा चिनिन्छ।', 'nepali'),
      (v_set_id, 26, E'भगवान गौतम बुद्धले कति वर्षको उमेरमा विवाह गरेको थिए?', E'२९ वर्ष', E'१६ वर्ष', E'३५ वर्ष', E'७ वर्ष', 'B', E'भगवान गौतम बुद्धले **१६ वर्षको** उमेरमा यशोधरासँग विवाह गरेका थिए। उनले २९ वर्षको उमेरमा गृहत्याग गरेका थिए भने ३५ वर्षको उमेरमा बोधगयामा ज्ञान प्राप्त गरेका थिए।', 'nepali'),
      (v_set_id, 27, E'कम्प्युटर फाइल सम्बन्धित PDF को पुरा रुप के हो?', E'Portable Document Format', E'Public Data File', E'Print Document Framework', E'Programmed Data Format', 'A', E'कम्प्युटर फाइलसँग सम्बन्धित PDF को पूरा रूप **Portable Document Format** हो।\nनोट: यो फाइल ढाँचा सन् १९९० को दशकमा एडोब (Adobe) कम्पनीले विकास गरेको हो।', 'nepali'),
      (v_set_id, 28, E'हाल नेपालमा संरक्षित पक्षीको संख्या कति रहेका छन्?', E'८ वटा', E'९ वटा', E'१० वटा', E'११ वटा', 'B', E'हाल नेपालमा संरक्षित पक्षीको संख्या **९ वटा** रहेको छ।\n- ती संरक्षित पक्षीहरू हुन्: कालो गरुड, सेतो गरुड, सारस, चीर कालिज, डाँफे, मोनाल, खर मुजुर, सानो खर मुजुर, र राज धनेश।', 'nepali'),
      (v_set_id, 29, E'नेपालको वर्तमान संविधानअनुसार नेपालको अन्तर्राष्ट्रिय सम्बन्ध सम्बन्धी व्यवस्था कति धारामा गरिएको छ?', E'५१ (च)', E'५१ (ट)', E'५१ (ङ)', E'५१ (ख)', 'C', E'नेपालको वर्तमान संविधानको **धारा ५१ (ङ)** मा नेपालको अन्तर्राष्ट्रिय सम्बन्ध सम्बन्धी व्यवस्था गरिएको छ।\nनोट: यो व्यवस्था संविधानको भाग-४ अन्तर्गत ''राज्यका निर्देशक सिद्धान्त, नीति तथा दायित्व'' भित्र पर्दछ, जसलाई परराष्ट्र नीति पनि भनिन्छ।', 'nepali'),
      (v_set_id, 30, E'युरोप महादेशको कुन नदीलाई युरोपेली व्यापारको जीवन रेखा समेत भनिन्छ?', E'भोल्गा', E'राइन', E'डेन्युब', E'नीपर', 'B', E'राइन नदी युरोपको सबैभन्दा व्यस्त आन्तरिक जल यातायात मार्ग भएकाले यसलाई युरोपेली व्यापारको **जीवन रेखा** भनिन्छ।\n- भोल्गा युरोपको सबैभन्दा लामो नदी हो।\n- डेन्युब नदीलाई ''अन्तर्राष्ट्रिय नदी'' भनेर चिनिन्छ।\nनोट: युरोपको सबैभन्दा व्यस्त रोटरडम बन्दरगाह यही राइन नदीमा अवस्थित छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२२', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_23.csv  →  आसमान दैनिक GK — २०८२/०९/२३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'एसिया महादेशमा अवस्थित दोहोरो भूपरिवेष्ठित मुलुक देहाएका मध्ये कुन होला पहिचान गर्नुहोस्?', E'आर्मेनिया', E'उज्वेकिस्तान', E'काजिकिस्तान', E'लिचेस्टाइन', 'B', E'एसिया महादेशमा अवस्थित दोहोरो भूपरिवेष्ठित मुलुक **उज्वेकिस्तान** हो।\n- आर्मेनिया एक भूपरिवेष्ठित राष्ट्र हो, तर दोहोरो भूपरिवेष्ठित होइन।\n- काजिकिस्तान विश्वको सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र हो, तर दोहोरो भूपरिवेष्ठित होइन।\n- लिचेस्टाइन युरोप महादेशमा अवस्थित दोहोरो भूपरिवेष्ठित मुलुक हो।\nनोट: विश्वमा जम्मा दुईवटा दोहोरो भूपरिवेष्ठित राष्ट्रहरू छन्: एसियाको उज्वेकिस्तान र युरोपको लिचेस्टाइन।', 'nepali'),
      (v_set_id, 2, E'सीमान्त हिमाली क्षेत्र कति मिटर उचाई सम्म फैलिएको छ?', E'५००० मि.', E'६००० मि.', E'७००० मि.', E'८००० मि.', 'C', E'सीमान्त हिमाली क्षेत्र (Tibetan Plateau) ६,००० मिटर देखि **७,००० मिटर** उचाई सम्म फैलिएको छ।\nनोट: नेपालको हिमाली प्रदेशलाई मुख्य हिमाली क्षेत्र (५,००० - ८,८४८.८६ मि.), भित्री हिमाली क्षेत्र (२,४०० - ५,००० मि.) र सीमान्त हिमाली क्षेत्र गरी तीन भागमा विभाजन गरिएको छ।', 'nepali'),
      (v_set_id, 3, E'विश्वको सबैभन्दा अग्लो र फराकिलो पठार कुन मुलुकमा रहेको छ?', E'चीन', E'भारत', E'नेपाल', E'रुस', 'A', E'विश्वको सबैभन्दा अग्लो र फराकिलो पठार, पामिर पठार, **चीनको** तिब्बत स्वायत्त क्षेत्रमा अवस्थित छ।\n- भारतमा दक्षिणको पठार (Deccan Plateau) रहेको छ।\n- नेपाल हिमालयको काखमा अवस्थित भए तापनि पामिर पठार यहाँ पर्दैन।\n- रुसमा मध्य साइबेरियन पठार (Central Siberian Plateau) रहेको छ।\nनोट: पामिर पठारलाई ''संसारको छानो'' पनि भनिन्छ र यो लगभग ५,००० मिटरको उचाइमा अवस्थित छ।', 'nepali'),
      (v_set_id, 4, E'International astronomical union को स्थापना कहिले भएको थियो?', E'सन् १९२१', E'सन् १९१९', E'सन् १९१५', E'सन् १९१७', 'B', E'आकाशीय पिण्डहरूको अध्ययन र अनुसन्धान गर्ने निकाय International Astronomical Union (IAU) को स्थापना **सन् १९१९ जुलाई २८** मा भएको थियो।\nनोट: यसको प्रधान कार्यालय फ्रान्सको पेरिसमा रहेको छ।', 'nepali'),
      (v_set_id, 5, E'नेपालमा व्यवसायिक कफि खेतिको सुरुवात कहिले देखि भएको हो?', E'वि.सं.१९९३', E'वि.सं.२०१५', E'वि.सं.१९९५', E'वि.सं.२०११', 'D', E'नेपालमा व्यावसायिक कफि खेतीको सुरुवात **वि.सं. २०११** देखि भएको हो।\n- नेपालमा कफी खेतीको सुरुवात भने वि.सं. १९९५ मा भएको थियो।\nनोट: हिरा गिरिले म्यानमारबाट नेपालमा कफि भित्र्याएका थिए।', 'nepali'),
      (v_set_id, 6, E'नेपालको संविधान अनुसार नेपालमा कुन पहिचानको आधारमा नागरिकताको व्यवस्था गरिएको छ?', E'संघीय', E'प्रादेशिक', E'जिल्लागत', E'स्थानीय तह', 'B', E'नेपालको संविधानको भाग-२, धारा १० अनुसार नेपालमा **प्रादेशिक पहिचान** सहितको एकल संघीय नागरिकताको व्यवस्था गरिएको छ।\nनोट: संविधान अनुसार कुनै पनि नेपाली नागरिकलाई नागरिकता प्राप्त गर्ने हकबाट वञ्चित गरिने छैन।', 'nepali'),
      (v_set_id, 7, E'जेन जीको आन्दोलन पश्चात गठित मन्त्रीमण्डलमा गृहमन्त्रीमा को नियुक्ति भएका छन्?', E'रामेश्वर प्रसाद खनाल', E'कुलमान घिसिङ', E'ओम प्रकाश अर्याल', E'रमेश लेखक', 'C', E'जेन जीको आन्दोलन पश्चात गठित मन्त्रीमण्डलमा **ओम प्रकाश अर्याल** गृहमन्त्रीमा नियुक्त भएका थिए।\n- रामेश्वर प्रसाद खनाल सोही मन्त्रीमण्डलमा अर्थ, संघीय मामिला तथा सामान्य प्रशासन मन्त्री थिए।\n- कुलमान घिसिङ ऊर्जा, जलश्रोत तथा सिंचाइ, भौतिक पूर्वाधार तथा यातायात, र सहरी विकास मन्त्री थिए।', 'nepali'),
      (v_set_id, 8, E'पुरुष तर्फ बालोन डी ओर अवार्ड-२०२४ जित्ने फुटबल खेलाडी को हुन्?', E'आइटाना बोनमाटी', E'ओस्मान डेम्बेले', E'रोद्री', E'लियोनल मेस्सी', 'B', E'**ओस्मान डेम्बेले** ले पुरुष तर्फको बालोन डी ओर अवार्ड-२०२४ जितेका हुन्।\n- आइटाना बोनमाटीले महिला तर्फको बालोन डी ओर अवार्ड-२०२३ जितेकी थिइन्।\n- रोद्री (Rodri) म्यानचेस्टर सिटीका खेलाडी हुन्।\n- लियोनल मेस्सीले यसअघि सन् २०२३ मा यो अवार्ड जितेका थिए।', 'nepali'),
      (v_set_id, 9, E'आ.व. २०८१/८२ बजेटमा राजस्वबाट कति प्रतिशत स्रोत व्यवस्थापन गरिएको छ?', E'६७.७४ प्रतिशत', E'६६.७४ प्रतिशत', E'६६.९५ प्रतिशत', E'६५.७४ प्रतिशत', 'C', E'आर्थिक वर्ष २०८१/८२ को बजेटमा राजस्वबाट **६६.९५ प्रतिशत** (रु. १३ खर्ब १५ अर्ब) स्रोत व्यवस्थापन गरिएको छ।\nनोट: बजेटका अन्य स्रोतहरूमा वैदेशिक अनुदान २.७२%, वैदेशिक ऋण ११.८९% र आन्तरिक ऋण १८.४३% रहेका छन्।', 'nepali'),
      (v_set_id, 10, E'विश्वकै प्रथम कानूनको संहिताकरण (Coding) केलाई मान्ने गरिन्छ?', E'नेपोलियन कोड', E'रुसो कोड', E'मन्टेस्क्यु कोड', E'भोल्तेयर कोड', 'A', E'विश्वको प्रथम कानूनको संहिताकरण **नेपोलियन कोड** लाई मानिन्छ। यो कोड नेपोलियन बोनापार्टले फ्रान्समा लागू गरेका थिए।\nनोट: "मेरो गौरव नै सिभिल कोड हो" भन्ने भनाइ नेपोलियन बोनापार्टको हो र यस कोडमा ३६० भन्दा बढी कानून संग्रहित थिए।', 'nepali'),
      (v_set_id, 11, E'कसको पालादेखि नेपालमा द्वैध शासन (दुई जनाको संयुक्त शासन) व्यवस्थाको सुरुवात भएको थियो?', E'वसन्तदेव', E'अंशुवर्मा', E'नरेन्द्रदेव', E'मानदेव', 'A', E'**वसन्तदेवको** पालादेखि नेपालमा द्वैध शासन व्यवस्थाको सुरुवात भएको थियो।\n- अंशुवर्माले द्वैध शासनको अन्त्य गरी एकल शासन चलाएका थिए।\n- नरेन्द्रदेवलाई ''आकाशको पूर्ण चन्द्र'' उपनामले चिनिन्छ र उनले भद्राधिवास भवन बनाएका थिए।\n- मानदेवलाई नेपालको प्रथम प्रमाणिक राजा मानिन्छ र उनले मानगृह दरबार बनाएका थिए।\nनोट: शिलालेखमा ''स्वस्ति नेपालभ्यः'' (नेपालको कल्याण होस्) लेख्ने राजा वसन्तदेव हुन्।', 'nepali'),
      (v_set_id, 12, E'बुद्ध धर्ममा निलो रंगले तलका मध्ये केलाई अंकित गर्दछ?', E'बुद्धको शरिर', E'बुद्धको अस्थिधातु', E'बुद्धको अन्तःस्करण', E'बुद्धको दाँत', 'A', E'**बुद्ध धर्ममा निलो रंगले बुद्धको शरीरलाई अंकित गर्दछ।**\n- बुद्धको अस्थिधातुलाई पहेलो रंगले अंकित गर्दछ।\n- बुद्धको अन्तःस्करणलाई कलेजी रंगले अंकित गर्दछ।\n- बुद्धको दाँतलाई सेतो रंगले अंकित गर्दछ।\nनोट: बुद्ध धर्ममा रातो रंगले बुद्धको रगतलाई अंकित गर्दछ।', 'nepali'),
      (v_set_id, 13, E'अल्वर्ट आइन्स्टाइनको मस्तिष्क कहाँ सुरक्षित राखिएको छ?', E'अमेरिका', E'जर्मनी', E'इजरायल', E'बेलायत', 'A', E'**अल्वर्ट आइन्स्टाइनको मस्तिष्क अमेरिकाको प्रिन्सटन अस्पतालमा सुरक्षित राखिएको छ।**', 'nepali'),
      (v_set_id, 14, E'घ्वाँसे चितुवाको लागि प्रख्यात राष्ट्रिय निकुञ्ज कुन हो?', E'शे-फोक्सुण्डो रा.नि.', E'शिवपुरी नागार्जुन रा.नि.', E'पर्सा रा.नि.', E'सगरमाथा रा.नि.', 'B', E'**घ्वाँसे चितुवाको लागि शिवपुरी नागार्जुन राष्ट्रिय निकुञ्ज प्रख्यात छ।**\n- शे-फोक्सुण्डो राष्ट्रिय निकुञ्ज तिब्बती खरायोको लागि प्रख्यात छ।\n- पर्सा राष्ट्रिय निकुञ्ज गौरी गाईको लागि प्रख्यात छ।\n- सगरमाथा राष्ट्रिय निकुञ्ज हिमचितुवाको लागि प्रख्यात छ।', 'nepali'),
      (v_set_id, 15, E'हालसम्ममा आयोजना भएका सार्क शिखर सम्मेलनहरूमा सबैभन्दा धेरै पटक नेपालबाट प्रतिनिधित्व गर्ने व्यक्ति को हुन्?', E'राजा वीरेन्द्र', E'शेरबहादुर देउवा', E'गिरिजा प्र. कोइराला', E'राजा ज्ञानेन्द्र', 'C', E'**सार्क शिखर सम्मेलनहरूमा नेपालबाट सबैभन्दा धेरै पटक प्रतिनिधित्व गर्ने व्यक्ति गिरिजाप्रसाद कोइराला हुन्।** उहाँले ५ पटक (छैटौं, सातौं, नवौं, एघारौं र चौधौं सम्मेलनमा) नेपालको प्रतिनिधित्व गर्नुभएको थियो।\nनोट: राजा वीरेन्द्रले ४ पटक (पहिलो देखि चौथो सम्मेलनसम्म) प्रतिनिधित्व गर्नुभएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_24.csv  →  आसमान दैनिक GK — २०८२/०९/२४  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'गोल्डेन ग्लोब्स अवार्ड, २०२५ मा उत्कृष्ट चलचित्र बन्न सफल चलचित्र कुन हो ?', E'The Brutalist', E'Dune: Part Two', E'Conclave', E'September 5', 'A', E'८३ औं गोल्डेन ग्लोब्स अवार्ड, २०२५ मा **''The Brutalist''** उत्कृष्ट चलचित्र बन्न सफल भयो।\nनोट: गोल्डेन ग्लोब्स अवार्ड उत्कृष्ट फिल्म तथा अमेरिकी टेलिभिजनलाई वार्षिक रुपमा प्रदान गरिन्छ।', 'nepali'),
      (v_set_id, 2, E'प्रतिनिधि सभा निर्वाचन, २०८२ कुल कति मतदान केन्द्रमा निर्वाचन हुँदैछ ?', E'२१ हजार १ सय १२', E'२२ हजार १ सय १२', E'२३ हजार १ सय १२', E'२४ हजार १ सय १२', 'C', E'प्रतिनिधि सभा निर्वाचन, २०८२ का लागि कुल **२३,११२** मतदान केन्द्रमा निर्वाचन हुँदैछ।\nनोट: यस निर्वाचनका लागि कुल मतदान स्थल १०,९६७ र कुल मतदाता संख्या एक करोड ८९ लाख तीन हजार ६८९ रहेको छ।', 'nepali'),
      (v_set_id, 3, E'सन् २०२५ सम्ममा नेपालमा कति प्रजातिको चराहरु फेला परेका छन् ?', E'९०४ वटा', E'९०३ वटा', E'९०२ वटा', E'९०१ वटा', 'B', E'सन् २०२५ सम्ममा नेपालमा **९०३ प्रजातिका** चराहरु फेला परेका छन्।', 'nepali'),
      (v_set_id, 4, E'दोस्रो राष्ट्रिय आर्थिक गणना, २०८२ को सुरुवात कहिले देखि हुने भनि तय गरिएको छ ?', E'२०८२ फागुन १', E'२०८२ चैत १', E'२०८३ बैशाख १', E'२०८३ जेठ १', 'B', E'दोस्रो राष्ट्रिय आर्थिक गणना, २०८२ को सुरुवात **२०८२ चैत १** देखि हुने तय भएको छ।\nयस गणनाको नारा ''नेपाली अर्थतन्त्र मापनको लागि आर्थिक गणना'' रहेको छ र यसअघि पहिलो राष्ट्रिय आर्थिक गणना २०७५ सालमा गरिएको थियो।', 'nepali'),
      (v_set_id, 5, E'सन् २०२५ मा जम्मा कति पटक भिटो प्रयोग भएको छ?', E'५ पटक', E'४ पटक', E'३ पटक', E'२ पटक', 'D', E'सन् २०२५ मा संयुक्त राष्ट्रसंघको सुरक्षा परिषद्मा जम्मा **२ पटक** भिटो प्रयोग भएको थियो।\nनोट: दुवै पटक (18 September 2025 र 04 June 2025) अमेरिकाले भिटो प्रयोग गरेको थियो।', 'nepali'),
      (v_set_id, 6, E'२०८२ मा कति औं राष्ट्रिय पोशाक तथा टोपी दिवस मनाइएको छ ?', E'११ औं', E'१२ औं', E'१३ औं', E'१४ औं', 'C', E'वि.सं. २०८२ मा **१३ औं** राष्ट्रिय पोशाक तथा टोपी दिवस मनाइएको थियो।\nनोट: यो दिवस प्रत्येक वर्ष जनवरी १ मा मनाइन्छ र वि.सं. २०७० देखि मनाउन सुरु गरिएको थियो।', 'nepali'),
      (v_set_id, 7, E'हालसालै मदन पुरस्कार विजेता निलम कार्की निहारिका द्वारा स्थापना गरिएको पुरस्कारको नाम के हो ?', E'मीना दिदी पुरस्कार', E'कार्की आमा पुरस्कार', E'नारी चेली पुरस्कार', E'उद् नारी पुरस्कार', 'A', E'मदन पुरस्कार विजेता निलम कार्की निहारिकाद्वारा स्थापना गरिएको पुरस्कारको नाम **मीना दिदी पुरस्कार** हो।\nनोट: यो पुरस्कार उत्कृष्ट महिला शिक्षकलाई प्रदान गर्नका लागि वि.सं. २०८२ पुस १४ गते स्थापना गरिएको हो।', 'nepali'),
      (v_set_id, 8, E'हाल सालै २०२६ मा कुन मुलुकका राष्ट्रप्रमुखलाई अमेरिकी सेना द्वारा पक्राउ गरी अमेरिकाको कब्जामा राखिएको हो ?', E'इरान', E'भेनेजुएला', E'युक्रेन', E'बोलिभिया', 'B', E'अमेरिकी सेनाले **भेनेजुएलाका** राष्ट्रपति निकोलस मादुरो र उनकी पत्नीलाई सन् २०२६ जनवरी ३ मा पक्राउ गरी आफ्नो कब्जामा लिएको थियो। उनीहरूमाथि लागुऔषध ओसारपसार र अमेरिकामा अपराध फैलाएको आरोप लगाइएको थियो।\nनोट: यो पक्राउलाई ''अप्रेसन एब्सोलुट रिजल्भ'' नाम दिइएको थियो।', 'nepali'),
      (v_set_id, 9, E'ग्रान्डस्लाम (अस्ट्रेलियन ओपन) टेनिसका लागि छनोट हुने पहिलो नेपाली खेलाडी को हुन् ?', E'परदेशी श्रेष्ठ', E'विनिता शर्मा', E'शिभाली गुरुङ', E'प्रनिता क्षेत्री', 'C', E'नेपाली टेनिस खेलाडी **शिभाली गुरुङ** ग्रान्डस्लाम (अस्ट्रेलियन ओपन) टेनिसका लागि छनोट हुने पहिलो नेपाली खेलाडी हुन्। उनले सन् २०२६ मा अस्ट्रेलियाको मेलवर्नमा भएको अस्ट्रेलियन ओपनको यु-१४ गर्ल्स क्याटेगोरीमा प्रतिस्पर्धा गरेकी थिइन्।', 'nepali'),
      (v_set_id, 10, E'आईसीसी पुरुष टि-२० विश्वकप २०२६ को ट्रफी टुरको लागि नेपालमा कहिले आएको हो ?', E'२०२६ जनवरी २', E'२०२६ जनवरी ३', E'२०२६ जनवरी ४', E'२०२६ जनवरी ५', 'C', E'आईसीसी पुरुष टि-२० विश्वकप २०२६ को ट्रफी टुरका लागि **२०२६ जनवरी ४** (वि.सं. २०८२ पौष २१) मा नेपाल ल्याइएको थियो। भारत र श्रीलंकामा संयुक्त रूपमा आयोजना हुने विश्वकपको ट्रफी पहिलोपटक नेपाल ल्याइएको हो।\nनोट: उक्त ट्रफी राष्ट्रपति भवन शीतल निवासमा प्रदर्शन गरिएको थियो।', 'nepali'),
      (v_set_id, 11, E'नेपाल पर्यटन बोर्ड अनुसार सन् २०२४ मा कति पर्यटक नेपालमा आएका छन् ?', E'११ लाख ५८ हजार ४५९', E'१२ लाख ५८ हजार ४५९', E'१३ लाख ५८ हजार ४५९', E'१४ लाख ५८ हजार ४५९', 'C', E'नेपाल पर्यटन बोर्डका अनुसार सन् २०२४ मा **१३ लाख ५८ हजार ४५९** पर्यटक नेपालमा आएका छन्।\nनोट: सन् २०२४ मा नेपालमा सबैभन्दा धेरै पर्यटक आउने मुलुक भारत हो, जहाँबाट २ लाख ९२ हजार ४३६ जना (कुलको २५.२%) पर्यटक आएका थिए।', 'nepali'),
      (v_set_id, 12, E'जापानका वैज्ञानिकले हालसालै कुन जीवमा क्यान्सरको औषधि रहेको तथ्य सार्वजनिक गरेका छन् ?', E'मुसा', E'भ्यागुता', E'सर्प', E'फ्याङ्ग्रा', 'B', E'जापानका वैज्ञानिकले हालसालै **भ्यागुता**मा क्यान्सरको औषधि रहेको तथ्य सार्वजनिक गरेका छन्। उनीहरूले जापानी ट्री फ्रग (वैज्ञानिक नाम: ड्रायोफाइट्स जापोनिकस) को आन्द्रामा पाइने विशेष ब्याक्टेरियाले क्यान्सरका ट्युमर नष्ट गर्ने पत्ता लगाएका हुन्।', 'nepali'),
      (v_set_id, 13, E'जलपन्छी गणना २०८२ को सुरुवात कुन जिल्लाबाट भएको छ ?', E'कैलाली', E'कञ्चनपुर', E'बाँके', E'बर्दिया', 'B', E'जलपन्छी गणना २०८२ को सुरुवात **कञ्चनपुर** जिल्लाबाट भएको छ। यो गणना हरेक वर्ष जनवरीको पहिलो शनिबारदेखि सिमसार क्षेत्रमा आश्रित रैथाने तथा आगन्तुक जलपन्छीहरूको अवस्था र संख्या अभिलेख गर्न गरिन्छ।', 'nepali'),
      (v_set_id, 14, E'नेपालको सबै भन्सार कार्यालयमा अनलाइन मुल्यांकन डाटाबेस प्रणाली लागु कहिले देखि भएको छ ?', E'२०८२ पौष १७', E'२०८२ पौष १८', E'२०८२ पौष १९', E'२०८२ पौष २०', 'B', E'नेपालका सबै भन्सार कार्यालयहरूमा अनलाइन मूल्यांकन डाटाबेस प्रणाली **वि.सं. २०८२ पौष १८** देखि लागू भएको हो।', 'nepali'),
      (v_set_id, 15, E'नेपालमा पर्यटकको अनलाइन ट्याकिङ सुरु कहिले देखि सुरु भएको छ ?', E'२०२६ जनवरी २', E'२०२६ जनवरी ३', E'२०२६ जनवरी ४', E'२०२६ जनवरी १', 'D', E'नेपालमा विदेशी नागरिकको अनलाइन ट्याकिङ गर्ने प्रणाली, जसलाई विदेशी नागरिक व्यवस्थापन सूचना प्रणाली (FNMIS) भनिन्छ, **सन् २०२६ जनवरी १** देखि कार्यान्वयनमा आएको हो।\nनोट: यो प्रणाली विदेशी नागरिकका गतिविधि नियमन, निगरानी, व्यवस्थापन र सहजीकरणका लागि ल्याइएको हो र यसको उद्घाटन गृहमन्त्री ओमप्रकाश अर्यालले गरेका थिए।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२४', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_27.csv  →  आसमान दैनिक GK — २०८२/०९/२७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालकै पहिलो कफी अनुसन्धान केन्द्र गुल्मी जिल्लाको कुन ठाँउमा रहेको छ?', E'आँपचौर', E'शान्तिपुर', E'रेसुङ्गा', E'बले टक्सार', 'D', E'नेपालको पहिलो कफी अनुसन्धान केन्द्र गुल्मी जिल्लाको **बले टक्सारमा** रहेको छ।\n- गुल्मीको आँपचौरबाट नेपालमा कफी खेतीको सुरुवात भएको थियो।\n- शान्तिपुर गुल्मी जिल्लामा अवस्थित एक गाउँपालिका हो।\n- रेसुङ्गा गुल्मी जिल्लाको एक प्रसिद्ध धार्मिक तथा पर्यटकीय स्थल एवं नगरपालिका हो।\nनोट: यो अनुसन्धान केन्द्र वि.सं. २०४१ मा स्थापना भएको थियो।', 'nepali'),
      (v_set_id, 2, E'बीउ बिजन र कृषि प्रजातिको छनौट र संरक्षण सम्बन्धि व्यवस्था कुन धारामा रहेको छ?', E'धारा ४०', E'धारा ४१', E'धारा ४२', E'धारा ४३', 'C', E'नेपालको संविधानको **धारा ४२** मा सामाजिक न्यायको हक अन्तर्गत प्रत्येक किसानलाई कानून बमोजिम कृषि कार्यका लागि भूमिमा पहुँच, परम्परागत रुपमा प्रयोग र अवलम्बन गरिएको स्थानीय बीउ बिजन र कृषि प्रजातिको छनौट र संरक्षणको हक हुने व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 3, E'सौर्यमण्डलका ८ वटा ग्रहहरू मध्ये कति वटा ग्रहहरूमा रिङ प्रणाली रहेको छ?', E'४ वटा', E'१ वटा', E'२ वटा', E'३ वटा', 'A', E'हाम्रो सौर्यमण्डलका **४ वटा** ग्रहहरूमा रिङ प्रणाली रहेको छ। सौर्यमण्डलका चारवटा ठुला बाहिरी ग्रहहरू (बृहस्पति, शनि, अरुण र वरुण) मा रिङ प्रणाली रहेको छ।\nनोट: शनि ग्रहको रिङ प्रणाली सबैभन्दा उत्तम र स्पष्ट देखिन्छ।', 'nepali'),
      (v_set_id, 4, E'डेनाली उपनामले कुन विश्व प्रसिद्ध शिखरलाई चिनिन्छ?', E'एल्ब्रुज', E'एलबर्ट', E'मेकिन्ले', E'किलिमन्जारो', 'C', E'डेनाली उपनामले उत्तर अमेरिका महादेशको सबैभन्दा अग्लो शिखर **मेकिन्ले** लाई चिनिन्छ।\n- एल्ब्रुज युरोप महादेशको सबैभन्दा अग्लो शिखर हो, जुन रुसमा पर्दछ।\n- एलबर्ट उत्तर अमेरिकाको रकी पर्वत श्रृंखलाको सबैभन्दा अग्लो शिखर हो।\n- किलिमन्जारो अफ्रिका महादेशको सबैभन्दा अग्लो शिखर हो, जुन तान्जानियामा अवस्थित छ।', 'nepali'),
      (v_set_id, 5, E'नेपाल कहिले अतिकम विकसित मुलुकबाट स्तरोन्नती हुँदैछ ?', E'सन् २०२६ मा', E'सन् २०२७ मा', E'सन् २०२८ मा', E'सन् २०२९ मा', 'A', E'नेपाल **सन् २०२६** मा अतिकम विकसित मुलुकको श्रेणीबाट विकासशील मुलुकमा स्तरोन्नती हुनेछ।\nनोट: नेपाललाई स्तरोन्नती गर्ने निर्णय सन् २०२१ नोभेम्बर २१ मा भएको थियो र यो २०२६ नोभेम्बर २४ देखि लागू हुनेछ।', 'nepali'),
      (v_set_id, 6, E'जयपृथ्वी बहादुर सिंह १६ औं राष्ट्रिय विभूतिका रुपमा कहिले घोषणा गरिएको हो ?', E'२०७९ असार ६', E'२०७९ असार १४', E'२०७९ असार २१', E'२०७९ असार २६', 'A', E'नेपाल सरकार मन्त्रिपरिषद्को निर्णय अनुसार जयपृथ्वी बहादुर सिंहलाई **२०७९ असार ६** गते राष्ट्रिय विभूति घोषणा गरिएको हो।\nनोट: जयपृथ्वी बहादुर सिंह नेपालका १८ औं राष्ट्रिय विभूति हुन्।', 'nepali'),
      (v_set_id, 7, E'विद्युतीकरण तथ्यांक २०७९ अनुसार मुलुकका कति स्थानीय तह पूर्ण विद्युतीकरण भएका छन्?', E'५३६ वटा', E'५३७ वटा', E'५३८ वटा', E'५३९ वटा', 'D', E'विद्युतीकरण तथ्यांक २०७९ अनुसार मुलुकका जम्मा **५३९ वटा** स्थानीय तह पूर्ण विद्युतीकरण भएका छन्।\nनोट: सोही तथ्यांक अनुसार, १९६ स्थानीय तहमा आंशिक विद्युतीकरण भएको छ भने १८ वटामा राष्ट्रिय प्रसारण लाइन पुग्न बाँकी छ।', 'nepali'),
      (v_set_id, 8, E'नेपालको इतिहास राजनैतिक विभाजनको अवधारणा कुन कालबाट आएको थियो?', E'किरात काल', E'लिच्छवी काल', E'मल्ल काल', E'राणा काल', 'B', E'**नेपालको इतिहासमा राजनैतिक विभाजनको अवधारणा लिच्छवी कालबाट आएको थियो।**\n- किरात कालमा प्रशासनिक विभाजनको स्पष्ट आधार पाइँदैन, यद्यपि ''थुम'' जस्ता प्रशासनिक एकाइहरू रहेको मानिन्छ।\n- मल्ल कालमा राज्यलाई विभिन्न विषय (जिल्ला) र गाउँमा विभाजन गरी शासन चलाइन्थ्यो।\n- राणा कालमा देशलाई ३५ जिल्लामा विभाजन गरी प्रशासनिक संरचना बनाइएको थियो।\nनोट: लिच्छवी राजा शिवदेव प्रथमले राज्यलाई द्रोंग (शहर), तल (विकसित गाउँ) र ग्राम (गाउँ) गरी तीन तहमा विभाजन गरेका थिए।', 'nepali'),
      (v_set_id, 9, E'चीन-भारतबीचको सिमारखालाई के लाइन भनिन्छ?', E'रेडक्लिफ', E'मेक मोहन', E'डुरण्ड', E'मेजिनट', 'B', E'**चीन र भारतबीचको सिमारखालाई मेक मोहन लाइन भनिन्छ।**\n- रेडक्लिफ लाइन भारत र पाकिस्तानबीचको सिमारखा हो।\n- डुरण्ड लाइन पाकिस्तान र अफगानिस्तानबीचको सिमारखा हो।\n- मेजिनट लाइन फ्रान्सले स्वीट्जरल्याण्डदेखि बेल्जियमसम्म बनाएको प्रतिरक्षात्मक रेखा हो।', 'nepali'),
      (v_set_id, 10, E'फ्रान्सको राज्यक्रान्ति पछि शासन सत्ता कसले सम्हालेका थिए?', E'रुसो', E'नेपोलियन बोनापार्ट', E'भोल्तेयर', E'लुई सोह्रौं', 'B', E'**फ्रान्सको राज्यक्रान्ति पछि नेपोलियन बोनापार्टले शासन सत्ता सम्हालेका थिए।**\n- रुसो एक प्रख्यात दार्शनिक थिए जसका विचारहरूले राज्यक्रान्तिलाई प्रेरित गर्यो।\n- भोल्तेयर पनि फ्रान्सेली राज्यक्रान्तिका एक प्रमुख प्रबुद्ध दार्शनिक थिए।\n- लुई सोह्रौं फ्रान्सेली राज्यक्रान्तिका समयमा फ्रान्सका राजा थिए, जसलाई पछि मृत्युदण्ड दिइयो।\nनोट: नेपोलियन बोनापार्ट सन् १८०४ मा फ्रान्सको सम्राट बनेका थिए।', 'nepali'),
      (v_set_id, 11, E'तिब्बतमा शरण लिन जाने लिच्छवि राजा को हुन्?', E'गुणकामदेव', E'नरेन्द्रदेव', E'उदयदेव', E'शिवदेव प्रथम', 'C', E'**लिच्छवि राजा उदयदेव तिब्बतमा शरण लिन गएका थिए।**\n- गुणकामदेवले कान्तिपुरमा मानव बस्ती बसालेका थिए र उनलाई आधुनिक काठमाडौंको निर्माता मानिन्छ।\n- नरेन्द्रदेवले भद्रालमा बुट्टा राख्ने चलन चलाएका थिए।\n- शिवदेव प्रथमले कीर्तिपुरमा बस्ती बसालेका थिए।\nनोट: उदयदेव राजा नरेन्द्रदेवका बुवा थिए।', 'nepali'),
      (v_set_id, 12, E'लिम्बु भाषाको प्रथम टेलिचलचित्र कुन हो?', E'नुमाफुङ', E'तखेवा', E'थात्थामा', E'फास्मुक', 'B', E'**लिम्बु भाषाको प्रथम टेलिचलचित्र ''तखेवा'' हो।**\n- ''नुमाफुङ'' लिम्बु भाषाको प्रथम चलचित्र हो।\n- ''थात्थामा'' लिम्बु भाषाको पहिलो उपन्यास हो।\n- ''फास्मुक'' लिम्बु जातिमा प्रचलित तीन टुक्रा बाँस मिलाई बनाइने एक प्रकारको बाजा हो।', 'nepali'),
      (v_set_id, 13, E'UNEP को प्रधान कार्यालय कुन मुलुकमा रहेको छ?', E'केन्या', E'स्वीडेन', E'नर्वे', E'बेलायत', 'A', E'संयुक्त राष्ट्र संघीय वातावरण कार्यक्रम (UNEP) को प्रधान कार्यालय **केन्याको नैरोबीमा** रहेको छ।\nनोट: UNEP को स्थापना सन् १९७२ जुन ५ मा भएको थियो।', 'nepali'),
      (v_set_id, 14, E'प्रमुख धर्म बौद्ध रहेका सार्क मुलुक कतिवटा रहेका छन्?', E'१ मात्र', E'२ वटा', E'३ वटा', E'४ वटा', 'B', E'सार्क मुलुकहरूमध्ये प्रमुख धर्म बौद्ध भएका **२ वटा** देशहरू छन्, जुन श्रीलंका र भुटान हुन्।\nनोट: नेपाल र भारतको प्रमुख धर्म हिन्दु हो।', 'nepali'),
      (v_set_id, 15, E'कुनै पनि जीवले आफ्नै जीवनकालका आफ्नै संघर्षबाट प्राप्त गरेको गुणलाई के भनिन्छ?', E'आर्जित गुण', E'वंशानुगत गुण', E'परिवृति गुण', E'उत्परिवर्तन गुण', 'A', E'कुनै पनि जीवले आफ्नै जीवनकालमा संघर्षबाट प्राप्त गरेको गुणलाई **आर्जित गुण** भनिन्छ।\n- वंशानुगत गुण भनेको मातापिताबाट छोराछोरीमा सर्न सक्ने लक्षण हो।\n- परिवृति (Variation) भन्नाले व्यक्ति वा सन्ततिपिच्छे देखा पर्ने फरकपनलाई बुझाउँछ।\n- उत्परिवर्तन (Mutation) भनेको पुर्खामा नभएको गुण नयाँ पुस्तामा अकस्मात देखा पर्नु हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_09_28.csv  →  आसमान दैनिक GK — २०८२/०९/२८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/०९/२८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/०९/२८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/०९/२८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'अफ्रिका महादेशको सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र कुन हो?', E'बेलारुस', E'बोलिभिया', E'चाड', E'काजकिस्तान', 'C', E'अफ्रिका महादेशको सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र **चाड** हो।\n- बेलारुस युरोप महादेशको सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र हो।\n- बोलिभिया दक्षिण अमेरिका महादेशको सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र हो।\n- काजकिस्तान एसिया महादेशको र विश्वकै सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र हो।\nनोट: अफ्रिकामा १६ वटा भूपरिवेष्ठित मुलुकहरू छन्, जसमध्ये सबैभन्दा सानो स्वाजील्याण्ड (इस्वातिनि) हो।', 'nepali'),
      (v_set_id, 2, E'धेरै वडा भएको उपमहानगरपालिका कुन हो?', E'कलैया', E'घोराही', E'धनगढी', E'बुटवल', 'A', E'नेपालमा सबैभन्दा धेरै वडा भएको उपमहानगरपालिका कलैया हो, जसमा **२७ वटा** वडाहरू रहेका छन्।\nनोट: हेटौंडा, बुटवल, तुल्सिपुर, घोराही र धनगढी उपमहानगरपालिकाहरूमा सबैभन्दा कम, १९/१९ वटा वडाहरू छन्।', 'nepali'),
      (v_set_id, 3, E'दियायु टापु कुन कुन मुलुक बिचको विवादित टापु हो?', E'भारत र नेपाल', E'भारत र चीन', E'जापान र चीन', E'चीन र पाकिस्तान', 'C', E'दियायु टापु **जापान र चीन** बिचको विवादित टापु हो।\n- भारत र नेपाल बिच कालापानी, लिपुलेक र लिम्पियाधुरा क्षेत्रमा सीमा विवाद रहेको छ।\n- भारत र चीन बिच अक्साई चिन र अरुणाचल प्रदेश लगायतका क्षेत्रमा सीमा विवाद छ।\n- चीन र पाकिस्तान बिचको सीमा विवाद सन् १९६३ को चीन-पाकिस्तान सम्झौता मार्फत समाधान गरिएको थियो, तर यसमा भारतको पनि दाबी रहेको कश्मीर क्षेत्र समावेश छ।\nनोट: दियायु टापुलाई जापानमा ''सेन्काकु'' र चीनमा ''दियाओयु'' भनिन्छ।', 'nepali'),
      (v_set_id, 4, E'हिन्दु धर्ममा प्रचलित नवग्रहमा देहाएको कुन पर्दैन?', E'मंगल', E'शुक्र', E'सूर्य', E'अरुण', 'D', E'हिन्दु धर्ममा प्रचलित नवग्रहमा **अरुण** पर्दैन।\nनोट: हिन्दु ज्योतिषशास्त्र अनुसार नवग्रहहरूमा सूर्य, चन्द्र, मंगल, बुध, बृहस्पति, शुक्र, शनि, राहु र केतु पर्दछन्।', 'nepali'),
      (v_set_id, 5, E'कफिको घर (Home of coffee) को उपनामले कुन देशलाई चिनिन्छ?', E'म्यानमार', E'ब्राजिल', E'फिनल्यान्ड', E'इथियोपिया', 'D', E'''कफिको घर'' (Home of Coffee) को उपनामले **इथियोपिया**लाई चिनिन्छ।\n- म्यानमारबाट नेपालमा कफि भित्रिएको मानिन्छ।\n- ब्राजिल विश्वमा सबैभन्दा धेरै कफि उत्पादन गर्ने देश हो।\n- फिनल्यान्ड विश्वमा सबैभन्दा धेरै कफि खपत गर्ने देश हो।\nनोट: विश्वको सबैभन्दा महँगो कफि उत्पादन गर्ने मुलुक इन्डोनेसिया हो।', 'nepali'),
      (v_set_id, 6, E'नेपालको संविधान प्रमाणित कसले गरेका हुन्?', E'सुवास नेम्वाङ', E'सुशील कोइराला', E'रामवरण यादव', E'कृष्णप्रसाद सिटौला', 'A', E'नेपालको संविधान, २०७२ लाई तत्कालीन संविधान सभाका अध्यक्ष **सुवास नेम्वाङले** प्रमाणित गरेका थिए।\n- सुशील कोइराला संविधान जारी हुँदाका प्रधानमन्त्री थिए।\n- रामवरण यादव संविधान जारी हुँदाका राष्ट्रपति थिए।\n- कृष्णप्रसाद सिटौला संविधान मस्यौदा समितिका अध्यक्ष थिए।', 'nepali'),
      (v_set_id, 7, E'सोह्रौं योजनाको अन्त्य सम्म नेपालको बेरोजगारी दर कतिमा झार्ने लक्ष्य रहेको छ?', E'१५ प्रतिशत', E'५ प्रतिशत', E'१० प्रतिशत', E'२५ प्रतिशत', 'B', E'सोह्रौं योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्ममा नेपालको बेरोजगारी दरलाई **५ प्रतिशतमा** झार्ने लक्ष्य राखिएको छ।\nनोट: यस योजनाले विद्युतमा पहुँच १००%, इन्टरनेटमा पहुँच ९०% र बैंक तथा वित्तीय संस्थामा पहुँच ८५% पुर्‍याउने लक्ष्य लिएको छ।', 'nepali'),
      (v_set_id, 8, E'फिफा विश्वकप, २०३४ कहाँ आयोजना हुने भएको छ?', E'पोर्चुगल', E'उरुग्वे', E'साउदी अरेबिया', E'क्यानडा', 'C', E'फिफा विश्वकप, २०३४ **साउदी अरेबियामा** आयोजना हुने भएको छ।\n- पोर्चुगल र उरुग्वेले स्पेन, मोरक्को, अर्जेन्टिना र पाराग्वेसँग मिलेर सन् २०३० को विश्वकप सह-आयोजना गर्नेछन्।\n- क्यानडाले अमेरिका र मेक्सिकोसँग मिलेर सन् २०२६ को विश्वकप सह-आयोजना गर्नेछ।', 'nepali'),
      (v_set_id, 9, E'नेपालले हालसालै सार्वजनिक गरेको नयाँ राष्ट्रिय निकुञ्जको नाम के हो?', E'मेरापिक राष्ट्रिय निकुञ्ज', E'महाकुलुङ राष्ट्रिय निकुञ्ज', E'छायाँनाथ राष्ट्रिय निकुञ्ज', E'पर्सा राष्ट्रिय निकुञ्ज', 'C', E'नेपालको हालसालै सार्वजनिक गरिएको नयाँ राष्ट्रिय निकुञ्ज **छायाँनाथ राष्ट्रिय निकुञ्ज** हो। यो मुगु जिल्लामा अवस्थित छ र यसको क्षेत्रफल ८४३ वर्ग कि.मि. रहेको छ।\nनोट: यो निकुञ्ज से-फोक्सुण्डो राष्ट्रिय निकुञ्जबाट टुक्रिएर बनेको हो, जससँगै नेपालमा राष्ट्रिय निकुञ्जको संख्या १३ पुगेको छ।', 'nepali'),
      (v_set_id, 10, E'फ्रान्सको राज्यक्रान्ति करिब कति अवधि भएको थियो?', E'१० वर्ष ६ महिना', E'१२ वर्ष ६ महिना', E'८ वर्ष ६ महिना', E'१४ वर्ष ६ महिना', 'A', E'फ्रान्सको राज्यक्रान्ति करिब **१० वर्ष ६ महिना** (सन् १७८९ मे ५ देखि १७९९ नोभेम्बर ९) सम्म चलेको थियो।\nनोट: यो क्रान्तिले फ्रान्सको निरङ्कुश राजतन्त्रात्मक व्यवस्था अन्त्य गरी गणतन्त्रात्मक शासनको स्थापना गरेको थियो।', 'nepali'),
      (v_set_id, 11, E'सोमवंशले नेपालमा कति वर्ष शासन गरेको थियो?', E'३५५ वर्ष', E'३४५ वर्ष', E'३३५ वर्ष', E'३२५ वर्ष', 'A', E'सोमवंशले नेपालमा **३५५ वर्ष** शासन गरेका थिए।\nनोट: यस वंशका ६ जना राजाहरूले शासन गरेका थिए, जसमा निमिष, मताक्ष, काकवर्मा, पशुप्रेक्षदेव, भाष्करवर्मा र भुमी वर्मा पर्दछन्।', 'nepali'),
      (v_set_id, 12, E'गौतम बुद्धका पहिलो शिक्षक कुन थिए?', E'रामपुत्त', E'अलारकलम', E'कौडिन्य', E'तपसु', 'B', E'**अलारकलम गौतम बुद्धका पहिलो शिक्षक थिए, जसबाट बुद्धले उपनिषद र सांख्य दर्शनको ज्ञान सिकेका थिए।**\n- रामपुत्त बुद्धका दोस्रो शिक्षक थिए, जसबाट उनले योगको शिक्षा लिए।\n- कौडिन्य बुद्धले सारनाथमा उपदेश दिएका पाँच ब्राह्मण शिष्यहरूमध्ये एक थिए।\n- तपसु र मल्ली बुद्धका प्रथम दुई अनुयायी थिए।', 'nepali'),
      (v_set_id, 13, E'सापेक्षतावादको सिद्धान्त (Theory of relativity) कुन वैज्ञानिकको हो?', E'अल्बर्ट आइन्स्टाइन', E'आर्किमिडिज', E'ग्यालिलियो ग्यालिली', E'सर आइज्याक न्यूटन', 'A', E'**सापेक्षतावादको सिद्धान्त (Theory of relativity) अल्बर्ट आइन्स्टाइनले प्रतिपादन गरेका हुन्।**\n- आर्किमिडिजले उत्प्लावन र सापेक्ष घनत्वको सिद्धान्त दिएका थिए।\n- ग्यालिलियो ग्यालिलीलाई ''आधुनिक विज्ञानका पिता'' मानिन्छ।\n- सर आइज्याक न्यूटनले गुरुत्वाकर्षण र गतिको नियमहरू प्रतिपादन गरेका थिए।\nनोट: आइन्स्टाइनको E=mc² समीकरणले द्रव्यमान-ऊर्जा समतुल्यताको अवधारणा प्रस्तुत गर्दछ।', 'nepali'),
      (v_set_id, 14, E'तराई क्षेत्रको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज कुन हो?', E'बर्दिया', E'बाँके', E'चितवन', E'पर्सा', 'A', E'तराई क्षेत्रको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज **बर्दिया** हो।\n- बाँके राष्ट्रिय निकुञ्ज बाघ संरक्षणका लागि स्थापना गरिएको हो।\n- चितवन राष्ट्रिय निकुञ्जमा सबैभन्दा धेरै पर्यटक घुम्न आउँछन्।\n- पर्सा राष्ट्रिय निकुञ्ज गौरी गाईको लागि प्रख्यात छ।', 'nepali'),
      (v_set_id, 15, E'नेपालमा रहेको सार्कको क्षेत्रीय केन्द्र कुन हो?', E'सार्क सांस्कृतिक केन्द्र', E'सार्क क्षयरोग र एड्स केन्द्र', E'सार्क वातावरण केन्द्र', E'सार्क कृषि केन्द्र', 'B', E'नेपालमा रहेको सार्कको क्षेत्रीय केन्द्र **सार्क क्षयरोग र एड्स केन्द्र** हो।\n- सार्क सांस्कृतिक केन्द्र श्रीलंकाको कोलम्बोमा अवस्थित छ।\n- सार्क वातावरण तथा विपद् व्यवस्थापन केन्द्र भारतको गुजरातमा रहेको छ।\n- सार्क कृषि केन्द्र बंगलादेशको ढाकामा अवस्थित छ।\nनोट: सार्क क्षयरोग र एड्स केन्द्र भक्तपुरको ठिमीमा रहेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/०९/२८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_01.csv  →  आसमान दैनिक GK — २०८२/१०/०१  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/०१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/०१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/०१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'सबैभन्दा ठूलो महादेश एसियाले कुल जमिनको कति प्रतिशत भू-भाग ओगटेको छ?', E'२९.९२ प्रतिशत', E'२८.९२ प्रतिशत', E'२७.२९ प्रतिशत', E'२६.२९ प्रतिशत', 'A', E'सबैभन्दा ठूलो महादेश एसियाले कुल जमिनको **२९.९२ प्रतिशत** भू-भाग ओगटेको छ।\nनोट: अन्य महादेशहरूले ओगटेको भू-भाग क्रमशः अफ्रिका (२०.३५%), उत्तर अमेरिका (१६.२%), दक्षिण अमेरिका (११.९%), अन्टार्कटिका (९%), युरोप (७%) र अष्ट्रेलिया (५%) रहेको छ।', 'nepali'),
      (v_set_id, 2, E'नेपालको हावापानीको आधारमा पालुवा पलाउने ऋतु भनेर कुन ऋतुलाई चिनिन्छ?', E'ग्रीष्म ऋतु', E'वसन्त ऋतु', E'हेमन्त ऋतु', E'वर्षा ऋतु', 'B', E'नेपालको हावापानीको आधारमा पालुवा पलाउने ऋतु भनेर **वसन्त ऋतु**लाई चिनिन्छ।\n- ग्रीष्म ऋतुमा अत्यन्त गर्मी हुन्छ।\n- हेमन्त ऋतुमा चिसोको अनुभव भई जाडो बढ्छ।\n- वर्षा ऋतुमा अत्याधिक वर्षा हुन्छ।', 'nepali'),
      (v_set_id, 3, E'एसियाको लामो हिमनदी सियाचेनमा कुन कुन मुलुकको बिबाद रहेको छ?', E'भारत र चीन', E'पाकिस्तान र भारत', E'चीन र अफगानिस्तान', E'पाकिस्तान र चीन', 'B', E'एसियाको लामो हिमनदी सियाचेनमा **पाकिस्तान र भारत** बीच विवाद रहेको छ। यो हिमनदी हिमालयको पूर्वी काराकोरम दायरामा अवस्थित छ।\nनोट: सियाचेन ग्लेशियरको लम्बाइ ७६ किलोमिटर छ।', 'nepali'),
      (v_set_id, 4, E'हालसालै नेपाल क्रिकेट संघ (क्यान) ले राष्ट्रिय पुरुष टोलि क्रिकेटको मुख्य प्रशिक्षकमा कसलाई नियुक्त गरेको छ?', E'स्टुवार्ट ल', E'कौशल विष्ट', E'गोकुल थापा', E'मोटी देसाई', 'A', E'नेपाल क्रिकेट संघ (क्यान) ले राष्ट्रिय पुरुष क्रिकेट टोलीको मुख्य प्रशिक्षकमा अष्ट्रेलियाका **स्टुवार्ट ल** लाई नियुक्त गरेको छ। वि.सं. २०८१ चैत्र १५ मा क्यानले उनलाई दुई वर्षको सम्झौतामा नियुक्त गरेको हो।\nनोट: उनले पूर्व प्रशिक्षक मोटी देसाईको स्थान लिएका हुन्, जसको अनुबन्ध नवीकरण गरिएन।', 'nepali'),
      (v_set_id, 5, E'नेपालको संविधानको कुन धारामा बजेट तर्जुमा सम्बन्धि व्यवस्था रहेको छ?', E'धारा ११९', E'धारा ११७', E'धारा ११५', E'धारा ११३', 'A', E'नेपालको संविधानको **धारा ११९** मा बजेट तर्जुमा सम्बन्धी व्यवस्था रहेको छ। यो व्यवस्था संविधानको भाग १० ''संघीय आर्थिक कार्यप्रणाली'' अन्तर्गत उल्लेख गरिएको छ, जसमा अर्थमन्त्रीले प्रत्येक आर्थिक वर्षको सम्बन्धमा संघीय संसदका दुवै सदनको संयुक्त बैठकमा वार्षिक अनुमान पेश गर्नुपर्ने व्यवस्था छ।', 'nepali'),
      (v_set_id, 6, E'राष्ट्रिय ज्येष्ठ नागरिक दिवस हरेक वर्ष कुन दिन मनाइन्छ?', E'पुस १०', E'पुस ११', E'पुस १२', E'पुस १३', 'B', E'राष्ट्रिय ज्येष्ठ नागरिक दिवस हरेक वर्ष **पुस ११** गते मनाइन्छ।\nनोट: पाँचौ राष्ट्रिय ज्येष्ठ नागरिक दिवस, २०८२ को नारा ''हाम्रो साझा अभियान: ज्येष्ठ नागरिक प्रति श्रद्धा र सम्मान'' रहेको थियो।', 'nepali'),
      (v_set_id, 7, E'राजापुर सिंचाइ आयोजना कुन जिल्लामा सञ्चालित रहेको छ?', E'रुपन्देही', E'बर्दिया', E'बाँके', E'झापा', 'B', E'**राजापुर सिंचाइ आयोजना बर्दिया जिल्लामा सञ्चालित रहेको छ।**\n- रुपन्देही जिल्लामा तिनाउ सिंचाइ आयोजना सञ्चालित छ।\n- बाँके जिल्लामा सिक्टा सिंचाइ आयोजना सञ्चालित छ।\n- झापा जिल्लामा कन्काई सिंचाइ आयोजना सञ्चालित छ।', 'nepali'),
      (v_set_id, 8, E'अवशिष्ट अधिकार सम्बन्धि व्यवस्था नेपालको संविधानको कुन धारामा रहेको छ?', E'धारा ६१', E'धारा ५९', E'धारा ६०', E'धारा ५८', 'D', E'नेपालको संविधानको **धारा ५८** मा अवशिष्ट अधिकार (Residual Powers) सम्बन्धी व्यवस्था रहेको छ। यस धारा अनुसार संघ, प्रदेश तथा स्थानीय तहको अधिकारको सूची वा साझा सूचीमा उल्लेख नभएको विषयमा संघको अधिकार हुने व्यवस्था छ।\nनोट: धारा ५९ मा आर्थिक अधिकारको प्रयोग सम्बन्धी व्यवस्था उल्लेख गरिएको छ।', 'nepali'),
      (v_set_id, 9, E'हाम्रो सौर्यमण्डल अवस्थित milky way galaxy को केन्द्र वरिपरि सूर्यलाई १ फन्को लगाउन करिब २५ करोड वर्ष लाग्छ, यस समयलाई के भनिन्छ?', E'milky year', E'galactic year', E'solar year', E'cosmic year', 'D', E'सूर्यले मिल्की वे ग्यालेक्सीको केन्द्रलाई एक पटक परिक्रमा गर्न लाग्ने समयलाई **कस्मिक इयर (Cosmic Year)** भनिन्छ। यो अवधि करिब २२.५ देखि २५ करोड वर्षको हुन्छ। हाम्रो सौर्यमण्डल मिल्की वे ग्यालेक्सीको एक कुनामा अवस्थित छ र यसको केन्द्र (Galactic Centre) बाट करिब ३० हजार प्रकाश वर्ष टाढा छ।', 'nepali'),
      (v_set_id, 10, E'चोनाम पर्व कुन जातिमा प्रचलन रहेको प्रमुख चाड हो?', E'तामाङ', E'चेपाङ', E'शेर्पा', E'राई', 'B', E'**चोनाम पर्व चेपाङ जातिको प्रमुख चाड हो।**\n- तामाङ समुदायले मुख्यतया सोनाम ल्होसार मनाउँछन्।\n- शेर्पा समुदायले ग्याल्पो ल्होसार र डुम्जी पर्व मनाउँछन्।\n- राई जातिले साकेला (उभौली र उधौली) पर्व धुमधामसँग मनाउँछन्।\nनोट: चोनाम पर्वलाई ''न्वागी'' पनि भनिन्छ, जुन नयाँ अन्नबाली पाकेपछि पितृ र भूमिलाई चढाएर मनाइन्छ।', 'nepali'),
      (v_set_id, 11, E'तलमध्ये कुन इनपुट उपकरण हो?', E'प्रिन्टर', E'किबोर्ड', E'स्क्यानर', E'स्पिकर', 'B', E'**किबोर्ड एक प्रमुख इनपुट उपकरण हो, जसबाट कम्प्युटरमा डाटा र निर्देशनहरू प्रविष्ट गरिन्छ।**\n- प्रिन्टर एक आउटपुट उपकरण हो, जसले डिजिटल जानकारीलाई कागजमा छाप्छ।\n- स्क्यानर पनि एक इनपुट उपकरण हो, जसले भौतिक कागजातलाई डिजिटल डाटामा रूपान्तरण गर्छ।\n- स्पिकर एक आउटपुट उपकरण हो, जसले अडियो डाटालाई ध्वनिमा बदल्छ।', 'nepali'),
      (v_set_id, 12, E'देहायका मध्ये कुन व्यक्ति पुनर्जागरण कालसँग सम्बन्धित छैनन्?', E'माइकेल एन्जेलो', E'दाँते', E'मन्टेस्क्यु', E'मेकियावेली', 'C', E'**मन्टेस्क्यु प्रबुद्धिकरण (Enlightenment) कालका दार्शनिक हुन्, पुनर्जागरण कालका होइनन्।**\n- माइकेल एन्जेलो पुनर्जागरण कालका एक प्रमुख कलाकार, मूर्तिकार र वास्तुकार थिए।\n- दाँते (Dante Alighieri) लाई मध्ययुगको अन्त्य र पुनर्जागरणको सुरुवातका एक महान् कविको रूपमा चिनिन्छ।\n- मेकियावेली (Niccolò Machiavelli) पुनर्जागरण कालका एक महत्वपूर्ण राजनीतिक दार्शनिक र लेखक थिए।\nनोट: मन्टेस्क्यु शक्ति पृथकीकरणको सिद्धान्त (Separation of Powers) का लागि प्रसिद्ध छन्।', 'nepali'),
      (v_set_id, 13, E'दोस्रो पटक राजा ज्ञानेन्द्र कहिले राजा बने?', E'२०५८ जेठ २२', E'२०५८ जेठ १९', E'२०५८ जेठ २०', E'२०६५ जेठ २१', 'A', E'नारायणहिटी दरबार हत्याकाण्ड (२०५८ जेठ १९) पछि तत्कालीन युवराज दीपेन्द्रको निधन भएपश्चात् ज्ञानेन्द्र शाह **२०५८ साल जेठ २२ गते** दोस्रो पटक नेपालको राजा बनेका थिए।\nनोट: उनी पहिलो पटक वि.सं. २००७ मा ३ महिनाका लागि राजा भएका थिए जब उनका हजुरबुवा त्रिभुवन भारतमा शरण लिन गएका थिए।', 'nepali'),
      (v_set_id, 14, E'पृथ्वी दिवस मनाउन कहिले देखि थालिएको हो?', E'सन् १९७०', E'सन् १९७२', E'सन् १९७६', E'सन् १९८०', 'A', E'पृथ्वी दिवस मनाउन **सन् १९७०** देखि थालिएको हो। दिगो विकासको अवधारणाको रूपमा सुरु भएको यो दिवस हरेक वर्ष अप्रिल २२ मा मनाइन्छ।\nनोट: पृथ्वी दिवस २०२४ को नारा ''Our Power, Our Planet'' रहेको थियो।', 'nepali'),
      (v_set_id, 15, E'Point four program देहाय मध्ये केसँग सम्बन्धित छ?', E'राजनीतिक विकास', E'भौतिक विकास', E'आर्थिक विकास', E'मानव विकास', 'C', E'अमेरिकी सहयोग कार्यक्रम ''प्वाइन्ट फोर प्रोग्राम'' **आर्थिक विकाससँग** सम्बन्धित छ। यसै कार्यक्रम मार्फत अमेरिकाले नेपाललाई पहिलो पटक आर्थिक सहयोग गरेको थियो।\nनोट: अमेरिकाले सन् १९५१ मा पहिलो पटक $22000 सहयोग प्रदान गरेको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/०१', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_02.csv  →  आसमान दैनिक GK — २०८२/१०/०२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/०२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/०२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/०२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको पहिलो माछा संरक्षण क्षेत्रको रुपमा कुन स्थानलाई घोषणा गरिएको छ ?', E'गोदावरी', E'बागेश्वरी', E'सत्तिघाट', E'तुल्सिपुर', 'C', E'नेपालको पहिलो माछा संरक्षण क्षेत्रको रुपमा **सत्तिघाट**लाई घोषणा गरिएको छ। यो क्षेत्र कर्णाली नदीमा बर्दिया र कैलालीको सिमानामा पर्दछ र यसलाई २०८२ पौष २५ मा घोषणा गरिएको थियो।\nनोट: ३.९ वर्ग किलोमिटर (३९० हेक्टर) क्षेत्रफलमा फैलिएको यस क्षेत्रको मुख्य प्रयोजन रैयाने माछाको प्रजनन, अण्डा पार्ने र नर्सरी क्षेत्रको विकास गर्नु हो।', 'nepali'),
      (v_set_id, 2, E'हालसालै FATF-International Cooperation Review Group को बैठक २०२६ कहाँ सम्पन्न भएको छ ?', E'जेनेभा', E'बैंकक', E'टोकियो', E'काठमाडौं', 'B', E'FATF-International Cooperation Review Group को बैठक २०२६ **बैंकक, थाइल्याण्डमा** सम्पन्न भएको थियो। यो बैठक वि.सं. २०८२ पौष २२ (२०२६ जनवरी ६) मा आयोजना भएको थियो र सम्पत्ति शुद्धिकरणसँग सम्बन्धित थियो।\nनोट: बैठकमा नेपाली प्रतिनिधि मण्डलको नेतृत्व गभर्नर विश्वनाथ पौडेलले गरेका थिए।', 'nepali'),
      (v_set_id, 3, E'राष्ट्रिय रेशम सम्मेलन, २०८२ कहिले सम्पन्न भएको छ ?', E'२०८२ पौष २४', E'२०८२ पौष २५', E'२०८२ पौष २६', E'२०८२ पौष २७', 'C', E'राष्ट्रिय रेशम सम्मेलन **वि.सं. २०८२ पौष २६** गते काठमाडौंमा सम्पन्न भएको थियो।\nनोट: यस सम्मेलनको उद्देश्य रेशम उद्योगको पुनःजागरण गर्नु रहेको थियो।', 'nepali'),
      (v_set_id, 4, E'नेपालमा प्रत्येक वर्ष कुन दिन राजवंशी समुदायमा भक्का दिवस मनाउने चलन रहेको छ ?', E'पौष २७', E'पौष २८', E'पौष २९', E'पौष ३०', 'C', E'पूर्वी तराईको झापा र मोरङका आदिवासी राजवंशी समुदायले प्रत्येक वर्ष **पौष २९** गते भक्का दिवस मनाउने गर्दछन्।\nनोट: यो दिवस रैथाने परम्परागत खाद्य परिकारको रूपमा रहेको भक्कालाई प्रवर्धन गर्ने उद्देश्यले मनाइन्छ।', 'nepali'),
      (v_set_id, 5, E'हालसालै प्रक्षेपण गरिएको नेपाली असफल भू-उपग्रहको नाम के हो ?', E'नेपाली स्याट', E'मुनाल', E'डाँफे', E'नेपाल किङ', 'B', E'हालसालै प्रक्षेपण गरिएको तर असफल भएको नेपाली भू-उपग्रहको नाम **मुनाल** हो।\n- नेपाली स्याट (NepaliSat-1) नेपालको पहिलो भू-उपग्रह हो, जसलाई वि.सं. २०७६ वैशाख ५ मा सफलतापूर्वक प्रक्षेपण गरिएको थियो।\n- डाँफे र नेपाल किङ नेपालका भू-उपग्रहका नाम होइनन्।\nनोट: मुनाल उपग्रह २०८२ पौष २८ (२०२६ जनवरी १२) मा भारतको श्रीहरिकोटास्थित सतीश धवन अन्तरिक्ष केन्द्रबाट प्रक्षेपण गरिएको थियो।', 'nepali'),
      (v_set_id, 6, E'२०८२ सालमा मनाइएको भूकम्प सुरक्षा दिवस कति औं हो ?', E'२६ औं', E'२७ औं', E'२८ औं', E'२९ औं', 'C', E'वि.सं. २०८२ सालमा **२८ औं** राष्ट्रिय भूकम्प सुरक्षा दिवस मनाइएको थियो।\nनोट: यो दिवस हरेक वर्ष माघ २ गते वि.सं. १९९० को महाभूकम्पको स्मृतिमा मनाइन्छ र यसको सुरुवात वि.सं. २०५५ देखि भएको हो।', 'nepali'),
      (v_set_id, 7, E'२०८२ सालमा मनाइएको पृथ्वी जन्मजयन्ती कति औं हो ?', E'३०३ औं', E'३०४ औं', E'३०५ औं', E'३०६ औं', 'B', E'राष्ट्रनिर्माता पृथ्वीनारायण शाहको **३०४ औं** जन्मजयन्ती तथा राष्ट्रिय एकता दिवस २०८२ पुस २७ गते मनाइएको छ। उनको जन्म वि.सं. १७७९ पुस २७ गते भएको थियो।', 'nepali'),
      (v_set_id, 8, E'गरिबी तथ्यांक, २०८२ अनुसार नेपालमा सबैभन्दा धेरै गरिबी दर रहेको जिल्ला कुन हो ?', E'जाजरकोट', E'मुस्ताङ', E'कास्की', E'अछाम', 'D', E'गरिबी तथ्यांक, २०८२ अनुसार नेपालमा सबैभन्दा धेरै गरिबी दर रहेको जिल्ला **अछाम (४९.५८%)** हो।\n- जाजरकोटको जुनीचाँदे गाउँपालिकामा स्थानीय तहमध्ये सबैभन्दा बढी गरिबी (७७.८९%) रहेको छ।\n- मुस्ताङको घरपझोङ गाउँपालिकामा सबैभन्दा कम गरिबी (१.१८%) रहेको छ।\n- कास्की जिल्लामा सबैभन्दा कम गरिबी दर (५.६३%) रहेको छ।\nनोट: प्रदेशगत रूपमा सुदूरपश्चिममा गरिबी सबैभन्दा बढी (३४.१६%) छ भने गण्डकी प्रदेशमा सबैभन्दा कम (११.८८%) छ।', 'nepali'),
      (v_set_id, 9, E'अमेरिकी संसदमा कुन मुलुकलाई ५१ औं राज्य बनाउने विधेयक पेस भएको छ ?', E'भेनेजुएला', E'इरान', E'ग्रिनल्यान्ड', E'ताइवान', 'C', E'अमेरिकी संसदमा **ग्रिनल्यान्डलाई** ५१ औं राज्य बनाउने विधेयक जनवरी १२, २०२६ मा पेस भएको हो। ''ग्रिनल्यान्डको विलय र राज्य ऐन'' नाम दिइएको उक्त विधेयक संसदमा पेस भएको थियो।', 'nepali'),
      (v_set_id, 10, E'दुवै खुट्टा घुँडा माथिबाट काटिएको अवस्थामा पनि विश्वका सातै महादेशका अग्ला हिमाल पूरा गर्ने कीर्तिमान कायम गरेका नेपाली आरोही को हुन् ?', E'हरि बुढामगर', E'निर्मल पुजा', E'फुन्जो झाङ्मु', E'कामिरिता शेर्पा', 'A', E'दुवै खुट्टा घुँडा माथिबाट काटिएको अवस्थामा विश्वका सातै महादेशका अग्ला हिमाल आरोहण गरी कीर्तिमान कायम गर्ने नेपाली आरोही **हरि बुढामगर** हुन्।\n- कामिरिता शेर्पाले २०८२ जेठ १३ मा सगरमाथाको ३१ औं पटक सफल आरोहण गरी कीर्तिमान कायम गरेका छन्।\n- निर्मल पुर्जा र फुन्जो झाङ्मु पनि नेपालका चर्चित पर्वतारोही हुन्।', 'nepali'),
      (v_set_id, 11, E'एनएसजेएफ पल्सर स्पोर्ट्स अवार्ड २०८१ मा उत्कृष्ट पुरुष खेलाडीको अवार्ड पाएका नेपाली खेलाडी को हुन् ?', E'सोमपाल कामी', E'दीपेन्द्रसिंह ऐरी', E'रोहित पौडेल', E'कुशल मल्ल', 'B', E'एनएसजेएफ पल्सर स्पोर्ट्स अवार्ड २०८१ मा उत्कृष्ट पुरुष खेलाडीको अवार्ड क्रिकेटर **दीपेन्द्रसिंह ऐरीले** जितेका हुन्।\nनोट: सोही अवार्डमा उत्कृष्ट महिला खेलाडीको अवार्ड करातेकी एरिका गुरुङले जितेकी थिइन्।', 'nepali'),
      (v_set_id, 12, E'नवौं केएनपी निरोलेक राष्ट्रिय महिला भलिबल प्रतियोगिताको विजेता टिम कुन बनेको छ ?', E'आर्मी क्लब', E'देउराली क्लब', E'न्यू एभरेष्ट', E'न्यू डायमण्ड', 'D', E'नवौं केएनपी निरोलेक राष्ट्रिय महिला भलिबल प्रतियोगिताको विजेता टिम **न्यू डायमण्ड युथ स्पोर्ट्स क्लब** बनेको हो।\nनोट: प्रतियोगितामा सर्वोत्कृष्ट खेलाडीको उपाधि न्यू डायमण्डकी प्रतिभा मालीले जितेकी थिइन्।', 'nepali'),
      (v_set_id, 13, E'बंगलादेशकी पहिलो महिला प्रधानमन्त्री खालिदा जियाको निधन कहिले भएको हो ?', E'२०२५ डिसेम्बर ३०', E'२०२५ डिसेम्बर २९', E'२०२५ डिसेम्बर २८', E'२०२५ डिसेम्बर २७', 'A', E'बंगलादेशकी पहिलो महिला प्रधानमन्त्री खालिदा जियाको निधन **सन् २०२५ डिसेम्बर ३०** मा भएको थियो। उनी सन् १९९१ देखि १९९६ र सन् २००१ देखि २००६ सम्म गरी दुई पटक बंगलादेशको प्रधानमन्त्री बनेकी थिइन्।\nनोट: खालिदा जिया सन् १९८१ मा बंगलादेशको राष्ट्रपति बनेका जियाउर रहमानकी पत्नी थिइन्।', 'nepali'),
      (v_set_id, 14, E'राष्ट्रिय योग दिवस नेपालमा हरेक वर्ष कुन दिन मनाइन्छ ?', E'माघ १', E'माघ २', E'माघ ३', E'माघ ४', 'A', E'नेपालमा राष्ट्रिय योग दिवस हरेक वर्ष **माघ १ गते** मनाइन्छ। यो दिवस वि.सं. २०७२ देखि मनाउन थालिएको हो।\nनोट: अन्तर्राष्ट्रिय योग दिवस भने हरेक वर्ष जुन २१ मा मनाइन्छ।', 'nepali'),
      (v_set_id, 15, E'२०८२ मा कति औं राष्ट्रिय कृषि जैविक विविधता दिवस मनाइएको छ?', E'पहिलो', E'दोस्रो', E'तेस्रो', E'चौथो', 'D', E'वि.सं. २०८२ मा **चौथो** राष्ट्रिय कृषि जैविक विविधता दिवस मनाइएको छ। यो दिवस वि.सं. २०७९ देखि हरेक वर्ष माघ १ गते मनाउन सुरु गरिएको हो।\nनोट: २०८२ को नारा ''कृषि जैविक विविधता हाम्रो अमूल्य सम्पदा: संरक्षण, उपयोग र प्रवर्द्धन युवा सहभागिता'' रहेको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/०२', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_04.csv  →  आसमान दैनिक GK — २०८२/१०/०४  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/०४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/०४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/०४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आकाश गङ्गा तारापुञ्ज (Milky way galaxy) कस्तो प्रकारको तारापुञ्ज हो?', E'स्पाइरल', E'इलिप्टिकल', E'इरेगुलर', E'सर्कुलर', 'A', E'हाम्रो सौर्यमण्डल रहेको आकाशगंगा तारापुञ्ज **स्पाइरल (Spiral) अर्थात् घुमाउरो** आकारको छ।\nनोट: तारापुञ्जहरूलाई तिनीहरूको आकारको आधारमा स्पाइरल, इलिप्टिकल (अण्डाकार), र इरेगुलर (अनियमित) गरी तीन मुख्य समूहमा विभाजन गरिन्छ।', 'nepali'),
      (v_set_id, 2, E'नेपालको राजनितिक एंव प्रशासनिक विभाजन अन्तर्गत नेपाललाई १४ अञ्चल ७५ जिल्लामा विभाजन कहिले गरिएको थियो?', E'२०१५ सालमा', E'२०१८ सालमा', E'२०१९ सालमा', E'२०१८ सालमा', 'D', E'राजा महेन्द्रको पालामा **वि.सं. २०१८ वैशाख १ गते** नेपाललाई १४ अञ्चल र ७५ जिल्लामा विभाजन गरिएको थियो।\nनोट: यो व्यवस्था नेपालको संविधान २०७२ जारी भएसँगै २०७२ असोज ३ गते खारेज भएको थियो।', 'nepali'),
      (v_set_id, 3, E'अमेरिकी स्वतन्त्रता संग्राम को नारा के थियो?', E'मृत्यु देउ वा स्वतन्त्रता', E'समानता, स्वतन्त्रता र भातृत्व', E'बाँच्नका लागि रोटी', E'विविधतामा एकता', 'A', E'**''मृत्यु देउ वा स्वतन्त्रता'' (Give me liberty, or give me death!)** अमेरिकी स्वतन्त्रता संग्रामको प्रमुख नारा थियो।\n- ''समानता, स्वतन्त्रता र भातृत्व'' फ्रान्सेली राज्य क्रान्तिको नारा हो।\n- ''बाँच्नका लागि रोटी'' (Peace, Land, and Bread) रुसी क्रान्तिसँग सम्बन्धित छ।\n- ''विविधतामा एकता'' भारतको राष्ट्रिय एकताको आदर्श वाक्य हो।', 'nepali'),
      (v_set_id, 4, E'प्रसिद्ध मन्दिर बौद्धनाथको स्थापना गर्ने लिच्छवि राजा को हुन्?', E'शिवदेव', E'नरेन्द्रदेव', E'प्रचण्डदेव', E'अंशुवर्मा', 'A', E'**प्रसिद्ध बौद्धनाथ मन्दिरको स्थापना लिच्छवि राजा शिवदेवले गरेका हुन्।**\n- नरेन्द्रदेवले प्रसिद्ध भद्राधिवास भवनको निर्माण गराएका थिए।\n- प्रचण्डदेव पशुपतिनाथको मन्दिर स्थापना गर्ने राजा हुन्।\n- अंशुवर्माले कैलाशकुट भवनको निर्माण गराएका थिए।\nनोट: शिवदेवलाई लिच्छवीका कुलकेतु पनि भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'नेपाल र किरिबाटी बिच दौत्य सम्बन्ध कहिले कायम भयो?', E'२०२४ जुलाई १७', E'२०२४ जुलाई १६', E'२०२४ जुन १७', E'२०२४ जुन १६', 'A', E'नेपाल र किरिबाटी बिच **सन् २०२४ जुलाई १७** मा दौत्य सम्बन्ध कायम भएको थियो।\nनोट: किरिबाटी नेपालसँग दौत्य सम्बन्ध कायम गर्ने १८३ औं मुलुक हो।', 'nepali'),
      (v_set_id, 6, E'सबैभन्दा अन्तिममा नामाकरण भएको कोशी प्रदेशको कहिले प्रदेश नामाकरण भयो?', E'२०७९ फागुन १३', E'२०७९ फागुन ११', E'२०७९ फागुन १२', E'२०७९ फागुन १७', 'D', E'कोशी प्रदेशको नामाकरण **वि.सं. २०७९ फागुन १७** गते भएको थियो। यो नामाकरण हुने अन्तिम प्रदेश हो।\nनोट: कोशी प्रदेशको राजधानी विराटनगर हो, जसलाई वि.सं. २०७६ वैशाख २३ मा तोकिएको थियो।', 'nepali'),
      (v_set_id, 7, E'आर्थिक वर्ष २०८२/८३ को बजेटले विद्यार्थीलाई दिवा खाजा उपलब्ध गराउने उद्देश्यले कति रकम विनियोजन गरिएको छ?', E'१० अर्ब १९ करोड', E'११ अर्ब १९ करोड', E'१२ अर्ब १९ करोड', E'१३ अर्ब १९ करोड', 'A', E'आर्थिक वर्ष २०८२/८३ को बजेटले विद्यार्थीलाई दिवा खाजा उपलब्ध गराउन **१० अर्ब १९ करोड** रकम विनियोजन गरेको छ।\nनोट: सोही बजेटले सेनेटरी प्याडका लागि १ अर्ब २९ करोड र ईसीडी शिक्षक तथा विद्यालय कर्मचारीको पारिश्रमिकका लागि १० अर्ब १६ करोड विनियोजन गरेको छ।', 'nepali'),
      (v_set_id, 8, E'विश्व व्यापार संगठनका कति वटा अंगहरू रहेका छन्?', E'३ वटा', E'४ वटा', E'५ वटा', E'६ वटा', 'B', E'विश्व व्यापार संगठन (WTO) का **४ वटा** अंगहरू रहेका छन्। ती अंगहरू मन्त्रीस्तरीय सम्मेलन, महापरिषद, परिषद र सचिवालय हुन्।\nनोट: WTO को सर्वोच्च अंग मन्त्रीस्तरीय सम्मेलन हो।', 'nepali'),
      (v_set_id, 9, E'प्रत्येक व्यक्ति र समुदायलाई आफ्नो भाषा प्रयोग गर्ने हक हुनेछ भन्ने कुरा कुन धारामा उल्लेख गरिएको छ?', E'धारा ३१', E'धारा ३२', E'धारा ३३', E'धारा ३४', 'B', E'नेपालको संविधानको **धारा ३२** मा प्रत्येक व्यक्ति र समुदायलाई आफ्नो भाषा प्रयोग गर्ने हक हुनेछ भन्ने व्यवस्था गरिएको छ। यस धारामा भाषा तथा संस्कृतिको हक सम्बन्धी व्यवस्था छ।', 'nepali'),
      (v_set_id, 10, E'पृथ्वीलाई ठिक बीचबाट आधाहुने गरी पृथ्वीको उत्तरी ध्रुव देखी दक्षिणी ध्रुव सम्म खिचिएको ठाडो काल्पनिक रेखालाई के भनिन्छ?', E'उत्तरी ध्रुव', E'प्रधान मध्यान्ह', E'भूमध्य रेखा', E'सुमेरु वृत्त', 'B', E'पृथ्वीलाई ठिक बीचबाट आधा हुने गरी उत्तरी ध्रुवदेखि दक्षिणी ध्रुवसम्म खिचिएको ठाडो काल्पनिक रेखालाई **प्रधान मध्यान्ह रेखा** भनिन्छ।\n- उत्तरी ध्रुव पृथ्वीको सबैभन्दा उत्तरी बिन्दु हो, जहाँ पृथ्वीको अक्ष सतहसँग मिल्छ।\n- भूमध्य रेखा पृथ्वीको केन्द्रबाट जाने गरी पूर्व-पश्चिम खिचिएको काल्पनिक रेखा हो, जसले पृथ्वीलाई उत्तरी र दक्षिणी गोलार्धमा विभाजन गर्छ।\n- सुमेरु वृत्त (Arctic Circle) उत्तरी गोलार्धमा रहेको एक प्रमुख अक्षांश वृत्त हो।\nनोट: प्रधान मध्यान्ह रेखालाई शून्य डिग्री देशान्तर मानिन्छ र यसले समयको मापनमा आधारको काम गर्दछ।', 'nepali'),
      (v_set_id, 11, E'दास प्रथाको अन्त्य गर्दा हत्या गरिएका अमेरिकी राष्ट्रपतिको हुन?', E'रोनाल्ड रेगन', E'अब्राहम लिंकन', E'डि रुजबेल्ट', E'बाराक ओबामा', 'B', E'दास प्रथाको अन्त्य गर्दा हत्या गरिएका अमेरिकी राष्ट्रपति **अब्राहम लिंकन** हुन्।\n- रोनाल्ड रेगन अमेरिकाका ४०औं राष्ट्रपति थिए, जो आफ्नो आर्थिक नीति ''रेगनोनोमिक्स'' का लागि चिनिन्छन्।\n- डि रुजबेल्ट (Franklin D. Roosevelt) अमेरिकाका ३२औं राष्ट्रपति थिए, जसले महामन्दी र दोस्रो विश्वयुद्धको समयमा देशको नेतृत्व गरे।\n- बाराक ओबामा अमेरिकाका ४४औं तथा प्रथम अश्वेत राष्ट्रपति हुन्।\nनोट: अब्राहम लिंकनले सन् १८६३ जनवरी १ मा दास प्रथाको अन्त्यको घोषणा गरेका थिए र उनको हत्या सन् १८६५ अप्रिल १५ मा भएको थियो।', 'nepali'),
      (v_set_id, 12, E'नेपालको पहिलो वैज्ञानिकको रुपमा चिनिने गेहेन्द्र शमशेरको हत्या कुन दरबारमा भएको थियो?', E'लाल दरबार', E'नारायणहिटी', E'सेतो दरबार', E'फोहोरा दरबार', 'C', E'नेपालका पहिलो वैज्ञानिक गेहेन्द्र शमशेरको हत्या **सेतो दरबारमा** भएको थियो।\n- लाल दरबार वीर शमशेरले आफ्ना छोराहरूका लागि निर्माण गराएका थिए।\n- नारायणहिटी दरबार नेपालका शाहवंशीय राजाहरूको निवास तथा कार्यालय थियो, जुन हाल संग्रहालयमा परिणत भएको छ।\n- फोहोरा दरबार चन्द्र शमशेरले निर्माण गराएका थिए।\nनोट: गेहेन्द्र शमशेरको मृत्यु सन् १९०५ मा काठमाडौँको सेतो दरबारमा भएको थियो।', 'nepali'),
      (v_set_id, 13, E'न्याय, शान्ती र सक्षम निकाय कुन लक्ष्यसँग सम्बन्धित छ?', E'लक्ष्य १४', E'लक्ष्य १५', E'लक्ष्य १३', E'लक्ष्य १६', 'D', E'दिगो विकासको **लक्ष्य १६** न्याय, शान्ति र सक्षम निकाय (Peace, Justice and Strong Institutions) सँग सम्बन्धित छ।\n- लक्ष्य १४ जलमुनिको जीवन (Life Below Water) सँग सम्बन्धित छ।\n- लक्ष्य १५ जमिनमाथिको जीवन (Life on Land) सँग सम्बन्धित छ।\n- लक्ष्य १३ जलवायु परिवर्तन र यसका प्रभाव न्यूनीकरण (Climate Action) सँग सम्बन्धित छ।', 'nepali'),
      (v_set_id, 14, E'अमेरिका बाहिर प्रधान कार्यालय भएको UNO को अंग कुन हो?', E'सुरक्षा परिषद्', E'अन्तर्राष्ट्रिय न्यायालय', E'जिम्मा जमानी परिषद्', E'सचिवालय', 'B', E'संयुक्त राष्ट्र संघ (UNO) को **अन्तर्राष्ट्रिय न्यायालयको** प्रधान कार्यालय अमेरिका बाहिर नेदरल्याण्डको हेगमा रहेको छ।\n- सुरक्षा परिषद्को प्रधान कार्यालय अमेरिकाको न्युयोर्कमा छ।\n- जिम्मा जमानी परिषद्को प्रधान कार्यालय पनि न्युयोर्कमा नै छ।\n- सचिवालयको मुख्य कार्यालय पनि न्युयोर्कमा अवस्थित छ।\nनोट: अन्तर्राष्ट्रिय न्यायालय संयुक्त राष्ट्र संघको एक मात्र यस्तो अंग हो जसमा महासचिवले भाग लिन पाउँदैनन्।', 'nepali'),
      (v_set_id, 15, E'सार्कको कति औं महासचिवहरु नेपाली नागरिक हुन?', E'चौथो र एघारौं', E'तेस्रो र बाह्रौं', E'चौथो र बाह्रौं', E'तेस्रो र एघारौं', 'C', E'हालसम्म सार्कका **चौथो र बाह्रौं** गरी दुई जना महासचिव नेपाली नागरिक भएका छन्।\n- नेपालका चौथो महासचिव यादव कान्त सिलवाल (१ जनवरी १९९४ - ३१ डिसेम्बर १९९५) र बाह्रौं महासचिव अर्जुन बहादुर थापा (१ मार्च २०१४ - १ मार्च २०१७) थिए।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/०४', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_05.csv  →  आसमान दैनिक GK — २०८२/१०/०५  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/०५'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/०५';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/०५', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'सूर्यको सतहको चम्किलो घेरालाई के भनिन्छ?', E'Photosphere', E'Umbra', E'Penumbra', E'Heliscope', 'C', E'सूर्यको सतहको चम्किलो घेरालाई **पेनम्ब्रा (Penumbra)** भनिन्छ।\n- सूर्यको सतह भागलाई फोटोस्फियर (Photosphere) भनिन्छ।\n- सूर्यको मध्य भागमा देखिने धब्बालाई अम्ब्रा (Umbra) भनिन्छ।\n- सूर्यलाई हेर्न प्रयोग गरिने यन्त्रलाई हेलिस्कोप (Heliscope) भनिन्छ।', 'nepali'),
      (v_set_id, 2, E'ओलम्पिक माउन्टेन कुन देशमा रहेको छ?', E'क्यानडा', E'अर्जेन्टिना', E'अमेरिका', E'जापान', 'C', E'ओलम्पिक माउन्टेन **अमेरिकाको** वाशिङ्टन राज्यमा अवस्थित ओलम्पिक राष्ट्रिय निकुञ्जमा पर्दछ।\nनोट: ग्रीसमा अवस्थित पर्वतलाई भने माउन्ट ओलम्पस भनिन्छ, जुन ग्रीक देवताहरूको घर मानिन्छ।', 'nepali'),
      (v_set_id, 3, E'सात पोखरीको शहर भनेर कुन शहरलाई चिनिन्छ?', E'काठमाण्डौ', E'रसुवा', E'पोखरा', E'बनेपा', 'A', E'**सात पोखरीको शहर भनेर काठमाण्डौलाई चिनिन्छ।**\n- रसुवालाई सात कुण्डको जिल्ला भनेर चिनिन्छ।\n- पोखरालाई सात तालको शहर भनेर चिनिन्छ।\n- बनेपा काभ्रेपलाञ्चोक जिल्लामा अवस्थित एक ऐतिहासिक र व्यापारिक शहर हो।', 'nepali'),
      (v_set_id, 4, E'साती कृषि गणना अनुसार सबैभन्दा धेरै तरकारी खेती हुने जिल्ला कुन हो?', E'काभ्रे', E'चितवन', E'स्याङ्जा', E'सिराहा', 'B', E'सातौँ कृषि गणना अनुसार सबैभन्दा धेरै तरकारी खेती हुने जिल्ला **चितवन** हो।\n- काभ्रे जिल्लामा सबैभन्दा धेरै आलु खेती हुन्छ।\n- स्याङ्जा जिल्लामा सबैभन्दा धेरै सुन्तला खेती हुन्छ।\n- सिराहा जिल्लामा सबैभन्दा धेरै आँप खेती हुन्छ।\nनोट: सबैभन्दा धेरै तरकारी खेती हुने प्रदेश बागमती हो।', 'nepali'),
      (v_set_id, 5, E'आर्थिक वर्ष २०८२/८३ को बजेटका प्रमुख प्रावधान अन्तर्गत वृद्धभत्ता पाउन अब कति वर्ष पुग्नु पर्नेछ?', E'६८ वर्ष', E'७० वर्ष', E'७२ वर्ष', E'७४ वर्ष', 'B', E'आर्थिक वर्ष २०८२/८३ को बजेट अनुसार वृद्धभत्ता पाउन **७० वर्ष** पुग्नुपर्ने प्रावधान ल्याइएको छ।', 'nepali'),
      (v_set_id, 6, E'बसुन्धराश्री पुरस्कार, २०८२ कसलाई प्रदान गरिएको छ?', E'कवि मञ्जुल', E'तुलसी दिवस', E'तोया गुरुङ', E'ध्रुवचन्द्र गौतम', 'B', E'**बसुन्धराश्री पुरस्कार, २०८२ तुलसी दिवसलाई प्रदान गरिएको छ।**\n- तोया गुरुङले मानश्री पुरस्कार, २०८२ प्राप्त गरेकी हुन्।\n- ध्रुवचन्द्र गौतमलाई राष्ट्रिय लेखन पुरस्कार, २०८२ प्रदान गरिएको छ।', 'nepali'),
      (v_set_id, 7, E'राष्ट्रिय धान दिवस, २०८२ कति औं धान दिवस हो?', E'२१ औं', E'२२ औं', E'२३ औं', E'२४ औं', 'B', E'वि.सं. २०८२ असार १५ मा मनाइएको राष्ट्रिय धान दिवस **२२ औं संस्करण** हो।\nनोट: यस वर्षको नारा ''धान बालीमा सघनता : खाद्य सुरक्षा र आत्मनिर्भरता'' रहेको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपालको संविधानको कुन धारामा स्वतन्त्रताको हक सम्बन्धित व्यवस्था गरेको छ?', E'धारा १६', E'धारा १७', E'धारा १८', E'धारा २०', 'B', E'नेपालको संविधानको **धारा १७** मा स्वतन्त्रताको हक सम्बन्धित व्यवस्था गरिएको छ।\n- धारा १६ मा सम्मानपूर्वक बाँच्न पाउने हकको व्यवस्था छ।\n- धारा १८ मा समानताको हकको व्यवस्था छ।\n- धारा २० मा न्याय सम्बन्धी हकको व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 9, E'सर्वप्रथम नाटक लेख्ने तथा रंगमञ्चन गर्ने कार्यको थालनी कहाँबाट भएको हो?', E'मिश्रको सभ्यता', E'युनानी सभ्यता', E'मेसोपोटामिया सभ्यता', E'सिन्धुघाटीको सभ्यता', 'B', E'सर्वप्रथम नाटक लेख्ने तथा रंगमञ्चन गर्ने कार्यको थालनी **युनानी सभ्यता** बाट भएको मानिन्छ।', 'nepali'),
      (v_set_id, 10, E'देहायका मध्ये कुन घटना महेन्द्र वीरविक्रम शाहको पालामा भएको थिएन?', E'योजनाबद्ध विकासको थालनी', E'नयाँ शिक्षा योजना', E'पञ्चायती व्यवस्था लागू', E'जनमत सङ्ग्रह', 'D', E'जनमत सङ्ग्रह राजा **वीरेन्द्र वीर विक्रम शाहको** पालामा वि.सं. २०३६ मा भएको थियो, त्यसैले यो राजा महेन्द्रको पालामा भएको घटना होइन।\n- योजनाबद्ध विकासको थालनी वि.सं. २०१३ मा राजा महेन्द्रको शासनकालमा सुरु भएको थियो।\n- नयाँ शिक्षा योजना वि.सं. २०२८ मा लागू भएको थियो।\n- पञ्चायती व्यवस्था राजा महेन्द्रले वि.सं. २०१९ मा लागू गरेका थिए।', 'nepali'),
      (v_set_id, 11, E'बौद्ध धर्मका ५ शीलहरू (पञ्चशील) मा देहायको मध्ये कुन पर्दैन?', E'सत्य', E'अहिंसा', E'मद्य निषेध', E'चोरी', 'D', E'बौद्ध धर्मको पञ्चशीलमा ''चोरी'' पर्दैन, बरु ''अस्तेय'' अर्थात् **चोरी नगर्नु** भन्ने शील समावेश छ।\n- सत्य (झुटो नबोल्नु) पञ्चशील मध्ये एक हो।\n- अहिंसा (कुनै पनि प्राणीको हिंसा नगर्नु) पनि पञ्चशील अन्तर्गत पर्दछ।\n- मद्य निषेध (मद्यपान तथा अन्य लागुपदार्थ सेवन नगर्नु) पञ्चशीलको एक महत्वपूर्ण अङ्ग हो।\nनोट: बौद्ध धर्मका पाँच शीलहरू हुन्: अहिंसा, सत्य, अस्तेय, ब्रह्मचर्य र मद्य निषेध।', 'nepali'),
      (v_set_id, 12, E'रोग देखि लाग्ने डरलाई वैज्ञानिक भाषामा के भनिन्छ?', E'Philophobia', E'Pyrophobia', E'Pathophobia', E'Ombrophobia', 'C', E'रोग देखि लाग्ने डरलाई वैज्ञानिक भाषामा **Pathophobia** भनिन्छ।\n- Philophobia माया प्रेम देखि लाग्ने डर हो।\n- Pyrophobia आगो देखि लाग्ने डर हो।\n- Ombrophobia वर्षा देखि लाग्ने डर हो।', 'nepali'),
      (v_set_id, 13, E'राष्ट्रिय जलवायु सम्मेलनसँग सम्बन्धित १० बुँदे गुफा घोषणा पत्र जारी कुन जिल्लामा भएको हो?', E'सोलुखुम्बु', E'दोलखा', E'सिन्धुपाल्चोक', E'संखुवासभा', 'C', E'राष्ट्रिय जलवायु सम्मेलनसँग सम्बन्धित १० बुँदे गुफा घोषणा पत्र **सिन्धुपाल्चोक** जिल्लामा जारी भएको हो।\n- सोलुखुम्बु जिल्लामा सगरमाथा अवस्थित छ।\n- दोलखा जिल्ला कालिञ्चोक भगवती मन्दिर र चरिकोटका लागि प्रसिद्ध छ।\n- संखुवासभा जिल्लामा मकालु हिमाल र अरुण उपत्यका पर्दछन्।\nनोट: यो सम्मेलन सिन्धुपाल्चोकको गुफाडाँडामा २०७५ पुस १७ गते (सन् २०१९ जनवरी १) मा सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 14, E'देहायका मध्ये कुन संगठन सबैभन्दा अन्तिममा स्थापना भएको हो?', E'बिमस्टेक', E'आसियान', E'सार्क', E'संयुक्त राष्ट्रसंघ', 'A', E'**बिमस्टेक (BIMSTEC)** दिइएका संगठनहरूमध्ये सबैभन्दा अन्तिममा, सन् १९९७ जुन ६ मा, स्थापना भएको हो।\n- संयुक्त राष्ट्रसंघ सन् १९४५ मा, आसियान सन् १९६७ मा, र सार्क सन् १९८५ मा स्थापना भएका थिए।', 'nepali'),
      (v_set_id, 15, E'मानव विकास सुचांक बढि भएको सार्क मुलुक कुन हो?', E'भारत', E'माल्दिभ्स', E'नेपाल', E'श्रीलंका', 'D', E'संयुक्त राष्ट्रसंघीय विकास कार्यक्रम (UNDP) द्वारा प्रकाशित मानव विकास प्रतिवेदन २०२३/२४ अनुसार, सार्क मुलुकहरूमध्ये सबैभन्दा उच्च मानव विकास सुचांक भएको मुलुक **श्रीलंका** हो।\n- माल्दिभ्स दोस्रो स्थानमा रहेको छ।\n- भारतको स्थान १३४ औं छ।\n- नेपालको स्थान १४६ औं छ।\nनोट: विश्वव्यापी रूपमा श्रीलंका ७८ औं स्थानमा रहेको छ।', 'nepali'),
      (v_set_id, 16, E'स्थायी मानव बसोबास जनसंख्याको सबैभन्दा कम जनसंख्या भएको महादेश कुन हो?', E'दक्षिण अमेरिका', E'उत्तर अमेरिका', E'अस्ट्रेलिया', E'युरोप', 'C', E'स्थायी मानव बसोबासको आधारमा सबैभन्दा कम जनसंख्या भएको महादेश **अस्ट्रेलिया** हो।\n- एसिया विश्वको सबैभन्दा बढी जनसंख्या भएको महादेश हो।\n- अफ्रिका जनसंख्याको आधारमा दोस्रो ठूलो महादेश हो।\n- युरोप क्षेत्रफलको आधारमा दोस्रो सानो महादेश हो।', 'nepali'),
      (v_set_id, 17, E'नेपालको हावापानीको आधारमा जेठ र असारमा कुन ऋतु पर्दछ?', E'ग्रीष्म ऋतु', E'वसन्त ऋतु', E'हेमन्त ऋतु', E'वर्षा ऋतु', 'A', E'नेपालको हावापानीको आधारमा जेठ र असार महिनामा **ग्रीष्म ऋतु** पर्दछ।\n- चैत र वैशाखमा वसन्त ऋतु पर्दछ।\n- साउन र भदौमा वर्षा ऋतु पर्दछ।\n- मंसिर र पुसमा हेमन्त ऋतु पर्दछ।\nनोट: नेपालमा असोज र कात्तिकमा शरद ऋतु तथा माघ र फागुनमा शिशिर ऋतु गरी जम्मा ६ ऋतुहरू अनुभव गरिन्छ।', 'nepali'),
      (v_set_id, 18, E'संसारको सबैभन्दा लामो ग्लेसियर कुन हो?', E'सियाचेन', E'हवार्ड', E'ल्याम्बर्ट', E'पेरिटो मोरेनो', 'C', E'विश्वको सबैभन्दा लामो हिमनदी **ल्याम्बर्ट ग्लेसियर** हो। यो अन्टार्कटिका महादेशमा पर्दछ।\nनोट: यसको लम्बाई करिब ५०० कि.मि., चौडाइ १०० कि.मि. र गहिराई २५०० मिटर रहेको छ।', 'nepali'),
      (v_set_id, 19, E'उखुको लागि प्रसिद्ध ठाउँ कुन हो?', E'धुनिवेशी', E'सिन्धुली', E'मालनेटा', E'फर्पिङ्ग', 'A', E'**उखुका लागि धादिङको धुनिवेशी प्रसिद्ध छ।**\n- सिन्धुली र रामेछाप जुनारका लागि प्रसिद्ध छन्।\n- सल्यानको मालनेटा अदुवाका लागि प्रख्यात छ।\n- फर्पिङ्ग नासपातिको लागि चिनिन्छ।', 'nepali'),
      (v_set_id, 20, E'हाल सालै नेपालको जीवित देवी उपाले चिनिने कुमारी पदमा कसलाई चयन गरियो?', E'आर्यतारा शाक्य', E'प्रतिक्षा शाक्य', E'तृष्णा शाक्य', E'दिनुषा शाक्य', 'A', E'गुठी संस्थानको निर्णय अनुसार **आर्यतारा शाक्य** लाई नेपालको नयाँ जीवित देवी कुमारीको रूपमा चयन गरिएको छ। उनको नियुक्ति २०८२ असोज १४ गते भएको थियो।\nनोट: कुमारीलाई तलेजु भवानीको अवतारका रूपमा पूजा गर्ने परम्परा रहेको छ।', 'nepali'),
      (v_set_id, 21, E'नेपालमा बजेट ल्याउनु पर्ने कानुनी व्यवस्था अनुसार स्थानीय तहले हरेक वर्ष कुन मिति भित्र बजेट ल्याउनु पर्दछ?', E'असार १० भित्र', E'असार १५ भित्र', E'जेठ १५ भित्र', E'असार १ भित्र', 'A', E'**कानुनी व्यवस्था अनुसार स्थानीय तहले हरेक वर्ष असार १० गतेभित्र आफ्नो बजेट ल्याउनुपर्छ।**\n- जेठ १५ गतेभित्र संघीय संसदमा बजेट पेश गर्नुपर्ने प्रावधान छ।\n- असार १ गतेभित्र प्रदेश सभामा बजेट पेश गर्नुपर्ने व्यवस्था रहेको छ।\n- असार १५ गतेलाई राष्ट्रिय धान दिवसको रूपमा मनाइन्छ, यो बजेट पेश गर्ने मिति होइन।', 'nepali'),
      (v_set_id, 22, E'अन्तर्राष्ट्रिय ओजन तह संरक्षण दिवस कहिले मनाइन्छ?', E'सेप्टेम्बर १२', E'सेप्टेम्बर १४', E'सेप्टेम्बर १६', E'सेप्टेम्बर १८', 'C', E'अन्तर्राष्ट्रिय ओजन तह संरक्षण दिवस हरेक वर्ष **सेप्टेम्बर १६** मा मनाइन्छ।\nनोट: सन् १९८७ को सेप्टेम्बर १६ मा ओजन तह संरक्षण सम्बन्धी मन्ट्रियल प्रोटोकलमा हस्ताक्षर भएको दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 23, E'नेपालको संविधानमा कुन धारामा राज्यको संरचनासँग सम्बन्धित व्यवस्था गरिएको छ?', E'धारा ५५', E'धारा ५६', E'धारा ५७', E'धारा ५८', 'B', E'नेपालको संविधानको **धारा ५६** ले राज्यको संरचनाबारे व्यवस्था गरेको छ। यस धारा अनुसार संघीय लोकतान्त्रिक गणतन्त्र नेपालको मूल संरचना संघ, प्रदेश र स्थानीय तह गरी तीन तहको हुनेछ।\nनोट: संविधानको धारा ५७ मा भने राज्यशक्तिको बाँडफाँडसम्बन्धी व्यवस्था रहेको छ।', 'nepali'),
      (v_set_id, 24, E'आकाशगंगा तारापुञ्ज (Milky way) देखि सबैभन्दा नजिकको तारापुञ्ज (Galaxy) कुन हो?', E'एन्ड्रोमेडा', E'सूर्य', E'Segue 2', E'IC-1101', 'A', E'हाम्रो आकाशगंगा तारापुञ्ज (Milky Way) बाट सबैभन्दा नजिकको तारापुञ्ज **एन्ड्रोमेडा (Andromeda)** हो।\n- सूर्य हाम्रो सौर्यमण्डलको एक तारा हो, तारापुञ्ज होइन।\n- Segue 2 पत्ता लागेका मध्ये सबैभन्दा सानो तारापुञ्ज मध्ये एक हो।\n- IC-1101 हालसम्म पत्ता लागेको सबैभन्दा ठूलो तारापुञ्ज हो।\nनोट: एन्ड्रोमेडा ग्यालेक्सी हाम्रो आकाशगंगाबाट लगभग २५ लाख प्रकाश वर्ष टाढा रहेको छ।', 'nepali'),
      (v_set_id, 25, E'सिकलसेल एनिमिया नामक रोग कुन समुदायमा मात्र प्रचलित रहेको छ?', E'तामाङ', E'शेर्पा', E'थारु', E'गुरुङ', 'C', E'सिकलसेल एनिमिया एक वंशानुगत रक्त विकार हो जुन नेपालमा विशेषगरी **थारु समुदायमा** बढी प्रचलित छ। यो रोग मलेरियाको प्रकोप बढी हुने क्षेत्रमा अनुकूलनको रूपमा विकसित भएको मानिन्छ।\nनोट: यो रोग खानपानको कारणले नभई पूर्णतया वंशानुगत हुन्छ।', 'nepali'),
      (v_set_id, 26, E'IC कुन पुस्ताको कम्प्युटर सँग सम्बन्धित रहेको छ?', E'तेस्रो', E'दोस्रो', E'चौथो', E'पाँचौ', 'A', E'**इन्टिग्रेटेड सर्किट (IC) को प्रयोग तेस्रो पुस्ताको कम्प्युटरमा भएको थियो।**\n- दोस्रो पुस्ताका कम्प्युटरहरूमा ट्रान्जिस्टरको प्रयोग भएको थियो।\n- चौथो पुस्ताका कम्प्युटरहरूमा माइक्रोप्रोसेसरको प्रयोग सुरु भयो।\n- पाँचौ पुस्ताका कम्प्युटरहरू बायोचिप्स र कृत्रिम बौद्धिकता (AI) मा आधारित छन्।\nनोट: पहिलो पुस्ताका कम्प्युटरहरूमा भ्याकुम ट्युबको प्रयोग गरिन्थ्यो।', 'nepali'),
      (v_set_id, 27, E'विश्व इतिहासमा पुनर्जागरणको सुरुवात कहाँ बाट भएको हो?', E'फ्रान्स', E'बेलायत', E'इटाली', E'अमेरिका', 'C', E'विश्व इतिहासमा पुनर्जागरणको सुरुवात **इटालीको फ्लोरेन्स सहरबाट** भएको मानिन्छ। यो घटना १४ औं शताब्दीमा इटालीमा सुरु भई १६ औं शताब्दीसम्म युरोपभर फैलिएको थियो।', 'nepali'),
      (v_set_id, 28, E'केरुङ सन्धि, वेत्रावति सन्धि कुन राजाको पालामा भएको थियो?', E'रण ब. शाह', E'बहादुर शाह', E'प्रतापसिंह शाह', E'पृथ्वीनारायण शाह', 'A', E'केरुङ सन्धि र वेत्रावति सन्धि **रण बहादुर शाहको** पालामा भएको थियो।\n- बहादुर शाह रण बहादुर शाहका नायब (regent) थिए र उनको नायबीकालमा यी सन्धिहरू भएका थिए।\n- प्रतापसिंह शाहको शासनकाल वि.सं. १८३१ देखि १८३४ सम्म रह्यो।\n- पृथ्वीनारायण शाहले नेपालको एकीकरणको सुरुवात गरेका थिए।\nनोट: केरुङ सन्धि वि.सं. १८४६ मा र वेत्रावति सन्धि वि.सं. १८४९ मा भएको थियो।', 'nepali'),
      (v_set_id, 29, E'"हाम्रो साझा भविष्य" नामक प्रतिवेदन पेश गर्ने संस्था कुन हो?', E'साइटिश', E'ब्रुटल्याण्ड', E'विश्व स्वास्थ्य संगठन', E'विश्व बैंक', 'B', E'"हाम्रो साझा भविष्य" (Our Common Future) नामक प्रतिवेदन **ब्रुटल्याण्ड आयोगले** पेश गरेको थियो।\n- साइटिस (CITES) लोपोन्मुख वन्यजन्तु तथा वनस्पतिको अन्तर्राष्ट्रिय व्यापारलाई नियमन गर्ने अन्तर्राष्ट्रिय महासन्धि हो।\n- विश्व स्वास्थ्य संगठन (WHO) अन्तर्राष्ट्रिय सार्वजनिक स्वास्थ्यको लागि जिम्मेवार संयुक्त राष्ट्र संघको एक विशेष एजेन्सी हो।\n- विश्व बैंक विकासशील देशहरूलाई ऋण र अनुदान प्रदान गर्ने एक अन्तर्राष्ट्रिय वित्तीय संस्था हो।\nनोट: यो प्रतिवेदन सन् १९८७ मा प्रकाशित भएको थियो र यसले पहिलो पटक ''दिगो विकास'' को अवधारणालाई परिभाषित गर्‍यो।', 'nepali'),
      (v_set_id, 30, E'भारत पछि नेपालले दौत्य सम्बन्ध स्थापना गरेको सार्क मुलुक कुन हो?', E'भुटान', E'पाकिस्तान', E'बंगलादेश', E'श्रीलंका', 'D', E'भारत पछि नेपालले दौत्य सम्बन्ध स्थापना गरेको सार्क मुलुक **श्रीलंका** हो।\n- नेपालसँग दौत्य सम्बन्ध स्थापना भएका सार्क राष्ट्रहरूको क्रम यस प्रकार छ: भारत, श्रीलंका, पाकिस्तान, अफगानिस्तान, बंगलादेश, माल्दिभ्स, र भुटान।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/०५', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_07.csv  →  आसमान दैनिक GK — २०८२/१०/०७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/०७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/०७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/०७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'रामायणमा थप भएको नयाँ काण्ड कुन हो?', E'राम अश्वमेध काण्ड', E'सुन्दर काण्ड', E'अयोध्याकाण्ड', E'किस्किन्धा काण्ड', 'A', E'वाल्मिकीद्वारा रचित रामायणमा ७ वटा काण्डहरू थिए, जसमा पछिल्लो समय **राम अश्वमेध काण्ड** थपिएर जम्मा ८ काण्ड पुगेका छन्।\nनोट: रामायणका मूल सात काण्डहरू बालकाण्ड, अयोध्याकाण्ड, अरण्यकाण्ड, किष्किन्धाकाण्ड, सुन्दरकाण्ड, युद्धकाण्ड र उत्तरकाण्ड हुन्।', 'nepali'),
      (v_set_id, 2, E'अफ्रिका महादेशको पूर्वमा रहेको सागर कुन हो?', E'भू-मध्यसागर', E'लालसागर', E'आन्ध्र महासागर', E'बेरिङ सागर', 'B', E'**लालसागर अफ्रिका महादेशको पूर्वमा रहेको छ।**\n- भू-मध्यसागर अफ्रिकाको उत्तरमा पर्दछ।\n- आन्ध्र महासागर अफ्रिकाको पश्चिममा अवस्थित छ।\n- बेरिङ सागर एसिया र उत्तर अमेरिका महादेशको बीचमा पर्दछ।', 'nepali'),
      (v_set_id, 3, E'आर्थिक वर्ष २०८२/८३ को बजेटले शिक्षा क्षेत्रको लागि कति रुपैयाँ विनियोजन गरेको छ?', E'२ खर्ब ११ अर्ब', E'२ खर्ब २१ अर्ब', E'२ खर्ब ३१ अर्ब', E'२ खर्ब ४१ अर्ब', 'A', E'आर्थिक वर्ष २०८२/८३ को बजेटले शिक्षा क्षेत्रको लागि **२ खर्ब ११ अर्ब** रुपैयाँ विनियोजन गरेको छ।\nनोट: बजेटमा उल्लेख भए अनुसार शिक्षा क्षेत्रको लागि छुट्याइएको यथार्थ रकम २ खर्ब ११ अर्ब १७ करोड हो।', 'nepali'),
      (v_set_id, 4, E'भैरव पुरस्कार, २०८२ कसलाई प्रदान गरिएको छ?', E'कृष्ण प्रधान', E'हरिप्रसाद शर्मा', E'विवश पोखरेल', E'आङ छिरिङ शेर्पा', 'A', E'**भैरव पुरस्कार, २०८२ कृष्ण प्रधानलाई प्रदान गरिएको छ।**\n- हरिप्रसाद शर्मालाई भैरव वाङ्मय पुरस्कार, २०८२ प्रदान गरिएको थियो।\n- विवश पोखरेललाई भैरव प्रतिभा पुरस्कार, २०८२ प्रदान गरिएको थियो।\n- आङ छिरिङ शेर्पालाई मदन भण्डारी पुरस्कार, २०८२ प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 5, E'जगदम्बा श्री पुरस्कार सर्वप्रथम कसलाई प्रदान गरिएको थियो?', E'सत्यमोहन जोशी', E'चित्तरञ्जन नेपाली', E'भूपि सेरचन', E'नारायण गोपाल', 'D', E'जगदम्बा श्री पुरस्कार सर्वप्रथम **नारायण गोपाल**लाई प्रदान गरिएको थियो।\nनोट: जगदम्बा श्री पुरस्कारको स्थापना वि.सं. २०१५ मा भएको थियो र हाल यसको राशी ४ लाख रुपैयाँ रहेको छ।', 'nepali'),
      (v_set_id, 6, E'मुलुककै पहिलो लाइओभर ग्वार्को लाइओभरको उद्घाटन कहिले भएको हो?', E'२०८२ असार ३', E'२०८२ असार ५', E'२०८२ असार ६', E'२०८२ असार ८', 'C', E'मुलुककै पहिलो, ग्वार्कोस्थित लाइओभरको उद्घाटन **वि.सं. २०८२ असार ६** गते भएको हो।\nनोट: यसको निर्माणका लागि वि.सं. २०७८ फागुन १२ गते सम्झौता भएको थियो।', 'nepali'),
      (v_set_id, 7, E'नेपालमा पहिलोपटक सफलतापूर्वक मृगौला प्रत्यारोपण कहिले गरियो?', E'वि.सं. २०५५', E'वि.सं. २०५६', E'वि.सं. २०५७', E'वि.सं. २०५८', 'D', E'नेपालमा पहिलोपटक सफलतापूर्वक मृगौला प्रत्यारोपण **वि.सं. २०५८** सालमा गरिएको थियो।\nनोट: यो प्रत्यारोपण २०५८ श्रावण २४ गते त्रिभुवन विश्वविद्यालय शिक्षण अस्पताल, महाराजगञ्जमा सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपालको संविधानको कुन धारामा राष्ट्रिय गान र अन्य राष्ट्रिय चिन्हको व्यवस्था रहेको छ?', E'धारा ७', E'धारा ८', E'धारा ९', E'धारा १०', 'C', E'**नेपालको संविधानको धारा ९ मा राष्ट्रिय गान र अन्य राष्ट्रिय चिन्हहरूको व्यवस्था गरिएको छ।**\n- धारा ७ मा सरकारी कामकाजको भाषा सम्बन्धी व्यवस्था छ।\n- धारा ८ मा नेपालको राष्ट्रिय झण्डा सम्बन्धी व्यवस्था छ।\n- धारा १० मा नागरिकताबाट वञ्चित नगरिने सम्बन्धी व्यवस्था छ।\nनोट: धारा ९ अनुसार नेपालको राष्ट्रिय गान अनुसूची-२ मा र निशान छाप अनुसूची-३ मा उल्लेख भए बमोजिम हुने व्यवस्था छ।', 'nepali'),
      (v_set_id, 9, E'चन्द्रमा पहिलो मानव कदम देहायका मध्ये कुन मितिमा परेको थियो?', E'1961 april 12', E'1969 july 20', E'1963 june 16', E'1965 april 12', 'B', E'**चन्द्रमामा पहिलो मानव कदम सन् १९६९ जुलाई २० मा परेको थियो।**\n- सन् १९६१ अप्रिल १२ मा युरी गागरिन भोस्तोक १ यानबाट अन्तरिक्षमा पुग्ने पहिलो व्यक्ति बनेका थिए।\n- सन् १९६३ जुन १६ मा भ्यालेन्टिना तेरेस्कोभा अन्तरिक्षमा जाने पहिलो महिला बनेकी थिइन्।\n- सन् १९६५ अप्रिल १२ को मिति अन्तरिक्ष अन्वेषणको कुनै प्रमुख घटनासँग सम्बन्धित छैन।\nनोट: एपोलो ११ मिसन अन्तर्गत अमेरिकी अन्तरिक्षयात्री निल आर्मस्ट्रङले चन्द्रमामा पहिलो पाइला टेकेका थिए।', 'nepali'),
      (v_set_id, 10, E'नेपाललाई ७७ जिल्लामा विभाजन गर्दा नेपालका तत्कालिन प्रधानमन्त्री को थिए?', E'शेर ब. देउवा', E'पुष्प क. दाहाल', E'केपी शर्मा वलि', E'सुशील कोइराला', 'A', E'नेपाललाई ७७ जिल्लामा विभाजन गर्दा तत्कालिन प्रधानमन्त्री **शेरबहादुर देउवा** थिए।\n- पुष्पकमल दाहाल ''प्रचण्ड''को प्रधानमन्त्रित्व कालमा स्थानीय तहको पुनर्संरचना भएको थियो।\n- केपी शर्मा ओलीको प्रधानमन्त्रित्व कालमा नेपालको नयाँ राजनीतिक नक्सा (चुच्चे नक्सा) जारी भएको थियो।\n- सुशील कोइरालाको प्रधानमन्त्रित्व कालमा २०७२ असोज ३ गते नेपालको संविधान जारी भई ७ प्रदेश कायम भएको थियो।\nनोट: शेरबहादुर देउवा सरकारको निर्णय अनुसार २०७४ भदौ ५ गते नवलपरासी र रुकुमलाई विभाजन गरी ७७ जिल्ला कायम गरिएको हो।', 'nepali'),
      (v_set_id, 11, E'विश्वको इतिहासमा पहिलो राजनीतिक क्रान्ति भनेर कुन क्रान्तीलाई चिनिन्छ?', E'औद्योगिक क्रान्ती', E'गौरवमय क्रान्ती', E'फ्रान्सेली क्रान्ति', E'रुसी क्रान्ति', 'B', E'विश्वको इतिहासमा पहिलो राजनीतिक क्रान्ति भनेर बेलायतको **गौरवमय क्रान्तिलाई** चिनिन्छ।\n- औद्योगिक क्रान्तिले उत्पादन प्रणालीमा ठूलो परिवर्तन ल्याएको थियो र यो बेलायतबाट सुरु भएको थियो।\n- फ्रान्सेली क्रान्ति सन् १७८९ मा सुरु भएको थियो र यसले समानता, स्वतन्त्रता र भातृत्वको नारा दिएको थियो।\n- रुसी क्रान्ति सन् १९१७ मा भएको थियो, जसले जार शासनको अन्त्य गरी साम्यवादी शासन स्थापना गर्‍यो।\nनोट: गौरवमय क्रान्तिलाई रक्तविहीन क्रान्ति (Bloodless Revolution) वा ''Glorious Revolution of 1688'' पनि भनिन्छ, किनकि यसमा रक्तपात बिना नै सत्ता परिवर्तन भएको थियो।', 'nepali'),
      (v_set_id, 12, E'लिच्छविकालिन समयमा आपणकर कसमा लाग्ने करलाई भनिन्थ्यो?', E'पसलमा', E'पलाण्डु', E'सुँगुरमा', E'फर्निचरमा', 'A', E'लिच्छविकालमा **पसलमा** लाग्ने करलाई आपणकर भनिन्थ्यो।\n- प्याजमा लाग्ने करलाई पलाण्डु भनिन्थ्यो।\n- सुँगुरमा लाग्ने करलाई सुकरकर भनिन्थ्यो।\n- फर्निचरमा लाग्ने करलाई सिंकर भनिन्थ्यो।', 'nepali'),
      (v_set_id, 13, E'सिमसार दिवस कहिले मनाइन्छ?', E'जनवरी २', E'फेब्रुअरी २', E'मार्च २', E'अप्रिल २', 'B', E'विश्व सिमसार दिवस हरेक वर्ष **फेब्रुअरी २** मा मनाइन्छ।\nनोट: सन् १९७१ फेब्रुअरी २ मा इरानको रामसार शहरमा ''रामसार महासन्धि''मा हस्ताक्षर भएको दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 14, E'सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गर्ने राष्ट्र देहायको कुन हैन?', E'अस्ट्रिया', E'नेपाल', E'इटाली', E'कोलम्बिया', 'D', E'**कोलम्बिया** सन् १९५५ डिसेम्बर १४ मा संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गर्ने राष्ट्रहरू मध्ये पर्दैन।\n- नेपाल, अस्ट्रिया, र इटाली लगायत १६ राष्ट्रहरूले सन् १९५५ डिसेम्बर १४ मा एकैसाथ संयुक्त राष्ट्रसंघको सदस्यता प्राप्त गरेका थिए।\nनोट: कोलम्बिया संयुक्त राष्ट्रसंघको संस्थापक सदस्य राष्ट्र हो, जसले सन् १९४५ अक्टोबर २४ मा सदस्यता लिएको थियो।', 'nepali'),
      (v_set_id, 15, E'पहिलो सार्क शिखर सम्मेलनमा नेपालको तर्फबाट भाग लिने राजा को हुन?', E'राजा त्रिभुवन', E'राजा वीरेन्द्र', E'राजा महेन्द्र', E'राजा ज्ञानेन्द्र', 'B', E'पहिलो सार्क शिखर सम्मेलनमा नेपालको तर्फबाट **राजा वीरेन्द्रले** भाग लिनुभएको थियो।\n- राजा त्रिभुवन र राजा महेन्द्रको सार्क स्थापना हुनुभन्दा पहिले नै निधन भइसकेको थियो।\n- राजा ज्ञानेन्द्रले आफ्नो शासनकालमा पछिका सार्क शिखर सम्मेलनहरूमा भाग लिनुभएको थियो।\nनोट: पहिलो सार्क शिखर सम्मेलन सन् १९८५ डिसेम्बर ७-८ मा बंगलादेशको ढाकामा सम्पन्न भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/०७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_09.csv  →  आसमान दैनिक GK — २०८२/१०/०९  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/०९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/०९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/०९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'जंग बहादुर राणा युरोप भ्रमण गएको बेला कार्यवाहक प्रधानमन्त्री हुने राणा प्रधानमन्त्री को हुन ?', E'चन्द्र सम्सेर', E'रणोदिप सिंह', E'वीर सम्सेर', E'बम बहादुर राणा', 'D', E'जंग बहादुर राणा (वीरनसिंह कुँवर) १९०६-१९०७ मा युरोप भ्रमणमा गएको बेला कार्यवाहक प्रधानमन्त्रीका रुपमा **बम बहादुर राणा** प्रधानमन्त्री भएका थिए।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधानको कुन धारामा बजेट तर्जुमा सम्बन्धि व्यवस्था रहेको छ ?', E'धारा १११', E'धारा ११७', E'धारा ११५', E'धारा ११३', 'A', E'नेपालको संविधानको भाग १० (संघीय आर्थिक कार्यप्रणाली) अन्तर्गत **धारा १११** मा राजस्व र व्ययको अनुमान (बजेट) सम्बन्धी व्यवस्था गरिएको छ।\nनोट: यस धारा अनुसार, नेपाल सरकारको अर्थमन्त्रीले प्रत्येक वर्ष जेठ महिनाको पन्ध्र गते संघीय संसदमा बजेट पेश गर्नुपर्छ।', 'nepali'),
      (v_set_id, 3, E'बेलायत, अमेरिका र भारत पछि नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो मुलुक कुन हो?', E'चीन', E'फ्रान्स', E'रुस', E'जापान', 'B', E'बेलायत, अमेरिका र भारतपछि नेपालसँग दौत्य सम्बन्ध कायम गर्ने चौथो मुलुक **फ्रान्स** हो।\n- नेपालसँग दौत्य सम्बन्ध कायम गर्ने पहिलो मुलुक बेलायत, दोस्रो अमेरिका र तेस्रो भारत हुन्।\n- चीन नेपालसँग दौत्य सम्बन्ध कायम गर्ने पाँचौ मुलुक हो।', 'nepali'),
      (v_set_id, 4, E'दोलखामा अवस्थित नेपालको चर्चित हिमाल गौरिशंकर हिमालको उचाइ कति रहेको छ?', E'७१३४ मिटर', E'७१३१ मिटर', E'७१३७ मिटर', E'७२३३ मिटर', 'A', E'दोलखा जिल्लामा अवस्थित गौरिशंकर हिमालको उचाइ **७,१३४ मिटर** रहेको छ। यही हिमाललाई काटेर गएको ८६ डिग्री १५ मिनेट पूर्वी देशान्तरलाई आधार मानेर नेपालको प्रमाणिक समय निर्धारण गरिएको हो।\nनोट: नेपालको प्रमाणिक समय वि.सं. २०४२ साल वैशाख १ गतेबाट लागू भएको हो र यो ग्रीनवीचको समयभन्दा ५ घण्टा ४५ मिनेट छिटो छ।', 'nepali'),
      (v_set_id, 5, E'देहायको मध्ये कुन प्रकारको माटो मुख्यतः काठमाडौं उपत्यकामा पाइन्छ ?', E'बलौटे माटो', E'तलैया माटो', E'पाँगो माटो', E'रातो फुस्रो माटो', 'B', E'काठमाडौं उपत्यकामा मुख्यतया **तलैया माटो** पाइन्छ।\n- बलौटे पथरिलो माटो भावर प्रदेश, भित्री मधेश र चुरे पहाडमा पाइन्छ।\n- रातो फुस्रो माटो महाभारतका ठाडा भिरहरूमा पाइन्छ।', 'nepali'),
      (v_set_id, 6, E'सार्क राष्ट्रका देशहरु मध्ये नेपालको समय भन्दा चाँडो समय भएका २ देशहरु कुन कुन हुन् ?', E'भारत र भुटान', E'बंगलादेश र भुटान', E'बंगलादेश र भारत', E'पाकिस्तान र भुटान', 'B', E'सार्क राष्ट्रहरूमध्ये **बंगलादेश र भुटानको** समय नेपालको भन्दा १५ मिनेट चाँडो छ।\n- भारत र श्रीलंकाको समय नेपालको भन्दा १५ मिनेट पछाडि छ।\n- पाकिस्तान र माल्दिभ्सको समय नेपालको भन्दा ४५ मिनेट पछाडि छ।\n- अफगानिस्तानको समय नेपालको भन्दा १ घण्टा १५ मिनेट पछाडि छ।', 'nepali'),
      (v_set_id, 7, E'नेपाललाई प्राविधिक सहयोग गर्ने पहिलो मुलुक कुन हो?', E'भारत', E'जापान', E'बेलायत', E'अमेरिका', 'C', E'नेपाललाई प्राविधिक सहयोग गर्ने पहिलो मुलुक **बेलायत** हो।\n- अमेरिका नेपाललाई पहिलो आर्थिक सहयोग गर्ने मुलुक हो।\n- जापान नेपाललाई सबैभन्दा धेरै सहयोग गर्ने मुलुक हो।', 'nepali'),
      (v_set_id, 8, E'लिम्बु जातिको पुरोहित लाई "फेदाङमा" र साम्बा भनिन्छ भने कुन जातिको पुरोहित लाई "घ्याब्रे ब्राह्मण" भनिन्छ ?', E'चेपाङ', E'मगर', E'तामाङ', E'गुरुङ', 'D', E'गुरुङ जातिको पुरोहितलाई **"घ्याब्रे ब्राह्मण"** भनिन्छ।\n- चेपाङ जातिको पुरोहितलाई पाँडे भनिन्छ।\n- मगर जातिको पुरोहितलाई भुषाल भनिन्छ।\n- तामाङ जातिको पुरोहितलाई लामा भनिन्छ।\nनोट: लिम्बु जातिको पुरोहितलाई फेदाङमा र साम्बा भनिन्छ।', 'nepali'),
      (v_set_id, 9, E'सुगौली सन्धि हुनु पूर्व नेपालको क्षेत्रफल कति थियो ?', E'२०४९१७ वर्ग कि.मि', E'२०२९१७ वर्ग कि.कि', E'२०६९१७ वर्ग कि.मि', E'२०७९१७ वर्ग कि.मि', 'A', E'सुगौली सन्धि हुनुभन्दा पहिले नेपालको क्षेत्रफल **२०४,९१७ वर्ग कि.मि.** थियो। यो सन्धि सन् १८१६ मार्च ३ मा नेपाल र तत्कालीन ब्रिटिश इस्ट इन्डिया कम्पनीबीच भएको थियो, जसले नेपालको सिमानालाई मेचीदेखि महाकालीसम्म सीमित गर्‍यो।', 'nepali'),
      (v_set_id, 10, E'नेपालको सबैभन्दा नजिकमा रहेको सार्क राष्ट्र राजधानी कुन देशको हो ?', E'अफगानिस्तान', E'भारत', E'बंगलादेश', E'भुटान', 'D', E'नेपालको सबैभन्दा नजिकमा रहेको सार्क राष्ट्रको राजधानी **भुटानको थिम्पु** हो।\n- भारत नेपालको छिमेकी राष्ट्र भए तापनि यसको राजधानी नयाँ दिल्ली थिम्पुभन्दा टाढा पर्दछ।\n- बंगलादेश नेपालबाट करिब २७ कि.मि. को दूरीमा रहेको नजिकको देश हो, तर यसको राजधानी ढाका थिम्पुभन्दा टाढा छ।\n- अफगानिस्तानको राजधानी काबुल अन्य विकल्पहरूभन्दा टाढा रहेको छ।\nनोट: नेपालबाट भुटानको राजधानी थिम्पुको हवाई दूरी करिब ४०० कि.मि. छ।', 'nepali'),
      (v_set_id, 11, E'डुंगुवा प्रथा विशेषत कुन जाति विशेष सँग सम्बन्धित छ ?', E'सतार', E'राजवंशी', E'चेपाङ', E'थारु', 'B', E'डुंगुवा प्रथा विशेषतः **राजवंशी** जातिसँग सम्बन्धित छ।\n- सतार, चेपाङ र थारु जातिहरूका आ-आफ्नै विशिष्ट सामाजिक तथा सांस्कृतिक प्रथाहरू छन्।\nनोट: यो प्रथा अन्तर्गत पूर्वी नेपालका राजवंशी समुदायमा विधवा महिलाले नाता नपर्ने पुरुषलाई पतिको रूपमा स्वीकार्ने चलन छ।', 'nepali'),
      (v_set_id, 12, E'बालाजुको २२ औं धारा निर्माण गर्ने राजा को हुन् ?', E'रण ब. शाह', E'योगनरेन्द्र मल्ल', E'जयप्रकाश मल्ल', E'जयस्थिति मल्ल', 'A', E'बालाजुको २२ औं धारा निर्माण गर्ने राजा **रण ब. शाह** हुन्।\n- योगनरेन्द्र मल्ल पाटनका राजा थिए।\n- जयप्रकाश मल्लले बालाजुका २१ वटा धारा निर्माण गराएका थिए, जसमा रण बहादुर शाहले एक धारा थपेर २२ पुऱ्याएका हुन्।\n- जयस्थिति मल्लले सामाजिक तथा कानुनी सुधारका लागि महत्वपूर्ण कार्य गरेका थिए।', 'nepali'),
      (v_set_id, 13, E'विश्व इतिहासमा कुन देशमा भएको आक्रमण पश्चात पहिलो विश्व युद्ध सुरु भएको थियो ?', E'पोल्याण्ड', E'जर्मनी', E'सर्विया', E'अष्ट्रिया', 'C', E'अष्ट्रियाले **सर्विया** विरुद्ध आक्रमण गरे सँगै प्रथम विश्व युद्ध सुरु भएको थियो।\n- जर्मनीले पोल्याण्ड विरुद्ध आक्रमण गरे सँगै द्वितीय विश्व युद्ध सुरु भएको थियो।\n- जर्मनी दुवै विश्वयुद्धमा एक प्रमुख शक्ति राष्ट्र थियो।\n- अष्ट्रिया प्रथम विश्वयुद्ध सुरु गर्ने आक्रमणकारी राष्ट्र थियो।', 'nepali'),
      (v_set_id, 14, E'हरेक वर्ष मंसिर १ मा मनाउँदै आइरहेको कफि दिवस कुन सालबाट मनाउन सुरु गरिएको हो ?', E'वि.सं. २०६२', E'वि.सं. २०५३', E'वि.सं. २०५४', E'वि.सं. २०६१', 'A', E'हरेक वर्ष मंसिर १ मा मनाइने कफी दिवस **वि.सं. २०६२** देखि मनाउन थालिएको हो।\n- वि.सं. २०५४ देखि वैशाख १५ मा राष्ट्रिय चिया दिवस मनाउन थालिएको हो।\n- वि.सं. २०६१ देखि असार १५ मा राष्ट्रिय धान दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 15, E'राष्ट्रिय जनगणना, २०७८ अनुसार धेरै जनसंख्या वृद्धिदर भएको प्रदेश कुन हो ?', E'लुम्बिनी', E'बागमती', E'मधेस', E'गण्डकी', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा धेरै जनसंख्या वृद्धिदर भएको प्रदेश **लुम्बिनी** हो।\n- बागमती प्रदेश सबैभन्दा धेरै जनसंख्या भएको प्रदेश हो।\n- गण्डकी प्रदेश सबैभन्दा कम जनसंख्या वृद्धिदर भएको प्रदेश हो।\nनोट: राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनसंख्या भएको प्रदेश कर्णाली हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/०९', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_11.csv  →  आसमान दैनिक GK — २०८२/१०/११  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/११'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/११';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/११', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'शेराबस्ती अवस्थित नेपाली जिल्ला कुन हो ?', E'जुम्ला', E'हुम्ला', E'डोल्पा', E'सोलुखुम्बु', 'B', E'नेपाल-चीन सीमा नजिकको बस्ती **शेराबस्ती हुम्ला जिल्लामा अवस्थित छ।**\nनोट: नेपाल र चीनलाई जोड्ने मितेरी पुल पनि यही क्षेत्रमा पर्दछ।', 'nepali'),
      (v_set_id, 2, E'हरित सहर भनी हेटौंडालाई चिनिन्छ भने सेलिक सहर भनी कुनलाई चिनिन्छ ?', E'देवचुली', E'वालिङ', E'मटिहानी', E'धनकुटा', 'D', E'**सेलिक सहर भनेर धनकुटालाई चिनिन्छ।**\n- देवचुलीलाई बालमैत्री स्थानीय शासन नगर भनेर चिनिन्छ।\n- वालिङलाई गुलाबी सहर भनेर चिनिन्छ।\n- मटिहानीलाई फ्रि वाईफाई नगर भनेर चिनिन्छ।\nनोट: प्रश्नमा उल्लेख भए अनुसार, हेटौंडालाई हरित सहर (Green City) को उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 3, E'पाँच पटक प्रधानमन्त्री बनेका प्रधानमन्त्री देहायका को होइनन् ?', E'गिरिजाप्र. कोइराला', E'शेर बहादुर देउवा', E'लोकेन्द्र बहादुर चन्द', E'सूर्यबहादुर थापा', 'C', E'देहायका मध्ये **लोकेन्द्र बहादुर चन्द** पाँच पटक प्रधानमन्त्री बनेका होइनन्، उनी चार पटक मात्र प्रधानमन्त्री बनेका थिए।\n- गिरिजाप्रसाद कोइराला पाँच पटक प्रधानमन्त्री बनेका थिए।\n- शेर बहादुर देउवा पाँच पटक प्रधानमन्त्री बनेका थिए।\n- सूर्यबहादुर थापा पनि पाँच पटक प्रधानमन्त्री बनेका थिए।\nनोट: केपी शर्मा ओली पनि लोकेन्द्र बहादुर चन्द जस्तै चार पटक प्रधानमन्त्री बनेका छन्।', 'nepali'),
      (v_set_id, 4, E'नेपालले स्विट्जरल्याण्डसँग द्विपक्षीय हवाई सम्झौता कहिले गर्यो?', E'२०२४ फेब्रुअरी ८', E'२०२४ फेब्रुअरी ६', E'२०२३ डिसेम्बर ५', E'२०२३ डिसेम्बर ९', 'B', E'नेपालले स्विट्जरल्याण्डसँग **२०२४ फेब्रुअरी ६** मा द्विपक्षीय हवाई सम्झौता गरेको थियो। यो सम्झौतासँगै स्विट्जरल्याण्ड नेपालसँग हवाई सम्झौता गर्ने ४२औं मुलुक बनेको छ।\nनोट: यसअघि ४१औं मुलुकको रूपमा नेपालले रुवान्डासँग २०२३ डिसेम्बर ५ मा हवाई सम्झौता गरेको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपालको संविधानको कुन धारामा धार्मिक स्वतन्त्रताको हक सम्बन्धित व्यवस्था गरेको छ ?', E'धारा २६', E'धारा २१', E'धारा ३२', E'धारा ३३', 'A', E'नेपालको संविधानको **धारा २६** मा धार्मिक स्वतन्त्रताको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा २१ मा अपराध पीडितको हकको व्यवस्था छ।\n- धारा ३२ मा भाषा तथा संस्कृतिको हकको व्यवस्था छ।\n- धारा ३३ मा रोजगारीको हकको व्यवस्था छ।', 'nepali'),
      (v_set_id, 6, E'हाल सबैभन्दा बढी नाफामा रहेका संस्थान कुन हो?', E'निक्षेप तथा कर्जा लगानी कोष', E'नेपाल आयल निगम', E'नेपाल विद्युत प्राधिकरण', E'नेपाल दूरसञ्चार कम्पनी लि.', 'C', E'हाल **नेपाल विद्युत प्राधिकरण** सबैभन्दा बढी नाफामा रहेको संस्थान हो। सार्वजनिक संस्थानहरूको वार्षिक स्थिति समीक्षा, २०८० अनुसार शीर्ष नाफामा रहेका संस्थाहरू निम्न छन्:\n- १. नेपाल विद्युत प्राधिकरण\n- २. नेपाल आयल निगम\n- ३. नेपाल दूरसञ्चार कम्पनी लि.\n- ४. निक्षेप तथा कर्जा लगानी कोष', 'nepali'),
      (v_set_id, 7, E'रणबहादुर शाहको नायवि शासन आमा राजेन्द्र लक्ष्मी शाहले कति वर्ष चलाइन् ?', E'८ वर्ष', E'१० वर्ष', E'१२ वर्ष', E'१४ वर्ष', 'A', E'रणबहादुर शाहको नायवि शासन उनकी आमा राजेन्द्र लक्ष्मीले **८ वर्ष** (वि.सं. १८४४ - १८५२) चलाएकी थिइन्।\nनोट: रणबहादुर शाहका अंकल बहादुर शाहले वि.सं. १८४२ देखि १८५४ सम्म नायवि शासन चलाएका थिए।', 'nepali'),
      (v_set_id, 8, E'रामायण अनुसार रामको आमा को थिइन्?', E'कौशल्या', E'कैकयी', E'सुमित्रा', E'सिता', 'A', E'रामायण अनुसार रामकी आमा **कौशल्या** थिइन्।\n- कैकयी भरतकी आमा थिइन्।\n- सुमित्रा लक्ष्मण र शत्रुधनकी आमा थिइन्।\n- सिता रामकी श्रीमती थिइन्।', 'nepali'),
      (v_set_id, 9, E'इन्द्रजात्रा कुन तिथिमा मनाइने गर्दछ?', E'भाद्र कृष्ण औंसी', E'भाद्र शुक्ल चतुर्दशी', E'आश्विन शुक्ल प्रतिपदा', E'आश्विन शुक्ल सप्तमी', 'B', E'इन्द्रजात्रा **भाद्र शुक्ल चतुर्दशी** तिथिमा मनाइने गर्दछ।\n- भाद्र कृष्ण औंसीमा कुश औंसी (बुबाको मुख हेर्ने दिन) मनाइन्छ।\n- आश्विन शुक्ल प्रतिपदामा घटस्थापना गरिन्छ।\n- आश्विन शुक्ल सप्तमीमा फूलपाती (महासप्तमी) मनाइन्छ।', 'nepali'),
      (v_set_id, 10, E'फरक गुण भएका बुवाआमा बाट प्रजनन भइ पहिलो बंशमा देखा परेका गुणलाई के भनिन्छ ?', E'प्रबल गुण', E'लुप्त गुण', E'परिवर्तन गुण', E'बंशाणुगत गुण', 'A', E'फरक गुण भएका अभिभावकबाट प्रजनन हुँदा पहिलो वंशमा देखिने गुणलाई **प्रबल गुण (Dominant Trait)** भनिन्छ। मेण्डेलको वंशाणुगत नियमअनुसार, पहिलो पुस्तामा एक गुण देखिन्छ भने अर्को गुण लुकेर बसेको हुन्छ, जसलाई लुप्त गुण (Recessive Trait) भनिन्छ।', 'nepali'),
      (v_set_id, 11, E'ग्यालिलियो ग्यालिली कहाँको वैज्ञानिक हुन् ?', E'अमेरिका', E'जर्मनी', E'इटाली', E'बेलायत', 'C', E'**ग्यालिलियो ग्यालिली इटालीका वैज्ञानिक थिए।**\n- अमेरिकाका प्रसिद्ध वैज्ञानिकहरूमा थोमस एडिसन पर्दछन्।\n- जर्मनीका प्रसिद्ध वैज्ञानिक अल्बर्ट आइन्स्टाइन हुन्।\n- बेलायतका प्रसिद्ध वैज्ञानिक आइज्याक न्यूटन हुन्।\nनोट: ग्यालिलियोको जन्म १५६४ फेब्रुअरी १५ मा इटालीको पिसामा भएको थियो।', 'nepali'),
      (v_set_id, 12, E'Eco tourism को अवधारणा कुन योजनाबाट सुरु भएको थियो ?', E'आठौं योजना', E'सातौं योजना', E'छैटौं योजना', E'पाँचौं योजना', 'C', E'**Eco tourism (पर्या-पर्यटन) को अवधारणा छैटौं योजनाबाट सुरु भएको थियो।**\n- आठौं योजनाले दिगो विकासको अवधारणा सुरु गरेको थियो।\n- सातौं योजनाले वातावरणीय प्रभाव मूल्याङ्कन (EIA) सुरु गरेको थियो।\n- पाँचौं योजनाले स्वास्थ्य कार्यक्रमलाई समावेश गरेको थियो।\nनोट: छैटौं योजना (२०४२-२०४७) ले पहिलो पटक वातावरण नीति ल्याएको थियो, जसले पर्या-पर्यटनको आधार तयार गर्यो।', 'nepali'),
      (v_set_id, 13, E'देहायका मध्ये कुन जिल्ला साक्षर जिल्ला घोषणा हुन बाँकि रहेको छ ?', E'हुम्ला', E'डोल्पा', E'कालिकोट', E'दार्चुला', 'B', E'नेपालमा साक्षर जिल्ला घोषणा हुन बाँकी रहेको एक मात्र जिल्ला **डोल्पा** हो। कर्णाली प्रदेशका १० जिल्लामध्ये हुम्ला र कालिकोट लगायत ९ जिल्ला साक्षर घोषित भइसकेका छन्, तर डोल्पा बाँकी छ।\nनोट: हालसम्म कुनै पनि जिल्ला साक्षर घोषणा नभएको एक मात्र प्रदेश मधेश प्रदेश हो।', 'nepali'),
      (v_set_id, 14, E'पृथ्वी सम्मेलनले पारित गरेको ४ विषयमा देहायको कुन पर्दैन ?', E'एजेण्डा-२१', E'दिगो विकास', E'जैविक विविधता', E'जलवायु परिवर्तन', 'B', E'**पृथ्वी सम्मेलनले पारित गरेका ४ मुख्य विषयमा दिगो विकास पर्दैन।**\n- एजेण्डा-२१ पृथ्वी सम्मेलनद्वारा पारित एक महत्त्वपूर्ण कार्ययोजना हो।\n- जैविक विविधता महासन्धि (Convention on Biological Diversity) पनि यसै सम्मेलनबाट पारित भएको थियो।\n- जलवायु परिवर्तन सम्बन्धी संयुक्त राष्ट्र संघीय संरचना महासन्धि (UNFCCC) पनि यसै सम्मेलनको परिणाम हो।\nनोट: पृथ्वी सम्मेलनले पारित गरेका ४ विषयहरू जैविक विविधता, मौसम परिवर्तन, एजेण्डा-२१ र वन संरक्षण सम्बन्धी सिद्धान्त हुन्।', 'nepali'),
      (v_set_id, 15, E'संयुक्त राष्ट्रसंघको बढी शक्तिशाली अंग कुन हो ?', E'महासभा', E'जिम्मा जमानी परिषद्', E'सुरक्षा परिषद्', E'अन्तर्राष्ट्रिय न्यायालय', 'C', E'**संयुक्त राष्ट्रसंघको सबैभन्दा शक्तिशाली अंग सुरक्षा परिषद् हो।**\n- महासभा (General Assembly) संयुक्त राष्ट्रसंघको मुख्य विचार-विमर्श गर्ने अंग हो, जसमा सबै सदस्य राष्ट्रहरूको समान प्रतिनिधित्व हुन्छ।\n- जिम्मा जमानी परिषद् (Trusteeship Council) ले उपनिवेशहरूको स्वतन्त्रता र स्वशासनको लागि काम गर्थ्यो र हाल यो निष्क्रिय छ।\n- अन्तर्राष्ट्रिय न्यायालय (International Court of Justice) संयुक्त राष्ट्रसंघको प्रमुख न्यायिक अंग हो, जसले राष्ट्रहरू बीचको कानुनी विवाद समाधान गर्दछ।\nनोट: सुरक्षा परिषद्ले अन्तर्राष्ट्रिय शान्ति र सुरक्षा कायम गर्ने, शान्ति सेना परिचालन गर्ने र सदस्य राष्ट्रहरूमाथि बाध्यकारी निर्णयहरू लागू गर्ने अधिकार राख्दछ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/११', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_12.csv  →  आसमान दैनिक GK — २०८२/१०/१२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/१२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/१२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/१२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'स्थानीय तहहरूको प्रशासनिक वर्गीकरण अन्तर्गत सुगम स्थानीय तह कति रहेका छन् ?', E'९९ वटा', E'९८ वटा', E'९७ वटा', E'९६ वटा', 'B', E'स्थानीय तहहरूको प्रशासनिक वर्गीकरण अनुसार नेपालमा जम्मा **९८ वटा** सुगम स्थानीय तह रहेका छन्।\nनोट: वर्गीकरण अनुसार अतिदुर्गममा १६२, दुर्गममा २१८, र मध्यममा २७५ स्थानीय तहहरू छन्।', 'nepali'),
      (v_set_id, 2, E'१ मात्र नगरपालिका भएको ८ जिल्लाको सूचीमा देहायको कुन जिल्ला पर्दैन ?', E'मुगु', E'जुम्ला', E'रोल्पा', E'डोल्पा', 'D', E'**डोल्पा** जिल्ला १ मात्र नगरपालिका भएको जिल्लाको सूचीमा पर्दैन।\n- मुगु, जुम्ला र रोल्पा १ मात्र नगरपालिका भएका जिल्लाहरू हुन्।\nनोट: १ मात्र नगरपालिका भएका ८ जिल्लाहरू ओखलढुंगा, म्याग्दी, मुगु, जुम्ला, रोल्पा, ताप्लेजुङ, सोलुखुम्बु र पाँचथर हुन्।', 'nepali'),
      (v_set_id, 3, E'जनताको छोराको रूपमा पहिलो प्रधानमन्त्री हुने व्यक्ति को हुन् ?', E'टंकप्रसाद आचार्य', E'मातृकाप्र. कोइराला', E'डा. केआई सिंह', E'वि पि कोइराला', 'B', E'**मातृकाप्रसाद कोइराला** ''जनताको छोरा'' को रूपमा चिनिने पहिलो प्रधानमन्त्री हुन्।\n- टंकप्रसाद आचार्यलाई ''जिउँदो शहीद'' भनेर चिनिन्छ र उनी पनि नेपालका प्रधानमन्त्री बनेका थिए।\n- डा. केआई सिंह पनि नेपालका प्रधानमन्त्री थिए, जो क्रान्तिकारी नेताको रूपमा परिचित छन्।\n- वि पि कोइराला नेपालका प्रथम जननिर्वाचित प्रधानमन्त्री हुन्।\nनोट: नेपालमा सर्वप्रथम बजेट पेश गर्ने प्रधानमन्त्री पनि मातृकाप्रसाद कोइराला नै हुन्।', 'nepali'),
      (v_set_id, 4, E'नेपालको संविधान बमोजिम स्वच्छ वातावरणको हक कसलाई प्राप्त हुन्छ?', E'प्रत्येक व्यक्तिलाई', E'प्रत्येक नागरिकलाई', E'हरेक व्यक्तिलाई', E'सबै नागरिकलाई', 'B', E'नेपालको संविधानको धारा ३० मा स्वच्छ वातावरणको हक **प्रत्येक नागरिकलाई** हुने व्यवस्था गरिएको छ। यस हक अन्तर्गत प्रत्येक नागरिकलाई स्वच्छ र स्वस्थ वातावरणमा बाँच्न पाउने अधिकार हुन्छ।', 'nepali'),
      (v_set_id, 5, E'नेपालमा हाल सबैभन्दा बढी घाटामा रहेका संस्थान कुन हो?', E'नेपाल खानेपानी संस्थान', E'नेपाल टेलिभिजन', E'नेपाल वायुसेवा निगम', E'हेटौंडा सिमेन्ट उद्योग', 'C', E'**नेपाल वायुसेवा निगम हाल सबैभन्दा बढी घाटामा रहेको संस्थान हो।**\n- नेपाल खानेपानी संस्थान घाटामा रहेको दोस्रो ठूलो संस्थान हो।\n- हेटौंडा सिमेन्ट उद्योग घाटामा रहेको तेस्रो ठूलो संस्थान हो।\n- नेपाल टेलिभिजन (सार्वजनिक सेवा प्रसारण नेपाल) घाटामा रहेको पाँचौं ठूलो संस्थान हो।', 'nepali'),
      (v_set_id, 6, E'मानव विकास सुचकाङ्क, २०२४ मा विश्वको पहिलो स्थानमा कुन मुलुक रहेको छ ?', E'स्वीट्जरल्याण्ड', E'डेनमार्क', E'फिनल्याण्ड', E'आइसल्याण्ड', 'D', E'**मानव विकास सुचकाङ्क, २०२४ मा ०.९७२ अंकसहित आइसल्याण्ड पहिलो स्थानमा रहेको छ।**\n- स्वीट्जरल्याण्ड र नर्वे ०.९७० अंकसहित दोस्रो स्थानमा छन्।\n- डेनमार्क ०.९६२ अंकसहित तेस्रो स्थानमा रहेको छ।\n- फिनल्याण्ड शीर्ष स्थानमा छैन, चौथो स्थानमा जर्मनी र स्वीडेन रहेका छन्।', 'nepali'),
      (v_set_id, 7, E'नेपाल एकीकरणका नायक पृथ्वीनारायण शाहको मृत्यु कति वर्षको उमेरमा भएको थियो ?', E'५२ वर्ष', E'५० वर्ष', E'५४ वर्ष', E'५६ वर्ष', 'A', E'नेपाल एकीकरणका नायक पृथ्वीनारायण शाहको मृत्यु **५२ वर्षको** उमेरमा नुवाकोटमा भएको थियो।\nनोट: उनको जन्म वि.सं. १७७९ पौष २७ गते भएको थियो भने मृत्यु वि.सं. १८३१ माघ १ गते भएको थियो।', 'nepali'),
      (v_set_id, 8, E'भगवान गौतम बुद्धले दिएका उपदेश कुन पिटकमा समावेश गरिएका छन्?', E'उपदेश पिटक', E'विनय पिटक', E'अभिधम्म पिटक', E'शुक्ति पिटक', 'D', E'**भगवान गौतम बुद्धले दिएका उपदेशहरू शुक्ति पिटकमा समावेश गरिएका छन्।**\n- विनय पिटकमा बौद्ध भिक्षु एवं भिक्षुणीहरूले पालना गर्नुपर्ने नियमहरू समावेश छन्।\n- अभिधम्म पिटकमा बौद्ध दर्शनका कुराहरू समावेश गरिएका छन्।\n- उपदेश पिटक भन्ने त्रिपिटकको अंग होइन, त्रिपिटकका तीन अंगहरू शुक्ति, विनय र अभिधम्म पिटक हुन्।', 'nepali'),
      (v_set_id, 9, E'कोजाग्रत पूर्णिमा कुन महिनामा पर्ने पूर्णिमालाई बुझिन्छ?', E'भदौ', E'असोज', E'कात्तिक', E'मंसिर', 'B', E'**कोजाग्रत पूर्णिमा असोज महिनामा पर्ने पूर्णिमालाई बुझिन्छ।**\n- दशैं सकिने पूर्णिमाको रातलाई कोजाग्रत भनिन्छ, जुन आश्विन शुक्ल पूर्णिमाको दिन पर्दछ। यस दिन सम्पन्नताकी देवी महालक्ष्मीको पूजा आराधना गरी राति जाग्राम बसेपछि दशैं पर्व समापन हुन्छ।', 'nepali'),
      (v_set_id, 10, E'आउटपुट उपकरणको उदाहरण कुन हो?', E'जोइस्टिक', E'माइक्रोफोन', E'प्रिन्टर', E'माउस', 'C', E'कम्प्युटरबाट प्रशोधित जानकारीलाई बाहिर निकाल्ने वा प्रस्तुत गर्ने उपकरणहरूमध्ये **प्रिन्टर** एक आउटपुट उपकरण हो।\n- जोइस्टिक एक इनपुट उपकरण हो, जुन विशेष गरी भिडियो गेम खेल्न प्रयोग गरिन्छ।\n- माइक्रोफोन एक इनपुट उपकरण हो जसले ध्वनि (audio) लाई कम्प्युटरमा पठाउँछ।\n- माउस एक पोइन्टिङ इनपुट उपकरण हो जसले कम्प्युटरलाई निर्देशन दिन मद्दत गर्छ।\nनोट: मनिटर, स्पिकर, प्रोजेक्टर आदि पनि आउटपुट उपकरणका अन्य उदाहरणहरू हुन्।', 'nepali'),
      (v_set_id, 11, E'वायुउर्जाको लागि सम्भाव्य उपयुक्त नेपाली जिल्ला कुन हो ?', E'मुस्ताङ', E'सिन्धुपाल्चोक', E'मुस्ताङ', E'दैलेख', 'A', E'नेपालमा वायुउर्जा उत्पादनको लागि सबैभन्दा सम्भाव्य र उपयुक्त जिल्ला **मुस्ताङ** हो, जहाँ निरन्तर तीव्र गतिमा हावा बहन्छ।\n- सिन्धुपाल्चोक जिल्ला भू-तापीय ऊर्जा (Geothermal Energy) को लागि सम्भाव्य मानिन्छ।\n- दैलेख जिल्ला पेट्रोलियम पदार्थको अन्वेषण र उत्खननका लागि चर्चामा रहेको छ।\nनोट: वायु उर्जाबाट बिजुली निकाल्ने विश्वको पहिलो मुलुक डेनमार्क हो।', 'nepali'),
      (v_set_id, 12, E'नेपालको कति औं पञ्चवर्षीय योजनाबाट पहिलोपटक दिर्घकालिन सोच राख्न सुरु गरिएको थियो ?', E'सातौं योजनाबाट', E'नवौं योजनाबाट', E'दशौं योजनाबाट', E'आठौं योजनाबाट', 'B', E'नेपालमा **नवौं पञ्चवर्षीय योजना (२०५४-२०५९)** बाट पहिलोपटक दीर्घकालीन सोच राख्ने अवधारणाको सुरुवात भएको थियो।\n- सातौं पञ्चवर्षीय योजनाले वातावरणीय प्रभाव मूल्याङ्कन (EIA) को अवधारणा ल्याएको थियो।\n- दशौं पञ्चवर्षीय योजनाले सहस्राब्दी विकास लक्ष्य (MDGs) लाई आत्मसात गरेको थियो।\n- आठौं पञ्चवर्षीय योजनाबाट दिगो विकासको अवधारणा सुरु भएको थियो।\nनोट: नवौं योजनाको एकमात्र मूल उद्देश्य ''गरिबी निवारण'' तय गरिएको थियो र यसैबाट सामाजिक सुरक्षाको अवधारणा पनि सुरु भयो।', 'nepali'),
      (v_set_id, 13, E'पहिलो साक्षर प्रदेश घोषणा बागमतीलाई साक्षर प्रदेश घोषणा कहिले गरिएको हो ?', E'२०७८ असार ३१', E'२०७८ असोज २४', E'२०७९ भदौ २३', E'२०७८ असोज ११', 'D', E'बागमती प्रदेशलाई नेपालको पहिलो साक्षर प्रदेशको रूपमा **वि.सं. २०७८ असोज ११** मा घोषणा गरिएको थियो।\n- नेपालको पहिलो साक्षर जिल्ला सिन्धुपाल्चोक हो, जसलाई वि.सं. २०७१ असार २ मा घोषणा गरिएको थियो।\n- नेपालको पहिलो पूर्ण साक्षर जिल्ला ललितपुर हो, जसलाई वि.सं. २०७१ असार ९ मा घोषणा गरिएको थियो।\n- नेपालको पहिलो साक्षर नगरपालिका पाल्पाको तानसेन हो, जसलाई वि.सं. २०७० मंसिर २६ मा घोषणा गरिएको थियो।', 'nepali'),
      (v_set_id, 14, E'नेपालमा अवस्थित संरक्षण क्षेत्र मध्ये सबैभन्दा सानो संरक्षण क्षेत्र कुन हो ?', E'अन्नपूर्ण', E'रारा', E'अपि नाम्पा', E'कृष्णसार', 'D', E'**कृष्णसार संरक्षण क्षेत्र नेपालको सबैभन्दा सानो संरक्षण क्षेत्र हो।**\n- अन्नपूर्ण संरक्षण क्षेत्र नेपालको सबैभन्दा ठूलो संरक्षण क्षेत्र हो।\n- रारा राष्ट्रिय निकुञ्ज हो, संरक्षण क्षेत्र होइन। यो नेपालको सबैभन्दा सानो राष्ट्रिय निकुञ्ज हो।\n- अपि नाम्पा संरक्षण क्षेत्र दार्चुला जिल्लामा अवस्थित छ।\nनोट: कृष्णसार संरक्षण क्षेत्र २०६५ सालमा स्थापना भएको हो, जसको क्षेत्रफल १६.९५ वर्ग कि.मि. छ र यो बर्दिया जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 15, E'संयुक्त राष्ट्रसंघ सुरक्षा परिषदमा सबैभन्दा धेरै पटक अस्थायी सदस्य भएको मुलुक कुन हो ?', E'जापान', E'जर्मनी', E'वेलायत', E'फ्रान्स', 'A', E'**संयुक्त राष्ट्रसंघ सुरक्षा परिषदमा सबैभन्दा धेरै पटक अस्थायी सदस्य हुने मुलुक जापान हो।**\n- जर्मनी पनि पटक-पटक अस्थायी सदस्य भएको छ।\n- बेलायत र फ्रान्स सुरक्षा परिषदका स्थायी सदस्य राष्ट्र (P5) हुन्, त्यसैले यिनीहरू अस्थायी सदस्यको रूपमा निर्वाचित हुँदैनन्।\nनोट: जापान हालसम्म १२ पटक सुरक्षा परिषदको अस्थायी सदस्य भइसकेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/१२', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_13.csv  →  आसमान दैनिक GK — २०८२/१०/१३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/१३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/१३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/१३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको शैक्षिक इतिहासमा पहिलो पटक बाल दिवस मनाउन सुरु कहिले देखि भयो?', E'वि.सं. २०१२', E'वि.सं. २०१६', E'वि.सं. २०१७', E'वि.सं. २०२१', 'B', E'नेपालको शैक्षिक इतिहासमा पहिलो पटक **वि.सं. २०१६** देखि बाल दिवस मनाउन सुरु भएको हो।\n- वि.सं. २०१२ मा प्रौढ शिक्षाको सुरुवात भएको थियो।\n- वि.सं. २०१७ चैत ९ मा त्रिभुवन विश्वविद्यालयको पहिलो दीक्षान्त समारोह सम्पन्न भएको थियो।\n- वि.सं. २०२१ देखि विशेष शिक्षाको सुरुवात भएको हो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधान अनुसार सरकारी कामकाजको भाषा कुन हो?', E'नेवारी भाषा', E'देवनागरी भाषा', E'सबै मातृभाषा', E'नेपाली भाषा', 'D', E'नेपालको संविधानको धारा ७ अनुसार देवनागरी लिपिमा लेखिने **नेपाली भाषा** नेपालको सरकारी कामकाजको भाषा हुनेछ।\n- नेवारी भाषा नेपालमा बोलिने एक मातृभाषा हो।\n- देवनागरी एक लिपि हो, भाषा होइन।\n- नेपालमा बोलिने सबै मातृभाषाहरू राष्ट्रभाषा हुन्, तर सरकारी कामकाजको भाषा नेपाली मात्र हो।', 'nepali'),
      (v_set_id, 3, E'नदिनालाको सन्दर्भमा मुख भन्नाले के बुझिन्छ?', E'नदी उत्पादित हुने स्थान', E'नदी अन्त्य हुने स्थान', E'मिल्ने स-साना नदी', E'दुई नदी मिल्ने स्थान', 'B', E'नदिनालाको सन्दर्भमा मुख भन्नाले **नदी अन्त्य हुने स्थान** (जहाँ नदी समुद्र, ताल वा अर्को नदीमा गएर मिल्छ) लाई बुझिन्छ।\n- नदी उत्पादित हुने स्थानलाई मुहान (Source) भनिन्छ।\n- मुख्य नदीमा मिल्ने स-साना नदीलाई सहायक नदी (Tributary) भनिन्छ।\n- दुई नदी मिल्ने स्थानलाई संगम वा दोभान (Confluence) भनिन्छ।', 'nepali'),
      (v_set_id, 4, E'चुरे पर्वतको सबैभन्दा फराकिलो स्थान देहाएका मध्ये कुन जिल्लामा रहेको छ?', E'दाङ', E'कैलाली', E'मकवानपुर', E'दोलखा', 'A', E'चुरे पर्वतको सबैभन्दा फराकिलो स्थान **दाङ जिल्लाको देउखुरी उपत्यका**मा रहेको छ, जुन १२ माइल चौडा छ।\n- कैलाली जिल्लामा चुरे पर्वतको सबैभन्दा धेरै भू-भाग (क्षेत्रफल) पर्दछ।', 'nepali'),
      (v_set_id, 5, E'आ.व. २०८१/८२ को बजेटमा सबैभन्दा बढी खर्च गर्ने प्रदेश कुन हो?', E'कोशी प्रदेश', E'मधेस प्रदेश', E'बागमती प्रदेश', E'कर्णाली प्रदेश', 'A', E'आर्थिक वर्ष २०८१/८२ को बजेट अनुसार सबैभन्दा बढी खर्च गर्ने प्रदेश **कोशी प्रदेश** हो, जसले कुल बजेटको ७७.२६ प्रतिशत खर्च गर्ने अनुमान छ।\nनोट: सबैभन्दा कम बजेट खर्च गर्ने प्रदेश कर्णाली (६४.७२ प्रतिशत) हो र सातै प्रदेशको औसत खर्च ७३ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 6, E'२०८१ को मदन पुरस्कार विजेता साहित्यकार को हुन्?', E'रमेश भुसाल (छलबाटो)', E'कुमारी लामा (दञ्युँ सलाप)', E'छुदेन काविमो (उरमाल)', E'श्रेयज सुवेदी (बहुरुपी)', 'C', E'**छुदेन काविमोले आफ्नो उपन्यास ''उरमाल'' का लागि २०८१ को मदन पुरस्कार प्राप्त गरेका हुन्।** यो उपन्यासले दार्जिलिङको चिया बगान क्षेत्रका महिला श्रमिकको सांस्कृतिक र ऐतिहासिक यथार्थलाई जीवन्त रूपमा प्रस्तुत गरेको छ।\nनोट: २०८१ सालको जगदम्बाश्री पुरस्कारबाट भने प्रेमदेव गिरी सम्मानित भएका छन्।', 'nepali'),
      (v_set_id, 7, E'दीर्घकालीन सोच २१०० ले वि.सं. २०८७ सम्ममा नेपाललाई ____ आयस्तर भएको मुलुकमा स्तरोन्नति गर्ने लक्ष्य लिएको छ।', E'उच्च मध्यम', E'मध्यम', E'उच्च', E'निम्न मध्यम', 'B', E'दीर्घकालीन सोच २१०० अनुसार नेपालले वि.सं. २०८७ (सन् २०३०) सम्ममा दिगो विकासका लक्ष्यहरू हासिल गर्दै **मध्यम आय** भएको मुलुकमा स्तरोन्नति गर्ने लक्ष्य लिएको छ।\nनोट: यसअघि वि.सं. २०८३ (सन् २०२६) मा नेपाललाई अतिकम विकसित राष्ट्रबाट विकासशील देशमा स्तरोन्नति गर्ने लक्ष्य रहेको छ।', 'nepali'),
      (v_set_id, 8, E'पहिलो शाह वंशीय राजा कुलमण्डन खा कुन राज्यका संस्थापक राजा हुन्?', E'कास्की', E'लमजुङ', E'गोरखा', E'गलकोट', 'A', E'**पहिलो शाह वंशीय राजा कुलमण्डन खा कास्की राज्यका संस्थापक राजा हुन्।**\n- लमजुङ राज्यका संस्थापक राजा यशोब्रम्ह शाह हुन्।\n- गोरखा राज्यका संस्थापक राजा द्रव्य शाह हुन्।\n- गलकोट राज्यका संस्थापक राजा जितारी मल्ल थिए।', 'nepali'),
      (v_set_id, 9, E'नेपाल राष्ट्र बैंक बाट प्रकाशित पहिलो नोट कहिले प्रकाशित भएको थियो?', E'२००४ असोज १', E'२०१४ फागुन ७', E'२००२ असोज १', E'२०१६ फागुन ७', 'D', E'नेपाल राष्ट्र बैंकले आफ्नो स्थापनापछि पहिलो पटक **वि.सं. २०१६ फागुन ७** मा नोट प्रकाशित गरेको थियो।\n- वि.सं. २००२ असोज १ मा नेपालमा पहिलो पटक सदरमुलुकी खानाबाट कागजी नोट प्रकाशन गरिएको थियो, तर यो नेपाल राष्ट्र बैंकद्वारा थिएन।\nनोट: नेपाल राष्ट्र बैंकको स्थापना वि.सं. २०१३ वैशाख १४ गते भएको हो।', 'nepali'),
      (v_set_id, 10, E'पुष १५ गते मनाइने तमु ल्होसार कुन जाति प्रचलित रहेको?', E'तामाङ', E'शेर्पा', E'नेवार', E'गुरुङ', 'D', E'**पुष १५ गते मनाइने तमु ल्होसार गुरुङ समुदायको प्रमुख चाड हो।**\n- तामाङ जातिको मुख्य पर्व सोनाम ल्होसार हो।\n- शेर्पा जातिको मुख्य पर्व ग्याल्पो ल्होसार हो।\nनोट: गुरुङ समुदायले तमु ल्होसारलाई नयाँ वर्षको रूपमा मनाउँछन्।', 'nepali'),
      (v_set_id, 11, E'''मैले रोजेको बाटो'' कृतिका लेखक कुन साहित्यकार हुन्?', E'पारिजात', E'सोमकाजी शाक्य', E'शम्भुप्रसाद ढुङ्गेल', E'लक्ष्मीप्रसाद देवकोटा', 'B', E'**''मैले रोजेको बाटो'' कृतिका लेखक सोमकाजी शाक्य हुन्।**\n- पारिजात ''उसले रोजेको बाटो'' कृतिकी लेखक हुन्।\n- शम्भुप्रसाद ढुङ्गेल ''शकुन्तला'' कृतिका लेखक हुन्।\n- लक्ष्मीप्रसाद देवकोटा ''शाकुन्तला'' महाकाव्यका लेखक हुन्।', 'nepali'),
      (v_set_id, 12, E'लेन्सको शक्ति कुन एकाइमा नापिन्छ?', E'डायप्टर', E'माइक्रोमिटर', E'क्युरी', E'हर्ज', 'A', E'**लेन्सको शक्ति डायप्टर एकाइमा नापिन्छ।**\n- माइक्रोमिटरले ज्यादै छोटो दुरी नाप्न प्रयोग गरिन्छ।\n- क्युरी रेडियो एक्टिभिटिज (radioactivity) मापन गर्ने एकाइ हो।\n- हर्ज (Hz) आवृत्ति (frequency) को एकाइ हो।', 'nepali'),
      (v_set_id, 13, E'संयुक्त राष्ट्र संघ को कति औं महासभाले ब्रुटल्याण्ड कमिसन गठन गरेको थियो?', E'३८ औं', E'३९ औं', E'४० औं', E'४१ औं', 'A', E'संयुक्त राष्ट्र संघको **३८ औं** महासभाले ब्रुटल्याण्ड कमिसन गठन गरेको थियो।\nनोट: यो कमिसन सन् १९८३ मा नर्वेकी प्रधानमन्त्री Dr. Gro Harlem Brundtland को अध्यक्षतामा गठन गरिएको थियो।', 'nepali'),
      (v_set_id, 14, E'संयुक्त राष्ट्र संघमा मान्यता प्राप्त ६ भाषाको सूचीमा देहाएको कुन भाषा पर्दैन?', E'फ्रेन्च', E'स्पेनिस', E'जापानीज', E'अरबी', 'C', E'संयुक्त राष्ट्र संघका मान्यता प्राप्त ६ आधिकारिक भाषाहरू छन्, जसमा **जापानीज पर्दैन**। ती भाषाहरू स्पेनिस (Spanish), रुसी (Russian), फ्रेन्च (French), अरबी (Arabic), चिनियाँ (Chinese), र अंग्रेजी (English) हुन्।', 'nepali'),
      (v_set_id, 15, E'नोबेल पुरस्कार प्राप्त गर्ने संयुक्त राष्ट्रसंघको पहिलो महासचिव हुन?', E'ट्रिग्वे ली', E'ड्याग ह्यामर शोल्ड', E'बान कि मुन', E'कोफि अन्नान', 'B', E'संयुक्त राष्ट्रसंघको महासचिवको रूपमा नोबेल पुरस्कार प्राप्त गर्ने पहिलो व्यक्ति **ड्याग ह्यामर शोल्ड** हुन्।\n- ट्रिग्वे ली संयुक्त राष्ट्रसंघका प्रथम महासचिव थिए।\n- बान कि मुन संयुक्त राष्ट्रसंघका आठौँ महासचिव थिए।\n- कोफि अन्नानले पनि सन् २००१ मा नोबेल शान्ति पुरस्कार प्राप्त गरेका थिए।\nनोट: ड्याग ह्यामर शोल्डले सन् १९६१ मा मरणोपरान्त (posthumously) नोबेल शान्ति पुरस्कार पाएका थिए।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/१३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_14.csv  →  आसमान दैनिक GK — २०८२/१०/१४  (11 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/१४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/१४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/१४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'भाषा पाठशालाको स्थापना कहिले भयो?', E'वि.सं. २००४', E'वि.सं. १९५८', E'वि.सं. १९७५', E'वि.सं. १९९०', 'B', E'देव शमशेरले **वि.सं. १९५८** मा भाषा पाठशालाको स्थापना गरेका थिए।\n- वि.सं. २००४ मा पद्म शमशेरले कन्या पाठशालाको स्थापना गरे।\n- वि.सं. १९७५ मा चन्द्र शमशेरले त्रिचन्द्र कलेजको स्थापना गरे।\n- वि.सं. १९१० मा जंगबहादुर राणाले दरबार हाइस्कुलको स्थापना गरेका थिए।\nनोट: देवशमशेरले उपत्यकाभित्र ५७ वटा र उपत्यका बाहिर १०० वटा भाषा पाठशाला स्थापना गरेका थिए।', 'nepali'),
      (v_set_id, 2, E'सार्वभौमसत्ता र राजकीयसत्ता सँग सम्बन्धित व्यवस्था नेपालको संविधानको कुन धारामा उल्लेख रहेको छ?', E'धारा १', E'धारा २', E'धारा ३', E'धारा ४', 'B', E'नेपालको संविधानको **धारा २** मा सार्वभौमसत्ता र राजकीयसत्ता सम्बन्धी व्यवस्था उल्लेख गरिएको छ।\n- धारा १ मा ''संविधान मूल कानून'' सम्बन्धी व्यवस्था छ।\n- धारा ३ मा ''राष्ट्र'' सम्बन्धी व्यवस्था छ।\n- धारा ४ मा ''नेपाल राज्य'' सम्बन्धी व्यवस्था छ।\nनोट: धारा २ अनुसार, नेपालको सार्वभौमसत्ता र राजकीयसत्ता नेपाली जनतामा निहित रहेको छ।', 'nepali'),
      (v_set_id, 3, E'स्यूर्पु ताल नेपालको कुन जिल्लामा अवस्थित प्रसिद्ध ताल हो?', E'रुकुम पश्चिम', E'रुकुम पूर्व', E'कास्कि', E'सुर्खेत', 'A', E'स्यूर्पु ताल **रुकुम पश्चिम** जिल्लामा अवस्थित प्रसिद्ध ताल हो।\n- रुकुम पूर्व जिल्लामा सुनपोखरी ताल रहेको छ।\n- कास्की जिल्लामा फेवा ताल, बेगनास ताल र रूपा ताल जस्ता प्रसिद्ध तालहरू छन्।\n- सुर्खेत जिल्लामा बुलबुले ताल अवस्थित छ।', 'nepali'),
      (v_set_id, 4, E'हालसालै नेपालको कुन जिल्लामा ठूलो ग्याँसको खानी रहेको प्रारम्भिक नतिजाले तथ्य देखाएको हो?', E'बाजुरा', E'अछाम', E'दार्चुला', E'दैलेख', 'D', E'हालैको अन्वेषण अनुसार दैलेखमा ठूलो ग्याँसको खानी रहेको तथ्य फेला परेको छ। चिनियाँ सरकारी निकाय, चाइना जियोलोजिकल सर्भेले गरेको अनुसन्धानको प्रारम्भिक प्रतिवेदन अनुसार सो स्थानमा **एक अर्ब १२ करोड घनमिटर** मिथेन ग्यासको भण्डार रहेको पाइएको हो।\nनोट: यो ग्याँस भण्डारले दैलेखको जलजले क्षेत्रमा करिब ५० वर्षसम्मको माग धान्न सक्ने अनुमान गरिएको छ।', 'nepali'),
      (v_set_id, 5, E'आर्थिक वर्ष २०८२/८३ को बजेटले नेपालको कुल जडित विद्युत क्षमता कति पुऱ्याउने लक्ष्य राखेको छ?', E'४६०० मेगावाट', E'४८०० मेगावाट', E'५००० मेगावाट', E'५५०० मेगावाट', 'B', E'आर्थिक वर्ष २०८२/८३ को बजेटले नेपालको कुल जडित विद्युत क्षमता **४८०० मेगावाट** पुऱ्याउने लक्ष्य राखेको थियो। सरकारले सो आर्थिक वर्षमा थप ९ सय मेगावाट बिजुली उत्पादन गर्ने योजना बनाएको थियो।', 'nepali'),
      (v_set_id, 6, E'नेपालको भूगोलमा सबैभन्दा धेरै प्रदेश सभा निर्वाचन क्षेत्र भएको जिल्ला काठमाडौं मा जम्मा कति वटा प्रदेशसभा निर्वाचन क्षेत्र रहेका छन?', E'२० वटा', E'१६ वटा', E'१४ वटा', E'१० वटा', 'A', E'काठमाडौं जिल्लामा जम्मा **२० वटा** प्रदेशसभा निर्वाचन क्षेत्र रहेका छन्, जुन नेपालको भूगोलमा सबैभन्दा धेरै हो। सामान्यतया, कुनै जिल्लामा जतिवटा प्रतिनिधिसभा निर्वाचन क्षेत्र हुन्छन्, त्यसको ठिक दोब्बर संख्यामा प्रदेशसभा निर्वाचन क्षेत्र निर्धारण गरिन्छ।\nनोट: काठमाडौंमा १० वटा प्रतिनिधिसभा निर्वाचन क्षेत्र रहेका छन्।', 'nepali'),
      (v_set_id, 7, E'नेपाल एकीकरणका नायक पृथ्वीनारायण शाहको मृत्यु कति वर्षको उमेरमा भएको थियो?', E'५२ वर्ष', E'५० वर्ष', E'५४ वर्ष', E'५६ वर्ष', 'A', E'नेपाल एकीकरणका नायक पृथ्वीनारायण शाहको मृत्यु **५२ वर्षको** उमेरमा भएको थियो। उनको जन्म वि.सं. १७७९ पौष २७ गते गोरखामा भएको थियो भने मृत्यु वि.सं. १८३१ माघ १ गते नुवाकोटमा भएको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपालको इतिहासमा "प्रचण्ड गोर्खा पर्व" मा पोल खोल्ने व्यक्ति देहाएका मध्ये को हुन?', E'उत्तरध्वज खवास', E'रामचन्द्र अधिकारी', E'रामहरि जोशी', E'लक्ष्मण राज', 'D', E'नेपालको इतिहासमा "प्रचण्ड गोर्खा पर्व" को पोल खोल्ने व्यक्ति **लक्ष्मण राज** हुन्।\n- उत्तरध्वज खवास (राजभण्डारी) ३८ सालको पर्वको पोल खोल्ने व्यक्ति हुन्।\n- रामचन्द्र अधिकारी लाइब्रेरी पर्वसँग सम्बन्धित छन्।\n- रामहरी अधिकारी र भोजराज जोशी मकै पर्वसँग सम्बन्धित छन्।', 'nepali'),
      (v_set_id, 9, E'शेर्पा जातिका महिलाले लगाउने कपडालाई के भनिन्छ?', E'बखखु', E'दोचा', E'पाङदेन', E'फोग्यु', 'C', E'शेर्पा जातिका महिलाले लगाउने कपडालाई **पाङदेन** भनिन्छ।\n- बखखु शेर्पा जातिले लगाउने परम्परागत पोसाक हो।\n- दोचा शेर्पा जातिले लगाउने जुत्तालाई भनिन्छ।\n- फोग्यु शेर्पा जातिको धार्मिक ग्रन्थलाई भनिन्छ।', 'nepali'),
      (v_set_id, 10, E'देहाएको कुन कृति महाकवी लक्ष्मीप्रसाद देवकोटाको हो?', E'अक्षरमाला', E'माटोको ममता', E'सुलोचना', E'मैया साहेब', 'C', E'**''सुलोचना''** महाकवि लक्ष्मीप्रसाद देवकोटाको कृति हो।\n- ''अक्षरमाला'' जयपृथ्वीबहादुर सिंहको कृति हो।\n- ''माटोको ममता'' बालकृष्ण समको कृति हो।\n- ''मैया साहेब'' भवानी दास गुप्ताको कृति हो।', 'nepali'),
      (v_set_id, 11, E'नेपालमा सुचना प्रविधि पार्क कहाँ स्थापना गरिएको छ?', E'काभ्रे, धुलिखेल', E'काभ्रे, बनेपा', E'काठमाडौं, ठमेल', E'ललितपुर, गोदावरी', 'B', E'नेपालमा सूचना प्रविधि पार्क **काभ्रेको बनेपामा** स्थापना गरिएको छ।\n- ललितपुरको गोदावरीमा नेपालको टिस्यु कल्चर ल्याब (Tissue Culture Lab) रहेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/१४', 11;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_16.csv  →  आसमान दैनिक GK — २०८२/१०/१६  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/१६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/१६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/१६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाल सरकारले स्वास्थ्य बीमा कार्यक्रम सुरु गरेका तीन जिल्ला अन्तर्गत देहायको कुन जिल्ला पर्दैन?', E'इलाम', E'कैलाली', E'बाग्लुङ', E'सुर्खेत', 'D', E'नेपाल सरकारले स्वास्थ्य बीमा कार्यक्रम पहिलो चरणमा कैलाली, बाग्लुङ र इलाम गरी तीन जिल्लाबाट सुरु गरेको थियो, त्यसैले **सुर्खेत** ती जिल्लाहरूमा पर्दैन।\nनोट: नेपालमा स्वास्थ्य बीमा कार्यक्रम वि.सं. २०७२ चैत्र २५ गतेबाट सुरु भएको हो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधानको कुन धारामा महिलाको हक सम्बन्धित व्यवस्था गरेको छ?', E'धारा ३८', E'धारा ३९', E'धारा ४०', E'धारा ४१', 'A', E'नेपालको संविधानको **धारा ३८** मा महिलाको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा ३९ मा बालबालिकाको हक सम्बन्धी व्यवस्था छ।\n- धारा ४० मा दलितको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा ४१ मा ज्येष्ठ नागरिकको हक सम्बन्धी व्यवस्था छ।', 'nepali'),
      (v_set_id, 3, E'१ पार्सक बराबर कति प्रकाश वर्ष रहेको हुन्छ?', E'३.२६ प्रकाश वर्ष', E'३.५२ प्रकाश वर्ष', E'३.८६ प्रकाश वर्ष', E'३.९५ प्रकाश वर्ष', 'A', E'एक पार्सक बराबर **३.२६ प्रकाश वर्ष** हुन्छ। पार्सेक (Parsec) धेरै टाढाका आकाशीय पिण्डहरूको दूरी नाप्ने खगोलीय एकाइ हो।\nनोट: १ पार्सक बराबर २०६२६५ AU (Astronomical Unit) पनि हुन्छ।', 'nepali'),
      (v_set_id, 4, E'नेपालमा पहिलो समलिंगी बिवाह दर्ता कहिले भएको थियो?', E'२०८० मंसिर १३', E'२०८० मंसिर १५', E'२०८० मंसिर १७', E'२०८० मंसिर १९', 'A', E'नेपालमा पहिलो समलिंगी विवाह **वि.सं. २०८० मंसिर १३** गते दर्ता भएको थियो। लमजुङको दोर्दी गाउँपालिका-२ का रामबहादुर गुरुङ र नवलपरासी (बर्दघाट सुस्ता पूर्व) कावासोती-८ का सुरेन्द्र पाण्डेबीचको विवाह दर्ता भएको हो।\nनोट: सर्वोच्च अदालतले वि.सं. २०८० असार १२ मा समलिंगी विवाह दर्ता गर्न अन्तरिम आदेश दिएको थियो।', 'nepali'),
      (v_set_id, 5, E'२०८२ मा पहिलो पटक याक दिवस कहिले मनाइएको छ?', E'वैशाख २', E'वैशाख ४', E'वैशाख ५', E'वैशाख ७', 'D', E'पहिलो पटक याक दिवस **वैशाख ७, २०८२** मा मनाइएको छ। सरकारले २०८१ असोजमा प्रत्येक वर्ष वैशाख ७ लाई राष्ट्रिय याक दिवसको रूपमा मनाउने निर्णय गरेको थियो।\nनोट: यस दिवसको मूल नारा ''याक चौंरी प्रवर्द्धन हिमाली जीवन, संस्कृति र पर्यावरण संरक्षण'' रहेको थियो।', 'nepali'),
      (v_set_id, 6, E'एसिया र युरोपको सिमाना छुट्याउने पर्वतमाला कुन हो?', E'काकेसस', E'युराल', E'आल्पस', E'अलस्का', 'B', E'**युराल पर्वतमालाले एसिया र युरोप महादेशको सिमाना छुट्याउँछ।**\n- काकेसस पर्वतमाला कृष्ण सागर र क्यास्पियन सागरको बीचमा अवस्थित छ।\n- आल्पस पर्वतमाला युरोप महादेशको एक प्रमुख पर्वत प्रणाली हो।\n- अलस्का पर्वत श्रेणी उत्तर अमेरिकाको अलास्का राज्यमा अवस्थित छ।\nनोट: युराल पर्वतमाला रुस र काजकिस्तानमा फैलिएको छ र यसको सबैभन्दा अग्लो शिखर नरोदनाया पर्वत (१८६४ मिटर) हो।', 'nepali'),
      (v_set_id, 7, E'कुशापानी झरणा, खरिगरा झरणा नेपालको कुन जिल्लामा अवस्थित छन?', E'सुर्खेत', E'दैलेख', E'अछाम', E'बझाङ', 'B', E'**कुशापानी झरणा र खरिगरा झरणा दैलेख जिल्लामा अवस्थित छन्।**\n- सुर्खेत जिल्लामा गिद्धे र गल्छेना झरनाहरू पर्दछन्।\n- अछाम जिल्लामा वैद्यनाथ झरना रहेको छ।\n- बझाङ जिल्लामा छहरा झरना अवस्थित छ।\nनोट: दैलेख जिल्लामा लाकुरी झरणा र द्वारीखोलाको झरना जस्ता अन्य झरनाहरू पनि रहेका छन्।', 'nepali'),
      (v_set_id, 8, E'आठ हजार मिटर भन्दा अग्ला आठवटा हिमाल मध्ये गण्डकी प्रदेशमा अवस्थित हिमालको संख्या कति रहेको छ?', E'५ वटा', E'४ वटा', E'३ वटा', E'२ वटा', 'C', E'आठ हजार मिटरभन्दा अग्ला आठवटा हिमालहरूमध्ये गण्डकी प्रदेशमा **३ वटा** अवस्थित छन्। ती हिमालहरू धवलागिरि, मनास्लु र अन्नपूर्ण हुन्।\nनोट: बाँकी ५ वटा हिमालहरू (सगरमाथा, कञ्चनजङ्घा, ल्होत्से, मकालु र चो ओयु) कोशी प्रदेशमा पर्दछन्।', 'nepali'),
      (v_set_id, 9, E'बोल्सेभिक क्रान्तिको उपनामले कुन क्रान्तिलाई चिनिन्छ?', E'फ्रान्सेली राज्य', E'रुसी राज्य', E'औद्योगिक', E'गौरवमय', 'B', E'रुसी राज्य क्रान्तिलाई **बोल्सेभिक क्रान्ति** वा अक्टोबर क्रान्तिको उपनामले पनि चिनिन्छ।\n- फ्रान्सेली राज्य क्रान्तिलाई बौद्धिक क्रान्तिको रूपमा चिनिन्छ।\n- औद्योगिक क्रान्तिलाई यान्त्रिक क्रान्ति पनि भनिन्छ।\n- गौरवमय क्रान्तिलाई रक्तहिन क्रान्तिको रूपमा चिनिन्छ।', 'nepali'),
      (v_set_id, 10, E'गोपालवंशावली अनुसार गोपालवंशका राजाहरूले नेपालमा कति वर्ष शासन गरेको थिए?', E'५०५ वर्ष', E'५२१ वर्ष', E'१११ वर्ष', E'१६१ वर्ष', 'A', E'गोपालवंशावली अनुसार गोपालवंशका आठ राजाहरूले नेपालमा करीब **५०५ वर्ष** शासन गरेका थिए।\n- राइट वंशावली अनुसार गोपालवंशले ५२१ वर्ष शासन गरेको उल्लेख छ।\n- राइट वंशावली अनुसार महिषपाल वंशले १११ वर्ष शासन गरेको मानिन्छ।\n- गोपालवंशावली अनुसार महिषपाल वंशका तीन राजाहरूले जम्मा १६१ वर्ष २ महिना शासन गरेका थिए।', 'nepali'),
      (v_set_id, 11, E'साहुको ऋण चुक्ता गर्न साहुको घरमा बसेर काम गर्ने र ब्याज मिनाह हुने नेपाली प्रथालाई कुन प्रथा भनिन्छ?', E'तिर्जा प्रथा', E'दास प्रथा', E'कमैया प्रथा', E'झारा प्रथा', 'C', E'साहुको ऋण चुक्ता गर्न साहुकै घरमा बसेर काम गर्ने प्रथालाई **कमैया प्रथा** भनिन्छ।\n- तिर्जा प्रथा जग्गाको तिरो बुझाउने सम्बन्धी एक प्रकारको कागजी प्रणाली थियो।\n- दास प्रथामा मानिसलाई वस्तुसरह किनबेच गरिन्थ्यो, जसको अन्त्य वि.सं. १९८१ मा चन्द्रशमशेरले गरेका थिए।\n- झारा प्रथा राज्यका लागि बिना पारिश्रमिक अनिवार्य श्रमदान गर्नुपर्ने व्यवस्था थियो।\nनोट: नेपाल सरकारले कमैया प्रथाको अन्त्यको घोषणा वि.सं. २०५७ साउन २ गते गरेको थियो।', 'nepali'),
      (v_set_id, 12, E'प्राय चिसोको कारण लाग्ने निमोनिया रोग विरुद्ध बालबालिका लाई दिने खोपको नाम देहायका मध्ये कुन हो?', E'पि सी भी', E'डि पि टी', E'बि सि जी', E'ओ पि भि', 'A', E'निमोनिया रोग विरुद्ध बालबालिकालाई दिइने खोप **पि सी भी (Pneumococcal Conjugate Vaccine)** हो।\n- डि पि टी खोप भ्यागुते रोग, लहरेखोकी र धनुष्टंकार विरुद्ध दिइन्छ।\n- बि सि जी खोप क्षयरोग विरुद्ध लगाइन्छ।\n- ओ पि भि (Oral Polio Vaccine) पोलियो रोग विरुद्ध दिइने खोप हो।', 'nepali'),
      (v_set_id, 13, E'नेपालको सबैभन्दा ठूलो रा. नि. ''शे-फोक्सुण्डो राष्ट्रिय निकुञ्जको'' स्थापना कहिले भएको हो?', E'वि.सं. २०४०', E'वि.सं. २०३०', E'वि.सं. २०४५', E'वि.सं. २०३५', 'A', E'नेपालको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज, शे-फोक्सुण्डो राष्ट्रिय निकुञ्जको स्थापना **वि.सं. २०४०** मा भएको हो।\nनोट: यो निकुञ्ज डोल्पा र मुगु जिल्लामा ३,५५५ वर्ग कि.मि. क्षेत्रफलमा फैलिएको छ।', 'nepali'),
      (v_set_id, 14, E'कालिगण्डकी A जलविद्युत आयोजना कुन मुलुकको आर्थिक सहयोगमा निर्माण भएको हो?', E'बेलायत', E'जापान', E'भारत', E'अमेरिका', 'B', E'कालिगण्डकी ''ए'' जलविद्युत आयोजना **जापानको** आर्थिक सहयोगमा निर्माण भएको हो।\nनोट: जापानले नेपालमा नयाँ बसपार्क, बालाजु, कर्णाली पुल, वागमती पुल, मलेखु पुल, महाराजगञ्ज टिचिङ अस्पताल, र त्रिभुवन अन्तर्राष्ट्रिय विमान स्थलको आधुनिकीकरणमा पनि सहयोग गरेको छ।', 'nepali'),
      (v_set_id, 15, E'सार्कमा महासचिव राख्न व्यवस्था कहिले देखि गरिएको हो?', E'सन् १९८५', E'सन् १९८८', E'सन् १९८७', E'सन् १९८६', 'C', E'सार्कमा महासचिव राख्ने व्यवस्था **सन् १९८७ जनवरी १६** देखि गरिएको हो।\nनोट: सार्कका पहिलो महासचिव बंगलादेशका अब्दुल अहसन थिए, जसको कार्यकाल १६ जनवरी १९८७ देखि १५ अक्टोबर १९८९ सम्म थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/१६', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_28.csv  →  आसमान दैनिक GK — २०८२/१०/२८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/२८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/२८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/२८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'''सम्पत्ति तथा पारिवारिक मामिलामा दम्पतीको समान हक हुनेछ'' यो कुरा कुन मौलिक हक अन्तर्गत रहेको छ ?', E'न्याय सम्बन्धि हक', E'समानताको हक', E'सम्पतिको हक', E'महिलाको हक', 'D', E'सम्पत्ति तथा पारिवारिक मामिलामा दम्पतीको समान हक हुने व्यवस्था **महिलाको हक** अन्तर्गत गरिएको छ।\n- न्याय सम्बन्धि हकले प्रत्येक व्यक्तिलाई आफ्नो मुद्दाको निष्पक्ष सुनुवाइको हक सुनिश्चित गर्दछ।\n- समानताको हकले कानूनको दृष्टिमा सबै नागरिक समान हुने र कसैलाई पनि भेदभाव नगरिने कुरा सुनिश्चित गर्दछ।\n- सम्पतिको हकले प्रत्येक नागरिकलाई कानूनको अधीनमा रही सम्पत्ति आर्जन गर्ने, भोग गर्ने, बेचबिखन गर्ने र अन्य कारोबार गर्ने हक प्रदान गर्दछ।\nनोट: नेपालको संविधानको धारा ३८ मा महिलाको हक सम्बन्धी व्यवस्था गरिएको छ, जसको उपधारा (६) मा यो प्रावधान उल्लेख छ।', 'nepali'),
      (v_set_id, 2, E'नेपालका लागि सान्दर्भिक नभएको दिगो विकासको लक्ष्य कुन हो ?', E'लक्ष्य १४', E'लक्ष्य १५', E'लक्ष्य १३', E'लक्ष्य १६', 'A', E'दिगो विकास लक्ष्यहरूमध्ये **लक्ष्य १४ (जलमुनिको जीवन)** नेपालका लागि सान्दर्भिक छैन, किनभने नेपाल एक भूपरिवेष्ठित राष्ट्र हो।\n- लक्ष्य १५ ''जलमाथिको जीवन'' (Life on Land) सँग सम्बन्धित छ, जुन नेपालको जैविक विविधता र वन संरक्षणका लागि अत्यन्त महत्त्वपूर्ण छ।\n- लक्ष्य १३ ''जलवायु परिवर्तन र यसका प्रभाव न्यूनीकरण'' (Climate Action) सँग सम्बन्धित छ, जुन हिमालय क्षेत्रको लागि संवेदनशील विषय हो।\n- लक्ष्य १६ ''शान्ति, न्याय र सशक्त संस्थाहरू'' (Peace, Justice and Strong Institutions) सँग सम्बन्धित छ, जुन नेपालको सुशासन र विकासका लागि आवश्यक छ।\nनोट: दिगो विकासका १७ लक्ष्यहरू सन् २०१६ देखि २०३० सम्मका लागि संयुक्त राष्ट्र संघले निर्धारण गरेको हो।', 'nepali'),
      (v_set_id, 3, E'महाराजधिराज परम भट्टारक पदवी धारण गर्ने प्रथम लिच्छवि राजा को हुन् ?', E'उदयदेव', E'अंशुवर्मा', E'मानदेव', E'नरेन्द्रदेव', 'D', E'**नरेन्द्रदेव** सर्वप्रथम ''महाराजधिराज परम भट्टारक'' पदवी धारण गर्ने लिच्छवि राजा हुन्।\n- अंशुवर्माले सर्वप्रथम ''महाराजधिराज''को पदवी धारण गरेका थिए।', 'nepali'),
      (v_set_id, 4, E'ग्रन्थकुट शैलीलाई कुन शैलीको आधुनिक शैलीका रुपमा चिनिन्छ ?', E'स्तूप शैली', E'प्यागोडा शैली', E'शिखर शैली', E'युरोपेली शैली', 'C', E'ग्रन्थकुट शैलीलाई **शिखर शैलीको** आधुनिक रूपमा चिनिन्छ।\nनोट: रानी पोखरीको बीचमा रहेको बाल गोपालेश्वर मन्दिर ग्रन्थकुट शैलीमा निर्माण भएको छ।', 'nepali'),
      (v_set_id, 5, E'हड्डीहरुको अध्ययन गर्ने विज्ञानको शास्त्रलाई के भनिन्छ ?', E'एग्रोलोजी', E'इकोलोजी', E'एनाटोमी', E'अस्टियोलोजी', 'D', E'**हड्डीहरुको अध्ययन गर्ने विज्ञानको शास्त्रलाई अस्टियोलोजी भनिन्छ।**\n- एग्रोलोजीमा भूमि (माटो) को अध्ययन गरिन्छ।\n- इकोलोजीमा परिस्थितिको अध्ययन गरिन्छ।\n- एनाटोमीमा मानवशरीरको संरचनाको अध्ययन गरिन्छ।', 'nepali'),
      (v_set_id, 6, E'देहाएका मध्ये कुन रोग जीवाणु समूह (Bacterial Group) अन्तर्गत पर्ने रोग हैन । पहिचान गर्नुहोस्', E'लहरे खोकी', E'दादुरा', E'हैजा', E'निमोनिया', 'B', E'**दादुरा** विषाणु (Virus) समूह अन्तर्गत पर्ने रोग हो, जीवाणु (Bacterial) समूह अन्तर्गत होइन।\n- लहरे खोकी, हैजा र निमोनिया जीवाणु समूह अन्तर्गत पर्ने रोगहरू हुन्।\nनोट: जीवाणु समूहमा पर्ने अन्य रोगहरूमा भ्यागुते रोग, कुष्ठरोग, क्षयरोग र धनुष्टंकार पर्दछन्।', 'nepali'),
      (v_set_id, 7, E'भारतले संयुक्त राष्ट्रसंघको बजेटमा कति प्रतिशत योगदान गरेको छ ?', E'१.०१० प्रतिशत', E'१.११४ प्रतिशत', E'१.०४४ प्रतिशत', E'१.०४१ प्रतिशत', 'C', E'भारतले संयुक्त राष्ट्रसंघको बजेटमा **१.०४४ प्रतिशत** योगदान गरेको छ, जुन सार्क राष्ट्रहरूमध्ये सबैभन्दा धेरै हो।\nनोट: संयुक्त राष्ट्रसंघको बजेटमा सबैभन्दा धेरै योगदान गर्ने राष्ट्र अमेरिका (२२%) हो भने नेपालले ०.०१०% योगदान गर्दछ।', 'nepali'),
      (v_set_id, 8, E'दुखाई मापन गर्ने यन्त्र देहाएका मध्ये कुन हो ?', E'अल्टोमिटर', E'एल्गोमिटर', E'ब्रेथलाइजर', E'पोलिग्राफ', 'B', E'**दुखाई मापन गर्ने यन्त्र एल्गोमिटर हो।**\n- ब्रेथलाइजर चालकले मादक पदार्थ खाए नखाएको जाँच्ने यन्त्र हो।\n- पोलिग्राफ झुट बोलेको पत्ता लगाउने यन्त्र हो।', 'nepali'),
      (v_set_id, 9, E'सर्वप्रथम दिगो विकास शब्दको प्रयोग कहिले गरियो ?', E'सन् १९८७', E'सन् १९८३', E'सन् १९७२', E'सन् २०१५', 'A', E'**सन् १९८७ मा ब्रुटल्यान्ड प्रतिवेदनमा सर्वप्रथम ''दिगो विकास'' शब्दको प्रयोग गरिएको थियो।**\nनोट: यसअघि सन् १९८३ मा ब्रुटल्यान्ड आयोगको गठन भएको थियो भने सन् १९७२ मा स्टकहोम सम्मेलन भएको थियो।', 'nepali'),
      (v_set_id, 10, E'पृथ्वीनारायण शाहले भाई शुर प्रताप शाहका आँखा फुटेको घटना कति औं कीर्तिपुर आक्रमणसँग सम्बन्धित रहेको छ ?', E'दोस्रो', E'तेस्रो', E'पहिलो', E'चौथो', 'A', E'पृथ्वीनारायण शाहका भाई शुर प्रताप शाहका आँखा फुटेको घटना **दोस्रो कीर्तिपुर आक्रमणसँग** सम्बन्धित छ।\n- पहिलो कीर्तिपुर आक्रमण (वि.सं. १८१४) असफल भएको थियो र यसमा काजी कालु पाँडेको निधन भयो।\n- तेस्रो कीर्तिपुर आक्रमण (वि.सं. १८२२) मा गोर्खाली सेनाले विजय हासिल गरेको थियो।\n- कीर्तिपुरमाथि विजयका लागि जम्मा तीन पटक आक्रमण भएको थियो।', 'nepali'),
      (v_set_id, 11, E'२०७८ सालको जनगणना अनुसार भोजपुरी भाषा बोल्ने जनसंख्या कति प्रतिशत रहेको छ ?', E'६.२४ प्रतिशत', E'४.८८ प्रतिशत', E'५.८८ प्रतिशत', E'११.०५ प्रतिशत', 'A', E'२०७८ सालको जनगणना अनुसार **भोजपुरी भाषा बोल्ने जनसंख्या ६.२४ प्रतिशत** रहेको छ।\n- ४.८८ प्रतिशत जनसंख्याले तामाङ भाषा बोल्छन्।\n- ५.८८ प्रतिशत जनसंख्याले थारु भाषा बोल्छन्।\n- ११.०५ प्रतिशत जनसंख्याले मैथिली भाषा बोल्छन्।\nनोट: सोही जनगणना अनुसार सबैभन्दा बढी बोलिने भाषा नेपाली (४४.८६%) हो।', 'nepali'),
      (v_set_id, 12, E'दक्षिण एसियाली क्षेत्रीय सहयोग संगठन (SAARC) को स्थापना कालका सदस्य संख्या कति रहेको छ ?', E'६ वटा', E'८ वटा', E'७ वटा', E'५ वटा', 'C', E'दक्षिण एसियाली क्षेत्रीय सहयोग संगठन (SAARC) को स्थापना कालमा सदस्य संख्या **७ वटा** रहेको थियो।\nनोट: अफगानिस्तानलाई सन् २००७ मा भएको १४ औं शिखर सम्मेलनबाट आठौं सदस्यको रूपमा थपिएको थियो, जसको निर्णय १३ औं शिखर सम्मेलनले गरेको थियो।', 'nepali'),
      (v_set_id, 13, E'नेपालका हालसम्म सम्पन्न १५ वटा आवधिक योजनाहरु मध्ये कुल विनियोजनको सबैभन्दा बढि प्रतिशत खर्च भएको योजना कुन हो ?', E'दोस्रो योजना', E'तेस्रो योजना', E'चौथो योजना', E'पाँचौं योजना', 'A', E'नेपालका आवधिक योजनाहरूमध्ये **दोस्रो योजनामा** कुल विनियोजनको सबैभन्दा बढी प्रतिशत खर्च भएको थियो।\n- तेस्रो पञ्चवर्षीय योजनाको लक्ष्य १५ वर्षभित्र राष्ट्रिय उत्पादनलाई दोब्बर गर्ने थियो।\n- चौथो पञ्चवर्षीय योजनाबाट क्षेत्रगत विकासको अवधारणा सुरु भएको थियो।\n- पाँचौं पञ्चवर्षीय योजनाले प्रादेशिक विकासको अवधारणा ल्याएको थियो।\nनोट: दोस्रो योजना (२०१९-२०२२) एक त्रिवर्षीय योजना थियो जसले वैदेशिक ऋण लिन र कृषि गणना गर्न सुरु गरेको थियो।', 'nepali'),
      (v_set_id, 14, E'नेपाल र अंग्रेज बिच भएको सुगौली सन्धिमा हस्ताक्षर कहिले भएको थियो ?', E'१८१६ मार्च ३', E'१८१५ मार्च ३', E'१८१५ डिसेम्बर २', E'१८१६ डिसेम्बर २', 'A', E'नेपाल र अंग्रेजबीच सुगौली सन्धिमा **सन् १८१६ मार्च ३** (वि.सं. १८७२ फागुन २४) मा हस्ताक्षर भएको थियो। यो सन्धिमा नेपालको तर्फबाट गजराज मिश्र र अंग्रेजको तर्फबाट लेफ्टिनेन्ट ब्राडशले हस्ताक्षर गरेका थिए।\nनोट: हस्ताक्षर हुँदा नेपालका प्रधानमन्त्री भीमसेन थापा र राजा गिर्वाणयुद्ध विक्रम शाह थिए।', 'nepali'),
      (v_set_id, 15, E'मानव अधिकार सम्बन्धमा विश्वको प्रथम दस्तावेज ''म्याग्नाकार्टा''मा कहिले हस्ताक्षर गरेका भयो ?', E'सन् १२१५ जुन १५', E'सन् १२२५ जुन १५', E'सन् १२१५ जुन २५', E'सन् १२२५ जुन २५', 'A', E'मानव अधिकार सम्बन्धी विश्वको पहिलो लिखित दस्तावेज मानिने म्याग्नाकार्टामा **सन् १२१५ जुन १५** मा हस्ताक्षर भएको थियो। यो बेलायतको रनीमेडे नामक स्थानमा राजा जोन द्वितीयद्वारा हस्ताक्षर गरिएको थियो।\nनोट: म्याग्नाकार्टामा जम्मा ६३ वटा धारा रहेका छन् र यसलाई बेलायती नागरिकहरूको स्वतन्त्रताको बडापत्र पनि भनिन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/२८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_10_29.csv  →  आसमान दैनिक GK — २०८२/१०/२९  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१०/२९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१०/२९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१०/२९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाल बहुसूचक सर्वेक्षण २०७१/८२ (२०२४-२५) अनुसार कति प्रतिशत घरपरिवारमा टेलिफोन सुविधाको पहुँच रहेको छ ?', E'९४.५ प्रतिशत', E'९५.५ प्रतिशत', E'९६.५ प्रतिशत', E'९७.५ प्रतिशत', 'B', E'नेपाल बहुसूचक सर्वेक्षण २०७१/८२ (२०२४-२५) अनुसार **९५.५ प्रतिशत** घरपरिवारमा टेलिफोन (स्थिर टेलिफोन वा मोबाइल फोन) सुविधाको पहुँच रहेको छ।\nनोट: प्रदेश अनुसार सबैभन्दा धेरै बागमती प्रदेश (९७.१ प्रतिशत) र सबैभन्दा कम सुदूरपश्चिम प्रदेश (९२.६ प्रतिशत) मा टेलिफोन सुविधाको पहुँच रहेको छ।', 'nepali'),
      (v_set_id, 2, E'हालसालै २०२६ फेब्रुअरीमा जापानमा सम्पन्न तल्लो सदनको निर्वाचनमा ऐतिहासिक विजय हासिल गर्न सफल पार्टि कुन हो ?', E'जापान इनोभेसन पार्टी', E'जापान डेमोक्रेटिक पार्टी', E'लिबरल डेमोक्रेटिक पार्टी', E'लिबरल कम्युनिष्ट पार्टी', 'C', E'सन् २०२६ फेब्रुअरीमा सम्पन्न जापानको तल्लो सदनको निर्वाचनमा **लिबरल डेमोक्रेटिक पार्टी (एलडिपी) ले** ऐतिहासिक विजय हासिल गरेको थियो।\nनोट: यो जित सानाए ताकाइचीको नेतृत्वमा भएको थियो, जो त्यसबेला जापानको प्रधानमन्त्री थिइन्।', 'nepali'),
      (v_set_id, 3, E'टि-२० क्रिकेट विश्वकप २०२६ मा नेपालको तर्फबाट विकेट लिने पहिलो खेलाडी को हुन् ?', E'सन्दीप लामिछाने', E'शेर मल्ल', E'नन्दन यादव', E'रोहित पौडेल', 'B', E'टि-२० क्रिकेट विश्वकप २०२६ मा नेपालको तर्फबाट विकेट लिने पहिलो खेलाडी **शेर मल्ल** हुन्।\n- सन्दीप लामिछाने नेपालका एक प्रमुख लेग-स्पिनर बलर हुन्।\n- नन्दन यादव नेपाली राष्ट्रिय क्रिकेट टोलीका सदस्य हुन्।\n- रोहित पौडेल नेपाली राष्ट्रिय क्रिकेट टोलीका कप्तान हुन्।\nनोट: २०२६ को टी-२० विश्वकपमा नेपालको पहिलो खेल इङ्गल्याण्डसँग भएको थियो।', 'nepali'),
      (v_set_id, 4, E'अर्थ मन्त्रालयले चालु आर्थिक वर्ष २०८२/८३ मा बजेट को कति प्रतिशत मात्र खर्च हुने गरि अर्धवार्षिक समीक्षा प्रतिवेदन सार्वजनिक गरेको छ ?', E'८१.९६ प्रतिशत', E'८३.९६ प्रतिशत', E'८५.९६ प्रतिशत', E'८७.९६ प्रतिशत', 'C', E'अर्थ मन्त्रालयले चालु आर्थिक वर्ष २०८२/८३ मा बजेटको **८५.९६ प्रतिशत** मात्र खर्च हुने गरी संशोधित अनुमानसहित अर्धवार्षिक समीक्षा प्रतिवेदन सार्वजनिक गरेको छ। यो अनुमान अर्थमन्त्री रामेश्वर खनालले सार्वजनिक गरेका हुन्।', 'nepali'),
      (v_set_id, 5, E'साफ यु-१९ महिला च्याम्पियनसिप, २०२६ को उपाधि कुन देशले जितेको छ ?', E'भारत', E'बंगलादेश', E'भुटान', E'नेपाल', 'A', E'**भारतले** साफ यु-१९ महिला च्याम्पियनसिप, २०२६ को उपाधि जितेको हो।\n- बंगलादेश प्रतियोगिताको उपविजेता बनेको थियो।\n- भुटान प्रतियोगितामा सहभागी एक टोली थियो।\n- नेपालले प्रतियोगिता आयोजना गरेको थियो र सहभागी पनि भएको थियो।\nनोट: यो प्रतियोगिता पोखरा, नेपालमा २०८२ माघ १७ देखि २४ सम्म सञ्चालन भएको थियो।', 'nepali'),
      (v_set_id, 6, E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार नेपाल विश्वको कति औं स्थानमा रहेको छ ?', E'१०३ औं', E'१०६ औं', E'१०९ औं', E'११० औं', 'C', E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार नेपाल विश्वको **१०९ औं** स्थानमा रहेको छ। यो सूचकांक ट्रान्सपरेन्सी इन्टरनेशनलले सन् २०२४ फेब्रुअरी १० मा सार्वजनिक गरेको हो, जसमा नेपालले ३४ अंक प्राप्त गरेको थियो।\nनोट: यस सूचकांकमा सबैभन्दा कम भ्रष्टाचार हुने मुलुक डेनमार्क र सबैभन्दा बढी भ्रष्टाचार हुने मुलुक साउथ सुडान र सोमालिया रहेका छन्।', 'nepali'),
      (v_set_id, 7, E'नेपाल बहुसूचक सर्वेक्षण २०८१/८२ (२०२४-२५) अनुसार हाल प्रति १००० जीवित जन्मेका शिशुहरूमध्ये नवजात शिशु मृत्युदर कति रहेको छ ?', E'१७ जना', E'२७ जना', E'३७ जना', E'४७ जना', 'A', E'नेपाल बहुसूचक सर्वेक्षण २०८१/८२ अनुसार हाल प्रति १००० जीवित जन्मेका शिशुहरूमध्ये नवजात शिशु मृत्युदर **१७ जना** रहेको छ।\nनोट: राष्ट्रिय तथ्यांक कार्यालयले सार्वजनिक गरेको यस सर्वेक्षण अनुसार, शिशु मृत्युदर (१ वर्षमुनि) २७ जना र बालमृत्युदर (५ वर्षमुनि) ३१ जना प्रति १००० जीवित जन्ममा रहेको छ।', 'nepali'),
      (v_set_id, 8, E'बंगलादेशमा जुलाई-अगस्ट २०२४ को जेनजी विद्रोहपछि पहिलोपटक संसदीय निर्वाचन कहिले सम्पन्न भएको छ ?', E'२०२६ फेब्रुअरी १०', E'२०२६ फेब्रुअरी ११', E'२०२६ फेब्रुअरी १२', E'२०२६ फेब्रुअरी ९', 'C', E'बंगलादेशमा जुलाई-अगस्ट २०२४ को विद्यार्थी आन्दोलन (जेनजी विद्रोह) पछि पहिलोपटक संसदीय निर्वाचन **२०२६ फेब्रुअरी १२** मा सम्पन्न भएको छ। यो निर्वाचन शेख हसिनाको १५ वर्षे शासनको अन्त्यपछि भएको थियो, जसमा ३ सय प्रत्यक्ष सिटका लागि चुनाव र जनमतसंग्रह एकसाथ गरिएको थियो।', 'nepali'),
      (v_set_id, 9, E'आदिवासी ज्ञान सम्मेलन, २०८२ सञ्चालन मिति कुन विकल्प सहि रहेको छ ?', E'२०८२ माघ २१ देखि २३', E'२०८२ माघ २३ देखि २५', E'२०८२ माघ २५ देखि २७', E'२०८२ माघ २७ देखि २९', 'C', E'आदिवासी ज्ञान सम्मेलन **वि.सं. २०८२ माघ २५ गते देखि २७ सम्म** काठमाण्डौमा सञ्चालन भएको थियो। ''ज्ञानको साझा प्रदान, धरोहरको संरक्षण, भविष्यको निर्माण'' मूल नारा रहेको यस सम्मेलनको शुभारम्भ राष्ट्रपति रामचन्द्र पौडेलले गर्नुभएको थियो।\nनोट: यो सम्मेलन राष्ट्रिय आदिवासी जनजाति विकास प्रतिष्ठान (एनएफडीन) ले आयोजना गरेको हो।', 'nepali'),
      (v_set_id, 10, E'नेपाल राष्ट्र बैंक अनुसार आर्थिक वर्ष २०८२/८३ को छ महिना (२०८२ पुससम्म) को तथ्यांकमा आधारित नेपालको ६ महिनाको औसत मुद्रास्फीति कति प्रतिशत रहेको छ ?', E'५.७० प्रतिशत', E'२.७० प्रतिशत', E'३.७० प्रतिशत', E'४.७० प्रतिशत', 'A', E'नेपाल राष्ट्र बैंकको तथ्यांक अनुसार आर्थिक वर्ष २०८२/८३ को पहिलो छ महिनामा नेपालको औसत मुद्रास्फीति **५.७० प्रतिशत** रहेको थियो।\nनोट: सोही अवधिमा कुल विदेशी विनिमय सञ्चिति रु. ३,२४२ अर्ब ४५ करोड पुगेको थियो।', 'nepali'),
      (v_set_id, 11, E'अन्तर्राष्ट्रिय मानव भ्रातृत्व दिवस प्रत्येक वर्ष कुन दिन मनाइन्छ ?', E'फेब्रुअरी १', E'फेब्रुअरी २', E'फेब्रुअरी ३', E'फेब्रुअरी ४', 'D', E'अन्तर्राष्ट्रिय मानव भ्रातृत्व दिवस प्रत्येक वर्ष **फेब्रुअरी ४** मा मनाइन्छ। यो दिवस सन् २०२० मा संयुक्त राष्ट्र संघ (UN) द्वारा स्थापित भएको थियो।\nनोट: सन् २०२६ को लागि यस दिवसको नारा ''Dialogue Over Division'' रहेको थियो।', 'nepali'),
      (v_set_id, 12, E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार सार्क मुलुक मध्ये सबैभन्दा कम भ्रष्टाचार हुने मुलुक कुन हो?', E'माल्दिभ्स', E'श्रीलंका', E'भुटान', E'अफगानिस्तान', 'C', E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार सार्क मुलुकहरूमध्ये सबैभन्दा कम भ्रष्टाचार हुने मुलुक **भुटान** हो। भुटानले ७१ अंक प्राप्त गरी विश्वमा १७ औं स्थान हासिल गरेको छ।\n- माल्दिभ्स ३९ अंकका साथ ९१ औं स्थानमा छ।\n- श्रीलंका ३५ अंकका साथ १०७ औं स्थानमा छ।\n- अफगानिस्तान १६ अंकका साथ १६९ औं स्थानमा रही सार्क मुलुकमा सबैभन्दा बढी भ्रष्टाचार हुने मुलुक हो।', 'nepali'),
      (v_set_id, 13, E'२५ औं शीतकालीन ओलम्पिक खेल २०२६ को आयोजक देश कुन हो?', E'इटाली', E'स्पेन', E'फ्रान्स', E'जर्मनी', 'A', E'२५ औं शीतकालीन ओलम्पिक खेलकुद **इटालीमा** आयोजना भएको थियो। यो खेलकुद सन् २०२६ फेब्रुअरी ६ देखि २२ सम्म सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 14, E'२०२६ मार्चमा आयोजना हुन लागेको पाकिस्तान सुपर लिगमा कुन नेपाली खेलाडी सहभागी हुँदैछन्?', E'सन्दिप लामिछाने', E'कुशल भुर्तेल', E'दिपेन्द्र सिंह ऐरी', E'रोहित पौडेल', 'C', E'२०२६ मार्चमा आयोजना भएको पाकिस्तान सुपर लिगमा नेपाली खेलाडी **दिपेन्द्र सिंह ऐरी** सहभागी भएका थिए। उनलाई इस्लामावाद युनाइटेडले ६० लाख पाकिस्तानी रुपैयाँमा अनुबन्ध गरेको थियो।\n- सन्दिप लामिछाने भने २०२६ को बंगलादेश प्रिमियर लिगमा सहभागी भएका थिए।', 'nepali'),
      (v_set_id, 15, E'नवौं हिन्द महासागर सम्मेलन २०२६ कहाँ आयोजना हुँदैछ?', E'मौरिसस', E'ओमान', E'भारत', E'नेपाल', 'A', E'नवौं हिन्द महासागर सम्मेलन २०२६ **मौरिससमा** आयोजना भएको थियो। यो सम्मेलन २०२६ अप्रिल १० देखि १२ सम्म सम्पन्न भएको थियो।\n- आठौं हिन्द महासागर सम्मेलन भने ओमानको मस्कटमा २०२५ फेब्रुअरी १६ र १७ मा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 16, E'संयुक्त राष्ट्र संघमा मान्यता प्राप्त ६ भाषाको सूचीमा देहायको कुन भाषा पर्दैन ?', E'फ्रेन्च', E'स्पेनिस', E'जापानीज', E'अरबी', 'C', E'संयुक्त राष्ट्र संघका ६ वटा आधिकारिक भाषाहरू छन्, जसमा **जापानीज भाषा पर्दैन**। ती भाषाहरू स्पेनिस (Spanish), रसियन (Russian), फ्रेन्च (French), अरबी (Arabic), चाइनिज (Chinese) र अंग्रेजी (English) हुन्।\nनोट: यी भाषाहरूलाई सम्झनका लागि ''SURFACE'' सूत्र प्रयोग गर्न सकिन्छ।', 'nepali'),
      (v_set_id, 17, E'एक गाउँ एक उत्पादन कार्यक्रम (OVOP) हाल नेपालका कति जिल्लामा सञ्चालित छ ?', E'४२ जिल्ला', E'३२ जिल्ला', E'७७ जिल्ला', E'६६ जिल्ला', 'A', E'एक गाउँ एक उत्पादन कार्यक्रम (OVOP) हाल नेपालका **४२ जिल्लामा** सञ्चालित छ।\nनोट: नेपालमा यो कार्यक्रम आर्थिक वर्ष २०६३/६४ को बजेटमार्फत दोलखा जिल्लाको सोता खेतीबाट सुरु भएको थियो।', 'nepali'),
      (v_set_id, 18, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा लैङ्गिक अनुपात कति रहेको छ ?', E'९५.५९ अनुपात', E'९५.१६ अनुपात', E'९४.१६ अनुपात', E'९४.५९ अनुपात', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा लैङ्गिक अनुपात **९५.५९** रहेको छ।\nनोट: लैङ्गिक अनुपात भन्नाले प्रति १०० जना महिलामा पुरुषको संख्यालाई जनाउँछ। अर्थात्, प्रत्येक १०० महिलाको तुलनामा ९५.५९ पुरुष छन्।', 'nepali'),
      (v_set_id, 19, E'Father of botany (वनस्पति विज्ञानका पिता) का रुपमा कुन वैज्ञानिकलाई चिनिन्छ ?', E'चार्ल्स डार्विन', E'एरिस्टोटल', E'रोबर्ट बोइल', E'थियोफ्रेस्टस', 'D', E'**थियोफ्रेस्टसलाई वनस्पति विज्ञानका पिता (Father of Botany) का रूपमा चिनिन्छ।**\n- चार्ल्स डार्विनलाई विकासवादका पिता (Father of Evolution) भनिन्छ।\n- एरिस्टोटललाई जीवविज्ञान, प्राणीशास्त्र र राजनीतिशास्त्रका पिता (Father of Biology/Zoology/Political Science) मानिन्छ।\n- रोबर्ट बोइललाई रसायनशास्त्रका पिता (Father of Chemistry) का रूपमा चिनिन्छ।', 'nepali'),
      (v_set_id, 20, E'लिच्छवि राजा गुणकामदेवले चलाएका जात्राहरू अन्तर्गत देहाएको कुन जात्रा पर्दैन ?', E'श्रीइष्टभरी जात्रा', E'कृष्ण जात्रा', E'हिले जात्रा', E'विस्केट जात्रा', 'D', E'**विस्केट जात्रा लिच्छवि राजा गुणकामदेवले चलाएका जात्राहरूमा पर्दैन।**\n- श्रीइष्टभरी जात्रा, कृष्ण जात्रा र हिले जात्रा गुणकामदेवले चलाएका प्रमुख जात्राहरू हुन्।\n- विस्केट जात्राको चलन भक्तपुरका राजा जगज्योति मल्लले चलाएका थिए।\n- गुणकामदेवले चलाएका अन्य जात्राहरूमा लाखे जात्रा, इन्द्र जात्रा र कुमारी जात्रा पनि पर्दछन्।', 'nepali'),
      (v_set_id, 21, E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनसंख्याले बोल्ने भाषा कुन हो ?', E'नुराङ', E'कुसुन्डा', E'वनकरिया', E'राउटे', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम वक्ता भएको भाषा **कुसुन्डा** हो।\n- यो भाषा बोल्ने वक्ताहरूको संख्या जम्मा २३ जना रहेको छ।\nनोट: सोही जनगणना अनुसार सबैभन्दा कम जनसंख्या भएको जाति भने नुराङ हो, जसको जनसंख्या ३६ रहेको छ।', 'nepali'),
      (v_set_id, 22, E'हिमाली जिल्लामा स्तरोन्नती हुने सबैभन्दा पछिल्लो (कान्छो) हिमाली जिल्ला कुन हो ?', E'म्याग्दी', E'रुकुम पूर्व', E'गोर्खा', E'धादिङ', 'A', E'हिमाली जिल्लामा स्तरोन्नती हुने सबैभन्दा पछिल्लो जिल्ला **म्याग्दी** हो। नेपाल सरकारले म्याग्दीलाई २०७५ फागुन १९ गते हिमाली जिल्लामा स्तरोन्नती गर्ने निर्णय गरेको थियो।\nनोट: यसअघि २०७४ भदौ २५ मा रामेछाप, धादिङ, गोर्खा र पूर्वी रुकुमलाई हिमाली जिल्लामा स्तरोन्नती गरिएको थियो।', 'nepali'),
      (v_set_id, 23, E'अमेरिकाद्वारा जापानको नागासाकी सहरमा फ्याट म्यान नामको बम कहिले प्रहार गर्यो?', E'१९४५ अगस्ट ३', E'१९४५ अगस्ट ६', E'१९४५ अगस्ट ९', E'१९४३ अगस्ट ६', 'C', E'अमेरिकाले जापानको नागासाकी सहरमा ''फ्याट म्यान'' नामक अणु बम **१९४५ अगस्ट ९** मा खसालेको थियो।\nनोट: यसको तीन दिन अघि, अर्थात् १९४५ अगस्ट ६ मा, हिरोसिमा सहरमा ''लिटल ब्वाई'' नामक पहिलो अणु बम खसालिएको थियो।', 'nepali'),
      (v_set_id, 24, E'सबैभन्दा धेरै स्थानीय तह भएको पहाडी जिल्ला कुन हो ?', E'धादिङ', E'काभ्रे', E'काठमाडौं', E'सर्लाही', 'B', E'सबैभन्दा धेरै स्थानीय तह भएको पहाडी जिल्ला **काभ्रे** हो, जहाँ १३ वटा स्थानीय तह छन्।\n- धादिङ १३ वटा स्थानीय तहसहित सबैभन्दा धेरै स्थानीय तह भएको हिमाली जिल्ला हो।\n- सर्लाही २० वटा स्थानीय तहसहित सबैभन्दा धेरै स्थानीय तह भएको तराईको जिल्ला हो।\n- काठमाडौं उपत्यकाको एक जिल्ला हो, तर यसमा पहाडी जिल्लाहरूमध्ये सबैभन्दा धेरै स्थानीय तह छैनन्।', 'nepali'),
      (v_set_id, 25, E'नेपालमा नगरपालिका मात्र भएका जिल्लाको संख्या कति रहेको छ ?', E'४ वटा', E'३ वटा', E'२ वटा', E'५ वटा', 'C', E'नेपालमा नगरपालिका मात्र भएका जिल्लाको संख्या **२ वटा** रहेको छ। ती जिल्लाहरू काठमाडौं र भक्तपुर हुन्।\nनोट: गाउँपालिका मात्र भएका जिल्लाहरूको संख्या ५ रहेको छ, जसमा मनाङ, मुस्ताङ, पूर्वी रुकुम, रसुवा र हुम्ला पर्दछन्।', 'nepali'),
      (v_set_id, 26, E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार नेपालमा पहाडी जिल्लाका रुपमा कति जिल्ला सुचिकृत गरेको छ ?', E'३५ जिल्ला', E'२१ जिल्ला', E'२८ जिल्ला', E'३२ जिल्ला', 'C', E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार नेपालमा **२८ जिल्ला** लाई पहाडी जिल्लाका रूपमा सुचिकृत गरिएको छ।\nनोट: सोही ऐन अनुसार हिमाली जिल्ला २१, तराईका जिल्ला १८, भित्री मधेशका जिल्ला ७ र काठमाडौं उपत्यकाका जिल्ला ३ वटा रहेका छन्।', 'nepali'),
      (v_set_id, 27, E'नेपालको इतिहासका चारसहिद मध्ये पहिलो सहिद पहिचान गरि उनलाई मृत्युदण्ड दिइएको स्थानको सहि विकल्प छनोट गर्नुहोस् ?', E'सिफलमा', E'टेकुमा', E'शोभा भगवतीमा', E'मनकामना मन्दिर', 'B', E'नेपालका चार सहिदमध्ये पहिलो सहिद शुक्रराज शास्त्रीलाई **टेकुमा** मृत्युदण्ड दिइएको थियो।\n- सिफलमा धर्मभक्त माथेमालाई झुन्ड्याएर मृत्युदण्ड दिइएको थियो।\n- शोभा भगवतीमा दशरथ चन्द र गंगालाल श्रेष्ठलाई गोली हानी मृत्युदण्ड दिइएको थियो।\n- मनकामना मन्दिर अगाडि नेपालका प्रथम सहिद लखन थापालाई वि.सं. १९३३ मा फाँसी दिइएको थियो।', 'nepali'),
      (v_set_id, 28, E'नेपालको उत्तर दक्षिण औसत चौडाइ कति रहेको छ ?', E'१९३ किमी', E'२४१ कि.मी', E'१४५ कि.मी', E'८८५ कि.मी', 'A', E'नेपालको उत्तर-दक्षिण औसत चौडाइ **१९३ किलोमिटर** रहेको छ। नेपालको उत्तर-दक्षिण चौडाइ बढीमा २४१ कि.मि. र कममा १४५ कि.मि. रहेको छ।\nनोट: नेपालको पूर्व-पश्चिम औसत लम्बाइ ८८५ किलोमिटर छ।', 'nepali'),
      (v_set_id, 29, E'नेपालको भूगोलमा उपमहानगरपालिका भएको तर महानगरपालिका नभएका प्रदेशको संख्या कति रहेको छ ?', E'१ वटा', E'२ वटा', E'३ वटा', E'४ वटा', 'B', E'नेपालमा उपमहानगरपालिका भएका तर महानगरपालिका नभएका प्रदेशहरूको संख्या **२ वटा** रहेको छ। ती प्रदेशहरू लुम्बिनी प्रदेश र सुदूरपश्चिम प्रदेश हुन्।\nनोट: गण्डकी प्रदेशमा महानगरपालिका (पोखरा) छ तर कुनै उपमहानगरपालिका छैन।', 'nepali'),
      (v_set_id, 30, E'लेप्चा जातिको मुख्य बसोबास क्षेत्र जिल्ला कुन हो ?', E'दोलखा', E'ताप्लेजुङ', E'धनकुटा', E'इलाम', 'D', E'लेप्चा जातिको मुख्य बसोबास क्षेत्र **इलाम जिल्ला** हो। यो जाति नेपालको एक अल्पसंख्यक आदिवासी जनजाति हो।\nनोट: लेप्चा जातिमा दुलहाले ६ महिनासम्म ससुरालीमै बस्नुपर्ने, केटी माग्न जाँदा सिस्नो लगाई सहनशीलता परीक्षण गर्ने जस्ता अनौठा चलनहरू प्रचलित छन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१०/२९', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_03.csv  →  आसमान दैनिक GK — २०८२/११/०३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/०३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/०३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/०३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'हालसम्म जीवित मानिने राजा को हुन्?', E'रण ब. शाह', E'योगनरेन्द्र मल्ल', E'जयप्रकाश मल्ल', E'जयस्थिति मल्ल', 'B', E'पाटनका मल्ल राजा **योगनरेन्द्र मल्ल**लाई हालसम्म जीवित मानिने राजाको रूपमा चिनिन्छ।\nनोट: उनले ''जबसम्म मेरो सालिकमाथि रहेको चरा उडेर जाँदैन, तबसम्म मलाई जीवित नै सम्झनु'' भनेका थिए भन्ने जनविश्वास छ।', 'nepali'),
      (v_set_id, 2, E'प्रथम विश्वयुद्धपछि जर्मनीमा उदाएको शासन व्यवस्था के रहेको थियो?', E'साम्यवाद', E'फाँसिवाद', E'नाजीवाद', E'समाजवाद', 'C', E'प्रथम विश्वयुद्धपछि जर्मनीमा **नाजीवाद** शासन व्यवस्था उदाएको थियो।\n- फाँसीवाद (Fascism) इटालीमा बेनिटो मुसोलिनीको नेतृत्वमा विकास भएको थियो।\nनोट: नाजीवादलाई फाँसीवादको जर्मन रूप मानिन्छ र यसको नेतृत्व हिटलरले गरेका थिए।', 'nepali'),
      (v_set_id, 3, E'महाभारत पहाडको दोस्रो अग्लो टाकुरा कुन हो?', E'फुलचोकी', E'गार्वा', E'शैलुङ', E'ट्याम्के', 'D', E'महाभारत पर्वत शृङ्खलाको दोस्रो अग्लो टाकुरा **ट्याम्के** हो।\n- शैलुङ महाभारत पर्वतको सबैभन्दा अग्लो टाकुरा हो।\nनोट: ट्याम्के टाकुरा खोटाङ र भोजपुर जिल्लाको सिमानामा पर्दछ।', 'nepali'),
      (v_set_id, 4, E'अन्टार्कटिका महादेशको सबैभन्दा ठूलो ताल कुन हो?', E'आइरा ताल', E'भिक्टोरिया ताल', E'बैकाल ताल', E'भोस्तोक ताल', 'D', E'**अन्टार्कटिका महादेशको सबैभन्दा ठूलो ताल भोस्तोक ताल हो।**\n- आइरा ताल अष्ट्रेलिया महादेशको सबैभन्दा ठूलो ताल हो।\n- भिक्टोरिया ताल अफ्रिका महादेशको सबैभन्दा ठूलो ताल हो।\n- बैकाल ताल एसिया महादेशको सबैभन्दा ठूलो ताल हो।\nनोट: विश्वको सबैभन्दा ठूलो ताल क्यास्पियन सागर हो, जुन युरेशियामा पर्दछ।', 'nepali'),
      (v_set_id, 5, E'सौर्यमण्डलका आठ वटा ग्रहहरू मध्ये चुम्बकीय क्षेत्र नभएको दुई ग्रहहरू कुन कुन हुन्?', E'शनि र वृहस्पति', E'बुध र शुक्र', E'वरुण र अरुण', E'शुक्र र मंगल', 'D', E'**सौर्यमण्डलका आठ ग्रहहरूमध्ये शुक्र र मंगल ग्रहमा चुम्बकीय क्षेत्र छैन।**\n- शनि र वृहस्पति दुवैमा शक्तिशाली चुम्बकीय क्षेत्र रहेको छ।\n- बुध र शुक्र सौर्यमण्डलका उपग्रह नभएका ग्रहहरू हुन्।\n- वरुण र अरुण दुवैमा चुम्बकीय क्षेत्र रहेको छ।', 'nepali'),
      (v_set_id, 6, E'सबै नागरिक कानूनको दृष्टिमा समान हुनेछन्। माथिको कथन कुन मौलिक हकसँग सम्बन्धित रहेको छ?', E'न्याय सम्बन्धि हक', E'समानताको हक', E'महिलाको हक', E'सम्पत्तिको हक', 'B', E'नेपालको संविधानको **धारा १८** मा व्यवस्था भए अनुसार, "सबै नागरिक कानूनको दृष्टिमा समान हुनेछन्" भन्ने कथन समानताको हकसँग सम्बन्धित छ। यस हक अन्तर्गत कसैलाई पनि कानूनको समान संरक्षणबाट वञ्चित गरिने छैन र समान कामका लागि लैंगिक आधारमा पारिश्रमिक तथा सामाजिक सुरक्षामा कुनै भेदभाव गरिने छैन।', 'nepali'),
      (v_set_id, 7, E'सानो दुधालु गाई कार्यक्रम सञ्चालित जिल्ला कुन हो?', E'कास्की', E'अछाम', E'ललितपुर', E'नुवाकोट', 'B', E'**सानो दुधालु गाई कार्यक्रम अछाम जिल्लामा सञ्चालित छ।**\n- कास्की जिल्लामा आलु उत्पादन कार्यक्रम सञ्चालित छ।\n- ललितपुरको खुमलटारमा च्याउको बीउ उत्पादन कार्यक्रम सञ्चालित छ।\n- नुवाकोट जिल्लामा ट्राउट माछा कार्यक्रम सञ्चालित रहेको छ।', 'nepali'),
      (v_set_id, 8, E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार विश्वमा सबैभन्दा कम भ्रष्टाचार हुने मुलुक कुन हो?', E'डेनमार्क', E'फिनल्याण्ड', E'सिंगापुर', E'न्युजिल्याण्ड', 'A', E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार **डेनमार्क** विश्वमा सबैभन्दा कम भ्रष्टाचार हुने मुलुक हो। डेनमार्कले ८९ अंक प्राप्त गरी पहिलो स्थान हासिल गरेको छ। यस सूचकांकमा फिनल्याण्ड (८८ अंक) दोस्रो र सिंगापुर (८४ अंक) तेस्रो स्थानमा रहेका छन्।\nनोट: सोही सूचकांक अनुसार, साउथ सुडान र सोमालिया सबैभन्दा बढी भ्रष्टाचार हुने मुलुकहरू हुन्।', 'nepali'),
      (v_set_id, 9, E'हालसालै कुन मुलुकको पहिलो महिला प्रधानमन्त्रीको रुपमा सानाई ताकाइची प्रधानमन्त्री बनिन?', E'बेलायत', E'द. कोरिया', E'जापान', E'माल्दिभ्स', 'C', E'सन् २०२४ अक्टोबर २१ मा संसदको दुवै सदनमा बहुमत प्राप्त गर्दै सानाई ताकाइची **जापानको पहिलो महिला प्रधानमन्त्रीमा** निर्वाचित भएकी हुन्। उनी ''जापानको आइरन लेडी'' भनेर पनि चिनिन्छिन्।\nनोट: जापानको प्रधानमन्त्री बन्ने यो ताकाइचीको तेस्रो प्रयास थियो।', 'nepali'),
      (v_set_id, 10, E'साफ्टा (SAFTA) मा नेपालको तर्फबाट हस्ताक्षर कस्ले गरेका हुन्?', E'महेश आचार्य', E'भेषबहादुर थापा', E'बाबुराम भट्टराई', E'सुशील कोइराला', 'B', E'दक्षिण एसियाली स्वतन्त्र व्यापार क्षेत्र (SAFTA) सम्झौतामा नेपालको तर्फबाट **भेषबहादुर थापाले** हस्ताक्षर गरेका हुन्।\n- महेश आचार्यले साप्टा (SAPTA) मा नेपालको तर्फबाट हस्ताक्षर गरेका थिए।\n- बाबुराम भट्टराई र सुशील कोइराला नेपालका पूर्व प्रधानमन्त्रीहरू हुन्।\nनोट: साफ्टा सम्झौतामा सन् २००४ जनवरी ६ मा हस्ताक्षर भई सन् २००६ जनवरी १ देखि लागू भएको थियो।', 'nepali'),
      (v_set_id, 11, E'एन्टोनियो गुटेरेस पहिलो कार्यकालको लागि कहिले संयुक्त राष्ट्रसंघ महासचिव भएका थिए?', E'सन् २०१७', E'सन् २०१६', E'सन् २०१९', E'सन् २०२०', 'A', E'एन्टोनियो गुटेरेस संयुक्त राष्ट्रसंघको महासचिवको रूपमा पहिलो कार्यकालका लागि **सन् २०१७** जनवरी १ मा नियुक्त भएका थिए। उनको पहिलो कार्यकाल २०२१ डिसेम्बर ३१ सम्म रहेको थियो।\nनोट: उनको दोस्रो कार्यकाल २०२२ जनवरी १ देखि सुरु भई २०२६ डिसेम्बर ३१ सम्म रहनेछ।', 'nepali'),
      (v_set_id, 12, E'मनास्लु संरक्षण क्षेत्र नेपालको कुन कुन जिल्लामा अवस्थित रहेको छ?', E'गोरखा र मुस्ताङ', E'मनाङ र मुस्ताङ', E'गोरखा र मनाङ', E'रामेछाप र दोलखा', 'C', E'मनास्लु संरक्षण क्षेत्र **गोरखा र मनाङ** जिल्लामा अवस्थित छ।\n- मुस्ताङ जिल्लामा अन्नपूर्ण संरक्षण क्षेत्र पर्दछ।\n- रामेछाप र दोलखा जिल्लाहरूमा गौरीशङ्कर संरक्षण क्षेत्र फैलिएको छ।\nनोट: मनास्लु संरक्षण क्षेत्रको स्थापना वि.सं. २०५५ (सन् १९९८) मा भएको हो।', 'nepali'),
      (v_set_id, 13, E'Oxygenated and Deoxygenated के सँग सम्बन्धित रहेको छ?', E'श्वासप्रश्वास प्रणाली', E'स्नायु प्रणाली', E'पाचन प्रणाली', E'रक्तसञ्चार प्रणाली', 'D', E'Oxygenated (अक्सिजनयुक्त) र Deoxygenated (अक्सिजनरहित) रगत **रक्तसञ्चार प्रणालीसँग** सम्बन्धित शब्दहरू हुन्। Oxygenated रगतलाई शुद्ध रगत र Deoxygenated रगतलाई अशुद्ध रगत पनि भनिन्छ।', 'nepali'),
      (v_set_id, 14, E'चन्द्रमाको अध्ययन गर्ने (The study of the moon) विज्ञानलाई के भनिन्छ?', E'Seismology', E'Psychology', E'Moonlogy', E'Selenology', 'D', E'चन्द्रमाको अध्ययन गर्ने विज्ञानलाई **Selenology** भनिन्छ।\n- Seismology भूकम्प सम्बन्धी अध्ययन गर्ने शास्त्र हो।\n- Psychology मनोविज्ञान अर्थात् मानव व्यवहार र मानसिक प्रक्रियाको अध्ययन हो।\n- Moonlogy सामान्यतया प्रयोगमा नभएको शब्द हो, सही वैज्ञानिक शब्द Selenology नै हो।', 'nepali'),
      (v_set_id, 15, E'ललितकला अन्तर्गत देहायको कुन पर्दैन?', E'चित्रकला', E'मूर्तिकला', E'वास्तुकला', E'नृत्यकला', 'D', E'नृत्यकला ललितकला अन्तर्गत पर्दैन, यो **प्रदर्शनकारी कला (Performing Arts)** हो।\n- चित्रकला घटना तथा तथ्यको चित्र निर्माणसँग सम्बन्धित कला हो।\n- मूर्तिकला काठ, ढुङ्गा तथा धातुलाई मूर्तिको आकारमा ढाल्ने कला हो।\n- वास्तुकला घर, दरबार, पाटीपौवा, मन्दिर आदिको निर्माणसँग सम्बन्धित कला हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/०३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_04.csv  →  आसमान दैनिक GK — २०८२/११/०४  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/०४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/०४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/०४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'प्रसिद्ध मन्दिर रानीमहल कति वर्ष लगाएर निमार्ण गरिएको थियो ?', E'२० वर्ष', E'१० वर्ष', E'१५ वर्ष', E'२५ वर्ष', 'B', E'नेपालको ताजमहल भनेर चिनिने पाल्पाको रानीमहल **१० वर्ष** लगाएर निर्माण गरिएको थियो। यो महल खड्ग शमशेरले आफ्नी रानी तेजकुमारीको सम्झनामा निर्माण गराएका हुन्।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधानको कुन धारामा सञ्चारको हक सम्बन्धि व्यवस्था गरेको छ ?', E'धारा २१', E'धारा २७', E'धारा १९', E'धारा २४', 'C', E'नेपालको संविधानको **धारा १९** मा सञ्चारको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा २१ मा अपराध पीडितको हकको व्यवस्था छ।\n- धारा २७ मा सूचनाको हकको व्यवस्था छ।\n- धारा २४ मा छुवाछुत तथा भेदभाव विरुद्धको हकको व्यवस्था छ।', 'nepali'),
      (v_set_id, 3, E'नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो आसियान मुलुक कुन हो ?', E'सिंगापुर', E'मलेसिया', E'थाइल्याण्ड', E'इण्डोनेसिया', 'C', E'नेपालसँग दौत्य सम्बन्ध कायम भएको पहिलो आसियान मुलुक **थाइल्याण्ड** हो। नेपाल र थाइल्याण्डबीच सन् १९५९ नोभेम्बर ३० मा दौत्य सम्बन्ध स्थापना भएको थियो।\nनोट: नेपालसँग दौत्य सम्बन्ध कायम गर्ने अन्तिम आसियान मुलुक पूर्वी टिमोर हो, जससँग सन् २०२२ फेब्रुअरी ११ मा सम्बन्ध स्थापित भएको थियो।', 'nepali'),
      (v_set_id, 4, E'आर्थिक तथा सामाजिक परिषदका सदस्य मध्ये कति सदस्यहरु एसिया महादेशका रहेको हुन्छन् ?', E'१२ मुलुक', E'११ मुलुक', E'१३ मुलुक', E'१४ मुलुक', 'B', E'संयुक्त राष्ट्र संघको आर्थिक तथा सामाजिक परिषद (ECOSOC) मा एसिया महादेशबाट **११ सदस्य** राष्ट्रहरू रहेका हुन्छन्।\nनोट: ECOSOC मा कुल ५४ सदस्य राष्ट्रहरू हुन्छन्, जसको निर्वाचन महासभाले ३ वर्षे कार्यकालका लागि गर्दछ।', 'nepali'),
      (v_set_id, 5, E'संयुक्त राष्ट्रसंघ (UNO) कसको अवधारणा हो ?', E'जियाउल रहमान', E'विड्रो विल्सन', E'फ्र्याङ्कलिन डि रुजवेल्ट', E'दानुक टुङ रहमान', 'C', E'संयुक्त राष्ट्रसंघ (UNO) को अवधारणा ३२ औं अमेरिकी राष्ट्रपति **फ्र्याङ्कलिन डि रुजवेल्टले** ल्याएका हुन्।\n- जियाउल रहमान सार्क (SAARC) का अवधारणाकार हुन्, जो बंगलादेशका राष्ट्रपति थिए।\n- विड्रो विल्सनले राष्ट्रसंघ (League of Nations) को अवधारणा ल्याएका थिए, जो २८ औं अमेरिकी राष्ट्रपति थिए।\n- दानुक टुङ रहमान आसियान (ASEAN) का अवधारणाकार हुन्, जो मलेसियाका प्रधानमन्त्री थिए।', 'nepali'),
      (v_set_id, 6, E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनघनत्व भएको जिल्ला मनाङमा जनघनत्व कति रहेको छ ?', E'५ जना प्रतिवर्ग कि मि', E'३ जना प्रतिवर्ग कि मि', E'४ जना प्रतिवर्ग कि मि', E'६ जना प्रतिवर्ग कि मि', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार सबैभन्दा कम जनघनत्व भएको जिल्ला मनाङको जनघनत्व **३ जना प्रतिवर्ग किलोमिटर** रहेको छ।\nनोट: नेपालको समग्र जनघनत्व १९८ जना प्रतिवर्ग किलोमिटर छ भने सबैभन्दा बढी जनघनत्व काठमाडौं जिल्लाको (५१६९ जना प्रतिवर्ग किलोमिटर) रहेको छ।', 'nepali'),
      (v_set_id, 7, E'तलका मध्ये कुन महादेशमा भूपरिवेष्ठित मुलुक छैनन् ?', E'युरोप', E'अफ्रिका', E'दक्षिण अमेरिका', E'उत्तर अमेरिका', 'D', E'**उत्तर अमेरिका** महादेशमा कुनै पनि भूपरिवेष्ठित मुलुक छैनन्।\n- युरोपमा १४ वटा भूपरिवेष्ठित मुलुकहरू छन्।\n- अफ्रिकामा १६ वटा भूपरिवेष्ठित मुलुकहरू छन्।\n- दक्षिण अमेरिकामा २ वटा भूपरिवेष्ठित मुलुकहरू (बोलिभिया र पाराग्वे) छन्।\nनोट: भूपरिवेष्ठित राष्ट्र नभएका अन्य महादेशहरू अष्ट्रेलिया र अन्टार्कटिका हुन्।', 'nepali'),
      (v_set_id, 8, E'नेपाल सरकार र माओवादी बीच विस्तृत शान्ति सम्झौता कहिले भयो ?', E'२०६३ मंसिर ५', E'२०६३ बैशाख ११', E'२०६३ माघ १', E'२०६३ चैत २८', 'A', E'नेपाल सरकार र तत्कालीन नेकपा (माओवादी) बीच विस्तृत शान्ति सम्झौता **वि.सं. २०६३ मंसिर ५** गते भएको थियो।\nनोट: यो सम्झौताले वि.सं. २०५२ फागुन १ गतेदेखि सुरु भएको दश वर्षे सशस्त्र द्वन्द्वको औपचारिक अन्त्य गरेको थियो।', 'nepali'),
      (v_set_id, 9, E'दिगो विकासको लक्ष्य नं. ५ के सँग सम्बन्धित रहेको छ ?', E'गरिबीको अन्त्य', E'गुणस्तरीय शिक्षा', E'लैंगिक समानता', E'सु स्वास्थ्य जिवन', 'C', E'दिगो विकासको लक्ष्य नं. ५ **लैंगिक समानता** र महिला तथा बालबालिकाको सशक्तीकरणसँग सम्बन्धित छ।\n- गरिबीको अन्त्य दिगो विकासको लक्ष्य नं. १ हो।\n- गुणस्तरीय शिक्षा दिगो विकासको लक्ष्य नं. ४ हो।\n- सु स्वास्थ्य जीवन (स्वस्थ जीवनको सुनिश्चितता) दिगो विकासको लक्ष्य नं. ३ हो।', 'nepali'),
      (v_set_id, 10, E'कुन समुन्द्रको सिमानाले तीनवटा महादेश छोएको छ ?', E'क्यारेबियन सागर', E'मेडिटेरियन सागर', E'क्यासपियन सागर', E'ब्ल्याक सागर', 'B', E'**मेडिटेरियन सागर (भूमध्य सागर) को सिमानाले युरोप, एसिया र अफ्रिका गरी तीनवटा महादेशलाई छोएको छ।**', 'nepali'),
      (v_set_id, 11, E'राष्ट्रिय जनगणना अनुसार, नेपालको जनसंख्या वृद्धिदर कति प्रतिशत रहेको छ ?', E'२.२५ %', E'१.३५ %', E'०.९२ %', E'०.८२ %', 'C', E'राष्ट्रिय जनगणना २०७८ अनुसार नेपालको वार्षिक जनसंख्या वृद्धिदर **०.९२ प्रतिशत** रहेको छ।\nनोट: जनगणना २०६८ मा यो दर १.३५ प्रतिशत थियो।', 'nepali'),
      (v_set_id, 12, E'गुराँस हिमश्रृंखला अन्तर्गत कुन हिमाल पर्छ ?', E'गणेश', E'चामर', E'अपि', E'तिलिचो', 'C', E'**अपि हिमाल गुराँस हिमश्रृंखला अन्तर्गत पर्दछ।**\n- गणेश हिमाल गणेश हिमशृङ्खलामा पर्दछ।\n- चामर हिमाल श्रीङ्गी हिमशृङ्खला अन्तर्गत पर्दछ।\n- तिलिचो हिमाल अन्नपूर्ण हिमशृङ्खला अन्तर्गत पर्दछ।\nनोट: अपि हिमाल दार्चुला जिल्लामा अवस्थित छ र यसको उचाइ ७,१३२ मिटर छ।', 'nepali'),
      (v_set_id, 13, E'अरुण तेस्रो जलविद्युत आयोजनाको विद्युत उत्पादन क्षमता कति रहेको छ ?', E'१२०० मेगावाट', E'९०० मेगावाट', E'४५६ मेगावाट', E'४४० मेगावाट', 'B', E'अरुण तेस्रो जलविद्युत आयोजनाको विद्युत उत्पादन क्षमता **९०० मेगावाट** रहेको छ।\nनोट: यो आयोजना संखुवासभा जिल्लाको मकालु गाउँपालिकामा अरुण नदीमा निर्माणाधीन छ।', 'nepali'),
      (v_set_id, 14, E'UNO बडापत्र कहिले देखि कार्यान्वयनमा आएको हो ?', E'२६ जुन १९४५', E'२४ सेप्टेम्बर १९४६', E'१५ अक्टोबर १९४५', E'२४ अक्टोबर १९४५', 'D', E'संयुक्त राष्ट्र संघ (UNO) को बडापत्र **२४ अक्टोबर १९४५** देखि कार्यान्वयनमा आएको हो। यही दिनको सम्झनामा हरेक वर्ष संयुक्त राष्ट्र संघ दिवस मनाइन्छ।\nनोट: बडापत्रमा २६ जुन १९४५ मा सान फ्रान्सिस्कोमा हस्ताक्षर भएको थियो।', 'nepali'),
      (v_set_id, 15, E'नेपालको देहाएको कुन मुलुकसँग विप्पा सम्झौता भएको छैन ?', E'चीन', E'जर्मनी', E'भारत', E'बेलायत', 'A', E'नेपालको **चीनसँग** द्विपक्षीय लगानी प्रवर्द्धन तथा संरक्षण सम्झौता (BIPPA) भएको छैन।\n- जर्मनी, भारत र बेलायतसँग नेपालको विप्पा सम्झौता भएको छ।\nनोट: नेपालले हालसम्म फ्रान्स, भारत, फिनल्याण्ड, मौरिसस, जर्मनी र बेलायत गरी जम्मा ६ वटा मुलुकसँग विप्पा सम्झौता गरेको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/०४', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_06.csv  →  आसमान दैनिक GK — २०८२/११/०६  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/०६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/०६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/०६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'मातृभाषा दिवस हरेक वर्ष कुन तारिखमा मनाइन्छ ?', E'फेब्रुअरी २३', E'फेब्रुअरी २२', E'फेब्रुअरी २१', E'फेब्रुअरी २४', 'C', E'अन्तर्राष्ट्रिय मातृभाषा दिवस हरेक वर्ष **फेब्रुअरी २१** मा मनाइन्छ।\nनोट: नेपालमा सन् २०१२ देखि औपचारिक रूपमा यो दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 2, E'''Point four programme'' के सँग सम्बन्धित छ ?', E'वैदेशिक सहयोग', E'वैदेशिक रोजगार', E'व्यापार सम्झौता', E'दौत्य सम्झौता', 'A', E'अमेरिकी राष्ट्रपति ह्यारी एस. ट्रुम्यानद्वारा सुरु गरिएको ''प्वाइन्ट फोर प्रोग्राम'' **वैदेशिक सहयोग**सँग सम्बन्धित छ। यस कार्यक्रम अन्तर्गत अमेरिकाले नेपाललाई पहिलो पटक सन् १९५१ मा आर्थिक सहयोग प्रदान गरेको थियो।\nनोट: अमेरिकाले ''प्वाइन्ट फोर प्रोग्राम'' मार्फत पहिलो पटक $22000 सहयोग गरेको थियो।', 'nepali'),
      (v_set_id, 3, E'२०२६ मा कार्यकाल अन्त्य हुने सुरक्षा परिषदमा ५ सदस्य मध्ये देहाएका मध्ये कुन हो ?', E'पाकिस्तान', E'नेपाल', E'भारत', E'बंगलादेश', 'A', E'**पाकिस्तान** संयुक्त राष्ट्र संघको सुरक्षा परिषदमा सन् २०२५-२०२६ कार्यकालका लागि निर्वाचित अस्थायी सदस्य हो, जसको कार्यकाल सन् २०२६ को अन्त्यमा समाप्त हुनेछ।\n- नेपाल, भारत र बंगलादेश हाल सुरक्षा परिषदका अस्थायी सदस्य छैनन्।\nनोट: पाकिस्तानसँगै पानामा, डेनमार्क, ग्रिस र सोमालिया पनि सन् २०२५-२०२६ कार्यकालका लागि निर्वाचित सदस्य हुन्।', 'nepali'),
      (v_set_id, 4, E'२०८२ सालमा मनाइएको पृथ्वी जन्मजयन्ती कति औं हो ?', E'३०१ औं', E'३०२ औं', E'३०३ औं', E'३०४ औं', 'D', E'वि.सं. २०८२ सालमा **३०४ औं** पृथ्वी जयन्ती मनाइन्छ। पृथ्वीनारायण शाहको जन्म वि.सं. १७७९ पुस २७ गते भएको थियो, र सोही दिनको सम्झनामा हरेक वर्ष पृथ्वी जयन्ती तथा राष्ट्रिय एकता दिवस मनाइन्छ।\nनोट: जन्मजयन्ती गणना गर्दा (वर्तमान वर्ष - जन्म वर्ष + १) सूत्र प्रयोग गरिन्छ, अर्थात् (२०८२ - १७७९ + १) = ३०४।', 'nepali'),
      (v_set_id, 5, E'नेपालमा पहिलोपटक गैरआवासीय नेपाली नागरिकता कहिले प्रदान गरियो ?', E'२०८० असोज ३०', E'२०८० असोज २९', E'२०८० भदौ ३०', E'२०८० भदौ २९', 'A', E'नेपालमा पहिलोपटक **२०८० असोज ३०** मा गैरआवासीय नेपाली नागरिकता प्रदान गरिएको थियो।\nनोट: गैरआवासीय नेपाली नागरिकता प्राप्त गर्ने पहिलो व्यक्तिहरू कुल आचार्य र बद्री केसी हुन्।', 'nepali'),
      (v_set_id, 6, E'बिमस्टेकको वर्तमान महासचिव कुन मुलुकका हुन् ?', E'भुटान', E'बंगलादेश', E'भारत', E'श्रीलंका', 'C', E'बिमस्टेकका वर्तमान महासचिव **भारतका इन्द्रमणी पाण्डे** हुन्। उनले २०२४ जनवरी ४ मा पदभार ग्रहण गरेका थिए।\nनोट: उनी बिमस्टेकका चौथो महासचिव हुन्।', 'nepali'),
      (v_set_id, 7, E'राष्ट्रिय जनगणना, २०७८ अनुसार अपाङ्गता भएका व्यक्ति मध्ये पुरुष कति प्रतिशत रहेको छ ?', E'५४.२ प्रतिशत', E'४५.८ प्रतिशत', E'४९.३१ प्रतिशत', E'५१.३४ प्रतिशत', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार अपाङ्गता भएका कुल व्यक्तिहरूमध्ये **पुरुष ५४.२ प्रतिशत** र महिला ४५.८ प्रतिशत रहेका छन्।\nनोट: कुल जनसंख्याको २.२ प्रतिशतमा कुनै न कुनै प्रकारको अपाङ्गता रहेको पाइएको छ।', 'nepali'),
      (v_set_id, 8, E'सार्कको कुन शिखर सम्मेलन देखि नारा राख्न थालिएको थियो ?', E'सत्रौं', E'सोह्रौं', E'अठारौं', E'पन्ध्रौं', 'B', E'सार्कमा **सोह्रौं शिखर सम्मेलन** देखि नारा राख्न थालिएको हो।\nनोट: यो सम्मेलन सन् २०१० अप्रिल २८-२९ मा भुटानको थिम्पुमा भएको थियो र यसको पहिलो नारा ''Green and happy south asia'' थियो।', 'nepali'),
      (v_set_id, 9, E'नेपालका नदिहरुको भारतको नाममा देहाएका मध्ये कुन विकल्प गलत छ ?', E'महाकाली - महानन्दा', E'बबई - सरयु', E'कर्णाली - घाँघरा', E'कन्काई - बेरिङ', 'A', E'नेपालका नदीहरूको भारतमा भएको नामको सन्दर्भमा **महाकाली - महानन्दा** को जोडा गलत छ। महाकाली नदीलाई भारतमा शारदा भनिन्छ।\n- बबई नदीलाई भारतमा सरयु भनिन्छ।\n- कर्णाली नदीलाई भारतमा घाँघरा भनिन्छ।\n- कन्काई नदीलाई भारतमा बेरिङ भनिन्छ।\nनोट: मेची नदीलाई भारतमा महानन्दा भनिन्छ।', 'nepali'),
      (v_set_id, 10, E'मातृभाषा दिवस हरेक वर्ष कुन तारिखमा मनाइन्छ ?', E'फ्रेबुअरी २३', E'फ्रेबुअरी २२', E'फ्रेबुअरी २१', E'फ्रेबुअरी २४', 'C', E'मातृभाषा दिवस हरेक वर्ष **फ्रेबुअरी २१** मा मनाइन्छ।\nनोट: नेपालमा सन् २०१२ देखि यो दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 11, E'प्रदेश सभा प्रत्यक्ष तर्फ २ वटा निर्वाचन क्षेत्र भएको नेपाली जिल्लाहरु कतिवटा रहेको छन ?', E'३५ वटा', E'२१ वटा', E'१५ वटा', E'३० वटा', 'B', E'नेपालमा प्रदेश सभा प्रत्यक्ष तर्फ २ वटा निर्वाचन क्षेत्र भएका जिल्लाहरु **२१ वटा** रहेका छन्।', 'nepali'),
      (v_set_id, 12, E'सूर्यको विकिरण नाप्न प्रयोग गरिने यन्त्र कुन हो ?', E'हेलिस्कोप', E'पारहेलियोमिटर', E'फोटोमिटर', E'एक्टिमोमिटर', 'B', E'सूर्यको विकिरण नाप्न **पारहेलियोमिटर** प्रयोग गरिन्छ।\n- हेलिस्कोप सूर्यलाई हेर्न प्रयोग गरिने यन्त्र हो।\n- फोटोमिटर सूर्यको प्रकाशको तिव्रता नाप्ने यन्त्र हो।\n- एक्टिमोमिटर सूर्यको किरणको तापीय तिव्रता निश्चित गर्ने उपकरण हो।', 'nepali'),
      (v_set_id, 13, E'नेपालको संविधानमा उल्लेख भए अनुसार नागरिको कर्तव्य कतिवटा रहेको छन ?', E'४ वटा', E'५ वटा', E'६ वटा', E'३ वटा', 'A', E'नेपालको संविधानको धारा ४८ मा नागरिकका **४ वटा** कर्तव्य सम्बन्धी व्यवस्था गरिएको छ।\nनोट: संविधानको भाग ३ मा मौलिक हक र कर्तव्य अन्तर्गत धारा १६ देखि ४६ सम्म ३१ वटा मौलिक हकको व्यवस्था छ।', 'nepali'),
      (v_set_id, 14, E'देहाएका मध्ये कुन विमानस्थल गोर्खा जिल्लामा अवस्थित प्रसिद्ध विमानस्थल हो ?', E'रुम्जाटार', E'पालुङटार', E'चन्दननाथ', E'राँझा', 'B', E'**पालुङटार विमानस्थल गोर्खा जिल्लामा अवस्थित छ।**\n- रुम्जाटार विमानस्थल ओखलढुंगा जिल्लामा पर्दछ।\n- चन्दननाथ विमानस्थल जुम्ला जिल्लामा रहेको छ।\n- राँझा विमानस्थल बाँके जिल्लामा अवस्थित छ।', 'nepali'),
      (v_set_id, 15, E'पछिल्लो कृषि गणना अनुसार नेपालमा सबैभन्दा धेरै आलु खेति हुने जिल्ला कुन हो ?', E'रुपन्देही', E'चितवन', E'धादिङ', E'काभ्रे', 'D', E'पछिल्लो सातौँ कृषि गणना, २०७८ अनुसार, नेपालमा सबैभन्दा धेरै आलु खेती **काभ्रे** जिल्लामा हुने गरेको पाइएको छ।\n- रुपन्देही जिल्लामा सबैभन्दा बढी गहुँ खेती हुन्छ।\n- चितवन जिल्लामा सबैभन्दा बढी तरकारी खेती हुन्छ।\n- धादिङ जिल्ला आलु उत्पादनका लागि प्रसिद्ध भए तापनि गणना अनुसार सबैभन्दा बढी उत्पादन काभ्रेमा हुन्छ।', 'nepali'),
      (v_set_id, 16, E'सबैभन्दा कम उमेरमा प्रधानमन्त्री भएका नेपालका प्रधानमन्त्री को हुन् ?', E'जंग ब राणा', E'देव समसेर', E'मोहन समसेर', E'भिमसेन थापा', 'A', E'नेपालको इतिहासमा सबैभन्दा कम उमेरमा प्रधानमन्त्री हुने व्यक्ति **जंगबहादुर राणा** हुन्।\n- देव समसेर सबैभन्दा थोरै कार्यकाल (११४ दिन) भएका राणा प्रधानमन्त्री थिए।\n- मोहन समसेर राणा शासनका अन्तिम प्रधानमन्त्री थिए।\n- भिमसेन थापा नेपालका प्रथम तथा सबैभन्दा लामो समयसम्म सेवा गर्ने प्रधानमन्त्री थिए।\nनोट: जंगबहादुर राणा २८ वर्षको उमेरमा प्रधानमन्त्री बनेका थिए।', 'nepali'),
      (v_set_id, 17, E'देहाएका मध्ये कुन कुण्ड बझाङ जिल्लामा अवस्थित रहेको छ ?', E'पाप कुण्ड', E'नारद कुण्ड', E'निहारी कुण्ड', E'ज्ञान कुण्ड', 'C', E'**निहारी कुण्ड** बझाङ जिल्लामा अवस्थित छ।\n- पाप कुण्ड मुगु जिल्लामा पर्दछ।\n- नारद कुण्ड गोरखा जिल्लामा अवस्थित छ।\n- ज्ञान कुण्ड धनुषा जिल्लामा पर्दछ।\nनोट: बझाङ जिल्लामा राक्षस कुण्ड पनि अवस्थित छ।', 'nepali'),
      (v_set_id, 18, E'नेपालको अग्लो मानव बस्ति पहिचान गरि उक्त बस्ति देहाएका मध्ये कुन जिल्लामा पर्छ उपयुक्त विकल्प छनोट गर्नुहोस् ?', E'जुम्ला', E'हुम्ला', E'डोल्पा', E'सोलुखुम्बु', 'C', E'नेपालको सबैभन्दा अग्लो मानव बस्ती **डोल्पा** जिल्लामा पर्दछ।\n- जुम्ला जिल्लाको पतारासीमा विश्वको सर्वोच्च उचाइमा धानखेती (जुम्ली मार्सी) गरिन्छ।\n- हुम्ला जिल्लाको सिमीकोट नेपालको सबैभन्दा अग्लो सदरमुकाम हो।\n- सोलुखुम्बु जिल्लामा विश्वको सर्वोच्च शिखर सगरमाथा अवस्थित छ।\nनोट: डोल्पाका छार्काभोट र तरापबस्ती नेपालका अग्ला मानव बस्तीहरू हुन्।', 'nepali'),
      (v_set_id, 19, E'नेपालमा उर्जा दिवस कहिले मनाइन्छ ?', E'जेठ ९', E'जेठ १०', E'जेठ ११', E'जेठ १२', 'A', E'नेपालमा हरेक वर्ष **जेठ ९** गते राष्ट्रिय ऊर्जा दिवस मनाइन्छ।\nनोट: नेपालमा पहिलो पटक वि.सं. १९६८ जेठ ९ गते बिजुली बत्ती बलेको दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 20, E'नेपालमा हालसम्म Plan Holiday वर्ष कति वटा रहेको छन ?', E'५ वटा', E'२ वटा', E'४ वटा', E'३ वटा', 'D', E'नेपालमा हालसम्म **३ वटा** योजनाविहीन वर्ष (Plan Holiday) रहेका छन्। सामान्यतया, एउटा योजना समाप्त भई अर्को योजना प्रारम्भ नहुने अवस्थालाई योजनाविहीन वर्ष भनिन्छ।\nनोट: नेपालमा पहिलोपटक वि.सं. २०१९ मा र दोस्रो पटक वि.सं. २०४७ र २०४८ मा गरी जम्मा ३ वर्ष योजनाविहीन रहेका थिए।', 'nepali'),
      (v_set_id, 21, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा बसाइँसराई गरेको जनसंख्या प्रतिशत कति रहेको छ ?', E'३५.०३ प्रतिशत', E'३३.०३ प्रतिशत', E'३४.०३ प्रतिशत', E'३२.०३ प्रतिशत', 'D', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा बसाइँसराई गरेको जनसंख्या **३२.०३ प्रतिशत** रहेको छ। जनगणना अनुसार १३,४९,४०८ जनाले बसाइँ सरेका थिए।\nनोट: बसाइँसराईको मुख्य कारण विवाह (३८.२%) देखिएको छ।', 'nepali'),
      (v_set_id, 22, E'सबैभन्दा धेरै अवधी महासचिव भएका संयुक्त राष्ट्रसंघका महासचिव को हुन ?', E'ट्रिग्वेली', E'कोफी अन्नान', E'उथान्त', E'वुत्रोस वुत्रोस घाली', 'C', E'**उथान्त संयुक्त राष्ट्रसंघका सबैभन्दा लामो समयसम्म महासचिव हुने व्यक्ति हुन्।**\n- ट्रिग्वेली राजीनामा दिने पहिलो महासचिव थिए।\n- कोफी अन्नान कार्यकाल समाप्त भएपछि अवकाश पाउने महासचिव हुन्।\n- वुत्रोस वुत्रोस-घाली कार्यकाल थप नभएका र छोटो समय महासचिव हुने व्यक्ति हुन्।\nनोट: उथान्तले ११ वर्षसम्म महासचिवको पद सम्हालेका थिए।', 'nepali'),
      (v_set_id, 23, E'सरकारले कुनै जाति विशेषलाई भोग चलन गर्ने गरी दिइएको भूमीलाई के भनिन्छ ?', E'किपट जग्गा', E'विर्ता जग्गा', E'रैकर जग्गा', E'रकम जग्गा', 'A', E'**सरकारले कुनै जाति विशेषलाई भोग चलन गर्न दिएको भूमिलाई किपट जग्गा भनिन्छ।**\n- विर्ता जग्गा भनेको राज्यले व्यक्ति विशेषलाई दिएको भूमी हो।\n- रैकर जग्गा भन्नाले किसानले सरकारलाई कर तिरेर भोग चलन गरेको भूमीलाई बुझिन्छ।\n- रकम जग्गा भनेको काम लगाए बापत पैसाको सट्टा भोग चलन गर्न दिइएको भूमी हो।', 'nepali'),
      (v_set_id, 24, E'नेपालको भूगोलमा देहाएका धेरै खेतीयोग्य भूमि रहेको माटो कुन हो ?', E'तलैया माटो', E'पाँगो माटो', E'हिमाली माटो', E'बलौटे माटो', 'B', E'**नेपालको भूगोलमा पाँगो माटो सबैभन्दा धेरै खेतीयोग्य भूमि भएको माटो हो, जुन तराई प्रदेश र बँेसीमा पाइन्छ।**\n- तलैया माटो उपत्यकाहरूमा पाइन्छ।\n- हिमाली माटो हिमाली क्षेत्रमा पाइन्छ।\n- बलौटे माटो (बलौटे पथ्थरिलो माटो) भावर प्रदेश, भित्री मधेश र चुरे पहाडमा पाइन्छ।', 'nepali'),
      (v_set_id, 25, E'दुलोभेरी नदिको उद्गम देहाएका मध्ये कुन हिमालबाट हुने गर्दछ ?', E'अपि हिमाल', E'धौलागिरी हिमाल', E'सैपाल हिमाल', E'मुकुट हिमाल', 'D', E'**ठूलो भेरी (दुलोभेरी) नदीको उद्गम मुकुट हिमालबाट हुन्छ।**\n- अपि हिमालबाट महाकाली नदीको उद्गम हुन्छ।\n- धौलागिरी हिमालबाट सानो भेरी नदीको उद्गम हुन्छ।\n- सैपाल हिमालबाट सेती नदीको उद्गम हुन्छ।', 'nepali'),
      (v_set_id, 26, E'वन्यजन्तु संग्रहालय नेपालको भूगोलको कुन जिल्लामा अवस्थित रहेको छ ?', E'गोदावरी, ललितपुर', E'पोखरा, कास्की', E'हेटौंडा, मकवानपुर', E'दमक, झापा', 'C', E'**वन्यजन्तु संग्रहालय हेटौंडा, मकवानपुरमा अवस्थित छ।**\n- गोदावरी, ललितपुरमा मृग अध्ययन केन्द्र रहेको छ।\n- पोखरा, कास्कीको फेवातालमा माछा संग्रहालय रहेको छ।\n- दमक, झापामा सर्प संग्रहालय रहेको छ।', 'nepali'),
      (v_set_id, 27, E'पृथ्वीलाई आफ्नो अक्षमा घुम्न लाग्ने समय कुन विकल्प सहि छ ?', E'२३ घ. ५६ मि. ४.०९ से.', E'२४ घ. ५६ मि. ४.०९ से.', E'२३ घ. ५६ मि. ४.०९ से.', E'२४ घ. ५६ मि. ४.०९ से.', 'C', E'पृथ्वीलाई आफ्नो अक्षमा एकपटक घुम्न **२३ घण्टा ५६ मिनेट ४.०९ सेकेन्ड** लाग्छ।\n- पृथ्वीको आफ्नो अक्षमा घुम्ने गतिलाई नै परिभ्रमण गति भनिन्छ, जुन पश्चिमबाट पूर्वतर्फ (घडीको विपरीत दिशामा) हुन्छ। यो अवधिलाई नाक्षत्र दिन (Sidereal Day) भनिन्छ।', 'nepali'),
      (v_set_id, 28, E'अति सिमान्तकृत समूहमा सुचिकृत जनजातिको संख्या कति रहेको छ ?', E'१५ जनजाति', E'२१ जनजाति', E'१२ जनजाति', E'१० जनजाति', 'C', E'आदिवासी जनजाति उत्थान राष्ट्रिय प्रतिष्ठान ऐन, २०५८ अनुसार अति सिमान्तकृत समूहमा **१२ जनजाति** सुचिकृत छन्।\n- सुविधाविहिन समूहमा १५ जनजाति पर्दछन्।\n- लोपोन्मुख समूहमा १० जनजाति पर्दछन्।\nनोट: ऐन अनुसार नेपालमा कुल ५९ जनजाति समूहहरू सूचीकृत छन्, जसलाई ५ समूहमा (लोपोन्मुख, अति सिमान्तकृत, सिमान्तकृत, सुविधाविहीन र उन्नत) वर्गीकरण गरिएको छ।', 'nepali'),
      (v_set_id, 29, E'देहायका मध्ये सबैभन्दा ठूलो खगोलिय दुरी कुन हो ?', E'प्रकाश वर्ष', E'एस्ट्रोनोमिकल एकाइ', E'पार्सेक', E'१ लाख कि.मि.', 'C', E'दिइएका विकल्पहरूमध्ये सबैभन्दा ठूलो खगोलिय दुरीको एकाइ **पार्सेक** हो।\n- प्रकाश वर्ष (Light year) भन्नाले प्रकाशले एक वर्षमा पार गर्ने दुरीलाई बुझाउँछ, जुन करिब ९५ खर्ब किलोमिटर हुन्छ।\n- एस्ट्रोनोमिकल एकाइ (Astronomical Unit) सूर्य र पृथ्वीबीचको औसत दुरी हो, जुन लगभग १४.९६ करोड किलोमिटर हुन्छ।\n- १ लाख कि.मि. एक सामान्य दुरीको मापन हो र खगोलिय मापनको तुलनामा निकै सानो छ।\nनोट: १ पार्सेक बराबर ३.२६ प्रकाश वर्ष वा २,०६,२६५ एस्ट्रोनोमिकल एकाइ (AU) हुन्छ।', 'nepali'),
      (v_set_id, 30, E'विश्व व्यापार संगठन (WTO) को प्रधान कार्यालय कहाँ रहेको छ ?', E'हेग', E'न्युयोर्क', E'पेरिस', E'जेनेभा', 'D', E'विश्व व्यापार संगठन (WTO) को प्रधान कार्यालय **जेनेभा, स्विट्जरल्याण्डमा** रहेको छ।\n- हेग, नेदरल्याण्ड्समा अन्तर्राष्ट्रिय न्यायालय (ICJ) को मुख्यालय रहेको छ।\n- न्युयोर्क, संयुक्त राज्य अमेरिकामा संयुक्त राष्ट्र संघ (UN) को मुख्यालय रहेको छ।\n- पेरिस, फ्रान्समा युनेस्को (UNESCO) को मुख्यालय रहेको छ।\nनोट: विश्व व्यापार संगठनको स्थापना १ जनवरी १९९५ मा भएको थियो र नेपाल २३ अप्रिल २००४ मा यसको १४७ औं सदस्य बनेको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/०६', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_07.csv  →  आसमान दैनिक GK — २०८२/११/०७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/०७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/०७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/०७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'सन् २०२६ बाट कार्यकाल सुरु भएको सुरक्षा परिषदमा अस्थायी सदस्य मुलुक देहायका मध्ये कुन हो?', E'कम्बोडिया', E'कंगो', E'पाकिस्तान', E'भुटान', 'B', E'संयुक्त राष्ट्रसंघको सुरक्षा परिषदमा सन् २०२६ बाट कार्यकाल सुरु गर्ने अस्थायी सदस्य राष्ट्रहरूमा **कंगो** पनि पर्दछ। कंगोसँगै बहराइन, लाइबेरिया, कोलम्बिया र लाटभियाले सन् २०२६ जनवरी १ देखि आफ्नो २ वर्षे कार्यकाल सुरु गरेका थिए।\nनोट: पाकिस्तान, पानामा, डेनमार्क, ग्रिस र सोमालियाको कार्यकाल भने २०२६ डिसेम्बर ३१ मा समाप्त भएको थियो।', 'nepali'),
      (v_set_id, 2, E'गाइने रियालिटी सो द भ्वाइस अफ नेपाल सिजन ७ को उपाधि कसलाई प्रदान भएको छ ?', E'सागर संसार', E'निता थापा मगर', E'पुनम गुरुङ', E'प्रोसेस पाण्डे', 'B', E'गाइने रियालिटी सो ''द भ्वाइस अफ नेपाल'' सिजन ७ को उपाधि **निता थापा मगर**ले जितेकी हुन्।\n- सागर संसार सिजन ७ का फस्ट रनरअप थिए।\n- पुनम गुरुङ सिजन ७ की सेकेन्ड रनरअप थिइन्।\n- प्रोसेस पाण्डेले ''द भ्वाइस अफ नेपाल'' सिजन ६ को उपाधि जितेका थिए।\nनोट: निता थापा मगर ''द भ्वाइस अफ नेपाल'' को उपाधि जित्ने पहिलो महिला हुन्।', 'nepali'),
      (v_set_id, 3, E'नेपालको तर्फ बाट ICC टी-२० विश्वकपमा अर्धशतक प्रहार गर्ने दुई खेलाडी कुन कुन हुन्?', E'सुबाश खकुरेल र दिपेन्द्र सिंह ऐरी', E'रोहित पौडेल र दिपेन्द्र सिंह ऐरी', E'सोमपाल कामी र दिपेन्द्र सिंह ऐरी', E'पारस खड्का र दिपेन्द्र सिंह ऐरी', 'A', E'**नेपालका लागि आईसीसी टी-२० विश्वकपमा अर्धशतक प्रहार गर्ने दुई खेलाडी सुबाश खकुरेल र दिपेन्द्र सिंह ऐरी हुन्।**\n- रोहित पौडेल नेपालका वर्तमान क्रिकेट कप्तान हुन्।\n- सोमपाल कामी आईसीसी टी-२० विश्वकपमा सर्वाधिक विकेट लिने नेपाली खेलाडी हुन्।\n- पारस खड्का नेपालका पूर्व कप्तान तथा एकदिवसीय अन्तर्राष्ट्रियमा शतक बनाउने पहिलो नेपाली खेलाडी हुन्।\nनोट: सुबाश खकुरेलले सन् २०१४ मा र दिपेन्द्र सिंह ऐरीले सन् २०२६ मा अर्धशतक प्रहार गरेका थिए।', 'nepali'),
      (v_set_id, 4, E'आगामी कोप ३१ सन् २०२६ मा कुन स्थानमा आयोजना हुने भएको छ?', E'बाकु', E'बेलेम', E'अस्ट्रेलिया', E'अन्टाल्या', 'D', E'**आगामी कोप ३१ सन् २०२६ नोभेम्बर ९-२० मा टर्कीको अन्टाल्यामा आयोजना हुने भएको छ।**\n- कोप ३० सन् २०२५ मा ब्राजिलको बेलेममा सम्पन्न भएको थियो भने कोप २९ सन् २०२४ मा अजरबैजानको बाकुमा आयोजना भएको थियो।\nनोट: पहिलो कोप सम्मेलन सन् १९९५ मा जर्मनीको बर्लिनमा भएको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपालले ICC टी-२० विश्वकपमा १२ वर्ष पछि कुन देश विरुद्ध ऐतिहासिक विजय प्राप्त गरेको हो?', E'इटाली', E'वेस्ट इन्डिज', E'स्कटल्यान्ड', E'आयरल्यान्ड', 'C', E'**नेपालले आईसीसी टी-२० विश्वकप २०२६ मा स्कटल्यान्डलाई ७ विकेटले पराजित गर्दै १२ वर्षपछि ऐतिहासिक विजय प्राप्त गरेको थियो।**\n- इटाली, वेस्ट इन्डिज र आयरल्यान्ड क्रिकेट खेल्ने अन्य राष्ट्रहरू हुन्।\nनोट: नेपालले सन् २०१४ को विश्वकपमा अफगानिस्तान र हङकङलाई पराजित गरेको थियो, जसपछि २०२६ को विश्वकपमा स्कटल्यान्डविरुद्धको जित तेस्रो हो।', 'nepali'),
      (v_set_id, 6, E'सन् २०२६ फेब्रुअरीमा बंगलादेशको प्रधानमन्त्री बन्न सफल राजनीतिज्ञ को हुन्?', E'तारिक रहमान', E'सादिक सेक', E'फरहान अली', E'जमाल हसन', 'A', E'**सन् २०२६ फेब्रुअरी १७ मा बंगलादेश राष्ट्रिय पार्टी (बीएनपी) का अध्यक्ष तारिक रहमान बंगलादेशको प्रधानमन्त्री बनेका थिए।**\n- सादिक सेक, फरहान अली र जमाल हसन बंगलादेशका अन्य राजनीतिज्ञहरू हुन्।\nनोट: तारिक रहमान पूर्व राष्ट्रपति जियाउर रहमान तथा बंगलादेशकी प्रथम महिला प्रधानमन्त्री बेगम खालिदा जियाका छोरा हुन्।', 'nepali'),
      (v_set_id, 7, E'२०८२ सालमा कति औं सेना दिवस मनाइएको छ?', E'२६१ औं', E'२६२ औं', E'२६३ औं', E'२६४ औं', 'C', E'**२०८२ सालमा नेपालले २६३ औं सेना दिवस मनाएको थियो।**\n- सेना दिवस हरेक वर्ष महाशिवरात्रीको दिन मनाइन्छ।\nनोट: २०८२ सालको सेना दिवसको प्रमुख आतिथ्य राष्ट्रपति रामचन्द्र पौडेलले गरेका थिए।', 'nepali'),
      (v_set_id, 8, E'विश्व रेडियो दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ?', E'फेब्रुअरी ११', E'फेब्रुअरी १३', E'फेब्रुअरी १४', E'फेब्रुअरी १७', 'B', E'**विश्व रेडियो दिवस प्रत्येक वर्ष फेब्रुअरी १३ मा मनाइन्छ।**\n- यो दिवस पहिलोपटक सन् २०१२ फेब्रुअरी १३ मा मनाइएको थियो।\nनोट: सन् २०२६ को विश्व रेडियो दिवसको नारा "Radio and Artificial Intelligence : AI is a tool, not a voice." रहेको थियो।', 'nepali'),
      (v_set_id, 9, E'एसियाली विकास बैंकको दक्षिण एसिया विभाग महानिर्देशकमा नियुक्त हुन सफल नेपाली को हुन्?', E'निर्मला शर्मा', E'सविता भण्डारी', E'चन्द्रकला पौडेल', E'सोना श्रेष्ठ', 'D', E'एसियाली विकास बैंकको दक्षिण एसिया विभागको महानिर्देशकमा **सोना श्रेष्ठ** नियुक्त भएकी हुन्। उनलाई विसं २०८२ माघ २९ (सन् २०२६ फेब्रुअरी १२) मा नेपाल, भारत, भुटान, बंगलादेश, माल्दिभ्स र श्रीलंका हेर्ने गरी नियुक्त गरिएको थियो।', 'nepali'),
      (v_set_id, 10, E'नेपालमा पहिलो पटक सालक सम्मेलन कहाँ सम्पन्न भएको हो?', E'चितवन', E'कास्की', E'बाँके', E'झापा', 'A', E'नेपालमा पहिलो पटक सालक सम्मेलन विसं **२०८२ माघ २६** मा चितवनको माडीमा सम्पन्न भएको थियो। यो सम्मेलन बागमती प्रदेश सरकारको वन तथा वातावरण मन्त्रालय र डिभिजन वन कार्यालयको संयोजनमा आयोजना गरिएको थियो।', 'nepali'),
      (v_set_id, 11, E'राष्ट्रिय प्राकृतिक स्रोत तथा वित्त आयोगको प्रतिवेदन २०८२ अनुसार कार्यसम्पादन मूल्यांकनमा मुलुककै पहिलो स्थानमा रहन सफल स्थानीय तह कुन हो?', E'चौरजहारी न. पा.', E'इच्छाकामना गा. पा.', E'पाणिनी गा. पा.', E'मेचीनगर न. पा.', 'C', E'राष्ट्रिय प्राकृतिक स्रोत तथा वित्त आयोगको विसं २०८२ माघ २९ मा सार्वजनिक गरेको प्रतिवेदन अनुसार कार्यसम्पादन मूल्यांकनमा अर्घाखाँचीको **पाणिनी गाउँपालिका** (८३.८४ अंक) मुलुककै पहिलो स्थानमा रहन सफल भएको छ।\n- रुकुम पश्चिमको चौरजहारी नगरपालिका (८२.९५ अंक) दोस्रो स्थानमा रहेको छ।\n- प्रदेशहरूमध्ये सुदूरपश्चिम प्रदेश (४५.७० अंक) पहिलो र मधेश प्रदेश (२७.२६ अंक) सबैभन्दा कमजोर देखिएको छ।\n- महानगरपालिकाहरूमध्ये विराटनगर (७८.११ अंक) पहिलो स्थानमा रहेको छ।', 'nepali'),
      (v_set_id, 12, E'अफ्रिकी संघ (AU) शिखर सम्मेलन २०२६ कहाँ आयोजना भएको छ?', E'अल्जेरिया', E'बोत्सवाना', E'इथियोपिया', E'नामिबिया', 'C', E'अफ्रिकी संघ (AU) को ३९औं साधारण शिखर सम्मेलन २०२६ फेब्रुअरी १४-१५ मा **इथियोपियाको आदिस अबाबामा** रहेको अफ्रिकी संघको मुख्यालयमा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 13, E'३६ औं नेटो सम्मेलन, २०२६ कहाँ आयोजना हुने भएको हो?', E'नेदरल्यान्ड', E'अमेरिका', E'स्विडेन', E'टर्की', 'D', E'**३६औं नेटो सम्मेलन २०२६ जुलाई ५-६ मा टर्कीको अंकारामा आयोजना हुने तय भएको छ।**\n- नेदरल्यान्डमा सन् २०२५ जुन २४-२५ मा ३५औं नेटो सम्मेलन आयोजना हुनेछ।\n- अमेरिकामा सन् २०२४ जुलाई ९-११ मा ३४औं नेटो सम्मेलन सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 14, E'सरकारले जंगली रातो बाँदरलाई पुनः कृषि हानिकारक वन्यजन्तु घोषणा कहिले गरेको छ?', E'२०८२ माघ २३', E'२०८२ माघ २५', E'२०८२ माघ २७', E'२०८२ माघ २९', 'D', E'सरकारले जंगली रातो बाँदरलाई पुनः कृषि हानिकारक वन्यजन्तु घोषणा **विसं २०८२ माघ २९** गते गरेको थियो। यो घोषणा राजपत्रमा प्रकाशित भएको थियो।\nनोट: यसअघि पहिलो पटक विसं २०७१ माघ १० गते रातो बाँदरलाई कृषि हानिकारक वन्यजन्तु घोषणा गरिएको थियो।', 'nepali'),
      (v_set_id, 15, E'हालसालै नेपालको दैलेख जिल्लामा कति मात्रामा ठूलो ग्याँसको खानी रहेको प्रमाणित भएको छ ?', E'६० अर्ब ७० करोड घनमिटर', E'७० अर्ब ७० करोड घनमिटर', E'८० अर्ब ७० करोड घनमिटर', E'९० अर्ब ७० करोड घनमिटर', 'C', E'नेपालको दैलेख जिल्लामा हालसालै **८० अर्ब ७० करोड घनमिटर** ठूलो ग्याँसको खानी रहेको प्रमाणित भएको छ। चीनको चाइना जियोलोजिकल सर्भे (CGS) ले २०२६ फेब्रुअरी १२ (२०८२ माघ २९ गते) मा नेपाल सरकारलाई बुझाएको अन्तिम प्रतिवेदनले यसको आधिकारिक पुष्टि गरेको थियो।\nनोट: यो खानी दैलेख जिल्लाको भैरवी गाउँपालिका-१, जलजले क्षेत्रमा अवस्थित छ र प्रारम्भिक नतिजा अनुसार ५० वर्षसम्म पुग्ने ग्यास रहेको अनुमान छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/०७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_08.csv  →  आसमान दैनिक GK — २०८२/११/०८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/०८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/०८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/०८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'निर्वाणनन्द स्वामी, स्वामी महाराजको नामले चिनिने राजा को हुन्?', E'गिर्वाणयुद्ध शाह', E'सुरेन्द्र शाह', E'त्रिभुवन शाह', E'रणबहादुर शाह', 'D', E'**रणबहादुर शाहलाई ''निर्वाणनन्द स्वामी'' र ''स्वामी महाराज'' उपनामले चिनिन्छ।**\n- सुरेन्द्र शाहलाई ''बहुला युवराज'', ''सन्की महाराज'' र ''नानीयुवराज'' जस्ता उपनामले चिनिन्थ्यो।\n- त्रिभुवन शाहलाई ''राष्ट्रपिता'' तथा ''जनताका राजा'' भनेर चिनिन्छ।\n- गिर्वाणयुद्ध शाहको पालामा नेपाल-अंग्रेज युद्ध भएको थियो र सुगौली सन्धिमा हस्ताक्षर भएको थियो।', 'nepali'),
      (v_set_id, 2, E'बाराक ओबामा कति औं अमेरिकी राष्ट्रपति हुने व्यक्ति को हुन्?', E'४२ औं', E'४३ औं', E'४४ औं', E'४५ औं', 'C', E'बाराक ओबामा अमेरिकाका **४४ औं** राष्ट्रपति हुन्।\nनोट: उनी अमेरिकाको इतिहासमा पहिलो पटक अश्वेत जातिबाट राष्ट्रपति बन्ने व्यक्ति थिए।', 'nepali'),
      (v_set_id, 3, E'गणेश हिमालबाट उत्पत्ति भएको नदी देहायका मध्ये कुन हो?', E'सेती गण्डकी', E'मर्स्याङ्दी', E'बुढी गण्डकी', E'कालिगण्डकी', 'C', E'**बुढी गण्डकी नदीको उत्पत्ति गणेश हिमालबाट भएको हो।**\n- सेती गण्डकी, मादी र मोदी नदीको उत्पत्ति अन्नपूर्ण हिमालबाट हुन्छ।\n- मर्स्याङ्दी नदीको उत्पत्ति दामोदर हिमालबाट भएको हो।\n- कालिगण्डकी नदी मुस्ताङ लेकबाट उत्पत्ति हुन्छ।', 'nepali'),
      (v_set_id, 4, E'विश्व भूगोलको तेस्रो ठूलो ताल कुन हो?', E'बैकाल ताल', E'सुपेरियर ताल', E'ताङ्गानिका ताल', E'भिक्टोरिया ताल', 'D', E'विश्वको तेस्रो ठूलो ताल **भिक्टोरिया ताल** हो।\n- सुपेरियर ताल सतहको क्षेत्रफलको आधारमा विश्वको सबैभन्दा ठूलो ताजा पानीको ताल हो।\n- बैकाल ताल आयतनको आधारमा विश्वको सबैभन्दा ठूलो र गहिरो ताल हो।\n- ताङ्गानिका ताल विश्वको दोस्रो गहिरो र दोस्रो ठूलो ताजा पानीको ताल (आयतनको आधारमा) हो।\nनोट: भिक्टोरिया ताल अफ्रिका महादेशको तान्जानिया, युगान्डा र केन्यामा फैलिएको छ।', 'nepali'),
      (v_set_id, 5, E'हिमालयको बिचमा रहेको तराईको क्षेत्रलाई के भनिन्छ?', E'हिमांचल क्षेत्र', E'चुरे क्षेत्र', E'दुन क्षेत्र', E'महाभारत क्षेत्र', 'C', E'मध्य हिमालय र शिवालिक हिमालयको बीचमा पाइने उपत्यकाहरूलाई **दुन क्षेत्र** (भित्री मधेस) भनिन्छ।\n- चुरे क्षेत्र (शिवालिक) नेपालको सबैभन्दा दक्षिणमा रहेको र सबैभन्दा नयाँ पर्वत श्रृंखला हो।\n- महाभारत क्षेत्र चुरे श्रृंखलाको उत्तर र मुख्य हिमालयको दक्षिणमा अवस्थित छ।\n- हिमांचल क्षेत्र नेपालको भौगोलिक विभाजनको औपचारिक शब्दावली होइन, तर सामान्यतया हिमाली प्रदेशलाई जनाउन प्रयोग हुन सक्छ।', 'nepali'),
      (v_set_id, 6, E'नेपालको संविधान बमोजिम प्रत्येक नागरिकलाई देहायको कुन स्वतन्त्रता हक उल्लेख छैन?', E'विचार र अभिव्यक्तिको स्वतन्त्रता', E'संघ र संस्था खोल्ने स्वतन्त्रता', E'राजनीतिक दल खोल्ने स्वतन्त्रता', E'हातहतियार भेला हुने स्वतन्त्रता', 'D', E'**नेपालको संविधानको धारा १७ ले हातहतियार भेला हुने स्वतन्त्रतालाई नागरिकको मौलिक हकको रूपमा उल्लेख गरेको छैन।**\n- विचार र अभिव्यक्तिको स्वतन्त्रता संविधानको धारा १७ (१) मा उल्लेख छ।\n- संघ र संस्था खोल्ने स्वतन्त्रता संविधानको धारा १७ (२) (ग) मा उल्लेख छ।\n- राजनीतिक दल खोल्ने स्वतन्त्रता संविधानको धारा १७ (२) (घ) मा उल्लेख छ।\nनोट: धारा १७ ले ६ प्रकारका स्वतन्त्रताको हकको व्यवस्था गरेको छ।', 'nepali'),
      (v_set_id, 7, E'एक गाउँ एक उत्पादन कार्यक्रम अन्तर्गत माछा पालनका लागि छनोट जिल्ला कुन हो?', E'डोटी', E'धनुषा', E'नुवाकोट', E'ताप्लेजुङ', 'B', E'**एक गाउँ एक उत्पादन कार्यक्रम अन्तर्गत माछा पालनका लागि धनुषा जिल्ला छनोट गरिएको छ।**\n- यो कार्यक्रम स्थानीय उत्पादनलाई प्रोत्साहन गर्नका लागि सञ्चालन गरिएको हो।', 'nepali'),
      (v_set_id, 8, E'सोह्रौं योजनाको अन्त्य आ.व. २०८५/८६ सम्म भ्रष्टाचार न्यूनीकरण अनुभूति सूचकाङ्क कति पुऱ्याउने लक्ष्य राखिएको छ?', E'४१ अंक', E'४३ अंक', E'४५ अंक', E'४७ अंक', 'B', E'**सोह्रौं योजनाको अन्त्य आ.व. २०८५/८६ सम्म भ्रष्टाचार न्यूनीकरण अनुभूति सूचकाङ्क ४३ अंक पुऱ्याउने लक्ष्य राखिएको छ।**\n- आ.व. २०७९/८० मा यो सूचकाङ्क ४१ अंक रहेको थियो।', 'nepali'),
      (v_set_id, 9, E'सन् २०३० सम्ममा हासिल गरिसक्नुपर्ने राष्ट्र संघ (United Nations) ले तय गरेका दिगो विकास लक्ष्यहरू-नेपालको कम प्राथमिकतामा रहेको लक्ष्य तलकामध्ये कुन हो?', E'Partnerships for the Goals', E'Climate Actions', E'Affordable and Clean Energy', E'Life Below Water', 'D', E'**संयुक्त राष्ट्र संघले तय गरेका दिगो विकास लक्ष्यहरूमध्ये ''Life Below Water'' (पानीमुनिको जीवन) नेपालको लागि कम प्राथमिकतामा रहेको लक्ष्य हो।**\n- ''Partnerships for the Goals'' (लक्ष्य प्राप्तिका लागि साझेदारी) दिगो विकास लक्ष्य १७ हो।\n- ''Climate Action'' (जलवायु कार्य) दिगो विकास लक्ष्य १३ हो।\n- ''Affordable and Clean Energy'' (सुलभ र स्वच्छ ऊर्जा) दिगो विकास लक्ष्य ७ हो।\nनोट: नेपाल भूपरिवेष्ठित राष्ट्र भएकाले ''Life Below Water'' प्रत्यक्ष रूपमा कम सान्दर्भिक मानिन्छ।', 'nepali'),
      (v_set_id, 10, E'पाकिस्तानले सार्कको बजेटमा कति प्रतिशत योगदान गर्दछ?', E'२२.१२ प्रतिशत', E'२२.२२ प्रतिशत', E'२२.७२ प्रतिशत', E'२२.३२ प्रतिशत', 'B', E'**पाकिस्तानले सार्कको बजेटमा २२.२२ प्रतिशत योगदान गर्दछ।**\n- सार्कको बजेटमा सदस्य राष्ट्रहरूको योगदान यस प्रकार छ:\n| देश | योगदान |\n| --- | --- |\n| भारत | ३०.३२% |\n| पाकिस्तान | २२.२२% |\n| नेपाल, बंगलादेश, श्रीलंका | १०.७२% (प्रत्येक) |\n| भुटान, माल्दिभ्स, अफगानिस्तान | ५% (प्रत्येक) |', 'nepali'),
      (v_set_id, 11, E'सबैभन्दा पहिला नेपालसँग दौत्य सम्बन्ध कायम भएको अफ्रिकी मुलुक कुन हो?', E'बेलायत', E'सुडान', E'इजिप्ट', E'अल्जेरिया', 'C', E'**नेपालसँग सबैभन्दा पहिला दौत्य सम्बन्ध कायम भएको अफ्रिकी मुलुक इजिप्ट हो।**\n- भारत नेपालसँग दौत्य सम्बन्ध कायम भएको प्रथम एसियाली मुलुक हो।\n- बेलायत नेपालसँग दौत्य सम्बन्ध कायम भएको प्रथम युरोपेली मुलुक हो।\n- अमेरिका नेपालसँग दौत्य सम्बन्ध कायम भएको प्रथम उत्तर अमेरिकी मुलुक हो।', 'nepali'),
      (v_set_id, 12, E'नेपालका मध्यवर्ती क्षेत्रहरू कतिवटा रहेका छन्?', E'१२ वटा', E'१३ वटा', E'१४ वटा', E'१५ वटा', 'C', E'नेपालमा **१४ वटा** मध्यवर्ती क्षेत्रहरू रहेका छन्। यी क्षेत्रहरू राष्ट्रिय निकुञ्ज तथा वन्यजन्तु आरक्षको वरिपरि जैविक विविधता संरक्षण र स्थानीय समुदायको जीविकोपार्जनमा सहयोग पुर्याउन स्थापना गरिएका हुन्।', 'nepali'),
      (v_set_id, 13, E'देहायका भिटामिनको कमीले लाग्ने रोग हरू मध्ये कुन रोग भिटामिन D को कमीले हुने गर्दछ?', E'रिकेट्स हुनु', E'स्कर्भी हुनु', E'रगत बग्ने समस्या', E'बाँझोपन हुनु', 'A', E'भिटामिन D को कमीले बालबालिकामा **रिकेट्स** (हड्डी कमजोर हुने) रोग लाग्दछ।\n- भिटामिन C को कमीले स्कर्भी रोग लाग्छ।\n- भिटामिन K को कमीले रगत जम्न ढिलाइ हुने समस्या देखिन्छ।\n- भिटामिन E को कमीले बाँझोपनको समस्या हुन सक्छ।', 'nepali'),
      (v_set_id, 14, E'रुख सम्बन्धी अध्ययन गर्ने विज्ञानलाई के भनिन्छ?', E'Aetiology', E'Bromatology', E'Hematology', E'Dendrology', 'D', E'रुख सम्बन्धी अध्ययन गर्ने विज्ञानलाई **डेन्ड्रोलोजी (Dendrology)** भनिन्छ।\n- एटियोलोजी (Aetiology) अन्तर्गत रोगका कारणहरूको अध्ययन गरिन्छ।\n- ब्रोमाटोलोजी (Bromatology) खाना सम्बन्धी अध्ययन गर्ने विज्ञान हो।\n- हेमाटोलोजी (Hematology) रगत सम्बन्धी अध्ययन गर्ने विज्ञान हो।', 'nepali'),
      (v_set_id, 15, E'दिइएका मध्ये कुन मन्दिर शिखर शैलीको सबैभन्दा पुरानो मन्दिर हो?', E'कृष्ण मन्दिर', E'जगतनारायण मन्दिर', E'ब्रह्मा मन्दिर', E'वत्सलादेवि मन्दिर', 'C', E'काठमाडौंको पशुपति क्षेत्रमा रहेको **ब्रह्मा मन्दिर** नेपालको शिखर शैलीमा निर्मित सबैभन्दा पुरानो मन्दिर मानिन्छ।\nनोट: नेपालको सबैभन्दा पुरानो मन्दिर स्वयम्भूनाथ स्तुप हो भने प्यागोडा शैलीको सबैभन्दा पुरानो मन्दिर चाँगुनारायण हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/०८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_10.csv  →  आसमान दैनिक GK — २०८२/११/१०  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/१०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/१०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/१०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको निर्वाचन प्रणालीमा कति प्रतिशत सदस्य समानुपातिकबाट निर्वाचित हुने गर्दछन्?', E'३३%', E'४०%', E'५०%', E'६०%', 'B', E'नेपालको निर्वाचन प्रणालीमा समानुपातिक निर्वाचन प्रणालीबाट **४० प्रतिशत** सदस्य निर्वाचित हुने गर्दछन्। प्रत्यक्ष निर्वाचन प्रणालीमा भने ६० प्रतिशत सदस्य निर्वाचित हुन्छन्।\nनोट: २०७४ को निर्वाचनमा १६५ सदस्य प्रत्यक्ष र ११० सदस्य समानुपातिकबाट चुनिएका थिए।', 'nepali'),
      (v_set_id, 2, E'म्याग्नाकार्टामा हस्ताक्षर कुन नदी किनारामा गरिएको थियो?', E'टिग्रिस नदी', E'सिन्धु नदी', E'थेम्स नदी', E'रनीमेड नदी', 'C', E'म्याग्नाकार्टामा हस्ताक्षर बेलायतको लण्डनबाट १९ माइल टाढा रहेको रनीमेड नामक स्थानमा **थेम्स नदी**को किनारमा गरिएको थियो। यसले जनप्रतिनिधिको स्वीकृति बिना कर लगाउन नपाइने अवधारणाको विकास गरेको थियो।\nनोट: म्याग्नाकार्टा चराको प्वाँखले चर्मपत्रमा लेखिएको थियो।', 'nepali'),
      (v_set_id, 3, E'''योग्य पिताका सुयोग्य छोरा'' भनेर कुन नेपाली राजालाई चिनिन्छ?', E'प्रतापसिंह शाह', E'रण व शाह', E'ज्ञानेन्द्र शाह', E'बहादुर शाह', 'D', E'**बहादुर शाह**लाई ''योग्य पिताका सुयोग्य छोरा'' भनेर चिनिन्छ।\n- प्रतापसिंह शाहलाई ''योग्य पिताका अयोग्य छोरा'' भनेर चिनिन्छ।\n- रणबहादुर शाह नेपालका चौथो शाहवंशीय राजा थिए।\n- ज्ञानेन्द्र शाह नेपालका अन्तिम राजा हुन्।', 'nepali'),
      (v_set_id, 4, E'गौरा पर्व कुन प्रदेशको महत्त्वपूर्ण धार्मिक एवं सांस्कृतिक पर्व हो?', E'कर्णाली', E'लुम्बिनी', E'सुदूरपश्चिम', E'मधेश', 'C', E'गौरा पर्व **सुदूरपश्चिम** प्रदेशको महत्त्वपूर्ण धार्मिक एवं सांस्कृतिक पर्व हो। यो पर्व विशेष गरेर डोटीमा परम्परा पूर्व कालदेखि नै मनाइँदै आएको छ।\n- कर्णाली प्रदेशमा देउडा, भुवा पर्व, सिस्नो खोल्ने पर्व जस्ता सांस्कृतिक पर्वहरू मनाइन्छ।\n- लुम्बिनी प्रदेशमा बुद्ध जयन्ती, माघी, दशैं, तिहार जस्ता पर्वहरू मनाइन्छ।\n- मधेश प्रदेशमा छठ पर्व, जुडशीतल, समाचकेवा जस्ता पर्वहरू मनाइन्छ।', 'nepali'),
      (v_set_id, 5, E'सार्वजनिक स्थान वा भिडहरू देखि लाग्ने रोगलाइ वैज्ञानिक भाषामा के भनिन्छ?', E'एन्ट्रोफोबिया', E'एल्गोफोबिया', E'अटोफोबिया', E'एगोराफोबिया', 'D', E'**एगोराफोबिया (Agoraphobia) भनेको सार्वजनिक स्थान वा भिडहरूदेखि लाग्ने डर हो।**\n- एल्गोफोबिया (Algophobia) पीडादेखि लाग्ने डर हो।\n- अटोफोबिया (Autophobia) एक्लै हुँदा लाग्ने डर हो।\n- एन्ड्रोफोबिया (Androphobia) पुरुष वा केटा मान्छेदेखि लाग्ने डर हो।', 'nepali'),
      (v_set_id, 6, E'रसुवा, नुवाकोट, सिन्धुपाल्चोक जिल्लामा फैलिएको राष्ट्रिय निकुञ्ज कुन हो?', E'लाङटाङ', E'शुक्लाफाँटा', E'शिवपुरी नागार्जुन', E'मकालु वरुण', 'A', E'**लाङटाङ राष्ट्रिय निकुञ्ज रसुवा, नुवाकोट र सिन्धुपाल्चोक जिल्लामा फैलिएको छ।**\n- शुक्लाफाँटा राष्ट्रिय निकुञ्ज कञ्चनपुर जिल्लामा अवस्थित छ।\n- शिवपुरी नागार्जुन राष्ट्रिय निकुञ्ज काठमाडौं, नुवाकोट, सिन्धुपाल्चोक र धादिङ जिल्लाहरूमा फैलिएको छ।\n- मकालु वरुण राष्ट्रिय निकुञ्ज संखुवासभा र सोलुखुम्बु जिल्लामा अवस्थित छ।\nनोट: लाङटाङ राष्ट्रिय निकुञ्ज वि.सं. २०३२ मा स्थापना भएको थियो र यसको क्षेत्रफल १७१० वर्ग कि.मि. छ।', 'nepali'),
      (v_set_id, 7, E'१९ औं सार्क शिखर सम्मेलन कुन सालमा सम्पन्न भएको थियो?', E'वि.सं. २०७०', E'वि.सं. २०७१', E'वि.सं. २०७२', E'वि.सं. २०७३', 'B', E'१९ औं सार्क शिखर सम्मेलन **वि.सं. २०७१** सालमा नेपालको राजधानी काठमाडौंमा सम्पन्न भएको थियो। यो सम्मेलन २०१४ नोभेम्बर २६-२७ (वि.सं. २०७१ मंसिर १०-११) मा आयोजना गरिएको थियो।\nनोट: उक्त सम्मेलनले ३६ बुँदे काठमाडौं घोषणापत्र जारी गरेको थियो।', 'nepali'),
      (v_set_id, 8, E'Bank of the year-2025 को अवार्डबाट सम्मानित भएको नेपाली बैंक कुन हो?', E'नबिल बैंक लि.', E'ग्लोबल आइएमई बैंक', E'कुमारी बैंक लि.', E'सिटिजन्स बैंक इन्टरनेसनल', 'D', E'**सिटिजन्स बैंक इन्टरनेसनल** ''Bank of the year-2025'' अवार्डबाट सम्मानित भएको छ। यो प्रतिष्ठित अवार्ड लन्डनस्थित ''द फाइनान्सियल टाइम्स''ले प्रदान गर्दछ।', 'nepali'),
      (v_set_id, 9, E'२०८२ मा मनाइएको बुद्ध जयन्ती कति औं हो?', E'२५६६ औं', E'२५६७ औं', E'२५६८ औं', E'२५६९ औं', 'D', E'वि.सं. २०८२ मा **२५६९ औं** बुद्ध जयन्ती मनाइएको थियो। शान्तिका अग्रदूत सिद्धार्थ गौतमको जन्मजयन्ती प्रत्येक वर्ष वैशाख शुक्ल पूर्णिमाको दिन मनाइन्छ।', 'nepali'),
      (v_set_id, 10, E'नेपालको नागरिक आमाबाट जन्म भई बाबुको पहिचान हुन नसकेको व्यक्तिले कुन आधारमा नागरिकता प्राप्त गर्दछ?', E'अंगीकृत', E'वंशज', E'गैरआवासीय', E'सम्मानार्थ', 'B', E'**नेपालको नागरिक आमाबाट नेपालमा जन्म भई बाबुको पहिचान हुन नसकेको व्यक्तिले वंशजको आधारमा नागरिकता प्राप्त गर्दछ।**\n- अंगीकृत नागरिकता संघीय कानुन बमोजिमका शर्तहरू पूरा गर्ने विदेशी नागरिकलाई प्रदान गरिन्छ, जस्तै नेपाली नागरिकसँग वैवाहिक सम्बन्ध कायम गरेकी विदेशी महिला।\n- गैरआवासीय नेपाली नागरिकता सार्क मुलुक बाहेक अन्य देशमा बसोबास गरेका नेपाली मूलका विदेशी नागरिकलाई प्रदान गरिन्छ।\n- सम्मानार्थ नागरिकता नेपालको श्रीवृद्धिमा विशेष योगदान पुऱ्याएका विशिष्ट विदेशी व्यक्तिलाई प्रदान गरिने मानार्थ नागरिकता हो।\nनोट: यदि बाबुको पहिचान खुलेर विदेशी नागरिक भएको ठहरेमा भने त्यस्तो व्यक्तिको वंशजको नागरिकता संघीय कानुन बमोजिम अंगीकृत नागरिकतामा परिणत हुनेछ।', 'nepali'),
      (v_set_id, 11, E'बोधिचित्त खेतीको सुरुवात कुन जिल्लाबाट भएको थियो?', E'काभ्रे', E'धनकुटा', E'दोलखा', E'इलाम', 'A', E'**नेपालमा बोधिचित्त खेतीको सुरुवात वि.सं. २०६० मा काभ्रे जिल्लाबाट भएको थियो।**\n- धनकुटा जिल्लामा वि.सं. २०५८ देखि एभोकाडो खेतीको सुरुवात भएको थियो।\n- दोलखा जिल्लामा वि.सं. २०४४ देखि किवि खेतीको सुरुवात भएको थियो।\n- इलाम जिल्लामा वि.सं. १९२० देखि चिया खेतीको सुरुवात भएको थियो।\nनोट: कफी खेतीको सुरुवात वि.सं. १९९५ मा गुल्मीको आँपचौरबाट भएको थियो।', 'nepali'),
      (v_set_id, 12, E'आर्थिक सर्वेक्षण २०७९/८० अनुसार वैदेशिक रोजगारको लागि नेपालको प्रमुख गन्तव्यका रूपमा रहेको मुलुक कुन हो?', E'साउदी अरब', E'कतार', E'युएई', E'कुवेत', 'C', E'**आर्थिक सर्वेक्षण २०७९/८० अनुसार वैदेशिक रोजगारको लागि नेपालको प्रमुख गन्तव्यका रूपमा युएई रहेको छ।**\n- वैदेशिक रोजगारमा जान नयाँ श्रम स्वीकृति लिने प्रमुख मुलुकहरूमा युएई, साउदी अरब, कतार र कुवेत पर्दछन्।\nनोट: सरकारले वैदेशिक रोजगारीका लागि संस्थागत रुपमा १११ र १६७० म्यानपावर कम्पनीलाई श्रमिक पठाउन इजाजतपत्र प्रदान गरेको छ।', 'nepali'),
      (v_set_id, 13, E'सौर्यमण्डलका ग्रहहरू मध्ये सबैभन्दा थोरै घनत्व भएको ग्रह कुन हो?', E'अरुण', E'बुध', E'शनि', E'पृथ्वी', 'C', E'**सौर्यमण्डलका ग्रहहरू मध्ये सबैभन्दा थोरै घनत्व भएको ग्रह शनि हो।**\n- शनिलाई सबैभन्दा कम औसत घनत्व भएको ग्रह र पानीमा उत्रने ग्रह भनेर चिनिन्छ।\nनोट: शनि ग्रहको घनत्व ०.६९७ ग्राम/क्युबिक से.मी. रहेको छ।', 'nepali'),
      (v_set_id, 14, E'विश्व भूगोलका पाँच महासागर मध्ये सबैभन्दा ठुलो पानी भएको महासागर कुन हो?', E'आन्ध्र महासागर', E'हिन्द महासागर', E'प्रशान्त महासागर', E'कुमेरु महासागर', 'A', E'**विश्व भूगोलका पाँच महासागर मध्ये सबैभन्दा ठुलो पानी भएको महासागर आन्ध्र महासागर हो।**\n- आन्ध्र महासागरलाई सबैभन्दा अग्लो छाल हाल्ने महासागर, रहस्यमय समुद्री क्षेत्र बर्मुडा त्रिकोण टापु भएको महासागर, ज्वार भाट महासागरको उपनाम, पहिलोपटक पानीजहाज र हवाईजहाजले पार गरेको महासागर, प्रचुर मात्रामा हेरिङ माछा पाइने भएकाले हेरिङ पोण्ड उपनाम र डाँडाहरू (Ridge) धेरै भएको महासागर भनेर पनि चिनिन्छ।', 'nepali'),
      (v_set_id, 15, E'हाल नेपालमा जम्मा संरक्षित क्षेत्र कतिवटा रहेको छन्?', E'१९ वटा', E'२० वटा', E'२१ वटा', E'२२ वटा', 'C', E'**नेपालमा हाल जम्मा २१ वटा संरक्षित क्षेत्र रहेका छन्।**', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/१०', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_11.csv  →  आसमान दैनिक GK — २०८२/११/११  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/११'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/११';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/११', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालमा प्रतिनिधिसभा निर्वाचन क्षेत्र ५ वटा भएका जिल्लाको सङ्ख्या कति रहेको छ?', E'१ वटा', E'२ वटा', E'३ वटा', E'४ वटा', 'C', E'नेपालमा प्रतिनिधिसभा निर्वाचन क्षेत्र ५ वटा भएका जिल्लाको सङ्ख्या **३ वटा** रहेको छ।\nनोट: ५ वटा निर्वाचन क्षेत्र भएका तीन जिल्लाहरू झापा, रुपन्देही, र कैलाली हुन्।', 'nepali'),
      (v_set_id, 2, E'म्याग्नाकार्टामा हस्ताक्षर गर्न बाध्य बनाउने व्यक्ति को थिए?', E'जोन लेकल्याण्ड', E'रिचर्ड', E'स्टेफन लंग़टन', E'इंग्लीस ब्यारोन्स', 'D', E'**इंग्लीस ब्यारोन्स (English Barons) हरूले तत्कालीन राजा जोनलाई म्याग्नाकार्टामा हस्ताक्षर गर्न बाध्य बनाएका थिए।**\n- जोन लेकल्याण्ड राजा जोन द्वितीयलाई चिनिने अर्को नाम हो।\n- रिचर्ड राजा जोन द्वितीयभन्दा पहिले बेलायतको राजगद्दीमा बसेका राजा थिए।\n- स्टेफन लंग़टन म्याग्नाकार्टाका लेखक थिए।', 'nepali'),
      (v_set_id, 3, E'नेपालको इतिहासमा राणा शासनको सुरु कुन राजाको पालामा भएको हो?', E'राजा राजेन्द्र', E'राजा महेन्द्र', E'राजा त्रिभुवन', E'राजा सुरेन्द्र', 'A', E'नेपालमा राणा शासनको सुरुवात **राजा राजेन्द्र विक्रम शाहको** पालामा भएको हो।\n- राजा महेन्द्रले २०१७ सालमा पञ्चायती व्यवस्था लागू गरेका थिए।\n- राजा त्रिभुवनको पालामा २००७ सालको क्रान्ति सफल भई राणा शासनको अन्त्य भएको थियो।\n- राजा सुरेन्द्रलाई कोत पर्वपछि जङ्गबहादुरले राजा बनाएका थिए र उनको पालामा राणा शासन स्थापित भयो, तर सुरुवात राजा राजेन्द्रकै पालामा भएको थियो।', 'nepali'),
      (v_set_id, 4, E'भाइटीका कुन दिन पर्छ?', E'कार्तिक कृष्ण त्रयोदशी', E'कार्तिक शुक्ल पञ्चमी', E'कार्तिक शुक्ल द्वितीया', E'कार्तिक कृष्ण एकादशी', 'C', E'भाइटीका पर्व **कार्तिक शुक्ल द्वितीया** तिथिका दिन पर्दछ। यो तिहार अर्थात् यमपञ्चकको पाँचौं तथा अन्तिम दिन हो, जुन विशेष उत्साहका साथ मनाइन्छ।', 'nepali'),
      (v_set_id, 5, E'काँच मुख्यत: कुन पदार्थ बाट बन्छ?', E'बालुवा', E'क्लेमाटो', E'चुनढुङ्गा', E'माटो', 'A', E'**काँच मुख्यतया बालुवा (सिलिका) बाट बन्दछ।**\n- क्लेमाटो सिमेन्ट बनाउन प्रयोग हुने एक मुख्य कच्चा पदार्थ हो।\n- चुनढुङ्गा पनि क्लेमाटोसँग मिसाएर सिमेन्ट बनाउन प्रयोग गरिन्छ।\n- चिनियाँ माटो (Kaolin) बाट सेरामिक्सका वस्तुहरू बनाइन्छ।', 'nepali'),
      (v_set_id, 6, E'सगरमाथा राष्ट्रिय निकुञ्जको स्थापना कहिले भएको हो?', E'वि.सं. २०३०', E'वि.सं. २०३२', E'वि.सं. २०३४', E'वि.सं. २०४०', 'B', E'सगरमाथा राष्ट्रिय निकुञ्जको स्थापना **वि.सं. २०३२** मा सोलुखुम्बु जिल्लामा भएको हो। यो निकुञ्ज ११४८ वर्ग कि.मि. क्षेत्रफलमा फैलिएको छ।\nनोट: यो नेपालको हिमाली क्षेत्रको पहिलो र सर्वाधिक उचाइमा रहेको राष्ट्रिय निकुञ्ज हो।', 'nepali'),
      (v_set_id, 7, E'१९ औं सार्क शिखर सम्मेलन कुन मुलुकमा आयोजना गर्ने भनि तय गरिएको थियो?', E'पाकिस्तान', E'श्रीलंका', E'माल्दिभ्स', E'अफगानिस्तान', 'A', E'**१९ औं सार्क शिखर सम्मेलन पाकिस्तानमा आयोजना गर्ने तय गरिएको थियो।**\n- श्रीलंकाले सन् २००८ मा १५औं सार्क शिखर सम्मेलन आयोजना गरेको थियो।\n- माल्दिभ्सले सन् २०११ मा १७औं सार्क शिखर सम्मेलन आयोजना गरेको थियो।\n- अफगानिस्तान सार्कको सदस्य राष्ट्र भए तापनि हालसम्म शिखर सम्मेलन आयोजना गरेको छैन।\nनोट: सन् २०१६ नोभेम्बरमा तय भएको यो सम्मेलन हालसम्म हुन सकेको छैन।', 'nepali'),
      (v_set_id, 8, E'सरकारले प्रत्येक वर्ष कुन दिनलाई जेनजी सहिद दिवसको रूपमा मनाउने निर्णय गरेको छ?', E'भाद्र २३', E'भाद्र २४', E'भाद्र २५', E'भाद्र २६', 'A', E'सरकारले प्रत्येक वर्ष **भाद्र २३** लाई जेनजी सहिद दिवसको रूपमा मनाउने निर्णय गरेको छ।\nनोट: यो निर्णय वि.सं. २०८० भदौ १५ गतेको मन्त्रिपरिषद् बैठकले गरेको हो।', 'nepali'),
      (v_set_id, 9, E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या कति पुगेको छ?', E'४४ वटा', E'४३ वटा', E'४५ वटा', E'४६ वटा', 'D', E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या **४६ वटा** पुगेको छ।\nनोट: वि.सं. २०८० मंसिर १६ गतेदेखि ४६औं भाषाको रूपमा कुलुङ भाषामा समाचार प्रकाशन सुरु भएको हो।', 'nepali'),
      (v_set_id, 10, E'नेपालको संविधानको दोस्रो संशोधन कहिले भएको हो?', E'२०७२ फागुन १६', E'२०७७ असार ४', E'२०७३ असार ४', E'२०७७ फागुन १६', 'B', E'नेपालको संविधानको दोस्रो संशोधन **वि.सं. २०७७ असार ४** गते भएको हो।\nनोट: यो संशोधनले नेपालको निशान छापमा रहेको नक्सालाई अध्यावधिक गर्न अनुसूची ३ लाई संशोधन गरेको थियो। पहिलो संशोधन भने वि.सं. २०७२ फागुन १६ गते भएको थियो।', 'nepali'),
      (v_set_id, 11, E'एक गाउँ एक उत्पादन कार्यक्रम (OVOP) को नेपालमा लोगो सार्वजनिक कहिले गरियो?', E'२०७१ असोज १२', E'२०७२ असोज १२', E'२०७३ असोज १२', E'२०७४ असोज १२', 'C', E'एक गाउँ एक उत्पादन (OVOP) कार्यक्रमको लोगो नेपालमा **वि.सं. २०७३ असोज १२** गते सार्वजनिक गरिएको थियो।\nनोट: यस कार्यक्रमको लोगो डिजाइनर नवज्योति सुवेदी हुन्।', 'nepali'),
      (v_set_id, 12, E'आर्थिक सर्वेक्षण २०७१/८२ अनुसार नेपालको प्रमुख औद्योगिक बाली कुन हो?', E'उखु', E'जुट', E'चिया', E'कफी', 'A', E'आर्थिक सर्वेक्षण २०७१/८२ अनुसार नेपालको प्रमुख औद्योगिक बाली **उखु** हो।\nनेपालका प्रमुख औद्योगिक बालीहरूको क्रम यस प्रकार छ:\n- उखु\n- जुट\n- चिया\n- कफी\n- कपास', 'nepali'),
      (v_set_id, 13, E'पृथ्वीको अक्षको झुकाव कति रहेको छ?', E'२३.५ डिग्री', E'६६.५ डिग्री', E'६५ डिग्री', E'२४.५ डिग्री', 'B', E'पृथ्वीको अक्षको झुकाव **६६.५ डिग्री** रहेको छ। पृथ्वी आफ्नो कक्षमा २३.५ डिग्रीमा झुकेर सूर्यको वरिपरि परिक्रमा गर्छ।\nनोट: चन्द्रमाले ५.१५ डिग्रीमा ढल्केर पृथ्वीको परिक्रमा गर्छ।', 'nepali'),
      (v_set_id, 14, E'विश्वको सबैभन्दा धेरै भूकम्प तथा ज्वालामुखी जाने क्षेत्र कुन हो?', E'Great Barrier Reef', E'Mid-Atlantic Ridge', E'Pacific Ring of Fire', E'Andes Mountains', 'C', E'**प्रशान्त महासागरको Pacific Ring of Fire विश्वको सबैभन्दा धेरै भूकम्प तथा ज्वालामुखी जाने क्षेत्र हो।**\n- Great Barrier Reef अस्ट्रेलियाको उत्तरपूर्वी तटमा रहेको विश्वको सबैभन्दा ठूलो कोरल रीफ प्रणाली हो।\n- Mid-Atlantic Ridge एट्लान्टिक महासागरको बीचमा रहेको एक प्रमुख पानीमुनि पर्वत श्रृंखला हो।\n- Andes Mountains दक्षिण अमेरिकाको पश्चिमी तटमा रहेको विश्वको सबैभन्दा लामो महाद्वीपीय पर्वत श्रृंखला हो।\nनोट: Pacific Ring of Fire मा विश्वका ७५% ज्वालामुखी र ९०% भूकम्पहरू पर्दछन्।', 'nepali'),
      (v_set_id, 15, E'वातावरण संरक्षण ऐन, २०५३ अनुसार कति प्रकारका जैविक विविधता हुन्छन्?', E'२ प्रकार', E'३ प्रकार', E'४ प्रकार', E'५ प्रकार', 'B', E'**३ प्रकार।**\n- वातावरण संरक्षण ऐन, २०५३ अनुसार जैविक विविधता भन्नाले पारिस्थितिकीय प्रणाली विविधता, प्रजाति विविधता र वंशाणुगत विविधता बुझिन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/११', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_12.csv  →  आसमान दैनिक GK — २०८२/११/१२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/१२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/१२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/१२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'२०८२ सालबाट कुन दिन राष्ट्रिय चलचित्र दिवस मनाउने मन्त्रिपरिषदको निर्णय गरेको छ?', E'असोज १', E'असोज १३', E'असोज १५', E'असोज २५', 'C', E'२०८२ सालबाट राष्ट्रिय चलचित्र दिवस **असोज १५** गते मनाउने निर्णय भएको छ। २०८२ असार १३ को मन्त्रिपरिषदको निर्णय अनुसार नेपालमा बनेको पहिलो चलचित्र ''आमा'' को प्रदर्शन मितिलाई आधार मानेर यो मिति तोकिएको हो।\nनोट: यसअघि चलचित्र दिवस असोज १ गते मनाइन्थ्यो।', 'nepali'),
      (v_set_id, 2, E'नेपाल WTO को कति औं सदस्य मुलुक हो?', E'१४१ औं', E'१४३ औं', E'१४५ औं', E'१४७ औं', 'D', E'नेपाल विश्व व्यापार सङ्गठन (World Trade Organization) को **१४७ औं** सदस्य मुलुक हो।\nनोट: नेपालले सन् २००४ अप्रिल २३ मा WTO को सदस्यता प्राप्त गरेको थियो।', 'nepali'),
      (v_set_id, 3, E'नेपालको सबैभन्दा पुरानो औद्योगिक क्षेत्र कुन हो?', E'पाटन औद्योगिक क्षेत्र', E'बालाजु औद्योगिक क्षेत्र', E'धरान औद्योगिक क्षेत्र', E'हेटौंडा औद्योगिक क्षेत्र', 'B', E'**बालाजु औद्योगिक क्षेत्र** नेपालको सबैभन्दा पुरानो औद्योगिक क्षेत्र हो।\nनोट: यसको स्थापना वि.सं. २०१६ मा भएको थियो।', 'nepali'),
      (v_set_id, 4, E'नेपालको संविधान अनुसार राज्यमन्त्रीले को समक्ष पद तथा गोपनीयताको शपथ लिनु पर्नेछ?', E'प्रधानमन्त्री', E'उपप्रधानमन्त्री', E'राष्ट्रपति', E'सभामुख', 'A', E'नेपालको संविधानको धारा ८० अनुसार, राज्यमन्त्री र सहायक मन्त्रीले **प्रधानमन्त्री** समक्ष पद तथा गोपनीयताको शपथ लिनुपर्छ। सोही धारा अनुसार प्रधानमन्त्री, उपप्रधानमन्त्री र अन्य मन्त्रीहरूले भने राष्ट्रपति समक्ष शपथ लिने व्यवस्था छ।', 'nepali'),
      (v_set_id, 5, E'देहायका मध्ये सौर्यमण्डलको कुन ग्रह को रङ्ग खैरो रहेको छ?', E'बुध ग्रह', E'शुक्र ग्रह', E'मंगल ग्रह', E'पृथ्वी ग्रह', 'A', E'सौर्यमण्डलमा **बुध ग्रहको रङ्ग खैरो** रहेको छ।\n- शुक्र ग्रहको रङ्ग पहेँलो हुन्छ।\n- मंगल ग्रहलाई रातो ग्रह पनि भनिन्छ।\n- पृथ्वी ग्रहको रङ्ग नीलो रहेको छ।', 'nepali'),
      (v_set_id, 6, E'अस्ट्रेलियाको सबैभन्दा ठूलो सहर कुन हो?', E'मेलबर्न', E'क्यानबेरा', E'सिड्नी', E'पर्थ', 'C', E'**अस्ट्रेलियाको सबैभन्दा ठूलो सहर सिड्नी हो।**\n- क्यानबेरा अस्ट्रेलियाको राजधानी सहर हो।\n- मेलबर्न र पर्थ पनि अस्ट्रेलियाका प्रमुख सहरहरू हुन्।', 'nepali'),
      (v_set_id, 7, E'संविधान अनुसार कतिवटा सदनात्मक संघीय व्यवस्थापिका रहने व्यवस्था गरेको छ?', E'एक सदनात्मक', E'दुई सदनात्मक', E'तीन सदनात्मक', E'कुनै व्यवस्था नभएको', 'B', E'नेपालको संविधानको धारा ८३ अनुसार संघीय व्यवस्थापिका **दुई सदनात्मक** हुने व्यवस्था छ। यसमा माथिल्लो सदनको रूपमा राष्ट्रिय सभा र तल्लो सदनको रूपमा प्रतिनिधि सभा रहेका छन्।\nनोट: प्रदेश व्यवस्थापिका एक सदनात्मक हुन्छ भने स्थानीय तहमा गाउँसभा र नगरसभा रहने व्यवस्था छ।', 'nepali'),
      (v_set_id, 8, E'देहायका मध्ये सबैभन्दा अग्लो हिमाल कुन हो? पहिचान गर्नुहोस्', E'चोयु', E'मनास्लु', E'मकालु', E'धवलागिरि', 'C', E'दिएका विकल्पहरूमध्ये **मकालु हिमाल (८,४६३ मिटर)** सबैभन्दा अग्लो हो।\n- चोयु हिमालको उचाइ ८,२०१ मिटर रहेको छ।\n- धवलागिरि हिमालको उचाइ ८,१६७ मिटर रहेको छ।\n- मनास्लु हिमालको उचाइ ८,१६३ मिटर रहेको छ।', 'nepali'),
      (v_set_id, 9, E'आधुनिक प्रयोगका पिताको रुपमा कसलाई मानिन्छ?', E'पेट्रार्च', E'मार्टिन लुथर किङ', E'रोजर बेकन', E'दाँते', 'C', E'**इङ्गल्याण्डका रोजर बेकनलाई आधुनिक प्रयोगका पिता मानिन्छ।**\n- इटालीका पेट्रार्चलाई मानवतावादको संस्थापक मानिन्छ।\n- मार्टिन लुथर किङ जर्मनीका धार्मिक सुधार आन्दोलनका प्रवर्तक थिए।\n- इटालीका दाँतेलाई पुनर्जागरणका प्रथम व्यक्ति (अग्रज) मानिन्छ र उनी ''डिभाइन कमेडी'' का लेखक हुन्।', 'nepali'),
      (v_set_id, 10, E'लिच्छविकालिनका समयमा जिल्ला सरकारी कार्यालयलाई के भनिन्थ्यो?', E'ग्राम', E'विषय', E'तल', E'चारभाट', 'B', E'**लिच्छविकालमा जिल्ला सरकारी कार्यालयलाई ''विषय'' भनिन्थ्यो।**\n- ''ग्राम'' भन्नाले स-साना गाउँलाई बुझिन्थ्यो।\n- ''तल'' भन्नाले विकसित गाउँलाई चिनिन्थ्यो।\n- ''चारभाट'' प्रहरीलाई भनिने शब्द थियो।', 'nepali'),
      (v_set_id, 11, E'नेपालको इतिहासमा शिक्षाका पिताको रुपमा कुन राणा प्रधानमन्त्रीलाई चिनिन्छ?', E'पदम समसेर', E'देव समसेर', E'भिम समसेर', E'चन्द्र समसेर', 'B', E'**राणा प्रधानमन्त्री देव समसेरलाई ''शिक्षाका पिता'' र ''धनकुटे महाराज'' उपनामले चिनिन्छ।**\n- पदम समसेरलाई ''रुन्चे महाराज'' र ''स्कुलमा पिता'' भनेर चिनिन्थ्यो।', 'nepali'),
      (v_set_id, 12, E'हुक्काहुक्की पर्व कुन जातिमा प्रचलित रहेको छ?', E'छन्त्याल', E'राजवंशी', E'ह्याल्मो', E'सुनुवार', 'B', E'हुक्काहुक्की पर्व **राजवंशी जातिमा** प्रचलित छ।\nनोट: राजवंशी जातिले नयाँ वर्षको रुपमा बैशाख १ र २ गते सिरुवा पर्व पनि मनाउँछन्।', 'nepali'),
      (v_set_id, 13, E'ऊर्जासँग सम्बन्धित प्रसिद्ध सूत्र Concept of mass- energy equivalence (E = mc²) पत्ता लगाउने वैज्ञानिक को हुन्?', E'Archimedes', E'Albert einstein', E'Sir isaac newton', E'Galileo galilei', 'B', E'**अल्बर्ट आइन्स्टाइनले** ऊर्जा-पिण्ड समतुल्यताको प्रसिद्ध सूत्र (E = mc²) पत्ता लगाएका हुन्।\n- आर्किमिडिजले उत्प्लावनको सिद्धान्त (principle of buoyancy) प्रतिपादन गरेका थिए।\n- सर आइज्याक न्यूटन गुरुत्वाकर्षण र गतिको नियमहरूका लागि परिचित छन्।\n- ग्यालिलियो ग्यालिलीले खगोल विज्ञानमा टेलिस्कोपको प्रयोग गरी महत्वपूर्ण खोजहरू गरेका थिए।\nनोट: आइन्स्टाइनले प्रकाश-विद्युतीय असर (Photoelectric Effect) को सिद्धान्त पनि दिएका थिए, जसका लागि उनले नोबेल पुरस्कार पाए।', 'nepali'),
      (v_set_id, 14, E'अपिनाम्पा संरक्षण क्षेत्र नेपालको कुन जिल्लामा पर्दछ?', E'धादिङ', E'दार्चुला', E'दोलखा', E'दैलेख', 'B', E'अपिनाम्पा संरक्षण क्षेत्र **दार्चुला जिल्लामा** अवस्थित छ।\nनोट: यो संरक्षण क्षेत्र वि.सं. २०६७ मा स्थापना भएको हो र यसको क्षेत्रफल १,९०३ वर्ग किलोमिटर छ।', 'nepali'),
      (v_set_id, 15, E'संयुक्त राष्ट्रसंघको महासभामा अध्यक्ष रहने व्यवस्था कहिले देखि सुरु भएको हो?', E'सन् १९४५', E'सन् १९४६', E'सन् १९४७', E'सन् १९४८', 'B', E'संयुक्त राष्ट्रसंघको महासभामा अध्यक्ष रहने व्यवस्था **सन् १९४६** देखि सुरु भएको हो।\nनोट: महासभाका प्रथम अध्यक्ष बेल्जियमका पाउल-हेनरी स्पाक थिए, जो सोही वर्ष निर्वाचित भएका थिए।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/१२', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_17.csv  →  आसमान दैनिक GK — २०८२/११/१७  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/१७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/१७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/१७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आर्थिक सर्वेक्षण २०७९/८२ अनुसार आधारभूत तह (कक्षा १-८) खुद भर्नादर कति छ?', E'९४.३ प्रतिशत', E'९४.७ प्रतिशत', E'९४.६ प्रतिशत', E'९४.९ प्रतिशत', 'D', E'आर्थिक सर्वेक्षण २०७९/८२ अनुसार आधारभूत तह (कक्षा १-८) को खुद भर्नादर **९४.९ प्रतिशत** रहेको छ।\nनोट: सोही सर्वेक्षण अनुसार, आधारभूत तह (कक्षा १-५) को खुद भर्नादर ९४.४% र आधारभूत तह (कक्षा ६-८) को खुद भर्नादर ९३.६% रहेको छ।', 'nepali'),
      (v_set_id, 2, E'सरकारले सातै प्रदेशमा नयाँ पर्यटकीय गन्तव्य अन्तर्गत कुन प्रदेशको पर्यटकीय गन्तव्य निग्लिहवा हो?', E'कर्णाली प्रदेश', E'लुम्बिनी प्रदेश', E'कोशी प्रदेश', E'गण्डकी प्रदेश', 'B', E'सरकारले घोषणा गरेको नयाँ पर्यटकीय गन्तव्य निग्लिहवा **लुम्बिनी प्रदेशको** कपिलवस्तुमा पर्दछ।\n- कर्णाली प्रदेशको नयाँ पर्यटकीय गन्तव्य मुगुको रारा हो।\n- कोशी प्रदेशको नयाँ पर्यटकीय गन्तव्य इलामको सन्दकपुर हो।\n- गण्डकी प्रदेशको नयाँ पर्यटकीय गन्तव्य कास्कीको पञ्चासे हो।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधान अनुसार राष्ट्रिय सभामा सदस्यहरूको पदावधि कति वर्षको हुने गर्दछ ?', E'४ वर्ष', E'५ वर्ष', E'६ वर्ष', E'३ वर्ष', 'C', E'नेपालको संविधान अनुसार राष्ट्रिय सभाका सदस्यहरूको पदावधि **६ वर्षको** हुन्छ।\nनोट: प्रतिनिधि सभाको कार्यकाल भने ५ वर्षको हुन्छ, तर संविधान बमोजिम अगावै विघटन हुन सक्ने प्रावधान छ।', 'nepali'),
      (v_set_id, 4, E'सौर्यमण्डलमा कति धुमकेतु रहेका छन्?', E'३००० बढी', E'३२०० बढी', E'३४०० बढी', E'३६०० बढी', 'B', E'सौर्यमण्डलमा **३२०० भन्दा बढी** धुमकेतुहरू रहेको अनुमान छ। धुमकेतुहरू सूर्यको वरिपरि अण्डाकार कक्षमा घुम्ने ग्याँस र बरफका डल्लाहरू हुन्, जसलाई पुच्छ्रेतारा पनि भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'हिन्द महासागरको सबैभन्दा ठूलो सागर कुन हो?', E'अरब सागर', E'लाल सागर', E'बंगाल सागर', E'लक्कडिव सागर', 'A', E'**हिन्द महासागरको सबैभन्दा ठूलो सागर अरब सागर हो।**\n- लाल सागर अफ्रिका र एसियाको बीचमा अवस्थित एक साँघुरो सागर हो।\n- बंगाल सागर विश्वको सबैभन्दा ठूलो खाडी (bay) हो, तर क्षेत्रफलमा यो अरब सागरभन्दा सानो छ।\n- लक्कडिव सागरले माल्दिभ्सलाई भारतबाट अलग गर्दछ र यो एक सानो सागर हो।', 'nepali'),
      (v_set_id, 6, E'नेपालमा कहिलेबाट पर्वतारोहणका लागि हिमाललाई खुला गर्न थालिएको हो?', E'सन् १९४९', E'सन् १९४८', E'सन् १९४७', E'सन् १९४६', 'A', E'नेपालमा पर्वतारोहणका लागि **सन् १९४९** देखि हिमालहरू खुला गर्न थालिएको हो।\nनोट: पर्वतारोहणका लागि खुला गरिएको पहिलो हिमाल अन्नपूर्ण थियो।', 'nepali'),
      (v_set_id, 7, E'नेपालको सबैभन्दा कान्छो उपत्यकाका रूपमा प्रसिद्ध ''जोगबुडा उपत्यका'' कुन जिल्लामा अवस्थित प्रसिद्ध उपत्यका हो?', E'रुकुम पश्चिम', E'लमजुङ', E'डडेलधुरा', E'मुस्ताङ', 'C', E'**नेपालको सबैभन्दा कान्छो उपत्यका मानिने जोगबुडा उपत्यका डडेलधुरा जिल्लामा अवस्थित छ।**\n- रुकुम पश्चिम जिल्लामा चौरजहारी उपत्यका पर्दछ।\n- लमजुङ जिल्लामा कर्पूटार उपत्यका रहेको छ।\n- मुस्ताङ जिल्लामा थाकखोला उपत्यका अवस्थित छ।', 'nepali'),
      (v_set_id, 8, E'हाल नेपालमा कति प्रजातिका चराहरु रहेका छन् ? (सन् २०२५ सम्ममा)', E'९०४ वटा', E'९०३ वटा', E'९०२ वटा', E'९०१ वटा', 'B', E'हाल नेपालमा **९०३ प्रजातिका** चराहरू रहेका छन्।\nनोट: ९०३ औं प्रजातिको रूपमा रातोकण्ठे डुबुल्कीचरालाई सुर्खेतको बुलबुले तालमा फेला पारिएको थियो।', 'nepali'),
      (v_set_id, 9, E'दोस्रो राष्ट्रिय आर्थिक गणना, २०८२ को सुरुवात कहिले देखि हुँदैछ ?', E'२०८२ फागुन १', E'२०८२ चैत १', E'२०८३ बैशाख १', E'२०८३ जेठ १', 'B', E'दोस्रो राष्ट्रिय आर्थिक गणना **२०८२ चैत १** गतेदेखि सुरु भएको थियो। राष्ट्रिय तथ्यांक कार्यालयले २०८२ चैत १ देखि असार मसान्तसम्म यो गणना सञ्चालन गरेको हो।\nनोट: यसअघि पहिलो राष्ट्रिय आर्थिक गणना २०७५ सालमा गरिएको थियो।', 'nepali'),
      (v_set_id, 10, E'अमेरिकामा स्वतन्त्र दिवस कुन तारिखमा मनाइन्छ?', E'अक्टोबर १६', E'अगस्ट १२', E'जुलाई ४', E'जुन १२', 'C', E'अमेरिकामा स्वतन्त्रता दिवस हरेक वर्ष **जुलाई ४** मा मनाइन्छ। अमेरिकी काङ्ग्रेसले ४ जुलाई, १७७६ मा स्वतन्त्रताको घोषणालाई स्वीकार गरेको दिनको सम्झनामा यो दिवस मनाइन्छ।\nनोट: अमेरिकी स्वतन्त्रताको घोषणापत्रमा ५६ जना व्यक्तिले हस्ताक्षर गरेका थिए।', 'nepali'),
      (v_set_id, 11, E'नारायणहिटी राजदरबारमा बस्ने पहिलो शाहवंशीय राजा को हुन्?', E'पृथ्वी वीर विक्रम शाह', E'त्रिभुवन वीर विक्रम शाह', E'राजेन्द्र वीर विक्रम शाह', E'सुरेन्द्र वीर विक्रम शाह', 'A', E'नारायणहिटी राजदरबारमा बस्ने पहिलो शाहवंशीय राजा **पृथ्वी वीर विक्रम शाह** हुन्।\nनोट: नेपालको राजदरबार वि.सं. १९४३ मा हनुमान ढोकाबाट नारायणहिटीमा सारिएको थियो, जुन समयमा पृथ्वी वीर विक्रम शाह राजा थिए।', 'nepali'),
      (v_set_id, 12, E'१९८१ मा चन्द्र शमशेरको पालामा दास प्रथा अन्त्य हुँदा कति जना दासत्व बाट मुक्त भएका थिए?', E'५९, ८९० जना', E'५८, ८९० जना', E'५९, ८९० जना', E'५६, ८९० जना', 'A', E'वि.सं. १९८१ मा चन्द्र शमशेरले दास प्रथा अन्त्य गर्दा करिब **५९, ८९० जना** दासत्वबाट मुक्त भएका थिए। दास दासीको व्यवस्थापन गर्न तत्कालीन समयमा रू ३६ लाख ७० हजार पशुपतिको गुठीबाट लिइएको थियो र राज्यले रकम भुक्तानी गरी मालिकहरूलाई दास मुक्त गर्न लगाएको थियो।', 'nepali'),
      (v_set_id, 13, E'What is the full form of LAN?', E'Large Area Network', E'Long Access Network', E'Local Area Network', E'Linked Address Node', 'C', E'कम्प्युटर सञ्जालमा LAN को पूरा रूप **Local Area Network** हो।\nनोट: यसैगरी, MAN को पूरा रूप Metropolitan Area Network र WAN को पूरा रूप Wide Area Network हुन्छ।', 'nepali'),
      (v_set_id, 14, E'जनगणना २०६८ अनुसार नेपालको जनघनत्व कति थियो?', E'१८० जना प्रतिवर्ग किलोमिटर', E'१८४ जना प्रतिवर्ग किलोमिटर', E'१९० जना प्रतिवर्ग किलोमिटर', E'१९८ जना प्रतिवर्ग किलोमिटर', 'A', E'राष्ट्रिय जनगणना २०६८ अनुसार नेपालको जनघनत्व **१८० जना प्रतिवर्ग किलोमिटर** रहेको थियो।\nनोट: सोही जनगणना अनुसार नेपालको जनसंख्या वृद्धिदर १.३५% थियो।', 'nepali'),
      (v_set_id, 15, E'नेपालको आधुनिक परराष्ट्र नीतिका निर्माता कसलाई मानिन्छ?', E'राजा वीरेन्द्र', E'राम शाह', E'राजा महेन्द्र', E'पृथ्वीनारायण शाह', 'C', E'**राजा महेन्द्रलाई** नेपालको आधुनिक परराष्ट्र नीतिका निर्माता मानिन्छ।\n- राजा वीरेन्द्रले नेपाललाई शान्ति क्षेत्र प्रस्ताव गर्ने नीतिका लागि चिनिन्छन्।\n- राम शाह न्याय र प्रशासनिक सुधारका लागि प्रसिद्ध थिए।\n- पृथ्वीनारायण शाहलाई नेपालको परराष्ट्र नीतिका प्रवर्तक मानिन्छ।', 'nepali'),
      (v_set_id, 16, E'आर्थिक सर्वेक्षण २०७९/८० अनुसार माध्यमिक तह (कक्षा ९-१२) खुद भर्ना दर कति छ?', E'५५.५ प्रतिशत', E'५५.८ प्रतिशत', E'५५.६ प्रतिशत', E'५५.९ प्रतिशत', 'B', E'आर्थिक सर्वेक्षण २०७९/८० अनुसार माध्यमिक तह (कक्षा ९-१२) को खुद भर्ना दर **५५.८ प्रतिशत** रहेको छ।\nनोट: यस सर्वेक्षणले नेपालको शिक्षा क्षेत्रको पछिल्लो अवस्थालाई चित्रण गर्दछ।', 'nepali'),
      (v_set_id, 17, E'हालसालै सडक सञ्जाल पुगेको ७७ औं जिल्ला सदरमुकाम कुन हो?', E'दुनै', E'सिमिकोट', E'गमगढी', E'दिपायल', 'B', E'**हुम्लाको सिमिकोट** हालसालै सडक सञ्जाल पुगेको ७७ औं जिल्ला सदरमुकाम हो।\n- डोल्पाको दुनै ७६ औं जिल्ला सदरमुकाम हो जहाँ २०७५ मंसिर ४ गते सडक पुगेको थियो।\n- गमगढी मुगु जिल्लाको सदरमुकाम हो।\n- दिपायल डोटी जिल्लाको सदरमुकाम हो।\nनोट: सिमिकोट २०७९ असार २२ गते राष्ट्रिय सडक सञ्जालमा जोडिएको थियो।', 'nepali'),
      (v_set_id, 18, E'नेपालको संघीय व्यवस्थापिका कति वटा रहेको छ?', E'१ वटा', E'२ वटा', E'३ वटा', E'४ वटा', 'A', E'नेपालको संविधानको भाग ८ को धारा ८३ अनुसार संघीय व्यवस्थापिका (संघीय संसद) **एक वटा** रहेको छ।\n- यस संघीय व्यवस्थापिकामा प्रतिनिधि सभा र राष्ट्रिय सभा नामका दुई सदन रहेका छन्।', 'nepali'),
      (v_set_id, 19, E'मार्च २१ मा दिन र रात बराबर हुने गर्दछ, हामी त्यो दिनलाई के उपनामले चिन्छौं?', E'मकर क्रान्ति', E'शरद सम्पात', E'कर्कट क्रान्ति', E'बसन्त सम्पात', 'D', E'मार्च २१ मा दिन र रात बराबर हुने दिनलाई **बसन्त सम्पात (Vernal Equinox)** भनिन्छ।\n- मकर क्रान्ति (Winter Solstice) सामान्यतया डिसेम्बर २२ मा हुन्छ, जुन उत्तरी गोलार्धमा सबैभन्दा छोटो दिन हो।\n- शरद सम्पात (Autumnal Equinox) सेप्टेम्बर २३ मा हुन्छ, जब दिन र रात बराबर हुन्छन्।\n- कर्कट क्रान्ति (Summer Solstice) सामान्यतया जुन २१ मा हुन्छ, जुन उत्तरी गोलार्धमा सबैभन्दा लामो दिन हो।\nनोट: दिन र रात बराबर हुने अवस्थालाई सम्पात (Equinox) भनिन्छ।', 'nepali'),
      (v_set_id, 20, E'एसिया, अफ्रिका र अस्ट्रेलिया महादेशको बीचमा रहेको महासागर कुन हो?', E'आन्ध्र', E'हिन्द', E'प्रशान्त', E'कुमेरु', 'B', E'**एसिया, अफ्रिका र अस्ट्रेलिया महादेशको बीचमा हिन्द महासागर रहेको छ।**\nनोट: नेपालबाट सबैभन्दा नजिकको दूरीमा रहेको महासागर पनि हिन्द महासागर नै हो, जुन एसियाको दक्षिणमा, अफ्रिकाको पूर्वमा र अस्ट्रेलियाको उत्तर-पश्चिममा अवस्थित छ।', 'nepali'),
      (v_set_id, 21, E'स्थानीय सरकार सञ्चालन ऐन २०७४ अनुसार नेपालका जिल्लाहरूलाई कति भागमा बर्गिकरण गरिएको छ?', E'३ भागमा', E'४ भागमा', E'५ भागमा', E'७ भागमा', 'C', E'स्थानीय सरकार सञ्चालन ऐन, २०७४ अनुसार नेपालका जिल्लाहरूलाई **५ भागमा** वर्गीकरण गरिएको छ।\n- ती वर्गहरूमा हिमालका २१, पहाडका २८, तराईका १८, उपत्यकाका ३ र भित्री मधेसका ७ जिल्लाहरू पर्दछन्।', 'nepali'),
      (v_set_id, 22, E'''पाटन उपत्यका'' कुन जिल्लामा अवस्थित रहेको छ?', E'प्युठान', E'बैतडी', E'चितवन', E'ललितपुर', 'B', E'**''पाटन उपत्यका'' बैतडी जिल्लामा अवस्थित छ।**\n- प्युठान जिल्लामा भिमरूक उपत्यका रहेको छ।\n- चितवन जिल्लामा माडी उपत्यका अवस्थित छ।\n- ललितपुर जिल्ला काठमाडौं उपत्यकाको एक भाग हो, तर प्रश्नमा सोधिएको पाटन उपत्यका बैतडीमा पर्दछ।\nनोट: दार्चुला जिल्लामा व्यास उपत्यका रहेको छ।', 'nepali'),
      (v_set_id, 23, E'गोल्डेन ग्लोब्स अवार्डस्, २०२५ मा उत्कृष्ट चलचित्र बन्न सफल चलचित्र कुन हो ?', E'The Brutalist', E'Dune: Part Two', E'Conclave', E'September 5', 'A', E'**''The Brutalist''** ले सन् २०२५ को ८२औं गोल्डेन ग्लोब्स अवार्डस्मा उत्कृष्ट चलचित्र (Best Motion Picture – Drama) को उपाधि जितेको थियो।\nनोट: गोल्डेन ग्लोब्स अवार्डस् हलिउड फरेन प्रेस एसोसिएसनद्वारा चलचित्र तथा अमेरिकी टेलिभिजनमा उत्कृष्टताको लागि वार्षिक रूपमा प्रदान गरिन्छ।', 'nepali'),
      (v_set_id, 24, E'प्रतिनिधि सभा निर्वाचन, २०८२ कुल कति मतदान केन्द्रमा निर्वाचन हुँदैछ ?', E'२१ हजार १ सय १२', E'२२ हजार १ सय १२', E'२३ हजार १ सय १२', E'२४ हजार १ सय १२', 'C', E'प्रतिनिधि सभा निर्वाचन, २०८२ का लागि कुल **२३,११२** मतदान केन्द्र निर्धारण गरिएको थियो।\n- उक्त निर्वाचनका लागि कुल मतदाता १ करोड ८९ लाख ३ हजार ६८९ रहेका थिए भने मतदान स्थलको संख्या १०,९६७ थियो।\nनोट: यो निर्वाचन २०८२ फागुन २१ गते सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 25, E'अमेरिकामा संविधान कहिले लागु भएको थियो?', E'सन् १७८९', E'सन् १७८७', E'सन् १७८५', E'सन् १७८३', 'A', E'**सन् १७८९** मा संयुक्त राज्य अमेरिकामा संविधान लागू भएको थियो।\n- यो विश्वको पहिलो लिखित संविधान मानिन्छ, जुन फिलाडेल्फिया कन्भेन्सनद्वारा सन् १७८७ मा तयार पारिएको थियो र सन् १७८९ मार्च ४ देखि प्रभावकारी भयो।', 'nepali'),
      (v_set_id, 26, E'शाहवंशीय राजाहरूमा नामको पछाडि विक्रम थप्ने पहिलो राजा को हुन्?', E'गिर्वाणयुद्ध विक्रम शाह', E'त्रैलोक्य विक्रम शाह', E'राजेन्द्र विक्रम शाह', E'त्रिभुवन विक्रम शाह', 'A', E'शाहवंशीय राजाहरूमा नामको पछाडि ''विक्रम'' उपाधि जोड्ने पहिलो राजा **गिर्वाणयुद्ध विक्रम शाह** हुन्।\n- त्रैलोक्य विक्रम शाह राजा सुरेन्द्रका छोरा थिए, जसको युवराज अवस्थामै निधन भयो।\n- राजेन्द्र विक्रम शाह गिर्वाणयुद्धका छोरा थिए, जसको शासनकालमा कोतपर्व र भण्डारखाल पर्व जस्ता घटनाहरू भए।\n- त्रिभुवन विक्रम शाहले नेपालमा राणा शासनको अन्त्य गर्न महत्त्वपूर्ण भूमिका खेलेका थिए।\nनोट: राजा रणबहादुर शाहले आफ्नी प्रिय रानी कान्तिमतीतर्फका छोरालाई नियमविपरीत राजा बनाएपछि ''विक्रम'' उपाधि जोडिन थालेको हो।', 'nepali'),
      (v_set_id, 27, E'दासप्रथा अन्त्य गर्ने विश्वको पहिलो मुलुक कुन हो?', E'जापान', E'अमेरिका', E'डेनमार्क', E'बेलायत', 'C', E'दासप्रथा अन्त्य गर्ने विश्वको पहिलो मुलुक **डेनमार्क** हो।\n- जापानले १९ औं शताब्दीको मेइजी पुनर्स्थापनाको समयमा सामन्तवादसँगै दासप्रथाका स्वरूपहरू अन्त्य गर्‍यो।\n- अमेरिकाले सन् १८६५ मा १३ औं संविधान संशोधनमार्फत दासप्रथा अन्त्य गरेको थियो।\n- बेलायतले सन् १८३३ मा ''स्लेभरी अबोलिसन एक्ट'' (Slavery Abolition Act) पारित गरी दासप्रथालाई गैरकानुनी घोषणा गर्‍यो।\nनोट: अफ्रिकी मुलुक मौरिटानिया दासप्रथा उन्मूलनको घोषणा गर्ने विश्वको अन्तिम राष्ट्र हो।', 'nepali'),
      (v_set_id, 28, E'विश्व रक्तदाता दिवस (International Blood Donor Day) हरेक वर्ष कुन तारिखमा मनाइन्छ?', E'डिसेम्बर १', E'मे ८', E'१४ जुन', E'७ अप्रिल', 'C', E'विश्व रक्तदाता दिवस (International Blood Donor Day) हरेक वर्ष **१४ जुनमा** मनाइन्छ।\n- डिसेम्बर १ मा विश्व एड्स दिवस मनाइन्छ।\n- मे ८ मा विश्व रेडक्रस दिवस मनाइन्छ।\n- अप्रिल ७ मा विश्व स्वास्थ्य दिवस मनाइन्छ।', 'nepali'),
      (v_set_id, 29, E'दिगो विकासको लक्ष्य कति वर्षे विश्व विकासको मार्गचित्र हो?', E'१५ वर्षे', E'२० वर्षे', E'२५ वर्षे', E'३० वर्षे', 'A', E'दिगो विकासका लक्ष्यहरू (SDGs) **१५ वर्षे** विश्वव्यापी विकास मार्गचित्र हुन्। यो कार्ययोजना सन् २०१६ जनवरी १ देखि सुरु भई सन् २०३० डिसेम्बर ३१ मा समाप्त हुनेछ।\nनोट: यसलाई ''एजेन्डा २०३०'' पनि भनिन्छ र यसमा १७ वटा मुख्य लक्ष्यहरू समावेश छन्।', 'nepali'),
      (v_set_id, 30, E'नेपालसँग दौत्य सम्बन्ध कायम गरेको अन्तिम सार्क मुलुक कुन हो?', E'बंगलादेश', E'भुटान', E'म्यानमार', E'थाइल्यान्ड', 'B', E'नेपालसँग दौत्य सम्बन्ध कायम गर्ने अन्तिम सार्क मुलुक **भुटान** हो, जससँग सन् १९८३ जुन ३ मा सम्बन्ध स्थापित भएको थियो।\n- बंगलादेशसँग सन् १९७२ अप्रिल ८ मा दौत्य सम्बन्ध कायम भएको थियो।\n- म्यानमार र थाइल्यान्ड सार्कका सदस्य राष्ट्र होइनन्।\nनोट: नेपालसँग दौत्य सम्बन्ध कायम गर्ने पहिलो सार्क मुलुक भारत हो (सन् १९४७ जुन १३)।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/१७', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_18.csv  →  आसमान दैनिक GK — २०८२/११/१८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/१८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/१८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/१८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आर्थिक सर्वेक्षण २०८९/८२ अनुसार प्रति उद्योग रोजगारी सङ्ख्या औसतमा कति रहेको छ?', E'७१ जना', E'७३ जना', E'७५ जना', E'७७ जना', 'B', E'आर्थिक सर्वेक्षण २०८९/८२ अनुसार प्रति उद्योग रोजगारी सङ्ख्या औसतमा **७३ जना** रहेको छ। यस सर्वेक्षण अनुसार ठूला उद्योगमा प्रति उद्योग १३६ जना, मझौलामा ९० जना र सानामा ५३ जनाले रोजगारी पाएका छन्।', 'nepali'),
      (v_set_id, 2, E'एक गाउँ एक उत्पादन कार्यक्रम (OVOP) हाल नेपालका कति जिल्लामा सञ्चालित छ?', E'३२ जिल्ला', E'४२ जिल्ला', E'७७ जिल्ला', E'६६ जिल्ला', 'B', E'एक गाउँ एक उत्पादन कार्यक्रम (OVOP) हाल नेपालका **४२ जिल्ला**मा सञ्चालित छ। यो कार्यक्रम आर्थिक वर्ष २०६३/६४ देखि दोलखा जिल्लाको लोक्ता खेतीबाट सुरु भएको थियो। सुरुमा ३२ जिल्लामा सञ्चालित यो कार्यक्रममा आर्थिक वर्ष २०७०/७१ बाट १० जिल्ला थप गरिएको थियो।', 'nepali'),
      (v_set_id, 3, E'कसैलाई पनि मृत्युदण्डको सजाय दिने गरी कानून बनाइने छैन। यो नेपालको संविधानको कुन हक अन्तर्गत रहेको छ?', E'सम्मानपूर्वक बाँच्न पाउने हक', E'न्याय सम्बन्धि हक', E'अपराध पिडितको हक', E'यातना विरुद्धको हक', 'A', E'कसैलाई पनि मृत्युदण्डको सजाय दिने गरी कानून नबनाइने व्यवस्था **सम्मानपूर्वक बाँच्न पाउने हक** अन्तर्गत पर्दछ।\n- न्याय सम्बन्धि हकले स्वच्छ सुनुवाइ र कानूनी सहायताको अधिकार सुनिश्चित गर्दछ।\n- अपराध पीडितको हकले पीडितलाई क्षतिपूर्ति सहितको न्याय पाउने अधिकार दिन्छ।\n- यातना विरुद्धको हकले शारीरिक वा मानसिक यातना वा क्रूर व्यवहारबाट संरक्षण प्रदान गर्दछ।\nनोट: यो हक नेपालको संविधानको धारा १६ मा व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 4, E'सौर्यमण्डलका ८ वटा ग्रहहरू मध्ये अन्य कति वटा ग्रहहरूलाई पृथ्वीबाट नाङ्गो आँखाले देख्न सकिन्छ?', E'अन्य ७ वटै', E'अन्य ५ वटा', E'अन्य २ वटा', E'अन्य ४ वटा', 'B', E'सौर्यमण्डलका ८ ग्रहहरूमध्ये **५ वटा** ग्रहलाई पृथ्वीबाट नाङ्गो आँखाले देख्न सकिन्छ।\nनोट: बुध, शुक्र, मंगल, वृहस्पति र शनि पृथ्वीबाट नाङ्गो आँखाले देखिने पाँच ग्रहहरू हुन्।', 'nepali'),
      (v_set_id, 5, E'२०८२ मा कति औं राष्ट्रिय पोसाक तथा टोपी दिवस मनाइएको छ ?', E'११ औं', E'१२ औं', E'१३ औं', E'१४ औं', 'C', E'वि.सं. २०८२ पौष १७ गते (सन् २०२६ जनवरी १) मा **१३ औं** राष्ट्रिय पोसाक तथा टोपी दिवस मनाइएको छ।\nनोट: वि.सं. २०७० देखि हरेक वर्ष जनवरी १ मा यो दिवस मनाउन सुरु गरिएको थियो।', 'nepali'),
      (v_set_id, 6, E'हाल सालै २०२६ मा कुन मुलुकका राष्ट्रप्रमुखलाई अमेरिकी सेना द्वारा पक्राउ गरी अमेरिकाको कब्जामा राखिएको हो ?', E'इरान', E'भेनेजुएला', E'युक्रेन', E'बोलिभिया', 'B', E'सन् २०२६ जनवरी ३ मा **भेनेजुएलाका** राष्ट्रपति निकोलस मादुरो र उनकी पत्नीलाई अमेरिकी सेनाले पक्राउ गरी आफ्नो कब्जामा राखेको थियो।\nनोट: उनीहरूमाथि लागुऔषध ओसारपसार र अमेरिकामा अपराध फैलाएको आरोप लगाइएको थियो।', 'nepali'),
      (v_set_id, 7, E'विश्वमा ३ वटा राजधानी भएको मुलुक कुन हो?', E'ट्युनेसिया', E'केप भर्डे', E'मैरिसस', E'दक्षिण अफ्रिका', 'D', E'**दक्षिण अफ्रिका** विश्वको एकमात्र तीनवटा राजधानी भएको मुलुक हो।\n- ट्युनेसियाको राजधानी ट्युनिस हो।\n- केप भर्डेको राजधानी प्राइया हो।\n- मैरिससको राजधानी पोर्ट लुइस हो।\nनोट: दक्षिण अफ्रिकाका तीन राजधानीहरू प्रिटोरिया (कार्यकारी), केप टाउन (विधायिकी) र ब्लोमफोन्टेन (न्यायिक) हुन्।', 'nepali'),
      (v_set_id, 8, E'जनसंख्या कम भएका गाउँपालिका नार्पा भूमीको कति जनसंख्या रहेको छ?', E'३९२ जना', E'३९४ जना', E'३९६ जना', E'३९८ जना', 'C', E'नेपालको सबैभन्दा कम जनसंख्या भएको गाउँपालिका मनाङ जिल्लाको नार्पा भूमी हो, जसको जनसंख्या **३९६ जना** रहेको छ।\nनोट: नार्पा भूमी पछि क्रमशः चामे, लो-घेकर दामोदरकुण्ड, र ल्हो-मन्थाङ गाउँपालिकाहरू कम जनसंख्या भएका गाउँपालिका हुन्।', 'nepali'),
      (v_set_id, 9, E'मकवानपुरको पुरानो जिल्ला सदरमुकाम कुन हो?', E'बन्दीपुर', E'भिमफेदि', E'हनुमाननगर', E'चैनपुर', 'B', E'**मकवानपुरको पुरानो जिल्ला सदरमुकाम भिमफेदि हो।**\n- बन्दीपुर तनहुँ जिल्लाको पुरानो सदरमुकाम हो।\n- हनुमाननगर सप्तरी जिल्लाको पुरानो सदरमुकाम हो।\n- चैनपुर संखुवासभा जिल्लाको पुरानो सदरमुकाम हो।', 'nepali'),
      (v_set_id, 10, E'फ्रान्सका राजा लुई १६ औं लाई कहिले मृत्युदण्ड दिइएको हो?', E'१७९२ सेप्टेम्बर २१', E'१७९३ मार्च १५', E'१७९३ अक्टोबर १६', E'१७९३ जनवरी २१', 'D', E'फ्रान्सका राजा लुई १६ औं लाई **सन् १७९३ जनवरी २१** मा मृत्युदण्ड दिइएको थियो।\nनोट: उनकी पत्नी, महारानी एन्टोइनेटलाई सोही वर्षको अक्टोबर १६ मा मृत्युदण्ड दिइएको थियो भने फ्रान्समा राजतन्त्रको अन्त्य सन् १७९२ सेप्टेम्बर २१ मा भएको थियो।', 'nepali'),
      (v_set_id, 11, E'राजा रामचन्द्र नेपालको प्राचीन इतिहासमा कुन युगका राजा मानिन्छन्?', E'त्रेतायुग', E'द्वापर युग', E'सत्ययुग', E'कलि युग', 'A', E'**राजा रामचन्द्र त्रेतायुगका राजा मानिन्छन्।**\n- द्वापर युगका राजा युधिष्ठिर थिए।\n- सत्ययुगका राजा ययाति थिए।\n- कलि युगका राजा भोजराज थिए।', 'nepali'),
      (v_set_id, 12, E'विश्वमा नेपाल कति औं धर्म निरपेक्ष मुलुक हो?', E'२२ औं', E'१८ औं', E'२० औं', E'१६ औं', 'D', E'विश्वमा नेपाल **१६ औं** धर्म निरपेक्ष मुलुक हो।\nनोट: नेपाललाई २०६३ जेठ ४ गते धर्मनिरपेक्ष राष्ट्र घोषणा गरिएको थियो।', 'nepali'),
      (v_set_id, 13, E'मानवको अध्ययन गर्ने विज्ञानको शाखालाई के भनिन्छ?', E'Anthropology', E'Anatomy', E'Actimology', E'humanlogy', 'A', E'मानवको अध्ययन गर्ने विज्ञानको शाखालाई **Anthropology** भनिन्छ।\nनोट: विज्ञानका अन्य शाखाहरूमा मुटुको अध्ययनलाई Cardiology, छालाको अध्ययनलाई Dermatology र कलेजोको अध्ययनलाई Hepatology भनिन्छ।', 'nepali'),
      (v_set_id, 14, E'नेपालमा कुन योजनाबाट वातावरणीय प्रभाव मूल्याङ्कन (Environment Impact Assesment) को सुरुवात समावेश गरिएको हो?', E'छैठौं योजना', E'आठौं योजना', E'नवौं योजना', E'सातौं योजना', 'D', E'**नेपालमा सातौं योजनाबाट वातावरणीय प्रभाव मूल्याङ्कन (EIA) को सुरुवात गरिएको हो।**\n- छैठौं योजनाबाट वातावरण र भूसंरक्षण नीति अवलम्बन गरिएको थियो।\n- आठौं योजनादेखि दिगो विकाससम्बन्धी नीति अवलम्बन गरिएको थियो।', 'nepali'),
      (v_set_id, 15, E'नेपाली संघिय संसदबाट एमसीसी सम्झौता अनुमोदन मिति कुन विकल्प सहि छ?', E'फागुन १५, २०७८', E'फागुन २०, २०७९', E'फागुन १५, २०७९', E'फागुन २०, २०७८', 'A', E'नेपाली संघीय संसदबाट एमसीसी सम्झौता **फागुन १५, २०७८ (27 Feb 2022)** मा अनुमोदन भएको हो।\nनोट: यो सम्झौता १२ बुँदे व्याख्यात्मक घोषणासहित तल्लो सदनबाट बहुमतले अनुमोदन गरिएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/१८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_21.csv  →  आसमान दैनिक GK — २०८२/११/२१  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/२१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/२१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/२१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालमा कुन आ.व. देखि लैङ्गिक बजेटको अवधारणा लागु गरिएको हो?', E'आ.व. २०६४/६५', E'आ.व. २०६५/६६', E'आ.व. २०६६/६७', E'आ.व. २०६७/६८', 'A', E'नेपालमा आर्थिक वर्ष **२०६४/६५** देखि लैङ्गिक उत्तरदायी बजेट प्रणाली कार्यान्वयनमा ल्याइएको हो।\nनोट: नेपालमा कार्यक्रममूलक बजेटको व्यवस्था भने आ.व. २०२६/२७ देखि लागु गरिएको थियो।', 'nepali'),
      (v_set_id, 2, E'आर्थिक सर्वेक्षण २०७९/८२ अनुसार कुल गार्हस्थ्य उत्पादनमा कृषि क्षेत्रको योगदान कति रहेको छ?', E'२५.१६ प्रतिशत', E'२४.५६ प्रतिशत', E'२४.५० प्रतिशत', E'२५.८७ प्रतिशत', 'A', E'आर्थिक सर्वेक्षण २०७९/८२ अनुसार कुल गार्हस्थ्य उत्पादनमा कृषि, वन तथा मत्स्यपालन क्षेत्रको योगदान **२५.१६ प्रतिशत** रहेको छ।\nनोट: प्राथमिक क्षेत्र अन्तर्गत नै पर्ने खानी तथा उत्खनन् क्षेत्रको योगदान भने ०.४६ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधान अनुसार राज्यका निर्देशक सिद्धान्त कतिवटा रहेको छन्?', E'७ वटा', E'४ वटा', E'१३ वटा', E'१८ वटा', 'B', E'**नेपालको संविधानको धारा ५० अनुसार राज्यका निर्देशक सिद्धान्तहरू ४ वटा रहेका छन्।**\n- संविधानको धारा ५१ मा राज्यका नीतिहरू १३ वटा उल्लेख गरिएका छन्।\nनोट: यी व्यवस्थाहरू संविधानको भाग-४, ''राज्यका निर्देशक सिद्धान्त, नीति तथा दायित्व'' अन्तर्गत पर्दछन्।', 'nepali'),
      (v_set_id, 4, E'छिमेकी मुलुक भारत अन्तरिक्ष प्रवेश गर्ने कति औं मुलुक हो?', E'छैटौं', E'पाँचौं', E'चौथो', E'तेस्रो', 'A', E'छिमेकी मुलुक भारत अन्तरिक्षमा प्रवेश गर्ने **छैटौं** मुलुक हो।\n- भारत चन्द्रमामा पुग्ने चौथो मुलुक हो।\nनोट: अन्तरिक्षमा पुग्ने मुलुकहरूको क्रम रुस, अमेरिका, फ्रान्स, जापान, चीन र भारत हो।', 'nepali'),
      (v_set_id, 5, E'सबैभन्दा पछि पत्ता लागेको महादेश कुन हो?', E'उत्तर अमेरिका', E'अन्टार्कटिका', E'अष्ट्रेलिया', E'दक्षिण अमेरिका', 'B', E'सबैभन्दा पछि पत्ता लागेको महादेश **अन्टार्कटिका** हो। यो महादेश जेम्स कुकले सन् १७७३ मा पत्ता लगाएका थिए।\nनोट: अन्टार्कटिका पुग्ने प्रथम नेपाली भुवनसिंह विश्वकर्मा हुन्।', 'nepali'),
      (v_set_id, 6, E'आइसीसी पुरुष टि-२० विश्वकप २०२६ को ट्रफी टुरको लागि नेपालमा कहिले आएको हो?', E'२०२६ जनवरी २', E'२०२६ जनवरी ३', E'२०२६ जनवरी ४', E'२०२६ जनवरी ५', 'D', E'आइसीसी पुरुष टि-२० विश्वकप २०२६ को ट्रफी टुरका लागि **२०२६ जनवरी ५** मा नेपाल ल्याइएको थियो। भारत र श्रीलंकामा संयुक्त रुपमा आयोजना हुने उक्त विश्वकपको ट्रफी टुर नेपालमा जनवरी ५ देखि ७ सम्म आयोजना भएको थियो।\nनोट: यो पहिलोपटक थियो जब टि-२० विश्वकपको ट्रफी नेपाल ल्याइएको हो।', 'nepali'),
      (v_set_id, 7, E'नेपाल पर्यटन बोर्ड अनुसार सन् २०२५ मा कति पर्यटन नेपालमा आएका छन्?', E'११ लाख ५८ हजार ४५९', E'१२ लाख ५८ हजार ४५९', E'१३ लाख ५८ हजार ४५९', E'१४ लाख ५८ हजार ४५९', 'A', E'नेपाल पर्यटन बोर्ड अनुसार सन् २०२५ मा **११ लाख ५८ हजार ४५९** पर्यटक नेपालमा आएका थिए। २०२५ मा नेपालमा धेरै पर्यटक भित्र्याउने प्रमुख मुलुकहरू निम्न थिए:\n- १. भारत: २,९२,४३८ जना (२५.२%)\n- २. अमेरिका: १,१२,३९६ जना (९.७%)\n- ३. चीन: ९५,४६० जना (८.२%)', 'nepali'),
      (v_set_id, 8, E'हिमाली जिल्ला भएर पनि चिनलाई नछुने जिल्लाहरूको संख्या कति रहेको छ?', E'५ वटा', E'६ वटा', E'७ वटा', E'८ वटा', 'B', E'हिमाली जिल्ला भएर पनि चीनलाई नछुने जिल्लाहरूको संख्या **६ वटा** रहेको छ। नेपालमा कुल २१ हिमाली जिल्लाहरू छन्, जसमध्ये १५ जिल्लाले मात्र चीनको सिमाना छुन्छन्।\nनोट: २१ हिमाली जिल्लाबाट चीनलाई छुने १५ जिल्ला घटाउँदा ६ जिल्ला बाँकी रहन्छन्।', 'nepali'),
      (v_set_id, 9, E'काठबाट तयार गरिएको धागो कात्ने मेसिन Spinning Jenny को आविष्कार कसले गरेका हुन्?', E'जेथ्रो तुल', E'James Brindl', E'जोन के', E'जेम्स हारग्रिब्स', 'D', E'काठबाट तयार गरिएको धागो कात्ने मेसिन ''स्पिनिङ जेनी'' को आविष्कार **जेम्स हारग्रिब्सले सन् १७६४ मा** गरेका हुन्।\n- जेथ्रो तुलले सन् १७१७ मा ड्रिल (जोत्ने/खन्ने) मेसिनको आविष्कार गरेका थिए।\n- जेम्स ब्रिन्ड्लीले सन् १७३१ मा नहर बनाउने प्रविधिको विकास गरेका थिए।\n- जोन केले सन् १७४३ मा कपडा बनाउने काठको मेसिन ''फ्लाइङ शटल'' को आविष्कार गरेका थिए।', 'nepali'),
      (v_set_id, 10, E'नेपालको इतिहासमा चारकुने मुद्रा प्रचलनमा ल्याउने, सेतो मच्छिन्द्रनाथको रथयात्रा सञ्चालन गर्ने राजा को हुन्?', E'प्रताप मल्ल', E'रत्न मल्ल', E'जयस्थिती मल्ल', E'जयप्रकाश मल्ल', 'A', E'नेपालको इतिहासमा चारकुने मुद्रा प्रचलनमा ल्याउने र सेतो मच्छिन्द्रनाथको रथयात्रा सञ्चालन गर्ने राजा **प्रताप मल्ल** हुन्।\n- रत्न मल्लले तामाको पैसा प्रचलनमा ल्याएका थिए।\n- जयस्थिती मल्लले समाजलाई ४ जात ३६ वर्णमा विभाजन र जग्गाको वर्गीकरण गरेका थिए।\n- जयप्रकाश मल्ल कान्तिपुरका अन्तिम मल्ल राजा थिए र उनले कुमारीको रथयात्रा चलाएका थिए।\nनोट: प्रताप मल्ललाई ''कविन्द्र'' उपनामले पनि चिनिन्छ।', 'nepali'),
      (v_set_id, 11, E'पञ्चामृत अन्तर्गत देहाएको कुन समावेश हुँदैन?', E'चिनी', E'दही', E'मह', E'घ्यू', 'A', E'पञ्चामृतमा दही, घ्यू, मह, शख्खर र गाईको दूधको मिश्रण हुन्छ, यसमा **चिनी समावेश हुँदैन**।\nनोट: हिन्दू धर्ममा पञ्चामृतलाई पवित्र मानिन्छ र यो पूजाआजामा प्रयोग गरिन्छ।', 'nepali'),
      (v_set_id, 12, E'कुसवाडिया जातिको मुख्य बसोबास क्षेत्र कुन हो?', E'बाँके, बर्दिया', E'कैलाली, कञ्चनपुर', E'दाङ, बाँके', E'सल्यान, दाङ', 'A', E'कुसवाडिया जातिको मुख्य बसोबास क्षेत्र **बाँके र बर्दिया** जिल्ला हो।\nनोट: यस जातिलाई पत्थरकट्टा र कुछबन्दिया पनि भनिन्छ र यिनीहरू आफूलाई प्रकृति पुजक भन्न रुचाउँछन्।', 'nepali'),
      (v_set_id, 13, E'सबैभन्दा महङ्गो धातु कुन हो?', E'रेडियम', E'ओस्मियम', E'लिथियम', E'हाइड्रोजन', 'A', E'सबैभन्दा महङ्गो धातु **रेडियम** हो।\n- ओस्मियम सबैभन्दा गह्रौं धातु हो।\n- लिथियम सबैभन्दा हल्का धातु हो।\n- हाइड्रोजन सबैभन्दा हल्का ग्याँस हो।', 'nepali'),
      (v_set_id, 14, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा हाल सक्रिय जनसंख्या कति प्रतिशत रहेको छ?', E'६०.९६ प्रतिशत', E'६२.९६ प्रतिशत', E'६१.९६ प्रतिशत', E'६३.९६ प्रतिशत', 'C', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा हाल सक्रिय जनसंख्या (१५ देखि ५९ वर्ष उमेर समूह) **६१.९६ प्रतिशत** रहेको छ।\nनोट: २०७८ को जनगणना अनुसार नेपालको कुल जनसंख्या २,९१,६४,५७८ रहेको छ।', 'nepali'),
      (v_set_id, 15, E'नेपालमा सार्क सचिवालय राख्न प्रस्ताव गर्ने मुलुक कुन हो?', E'पाकिस्तान', E'भारत', E'बंगलादेश', E'श्रीलंका', 'A', E'नेपालको काठमाडौंमा सार्क सचिवालय राख्न प्रस्ताव गर्ने मुलुक **पाकिस्तान** हो। यो प्रस्ताव दोस्रो सार्क शिखर सम्मेलनमा गरिएको थियो।\nनोट: काठमाडौंमा सार्क सचिवालयको स्थापना १६ जनवरी १९८७ (वि.सं. २०४३ माघ २) मा भएको थियो र यसको उद्घाटन तत्कालीन राजा वीरेन्द्रले गरेका थिए।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/२१', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_22.csv  →  आसमान दैनिक GK — २०८२/११/२२  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/२२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/२२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/२२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'देहायको मध्ये कुन खेती तुलनात्मक कम तापक्रममा पनि गर्न सकिन्छ?', E'धान', E'कोदो', E'जौ', E'मकै', 'C', E'दिएका बालीहरूमध्ये जौ खेती तुलनात्मक रूपमा कम तापक्रममा पनि गर्न सकिन्छ, जसका लागि **१० देखि २० डिग्री सेल्सियस** तापक्रम उपयुक्त हुन्छ।\n- धान खेतीका लागि २५ देखि ३० डिग्री सेल्सियस तापक्रम आवश्यक पर्छ।\n- कोदो खेतीका लागि ११ देखि २७ डिग्री सेल्सियस तापक्रम उपयुक्त मानिन्छ।\n- मकै खेतीका लागि करिब २१ डिग्री सेल्सियस तापक्रम आवश्यक हुन्छ।', 'nepali'),
      (v_set_id, 2, E'१६ औं योजनाको अन्त्यसम्म नेपालको प्रतिव्यक्ति राष्ट्रिय आय कति पुर्याउने लक्ष्य रहेको छ?', E'२२५१ अमेरिकी डलर', E'२३५१ अमेरिकी डलर', E'२४५१ अमेरिकी डलर', E'२५५१ अमेरिकी डलर', 'B', E'१६ औं पञ्चवर्षीय योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्ममा नेपालको प्रतिव्यक्ति आय **२,३५१ अमेरिकी डलर** पुर्याउने लक्ष्य निर्धारण गरिएको छ।\nनोट: आ.व. २०७९/८० को प्रगति अनुसार नेपालको प्रतिव्यक्ति आय १,४४६ अमेरिकी डलर रहेको थियो।', 'nepali'),
      (v_set_id, 3, E'नेपालको अन्तरिम संविधान, २०६३ कति पटक संशोधन गरिएको थियो?', E'१० पटक', E'१२ पटक', E'१४ पटक', E'१६ पटक', 'B', E'नेपालको अन्तरिम संविधान, २०६३ लाई जम्मा **१२ पटक** संशोधन गरिएको थियो। यो संविधान २०६३ माघ १ गते जारी भई २०७२ असोज ३ गते सम्म लागू रह्यो।\nनोट: यसै संविधानको तेस्रो संशोधनले नेपाललाई संघीय लोकतान्त्रिक गणतन्त्रात्मक राज्य घोषणा गरेको थियो।', 'nepali'),
      (v_set_id, 4, E'सूर्यग्रहण लाग्दा सूर्य र चन्द्रमाको बिचमा के भएको पाउनु भयो?', E'चन्द्रमा', E'पृथ्वी', E'सूर्य', E'भन्न सकिँदैन', 'A', E'सूर्यग्रहण लाग्दा सूर्य र पृथ्वीको बीचमा **चन्द्रमा** आउँछ, जसले गर्दा पृथ्वीबाट हेर्दा सूर्य ढाकिएको देखिन्छ।\n- पृथ्वी सूर्य र चन्द्रमाको बीचमा आएको अवस्थामा चन्द्रग्रहण लाग्छ।\n- सूर्य सौर्यमण्डलको केन्द्रमा रहेको तारा हो, जसलाई ग्रहहरूले परिक्रमा गर्छन्।', 'nepali'),
      (v_set_id, 5, E'अफ्रिका महादेशको होचो स्थान असाल ताल कुन मुलुकमा रहेको छ?', E'नाइजेरिया', E'जिबुटी', E'तान्जानिया', E'कंगो', 'B', E'अफ्रिका महादेशको होचो स्थान, असाल ताल, **जिबुटीमा** रहेको छ।\n- नाइजेरिया अफ्रिकाको सबैभन्दा बढी जनसंख्या भएको देश हो।\n- तान्जानियामा अफ्रिका महादेशको अग्लो स्थान किलिमञ्जारो पर्दछ।\n- कंगो देश कंगो नदीका लागि चिनिन्छ, जुन जलप्रवाहको हिसाबले विश्वको दोस्रो ठूलो नदी हो।\nनोट: असाल ताल समुद्र सतहबाट ५०९ फिट तल अवस्थित छ।', 'nepali'),
      (v_set_id, 6, E'ठूलो भेरी र नसिङ्गाड नदीको दोभान जाजरकोटको कुन ठाउँमा रहेको छ?', E'रिम्ना', E'दल्ली', E'मटेला', E'खलंगा', 'B', E'ठूलो भेरी र नसिङ्गाड नदीको दोभान जाजरकोटको **दल्लीमा** रहेको छ।\n- रिम्नामा सानो भेरी र ठूलो भेरी नदीको दोभान पर्दछ।\n- मटेला जाजरकोट जिल्लामै पर्ने एक ठाउँ हो।\n- खलंगा जाजरकोट जिल्लाको सदरमुकाम हो।', 'nepali'),
      (v_set_id, 7, E'२०८२ मा मनाइएको राष्ट्रिय योग दिवस कति औं हुन् ?', E'१० औं', E'११ औं', E'१२ औं', E'१३ औं', 'B', E'२०८२ सालमा मनाइएको राष्ट्रिय योग दिवस **११ औं** संस्करणको थियो।\nनोट: राष्ट्रिय योग दिवस हरेक वर्ष माघ १ गते मनाइन्छ र २०८२ को नारा ''स्वस्थ समाज, समृद्ध नेपाल र विश्व शान्तिका लागि योग'' रहेको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपालमा करदाता सेवा दिने पहिलो स्थानीय तह कुन बनेको छ ?', E'पाँचखाल गाउँपालिका', E'गैडहवा गाउँपालिका', E'केराबारी गाउँपालिका', E'सिस्ने गाउँपालिका', 'C', E'नेपालमा करदाता सेवा दिने पहिलो स्थानीय तह मोरङ जिल्लाको **केराबारी गाउँपालिका** बनेको छ। यो सेवा २०८२ पुस ०९ गतेदेखि शुभारम्भ भएको हो।\nनोट: अर्थ मन्त्री रामेश्वरप्रसाद खनालले यस सेवाको शुभारम्भ गरेका थिए।', 'nepali'),
      (v_set_id, 9, E'चुनढुङ्गाका लागि प्रसिद्ध नेपाली ठाउँ कुन हो?', E'बुद्धखोला', E'फुलचोकी', E'भैंसे दोभान', E'थाकखोला', 'C', E'हेटौंडाको **भैंसे दोभान** चुनढुङ्गाका लागि प्रसिद्ध छ।\n- तनहुँको बुद्धखोला तामाको लागि प्रसिद्ध छ।\n- काठमाडौंको फुलचोकी फलामको लागि प्रसिद्ध छ।\n- मुस्ताङको थाकखोला नुनखानीको लागि प्रसिद्ध छ।\nनोट: नेपालमा सबैभन्दा बढी प्रयोगमा ल्याइएको प्रमुख खनिज पदार्थ चुनढुङ्गा हो।', 'nepali'),
      (v_set_id, 10, E'प्रथम विश्व युद्धको अन्त्य मिति कुन विकल्प सहि छ?', E'१९१९ जुलाई २८', E'१९१९ जुलाई ११', E'१९१८ सेप्टेम्बर २', E'१९१८ नोभेम्बर ११', 'D', E'प्रथम विश्व युद्ध **१९१८ नोभेम्बर ११** मा समाप्त भएको थियो। यो युद्ध २८ जुलाई १९१४ मा सुरु भई ४ वर्ष ३ महिना ११ दिनसम्म चलेको थियो।\nनोट: दोस्रो विश्वयुद्ध भने १ सेप्टेम्बर १९३९ मा सुरु भई २ सेप्टेम्बर १९४५ मा समाप्त भएको थियो।', 'nepali'),
      (v_set_id, 11, E'परस्त्रीसँग अनुचित सम्बन्ध राखेको आरोपमा तलेजु मन्दिरमा काटिने राजा को हुन्?', E'प्रताप मल्ल', E'भुपालेन्द्र मल्ल', E'विश्वजित मल्ल', E'भाष्कर मल्ल', 'C', E'परस्त्रीसँग अनुचित सम्बन्ध राखेको आरोपमा तलेजु मन्दिरमा काटिने राजा **विश्वजित मल्ल** हुन्।\n- प्रताप मल्लले काठमाडौंमा रानीपोखरी, स्वयम्भूमा प्रतापपुर र अनन्तपुर, र हनुमानढोका दरबारको सुन्दरीचोक निर्माण गराएका थिए।\n- भुपालेन्द्र मल्लको मृत्यु तीर्थ गर्न जाँदा भएको थियो।\n- भाष्कर मल्लको मृत्यु महामारीमा परेर भएको थियो।', 'nepali'),
      (v_set_id, 12, E'मुलुकी अपराध संहिता ऐन, २०७४ अनुसार बहुविवाह गर्ने वा गराउने व्यक्तिलाई कति वर्षसम्म कैद सजाय हुन सक्छ?', E'२ वर्षसम्म', E'३ वर्षसम्म', E'४ वर्षसम्म', E'५ वर्षसम्म', 'D', E'मुलुकी अपराध संहिता ऐन, २०७४ अनुसार बहुविवाह गर्ने वा गराउने व्यक्तिलाई एक वर्षदेखि **पाँच वर्षसम्म** कैद र दश हजार रुपैयाँदेखि पचास हजार रुपैयाँसम्म जरिवाना हुन सक्ने व्यवस्था छ।', 'nepali'),
      (v_set_id, 13, E'ध्वनीको तिव्रता नाप्ने एकाइ कुन हो?', E'न्युटन', E'जुल', E'डेसिबल', E'पास्कल', 'C', E'ध्वनीको तिव्रता नाप्ने एकाइ **डेसिबल** हो।\n- न्युटन बल (Force) को एस.आई. एकाइ हो।\n- जुल ऊर्जा (Energy) वा कार्य (Work) को एस.आई. एकाइ हो।\n- पास्कल चाप (Pressure) को एस.आई. एकाइ हो।', 'nepali'),
      (v_set_id, 14, E'विश्व महासागर दिवस हरेक वर्ष कुन तारिखमा कहिले मनाइन्छ?', E'मार्च २१', E'जुन ८', E'मार्च ३', E'डिसेम्बर ११', 'B', E'विश्व महासागर दिवस हरेक वर्ष **जुन ८** मा मनाइन्छ।\n- मार्च २१ मा अन्तर्राष्ट्रिय वन दिवस मनाइन्छ।\n- मार्च ३ मा विश्व वन्यजन्तु दिवस मनाइन्छ।\n- डिसेम्बर ११ मा अन्तर्राष्ट्रिय पर्वत दिवस मनाइन्छ।', 'nepali'),
      (v_set_id, 15, E'नेपाल संयुक्त राष्ट्र संघको सदस्य हुँदा तत्कालीन UNO महासचिव को थिए?', E'ट्रिग्वे ली', E'ड्याग ह्यामरसोल्ड', E'कोफी अन्नान', E'वान कि मुन', 'B', E'नेपालले संयुक्त राष्ट्र संघको सदस्यता प्राप्त गर्दा (सन् १९५५ डिसेम्बर १४) तत्कालीन महासचिव **ड्याग ह्यामरसोल्ड** थिए।\n- ट्रिग्वे ली नेपालले संयुक्त राष्ट्र संघको सदस्यताका लागि आवेदन दिँदा (सन् १९४९ फेब्रुअरी १३) का महासचिव थिए।\n- कोफी अन्नान संयुक्त राष्ट्र संघका सातौँ महासचिव (१९९७-२००६) थिए।\n- वान कि मुन संयुक्त राष्ट्र संघका आठौँ महासचिव (२००७-२०१६) थिए।', 'nepali'),
      (v_set_id, 16, E'आर्थिक सर्वेक्षण २०७१/८२ अनुसार कुल गार्हस्थ उत्पादनमा उद्योग क्षेत्रको योगदान कति रहेको छ?', E'१२.८७ प्रतिशत', E'१२.७२ प्रतिशत', E'१२.८३ प्रतिशत', E'१२.५५ प्रतिशत', 'C', E'आर्थिक सर्वेक्षण २०७१/८२ अनुसार कुल गार्हस्थ उत्पादनमा उद्योग क्षेत्रको योगदान **१२.८३ प्रतिशत** रहने अनुमान गरिएको थियो।\nनोट: सोही सर्वेक्षण अनुसार कृषि क्षेत्रको योगदान २५.९६ प्रतिशत र सेवा क्षेत्रको योगदान ६२.०१ प्रतिशत रहने अनुमान थियो।', 'nepali'),
      (v_set_id, 17, E'नेपालको अन्तरिम योजनाका रुपमा कार्यान्वयन भएको नेपालको योजना कुन हो?', E'९ औं', E'१२ औं', E'१० औं', E'११ औं', 'D', E'जनआन्दोलन २०६२/६३ पछि कार्यान्वयनमा आएको **११ औं योजना** लाई नेपालको अन्तरिम योजनाको रूपमा चिनिन्छ। यो त्रिवर्षीय अन्तरिम योजना (२०६४ - २०६७) ले समृद्ध, आधुनिक र न्यायपूर्ण नेपाल निर्माण गर्ने लक्ष्य राखेको थियो।', 'nepali'),
      (v_set_id, 18, E'राज्यका ४ वटा निर्देशक सिद्धान्त अनुसार देहाएको कुन पर्दैन?', E'राजनीतिक उद्देश्य', E'आर्थिक उद्देश्य', E'वातावरण उद्देश्य', E'अन्तर्राष्ट्रिय सम्बन्ध', 'C', E'राज्यका ४ वटा निर्देशक सिद्धान्तहरूमा **वातावरण उद्देश्य** पर्दैन।\n- नेपालको संविधानको धारा ५० अनुसार राज्यका ४ निर्देशक सिद्धान्तहरूमा राजनीतिक उद्देश्य, आर्थिक उद्देश्य र अन्तर्राष्ट्रिय सम्बन्ध समावेश छन्।\nनोट: चौथो सिद्धान्त सामाजिक र सांस्कृतिक उद्देश्य हो।', 'nepali'),
      (v_set_id, 19, E'पहिलो मानव निर्मित उपग्रह कुन हो?', E'स्पुतनिक १', E'स्पुतनिक २', E'लुना १', E'लुना २', 'A', E'**स्पुतनिक १** पहिलो मानव निर्मित उपग्रह हो, जसलाई सोभियत संघले सन् १९५७ अक्टोबर ४ मा अन्तरिक्षमा पठाएको थियो।\n- स्पुतनिक २ अन्तरिक्षमा पठाइएको दोस्रो यान हो, जसमा सन् १९५७ नोभेम्बर ३ मा ''लाइका'' नामको कुकुरलाई पठाइएको थियो।\n- लुना १ र लुना २ सोभियत संघले चन्द्रमाको अध्ययनका लागि पठाएका प्रारम्भिक यानहरू थिए।', 'nepali'),
      (v_set_id, 20, E'''Buffar Zone of Europe'' भनेर कुन मुलुकलाई चिनिन्छ?', E'बेलायत', E'टर्की', E'स्वीट्जरल्याण्ड', E'बेल्जियम', 'D', E'**बेल्जियमलाई ''Buffar Zone of Europe'' र ''युरोपको कारखाना'' भनेर चिनिन्छ।**\n- बेलायतलाई ''समुद्रको रानी'' उपनामले चिनिन्छ।\n- टर्कीलाई ''युरोपको वीरामी'' भनिन्छ।\n- स्वीट्जरल्याण्डलाई ''युरोपको खेलमैदान'' भनिन्छ।', 'nepali'),
      (v_set_id, 21, E'जलपक्षी गणना २०८२ को सुरुवात कुन जिल्लाबाट भएको छ ?', E'कैलाली', E'कञ्चनपुर', E'बाँके', E'बर्दिया', 'B', E'जलपक्षी गणना २०८२ को सुरुवात **कञ्चनपुर जिल्लाबाट** भएको छ।\nनोट: यो गणना वि.सं. २०८२ पौष १९ देखि माघ ४ सम्म सञ्चालन भएको थियो, जसको मुख्य उद्देश्य सिमसार क्षेत्रमा आश्रित रैथाने तथा आगन्तुक जल पंक्षीहरुको अवस्था र संख्या अभिलेख गर्नु हो।', 'nepali'),
      (v_set_id, 22, E'नेपालको सबै भन्सार कार्यालयमा अनलाइन मुल्यांकन डाटाबेस प्रणाली लागु कहिले देखि भएको छ ?', E'२०८२ पौष १७', E'२०८२ पौष १८', E'२०८२ पौष १९', E'२०८२ पौष २०', 'B', E'नेपालका सबै १८ वटै भन्सार कार्यालयमा अनलाइन मुल्यांकन डाटाबेस प्रणाली **वि.सं. २०८२ पौष १८** देखि लागु भएको हो।\nनोट: अन्तर्राष्ट्रिय व्यापारको लागत घटाउने उद्देश्यले यो प्रणाली लागू गरिएको हो। यसअघि विरगंज भन्सारमा २०८२ कार्तिक १६ देखि पहिलो पटक यो प्रणाली सञ्चालनमा आएको थियो।', 'nepali'),
      (v_set_id, 23, E'देहाएको मध्ये कुन हिमाली जिल्लाले चीनलाई छोएको छैन ?', E'कालिकोट', E'म्याग्दी', E'जुम्ला', E'धादिङ', 'D', E'प्रश्नले चीनलाई नछुने हिमाली जिल्ला सोधेको छ, तर विकल्पहरूमध्ये धादिङले चीनलाई छुन्छ, जबकि अन्यले छुँदैनन्, त्यसैले यो नै सही उत्तर हो। **धादिङ** हिमाली जिल्ला हो जसले चीनको सिमानालाई छुन्छ।\n- कालिकोट, म्याग्दी, र जुम्ला हिमाली जिल्ला भए तापनि यिनीहरूले चीनको सिमानालाई छुँदैनन्।\nनोट: नेपालका जम्मा ६ वटा हिमाली जिल्लाहरूले चीनलाई छुँदैनन्: जुम्ला, म्याग्दी, रुकुम पूर्व, कालिकोट, बाजुरा र रामेछाप।', 'nepali'),
      (v_set_id, 24, E'पानीको वाफबाट चल्ने मेसिन (स्टिम इन्जिन) को आविष्कार कसले गरेका हुन् ?', E'जेम्स वाट', E'Robert Fulton', E'रिचर्ड आर्कराइट', E'चर्ज राइटन', 'A', E'**जेम्स वाटले** सन् १७६९ मा पानीको वाफबाट चल्ने मेसिन (स्टिम इन्जिन) को आविष्कार गरेका हुन्।\n- Robert Fulton ले वाष्प इन्जिनयुक्त डुंगाको आविष्कार गरेका थिए।\n- रिचर्ड आर्कराइटले फलामबाट बनेको धागो कात्ने वाटरफ्रेमको आविष्कार गरेका थिए र उनलाई ''आधुनिक फ्याक्ट्री पद्धतिका पिता'' पनि भनिन्छ।', 'nepali'),
      (v_set_id, 25, E'घर, जमिन बेचबिखन गर्न र बन्धक राख्न पनि पाइने व्यवस्था ल्याउने राजा को हुन् ?', E'जयस्थिती मल्ल', E'योगनरेन्द्र मल्ल', E'गुणकामदेव', E'जयप्रकाश मल्ल', 'A', E'**जयस्थिती मल्लले** घर, जमिन बेचबिखन गर्न र बन्धक राख्न पाइने कानुनी व्यवस्थाको सुरुवात गरेका थिए।\nनोट: उनले समाजलाई ४ जात र १८ वर्णमा विभाजन गर्ने, व्यावसायिक शिक्षाको सुरुवात गर्ने, र विवाहपछि महिलाले पुरुषको थर राख्ने जस्ता सामाजिक सुधारहरू पनि गरेका थिए।', 'nepali'),
      (v_set_id, 26, E'हिन्दु धर्म परम्परा अनुसार भगवान विष्णुको धनुलाई के भनिन्छ?', E'गाण्डिव', E'सारंग', E'पिनाक', E'विजय', 'B', E'**हिन्दु धर्म परम्परा अनुसार भगवान विष्णुको धनुलाई सारंग भनिन्छ।**\n- गाण्डिव अर्जुनको धनु हो।\n- पिनाक भगवान शिवको त्रिशूल हो।\n- विजय कर्णको धनुको नाम हो।', 'nepali'),
      (v_set_id, 27, E'लेप्चा जातिको मुख्य बसोबास क्षेत्र जिल्ला कुन हो?', E'दोलखा', E'ताप्लेजुङ', E'धनकुटा', E'इलाम', 'D', E'लेप्चा जातिको मुख्य बसोबास क्षेत्र **इलाम जिल्ला** हो। इलामका नामसिङ, जोगमाई, गोर्खे, पशुपतिनगर जस्ता स्थानहरूमा कन्चनजंघा हिमालको फेदमा यिनीहरूको बसोबास रहेको पाइन्छ।\nनोट: लेप्चा जातिले कन्चनजंघा हिमाललाई देवता मान्ने र मृत शरीरलाई गाड्दा शिर सोही हिमालतर्फ पार्ने चलन छ।', 'nepali'),
      (v_set_id, 28, E'जैविक प्रविधि कसको अवधारणा हो?', E'बार्बरा वार्ड', E'कार्ल ऐरेली', E'इ डी विल्सन', E'ए जी टान्सली', 'B', E'जैविक प्रविधि (Biotechnology) को अवधारणा **कार्ल ऐरेली (Karl Ereky)** ले प्रस्तुत गरेका हुन्। उनले सर्वप्रथम सन् १९१९ मा ''जैविक प्रविधि'' शब्दको प्रयोग गरेका थिए, जसअन्तर्गत जीव एवं वनस्पतिका कोषहरू मानिसको उपयोगका लागि प्रयोग गरिन्छ।', 'nepali'),
      (v_set_id, 29, E'नेपालको जनगणना इतिहासमा पहिलो आधुनिक जनगणनाको रूपमा कुन सालको जनगणनालाई बुझिन्छ?', E'वि.सं. २००८', E'वि.सं. १९९८', E'वि.सं. २०१६', E'वि.सं. २०२८', 'A', E'नेपालको जनगणना इतिहासमा **वि.सं. २००८** सालको जनगणनालाई पहिलो आधुनिक र वैज्ञानिक जनगणनाको रूपमा बुझिन्छ। यो जनगणना दुई चरणमा (वि.सं. २००९ र २०११) सम्पन्न भएको थियो र यसपछिका जनगणनाहरू अन्तर्राष्ट्रिय रूपमा तुलनायोग्य मानिन्छन्।\nनोट: नेपालमा जनगणनामा कम्प्युटरको प्रयोग भने वि.सं. २०२८ बाट सुरु भएको हो।', 'nepali'),
      (v_set_id, 30, E'सार्कको पर्यवेक्षक मुलुक कति वटा रहेको छन्?', E'१० वटा', E'९ वटा', E'८ वटा', E'७ वटा', 'B', E'सार्कका पर्यवेक्षकहरूको कुल संख्या **९** रहेको छ।\nनोट: सार्कका पर्यवेक्षकहरूमा ८ राष्ट्र (अस्ट्रेलिया, चीन, इरान, जापान, मौरिसस, म्यानमार, दक्षिण कोरिया, संयुक्त राज्य अमेरिका) र १ अन्तर्राष्ट्रिय सङ्गठन (युरोपेली सङ्घ) पर्दछन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/२२', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_24.csv  →  आसमान दैनिक GK — २०८२/११/२४  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/२४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/२४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/२४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको इतिहासमा कर्मचारीलाई पेन्सन ब्यबस्था को सुरुवात कहिले देखि भएको हो ?', E'१९९९', E'१९९३', E'१९९५', E'१९९७', 'A', E'नेपालको इतिहासमा कर्मचारीलाई पेन्सन व्यवस्थाको सुरुवात **वि.सं. १९९९** देखि भएको हो। जुद्ध शम्सेरको पालामा सैनिक द्रव्यकोषको स्थापना भएसँगै यसको सुरुवात भएको थियो।\nनोट: पछि वि.सं. २००१ मा निजामति कर्मचारीहरूका लागि निजामति प्रोभिडेन्ट फण्डको स्थापना भयो, जसलाई हाल कर्मचारी सञ्चय कोषले हेर्दछ।', 'nepali'),
      (v_set_id, 2, E'लोकसेवा आयोगको चौथो राष्ट्रिय सम्मेलन कहाँ सम्पन्न भएको थियो ?', E'धनगढी, कैलाली', E'बिरेन्द्रनगर, सुर्खेत', E'काभ्रे, धुलिखेल', E'रुपन्देही, लुम्बिनी', 'B', E'लोकसेवा आयोगको चौथो राष्ट्रिय सम्मेलन **बिरेन्द्रनगर, सुर्खेतमा** सम्पन्न भएको थियो।\n- धनगढी, कैलालीमा तेस्रो राष्ट्रिय सम्मेलन (वि.सं. २०७९/११/१९-२०) सम्पन्न भएको थियो।\n- काभ्रेको धुलिखेलमा पहिलो सम्मेलन (वि.सं. २०७७/११/२३-२४) सम्पन्न भएको थियो।\n- रुपन्देही, लुम्बिनीमा दोस्रो सम्मेलन (वि.सं. २०७८/११/२३-२४) सम्पन्न भएको थियो।\nनोट: चौथो राष्ट्रिय सम्मेलन वि.सं. २०८० फागुन २३ र २४ गते सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 3, E'नेपालमा पोखरापछि सबैभन्दा बढी पानी पर्ने ठाउँ कुन हो ?', E'गोदावरी', E'संखुवासभा', E'नेपालगन्ज', E'मुस्ताङ', 'B', E'नेपालमा पोखराको लुम्लेपछि सबैभन्दा बढी पानी पर्ने ठाउँ **संखुवासभा** हो।\n- गोदावरी काठमाडौं उपत्यकामा सबैभन्दा बढी पानी पर्ने ठाउँ हो।\n- नेपालगन्ज नेपालमा सबैभन्दा धेरै गर्मी हुने ठाउँ हो।\n- मुस्ताङ नेपालमा सबैभन्दा कम पानी पर्ने ठाउँ हो।', 'nepali'),
      (v_set_id, 4, E'नेपालको वाटर लु भनेर कुन पर्व/घटनालाई चिनिन्छ ?', E'कोत पर्व', E'भण्डारखाल पर्व', E'अलौ पर्व', E'मकै पर्व', 'C', E'नेपालको ''वाटर लु'' भनेर **अलौ पर्व**लाई चिनिन्छ।\n- कोत पर्वलाई राणा शासन जन्माएको पर्वको रूपमा चिनिन्छ।\n- भण्डारखाल पर्वलाई बस्नेत पर्व पनि भनिन्छ।\n- मकै पर्व वि.सं. १९७७ मा भएको एक राजनीतिक घटना थियो जसमा मकै खेतीबारे किताब लेख्नेहरूलाई दण्डित गरिएको थियो।', 'nepali'),
      (v_set_id, 5, E'सर्वप्रथम युवराजधिराज पदवी धारण गर्ने राजा को हुन्?', E'अंशुवर्मा', E'नरेन्द्रदेव', E'उदयदेव', E'वसन्तदेव', 'C', E'सर्वप्रथम युवराजधिराज पदवी धारण गर्ने राजा **उदयदेव** हुन्।\n- अंशुवर्माले महाराजधिराज पदवी धारण गरेका थिए र युवराजधिराज घोषणा गरेका थिए।\n- नरेन्द्रदेवले महाराजधिराज परम भट्टारक पदवी धारण गरेका थिए र उनलाई रातो मच्छिन्द्रनाथको रथजात्रा चलाउने राजाको रूपमा पनि चिनिन्छ।\n- वसन्तदेव लिच्छवि राजा मानदेवका पनाति थिए।', 'nepali'),
      (v_set_id, 6, E'राष्ट्रिय जनगणना, २०७८ अनुसार पहाडी क्षेत्रको जनघनत्व कति रहेको छ ?', E'१९२ जना प्रति वर्ग कि मि', E'१९६ जना प्रति वर्ग कि मि', E'१९४ जना प्रति वर्ग कि मि', E'१९८ जना प्रति वर्ग कि मि', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार पहाडी क्षेत्रको जनघनत्व **१९२ जना प्रति वर्ग किलोमिटर** रहेको छ। समग्रमा नेपालको जनघनत्व १९८, तराई क्षेत्रको ४६० र हिमाली क्षेत्रको ३४ जना प्रति वर्ग किलोमिटर रहेको छ।', 'nepali'),
      (v_set_id, 7, E'देहाएका मध्ये कुन जलविद्युत आयोजना चीन सरकार को सहयोगमा निर्माण भएका हो ?', E'फर्पिङ जलविद्युत आयोजना', E'सुनकोशी जलविद्युत आयोजना', E'त्रिशुली जलविद्युत आयोजना', E'कुलेखानी जलविद्युत आयोजना', 'B', E'**सुनकोशी जलविद्युत आयोजना** चीन सरकारको सहयोगमा निर्माण भएको हो।\n- फर्पिङ जलविद्युत आयोजना बेलायत सरकारको सहयोगमा बनेको नेपालको पहिलो जलविद्युत आयोजना हो।\n- त्रिशुली जलविद्युत आयोजना भारत सरकारको सहयोगमा निर्माण भएको थियो।\n- कुलेखानी जलविद्युत आयोजना जापान सरकारको सहयोगमा निर्माण भएको हो।', 'nepali'),
      (v_set_id, 8, E'लैङ्गिक उत्तरदायी बजेटको सुरुवात गर्ने मुलुक कुन हो?', E'अष्ट्रेलिया', E'फ्रान्स', E'बेलायत', E'अमेरिका', 'A', E'लैङ्गिक उत्तरदायी बजेटको सुरुवात गर्ने मुलुक **अष्ट्रेलिया** हो।\n- फ्रान्स वर्षमा २ पटक बजेट प्रस्तुत गर्ने मुलुक हो।\n- बेलायतले सन् १७३३ मा विश्वमा सर्वप्रथम बजेटको सुरुवात गरेको थियो।\n- अमेरिकाले कार्यक्रम बजेटको सुरुवात गरेको थियो।', 'nepali'),
      (v_set_id, 9, E'आन्द्र महासागरको औषत गहिराई कति रहेको छ?', E'3900 मि.', E'2400 मि.', E'3700 मि.', E'1330 मि.', 'C', E'आन्द्र महासागरको औसत गहिराई **३७०० मिटर** रहेको छ।\n- ३९०० मि. हिन्द महासागरको औसत गहिराई हो।\n- २४०० मि. कुमेरु महासागरको औसत गहिराई हो।\n- १३३० मि. सुमेरु महासागरको औसत गहिराई हो।\nनोट: प्रशान्त महासागर सबैभन्दा गहिरो महासागर हो, जसको औसत गहिराई ४३०० मिटर छ।', 'nepali'),
      (v_set_id, 10, E'सोह्रौं योजनाको अन्त्य सम्म साक्षरता दर (५ वर्ष माथि) कति पुर्याउने लक्ष्य रहेको छ ?', E'८५ प्रतिशत', E'९० प्रतिशत', E'७५ प्रतिशत', E'८० प्रतिशत', 'A', E'सोह्रौं योजनाको अन्त्यसम्म साक्षरता दर (५ वर्ष माथि) **८५ प्रतिशत** पुर्याउने लक्ष्य रहेको छ।\nनोट: सोही योजनाले अपेक्षित आयु ७३.० वर्ष, मानव सम्पत्ति सूचकाङ्क ७६.०, र आर्थिक तथा वातावरणीय जोखिम सूचकाङ्क २४.० पुर्याउने लक्ष्य लिएको छ।', 'nepali'),
      (v_set_id, 11, E'हरियो साइकल कुन साहित्यकारको कृति हो ?', E'गोविन्द वर्तमान', E'विवेक कुमार शाह', E'भरत जंगम', E'विष्णु भण्डारी', 'A', E'**''हरियो साइकल'' गोविन्द वर्तमानको कृति हो।**\n- विवेक कुमार शाहको कृति ''मैले देखेको दरबार'' हो।\n- भरत जंगमको कृति ''रातो घाम'' हो।\n- विष्णु भण्डारीको कृति ''पँहेलो घाम'' हो।', 'nepali'),
      (v_set_id, 12, E'नेपालको प्रसिद्ध साहित्य पुरस्कार मदन पुरस्कार कुन भाषाको वर्षको उत्कृष्ट कृतिलाई प्रदान गरिन्छ ?', E'नेपाली र नेवारी मात्र', E'नेपाली र विदेशी दुवै', E'नेपाली मात्र', E'सबै मातृभाषा', 'C', E'मदन पुरस्कार **नेपाली भाषामा** लेखिएको वर्षको उत्कृष्ट कृतिलाई मात्र प्रदान गरिन्छ। यो पुरस्कार एक वर्षभित्र नेपाली भाषामा प्रकाशित उत्कृष्ट कृतिहरू मध्ये एकलाई दिइन्छ।\nनोट: मदन पुरस्कारको घोषणा २०१२ साल असोज १० गते भएको थियो र यसको वितरण २०१४ सालदेखि सुरु भएको हो।', 'nepali'),
      (v_set_id, 13, E'नेपालको भुगोलमा देवीघाट कुन जिल्लामा अवस्थित धार्मिक स्थान हो ?', E'नुवाकोट', E'रुपन्देही', E'तनहुँ', E'उदयपुर', 'A', E'**देवीघाट नुवाकोट जिल्लामा अवस्थित धार्मिक स्थान हो।**\n- रुपन्देही जिल्लामा सैनामैना पर्दछ।\n- तनहुँ जिल्लामा देवघाट अवस्थित छ।\n- उदयपुर जिल्लामा मैनामैनी पर्दछ।\nनोट: देवघाट र देवीघाट फरक-फरक स्थान हुन्، देवघाट तनहुँमा र देवीघाट नुवाकोटमा पर्दछ।', 'nepali'),
      (v_set_id, 14, E'पर्यटनको राजधानी घोषणा भएको शहर कुन हो ?', E'पोखरा', E'बिरेन्द्रनगर', E'बुटवल', E'ललितपुर', 'A', E'**पोखरा** शहरलाई नेपालको पर्यटनको राजधानी घोषणा गरिएको छ। प्रधानमन्त्री पुष्पकमल दाहालले २०८० चैत ४ गते पोखरामा आयोजित एक विशेष समारोहमा यो घोषणा गरेका हुन्।\nनोट: गण्डकी प्रदेश सरकारको मन्त्रिपरिषद्ले २०८० फागुन २३ गते पोखरालाई पर्यटकीय राजधानी घोषणा गर्ने निर्णय गरेको थियो।', 'nepali'),
      (v_set_id, 15, E'नेपालको संविधानको धारा २७५ मा के सँग सम्बन्धि व्यवस्था गरिएको छ ?', E'जनमत संग्रह', E'आम माफि', E'उपाधी तथा विभूषण', E'राजधानी', 'A', E'नेपालको संविधानको धारा २७५ मा **जनमत संग्रह** सम्बन्धी व्यवस्था गरिएको छ।\n- आम माफी सम्बन्धी व्यवस्था धारा २७६ मा गरिएको छ।\n- उपाधि, सम्मान र विभूषण सम्बन्धी व्यवस्था धारा २७७ मा गरिएको छ।\n- राजधानी सम्बन्धी व्यवस्था धारा २८८ मा गरिएको छ, जसमा नेपालको राजधानी काठमाडौंमा रहने उल्लेख छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/२४', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_27.csv  →  आसमान दैनिक GK — २०८२/११/२७  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/२७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/२७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/२७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आर्थिक सर्वेक्षण, २०७९/८२ अनुसार कुल बिमित जनसंख्यामध्ये कति ले बीमा सेवा लिएका छन्?', E'४६.२ प्रतिशत', E'४७.२ प्रतिशत', E'४८.२ प्रतिशत', E'४९.२ प्रतिशत', 'D', E'आर्थिक सर्वेक्षण, २०७९/८२ अनुसार कुल बिमित जनसंख्यामध्ये **४९.२ प्रतिशतले** बीमा सेवा लिएका छन्।\nनोट: बीमा सेवा लिनेहरूमध्ये ४८% स्वास्थ्य सेवा प्रदायक बिमामा आबद्ध छन्, जसमा ८३% सरकारी, १०% निजी र ७% सामुदायिक प्रदायक रहेका छन्।', 'nepali'),
      (v_set_id, 2, E'नेपालको पहिलो नहर चन्द्र नहर कुन जिल्लामा पर्दछ?', E'सप्तरी', E'सर्लाही', E'रौतहट', E'बारा', 'A', E'**नेपालको पहिलो नहर, चन्द्र नहर, सप्तरी जिल्लामा पर्दछ।**\n- सर्लाही जिल्लामा जुद्ध नहर र वागमती सिंचाइ आयोजना पर्दछन्।\n- रौतहट जिल्लामा वागमती सिंचाइ आयोजना पर्दछ।\n- बारा जिल्लामा गण्डक सिंचाइ आयोजना रहेको छ।\nनोट: चन्द्र नहरको निर्माण वि.सं. १९८० मा प्रधानमन्त्री चन्द्र शमशेरको पालामा भएको थियो।', 'nepali'),
      (v_set_id, 3, E'सर्वोच्च अदालतमा नेपालको प्रधान न्यायाधीशका अतिरिक्त बढीमा कति जना न्यायाधीश रहने व्यवस्था रहेको छ?', E'१५ जना', E'२० जना', E'१० दिन', E'२५ दिन', 'B', E'नेपालको संविधानको धारा १२९ अनुसार सर्वोच्च अदालतमा प्रधान न्यायाधीशका अतिरिक्त बढीमा **२० जना** न्यायाधीश रहने व्यवस्था छ।\nनोट: संवैधानिक परिषदको सिफारिसमा प्रधान न्यायाधीश र न्याय परिषदको सिफारिसमा अन्य न्यायाधीशहरूको नियुक्ति राष्ट्रपतिबाट हुने गर्दछ।', 'nepali'),
      (v_set_id, 4, E'आकाशमा कुनै निश्चित आकार बनाएर रहेका ताराहरूको समुहलाई के भनिन्छ?', E'तारापुञ्ज', E'तारा मण्डल', E'रात्री तारा', E'कुनै पनि होइन', 'B', E'आकाशमा कुनै निश्चित आकार बनाएर रहेका ताराहरूको समूहलाई **तारा मण्डल** भनिन्छ।\n- अरबौं ताराहरूको अति विशाल समूहलाई तारापुञ्ज भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'विश्वको सर्वोच्च शिखर सगरमाथाको उचाई कति फिट रहेको छ?', E'२९०३३.६९ फिट', E'२९०३१.६९ फिट', E'२९०२९.६९ फिट', E'२९०२७.६९ फिट', 'B', E'विश्वको सर्वोच्च शिखर सगरमाथाको उचाई **२९०३१.६९ फिट** (८८४८.८६ मिटर) रहेको छ।\nनोट: सगरमाथा नेपाल र चीनको सीमामा अवस्थित छ।', 'nepali'),
      (v_set_id, 6, E'अमलेखगन्जको पुरानो नाम के हो?', E'पदमकण्ठगिरी', E'भैसालोटन', E'भिच्छाखोरी', E'फुलोच्चगिरी', 'C', E'अमलेखगन्जको पुरानो नाम **भिच्छाखोरी** हो।\n- पदमकण्ठगिरी स्वयम्भूको पुरानो नाम हो।\n- भैसालोटन बाल्मिकीनगरको पुरानो नाम हो।\n- फुलोच्चगिरी फुल्चोकीको पुरानो नाम हो।', 'nepali'),
      (v_set_id, 7, E'विचित्र गुफा कुन जिल्लामा अवस्थित प्रसिद्ध गुफा हो?', E'तनहुँ', E'अर्घाखाँची', E'कास्की', E'गुल्मी', 'D', E'विचित्र गुफा **गुल्मी** जिल्लामा अवस्थित छ।\n- तनहुँ जिल्लामा सिद्ध गुफा अवस्थित छ।\n- अर्घाखाँची जिल्लामा साततले गुफा अवस्थित छ।\n- कास्की जिल्लामा महेन्द्र गुफा अवस्थित छ।', 'nepali'),
      (v_set_id, 8, E'राष्ट्रिय योग दिवस नेपालमा हरेक वर्ष कुन दिन मनाइन्छ ?', E'माघ १', E'माघ २', E'माघ ३', E'माघ ४', 'A', E'नेपालमा राष्ट्रिय योग दिवस हरेक वर्ष **माघ १** गते मनाइन्छ। नेपालमा वि.सं २०७२ देखि यो दिवस मनाउन थालिएको हो।\nनोट: अन्तर्राष्ट्रिय योग दिवस भने हरेक वर्ष जुन २१ मा मनाइन्छ।', 'nepali'),
      (v_set_id, 9, E'२०८२ मा कति औं राष्ट्रिय कृषि जैविक विविधता दिवस मनाइएको छ?', E'पहिलो', E'दोस्रो', E'तेस्रो', E'चौथो', 'D', E'वि.सं. २०८२ मा **चौथो** राष्ट्रिय कृषि जैविक विविधता दिवस मनाइएको थियो। यो दिवस वि.सं. २०७९ देखि हरेक वर्ष माघ १ गते मनाउन सुरु गरिएको हो।\nनोट: २०८२ को नारा ''कृषि जैविक विविधता हाम्रो अमूल्य सम्पदा: संरक्षण, उपयोग र प्रवर्द्धन युवा सहभागिता'' रहेको थियो।', 'nepali'),
      (v_set_id, 10, E'राजनीतिलाई धर्मबाट अलग राख्न प्रेरित गर्ने बहुचर्चित पुस्तक कुन हो?', E'Canterbury', E'Utopia', E'The Prince', E'Divine Comedy', 'C', E'**''The Prince''** राजनीतिलाई धर्मबाट अलग राख्न प्रेरित गर्ने बहुचर्चित पुस्तक हो।\n- Canterbury (The Canterbury Tales) Geoffrey Chaucer द्वारा लिखित कथाहरूको संग्रह हो।\n- Utopia पुस्तकले एक आदर्श काल्पनिक टापु समाजको वर्णन गर्दछ।\n- Divine Comedy मा स्वर्ग र नरकको बारेमा विवेचना गरिएको छ।\nनोट: ''The Prince'' का लेखक इटालेली कूटनीतिज्ञ निकोलो म्याकियाभेली हुन्।', 'nepali'),
      (v_set_id, 11, E'अंशुवर्माले निर्माण गरेको प्रसिद्ध भवन कुन हो?', E'मानगृह', E'भद्राधिवास', E'कैलाशकुट', E'पशुपतिनाथ', 'C', E'अंशुवर्माले निर्माण गरेको प्रसिद्ध भवन **कैलाशकुट** हो।\n- मानगृहको निर्माण मानदेवले गरेका थिए।\n- भद्राधिवासको निर्माण नरेन्द्रदेवले गरेका थिए।\n- पशुपतिनाथको निर्माण प्रचण्डदेवले गरेका थिए।', 'nepali'),
      (v_set_id, 12, E'नेपालमा हलिया प्रथाको अन्त्य हुँदा नेपालका तत्कालिन प्रधानमन्त्री को थिए?', E'पुष्पकमल दाहाल', E'गिरिजाप्रसाद कोइराला', E'शेर व देउवा', E'चन्द्र सम्सेर', 'A', E'नेपालमा हलिया प्रथाको अन्त्य वि.सं. २०६५ भदौ २१ मा हुँदा तत्कालिन प्रधानमन्त्री **पुष्पकमल दाहाल** थिए।\n- गिरिजाप्रसाद कोइरालाको प्रधानमन्त्रीत्वकालमा कमैया प्रथा अन्त्यको घोषणा भएको थियो।\n- चन्द्र शमशेरले आफ्नो कार्यकालमा दास प्रथा र सती प्रथाको अन्त्य गरेका थिए।', 'nepali'),
      (v_set_id, 13, E'फरक गुण भएका बुवाआमा बाट प्रजनन भइ पहिलो वंशमा देखा परेका गुणलाई के भनिन्छ?', E'प्रबल गुण', E'लुप्त गुण', E'परिवर्तन गुण', E'वंशाणुगत गुण', 'A', E'मेण्डेलको वंशाणुगत नियम अनुसार, फरक गुण भएका अभिभावकबाट प्रजनन हुँदा पहिलो वंशमा देखिने गुणलाई **प्रबल गुण (Dominant Trait)** भनिन्छ।\nनोट: पहिलो वंशमा लुकेर बसेको वा नदेखिएको गुणलाई लुप्त गुण (Recessive Trait) भनिन्छ।', 'nepali'),
      (v_set_id, 14, E'विश्वको सबैभन्दा कम जैविक विविधता भएको मुलुक कुन हो?', E'मोनाको', E'टुभालु', E'नाउरु', E'सान मारिनो', 'A', E'विश्वको सबैभन्दा कम जैविक विविधता भएको मुलुक **मोनाको** हो।\nनोट: सबैभन्दा कम जैविक विविधता भएका अन्य देशहरूमा सेन्ट मार्टिन, टुभालु, नाउरु र सान मारिनो पर्दछन्।', 'nepali'),
      (v_set_id, 15, E'सार्कमा जलपरिवेष्ठित मुलुक कति रहेका छन्?', E'२ वटा', E'३ वटा', E'४ वटा', E'५ वटा', 'A', E'सार्कमा **२ वटा** जलपरिवेष्ठित (Island) मुलुकहरू रहेका छन्, जुन माल्दिभ्स र श्रीलंका हुन्।\nनोट: सार्कमा ३ वटा भूपरिवेष्ठित (Landlocked) मुलुकहरू छन्: नेपाल, अफगानिस्तान र भुटान।', 'nepali'),
      (v_set_id, 16, E'आर्थिक सर्वेक्षण, २०७१/८२ अनुसार नेपालमा सबैभन्दा धेरै विद्यार्थी भएको सामुदायिक विद्यालय कुन हो?', E'कालिका मानव ज्ञान मा.वि', E'जनता नमुना मा.वि.', E'शान्ति नमुना मा.वि.', E'त्रिभुवन नमुना मा.वि.', 'A', E'आर्थिक सर्वेक्षण, २०७१/८२ अनुसार नेपालमा सबैभन्दा धेरै विद्यार्थी भएको सामुदायिक विद्यालय रुपन्देहीको **कालिका मानव ज्ञान मा.वि.** हो।\n- जनता नमुना मा.वि., धनुषा, ६५८७ विद्यार्थीसहित दोस्रो स्थानमा थियो।\n- शान्ति नमुना मा.वि., रुपन्देही, ५६४१ विद्यार्थीसहित तेस्रो स्थानमा थियो।\n- त्रिभुवन नमुना मा.वि. काठमाडौंमा अवस्थित एक प्रमुख सामुदायिक विद्यालय भए तापनि विद्यार्थी संख्याको आधारमा यो शीर्ष स्थानमा थिएन।\nनोट: उक्त सर्वेक्षण अनुसार कालिका मानव ज्ञान मा.वि. मा ७४६७ जना विद्यार्थी अध्ययनरत थिए।', 'nepali'),
      (v_set_id, 17, E'नेपालमा औद्योगिक विकास निगमको स्थापना कहिले भयो?', E'वि.सं. २०१६', E'वि.सं. २००३', E'वि.सं. २०४९', E'वि.सं. २०६७', 'A', E'नेपालमा औद्योगिक विकास निगमको स्थापना **वि.सं. २०१६** मा भएको थियो।\n- वि.सं. २००३ मा नेपालमा रघुपति जुटमिलको स्थापना भएको थियो।\n- वि.सं. २०४९ कार्तिक २७ देखि औद्योगिक विकास ऐन लागू भएको थियो।\n- वि.सं. २०६७ जेठ २ मा औद्योगिक नीति सार्वजनिक गरिएको थियो।', 'nepali'),
      (v_set_id, 18, E'नेपालको संविधान अनुसार अध्यादेश सिफारिसको अधिकार के मा हुने गर्दछ?', E'सभामुख', E'संवैधानिक परिषद्', E'राष्ट्रपति', E'मन्त्रीपरिषद', 'D', E'नेपालको संविधानको धारा ११४ अनुसार, संघीय संसदको अधिवेशन नचलेको अवस्थामा तत्काल केही गर्न आवश्यक परेमा **मन्त्रिपरिषदको सिफारिसमा** राष्ट्रपतिले अध्यादेश जारी गर्न सक्ने व्यवस्था छ। राष्ट्रपतिले अध्यादेश जारी गर्ने भएता पनि सिफारिस गर्ने अधिकार मन्त्रिपरिषदमा निहित हुन्छ।\nनोट: यसरी जारी भएको अध्यादेश संसदको बैठक बसेको साठी दिनभित्र दुवै सदनबाट स्वीकार नभएमा स्वतः निष्क्रिय हुन्छ।', 'nepali'),
      (v_set_id, 19, E'तारामण्डल अन्तर्गत पर्ने राशीको संख्या कति रहेको छ?', E'12 ओटा', E'11 ओटा', E'10 ओटा', E'14 ओटा', 'A', E'तारामण्डल अन्तर्गत पर्ने राशीको संख्या **१२ ओटा** रहेको छ। सूर्य सरेको देखिने रविमार्गका १२ ओटा तारा मण्डलहरूलाई राशी भनिन्छ, जसमा मेष, वृष, मिथुन, कर्कट, सिंह, कन्या, तुला, वृश्चिक, धनु, मकर, कुम्भ र मीन पर्दछन्।', 'nepali'),
      (v_set_id, 20, E'विश्वको सबैभन्दा होचो स्थान मृतसागर कुन मुलुकको सिमानामा रहेको छ?', E'Jordan & Israel', E'Jordan & Egypt', E'Israel & Egypt', E'Palestine & Israel', 'A', E'**विश्वको सबैभन्दा होचो स्थान मृतसागर (Dead Sea) जोर्डन र इजरायलको सिमानामा रहेको छ।**\n- जोर्डन र इजिप्टको सिमानामा अकाबाको खाडी पर्दछ।\n- इजरायल र इजिप्टको सिमानामा गाजा पट्टी र सिनाई प्रायद्वीप पर्दछन्।\n- प्यालेस्टाइन र इजरायल बीचको सिमाना एक जटिल र विवादित क्षेत्र हो।\nनोट: मृतसागर समुद्र सतहबाट लगभग ४१८ मिटर तल रहेको छ र यो पृथ्वीको सबैभन्दा होचो भू-भाग हो।', 'nepali'),
      (v_set_id, 21, E'सिक्‍टा सिंचाइ आयोजना कुन जिल्लामा सञ्चालित राष्ट्रिय गौरवको आयोजना हो?', E'रुपन्देही', E'बर्दिया', E'बाँके', E'झापा', 'C', E'**सिक्‍टा सिंचाइ आयोजना बाँके जिल्लामा सञ्चालित राष्ट्रिय गौरवको आयोजना हो।**\n- रुपन्देही जिल्लामा तिनाउ सिंचाइ आयोजना सञ्चालित छ।\n- बर्दिया जिल्लामा राजापुर सिंचाइ आयोजना रहेको छ।\n- झापा जिल्लामा कन्काई सिंचाइ आयोजना सञ्चालित छ।', 'nepali'),
      (v_set_id, 22, E'सोलुखुम्बु जिल्लामा पर्ने ८००० मि भन्दा पछिको अग्लो हिमाल नुप्से हिमालको उचाइ कति रहेको छ?', E'७,२९६ मिटर', E'७,५९९ मिटर', E'७,९६३ मिटर', E'७,८५५ मिटर', 'D', E'सोलुखुम्बु जिल्लामा पर्ने नुप्से हिमालको उचाइ **७,८५५ मिटर** रहेको छ।\n- ७,५९९ मिटर शान्ति पिकको उचाइ हो भने ७,१६३ मिटर गणेश हिमालको उचाइ हो।', 'nepali'),
      (v_set_id, 23, E'पहिलो राष्ट्रिय चिया दिवस, २०८२ कहिले मनाइएको छ ?', E'पुस १३', E'पुस १५', E'पुस १७', E'पुस १९', 'B', E'पहिलो राष्ट्रिय चिया दिवस **२०८२ पुस १५** गते मनाइएको छ। २०८२ पुस ११ गते बसेको मन्त्रिपरिषद् बैठकले हरेक वर्ष पुस १५ गतेलाई राष्ट्रिय चिया दिवसको रूपमा मनाउने निर्णय गरेको थियो।', 'nepali'),
      (v_set_id, 24, E'नेपाल प्रिमियर लिग (NPL) को ट्रफी बनाउन कुन ठाउँ बाट ढुंगा लिइ प्रयोगमा ल्याइएको थियो? (कोशी सातो, २०८२)', E'रसुवा', E'लिपुलेख', E'कालापत्थर', E'कालीगण्डकी', 'C', E'**नेपाल प्रिमियर लिग (NPL) को ट्रफी बनाउन सगरमाथा क्षेत्रको कालापत्थरबाट ल्याइएको ढुंगा प्रयोग गरिएको थियो।**\n- रसुवा जिल्ला गोसाइँकुण्ड र लाङटाङ राष्ट्रिय निकुञ्जका लागि प्रसिद्ध छ।\n- लिपुलेख नेपाल, भारत र चीनको त्रिदेशीय विन्दुमा अवस्थित एक हिमाली पास हो।\n- कालीगण्डकी नदी शालिग्राम शिलाका लागि प्रसिद्ध छ।\nनोट: एनपिएलको ट्रफी २०८१ मंसिर १० गते धरहराबाट सार्वजनिक गरिएको थियो।', 'nepali'),
      (v_set_id, 25, E'चित्र मस्तिष्कबाट बनाइन्छ हातबाट हैन यो प्रसिद्ध भनाइ कसको हो?', E'माइकल एन्जेलो', E'लियोनार्दो दा भिन्ची', E'मेकियावेली', E'दाँते', 'A', E'''चित्र मस्तिष्कबाट बनाइन्छ, हातबाट हैन'' भन्ने प्रसिद्ध भनाइ **माइकल एन्जेलोको** हो।\nनोट: उनी पुनर्जागरण कालका एक प्रमुख कलाकार थिए, जसले २० वर्ष लगाएर ''द लास्ट जजमेन्ट'' नामक बहुचर्चित चित्र तयार पारेका थिए।', 'nepali'),
      (v_set_id, 26, E'आमालाई सति जानबाट रोक्ने लिच्छवि राजा देहाएका मध्ये को हुन?', E'जयकामदेव', E'अंशुवर्मा', E'नरेन्द्रदेव', E'मानदेव', 'D', E'आफ्नी आमा राज्यवतीलाई सति जानबाट रोक्ने लिच्छवि राजा **मानदेव** थिए।\nनोट: नेपालमा सती प्रथाको पूर्ण अन्त्य भने चन्द्रशमशेरले वि.सं. १९७७ असार २५ मा गरेका थिए।', 'nepali'),
      (v_set_id, 27, E'नेपालको भूगोलमा रहेको सैरैली प्रथा कहाँ प्रचलित रहेको छ?', E'दाङ र बाँके', E'बर्दिया र रोटि', E'दैलेख र सुर्खेत', E'सुर्खेत र सल्यान', 'D', E'सैरैली प्रथा **सुर्खेत र सल्यान** जिल्लामा प्रचलित छ।\n- यो प्रथा अन्तर्गत युवकहरूले युवतीहरूलाई निमन्त्रणा गरी बोलाएको ठाउँमा घुम्न वा सयर गर्न जाने चलनलाई बुझाउँछ।', 'nepali'),
      (v_set_id, 28, E'मेण्डेलको प्रयोग अन्तर्गत प्रतिपाद ३ सिद्धान्त अन्तर्गत देहाएको कुन पर्दैन?', E'प्रबलताको नियम', E'ग्यामेटहरूको शुद्धताको नियम', E'स्वतन्त्र छनोटको नियम', E'प्राकृतिक छनोटको नियम', 'D', E'**प्राकृतिक छनोटको नियम** मेण्डेलको वंशाणुगतिका ३ सिद्धान्तहरूमा पर्दैन।\n- यो सिद्धान्त चार्ल्स डार्विनले प्रतिपादन गरेका हुन्, जबकि प्रबलताको नियम, ग्यामेटहरूको शुद्धताको नियम र स्वतन्त्र छनोटको नियम मेण्डेलका सिद्धान्तहरू हुन्।', 'nepali'),
      (v_set_id, 29, E'ब्राजिल पछि सबैभन्दा धेरै जैविक विविधता भएको विश्वको मुलुक कुन हो?', E'अमेरिका', E'इन्डोनेसिया', E'कोलम्बिया', E'चीन', 'B', E'विश्वमा ब्राजिलपछि सबैभन्दा धेरै जैविक विविधता भएको मुलुक **इन्डोनेसिया** हो।\n- जैविक विविधतामा शीर्ष देशहरूको क्रम यसप्रकार छ: ब्राजिल, इन्डोनेसिया, कोलम्बिया, चीन, मेक्सिको, अस्ट्रेलिया, पेरु, भारत, इक्वेडर, र संयुक्त राज्य अमेरिका।', 'nepali'),
      (v_set_id, 30, E'सार्कमा चीन पर्यवेक्षक हुने गरी आबद्ध गराउन प्रस्ताव गर्ने मुलुक कुन हो?', E'बंगलादेश', E'नेपाल', E'भारत', E'पाकिस्तान', 'B', E'सार्कमा चीनलाई पर्यवेक्षकको रूपमा आबद्ध गराउन प्रस्ताव गर्ने मुलुक **नेपाल** हो।\nनोट: अफगानिस्तानलाई सार्कको सदस्य राष्ट्र बनाउन प्रस्ताव गर्ने मुलुक भने भारत हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/२७', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_11_28.csv  →  आसमान दैनिक GK — २०८२/११/२८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/११/२८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/११/२८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/११/२८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'International AI Impact Summit २०२६ कहाँ आयोजना भएको थियो?', E'Tokyo', E'New Delhi', E'London', E'Paris', 'B', E'International AI Impact Summit २०२६ भारतको **नयाँ दिल्लीमा** आयोजना भएको थियो। यो समिट फेब्रुअरी १६ देखि २१, २०२६ सम्म चलेको थियो।\nनोट: यस सम्मेलनमा १०० भन्दा बढी देशका प्रतिनिधिहरूको सहभागिता रहेको थियो।', 'nepali'),
      (v_set_id, 2, E'हालसालै सन् २०२६ मा अपरेशन गजब लिल हक (Operation Ghazab Lil Haq) कुन देशले सुरु गरेको सैन्य अभियान हो?', E'India', E'Pakistan', E'Iran', E'Afghanistan', 'B', E'**पाकिस्तानले** सन् २०२६ फेब्रुअरी २७ मा ''अपरेशन गजब लिल हक'' नामक सैन्य अभियान सुरु गरेको थियो। यो अभियान मुख्यतः अफगानिस्तानमा रहेको अफगान तालिवान विरुद्ध लक्षित थियो।\nनोट: २६ फेब्रुअरी २०२६ मा डुरन्ड रेखामा भएको सीमापार गोलीबारीमा पाकिस्तानी सैनिक मारिएपछि यो अभियान सुरु भएको हो।', 'nepali'),
      (v_set_id, 3, E'इरानका सर्वोच्च नेता आयतोल्लाह अली खामेनी मृत्यु पुष्टि कहिले भएको छ ?', E'२०२६ मार्च १', E'२०२६ फेब्रुअरी २८', E'२०२६ मार्च ५', E'२०२६ मार्च ९', 'A', E'इरानका सर्वोच्च नेता आयतोल्लाह अली खामेनीको मृत्यु **२०२६ मार्च १** मा पुष्टि भएको थियो। उनको मृत्युको घोषणासँगै इरानमा ४० दिने राष्ट्रिय शोकको घोषणा गरिएको थियो।\nनोट: उनको मृत्यु सन् २०२६ फेब्रुअरी २८ मा अमेरिका र इजरायलको सैन्य कारवाहीमा भएको थियो।', 'nepali'),
      (v_set_id, 4, E'प्रतिनिधि सभा निर्वाचन, २०७९ मा प्रत्यक्षतर्फ सबैभन्दा बढी मत अन्तर बनाई विजयी हुने उम्मेदवार को हुन् ?', E'बालेन्द्र शाह', E'विश्वराज पोखरेल', E'डा. लेखजंग थापा', E'टेकबहादुर गुरुङ', 'C', E'प्रतिनिधि सभा निर्वाचन, २०७९ मा प्रत्यक्षतर्फ सबैभन्दा बढी मतान्तरले विजयी हुने उम्मेदवार **डा. लेखजंग थापा** हुन्।\n- बालेन्द्र शाह सबैभन्दा बढी मत (६८,३४८) का साथ विजयी भएका थिए।\n- विश्वराज पोखरेल सबैभन्दा कम मतान्तर (५) ले विजयी भएका थिए।\n- टेकबहादुर गुरुङ सबैभन्दा कम मत (२,४१५) का साथ विजयी भएका थिए।\nनोट: डा. थापाले रुपन्देही क्षेत्र नं. ३ बाट ५०,३७९ को मतान्तरले चुनाव जितेका थिए।', 'nepali'),
      (v_set_id, 5, E'बहुराष्ट्रिय हुने पहिलो नेपाल प्रिमियर लिग फ्रान्चाइज टिम कुन बन्न सफल भएको छ ?', E'लुम्बिनी लायन्स', E'सुदूरपश्चिम रोयल्स', E'विराटनगर किंग', E'जनकपुर बोल्ट्स', 'D', E'**जनकपुर बोल्ट्स** बहुराष्ट्रिय हुने पहिलो नेपाल प्रिमियर लिग (NPL) फ्रान्चाइज टिम बन्न सफल भएको छ।\n- यो टिमले EU T-20 बेल्जियम लिगमा ''JB Bruges'' (जेबी ब्रुग्स) को रुपमा सहभागिता जनाउने भएको छ।', 'nepali'),
      (v_set_id, 6, E'जेन जी आन्दोलनसंग सम्बन्धी विषयमा जाँचबुझ गर्न गठित न्यायिक आयोगले प्रतिवेदन सरकारलाई कहिले बुझाएको छ ?', E'२०८२ फागुन २३', E'२०८२ फागुन २४', E'२०८२ फागुन २५', E'२०८२ फागुन २३', 'C', E'जेन जी आन्दोलनबारे जाँचबुझ गर्न गठित न्यायिक आयोगले सरकारलाई **२०८२ फागुन २५** गते आफ्नो प्रतिवेदन बुझाएको थियो।\nनोट: उक्त आयोगको अध्यक्षता गौरीबहादुर कार्कीले गरेका थिए।', 'nepali'),
      (v_set_id, 7, E'विश्व संगीतको सर्वोच्च अवार्ड ग्रामी (सन् २०२६ मा) अन्तर्गत बेस्ट न्यु आर्टिस्ट अवार्ड कसलाई प्रदान गरियो ?', E'एडिसन रे', E'ओलिभिया डोन', E'एलेक्स वारेन', E'क्याट्से', 'B', E'सन् २०२६ को ६८औं ग्रामी अवार्डमा बेस्ट न्यु आर्टिस्टको अवार्ड बेलायती गायिका **ओलिभिया डिन** (डोन) ले जितेकी थिइन्।\nनोट: सोही समारोहमा ''एल्बम अफ द इयर'' ब्याड बन्नीले र ''सङ अफ द इयर'' बिली आइलिसले जितेका थिए।', 'nepali'),
      (v_set_id, 8, E'सरकारले जंगली बँदेललाई पुनः एक वर्षका लागि कृषि हानिकारक वन्यजन्तु घोषणा कहिले गरेको हो ?', E'२०८२ फागुन १०', E'२०८२ फागुन ११', E'२०८२ फागुन १२', E'२०८२ फागुन १३', 'B', E'नेपाल सरकारले जंगली बँदेललाई थप एक वर्षका लागि कृषि हानिकारक वन्यजन्तुको रूपमा घोषणा गर्ने निर्णय **२०८२ फागुन ११** गते गरेको हो।', 'nepali'),
      (v_set_id, 9, E'ICC T-20 विश्वकप प्रतियोगिता, २०२६ को उपाधी कुन मुलुकले प्राप्त गरेको छ ?', E'न्युजिल्याण्ड', E'भारत', E'इंग्ल्याण्ड', E'दक्षिण अफ्रिका', 'B', E'सन् २०२६ को ICC T-20 विश्वकप क्रिकेट प्रतियोगिताको उपाधि **भारतले** जितेको हो। फाइनलमा भारतले न्युजिल्याण्डलाई १६ रनले पराजित गर्दै उपाधि जितेको थियो।\n- न्युजिल्याण्ड प्रतियोगिताको उपविजेता राष्ट्र बन्यो।\n- इंग्ल्याण्ड र दक्षिण अफ्रिका सेमिफाइनलसम्म पुगेका थिए।\nनोट: यो भारतको लगातार दोस्रो र समग्रमा तेस्रो पटकको T-20 विश्वकप उपाधि थियो।', 'nepali'),
      (v_set_id, 10, E'शीतकालीन ओलम्पिक खेलकुद प्रतियोगिता, २०२६ मा प्रथम स्थान हाँसिल गर्न सफल मुलुक कुन हो ?', E'चीन', E'अमेरिका', E'जापान', E'नर्वे', 'D', E'**नर्वेले** सन् २०२६ को शीतकालीन ओलम्पिक खेलकुदमा प्रथम स्थान हासिल गरेको थियो। इटालीको मिलान-कोर्टिनामा सम्पन्न २४औं संस्करणको पदक तालिकामा शीर्ष तीन राष्ट्रहरू निम्न थिए:\n- १. नर्वे: १८ स्वर्ण, १२ रजत, ११ कांस्य (कुल ४१ पदक)\n- २. अमेरिका: १२ स्वर्ण, १२ रजत, ९ कांस्य (कुल ३३ पदक)\n- ३. नेदरल्यान्ड्स: १० स्वर्ण, ७ रजत, ३ कांस्य (कुल २० पदक)', 'nepali'),
      (v_set_id, 11, E'२०८२ मनाइएको राष्ट्रिय स्वास्थ्य सेवा दिवस कति औं हो ?', E'२५ औं', E'२६ औं', E'२७ औं', E'२८ औं', 'C', E'वि.सं. २०८२ मा **२७ औं** राष्ट्रिय स्वास्थ्य सेवा दिवस मनाइएको थियो।\nनोट: यो दिवस हरेक वर्ष फागुन १५ गते मनाइन्छ र २०८२ को नारा ''दक्ष जनशक्ति, दिगो सेवा: स्वास्थ्य सुरक्षा हाम्रो दृढ प्रतिबद्धता'' रहेको थियो।', 'nepali'),
      (v_set_id, 12, E'अन्तर्राष्ट्रिय महिला दिवसको प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'मार्च ६', E'मार्च ७', E'मार्च ८', E'मार्च ९', 'C', E'अन्तर्राष्ट्रिय महिला दिवस प्रत्येक वर्ष **मार्च ८** तारिखमा मनाइन्छ।\nनोट: सन् २०२६ को अन्तर्राष्ट्रिय नारा ''Rights, Justice, Action, For ALL Women and Girls'' थियो भने वि.सं. २०८२ को राष्ट्रिय नारा ''सबै महिला र बालिकाको लागि अधिकार, न्याय र कार्यसहितको अवसर'' रहेको थियो।', 'nepali'),
      (v_set_id, 13, E'२०८२ मा कति औं निर्वाचन दिवस मनाइएको हो ?', E'१० औं', E'११ औं', E'१२ औं', E'१३ औं', 'A', E'वि.सं. २०८२ मा **१० औं** निर्वाचन दिवस मनाइएको हो। नेपालमा पहिलो पटक वि.सं. २०१५ साल फागुन ७ गते आम निर्वाचन भएको थियो र सोही दिनको सम्झनामा वि.सं. २०७३ सालबाट निर्वाचन दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 14, E'ICC T-20 विश्वकप क्रिकेट प्रतियोगिता, २०२६ मा सर्वाधिक रन बनाउने खेलाडीको हुन् ?', E'टिम सेफर्ट', E'जसप्रित बुमराह', E'साहिबजादा फरहान', E'वरुण चक्रवर्ती', 'C', E'**सन् २०२६ को ICC T-20 विश्वकप क्रिकेटमा पाकिस्तानका साहिबजादा फरहान सर्वाधिक रन बनाउने खेलाडी हुन्।**\n- न्युजिल्याण्डका टिम सेफर्टले प्रतियोगितामा सर्वाधिक ४ अर्धशतक बनाएका थिए।\n- भारतका जसप्रित बुमराह र वरुण चक्रवर्तीले संयुक्त रूपमा सर्वाधिक १४ विकेट लिएका थिए।', 'nepali'),
      (v_set_id, 15, E'प्रतिनिधि सभा निर्वाचन, २०८२ मा प्रत्यक्षतर्फ निर्वाचित महिला सांसदको संख्या कति रहेको छ ?', E'१४ जना', E'१५ जना', E'१६ जना', E'१७ जना', 'A', E'प्रतिनिधि सभा निर्वाचन, २०८२ मा प्रत्यक्षतर्फ निर्वाचित महिला सांसदको संख्या **१४ जना** रहेको छ।\nनोट: उक्त निर्वाचनमा राष्ट्रिय स्वतन्त्र पार्टी (रास्वपा) बाट १३ जना र नेपाली कांग्रेसबाट १ जना महिला सांसद प्रत्यक्षतर्फ निर्वाचित भएका थिए।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/११/२८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_01.csv  →  आसमान दैनिक GK — २०८२/१२/०१  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/०१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/०१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/०१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालमा पहिलो पटक प्रेसको स्थापना कुन राणा प्रधानमन्त्रीको पालादेखि सुरु भयो?', E'जंग ब. राणा', E'वीर समसेर', E'देव समसेर', E'चन्द्र समसेर', 'A', E'नेपालमा पहिलो पटक प्रेसको स्थापना प्रधानमन्त्री **जंगबहादुर राणाको** पालामा भएको थियो। उनले युरोप भ्रमणबाट फर्किंदा वि.सं. १९०८ मा ''गिद्दे प्रेस'' नामक छापाखाना नेपाल भित्र्याएका थिए, जुन नेपालको पहिलो छापाखाना हो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधान बमोजिम स्वच्छ वातावरणको हक कसलाई प्राप्त हुन्छ?', E'प्रत्येक व्यक्तिलाई', E'प्रत्येक नागरिकलाई', E'हरेक व्यक्तिलाई', E'सबै नागरिकलाई', 'B', E'नेपालको संविधानले **प्रत्येक नागरिकलाई** स्वच्छ वातावरणको हक प्रदान गरेको छ।\nनोट: नागरिकलाई प्रदान गरिने अन्य मौलिक हकहरूमा रोजगारीको हक, खाद्य सम्बन्धी हक, आवासको हक, र सूचनाको हक पर्दछन्।', 'nepali'),
      (v_set_id, 3, E'सूर्यको आकर्षण शक्ति पृथ्वीभन्दा कति गुणा ठूलो छ?', E'२८ गुणा', E'२५ गुणा', E'२४ गुणा', E'२२ गुणा', 'A', E'सूर्यको आकर्षण शक्ति पृथ्वीको भन्दा **२८ गुणा** ठूलो छ।\nनोट: बृहस्पतिको आकर्षण शक्ति भने पृथ्वीको भन्दा ३.५ गुणा ठूलो रहेको छ।', 'nepali'),
      (v_set_id, 4, E'आन्ध्र महासागरमा टाइटानिक जहाज दुर्घटना कहिले भएको थियो?', E'सन् १९१२', E'सन् १९१३', E'सन् १९१४', E'सन् १९१५', 'A', E'टाइटानिक जहाज दुर्घटना **सन् १९१२** मा आन्ध्र महासागरमा भएको थियो। बेलायतको साउथह्याम्पटनबाट अमेरिकाको न्युयोर्कसम्मको आफ्नो पहिलो यात्रामा रहेको यो जहाजलाई सामुद्रिक इतिहासको सबैभन्दा भयानक दुर्घटना मानिन्छ, जसमा १५१७ जनाको मृत्यु भएको थियो।', 'nepali'),
      (v_set_id, 5, E'कोशी नदीको सिञ्चित क्षेत्र कति रहेको छ?', E'३३,००० वर्ग कि.मि.', E'२६,००० वर्ग कि.मि.', E'४९,००० वर्ग कि.मि.', E'३६,००० वर्ग कि.मि.', 'A', E'**कोशी नदीले करिब ३३,००० वर्ग कि.मी. क्षेत्र सिञ्चित गरेको छ।**\n- गण्डकी नदीले करिब २६,००० वर्ग कि.मी. क्षेत्र सिञ्चित गरेको छ।\n- कर्णाली नदीले करिब ४९,००० वर्ग कि.मी. क्षेत्र सिञ्चित गरेको छ।', 'nepali'),
      (v_set_id, 6, E'नेपाल र चीन बीचमा सीमा प्रोटोकल सम्झौतामा हस्ताक्षर कहिले भएको थियो?', E'सन् १९६०', E'सन् १९६१', E'सन् १९६२', E'सन् १९६३', 'B', E'नेपाल र चीन बीचमा सीमा प्रोटोकल सम्झौतामा **सन् १९६१ अक्टोबर ५** मा हस्ताक्षर भएको थियो।\nनोट: यो सम्झौतामा नेपालका राजा श्री ५ महेन्द्र र चीनका तत्कालीन राष्ट्रपति लिउ साउचीले हस्ताक्षर गरेका थिए, जसले नेपाल-चीन (तिब्बत) बीचको सीमा निर्धारण गर्‍यो।', 'nepali'),
      (v_set_id, 7, E'बंगलादेशकी पहिलो महिला प्रधानमन्त्री खालिदा जियाको निधन कहिले भएको हो ?', E'२०२४ डिसेम्बर ३०', E'२०२४ डिसेम्बर २९', E'२०२४ डिसेम्बर २८', E'२०२४ डिसेम्बर २७', 'A', E'बंगलादेशकी पहिलो महिला प्रधानमन्त्री खालिदा जियाको निधन **२०२४ डिसेम्बर ३०** मा भएको हो।\nनोट: उनी सन् १९९१-१९९६ र सन् २००१-२००६ गरी दुई पटक बंगलादेशको प्रधानमन्त्री बनेकी थिइन्।', 'nepali'),
      (v_set_id, 8, E'दुवै खुट्टा घुँडा माथिबाट काटिएको अवस्थामा पनि विश्वका सातै महादेशका अग्ला हिमाल पूरा गर्ने कीर्तिमान कायम गरेका नेपाली आरोही को हुन् ?', E'हरि बुढामगर', E'निर्मल पुजा', E'फुन्जो झाङमु', E'कामिरिता शेर्पा', 'A', E'**हरि बुढामगर** दुवै खुट्टा घुँडा माथिबाट काटिएको अवस्थामा (double above-knee amputee) विश्वका सातै महादेशका अग्ला हिमाल आरोहण गरी कीर्तिमान कायम गर्ने नेपाली आरोही हुन्।\n- कामिरिता शेर्पाले सगरमाथाको ३० औं पटक सफल आरोहण गरी कीर्तिमान कायम गरेका छन्।', 'nepali'),
      (v_set_id, 9, E'सार्वजनिक संस्थानको वार्षिक स्थिति समीक्षा, २०८२ अनुसार व्यवसायिक कारोबार नगरेका संस्थानहरूको संख्या कति रहेको छ?', E'५ वटा', E'६ वटा', E'७ वटा', E'८ वटा', 'B', E'सार्वजनिक संस्थानको वार्षिक स्थिति समीक्षा, २०८२ अनुसार व्यवसायिक कारोबार नगरेका संस्थानहरूको संख्या **६ वटा** रहेको छ।\nनोट: सोही समीक्षा अनुसार, २५ संस्थानहरू सञ्चित नाफामा र १८ संस्थानहरू सञ्चित नोक्सानमा रहेका छन्। सञ्चित नाफा सबैभन्दा धेरै हुने संस्थान नेपाल दूरसञ्चार कम्पनी लिमिटेड हो।', 'nepali'),
      (v_set_id, 10, E'''Man is born free but everywhere he is in chain'' यो भनाइ कसको हो?', E'नेपोलियन बोनापार्ट', E'लुई १४ औं', E'भोल्तेयर', E'रुसो', 'D', E'**''मानिस स्वतन्त्र जन्मन्छ तर सर्वत्र साङ्लोले बाँधिन्छ'' (Man is born free but everywhere he is in chain) भन्ने प्रसिद्ध भनाइ दार्शनिक रुसोको हो।**\nनोट: उनको अर्को प्रसिद्ध भनाइ ''Nature is far better than civilization'' (प्रकृति सभ्यताभन्दा धेरै राम्रो छ) पनि हो।', 'nepali'),
      (v_set_id, 11, E'प्रथम मल्ल राजा अरिदेव मल्ल कहिले राजा बने?', E'वि.सं. १२१०', E'वि.सं. १२५८', E'वि.सं. १२७४', E'वि.सं. १२८४', 'B', E'प्रथम मल्ल राजा अरिदेव मल्ल **वि.सं. १२५८** मा राजा बनेका थिए।\nनोट: उनी वि.सं. १२१० मा जन्मेका थिए र १५ वर्ष शासन गरेपछि वि.सं. १२७४ मा उनको देह त्याग भएको थियो।', 'nepali'),
      (v_set_id, 12, E'त्रिभुवन शाहको मृत्यु कहिले भएको थियो?', E'२०११ फागुन ३०', E'२०१२ फागुन ३०', E'२०१३ फागुन ३०', E'२०१४ फागुन ३०', 'A', E'राजा त्रिभुवन शाहको मृत्यु **वि.सं. २०११ फागुन ३०** मा स्वीट्जरल्याण्डमा उपचारको क्रममा भएको थियो।\nनोट: उनी नेपालभन्दा बाहिर मृत्यु हुने शाह वंशीय राजा थिए।', 'nepali'),
      (v_set_id, 13, E'भगवान गौतम बुद्धले उपदेश कुन भाषामा दिन्थे?', E'शाक्य', E'गन्ध', E'पाली', E'बोधी', 'C', E'**भगवान गौतम बुद्धले पाली भाषामा उपदेश दिन्थे।**\n- शाक्य उनको वंश थियो।\n- गन्धकुटी उनले बस्ने कुटीलाई भनिन्थ्यो।\n- बोधी (बोधिवृक्ष) मुनि उनले बुद्धत्व प्राप्त गरेका थिए।', 'nepali'),
      (v_set_id, 14, E'पारिस्थितिक प्रणालीमा हुने घटनाको क्रम जहाँ एक जिवले अर्को जिवलाई खाएर उपभोग गर्दछन् र क्रम चलिरहन्छ, यो क्रमलाई के भनिन्छ?', E'खाद्य जाल', E'खाद्य चक्र', E'खाद्य प्रक्रिया', E'विच्छेदक', 'B', E'**पारिस्थितिक प्रणालीमा एक जीवले अर्को जीवलाई खाएर ऊर्जा उपभोग गर्ने क्रमलाई खाद्य चक्र (Food Chain) भनिन्छ।**\n- खाद्य जाल (Food Web) भनेको धेरै अन्तरसम्बन्धित खाद्य श्रृङ्खलाहरूको सञ्जाल हो।\n- खाद्य प्रक्रिया कुनै निश्चित पारिस्थितिक शब्दावली होइन।\n- विच्छेदक (Decomposer) हरू मृत जीवहरूलाई कुहाएर पोषक तत्वहरू पुनः प्रणालीमा फर्काउने जीवहरू हुन्।', 'nepali'),
      (v_set_id, 15, E'नेपाल कहिले बिमस्टेकको सदस्य बनेको हो?', E'२००४ फेब्रुअरी २', E'२००४ फेब्रुअरी ४', E'२००४ फेब्रुअरी ८', E'२००४ फेब्रुअरी ६', 'C', E'नेपाल **सन् २००४ फेब्रुअरी ८** मा बिमस्टेक (BIMSTEC) को सदस्य बनेको हो।\nनोट: नेपालसँगै भुटानले पनि सोही दिन सदस्यता प्राप्त गरेको थियो, जसपछि बिमस्टेकका सदस्य राष्ट्रहरूको संख्या ७ पुगेको हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/०१', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_02.csv  →  आसमान दैनिक GK — २०८२/१२/०२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/०२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/०२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/०२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'पारिवारिक मामिला र सम्पत्तिमा दम्पतिको समान हक हुनेछ। माथिको कथन कुन हक सँग सम्बन्धित रहेको छ?', E'महिलाको हक', E'समानताको हक', E'सम्पतीको हक', E'न्याय सम्बन्धी हक', 'A', E'नेपालको संविधानमा व्यवस्था भए अनुसार, **पारिवारिक मामिला र सम्पत्तिमा दम्पतीको समान हक हुने** कुरा महिलाको हक अन्तर्गत पर्दछ।\nनोट: यसै हक अन्तर्गत प्रत्येक महिलालाई सुरक्षित मातृत्व र प्रजनन स्वास्थ्य सम्बन्धी हक पनि सुनिश्चित गरिएको छ।', 'nepali'),
      (v_set_id, 2, E'सूर्यको विकिरण नाप्न प्रयोग गरिने यन्त्र कुन हो?', E'हेलिस्कोप', E'पारहेलियोमिटर', E'फोटोमिटर', E'एक्टिमोमिटर', 'B', E'**सूर्यको विकिरण नाप्न पारहेलियोमिटर (Pyrheliometer) प्रयोग गरिन्छ।**\n- हेलिस्कोप (Helioscope) सूर्यलाई हेर्न प्रयोग गरिने यन्त्र हो।\n- फोटोमिटर (Photometer) सूर्यको प्रकाशको तीव्रता नाप्न प्रयोग गरिन्छ।\n- एक्टिमोमिटर (Actimometer) सूर्यको किरणको तापीय तीव्रता निश्चित गर्ने उपकरण हो।', 'nepali'),
      (v_set_id, 3, E'दुबै गोलार्द्ध तर्फ ५° अक्षांशभित्र पाइने हावापानीलाई के भनिन्छ?', E'भू-मध्यरेखीय', E'उष्ण मौसमी', E'भू-मध्यसागरीय', E'समशितोष्ण', 'A', E'**दुबै गोलार्द्ध तर्फ ५° अक्षांशभित्र पाइने हावापानीलाई भू-मध्यरेखीय हावापानी भनिन्छ।**\n- उष्ण मौसमी हावापानी ५° देखि ३०° अक्षांशभित्र पाइन्छ।\n- भू-मध्यसागरीय हावापानी ३०° देखि ४५° दुबै गोलार्द्धमा पाइन्छ।\n- समशितोष्ण हावापानी (जस्तै समशितोष्ण तृणभूमि) ४५° देखि ६०° दुबै गोलार्द्धमा पाइन्छ।', 'nepali'),
      (v_set_id, 4, E'नेपालको कुल अन्तर्राष्ट्रिय सिमाना कति कि.मि. रहेको छ?', E'२८२६ कि.मि.', E'२८९६ कि.मि.', E'२९३६ कि.मि.', E'२९२६ कि.मि.', 'D', E'नेपालको कुल अन्तर्राष्ट्रिय सिमाना **२९२६ कि.मि.** रहेको छ। यो भारत र चीन दुई देशसँग जोडिएको छ।\nनोट: नेपालको सिमाना भारतसँग १६९० कि.मि. र चीनसँग १२३६ कि.मि. रहेको छ (१६९० + १२३६ = २९२६)।', 'nepali'),
      (v_set_id, 5, E'कोशी नदीका सातवटा सहायक नदीहरू मध्ये सबैभन्दा पश्चिमको सहायक नदी कुन हो?', E'इन्द्रावती', E'तमोर', E'अरुण', E'तामाकोशी', 'A', E'कोशी नदीका सहायक नदीहरूमध्ये सबैभन्दा पश्चिमको सहायक नदी **इन्द्रावती** हो।\n- तमोर कोशीको सबैभन्दा पूर्वको सहायक नदी हो।\n- अरुण पूर्वबाट दोस्रो सहायक नदी हो।\n- तामाकोशी कोशीको सहायक नदीहरूमध्ये एक हो जुन लिखु र सुनकोशीको बीचमा पर्दछ।\nनोट: कोशीका सहायक नदीहरूको पूर्वदेखि पश्चिमको क्रम: तमोर, अरुण, दुधकोशी, लिखु, तामाकोशी, सुनकोशी, र इन्द्रावती हो।', 'nepali'),
      (v_set_id, 6, E'फ्रान्सेली राज्य क्रान्ति कहिले भयो?', E'१७८९ मे ५', E'१७८८ मे ५', E'१७८७ मे ५', E'१७८६ मे ५', 'A', E'फ्रान्सेली राज्य क्रान्ति **सन् १७८९ मे ५** मा भएको थियो। फ्रान्समा तत्कालीन शासकहरूको भ्रष्ट आर्थिक विशृङ्खलता र गलत नीतिको विरोधमा यो क्रान्ति भएको थियो।\nनोट: यो क्रान्ति हुँदा नेपालमा राजा रणबहादुर शाह थिए र यसलाई बौद्धिक क्रान्ति पनि भनिन्छ।', 'nepali'),
      (v_set_id, 7, E'हालसालै प्रक्षेपण गरिएको नेपाली असफल भू-उपग्रहको नाम के हो?', E'नेपाली स्याट', E'मुनाल', E'डाँफे', E'नेपाल किड', 'B', E'हालसालै प्रक्षेपणमा असफल भएको नेपाली भू-उपग्रहको नाम **मुनाल** हो।\n- नेपाली स्याट (नेपाली स्याट-१) नेपालको पहिलो भू-उपग्रह हो, जुन वि.सं. २०७६ वैशाख ५ मा सफलतापूर्वक प्रक्षेपण गरिएको थियो।\n- डाँफे र नेपाल किड यस सन्दर्भमा सम्बन्धित नामहरू होइनन्।\nनोट: मुनाल उपग्रह उच्च माध्यमिक तहका विद्यार्थीहरूको नेतृत्वमा निर्माण गरिएको थियो र यसको प्रक्षेपण भारतको श्रीहरिकोटास्थित सतीश धवन अन्तरिक्ष केन्द्रबाट भएको थियो।', 'nepali'),
      (v_set_id, 8, E'२०८२ सालमा मनाइएको भूकम्प सुरक्षा दिवस कति औं हो ?', E'२६ औं', E'२७ औं', E'२८ औं', E'२९ औं', 'C', E'वि.सं. २०८२ सालमा **२८ औं** राष्ट्रिय भूकम्प सुरक्षा दिवस मनाइएको थियो। यो दिवस हरेक वर्ष माघ २ गते मनाइन्छ।\nनोट: वि.सं. १९९० माघ २ गतेको महाभूकम्पको स्मृतिमा वि.सं. २०५५ देखि राष्ट्रिय भूकम्प सुरक्षा दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 9, E'हाल सबैभन्दा बढी नाफामा रहेका संस्थान कुन हो?', E'निक्षेप तथा कर्जा लगानी कोष', E'नेपाल आयल निगम', E'नेपाल विद्युत प्राधिकरण', E'नेपाल दूरसञ्चार कम्पनी लि.', 'C', E'हाल सबैभन्दा बढी नाफामा रहेको संस्थान **नेपाल विद्युत प्राधिकरण** हो।\n- नेपाल आयल निगम दोस्रो बढी नाफामा रहेको संस्थान हो।\n- नेपाल दूरसञ्चार कम्पनी लि. तेस्रो स्थानमा छ।\n- निक्षेप तथा कर्जा लगानी कोष चौथो बढी नाफा कमाउने संस्थान हो।', 'nepali'),
      (v_set_id, 10, E'१६ औं योजनाको अन्तिम वर्ष सम्म इन्टरनेटमा पहुँच प्राप्त जनसंख्या कति प्रतिशत पुर्याउने लक्ष्य रहेको छ?', E'८० प्रतिशत', E'७० प्रतिशत', E'१०० प्रतिशत', E'९० प्रतिशत', 'D', E'१६ औं योजनाको अन्तिम वर्षसम्ममा इन्टरनेटमा पहुँच प्राप्त जनसंख्या **९० प्रतिशत** पुर्याउने लक्ष्य रहेको छ।\nनोट: नेपालको दीर्घकालीन सोच अनुसार वि.सं. २१००/०१ सम्ममा इन्टरनेटमा पहुँच प्राप्त जनसंख्या १०० प्रतिशत पुर्याउने लक्ष्य छ।', 'nepali'),
      (v_set_id, 11, E'लिच्छविकालिन समयमा सिपाहीलाई के भनिन्थ्यो?', E'दण्डनायक', E'भट्ट', E'युवराज', E'अमात्य', 'B', E'लिच्छविकालिन समयमा सिपाहीलाई **भट्ट** भनिन्थ्यो।\n- दण्डनायकको अर्थ प्रहरी प्रमुख हुन्थ्यो।\n- युवराजको अर्थ भावी राजा हुन्थ्यो।\n- अमात्यको अर्थ मन्त्री हुन्थ्यो।', 'nepali'),
      (v_set_id, 12, E'त्रिभुवन शाहले कति वर्ष नेपालमा शासन गरेका थिए?', E'४२ वर्ष', E'४३ वर्ष', E'४४ वर्ष', E'४५ वर्ष', 'B', E'राजा त्रिभुवनले नेपालमा **४३ वर्ष** शासन गरेका थिए। उनी शाहवंशीय इतिहासमा सबैभन्दा लामो समय शासन गर्ने राजा हुन्, जसले वि.सं. १९६८ देखि वि.सं. २०११ सम्म शासन चलाए।', 'nepali'),
      (v_set_id, 13, E'प्युरिटिन तथा रोमन क्याथोलिक सभ्यता विश्व भूगोलको कुन धर्म सँग सम्बन्धित छन्?', E'बौद्ध', E'शिख', E'इसाई', E'इस्लाम', 'C', E'प्युरिटिन तथा रोमन क्याथोलिक **इसाई** धर्मसँग सम्बन्धित सम्प्रदायहरू हुन्।\n- बौद्ध धर्मका सम्प्रदायहरूमा हिनयान, महायान, बज्रयान, तन्त्रयान र लामावाद पर्दछन्।\n- इस्लाम धर्मका प्रमुख सम्प्रदायहरू सुन्नी र सिया हुन्।', 'nepali'),
      (v_set_id, 14, E'देहायका मध्ये कुन प्राथमिक उपभोक्ताको उदाहरण हैन?', E'गैंड्यौला', E'मृग', E'चराचुरुङ्गी', E'मुसा', 'C', E'**चराचुरुङ्गी** द्वितीय उपभोक्ताको उदाहरण हो, प्राथमिक उपभोक्ताको होइन। प्राथमिक उपभोक्ताहरू (जस्तै: गैंड्यौला, मृग, मुसा) शाकाहारी हुन्छन् र खानाको लागि उत्पादकहरूमा निर्भर रहन्छन्, भने द्वितीय उपभोक्ताहरू खानाको लागि प्राथमिक उपभोक्तामा निर्भर हुन्छन् र मांसाहारी वा सर्वाहारी हुन सक्छन्।', 'nepali'),
      (v_set_id, 15, E'दिवेही कुन सार्क मुलुकको राष्ट्रिय भाषा हो?', E'बंगलादेश', E'श्रीलंका', E'माल्दिभ्स', E'भुटान', 'C', E'दिवेही **माल्दिभ्सको** राष्ट्रिय भाषा हो।\n- बंगलादेशको राष्ट्रिय भाषा बंगाली हो।\n- श्रीलंकाको राष्ट्रिय भाषा सिंहाली हो।\n- भुटानको राष्ट्रिय भाषा जोङ्खा हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/०२', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_03.csv  →  आसमान दैनिक GK — २०८२/१२/०३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/०३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/०३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/०३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालमा इन्टरनेटको सुरुवात कहिलेबाट भयो?', E'सन् १९९२', E'सन् १९९४', E'सन् १९९६', E'सन् १९९८', 'B', E'नेपालमा इन्टरनेटको सुरुवात **सन् १९९४** बाट भएको हो।\nनोट: नेपालमा इन्टरनेट सेवा सुरु गर्ने पहिलो कम्पनी मर्कन्टाइल कम्युनिकेसन्स हो।', 'nepali'),
      (v_set_id, 2, E'प्रत्येक नागरिकलाई स्वच्छ खानेपानी तथा सरसफाइमा पहुँचको हक हुनेछ भन्ने कुरा नेपालको संविधानको कुन धारामा उल्लेख गरिएको छ?', E'धारा ३५', E'धारा ३४', E'धारा ३३', E'धारा ३२', 'A', E'नेपालको संविधानको **धारा ३५** मा प्रत्येक नागरिकलाई स्वच्छ खानेपानी तथा सरसफाइमा पहुँचको हक हुने व्यवस्था छ।\n- धारा ३४ मा श्रमको हक सम्बन्धी व्यवस्था छ।\n- धारा ३३ मा रोजगारीको हक सम्बन्धी व्यवस्था छ।\n- धारा ३२ मा भाषा तथा संस्कृतिको हक सम्बन्धी व्यवस्था छ।\nनोट: धारा ३५ ले नै प्रत्येक नागरिकलाई राज्यबाट आधारभूत स्वास्थ्य सेवा निःशुल्क प्राप्त गर्ने हकको पनि सुनिश्चितता गरेको छ।', 'nepali'),
      (v_set_id, 3, E'सूर्यभन्दा ठूलो तारा बिष्फोट भएको अवस्थालाई के भनिन्छ?', E'सुपरनोभा', E'मेन्टल', E'क्रस्ट', E'कोर', 'A', E'सूर्यभन्दा ठूलो तारा बिष्फोट भएको अवस्थालाई **सुपरनोभा** भनिन्छ।\n- मेन्टल पृथ्वीको मध्य भाग हो।\n- क्रस्ट पृथ्वीको बाह्य सतहको भाग हो।\n- कोर पृथ्वीको केन्द्रको भागलाई भनिन्छ।', 'nepali'),
      (v_set_id, 4, E'हिन्द महासागर चल्ने स्थानिय वायुलाई के भनिन्छ?', E'साइक्लोन', E'टोर्नाडो', E'विलिविलि', E'लु', 'A', E'हिन्द महासागरमा चल्ने स्थानीय वायुलाई **साइक्लोन** भनिन्छ।\n- टोर्नाडो पश्चिम अफ्रिकी क्षेत्रमा चल्ने स्थानीय वायु हो।\n- विलिविलि दक्षिण पश्चिम अष्ट्रेलियामा चल्ने स्थानीय वायु हो।\n- लु थार र गोबी मरुभूमिमा चल्ने तातो हावा हो।\nनोट: बंगालको खाडीमा चल्ने वायुलाई पनि साइक्लोन नै भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'लिपुलेख तथा लिम्पियाधुरा समावेश गरिएको नेपालको नयाँ नक्सा प्रतिनिधि सभाबाट कहिले पारित भएको थियो?', E'२०७७ वैशाख ७', E'२०७७ असार ४', E'२०७७ जेठ ३१', E'२०७७ जेठ ५', 'C', E'नेपालको नयाँ नक्सा (लिपुलेख, लिम्पियाधुरा र कालापानी सहित) प्रतिनिधि सभाबाट **वि.सं. २०७७ जेठ ३१** गते पारित भएको थियो।\n- वि.सं. २०७७ असार ४ मा यो नक्सा राष्ट्रिय सभाबाट पारित भई राष्ट्रपतिबाट प्रमाणित भएको थियो।\n- वि.सं. २०७७ जेठ ५ मा मन्त्रिपरिषदले नयाँ नक्सा स्वीकृत गरी राजपत्रमा प्रकाशित गर्ने निर्णय गरेको थियो।\n- वि.सं. २०७७ जेठ ७ मा तत्कालीन भूमि व्यवस्था मन्त्री पद्माकुमारी अर्यालले नक्सा सार्वजनिक गरेकी थिइन्।', 'nepali'),
      (v_set_id, 6, E'प्रश्न वाचक चिन्ह भएको ठाँउमा उपयुक्त विकल्प छनोट गर्नुहोस् : (मेची:महानन्दा :: महाकाली:?)', E'बेरिङ', E'दामोदर', E'सरयु', E'शारदा', 'D', E'महाकाली नदीलाई भारतमा पुगेपछि **शारदा** नामले चिनिन्छ, जसरी मेची नदीलाई महानन्दा भनिन्छ।\n- कन्काई नदीलाई भारतमा बेरिङ भनिन्छ।\n- कोशी नदीलाई भारतमा दामोदर भनिन्छ।\n- बबई नदीलाई भारतमा सरयु भनिन्छ।', 'nepali'),
      (v_set_id, 7, E'हालसालै FATF - International Cooperation Review Group को बैठक २०२६ कहाँ सम्पन्न भएको छ ?', E'जेनेभा', E'बैंकक', E'टोकियो', E'काठमाडौं', 'B', E'सन् २०२६ को FATF - International Cooperation Review Group को बैठक थाइल्याण्डको **बैंकक**मा सम्पन्न भएको थियो।\nनोट: यो बैठक सन् २०२६ जनवरी ६ (वि.सं. २०८२ पौष २२) मा आयोजना भएको थियो र यसको सम्बन्ध सम्पत्ति शुद्धिकरणसँग रहेको छ।', 'nepali'),
      (v_set_id, 8, E'राष्ट्रिय रेशम सम्मेलन, २०८२ कहिले सम्पन्न भएको छ ?', E'२०८२ पौष २४', E'२०८२ पौष २४', E'२०८२ पौष २६', E'२०८२ पौष २७', 'C', E'राष्ट्रिय रेशम सम्मेलन **वि.सं. २०८२ पौष २६** मा सम्पन्न भएको थियो।\nनोट: यो सम्मेलन काठमाडौंमा रेशम उद्योगको पुनःजागरण गर्ने उद्देश्यले आयोजना गरिएको थियो।', 'nepali'),
      (v_set_id, 9, E'औद्योगिक क्षेत्रमा कतिवटा संस्थाहरू रहेका छन्?', E'४ वटा', E'१० वटा', E'५ वटा', E'११ वटा', 'B', E'नेपालमा औद्योगिक क्षेत्रमा **१० वटा** सार्वजनिक संस्थानहरू रहेका छन्।\n- व्यापारिक क्षेत्रमा ४ वटा संस्थानहरू छन्।\n- जनोपयोगी र सामाजिक क्षेत्रमा ५-५ वटा संस्थानहरू छन्।\n- सेवा क्षेत्रमा ११ वटा संस्थानहरू छन्।\nनोट: वित्तीय क्षेत्रमा पनि १० वटै संस्थानहरू रहेका छन्।', 'nepali'),
      (v_set_id, 10, E'म नै राज्य हुँ राज्य नै म हो भन्ने फ्रान्सेली राजा को हुन?', E'लुई चौधौं', E'लुई दशौं', E'लुई बाह्रौं', E'लुई सोह्रौं', 'A', E'''म नै राज्य हुँ'' भन्ने फ्रान्सेली राजा **लुई चौधौं** हुन्, जो एक निरंकुश शासक थिए।\n- लुई दशौं फ्रान्सका एक प्रारम्भिक राजा थिए।\n- लुई बाह्रौंलाई ''जनताका पिता'' (Father of the People) भनेर चिनिन्थ्यो।\n- लुई सोह्रौं फ्रान्सेली राज्य क्रान्तिको समयमा फ्रान्सका राजा थिए र उनलाई मृत्युदण्ड दिइएको थियो।', 'nepali'),
      (v_set_id, 11, E'लिच्छविकालिन समयमा प्रधानमन्त्रीलाई के भनिन्थ्यो?', E'महाबलाध्यक्ष', E'महासर्वदण्डनायक', E'महासामन्त', E'युवराज', 'C', E'लिच्छविकालमा प्रधानमन्त्रीलाई **महासामन्त** भनिन्थ्यो।\n- महाबलाध्यक्ष पदले प्रधानसेनापतिलाई जनाउँथ्यो।\n- महासर्वदण्डनायक पदले प्रधान न्यायाधीशलाई जनाउँथ्यो।\n- युवराज भनेको भावी राजा वा राजकुमार हुन्।', 'nepali'),
      (v_set_id, 12, E'श्री ५ त्रिभुवनको पालामा राणा प्रधानमन्त्री बाहेकको प्रधानमन्त्री बनेकाको थिए?', E'मातृका प्र. कोइराला', E'वि पि कोइराला', E'डा. के आई सिंह', E'कुनै भएनन्', 'A', E'श्री ५ त्रिभुवनको पालामा राणा प्रधानमन्त्री बाहेक **मातृका प्रसाद कोइराला** प्रधानमन्त्री बनेका थिए। त्रिभुवनको पालामा जम्मा ६ जना प्रधानमन्त्री भए, जसमध्ये ५ जना राणा (चन्द्रशमशेर, भीमशमशेर, जुद्धशमशेर, पद्मशमशेर, मोहनशमशेर) र एक जना गैर-राणा (मातृका प्रसाद कोइराला) थिए।', 'nepali'),
      (v_set_id, 13, E'देहाएका मध्ये कुन धार्मिक पुस्तकका लेखक वेदव्यास होइनन्?', E'महाभारत', E'अठार पुराण', E'भगवद्गीता', E'रामायण', 'D', E'**रामायणका** लेखक वेदव्यास होइनन्, यसका लेखक वाल्मीकि हुन्।\n- महाभारत वेदव्यासद्वारा रचिएको महाकाव्य हो।\n- अठार पुराणहरू पनि वेदव्यासले नै लेखेका हुन्।\n- भगवद्गीता महाभारतकै एक अंश हो, जसलाई वेदव्यासकै रचना मानिन्छ।', 'nepali'),
      (v_set_id, 14, E'उत्पादकलाई पोषक तत्वहरू प्रदान गरी पुनः उत्पादनमा मद्दत गर्ने कार्य कसको हो?', E'प्राथमिक उपभोक्ता', E'तृतीय उपभोक्ता', E'विच्छेदक', E'अजैविक तत्वको', 'C', E'**विच्छेदकहरूले** उत्पादकलाई पोषक तत्वहरू प्रदान गरी पुनः उत्पादनमा मद्दत गर्दछन्। फङ्गी र ब्याक्टेरिया जस्ता विच्छेदकहरूले मृत र सड्ने जैविक पदार्थहरूलाई विघटन गरी पारिस्थितिक प्रणालीको लागि आवश्यक पोषक तत्वहरू उपलब्ध गराउँछन्।', 'nepali'),
      (v_set_id, 15, E'कुन सार्क मुलुकको मुद्रा टाका हो?', E'बंगलादेश', E'श्रीलंका', E'पाकिस्तान', E'भुटान', 'A', E'**बंगलादेशको** मुद्रा टाका हो।\n- श्रीलंकाको मुद्रा श्रीलंकन रुपी हो।\n- पाकिस्तानको मुद्रा पाकिस्तानी रुपी हो।\n- भुटानको मुद्रा नेगुल्ट्रम हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/०३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_08.csv  →  आसमान दैनिक GK — २०८२/१२/०८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/०८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/०८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/०८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'गोरखा पत्र साते दिन प्रकाशन सुरु कहिले देखि भएको थियो?', E'२००३ पुस ८', E'२०१९ फागुन ७', E'२०२९ असार १०', E'२०६४ असोज १', 'B', E'**गोरखा पत्रले वि.सं. २०१९ फागुन ७ देखि दैनिक (साते दिन) प्रकाशन सुरु गरेको थियो।**\n- वि.सं. २००३ पुस ८ मा गोरखा पत्र हप्तामा ३ पटक प्रकाशन हुन थालेको थियो।\n- वि.सं. २०२९ असार १० देखि गोरखा पत्र रङ्गिनमा प्रकाशन हुन थालेको हो।\n- वि.सं. २०६४ असोज १ देखि गोरखा पत्र बहुभाषामा प्रकाशित हुन थालेको हो।', 'nepali'),
      (v_set_id, 2, E'''कुनै पनि व्यक्तिलाई देश निकाला गर्न पाइने छैन'' माथिको कथन नेपालको संविधानको कुन धारामा उल्लेख गरिएको छ?', E'धारा ४४', E'धारा ४३', E'धारा ४५', E'धारा ४६', 'C', E'**''कुनै पनि व्यक्तिलाई देश निकाला गर्न पाइने छैन'' भन्ने व्यवस्था नेपालको संविधानको धारा ४५ मा गरिएको छ, जुन देश निकाला विरुद्धको हक हो।**\n- धारा ४४ मा उपभोक्ताको हक सम्बन्धी व्यवस्था छ।\n- धारा ४३ मा सामाजिक सुरक्षाको हक सम्बन्धी व्यवस्था छ।\n- धारा ४६ मा संवैधानिक उपचारको हक सम्बन्धी व्यवस्था छ।', 'nepali'),
      (v_set_id, 3, E'पृथ्वीले सूर्यको परिक्रमा गर्ने बाटोलाई पृथ्वीको के भनिन्छ?', E'अक्ष', E'कक्ष', E'वर्ष', E'वर्ण', 'B', E'**पृथ्वीले सूर्यको परिक्रमा गर्ने बाटोलाई कक्ष (Orbit) भनिन्छ।**\n- पृथ्वी आफ्नो वरिपरि घुम्ने काल्पनिक रेखालाई अक्ष (Axis) भनिन्छ।\n- पृथ्वीले सूर्यको एक परिक्रमा पूरा गर्न लाग्ने समय अवधिलाई एक वर्ष भनिन्छ।\n- वर्णको अर्थ रङ वा अक्षर हुन्छ, जसको खगोलीय विज्ञानसँग सम्बन्ध छैन।', 'nepali'),
      (v_set_id, 4, E'The Bermuda Triangle is located in which ocean?', E'Indian Ocean', E'Atlantic Ocean', E'Pacific Ocean', E'Arctic Ocean', 'B', E'**बर्मुडा त्रिकोण (The Bermuda Triangle) आन्ध्र महासागर (Atlantic Ocean) मा अवस्थित छ।**\n- हिन्द महासागर (Indian Ocean) तेस्रो ठूलो महासागर हो।\n- प्रशान्त महासागर (Pacific Ocean) विश्वको सबैभन्दा ठूलो महासागर हो।\n- आर्कटिक महासागर (Arctic Ocean) विश्वको सबैभन्दा सानो महासागर हो।\nनोट: यो रहस्यमय समुद्री क्षेत्र मियामी, बर्मुडा र प्युर्टो रिकोको बिचमा रहेको छ र यसलाई ''शैतान सागर'' पनि भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'नेपालको भूगोलमा चीन र भारत दुबैलाई नछुने नेपाली जिल्ला कति वटा रहेको छन्?', E'३७ वटा', E'३६ वटा', E'३५ वटा', E'३४ वटा', 'A', E'नेपालका **३७ वटा** जिल्लाहरूले चीन र भारत दुवै देशको सिमाना छुँदैनन्। यस्ता जिल्लाहरूलाई भूपरिवेष्ठित जिल्ला भनिन्छ।\nनोट: नेपालका कुल ७७ जिल्लामध्ये १३ जिल्लाले चीनलाई मात्र, २५ जिल्लाले भारतलाई मात्र र २ जिल्ला (ताप्लेजुङ र दार्चुला) ले दुवै देशलाई छुन्छन्।', 'nepali'),
      (v_set_id, 6, E'कर्णाली नदीको नामाकरण कुन ऋषिको नामबाट भएको छ?', E'कौशिक ऋषि', E'गण्डव ऋषि', E'कर्णाद ऋषि', E'पञ्चेश्वर ऋषि', 'C', E'**कर्णाली नदीको नामाकरण कर्णाद ऋषिको नामबाट भएको हो।**\n- कौशिक ऋषिको नामबाट कोशी नदीको नामाकरण भएको हो।\n- गण्डव ऋषिको नामबाट गण्डकी नदीको नामाकरण भएको हो।\n- पञ्चेश्वर महाकाली नदीसँग सम्बन्धित एक पवित्र स्थल हो, कुनै ऋषिको नाम होइन।', 'nepali'),
      (v_set_id, 7, E'नेपालको पहिलो माछा संरक्षण क्षेत्रको रुपमा कुन स्थानलाई घोषणा गरिएको छ?', E'गोदावरी', E'बागेश्वरी', E'सत्तिघाट', E'तुल्सिपुर', 'C', E'नेपालको पहिलो माछा संरक्षण क्षेत्रको रुपमा **सत्तिघाट** लाई घोषणा गरिएको छ। यो घोषणा २०८२ पौष २५ गते गरिएको थियो।\nनोट: यो क्षेत्र कर्णाली नदीमा बर्दिया र कैलालीको सिमानामा पर्दछ र यसको क्षेत्रफल ३.९ वर्ग किलोमिटर (३९० हेक्टर) रहेको छ।', 'nepali'),
      (v_set_id, 8, E'दोस्रो डब्ल्युएचओ विश्वव्यापी परम्परागत औषधी शिखर सम्मेलन, २०२४ कहाँ सम्पन्न भएको हो?', E'भारत', E'जापान', E'अमेरिका', E'बेलायत', 'A', E'दोस्रो डब्ल्युएचओ विश्वव्यापी परम्परागत औषधी शिखर सम्मेलन, २०२४ **भारतमा** सम्पन्न भएको हो।\nनोट: यो सम्मेलन सन् २०२४ डिसेम्बर १७-१९ मा आयोजना गरिएको थियो।', 'nepali'),
      (v_set_id, 9, E'नेपालमा हाल सबैभन्दा बढी घाटामा रहेका संस्थान कुन हो?', E'नेपाल खानेपानी संस्थान', E'नेपाल टेलिभिजन', E'नेपाल वायुसेवा निगम', E'हैटौंडा सिमेन्ट उद्योग', 'C', E'**नेपाल वायुसेवा निगम** हाल नेपालमा सबैभन्दा बढी घाटामा रहेको संस्थान हो।\n- नेपाल खानेपानी संस्थान घाटामा रहेको दोस्रो ठूलो संस्थान हो।\n- नेपाल टेलिभिजन नाफामा सञ्चालित संस्थान हो।\n- हेटौंडा सिमेन्ट उद्योग घाटामा रहेको तेस्रो ठूलो संस्थान हो।', 'nepali'),
      (v_set_id, 10, E'शक्ति पृथकीकरणको सिद्धान्तका प्रतिपादक को हुन्?', E'नेपोलियन बोनापार्ट', E'मन्टेस्क्यु', E'भोल्तेयर', E'रुसो', 'B', E'**शक्ति पृथकीकरणको सिद्धान्तका प्रतिपादक मन्टेस्क्यु हुन्।**\n- नेपोलियन बोनापार्ट फ्रान्सका एक सैन्य तथा राजनीतिक नेता थिए।\n- भोल्तेयर वाक् स्वतन्त्रता र धर्मनिरपेक्षताका पक्षपाती एक फ्रान्सेली दार्शनिक थिए।\n- रुसो सामाजिक अनुबन्ध (Social Contract) को सिद्धान्तका लागि परिचित एक जेनेभान दार्शनिक हुन्।\nनोट: मन्टेस्क्युले आफ्नो सिद्धान्त सन् १७४८ मा प्रकाशित पुस्तक ''The Spirit of Law'' मा प्रस्तुत गरेका थिए।', 'nepali'),
      (v_set_id, 11, E'प्रथम मल्ल राजा अरिदेव मल्ल पछि राजा हुने उनका छोरा को हुन्?', E'अभय मल्ल', E'यश मल्ल', E'अमर मल्ल', E'रन मल्ल', 'A', E'प्रथम मल्ल राजा अरिदेव मल्ल पछि उनका छोरा **अभय मल्ल** राजा भएका थिए।\nनोट: अभय मल्ल वि.सं. १२७४ मा राजा बनी ३८ वर्षसम्म शासन चलाएका थिए।', 'nepali'),
      (v_set_id, 12, E'त्रिभुवन शाहको आमाको नाम के हो?', E'राज दिव्येश्वरी', E'रुप दिव्येश्वरी', E'चारु दिव्येश्वरी', E'लक्ष्मी दिव्येश्वरी', 'D', E'त्रिभुवन शाहको आमाको नाम **लक्ष्मी दिव्येश्वरी** हो।\nनोट: उनी राजा पृथ्वी वीरविक्रम शाहकी माहिली महारानी थिइन्। त्रिभुवनको जन्म वि.सं. १९६३ असार १७ गते भएको थियो।', 'nepali'),
      (v_set_id, 13, E'भगवान गौतम बुद्धले जन्म र ज्ञान प्राप्त गरेको एउटै तिथि कुन हो?', E'वैशाख शुक्ल पूर्णिमा', E'जेठ शुक्ल पूर्णिमा', E'असार शुक्ल पूर्णिमा', E'साउन शुक्ल पूर्णिमा', 'A', E'भगवान गौतम बुद्धले जन्म, ज्ञान र महापरिनिर्वाण **वैशाख शुक्ल पूर्णिमा**कै दिन प्राप्त गरेका थिए। यसै दिनलाई बुद्ध जयन्तीको रूपमा मनाइन्छ।\nनोट: बुद्धको जन्म इ.पू. ५६३ मा कपिलवस्तुबाट १४ माइल टाढा लुम्बिनी जंगलमा भएको थियो।', 'nepali'),
      (v_set_id, 14, E'जलवायु परिवर्तन सम्बन्धी विश्वव्यापी सन्धि, पेरिस सम्झौता कहिले भयो?', E'डिसेम्बर १२, २०१५', E'डिसेम्बर १२, २०२०', E'डिसेम्बर १२, २०१६', E'डिसेम्बर १२, २०१७', 'A', E'जलवायु परिवर्तन सम्बन्धी विश्वव्यापी पेरिस सम्झौता **डिसेम्बर १२, २०१५** मा भएको थियो।\nनोट: यो सम्झौता फ्रान्सको पेरिसमा सम्पन्न २१औं कोप (COP21) सँग सम्बन्धित छ।', 'nepali'),
      (v_set_id, 15, E'सात वटा दक्षिण एसियाली र दक्षिणपूर्वी एसियाली राष्ट्रहरूको अन्तर्राष्ट्रिय संगठन कुन हो?', E'ईयु', E'सार्क', E'बिमस्टेक', E'आसियान', 'C', E'सात वटा दक्षिण एसियाली र दक्षिणपूर्वी एसियाली राष्ट्रहरूको अन्तर्राष्ट्रिय संगठन **बिमस्टेक (BIMSTEC)** हो।\n- ईयु (European Union) युरोपेली देशहरूको राजनीतिक र आर्थिक संघ हो।\n- सार्क (SAARC) दक्षिण एसियाका आठ राष्ट्रहरूको क्षेत्रीय संगठन हो।\n- आसियान (ASEAN) दक्षिणपूर्वी एसियाका १० सदस्य राष्ट्रहरूको संगठन हो।\nनोट: बिमस्टेकको पूरा रूप ''Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation'' हो, जसमा बंगलादेश, भुटान, भारत, म्यानमार, नेपाल, श्रीलंका र थाइल्यान्ड सदस्य छन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/०८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_09.csv  →  आसमान दैनिक GK — २०८२/१२/०९  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/०९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/०९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/०९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'दीर्घकालीन सोच २१०० ले वि.सं. २०८७ सम्ममा नेपाललाई आयस्तर भएको मुलुकमा स्तरोन्नति गर्ने लक्ष्य लिएको छ।', E'उच्च मध्यम', E'मध्यम', E'उच्च', E'निम्न मध्यम', 'B', E'दीर्घकालीन सोच २१०० अनुसार वि.सं. २०८७ (सन् २०३०) सम्ममा नेपाललाई **मध्यम** आय भएको मुलुकमा पुऱ्याउने लक्ष्य तय गरिएको छ।\nनोट: यसै सोच अन्तर्गत वि.सं. २०८३ (सन् २०२६) सम्ममा नेपाललाई अतिकम विकसित राष्ट्रबाट विकासशील देशमा स्तरोन्नति गर्ने लक्ष्य पनि रहेको छ।', 'nepali'),
      (v_set_id, 2, E'आर्थिक अवस्था सँग सम्बन्धित ''वाणिज्यको खैरो कागज'' को उपनामले देहाएका मध्ये कुन खेतीलाई बुझाउँछ?', E'चिया', E'कफि', E'अलैंची', E'जुट', 'D', E'**जुटलाई ''वाणिज्यको खैरो कागज'' वा ''खैरो थैलो'' उपनामले चिनिन्छ।**\n- नेपालमा पाइने चियालाई ''Assam Spices'' को रूपमा पनि चिनिन्छ।\n- अलैंचीलाई ''खोल्साको सुन'' वा ''कालो सुन'' भनेर चिनिन्छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधानमा उल्लेख भए अनुसार नागरिकको कर्तव्य कतिवटा रहेको छन?', E'४ वटा', E'५ वटा', E'६ वटा', E'३ वटा', 'A', E'नेपालको संविधानको धारा ४८ मा नागरिकका **४ वटा** कर्तव्यहरूको व्यवस्था गरिएको छ।\nनोट: संविधानको भाग ३, ''मौलिक हक र कर्तव्य'' अन्तर्गत धारा १६ देखि ४६ सम्म ३१ वटा मौलिक हकको व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 4, E'देहायका सौर्यमण्डलका ग्रहहरू मध्ये आफ्नो अक्षमा सबैभन्दा बढि वेगले घुम्ने ग्रह कुन हो?', E'अरुण', E'शुक्र', E'बुध', E'बृहस्पति', 'D', E'सौर्यमण्डलमा आफ्नो अक्षमा सबैभन्दा बढि वेगले घुम्ने ग्रह **बृहस्पति** हो।\n- अरुण (Uranus) ग्रह आफ्नो अक्षमा लगभग ९८ डिग्रीले ढल्किएर घुम्छ।\n- शुक्र (Venus) ग्रह सबैभन्दा ढिलो गतिमा आफ्नो अक्षमा घुम्छ, जसकारण यसको एक दिन एक वर्षभन्दा लामो हुन्छ।\n- बुध (Mercury) ग्रह सूर्यको वरिपरि सबैभन्दा छिटो परिक्रमा गर्ने ग्रह हो, जसको एक वर्ष ८८ दिनको हुन्छ।\nनोट: बृहस्पतिको एक दिन करिब ९ घण्टा ५५ मिनेटको हुन्छ, जुन सौर्यमण्डलका सबै ग्रहहरूमध्ये सबैभन्दा छोटो हो।', 'nepali'),
      (v_set_id, 5, E'विश्वमा सर्वाधिक फोटो खिचिएको र चित्रलेखन गरिएको पहाड फुजी कहाँ पर्दछ?', E'जापान', E'श्रीलंका', E'कोलम्बिया', E'भियतनाम', 'A', E'विश्वमा सर्वाधिक फोटो खिचिएको र चित्रलेखन गरिएको पहाड, माउन्ट फुजी, **जापानमा** पर्दछ।\nनोट: यो पहाड जापानको होन्शु टापुमा अवस्थित एक सक्रिय ज्वालामुखी हो र यसको उचाइ ३,७७६ मिटर छ।', 'nepali'),
      (v_set_id, 6, E'सबैभन्दा धेरै वडा रहेको नेपालको भूगोलको महानगरपालिका कुन हो?', E'भरतपुर', E'काठमाडौं', E'विराटनगर', E'पोखरा', 'D', E'नेपालका महानगरपालिकाहरूमध्ये सबैभन्दा धेरै वडा **पोखरा महानगरपालिकामा (३३ वटा)** रहेका छन्।\n- भरतपुर महानगरपालिकामा २९ वटा वडाहरू छन्।\n- काठमाडौं र वीरगञ्ज महानगरपालिकामा ३२/३२ वटा वडाहरू छन्।\n- विराटनगर महानगरपालिकामा १९ वटा वडाहरू छन्।\nनोट: नेपालमा हाल ६ वटा महानगरपालिकाहरू छन्: काठमाडौं, ललितपुर, पोखरा, भरतपुर, वीरगञ्ज र विराटनगर।', 'nepali'),
      (v_set_id, 7, E'सगरमाथालाई माउन्ट एभरेष्ट भनि नामाकरण कहिले गरियो?', E'सन् १८५५', E'सन् १८६५', E'सन् १८७५', E'सन् १८८५', 'B', E'सगरमाथालाई **सन् १८६५** मा ''माउन्ट एभरेष्ट'' भनी नामाकरण गरिएको थियो।\nनोट: यो नामकरण तत्कालीन ब्रिटिस सर्भेयर जनरल सर जर्ज एभरेष्टको सम्मानमा गरिएको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपालको इतिहासको पहिलो रक्षा मन्त्री को हुन्?', E'बबर शमशेर', E'चुडा शमशेर', E'नृपजङ्ग राणा', E'भद्रकाली मिश्र', 'A', E'नेपालको इतिहासको पहिलो रक्षा मन्त्री **बबर शमशेर** हुन्।\n- चुडा शमशेर नेपालको पहिलो वन मन्त्री थिए।\n- नृपजङ्ग राणा नेपालको पहिलो शिक्षा मन्त्री थिए।\n- भद्रकाली मिश्र नेपालको पहिलो यातायात मन्त्री थिए।\nनोट: यो मन्त्रीमण्डल वि.सं. २००७ साल फागुन ७ गते गठन भएको थियो।', 'nepali'),
      (v_set_id, 9, E'अफ्रिका कप अफ नेसन्स, २०२६ को उपाधि कुन मुलुकले प्राप्त गरेको छ?', E'सेनेगल', E'मोरक्को', E'सुडान', E'कंगो', 'B', E'**मोरक्कोले** अफ्रिका कप अफ नेसन्स, २०२६ को उपाधि प्राप्त गरेको छ।\nनोट: यो प्रतियोगिता डिसेम्बर २०२५ देखि जनवरी २०२६ सम्म मोरक्कोमा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 10, E'नेपालको राष्ट्रिय खेलाडी मञ्जु तुलाधर श्रेष्ठको निधन कहिले भएको छ?', E'२०८२ माघ ३', E'२०८२ माघ ४', E'२०८२ माघ ५', E'२०८२ माघ ६', 'C', E'नेपालकी राष्ट्रिय तेक्वान्दो खेलाडी मञ्जु तुलाधर श्रेष्ठको निधन **वि.सं. २०८२ माघ ५** गते भएको हो।\nनोट: उनले सन् १९९९ मा नेपालमा भएको आठौं दक्षिण एसियाली खेलकुद (साग) मा रजत पदक जितेकी थिइन्।', 'nepali'),
      (v_set_id, 11, E'''म्याग्नाकार्टा''मा कहिले हस्ताक्षर गरेका भयो?', E'१२१५ जुन १५', E'१२१५ जुलाई १५', E'१२१५ जुन १२', E'१२१५ जुलाई १२', 'A', E'म्याग्नाकार्टामा **सन् १२१५ जुन १५** मा हस्ताक्षर भएको थियो। यो बेलायतको एक ऐतिहासिक अधिकार पत्र हो जसमा राजा जोन द्वितीयले हस्ताक्षर गरेका थिए।\nनोट: पछि राजा हेनरी तृतीयले यसलाई संशोधन गरेका थिए।', 'nepali'),
      (v_set_id, 12, E'प्रथम पटक सतिप्रथाको बारेमा उल्लेख भएको धार्मिक ग्रन्थ कुन हो?', E'रामायण', E'उपनिषद्', E'विष्णुधर्म शुत्र', E'महाभारत', 'C', E'सतिप्रथाको बारेमा पहिलो पटक उल्लेख भएको धार्मिक ग्रन्थ **विष्णुधर्म शुत्र** हो।\nनोट: नेपालमा सतिप्रथामा आधारित भएर ''झोला'' नामक चलचित्र पनि निर्माण भएको छ।', 'nepali'),
      (v_set_id, 13, E'''टीका vaccine'' पत्ता लगाउने वैज्ञानिक को हुन्?', E'थोमस अल्वा एडिसन', E'सर आइज्याक न्यूटन', E'ग्यालिलियो ग्यालिली', E'लुई पाश्चर', 'D', E'**लुई पाश्चर** रेबिज विरुद्धको पहिलो ''टीका'' (Vaccine) पत्ता लगाउने वैज्ञानिक हुन्।\n- थोमस अल्वा एडिसनले बिजुली बत्तीको आविष्कार गरेका थिए।\n- सर आइज्याक न्यूटन गुरुत्वाकर्षणको नियमका लागि परिचित छन्।\n- ग्यालिलियो ग्यालिलीले टेलिस्कोपको सुधार र खगोलीय अवलोकनमा महत्वपूर्ण योगदान दिएका थिए।\nनोट: लुई पाश्चरले पाश्चराइजेसन प्रक्रिया र कीटाणु सिद्धान्तको पनि विकास गरेका थिए।', 'nepali'),
      (v_set_id, 14, E'नेपालको पहिलो जनगणना १९६८ अनुसार नेपालको जनघनत्व कति थियो?', E'३८ जना प्रतिवर्ग किलोमिटर', E'३९ जना प्रतिवर्ग किलोमिटर', E'४० जना प्रतिवर्ग किलोमिटर', E'४१ जना प्रतिवर्ग किलोमिटर', 'A', E'नेपालको पहिलो जनगणना वि.सं. १९६८ अनुसार नेपालको जनघनत्व **३८ जना प्रतिवर्ग किलोमिटर** थियो।\nनोट: उक्त जनगणना अनुसार नेपालको कुल जनसंख्या ५६,३८,७४९ रहेको थियो।', 'nepali'),
      (v_set_id, 15, E'देहायका मध्ये कुन आसियानको सदस्य हैन?', E'भियतनाम', E'ब्रुनाइ', E'ताइवान', E'कम्बोडिया', 'C', E'**ताइवान** दक्षिण पूर्वी एसियाली राष्ट्रहरूको संगठन (आसियान) को सदस्य राष्ट्र होइन।\n- भियतनाम, ब्रुनाइ र कम्बोडिया आसियानका सदस्य राष्ट्रहरू हुन्।\nनोट: आसियानमा इन्डोनेसिया, मलेसिया, फिलिपिन्स, सिंगापुर, थाइल्याण्ड, ब्रुनाइ, भियतनाम, म्यानमार, लाओस, कम्बोडिया र पूर्वी टिमोर गरी ११ सदस्य राष्ट्रहरू छन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/०९', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_10.csv  →  आसमान दैनिक GK — २०८२/१२/१०  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालमा सर्वप्रथम बजेट कुन प्रधानमन्त्रीको पालादेखि आएको थियो?', E'वि पि कोइराला', E'सुवर्ण सम्सेर', E'मातृका प्र. कोइराला', E'टंक प्रसाद आचार्य', 'C', E'नेपालमा सर्वप्रथम बजेट **मातृका प्रसाद कोइराला**को पालामा आएको थियो।\nवि.सं. २००८ साल माघ २१ गते तत्कालीन अर्थमन्त्री सुवर्ण शमशेरले पहिलो बजेट प्रस्तुत गरेका थिए।', 'nepali'),
      (v_set_id, 2, E'अर्थोडक्स कुन खेतीसँग सम्बन्धित रहेको छ?', E'चिया', E'कफि', E'धान', E'अलैंची', 'A', E'**अर्थोडक्स चिया खेतीसँग** सम्बन्धित एक प्रकार हो।\n- कफी एक लोकप्रिय पेय पदार्थ तथा नगदे बाली हो।\n- धान नेपालको प्रमुख खाद्यान्न बाली हो।\n- अलैंची एक महत्त्वपूर्ण मसला बाली हो, जसलाई ''कालो सुन'' पनि भनिन्छ।\nनोट: नेपालको पहाडी क्षेत्रमा हुने चिया खेतीलाई अर्थोडक्स भनिन्छ भने तराईमा हुनेलाई CTC (Crush, Tear, Curl) भनिन्छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधानको कुन धारामा सञ्चारको हक सम्बन्धित व्यवस्था गरेको छ?', E'धारा ३१', E'धारा २७', E'धारा १९', E'धारा २४', 'C', E'नेपालको संविधानको **धारा १९** मा सञ्चारको हक सम्बन्धी व्यवस्था छ।\n- धारा ३१ मा शिक्षा सम्बन्धी हकको व्यवस्था गरिएको छ।\n- धारा २७ मा सूचनाको हकको व्यवस्था छ।\n- धारा २४ मा छुवाछुत तथा भेदभाव विरुद्धको हकको व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 4, E'सौर्यमण्डलको गहनाको रुपमा कुन ग्रहलाई चिनिन्छ?', E'बृहस्पति', E'शुक्र', E'पृथ्वी', E'शनि', 'D', E'**शनि ग्रहलाई** सौर्यमण्डलको गहनाको रुपमा चिनिन्छ।\n- बृहस्पति सौर्यमण्डलको सबैभन्दा ठूलो ग्रह हो।\n- शुक्र ग्रहलाई ''Morning Star'' र ''Evening Star'' पनि भनिन्छ।\n- पृथ्वीलाई ''नीलो ग्रह'' (Blue Marble) भनिन्छ र यो जीवन भएको एकमात्र ज्ञात ग्रह हो।\nनोट: यसको वरिपरि रहेका सुन्दर रिङ्ग (वलय) हरूका कारण यसलाई यो उपनाम दिइएको हो।', 'nepali'),
      (v_set_id, 5, E'संसारको सबैभन्दा अग्लो भवन बुर्ज खलिफा कुन एसियाली मुलुकमा रहेको छ?', E'कतार', E'युएई', E'साउदी अरेबिया', E'चीन', 'B', E'संसारको सबैभन्दा अग्लो भवन बुर्ज खलिफा **युएई (संयुक्त अरब इमिरेट्स)** को दुबई शहरमा रहेको छ।\nनोट: यसको उचाइ ८२८ मिटर छ।', 'nepali'),
      (v_set_id, 6, E'देहायका मध्ये सबैभन्दा धेरै महानगरपालिका भएको प्रदेश कुन हो?', E'सुदुरपश्चिम', E'बागमती', E'कोशी', E'मधेस', 'B', E'नेपालका सात प्रदेशमध्ये **बागमती प्रदेशमा** सबैभन्दा धेरै, ३ वटा महानगरपालिका रहेका छन्।\n- सुदुरपश्चिम प्रदेशमा कुनै पनि महानगरपालिका छैन।\n- कोशी प्रदेशमा १ वटा (विराटनगर) महानगरपालिका छ।\n- मधेस प्रदेशमा १ वटा (वीरगञ्ज) महानगरपालिका छ।\nनोट: नेपालमा हाल ६ वटा महानगरपालिका छन्: काठमाडौं, ललितपुर, भरतपुर (बागमती), पोखरा (गण्डकी), विराटनगर (कोशी) र वीरगञ्ज (मधेस)।', 'nepali'),
      (v_set_id, 7, E'सगरमाथा आरोहण गर्ने प्रथम विदेशी सर एडमण्ड हिलारी कुन मुलुकका नागरिक हुन?', E'बेलायत', E'न्युजिल्यान्ड', E'स्वीट्जरल्याण्ड', E'जापान', 'B', E'**सगरमाथा आरोहण गर्ने प्रथम विदेशी सर एडमण्ड हिलारी न्युजिल्यान्डका नागरिक हुन्।**\n- बेलायतका पर्वतारोही जोर्ज ब्याण्डले पहिलो पटक कञ्चनजंघा हिमालको सफल आरोहण गरेका थिए।\n- स्वीट्जरल्याण्डका पर्वतारोहीहरूले सगरमाथा आरोहणका लागि प्रारम्भिक प्रयासहरू गरेका थिए।\n- जापानकी जुन्को ताबेई सगरमाथा आरोहण गर्ने विश्वकी पहिलो महिला हुन्।\nनोट: सर एडमण्ड हिलारी र नेपालका तेन्जिङ नोर्गे शेर्पाले सन् १९५३ मे २९ मा संयुक्त रूपमा पहिलो पटक सगरमाथाको सफल आरोहण गरेका थिए।', 'nepali'),
      (v_set_id, 8, E'नेपालमा गठित पहिलो मन्त्रीमण्डलमा देहायका मध्ये कुन मन्त्री राणा पक्षिय मन्त्री हैनन्?', E'यज्ञबहादुर बस्नेत', E'मोहन समसेर', E'बबर समसेर', E'सुवर्ण समसेर', 'D', E'नेपालको पहिलो मन्त्रीमण्डलमा **सुवर्ण समसेर** राणा थरका भए तापनि नेपाली काँग्रेसको पक्षबाट मन्त्री बनेका थिए, राणा पक्षबाट होइन।\n- यज्ञबहादुर बस्नेत राणा थरका नभए पनि राणा पक्षबाट स्वास्थ्य मन्त्री बनेका थिए।\n- मोहन समसेर सो मन्त्रीमण्डलका प्रधानमन्त्री थिए र राणा पक्षको नेतृत्व गरेका थिए।\n- बबर समसेर राणा पक्षबाट रक्षा मन्त्री थिए।\nनोट: २००७ सालमा गठित पहिलो मन्त्रीमण्डलमा ५ जना राणा पक्षबाट र ५ जना काँग्रेस पक्षबाट मन्त्री बनाइएको थियो।', 'nepali'),
      (v_set_id, 9, E'युरोपेली संघको आधिकारिक मुद्रा युरो बनाउने पछिल्लो मुलुक कुन हो?', E'क्रोएसिया', E'डेनमार्क', E'रोमानिया', E'बुल्गेरिया', 'D', E'युरोपेली संघको आधिकारिक मुद्रा युरो बनाउने पछिल्लो मुलुक **बुल्गेरिया** हो।\n- बुल्गेरिया युरो अपनाउने २१औं सदस्य राष्ट्र बनेको छ। यसअघि २०औं सदस्यको रूपमा क्रोएसियाले सन् २०२३ जनवरी १ मा युरो अपनाएको थियो।', 'nepali'),
      (v_set_id, 10, E'काठमाडौं महानगरपालिकाको कार्यवाहक प्रमुखका रुपमा सुनिता डंगोलले कहिले जिम्मेवारी पाइन् ?', E'२०८२ माघ ३', E'२०८२ माघ ४', E'२०८२ माघ ५', E'२०८२ माघ ६', 'B', E'काठमाडौं महानगरपालिकाको उपमेयर सुनिता डंगोलले **२०८२ माघ ४ गते** कार्यवाहक प्रमुखको जिम्मेवारी पाएकी थिइन्।\nनोट: तत्कालीन मेयर बालेन्द्र शाहले राजीनामा दिएपछि उपमेयर डंगोलले कार्यवाहक प्रमुखको जिम्मेवारी सम्हालेकी हुन्।', 'nepali'),
      (v_set_id, 11, E'राजतन्त्रकाल, गणतन्त्रकाल र साम्राज्यकाल तीनवटै शासन व्यवस्था अनुभूति गरेको सभ्यता कुन हो?', E'सिन्धुघाँटीको सभ्यता', E'युनानी सभ्यता', E'मेसोपोटामिया सभ्यता', E'रोमको सभ्यता', 'D', E'**रोमको सभ्यताले** राजतन्त्रकाल, गणतन्त्रकाल र साम्राज्यकाल गरी तीनवटै शासन व्यवस्थाको अनुभूति गरेको थियो।\n- सिन्धुघाँटीको सभ्यता आफ्नो व्यवस्थित सहरी योजना र उन्नत जल निकास प्रणालीका लागि परिचित छ।\n- युनानी सभ्यतालाई दर्शन, प्रजातन्त्र, र ओलम्पिक खेलको जन्मस्थलको रूपमा चिनिन्छ।\n- मेसोपोटामिया सभ्यतालाई विश्वको पहिलो लेखन प्रणाली (क्युनिफर्म) र कानून (हम्मुराबीको कोड) को विकासको श्रेय दिइन्छ।\nनोट: रोमको सभ्यतालाई ७५३ ई.पू. देखि सन् ४७६ सम्मको अवधिमा तीन चरणमा विभाजन गरिएको छ।', 'nepali'),
      (v_set_id, 12, E'घोडाभेडा प्रथा नेपालको कुन जिल्लामा प्रचलित रहेको छ?', E'बैतडी', E'डोल्पा', E'मुगु', E'अछाम', 'C', E'घोडाभेडा प्रथा **मुगु जिल्लामा** प्रचलित छ।\n- बैतडी जिल्लामा देउकी प्रथा प्रचलित छ।\n- डोल्पा जिल्लामा खुल्ला प्रथा प्रचलित छ।\n- अछाम जिल्ला छाउपडी प्रथाको केन्द्रको रुपमा चिनिन्छ।\nनोट: लेनदेन, जारी, कुटपिट जस्ता विवादमा दुवै पक्षलाई मिलाएर मध्यस्थकर्तालाई भेडा काटेर खुवाउने र घोडामा चढाएर पठाउने प्रथालाई घोडाभेडा प्रथा भनिन्छ।', 'nepali'),
      (v_set_id, 13, E'लुई पाश्चर कहाँको वैज्ञानिक हुन्?', E'अमेरिका', E'जर्मनी', E'फ्रान्स', E'बेलायत', 'C', E'लुई पाश्चर **फ्रान्सका** वैज्ञानिक हुन्। उनको जन्म सन् १८२२ डिसेम्बर २७ मा र मृत्यु सन् १८९५ सेप्टेम्बर २८ मा भएको थियो।', 'nepali'),
      (v_set_id, 14, E'हालसम्ममा नेपालमा भएका जनगणना मध्ये सबैभन्दा धेरै जनसंख्या वृद्धिदर भएको जनगणना कुन हो?', E'२०३८ सालको', E'२०८० सालको', E'२०६८ सालको', E'२०७८ सालको', 'A', E'नेपालमा हालसम्म भएका जनगणनामध्ये सबैभन्दा धेरै जनसंख्या वृद्धिदर **वि.सं. २०३८** को जनगणनामा भएको थियो, जतिबेला वृद्धिदर २.६२ प्रतिशत थियो।\nनोट: वि.सं. २०७८ को जनगणना अनुसार नेपालको जनसंख्या वृद्धिदर ०.९२ प्रतिशत रहेको छ।', 'nepali'),
      (v_set_id, 15, E'दक्षिणपूर्व एशियाली राष्ट्रहरूको संगठन का राष्ट्रहरू मध्ये ठूलो राष्ट्र कुन हो?', E'फिलिपिन्स', E'इण्डोनेसिया', E'थाइल्याण्ड', E'मलेसिया', 'B', E'दक्षिणपूर्व एशियाली राष्ट्रहरूको संगठन (आसियान) मा जनसंख्या र क्षेत्रफल दुवैको आधारमा सबैभन्दा ठूलो राष्ट्र **इण्डोनेसिया** हो।\nनोट: जनसंख्याको आधारमा सबैभन्दा सानो आसियान मुलुक ब्रुनाई हो भने क्षेत्रफलको आधारमा सबैभन्दा सानो सिंगापुर हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१०', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_12.csv  →  आसमान दैनिक GK — २०८२/१२/१२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'पछिल्लो तथ्यांक, २०२६ अनुसार बाघ संख्याको आधारमा कुन क्रम सहि रहेको छ ?', E'भारत, इन्डोनेसिया, रसिया, नेपाल', E'भारत, नेपाल, रसिया, इन्डोनेसिया', E'भारत, रसिया, इन्डोनेसिया, नेपाल', E'भारत, रसिया, नेपाल, इन्डोनेसिया', 'C', E'पछिल्लो तथ्यांक, २०२६ अनुसार बाघ संख्याको आधारमा सही क्रम **भारत, रसिया, इन्डोनेसिया, नेपाल** रहेको छ।\nयो तथ्यांक अनुसार भारतमा ३,१६७, रसियामा ७५०, इन्डोनेसियामा ४०० र नेपालमा ३५५ बाघ रहेका छन्, जसले नेपाललाई चौथो स्थानमा राख्छ।', 'nepali'),
      (v_set_id, 2, E'२०२६ को नबिनतम तथ्यांक अनुसार नेपाल जनसंख्याको हिसाबले हाल विश्वको कति औं स्थानमा रहेको छ ?', E'५१ औं', E'५२ औं', E'५३ औं', E'५४ औं', 'B', E'२०२६ को नवीनतम तथ्यांक अनुसार नेपाल जनसंख्याको हिसाबले विश्वमा **५२ औं** स्थानमा रहेको छ।\nनोट: विश्वमा सबैभन्दा धेरै जनसंख्या भएको देश भारत हो भने सबैभन्दा कम जनसंख्या भएको देश भ्याटिकन सिटी हो।', 'nepali'),
      (v_set_id, 3, E'अन्तर्राष्ट्रिय जातीय उत्पीडन दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'मार्च २१', E'मार्च २२', E'मार्च २३', E'मार्च २४', 'A', E'अन्तर्राष्ट्रिय जातीय उत्पीडन दिवस प्रत्येक वर्ष **मार्च २१** मा मनाइन्छ। सन् १९६० मार्च २१ मा दक्षिण अफ्रिकाको सार्पभिलमा रंगभेद विरुद्ध भएको शान्तिपूर्ण प्रदर्शनमा ६९ जनाको हत्या भएको घटनाको स्मरणमा यो दिवस मनाउन सुरु गरिएको हो।\nनोट: यो दिवस सन् १९६७ देखि मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 4, E'महिला एसियन कप फुटबल, २०२६ को उपाधि कुन मुलुकले प्राप्त गरेको छ ?', E'चीन', E'बंगलादेश', E'भारत', E'जापान', 'D', E'सन् २०२६ को महिला एसियन कप फुटबलको उपाधि **जापानले** जितेको थियो। अस्ट्रेलियामा आयोजित उक्त प्रतियोगिताको फाइनलमा जापानले आयोजक अस्ट्रेलियालाई १-० गोल अन्तरले पराजित गरेको थियो।\nनोट: यस प्रतियोगितामा चीन, बंगलादेश र भारत लगायत कुल १२ टोलीहरू सहभागी थिए।', 'nepali'),
      (v_set_id, 5, E'विश्व खुशी सूचकांक, २०२६ मा नेपाल कति औं स्थानमा रहेको छ?', E'९२ औं', E'९७ औं', E'९४ औं', E'९९ औं', 'D', E'विश्व खुशी सूचकांक, २०२६ मा नेपाल **९९ औं** स्थानमा रहेको छ। सन् २०२५ मा नेपाल यस सूचकांकमा ९२ औं स्थानमा थियो।\nनोट: यो सूचकांक अनुसार, २०२६ मा विश्वको सबैभन्दा खुशी देश फिनल्याण्ड हो भने सबैभन्दा दुःखी देश अफगानिस्तान हो।', 'nepali'),
      (v_set_id, 6, E'सन् २०२६ को आतंकवादी गतिविधि सूची अनुसार नेपाल कति औं स्थानमा रहेको छ ?', E'८६ औं', E'८७ औं', E'८८ औं', E'८९ औं', 'D', E'सन् २०२६ को विश्व आतंकवाद सूचकांक अनुसार नेपाल **८९ औं** स्थानमा रहेको छ। यो रिपोर्ट Institute for Economics and Peace द्वारा प्रकाशित गरिएको हो।\nनोट: यस सूचीमा पाकिस्तान शीर्ष स्थानमा रहेको छ भने भारत १३ औं स्थानमा छ।', 'nepali'),
      (v_set_id, 7, E'विश्व मौसम विज्ञान दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'मार्च २१', E'मार्च २२', E'मार्च २३', E'मार्च २४', 'C', E'**विश्व मौसम विज्ञान दिवस प्रत्येक वर्ष मार्च २३ मा मनाइन्छ।**\n- मार्च २१ मा अन्तर्राष्ट्रिय वन दिवस मनाइन्छ।\n- मार्च २२ मा विश्व पानी दिवस मनाइन्छ।\n- मार्च २४ मा विश्व क्षयरोग दिवस मनाइन्छ।\nनोट: सन् १९५० मार्च २३ मा विश्व मौसम विज्ञान संगठन (WMO) को स्थापना भएको सम्झनामा यो दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 8, E'प्रतिनिधि सभा निर्वाचन, २०८२ को जम्मा २७५ सदस्य मध्ये सबैभन्दा जेष्ठ सांसदको हुन् ?', E'अनुष्का श्रेष्ठ', E'अर्जुन नरसिंह केसी', E'महावीर पुन', E'भूमिका श्रेष्ठ', 'B', E'**प्रतिनिधि सभा निर्वाचन, २०८२ मा सबैभन्दा जेष्ठ सांसद नेपाली कांग्रेसका अर्जुन नरसिंह केसी हुन्।**\n- अनुष्का श्रेष्ठ संघीय संसदमा निर्वाचित हुने पहिलो मिस नेपाल हुन्।\n- महावीर पुन म्याग्दी-१ बाट निर्वाचित एकमात्र स्वतन्त्र सांसद हुन्।\n- भूमिका श्रेष्ठ नेपालकै पहिलो पारलैंगिक (ट्रान्सजेन्डर) महिला सांसद हुन्।\nनोट: अर्जुन नरसिंह केसी ७८ वर्षको उमेरमा जेष्ठ सांसद बनेका हुन्।', 'nepali'),
      (v_set_id, 9, E'सन् २०२६ को ब्रिक्स (BRICS) शिखर सम्मेलन को अध्यक्षता कुन देशले गरिरहेको छ ?', E'चीन', E'भारत', E'ब्राजिल', E'जापान', 'B', E'सन् २०२६ को १८ औं ब्रिक्स (BRICS) शिखर सम्मेलनको अध्यक्षता **भारतले** गरिरहेको छ। भारतले १ जनवरी २०२६ देखि ब्राजिलबाट यो जिम्मेवारी औपचारिक रूपमा सम्हालेको हो।', 'nepali'),
      (v_set_id, 10, E'नेपाल बहुसूचक सर्वेक्षण २०२४/२५ अनुसार नेपालका कति घरधुरीमा खाना पकाउन दाउराको प्रयोग हुने गरेको छ ?', E'५३.६ प्रतिशत', E'५५.६ प्रतिशत', E'५७.६ प्रतिशत', E'५९.६ प्रतिशत', 'A', E'नेपाल बहुसूचक सर्वेक्षण २०२४/२५ अनुसार नेपालका **५३.६ प्रतिशत** घरधुरीमा खाना पकाउन दाउराको प्रयोग हुने गरेको छ।\nनोट: दाउरापछि सबैभन्दा धेरै, ४१.९ प्रतिशत घरधुरीमा खाना पकाउन एलपिजी ग्यासको प्रयोग हुने गरेको सर्वेक्षणले देखाएको छ।', 'nepali'),
      (v_set_id, 11, E'नेपालको टेस्ट म्याचको उपनामले चिनिने नेपालको घरेलु क्रिकेट प्रतियोगिता Jay Trophy 2026 को उपाधी कुन टिमले जितेको छ ?', E'नेपाल पुलिस क्लब', E'त्रिभुवन आर्मी क्लब', E'सशस्त्र प्रहरी बल क्लब', E'बागमती प्रदेश क्रिकेट टिम', 'A', E'**नेपाल पुलिस क्लबले** Jay Trophy 2026 को उपाधि जितेको छ।\n- त्रिभुवन आर्मी क्लब फाइनलमा नेपाल पुलिस क्लबसँग ४ विकेटले पराजित भई उपविजेता बनेको थियो।\n- सशस्त्र प्रहरी बल क्लब र बागमती प्रदेश क्रिकेट टिम प्रतियोगिताका अन्य सहभागी टोलीहरू थिए।\nनोट: नेपाल पुलिस क्लबले लगातार दोस्रो वर्ष जय ट्रफी कप क्रिकेटको उपाधि जितेको हो।', 'nepali'),
      (v_set_id, 12, E'हेन्ले ग्लोबल पासपोर्ट इन्डेक्स, २०२६ अनुसार नेपाल कति औं स्थानमा रहेको छ ?', E'९५औं', E'९६औं', E'९७औं', E'९८औं', 'B', E'हेन्ले एण्ड पार्टनर्सद्वारा सन् २०२६ जनवरी ९ मा प्रकाशित हेन्ले ग्लोबल पासपोर्ट इन्डेक्स अनुसार नेपाल **९६औं** स्थानमा रहेको छ।\nनोट: यस सूचकांकमा सिंगापुर पहिलो स्थानमा र अफगानिस्तान अन्तिम स्थानमा रहेका छन्।', 'nepali'),
      (v_set_id, 13, E'९८ औं ओस्कार अवार्ड, २०२६ का लागि नेपालबाट सिफारिस भएको फिल्म कुन हो?', E'डिग्री माइला', E'एग्जिला', E'शाम्भला', E'पुर्ण बहादुरको सारंगी', 'B', E'९८ औं ओस्कार अवार्ड, २०२६ का लागि नेपालबाट **एग्जिला** फिल्म सिफारिस भएको छ।\n- शाम्भला चलचित्र ९७ औं ओस्कार अवार्डका लागि छनोट भएको थियो।\nनोट: मिलन चाम्सद्वारा निर्देशित चलचित्र एग्जिला राष्ट्रिय महिला फुटबल खेलाडी एन्जिला तुम्बापो सुब्बाको वास्तविक जीवनकथामा आधारित रहेको छ।', 'nepali'),
      (v_set_id, 14, E'संयुक्त राष्ट्रसंघले घोषणा गरेको दिगो विकास लक्ष्यका १७ युवा नेता (सन् २०२४ का लागि) मा पर्न सफल नेपाली अभियन्ता को हुन् ?', E'एन्जल लामा', E'ऐश्वर्या श्रेष्ठ', E'विनायक कसौधन', E'कन्चन अमात्य', 'B', E'संयुक्त राष्ट्रसंघले घोषणा गरेको दिगो विकास लक्ष्यका १७ युवा नेता (सन् २०२४ का लागि) मा पर्न सफल नेपाली अभियन्ता **ऐश्वर्या श्रेष्ठ** हुन्।', 'nepali'),
      (v_set_id, 15, E'सन् २०२६ मा आयोजना हुने आईसीसी महिला टी-२० विश्वकप (ICC Women''s T-20 World Cup) कुन देशमा हुँदैछ ?', E'बंगलादेश र भारत', E'इंग्ल्याण्ड र वेल्स', E'अफगानिस्तान र बंगलादेश', E'भारत र श्रीलंका', 'B', E'सन् २०२६ मा आयोजना हुने आईसीसी महिला टी-२० विश्वकप **इंग्ल्याण्ड र वेल्समा** हुँदैछ।\nनोट: यो १०औं संस्करणको महिला टी-२० विश्वकप हो, जसमा १२ मुलुक सहभागी हुनेछन् र कुल ३३ खेल खेलिनेछ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१२', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_13.csv  →  आसमान दैनिक GK — २०८२/१२/१३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको बजेट इतिहासमा कुन आर्थिक वर्षमा बचत बजेट (Surplus budget) को सिद्धान्तमा रहेर बजेट प्रस्तुत गरिएको थियो?', E'आ.व. २०७७/७८', E'आ.व. २०१९/२०', E'आ.व. २०२६/२७', E'आ.व. २०३३/३४', 'D', E'नेपालको बजेट इतिहासमा आर्थिक वर्ष **२०३३/३४** मा बचत बजेट (Surplus budget) को सिद्धान्तमा रहेर बजेट प्रस्तुत गरिएको थियो।\nनोट: सामान्यतया नेपालले घाटा बजेट (Deficit budget) प्रस्तुत गर्ने गर्दछ।', 'nepali'),
      (v_set_id, 2, E'हरेक वर्ष मंसिर १ मा मनाउँदै आइरहेको कफि दिवस कुन सालबाट मनाउन सुरु गरिएको हो?', E'वि.सं. २०६२', E'वि.सं. २०५३', E'वि.सं. २०५४', E'वि.सं. २०६१', 'A', E'हरेक वर्ष मंसिर १ मा मनाइने राष्ट्रिय कफी दिवस **वि.सं. २०६२** देखि मनाउन सुरु गरिएको हो।\n- वि.सं. २०५४ देखि वैशाख १५ मा राष्ट्रिय चिया दिवस मनाउन थालिएको हो।\n- वि.सं. २०६१ देखि असार १५ मा राष्ट्रिय धान दिवस मनाउन सुरु गरिएको हो।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधानको कुन धारामा सम्पत्तिको हक सम्बन्धित व्यवस्था गरेको छ?', E'धारा २१', E'धारा २२', E'धारा २३', E'धारा २५', 'D', E'नेपालको संविधानको **धारा २५** मा सम्पत्तिको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा २१ मा अपराध पीडितको हकको व्यवस्था छ।\n- धारा २२ मा यातना विरुद्धको हकको व्यवस्था छ।\n- धारा २३ मा निवारक नजरबन्द विरुद्धको हकको व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 4, E'सौर्यमण्डलको कुन ग्रहलाई कनिष्ठ ग्रहको उपनामले समेत चिनिन्छ?', E'शुक्र ग्रह', E'बुध ग्रह', E'पृथ्वी ग्रह', E'शनि ग्रह', 'B', E'**बुध ग्रहलाई** कनिष्ठ ग्रहको उपनामले चिनिन्छ।\n- शुक्र ग्रहलाई ''Morning Star'' र ''Evening Star'' उपनामले चिनिन्छ।\n- पृथ्वीलाई ''नीलो ग्रह'' (Blue Planet) भनिन्छ।\n- शनि ग्रहलाई ''छल्ला भएको ग्रह'' (Ringed Planet) भनेर चिनिन्छ।\nनोट: बुध ग्रहको कुनै उपग्रह र वायुमण्डल नभएकाले यसलाई कनिष्ठ ग्रह भनिएको हो।', 'nepali'),
      (v_set_id, 5, E'संसारको सबैभन्दा अग्लो मूर्ति कुन एसियाली मुलुकमा रहेको छ?', E'भारत', E'युएई', E'चीन', E'सिंगापुर', 'A', E'संसारको सबैभन्दा अग्लो मूर्ति ''स्ट्याचु अफ युनिटी'' **भारत**को गुजरात राज्यमा रहेको छ। यो मूर्ति नर्मदा नदीको किनारमा अवस्थित छ र यसको उचाइ १८२ मिटर छ।\nनोट: यो विशाल मूर्ति भारतका प्रथम उपप्रधानमन्त्री तथा गृहमन्त्री सरदार वल्लभभाइ पटेलको हो।', 'nepali'),
      (v_set_id, 6, E'नोबेल शान्ति पुरस्कार, २०२४ विजेता भेनेजुएलाकी कोरिना मचाडोले आफूले पाएको पदक कुन राजनीतिज्ञलाई प्रदान गरेकी हुन् ?', E'भ्लादिमिर जेलेनेस्की', E'निकोलस मादुरो', E'एलान मस्क', E'डोनाल्ड ट्रम्प', 'D', E'भेनेजुएलाकी कोरिना मचाडोले २०२४ को नोबेल शान्ति पुरस्कारको पदक **डोनाल्ड ट्रम्प**लाई प्रदान गरेकी हुन्।\n- भ्लादिमिर जेलेनेस्की युक्रेनका राष्ट्रपति हुन्।\n- निकोलस मादुरो भेनेजुएलाका राष्ट्रपति हुन्।\n- एलान मस्क टेस्ला र स्पेसएक्सका प्रमुख कार्यकारी अधिकृत हुन्।\nनोट: उनले २०२४ जनवरी १६ मा उक्त पदक हस्तान्तरण गरेकी थिइन्।', 'nepali'),
      (v_set_id, 7, E'कुष्ठरोग दिवस (World Leprosy Day) प्रत्येक वर्ष कुन महिनाको अन्तिम आइतबार मनाइन्छ ?', E'जनवरी', E'डिसेम्बर', E'मार्च', E'अप्रिल', 'A', E'विश्व कुष्ठरोग दिवस हरेक वर्ष **जनवरी** महिनाको अन्तिम आइतबार मनाइन्छ। यो दिवस सन् १९५४ देखि मनाउन सुरु गरिएको हो।\nनोट: सन् २०२६ को नारा ''Leprosy is Curable, the real challenge is stigma'' (कुष्ठरोग निको हुन्छ, वास्तविक चुनौती कलंक हो) रहेको थियो।', 'nepali'),
      (v_set_id, 8, E'बाग्मती प्रदेशमा उपमहानगरपालिकाको संख्या कति रहेको छ?', E'१ वटा', E'२ वटा', E'३ वटा', E'४ वटा', 'A', E'बाग्मती प्रदेशमा **१ वटा** उपमहानगरपालिका (हेटौंडा) रहेको छ। नेपालमा कुल ११ उपमहानगरपालिकाहरू छन्, जसमध्ये सबैभन्दा धेरै लुम्बिनी प्रदेशमा ४ वटा र सबैभन्दा कम बाग्मती र सुदूरपश्चिम प्रदेशमा १/१ वटा रहेका छन्।', 'nepali'),
      (v_set_id, 9, E'६ चुलीको हिमालको उपनामले नेपालको कुन हिमाललाई चिनिन्छ?', E'कन्चनजंघा', E'सगरमाथा', E'धौलागिरी', E'मकालु', 'C', E'**धौलागिरी हिमाल**लाई ६ चुलीको हिमाल र सेतो हिमालको उपनामले चिनिन्छ।\n- कन्चनजंघा हिमाललाई पाँचौं चुली र नेपाल पिक भनिन्छ।\n- सगरमाथालाई पन्ध्रौं चुली, संसारको आमा, र तेस्रो ध्रुव जस्ता उपनामले चिनिन्छ।\n- मकालु हिमाललाई जन्जु हिमाल र उच्च कालो हिमाल पनि भनिन्छ।', 'nepali'),
      (v_set_id, 10, E'नेपालमा गठित पहिलो मन्त्रीमण्डलमा "गणेशमान सिंह" ले कुन मन्त्रालयको जिम्मा पाएका थिए?', E'स्वास्थ्य तथा स्थानीय मन्त्री', E'उद्योग वाणिज्य मन्त्री', E'खाद्य तथा कृषि मन्त्री', E'गृह तथा कानून मन्त्री', 'B', E'वि.सं. २००७ साल फागुन ७ मा गठित नेपालको पहिलो मन्त्रीमण्डलमा गणेशमान सिंहले **उद्योग वाणिज्य मन्त्री**को जिम्मा पाएका थिए।\n- यज्ञबहादुर बस्नेत स्वास्थ्य मन्त्री थिए।\n- भरतमणि शर्मा खाद्य र कृषि मन्त्री थिए।\n- विश्वेश्वरप्रसाद कोइराला गृह मन्त्री थिए।\nनोट: उक्त मन्त्रीमण्डल मोहनशमशेर ज.ब.रा.को प्रधानमन्त्रीत्वमा गठन भएको थियो।', 'nepali'),
      (v_set_id, 11, E'विश्वको मानव अधिकारसँग सम्बन्धित प्रथम लिखित दस्तावेज म्याग्नाकार्टा कतिवटा कानुनको संग्रह हो?', E'३७ वटा', E'३९ वटा', E'६१ वटा', E'६३ वटा', 'D', E'विश्वको मानव अधिकारसँग सम्बन्धित प्रथम लिखित दस्तावेज, म्याग्नाकार्टा, **६३ वटा** कानुनको संग्रह हो।\nनोट: म्याग्नाकार्टा ल्याटिन भाषामा लेखिएको थियो र यसमा जम्मा ४,९२२ शब्दहरू रहेका छन्।', 'nepali'),
      (v_set_id, 12, E'कुन राणा प्रधानमन्त्रीको पालामा सति जान अनुमति लिनुपर्दथ्यो?', E'वीरशमशेर', E'चन्द्रशमशेर', E'जंग बहादुर राणा', E'जुद्ध शमशेर', 'B', E'**चन्द्रशमशेरको पालामा सति जान अनुमति लिनुपर्ने व्यवस्था थियो र पछि उनले नै यस प्रथाको अन्त्य गरेका थिए।**\n- वीरशमशेरले नेपालमा पहिलो पटक खानेपानीको व्यवस्था र वीर अस्पतालको स्थापना गरेका थिए।\n- जंग बहादुर राणाले वि.सं. १९१० को मुलुकी ऐनमार्फत सती प्रथालाई सीमित गरेका थिए।\n- जुद्ध शमशेरले १९९० सालको महाभूकम्पपछिको पुनर्निर्माण र उद्योगहरूको स्थापनामा महत्वपूर्ण भूमिका खेलेका थिए।\nनोट: चन्द्रशमशेरले वि.सं. १९७७ असार २५ मा सती प्रथाको पूर्ण रूपमा अन्त्यको घोषणा गरेका थिए।', 'nepali'),
      (v_set_id, 13, E'पानीदेखि डराउने रोग हाइड्रोफोबिया (Hydrophobia) पत्ता लगाउने वैज्ञानिक को हुन्?', E'सर आइज्याक न्युटन', E'थोमस अल्वा एडिसन', E'लुई पाश्चर', E'चार्ल्स डार्विन', 'C', E'पानीदेखि डराउने रोग हाइड्रोफोबिया (रेबिज) को खोप पत्ता लगाउने वैज्ञानिक **लुई पाश्चर** हुन्।\n- सर आइज्याक न्युटन गुरुत्वाकर्षणको नियम र गतिको तीन नियमहरूका लागि परिचित छन्।\n- थोमस अल्वा एडिसनले फोनोग्राफ र बिजुली बत्ती जस्ता महत्त्वपूर्ण आविष्कारहरू गरेका थिए।\n- चार्ल्स डार्विनले क्रमविकासको सिद्धान्त (Theory of Evolution) प्रतिपादन गरेका थिए।\nनोट: लुई पाश्चरलाई ''माइक्रोबायोलोजीका पिता'' पनि भनिन्छ र उनले पाश्चराइजेसन प्रक्रियाको विकास गरेका थिए।', 'nepali'),
      (v_set_id, 14, E'राष्ट्रिय जनगणना, २०७८ अनुसार मनाङ र मुस्ताङ पछि सबैभन्दा कम जनघनत्व भएको जिल्ला कुन हो?', E'मुगु', E'डोल्पा', E'हुम्ला', E'जुम्ला', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार मनाङ र मुस्ताङ पछि सबैभन्दा कम जनघनत्व भएको जिल्ला **डोल्पा** हो।\nकम जनघनत्व भएका ५ जिल्लाहरू र तिनीहरूको जनघनत्व (प्रति वर्ग कि.मि.) यसप्रकार छन्:\n| जिल्ला | जनघनत्व (व्यक्ति/वर्ग कि.मि.) |\n| --- | --- |\n| मनाङ | ३ |\n| मुस्ताङ | ४ |\n| डोल्पा | ५ |\n| हुम्ला | १० |\n| मुगु | १८ |', 'nepali'),
      (v_set_id, 15, E'आसियानको प्रथम शिखर सम्मेलन कहाँ भएको थियो?', E'थाइल्याण्ड', E'लाओस', E'इन्डोनेसिया', E'कम्बोडिया', 'C', E'**आसियानको प्रथम शिखर सम्मेलन इन्डोनेसियाको बालीमा भएको थियो।**\n- थाइल्याण्ड आसियानको संस्थापक सदस्य राष्ट्रहरू मध्ये एक हो।\n- लाओस सन् १९९७ मा आसियानको सदस्य बनेको थियो।\n- कम्बोडिया सन् १९९९ मा आसियानको दशौं सदस्यको रूपमा सामेल भएको थियो।\nनोट: पहिलो आसियान शिखर सम्मेलन सन् १९७६ फेब्रुअरी २३-२४ मा सम्पन्न भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_16.csv  →  आसमान दैनिक GK — २०८२/१२/१६  (9 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको पहिलो लिखित संविधान ''नेपाल सरकारको वैधानिक कानुन, २००४'' कहिले जारी भएको हो?', E'२००४ माघ १३', E'२००४ माघ १९', E'२००४ माघ १७', E'२००४ माघ १५', 'A', E'नेपालको पहिलो लिखित संविधान ''नेपाल सरकारको वैधानिक कानुन, २००४'' **वि.सं. २००४ माघ १३ गते** जारी भएको थियो। यो संविधानमा ६ भाग, ६८ धारा र १ अनुसूची रहेका थिए।\nनोट: यो संविधान २००५ वैशाख १ देखि लागू हुने भनिए तापनि पूर्ण रूपमा लागू हुन सकेन।', 'nepali'),
      (v_set_id, 2, E'औपचारिक रुपमा कार्बन बेच्ने पहिलो एसियाली मुलुक कुन बनेको छ ?', E'नेपाल', E'भारत', E'थाइल्याण्ड', E'चीन', 'A', E'**नेपाल** औपचारिक रुपमा कार्बन बेच्ने पहिलो एसियाली मुलुक बनेको छ। ''लिफ कोलिसन'' (LEAF Coalition) नामक ऐतिहासिक सम्झौतापत्रमा हस्ताक्षर गरेसँगै नेपालले कार्बन व्यापारबाट औपचारिक रुपमा लाभ लिन थालेको हो।\nनोट: यो सम्झौता अनुसार नेपालले सन् २०२२ देखि २०२६ सम्मको अवधिमा कार्बन उत्सर्जन कटौती गरी बिक्री गर्नेछ।', 'nepali'),
      (v_set_id, 3, E'विश्व भूगोलमा एसिया र अफ्रिका महादेश लाई छुट्टाउने जलसंयोजन सिमा देखाएका मध्ये कुन हो?', E'युराल सागर', E'बेरिङ सागर', E'लाल सागर', E'कपुर सागर', 'C', E'एसिया र अफ्रिका महादेशलाई छुट्टाउने जलसंयोजन सीमा **लाल सागर** हो।\n- युराल पर्वतले एसिया र युरोप महादेशलाई छुट्टाउँछ।\n- बेरिङ सागरले एसिया र उत्तरी अमेरिका महादेशलाई छुट्टाउँछ।', 'nepali'),
      (v_set_id, 4, E'नेपाल सरकारको पूर्ण स्वामित्वमा स्थापना भएको नेपालको पहिलो बैंक कुन हो ?', E'कृषि विकास बैंक', E'नेपाल राष्ट्र बैंक', E'नेपाल बैंक लिमिटेड', E'राष्ट्रिय वाणिज्य बैंक', 'D', E'नेपाल सरकारको पूर्ण स्वामित्वमा स्थापना भएको नेपालको पहिलो बैंक **राष्ट्रिय वाणिज्य बैंक** हो।\n- नेपाल राष्ट्र बैंक नेपालको केन्द्रीय बैंक हो, जसको स्थापना वि.सं. २०१३ वैशाख १४ मा भएको थियो।\n- नेपाल बैंक लिमिटेड नेपालको पहिलो वाणिज्य बैंक हो, जसको स्थापना वि.सं. १९९४ कार्तिक ३० मा भएको थियो।\nनोट: राष्ट्रिय वाणिज्य बैंकको स्थापना वि.सं. २०२२ माघ १० गते भएको थियो।', 'nepali'),
      (v_set_id, 5, E'देहाएका भिटामिनको कमीले लाग्ने रोग हरु मध्ये कुन रोग भिटामिन D को कमिले हुने गर्दछ?', E'रिकेट्स हुनु', E'स्कर्भी हुनु', E'रगत बग्ने समस्या', E'बाँझोपन हुनु', 'A', E'भिटामिन D को कमीले **रिकेट्स** नामक रोग लाग्दछ।\n- भिटामिन C को कमीले स्कर्भी रोग लाग्छ।\n- भिटामिन K को कमीले रगत बग्ने समस्या हुन्छ।\n- भिटामिन E को कमीले बाँझोपन हुन सक्छ।', 'nepali'),
      (v_set_id, 6, E'विश्व सम्पदा सुचीमा सुचिकृत नेपालका सम्पदा मध्ये काठमाडौं उपत्यका बाहिरका सम्पदाको संख्या कति रहेको छ ?', E'४ वटा', E'२ वटा', E'३ वटा', E'१ वटा', 'C', E'विश्व सम्पदा सूचीमा सूचीकृत नेपालका १० सम्पदाहरूमध्ये काठमाडौं उपत्यका बाहिर **३ वटा** सम्पदा रहेका छन्।\nनोट: उपत्यका बाहिरका ३ सम्पदाहरू सगरमाथा राष्ट्रिय निकुञ्ज, चितवन राष्ट्रिय निकुञ्ज र लुम्बिनी क्षेत्र हुन्।', 'nepali'),
      (v_set_id, 7, E'नेपालमा हाल कति प्रकारका मानपदवी विभुषणको व्यवस्था रहेको छ ?', E'४ प्रकारका', E'३ प्रकारका', E'२ प्रकारका', E'५ प्रकारका', 'A', E'नेपालमा हाल **४ प्रकारका** मानपदवी विभूषणको व्यवस्था रहेको छ।\nनोट: ती मानपदवीहरू नेपाल रत्न, राष्ट्रगौरव, राष्ट्रदीप र जनसेवाश्री हुन्।', 'nepali'),
      (v_set_id, 8, E'शाहवंशीय राजाहरु मध्ये पृथ्विनारायण शाह पछिका प्रथम राजा को हुन ?', E'सुरेन्द्र विक्रम शाह', E'प्रतापसिंह शाह', E'राजेन्द्र विक्रम शाह', E'रणबहादुर शाह', 'B', E'पृथ्वीनारायण शाहपछिका प्रथम राजा उनका छोरा **प्रतापसिंह शाह** हुन्।\n- रणबहादुर शाह प्रतापसिंह शाहका छोरा थिए।\n- राजेन्द्र विक्रम शाह रणबहादुर शाहका नाति थिए।\n- सुरेन्द्र विक्रम शाह राजेन्द्र विक्रम शाहका छोरा थिए।\nनोट: प्रतापसिंह शाहलाई ''योग्य पिताका अयोग्य छोरा'' भनेर पनि चिनिन्छ।', 'nepali'),
      (v_set_id, 9, E'विद्युतीकरण तथ्यांक २०८२ अनुसार सबैभन्दा बढी विद्युतीकरण भएको प्रदेश कुन हो ?', E'कोशी प्रदेश', E'गण्डकी प्रदेश', E'बाग्मती प्रदेश', E'मधेस प्रदेश', 'D', E'विद्युतीकरण तथ्यांक २०८२ अनुसार, **मधेस प्रदेश** शतप्रतिशत (१००%) विद्युतीकरण भई सबैभन्दा अगाडि रहेको छ।\nनोट: यस तथ्यांक अनुसार सबैभन्दा कम विद्युतीकरण कर्णाली प्रदेशमा (७४.३८%) भएको छ भने राष्ट्रिय प्रसारण ग्रिड अझै हुम्ला जिल्लामा पुग्न सकेको छैन।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१६', 9;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_17.csv  →  आसमान दैनिक GK — २०८२/१२/१७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'झमक घिमिरेले कुन सालको मदन पुरस्कार प्राप्त गरेकी थिइन् ?', E'२०६७ सालको', E'२०६५ सालको', E'२०६६ सालको', E'२०६८ सालको', 'A', E'झमक घिमिरेले आफ्नो कृति ''जीवन काँडा कि फूल'' का लागि **वि.सं. २०६७** को मदन पुरस्कार प्राप्त गरेकी थिइन्।\nनोट: मदन पुरस्कार पाउने अन्य महिलाहरूमा पारिजात (२०२२), राधा पौडेल (२०७०) र निलम कार्की (२०७४) हुन्।', 'nepali'),
      (v_set_id, 2, E'जनमत संग्रह, २०३७ को घोषणा कहिले भयो ?', E'२०३६ जेठ १०', E'२०३७ जेठ २०', E'२०३७ जेठ १', E'२०३७ वैशाख २०', 'A', E'राजा वीरेन्द्रले शाही सन्देशमार्फत **वि.सं. २०३६ जेठ १०** गते जनमत संग्रहको घोषणा गरेका थिए।\n- वि.सं. २०३७ वैशाख २० गते जनमत संग्रह सम्पन्न भएको थियो।\n- वि.सं. २०३७ जेठ १ गते जनमत संग्रहको परिणाम घोषणा गरियो।', 'nepali'),
      (v_set_id, 3, E'सोह्रौं योजनाको अन्त्य सम्म पाँच वर्षमुनिका बालबालिकाको जन्म दर्ता कति पुर्याउने लक्ष्य रहेको छ ?', E'७० प्रतिशत', E'८० प्रतिशत', E'९० प्रतिशत', E'१०० प्रतिशत', 'D', E'सोह्रौं योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्ममा पाँच वर्षमुनिका बालबालिकाको जन्म दर्ता **१०० प्रतिशत** पुर्याउने लक्ष्य निर्धारण गरिएको छ।\nनोट: सोही योजनाले कुल विनियोजनमा खर्चको अनुपात र राष्ट्रिय परिचय-पत्र प्राप्त गर्ने नागरिकको संख्या ९० प्रतिशत पुर्याउने लक्ष्य लिएको छ।', 'nepali'),
      (v_set_id, 4, E'कोशी नदीको प्रभावित क्षेत्र पश्चिममा कुन हिमालसम्म रहेको छ ?', E'व्यास हिमाल', E'कन्चनजंघा हिमाल', E'धौलागिरी हिमाल', E'लाङटाङ हिमाल', 'D', E'कोशी नदीको जलाधार क्षेत्र पश्चिममा **लाङटाङ हिमाल** सम्म फैलिएको छ।\n- कन्चनजंघा हिमालले कोशी नदीको जलाधार क्षेत्रको पूर्वी सिमाना निर्धारण गर्दछ।\n- धौलागिरी हिमाल गण्डकी नदीको जलाधार क्षेत्रमा पर्दछ।\n- व्यास हिमाल दार्चुला जिल्लामा पर्छ र यो महाकाली नदीको जलाधार क्षेत्रसँग सम्बन्धित छ।', 'nepali'),
      (v_set_id, 5, E'सार्क राष्ट्रका देशहरु मध्ये नेपालको समय भन्दा चाँडो समय भएका २ देशहरु कुन कुन हुन् ?', E'भारत र भुटान', E'बंगलादेश र भुटान', E'बंगलादेश र भारत', E'पाकिस्तान र भुटान', 'B', E'नेपालभन्दा पूर्वमा रहेका सार्क राष्ट्रहरू **बंगलादेश र भुटानको समय नेपालको भन्दा १५ मिनेट चाँडो** छ। भौगोलिक अवस्थितिका कारण पूर्वका देशहरूको समय पश्चिमका देशहरूको भन्दा अगाडि हुन्छ।', 'nepali'),
      (v_set_id, 6, E'सिंहदरबार, नारायणहिटी दरबार कुन शैलिमा निर्माण गरिएका सम्पदा हुन् ?', E'शिखर शैली', E'युरोपेली शैली', E'मिश्रित शैली', E'प्यागोडा शैली', 'B', E'**सिंहदरबार र नारायणहिटी दरबार युरोपेली शैलीमा निर्माण गरिएका सम्पदा हुन्।** यस शैलीलाई ग्रीक शैली पनि भनिन्छ।\nनोट: लाल दरबार, केशरमहल र थापाथली दरबार पनि युरोपेली शैलीका अन्य उदाहरणहरू हुन्।', 'nepali'),
      (v_set_id, 7, E'नेपालको इतिहासमा पहिलो महिला उपसभामुख हुने व्यक्ति को हुन् ?', E'लीला श्रेष्ठ', E'सुशीला थापा', E'विद्यादेवी भण्डारी', E'ओनसरी घर्ती', 'A', E'**नेपालको इतिहासमा पहिलो महिला उपसभामुख लीला श्रेष्ठ (सुब्बा) हुन्।**\n- सुशीला थापा नेपालको पहिलो महिला मन्त्री हुन्।\n- विद्यादेवी भण्डारी नेपालको पहिलो महिला राष्ट्रपति हुन्।\n- ओनसरी घर्ती नेपालको पहिलो महिला सभामुख हुन्।\nनोट: द्वारिकादेवी ठकुरानी पहिलो महिला उपमन्त्री हुन्।', 'nepali'),
      (v_set_id, 8, E'देहायका मध्ये कुन तत्वको कारणले गर्दा बेसार पहेँलो हुने गर्दछ?', E'क्यापसाइसिन', E'मिथानोइक', E'कुरकुमिन', E'सल्फर एसिड', 'C', E'**बेसारमा पाइने कुरकुमिन नामक तत्वको कारणले गर्दा यो पहेँलो हुन्छ।**\n- क्यापसाइसिनका कारण खुर्सानी पिरो हुन्छ।\n- मिथानोइक एसिड (फर्मिक एसिड) सिन्कोमा पाइन्छ।\n- सल्फर एसिड लसुनमा पाइने तत्व हो।', 'nepali'),
      (v_set_id, 9, E'सन् २०२६ मा कति औं अन्तर्राष्ट्रिय भन्सार दिवस (International Customs Day) मनाइएको छ ?', E'७२ औं', E'७४ औं', E'७६ औं', E'७८ औं', 'B', E'**सन् २०२६ मा ७४ औं अन्तर्राष्ट्रिय भन्सार दिवस मनाइएको छ।** विश्व भन्सार संगठन (WCO) को स्थापना सन् १९५२ जनवरी २६ मा भएको सम्झनामा सन् १९५३ देखि हरेक वर्ष जनवरी २६ मा यो दिवस मनाउन थालिएको हो।\nनोट: सन् २०२६ को नारा ''Customs Protecting Security Through Vigilance and Commitment'' रहेको थियो।', 'nepali'),
      (v_set_id, 10, E'विश्वको सबैभन्दा ठुलो धर्म "इसाई" को उत्पत्ति कुन देशबाट भएको हो?', E'म्यानमार', E'इजराइल', E'पाकिस्तान', E'साउदी अरेबिया', 'B', E'**विश्वको सबैभन्दा ठूलो धर्म इसाईको उत्पत्ति इजराइलको जेरुसलमबाट भएको हो।**\n- पाकिस्तानको सिन्धुघाँटीबाट हिन्दु धर्मको विकास भएको मानिन्छ।\n- साउदी अरेबियाको मक्काबाट इस्लाम धर्मको उत्पत्ति भएको हो।\nनोट: नेपालको लुम्बिनीबाट बौद्ध धर्मको सुरुवात भएको थियो।', 'nepali'),
      (v_set_id, 11, E'सौर्यमण्डलको कुन ग्रहमा वर्ष भन्दा दिन लामो हुने गर्दछ?', E'बुध', E'शनि', E'बृहस्पति', E'शुक्र', 'D', E'**शुक्र ग्रहमा वर्षभन्दा दिन लामो हुन्छ।** शुक्र ग्रहलाई आफ्नो अक्षमा एक पटक घुम्न (एक दिन) करिब २४३ पृथ्वी दिन लाग्छ, जबकि सूर्यको परिक्रमा गर्न (एक वर्ष) करिब २२५ पृथ्वी दिन मात्र लाग्छ।', 'nepali'),
      (v_set_id, 12, E'नेपाली इतिहासमा पहिलो पञ्चवर्षीय योजना ल्याउँदा तत्कालीन प्रधानमन्त्री को थिए?', E'मातृका प्रसाद कोइराला', E'टंकप्रसाद आचार्य', E'डा के आई सिंह', E'विश्वेश्वर प्रसाद कोइराला', 'B', E'**नेपालमा पहिलो पञ्चवर्षीय योजना ल्याउँदा तत्कालीन प्रधानमन्त्री टंकप्रसाद आचार्य थिए।**\n- मातृका प्रसाद कोइरालाले वि.सं. २००८ माघ २१ मा नेपालको पहिलो बजेट प्रस्तुत गरेका थिए।\n- डा. के. आई. सिंह छोटो अवधिका लागि नेपालको प्रधानमन्त्री बनेका थिए।\n- विश्वेश्वर प्रसाद कोइराला वि.सं. २०१६ मा नेपालका प्रथम जननिर्वाचित प्रधानमन्त्री बनेका थिए।\nनोट: नेपालमा योजनाबद्ध विकासक्रमको सुरुवात वि.सं. २०१३ असोज १ गतेबाट भएको थियो।', 'nepali'),
      (v_set_id, 13, E'नेपालको दोस्रो पुरानो विश्वविद्यालय “नेपाल संस्कृत विश्वविद्यालय” कुन जिल्लामा अवस्थित छ?', E'काभ्रे', E'दाङ', E'कास्की', E'सुर्खेत', 'B', E'**नेपालको दोस्रो पुरानो विश्वविद्यालय, नेपाल संस्कृत विश्वविद्यालय, दाङ जिल्लामा अवस्थित छ।**\n- काभ्रे जिल्लामा काठमाडौं विश्वविद्यालय रहेको छ।\n- कास्की जिल्लामा पोखरा विश्वविद्यालय रहेको छ।\n- सुर्खेत जिल्लामा मध्यपश्चिमाञ्चल विश्वविद्यालय रहेको छ।\nनोट: नेपाल संस्कृत विश्वविद्यालयको स्थापना वि.सं. २०४३ मा भएको थियो भने नेपालको पहिलो विश्वविद्यालय, त्रिभुवन विश्वविद्यालय, वि.सं. २०१६ मा स्थापना भएको हो।', 'nepali'),
      (v_set_id, 14, E'प्राय चिसोको कारण लाग्ने निमोनिया रोग विरुद्ध बालबालिका लाई दिने खोपको नाम देहायका मध्ये कुन हो?', E'पि सी भी', E'डि पि टी', E'बि सि जी', E'ओ पि भि', 'A', E'**चिसोका कारण लाग्ने निमोनिया रोग विरुद्ध बालबालिकालाई दिइने खोप पि सी भी (PCV) हो।**\n- डि पि टी (DPT) खोप भ्यागुते रोग, लहरेखोकी र धनुष्टंकार विरुद्ध दिइन्छ।\n- बि सि जी (BCG) खोप क्षयरोग विरुद्ध दिइन्छ।\n- ओ पि भि (OPV) खोप पोलियो रोग विरुद्ध दिइन्छ।', 'nepali'),
      (v_set_id, 15, E'नेपालको भुगोलमा २ उपमहानगरपालिका भएको जिल्लाको संख्या कति रहेको छ?', E'३ वटा', E'६ वटा', E'५ वटा', E'४ वटा', 'A', E'नेपालमा २ वटा उपमहानगरपालिका भएका जिल्लाहरूको संख्या **३** रहेको छ।\nनोट: ती जिल्लाहरू सुनसरी, बारा र दाङ हुन्।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_18.csv  →  आसमान दैनिक GK — २०८२/१२/१८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाल र चिन बिचको प्रमुख व्यापारिक नाका मध्येको एक तिब्बतको पुरानो नाका ताक्लाकोट कुन जिल्लामा पर्दछ?', E'गोर्खा', E'रसुवा', E'दोलखा', E'बझाङ', 'D', E'तिब्बतको पुरानो व्यापारिक नाका ताक्लाकोट **बझाङ जिल्लामा** पर्दछ।\n- गोर्खा जिल्लामा लार्के भञ्ज्याङ नाका रहेको छ।\n- रसुवा जिल्लामा रसुवागढी नाका चीनसँगको प्रमुख व्यापारिक नाकाको रुपमा सञ्चालित छ।\n- दोलखा जिल्लामा दिर्घाचा र लामाबगर नाका रहेका छन्।\nनोट: नेपाल र चीन बीच १३ वटा व्यापारिक नाका रहेका छन्।', 'nepali'),
      (v_set_id, 2, E'संविधान सभाबाट संविधान जारी गर्ने विश्वको पहिलो संविधान कुन मुलुकको हो ?', E'फ्रान्स', E'अमेरिका', E'बेलायत', E'भारत', 'A', E'संविधान सभाबाट संविधान जारी गर्ने विश्वको पहिलो राष्ट्र **फ्रान्स** हो।\n- अमेरिका विश्वको पहिलो लिखित संविधान जारी गर्ने देश हो।\n- बेलायतमा लिखित संविधान छैन, यो अलिखित संविधान भएको देश हो।\n- भारतको संविधान विश्वको सबैभन्दा लामो लिखित संविधान हो।\nनोट: नेपाल संविधानसभाबाट संविधान जारी गर्ने ४४ औं राष्ट्र हो।', 'nepali'),
      (v_set_id, 3, E'नेपाललाई हलियाप्रथा मुक्त राष्ट्र घोषणा कहिले गरिएको थियो?', E'२०६५ भदौ २३', E'२०६५ भदौ २१', E'२०६५ भदौ २४', E'२०६५ भदौ २७', 'B', E'नेपाललाई **वि.सं. २०६५ भदौ २१** मा हलियाप्रथा मुक्त राष्ट्र घोषणा गरिएको थियो। यो घोषणा तत्कालीन प्रधानमन्त्री पुष्पकमल दाहाल ''प्रचण्ड''को सरकारले गरेको थियो।\nनोट: यसैगरी कमैया प्रथाको अन्त्य वि.सं. २०५७ साउन २ मा र दास प्रथाको अन्त्य वि.सं. १९८० मंसिर १४ मा भएको थियो।', 'nepali'),
      (v_set_id, 4, E'विश्व भूगोलमा क्यास्पियन सागर पछिको सबैभन्दा ठूलो ताल सुपेरियर ताल कुन कुन देशमा अवस्थित छ?', E'अमेरिका र क्युवा', E'अमेरिका र मेक्सिको', E'अमेरिका र डोमिनिया', E'अमेरिका र क्यानडा', 'D', E'सुपेरियर ताल **अमेरिका र क्यानडामा** अवस्थित छ।\nनोट: यो ताल विश्वको सबैभन्दा ठूलो स्वच्छ पानीको ताल हो र क्षेत्रफलको आधारमा क्यास्पियन सागरपछि दोस्रो ठूलो ताल हो, जसको क्षेत्रफल ८२,४१४ वर्ग किलोमिटर छ।', 'nepali'),
      (v_set_id, 5, E'अमेरिका औपचारिक रुपमा विश्व स्वास्थ्य संगठनबाट कहिले बाहिरिएको छ?', E'२०२६ जनवरी २१', E'२०२६ जनवरी २२', E'२०२६ जनवरी २३', E'२०२६ जनवरी २४', 'B', E'अमेरिका औपचारिक रुपमा विश्व स्वास्थ्य संगठन (WHO) बाट **२०२६ जनवरी २२** मा बाहिरिएको थियो।\nनोट: यो निर्णय चीनको वुहानबाट सुरु भएको कोभिड-१९ महामारीको व्यवस्थापनमा WHO को जवाफदेहिता, पारदर्शिता र स्वतन्त्रताको अभावका कारण भएको थियो।', 'nepali'),
      (v_set_id, 6, E'मानव अधिकार र व्यक्तिगत स्वतन्त्रता सम्बन्धमा पहिलो लिखित दस्तावेज म्याग्नाकार्टामा कतिवटा धारा हरु रहेका थिए?', E'६३ वटा', E'६२ वटा', E'६१ वटा', E'६० वटा', 'A', E'मानव अधिकार र व्यक्तिगत स्वतन्त्रता सम्बन्धी पहिलो लिखित दस्तावेज म्याग्नाकार्टामा जम्मा **६३ वटा** धाराहरू रहेका थिए।\nनोट: यो दस्तावेजमा सन् १२१५ जुन १५ मा बेलायतका राजा जोन द्वितीयले हस्ताक्षर गरेका थिए।', 'nepali'),
      (v_set_id, 7, E'संयुक्त राष्ट्रसंघको प्रथम महासचिव ट्रिग्वे ह्यवदान ली कुन देशका नागरिक हुन?', E'स्वीडेन', E'नर्वे', E'म्यानमार', E'पोर्चुगल', 'B', E'**संयुक्त राष्ट्रसंघका प्रथम महासचिव ट्रिग्वे ह्यवदान ली नर्वेका नागरिक थिए।**\n- स्वीडेनका नागरिक ड्याग ह्यामरसोल्ड संयुक्त राष्ट्रसंघका दोस्रो महासचिव थिए।\n- म्यानमार (बर्मा) का नागरिक उ थान्त प्रथम एसियाली महासचिव थिए।\n- पोर्चुगलका नागरिक एन्टोनियो गुटेस हालका महासचिव हुन्।', 'nepali'),
      (v_set_id, 8, E'देहाएका मध्ये कुन सिद्धान्त डार्विनको सिद्धान्त हैन?', E'वंशज', E'परिवृत्ती', E'उत्परिवर्तन', E'नयाँ जिवको उत्पति', 'C', E'**उत्परिवर्तनको सिद्धान्त डार्विनको सिद्धान्त होइन، यो ह्युगो डिभ्रिजले प्रतिपादन गरेका हुन्।**\n- वंशज, परिवृत्ति, र नयाँ जीवको उत्पत्ति डार्विनका सिद्धान्तका अंग हुन्।\nनोट: डार्विनका अन्य प्रमुख सिद्धान्तहरूमा अत्याधिक प्रजनन, बाँच्नका लागि संघर्ष, र प्राकृतिक छनोट पर्दछन्।', 'nepali'),
      (v_set_id, 9, E'सार्कको अवधारणा ल्याउने व्यक्ति कुन मुलुकका नागरिक हुन?', E'बंगलादेश', E'नेपाल', E'भारत', E'भुटान', 'A', E'सार्कको अवधारणा ल्याउने व्यक्ति **बंगलादेशका** तत्कालीन राष्ट्रपति जियाउल रहमान थिए।\nनोट: उनले सन् १९८० मे २ मा यो अवधारणा प्रस्तुत गरेका थिए र सार्कको स्थापना भने ८ डिसेम्बर १९८५ मा भएको हो।', 'nepali'),
      (v_set_id, 10, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा प्रचलित १० वटा धर्म मध्ये सबैभन्दा कम धर्मावलम्बी भएको धर्म कुन हो ?', E'बहाइ', E'शिख', E'जैन', E'बोन', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा सबैभन्दा कम धर्मावलम्बी भएको धर्म **बहाइ** हो।\nनोट: जनगणना अनुसार नेपालमा बहाइ धर्मावलम्बीको संख्या ५३७ जना रहेको छ।', 'nepali'),
      (v_set_id, 11, E'राष्ट्रिय जनगणना, २०७८ अनुसार रामेछाप पछि जनसंख्या वृद्धिदर सबैभन्दा कम भएको नेपाली जिल्ला कुन हो ?', E'मनाङ', E'खोटाङ', E'भोजपुर', E'मुस्ताङ', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार जनसंख्या वृद्धिदर सबैभन्दा कम भएको जिल्ला रामेछाप हो, र त्यसपछिको दोस्रो कम वृद्धिदर भएको जिल्ला **खोटाङ** हो।\n- मनाङ जनसंख्या वृद्धिदर कम हुने जिल्लाको सूचीमा तेस्रो स्थानमा छ।\n- भोजपुर जनसंख्या वृद्धिदर कम हुने जिल्लाको सूचीमा चौथो स्थानमा छ।\n- मुस्ताङ पनि ऋणात्मक जनसंख्या वृद्धिदर भएका जिल्लाहरू मध्ये एक हो।\nनोट: जनगणना, २०७८ अनुसार ३४ वटा जिल्लाको जनसंख्या वृद्धिदर ऋणात्मक रहेको छ।', 'nepali'),
      (v_set_id, 12, E'संयुक्त राष्ट्रसंघको सफल अंग जिम्माजमानी परिषदले उपनिवेशमा रहेका राष्ट्र मध्ये स्वतन्त्र बनाएको पहिलो मुलुक कुन हो ?', E'भ्याटिकन सिटि', E'नाउरु', E'पलाउ', E'घाना', 'D', E'संयुक्त राष्ट्रसंघको जिम्माजमानी परिषदले स्वतन्त्र बनाएको पहिलो मुलुक **घाना** (सन् १९५७) हो।\n- नाउरु पनि जिम्माजमानी परिषदद्वारा स्वतन्त्रता प्राप्त गर्ने एक मुलुक हो।\n- पलाउ जिम्माजमानी परिषदले स्वतन्त्र बनाएको अन्तिम मुलुक हो, जसले सन् १९९४ मा स्वतन्त्रता पायो।\n- भ्याटिकन सिटि संयुक्त राष्ट्रसंघको सदस्य राष्ट्र नभई एक स्थायी पर्यवेक्षक राष्ट्र हो।\nनोट: जिम्माजमानी परिषदलाई संयुक्त राष्ट्रसंघको सबैभन्दा सफल अंग मानिन्छ र यो हाल निष्क्रिय अवस्थामा छ।', 'nepali'),
      (v_set_id, 13, E'प्रत्येक वर्ष सुरक्षा परिषदमा कति मुलुक हरु अस्थायी सदस्य राष्ट्रका रुपमा निर्वाचित हुन्छन् ?', E'५ देश', E'१० देश', E'२ देश', E'१५ देश', 'A', E'संयुक्त राष्ट्रसंघको सुरक्षा परिषदमा प्रत्येक वर्ष **५ देश** अस्थायी सदस्य राष्ट्रका रूपमा निर्वाचित हुन्छन्।\nनोट: सुरक्षा परिषदमा कुल १५ सदस्य हुन्छन्, जसमा ५ स्थायी र १० अस्थायी सदस्य रहन्छन्। अस्थायी सदस्यहरूको कार्यकाल दुई वर्षको हुन्छ।', 'nepali'),
      (v_set_id, 14, E'देहाएका विकल्प मध्ये कुन लक्ष्य दिगो बिकासका १७ लक्ष्य अन्तर्गत पर्दैन पहिचान गर्नुहोस् ?', E'लैङ्गिक समानता', E'गुणस्तरीय शिक्षा', E'असमानताको अन्त्य', E'दिगो सहर र समुदाय', 'C', E'दिगो विकासका १७ लक्ष्यहरूमध्ये **''असमानताको अन्त्य''** भन्ने लक्ष्य समावेश छैन।\n- लैङ्गिक समानता दिगो विकासको लक्ष्य नम्बर ५ हो।\n- गुणस्तरीय शिक्षा दिगो विकासको लक्ष्य नम्बर ४ हो।\n- दिगो सहर र समुदाय दिगो विकासको लक्ष्य नम्बर ११ हो।\nनोट: दिगो विकासको लक्ष्य नम्बर १० ''देशभित्र तथा बाहिरको असमानताको न्यूनीकरण'' (Reduced Inequalities) हो, ''असमानताको अन्त्य'' होइन।', 'nepali'),
      (v_set_id, 15, E'विश्व बौद्ध शिखर सम्मेलन २०२६ कुन मुलुकमा आयोजना भएको छ ?', E'नेपाल', E'भारत', E'थाइल्याण्ड', E'चीन', 'B', E'विश्व बौद्ध शिखर सम्मेलन २०२६ **भारतमा** आयोजना भएको थियो।\nनोट: भारत सरकारको संस्कृति मन्त्रालय र अन्तर्राष्ट्रिय बौद्ध महासंघ (IBC) को सहकार्यमा यो सम्मेलन नयाँ दिल्लीमा २०२६ जनवरी २४ र २५ मा सम्पन्न भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_19.csv  →  आसमान दैनिक GK — २०८२/१२/१९  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/१९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/१९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/१९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'प्रसिद्ध गायक तथा कलाकार प्रशान्त तामाङको निधन देहाएका मध्ये कुन मितिमा भएको हो ?', E'२०८२ पौष २७', E'२०८२ मंसिर २९', E'२०८२ कात्तिक २२', E'२०८२ वैशाख १५', 'A', E'प्रसिद्ध गायक तथा कलाकार प्रशान्त तामाङको निधन **२०८२ पौष २७** मा भएको हो।\n- २०८२ मंसिर २९ मा पूर्व शिक्षामन्त्री आमोदप्रसाद उपाध्यायको निधन भएको थियो।\n- २०८२ कात्तिक २२ मा पूर्व मन्त्री तथा चर्चित नेता मोहम्मद अफताव आलमको निधन भएको थियो।\n- २०८२ वैशाख १५ मा राउटे समुदायका मुखिया सूर्यनारायण शाहीको निधन भएको थियो।', 'nepali'),
      (v_set_id, 2, E'आर्थिक वर्ष २०८२/८३ फागुन सम्ममा नेपालको कुल व्यापार घाटा कति रहेको छ ?', E'१० खर्ब ९८ अर्ब ३९ करोड', E'११ खर्ब ९८ अर्ब ३९ करोड', E'१२ खर्ब ९८ अर्ब ३९ करोड', E'१३ खर्ब ९८ अर्ब ३९ करोड', 'A', E'आर्थिक वर्ष २०८२/८३ को फागुन सम्ममा नेपालको कुल व्यापार घाटा **१० खर्ब ९८ अर्ब ३९ करोड** रहेको छ।\nनोट: सोही अवधिमा कुल आयात १२ खर्ब ८९ अर्ब ९२ करोड र कुल निर्यात १ खर्ब ९१ अर्ब ११ करोड रहेको थियो।', 'nepali'),
      (v_set_id, 3, E'प्रतिनिधि सभा निर्वाचन, २०८२ पश्चात गठित बालेन्द्र शाह नेतृत्वको मन्त्रीपरिषदले संघीय मन्त्रालयको संख्या घटाएर कति बनाउने निर्णय गरेको छ?', E'१५ वटा', E'१७ वटा', E'२० वटा', E'२२ वटा', 'B', E'प्रतिनिधि सभा निर्वाचन, २०८२ पश्चात गठित बालेन्द्र शाह नेतृत्वको मन्त्रिपरिषदले संघीय मन्त्रालयको संख्या घटाएर **१७ वटा** बनाउने निर्णय गरेको छ।\nनोट: सरकारले २०८२ चैत १५ मा १०० बुँदे सुशासन सुधार कार्यसूची सार्वजनिक गरेको थियो।', 'nepali'),
      (v_set_id, 4, E'१६ वर्षमुनिकालाई सामाजिक सञ्जालमा प्रतिबन्ध लगाउने दक्षिणपूर्वी एसियाको पहिलो देश कुन बनेको छ ?', E'थाइल्याण्ड', E'मलेसिया', E'इन्डोनेसिया', E'भारत', 'C', E'**इन्डोनेसिया** १६ वर्षमुनिकालाई सामाजिक सञ्जालमा प्रतिबन्ध लगाउने दक्षिणपूर्वी एसियाको पहिलो देश बनेको छ। यो निर्णय सन् २०२६ मार्च २८ मा लागू भएको थियो, जसअन्तर्गत युट्युब, टिकटक, फेसबुक, इन्स्टाग्राम जस्ता प्लेटफर्ममा अकाउन्ट खोल्न रोक लगाइएको छ।', 'nepali'),
      (v_set_id, 5, E'हालसालै नेपालको न्यायिक इतिहासमा दोस्रो महिला कायम मुकायम (कामु) प्रधानन्यायाधीश को बन्न सफल हुनु भएको हो ?', E'सुशीला कार्की', E'सपना प्रधान मल्ल', E'मीरा खड्का', E'शारदा श्रेष्ठ', 'B', E'**सपना प्रधान मल्ल** नेपालको न्यायिक इतिहासमा दोस्रो महिला कायम मुकायम (कामु) प्रधानन्यायाधीश बन्न सफल हुनुभएको हो।\n- सुशीला कार्की नेपालकी प्रथम महिला प्रधानन्यायाधीश हुनुहुन्छ।\n- मीरा खड्का सर्वोच्च अदालतकी न्यायाधीश हुनुहुन्थ्यो।\n- शारदा श्रेष्ठ सर्वोच्च अदालतकी प्रथम महिला न्यायाधीश हुनुहुन्थ्यो।\nनोट: प्रधानन्यायाधीश प्रकाशमानसिंह राउतले ६५ वर्षे उमेरहदका कारण अवकाश पाएपछि वरिष्ठतम न्यायाधीश मल्लले २०८२ चैत १८ देखि कामु प्रधानन्यायाधीशको जिम्मेवारी सम्हाल्नुभएको हो।', 'nepali'),
      (v_set_id, 6, E'मानिसको दिमागमा कम्प्युटर चिप राख्न व्यावसायिक स्वीकृति दिने विश्वकै पहिलो मुलुक कुन बनेको छ ?', E'भारत', E'चीन', E'अमेरिका', E'जापान', 'B', E'**चीन** मानिसको दिमागमा कम्प्युटर चिप राख्न व्यावसायिक स्वीकृति दिने विश्वको पहिलो मुलुक बनेको छ। चीनको नेसनल मेडिकल प्रोडक्ड्स एडमिनिस्ट्रेसन (NMPA) ले सन् २०२६ मार्च १३ मा न्युराकल मेडिकल टेक्नोलोजीद्वारा विकसित ''नियो'' नामक उपकरणलाई स्वीकृति दिएको हो।\nनोट: यो ब्रेन कम्प्युटर इन्टरफेस (BCI) प्रविधिको मुख्य उद्देश्य पक्षघात (Paralysis) भएका बिरामीहरूको उपचारमा सहयोग गर्नु हो।', 'nepali'),
      (v_set_id, 7, E'इन्डियन प्रिमियर लिग (आइपिएल), २०२६ कहिले देखि सुरु भएको हो ?', E'सन् २०२६ मार्च २७', E'सन् २०२६ मार्च २८', E'सन् २०२६ मार्च २९', E'सन् २०२६ मार्च ३०', 'B', E'इन्डियन प्रिमियर लिग (आइपिएल) को १९ औं संस्करण **सन् २०२६ मार्च २८** देखि सुरु भएको हो। यो प्रतियोगिता मार्च २८ देखि मे ३१, २०२६ सम्म आयोजना भएको थियो, जसमा १० टोलीको सहभागिता रहेको थियो।', 'nepali'),
      (v_set_id, 8, E'प्रतिनिधि सभा निर्वाचन, २०८२ पछि नेपालमा प्रधानमन्त्री बन्न सफल राजनीतिज्ञ बालेन्द्र शाह व्यक्तिगत आधारमा नेपालको कति औं प्रधानमन्त्री बनेका छन् ?', E'४० औं', E'४१ औं', E'४२ औं', E'४३ औं', 'A', E'प्रतिनिधि सभा निर्वाचन, २०८२ पछि प्रधानमन्त्री बनेका बालेन्द्र शाह व्यक्तिगत आधारमा नेपालको **४० औं** प्रधानमन्त्री हुन्। उनी गणतन्त्र नेपालका दशौं प्रधानमन्त्री पनि हुन्।\nनोट: कार्यकालको आधारमा भने भिमसेन थापादेखि गणना गर्दा उनी ७० औं प्रधानमन्त्री पर्छन्।', 'nepali'),
      (v_set_id, 9, E'आर्थिक वर्ष २०८२/८३ फागुन सम्ममा नेपालको वैदेशिक व्यापारमा सबैभन्दा उच्च व्यापार नाफा कुन देशसँग भएको छ ?', E'रोमानिया', E'युएइ', E'भारत', E'डेनमार्क', 'D', E'आर्थिक वर्ष २०८२/८३ को फागुन सम्मको तथ्याङ्क अनुसार नेपालले **डेनमार्कसँग** सबैभन्दा उच्च व्यापार नाफा गरेको छ।\n- रोमानियासँग पनि नेपालको व्यापार नाफामा रहेको थियो।\n- युएईसँग नेपालको उच्च व्यापार घाटा रहेको छ।\n- भारतसँग पनि नेपालको उच्च व्यापार घाटा रहेको छ।\nनोट: उक्त अवधिमा नेपालले १८४ देशसँग व्यापार गरेकोमा ३५ देशसँग मात्र नाफा कमाएको थियो।', 'nepali'),
      (v_set_id, 10, E'प्रतिनिधि सभा निर्वाचन, २०८२ मा नवनिर्वाचित संसदले पद तथा गोपनीयता शपथ कहिले लिएका छन् ?', E'२०८२ चैत ११', E'२०८२ चैत १२', E'२०८२ चैत १३', E'२०८२ चैत १४', 'B', E'प्रतिनिधि सभा निर्वाचन, २०८२ का नवनिर्वाचित सांसदहरूले **२०८२ चैत १२** गते पद तथा गोपनीयताको शपथ लिएका थिए।\n- २०८२ चैत ११ गते जेष्ठ सदस्यको रूपमा अर्जुननरसिंह केसीले राष्ट्रपतिबाट शपथ ग्रहण गरेका थिए।\n- २०८२ चैत १३ गते बालेन्द्र शाहले प्रधानमन्त्री पदको शपथ लिएका थिए।\n- २०८२ चैत १४ को मिति प्रश्नमा उल्लेखित घटनाक्रमसँग सम्बन्धित छैन।', 'nepali'),
      (v_set_id, 11, E'बासु शशी साहित्य पुरस्कार, २०८२ कसलाई प्रदान गरियो ?', E'घनश्याम कँडेल', E'वसन्त चौधरी', E'नवराज अधिकारी', E'प्रवीण रेग्मी', 'B', E'**बासु शशी साहित्य पुरस्कार, २०८२ वसन्त चौधरीलाई प्रदान गरियो।**\n- घनश्याम कँडेललाई लेखनाथ पुरस्कार, २०८२ प्रदान गरिएको थियो।\n- नवराज अधिकारीलाई लेखनाथ सांस्कृतिक पुरस्कार, २०८२ प्रदान गरिएको थियो।\n- गंगा कर्माचार्य पौडेललाई कुन्तिदेवी साहित्य पुरस्कार, २०८२ प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 12, E'प्रतिनिधि सभा निर्वाचन, २०८२ पश्चात गठित बालेन्द्र शाह नेतृत्वको मन्त्रीमण्डलमा शिक्षा मन्त्रीको बनेका छन् ?', E'सस्मित पोखरेल', E'स्वर्णिम वाग्ले', E'सुनिल लम्साल', E'गणेश पौडेल', 'A', E'प्रतिनिधि सभा निर्वाचन, २०८२ पश्चात गठित बालेन्द्र शाह नेतृत्वको मन्त्रीमण्डलमा **सस्मित पोखरेल** शिक्षा मन्त्री बनेका थिए।\n- स्वर्णिम वाग्ले अर्थमन्त्री बनेका थिए।\n- सुनिल लम्साल भौतिक पूर्वाधार तथा यातायात मन्त्री बनेका थिए।\n- गणेश पौडेल संस्कृति, पर्यटन तथा नागरिक उड्डयन मन्त्री बनेका थिए।', 'nepali'),
      (v_set_id, 13, E'विश्व खुशी सूचकांक, २०२६ मा सबैभन्दा खुशी रहेको दक्षिण एसियाली मुलुक कुन हो ?', E'नेपाल', E'पाकिस्तान', E'भारत', E'अफगानिस्तान', 'A', E'विश्व खुशी सूचकांक, २०२६ अनुसार दक्षिण एसियामा सबैभन्दा खुशी मुलुक **नेपाल** हो।\n- पाकिस्तान यस सूचकांकमा १०४ औं स्थानमा थियो।\n- भारत ११६ औं स्थानमा थियो।\n- अफगानिस्तान १४७ औं स्थानमा रहँदै विश्वकै अन्तिम स्थानमा थियो।\nनोट: समग्र विश्वमा नेपाल ९९ औं स्थानमा रहेको थियो।', 'nepali'),
      (v_set_id, 14, E'देहायका मध्ये कुन मुलुकले फिफा विश्वकप, २०२६ सहभागी बाट बाहिरिने निर्णय गरेको छ ?', E'इरान', E'क्यानडा', E'बंगलादेश', E'ब्राजिल', 'A', E'**इरानले** फिफा विश्वकप, २०२६ मा सहभागी नहुने निर्णय गरेको छ। यो विश्वकप अमेरिका, मेक्सिको र क्यानडामा संयुक्त रूपमा आयोजना भएको थियो, जसमा पहिलोपटक ४८ देशले सहभागिता जनाएका थिए।', 'nepali'),
      (v_set_id, 15, E'विश्व खुसी दिवस (International Day of Happiness) हरेक वर्ष कुन तारिखमा मनाइन्छ?', E'मार्च ५', E'मार्च १०', E'मार्च १५', E'मार्च २०', 'D', E'अन्तर्राष्ट्रिय खुसी दिवस (International Day of Happiness) हरेक वर्ष **मार्च २०** मा मनाइन्छ।\nनोट: सन् २०२६ को लागि यस दिवसको नारा ''Caring and Sharing'' रहेको थियो, जसको उद्देश्य सम्बन्ध र कल्याणलाई तोड्न होइन, निर्माण गर्न सामाजिक सञ्जालको सकारात्मक प्रयोगलाई बढावा दिनु थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/१९', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_20.csv  →  आसमान दैनिक GK — २०८२/१२/२०  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/२०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/२०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/२०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको केन्द्रिय बैंक ''नेपाल राष्ट्र बैंक'' को स्थापना हुदाँ तत्कालीन प्रधानमन्त्री को थिए?', E'मोहन सम्सेर', E'जुद्ध सम्सेर', E'टंक प्रसाद आचार्य', E'मातृका प्रसाद कोइराला', 'C', E'नेपाल राष्ट्र बैंकको स्थापना हुँदा तत्कालीन प्रधानमन्त्री **टंक प्रसाद आचार्य** थिए।\n- मोहन शमशेर राणा शासनका अन्तिम प्रधानमन्त्री थिए।\n- जुद्ध शमशेरको पालामा नेपालको पहिलो बैंक, नेपाल बैंक लिमिटेड, वि.सं. १९९४ कार्तिक ३० मा स्थापना भएको थियो।\n- मातृका प्रसाद कोइराला नेपालका प्रथम गैर-राणा प्रधानमन्त्री थिए।\nनोट: नेपाल राष्ट्र बैंकको स्थापना वि.सं. २०१३ वैशाख १४ मा भएको थियो।', 'nepali'),
      (v_set_id, 2, E'भनाइ मुल्यांकन गर्नुहोस् A) विश्व स्वास्थ्य दिवस अप्रिल ८ मा मनाइन्छ। B) शरिरमा सेता रक्त कोषको संख्या बढि भएमा हेमोग्लोबिन हुन्छ।', E'A मात्र ठिक', E'B मात्र ठिक', E'दुवै बेठीक', E'दुवै ठिक', 'C', E'दुवै भनाइहरू बेठीक छन्।\n- विश्व स्वास्थ्य दिवस **अप्रिल ७** मा मनाइन्छ, अप्रिल ८ मा होइन।\n- शरीरमा सेता रक्तकोषको संख्या अत्यधिक बढ्नुलाई ल्युकेमिया (रक्त क्यान्सर) भनिन्छ। हेमोग्लोबिन रातो रक्तकोषमा पाइने प्रोटिन हो, जसको कमीले रक्तअल्पता हुन्छ।', 'nepali'),
      (v_set_id, 3, E'देहाएका मध्ये कसको हत्या रानी राज्यलक्ष्मीको षड्यन्त्र र आदेशको कारण भएको हो ?', E'माथवरसिंह थापा', E'अभिमानसिंह बस्नेत', E'फत्तेजंग शाह', E'गगन सिंह', 'A', E'**माथवरसिंह थापाको** हत्या रानी राज्यलक्ष्मीको षड्यन्त्र र आदेशमा भएको थियो।\n- अभिमानसिंह बस्नेतको हत्या कोत पर्वमा भएको थियो।\n- फत्तेजंग शाह, जो कोत पर्वका बेला प्रधानमन्त्री थिए, उनको पनि सोही पर्वमा हत्या भयो।\n- गगन सिंहको हत्या कोत पर्वको प्रमुख कारण बनेको थियो، उनी रानीका प्रिय पात्र थिए।', 'nepali'),
      (v_set_id, 4, E'तेस्रो बालसाहित्य महोत्सव, २०८२ कुन जिल्लामा सम्पन्न भएको छ ?', E'काठमाण्डौं', E'ललितपुर', E'भक्तपुर', E'कास्की', 'B', E'तेस्रो बालसाहित्य महोत्सव, २०८२ **ललितपुर** जिल्लामा सम्पन्न भएको थियो।\nनोट: यो महोत्सव नेपाल बालसाहित्य समाज, ललितपुर महानगरपालिका र पाटन संग्रहालयको आयोजनामा २०८२ माघ ११ देखि १४ गतेसम्म पाटन संग्रहालयमा आयोजना गरिएको थियो।', 'nepali'),
      (v_set_id, 5, E'नेपालको इतिहासमा मकै पर्व देहाएको कुन मितिमा भएको थियो ?', E'१९७७ साउन ११', E'१९७७ साउन १०', E'१९७६ साउन ११', E'१९७६ साउन १०', 'A', E'नेपालको इतिहासमा मकै पर्व **वि.सं. १९७७ साउन ११** मा भएको थियो। कृष्णलाल अधिकारीले ''मकैको खेती'' नामक पुस्तक लेखेका थिए, जसमा राणा शासनको विरोध गरिएको आरोपमा उनलाई ९ वर्षको जेल सजाय दिइएको थियो र जेलमै उनको मृत्यु भयो।', 'nepali'),
      (v_set_id, 6, E'नेपालको संविधान अनुसार संघीय इकाइ अन्तर्गत देहाएको के पर्छ ?', E'संघ र स्थानीय तह', E'संघ मात्र', E'संघ र प्रदेश तह', E'तीनवटै तह', 'D', E'नेपालको संविधान अनुसार संघीय इकाइ भन्नाले **संघ, प्रदेश र स्थानीय तह** सम्झनु पर्छ, त्यसैले तीनवटै तह यस अन्तर्गत पर्दछन्।\nनोट: संविधानको धारा ५६ मा राज्यको संरचना सम्बन्धी व्यवस्था गरिएको छ, जसमा संघ, प्रदेश र स्थानीय तह गरी तीन तहको राज्यको मूल संरचना रहने उल्लेख छ।', 'nepali'),
      (v_set_id, 7, E'युनेस्को (UNESCO) को प्रधान कार्यालय कहाँ रहेको छ ?', E'जेनेभा', E'लण्डन', E'पेरिस', E'बैंकक', 'C', E'संयुक्त राष्ट्र संघीय शैक्षिक, वैज्ञानिक तथा सांस्कृतिक सङ्गठन (UNESCO) को प्रधान कार्यालय **फ्रान्सको पेरिसमा** रहेको छ।\n- जेनेभामा विश्व स्वास्थ्य संगठन (WHO) र अन्तर्राष्ट्रिय श्रम संगठन (ILO) जस्ता संस्थाहरूको मुख्यालय छ।\n- लण्डनमा अन्तर्राष्ट्रिय सामुद्रिक संगठन (IMO) को मुख्यालय रहेको छ।\n- बैंककमा संयुक्त राष्ट्रसंघीय एसिया तथा प्रशान्त क्षेत्रका लागि आर्थिक तथा सामाजिक आयोग (UNESCAP) को मुख्यालय छ।\nनोट: युनेस्कोको स्थापना सन् १९४६ नोभेम्बर ४ मा भएको थियो र नेपालले सन् १९५३ मा यसको सदस्यता प्राप्त गरेको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपाल भारत बिप्पा (BIPPA) सम्झौतामा जम्मा कतिवटा धारा रहेका छन् ?', E'१६ वटा', E'१५ वटा', E'१४ वटा', E'१७ वटा', 'A', E'नेपाल र भारतबीच भएको द्विपक्षीय लगानी प्रवर्द्धन तथा संरक्षण सम्झौता (BIPPA) मा जम्मा **१६ वटा** धारा रहेका छन्।\nनोट: यो सम्झौतामा वि.सं. २०६८ कार्तिक ४ (सन् २०११ अक्टोबर २१) मा हस्ताक्षर भएको थियो।', 'nepali'),
      (v_set_id, 9, E'नेपालको संविधान अनुसार सरकारी कामकाजको भाषा कुन हो ?', E'नेवारी भाषा', E'देवनागरी भाषा', E'सबै मातृभाषा', E'नेपाली भाषा', 'D', E'नेपालको संविधान अनुसार देवनागरी लिपिमा लेखिने **नेपाली भाषा** सरकारी कामकाजको भाषा हो।\n- नेवारी भाषा नेपालमा बोलिने एक मातृभाषा हो, जसलाई राष्ट्रभाषाको मान्यता दिइएको छ।\n- देवनागरी एक लिपि हो, भाषा होइन। नेपाली भाषा देवनागरी लिपिमा लेखिन्छ।\n- नेपालमा बोलिने सबै मातृभाषाहरू राष्ट्रभाषा हुन्, तर सरकारी कामकाजको भाषा नेपाली हो।\nनोट: संविधानको धारा ७ ले सरकारी कामकाजको भाषा सम्बन्धी व्यवस्था गरेको छ।', 'nepali'),
      (v_set_id, 10, E'हिन्दु धर्म परम्परा सँग सम्बन्धित वेदमा रहेका तीन काण्डमा देहाएका मध्ये कुन कुरा पर्दैन ?', E'उपसना काण्ड', E'ज्ञानकाण्ड', E'कर्मकाण्ड', E'धर्मकाण्ड', 'D', E'वेदमा रहेका तीन प्रमुख काण्डहरूमा **धर्मकाण्ड** पर्दैन।\n- उपसना काण्ड सामवेदसँग सम्बन्धित छ।\n- ज्ञानकाण्ड ऋग्वेदसँग सम्बन्धित छ।\n- कर्मकाण्ड यजुर्वेदसँग सम्बन्धित छ।\nनोट: वेदहरूमा ज्ञान, कर्म र उपासनालाई तीन मुख्य मार्गका रूपमा व्याख्या गरिएको छ।', 'nepali'),
      (v_set_id, 11, E'विश्वको भुगोलमा कुन महादेशको सबैभन्दा ठूलो हिमनदि ''सियाचेन'' हो ?', E'अफ्रिका', E'युरोप', E'अस्ट्रेलिया', E'एसिया', 'D', E'विश्वको सबैभन्दा ठूलो हिमनदी सियाचेन **एसिया** महादेशमा पर्दछ।\n- अफ्रिका महादेशको प्रसिद्ध हिमनदी किलिमञ्जारो हो।\n- युरोप महादेशको प्रसिद्ध हिमनदी भट्नाजुकल हो।\n- अस्ट्रेलिया महादेशको प्रसिद्ध हिमनदी हार्ड एयरल्याण्ड हो।\nनोट: सियाचेन हिमनदी हिमालयको पूर्वी काराकोरम पर्वत श्रृंखलामा अवस्थित छ।', 'nepali'),
      (v_set_id, 12, E'आदिवासी तथा लोपोन्मुख जाति अन्तर्गतको एक ''दराई'' जातिको मुख्य बासस्थान देहाएका मध्ये कुन नेपाली जिल्ला हो?', E'बाग्लुङ', E'पाल्पा', E'तनहुँ', E'रुपन्देही', 'C', E'आदिवासी तथा लोपोन्मुख ''दराई'' जातिको मुख्य बसोबास **तनहुँ** जिल्लामा रहेको छ। यो जाति नेपालको सिमान्तकृत समूहमा सूचीकृत २० जनजाति मध्ये एक हो।\nनोट: दराई जातिमा नयाँ वर्षमा पुरानो आगो निभाएर नयाँ बाल्ने, रोदिनाच, घाटुनाच र मृत्यु संस्कारमा ''सोराहे'' जस्ता मौलिक प्रचलनहरू रहेका छन्।', 'nepali'),
      (v_set_id, 13, E'भुकम्पको तिब्रता उत्पत्ति भएको स्थान वेग फैलावट आदि नाप्ने यन्त्रलाई के भनिन्छ ?', E'सिस्मोलोजी', E'सिस्मोमिटर', E'रेक्टरस्केल', E'सिस्मोग्राफ', 'D', E'भूकम्पको तीव्रता, उत्पत्ति स्थान, वेग र फैलावट नाप्ने यन्त्रलाई **सिस्मोग्राफ** भनिन्छ।\n- सिस्मोलोजी भनेको भूकम्पसम्बन्धी अध्ययन गर्ने विज्ञान हो।\n- सिस्मोमिटर भूकम्पको म्याग्निच्युड (शक्ति) मापन गर्ने उपकरण हो।\n- रेक्टरस्केल भूकम्पको म्याग्निच्युड मापन गर्ने एकाइ वा मापक हो।', 'nepali'),
      (v_set_id, 14, E'सन् २०२६ मा नेपालसँगै विकासशील राष्ट्रमा स्तरोन्नति हुने मुलुकहरु कुनकुन हुन् ?', E'बंगलादेश र लाओस', E'भुटान र लाओस', E'श्रीलंका र लाओस', E'बंगलादेश र भुटान', 'A', E'सन् २०२६ मा नेपालसँगै **बंगलादेश र लाओस** अतिकम विकसित मुलुकबाट विकासशील राष्ट्रमा स्तरोन्नति भएका थिए।\nनोट: नेपालको स्तरोन्नति सन् २०२६ नोभेम्बर २४ मा भएको थियो, जसले देशको आर्थिक विकासमा एक महत्वपूर्ण कोसेढुङ्गा पार गरेको जनाउँछ।', 'nepali'),
      (v_set_id, 15, E'इन्द्रेणीका सात रंगमा देखा पर्ने सबैभन्दा तल्लो रंग कुन हो ?', E'सुन्तला', E'नीर', E'रातो', E'बैजनी', 'D', E'इन्द्रेणीमा देखिने सात रंगमध्ये सबैभन्दा तल्लो रंग **बैजनी** हो।\n- रातो रंग इन्द्रेणीको सबैभन्दा माथिल्लो भागमा देखिन्छ।\n- सुन्तला रंग रातोभन्दा तल र पहेँलोभन्दा माथि हुन्छ।\n- नीर (Indigo) बैजनीभन्दा माथि र निलोभन्दा तल हुन्छ।\nनोट: इन्द्रेणीका रंगहरूको क्रम VIBGYOR (बैजनी, नीर, निलो, हरियो, पहेँलो, सुन्तला, रातो) तलबाट माथितिर हुन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/२०', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_22.csv  →  आसमान दैनिक GK — २०८२/१२/२२  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/२२'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/२२';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/२२', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको पहिलो महिला राजदुत को हुन ?', E'सुजाता कोइराला', E'शुसीला थापा', E'विन्देश्वरी शाह', E'जयकला देवी', 'C', E'नेपालको पहिलो महिला राजदुत **विन्देश्वरी शाह** हुन्।\n- सुजाता कोइराला नेपालको पहिलो महिला परराष्ट्रमन्त्री हुन्।\n- शुसीला थापा नेपालको पहिलो महिला मन्त्री हुन्।\n- जयकला देवी नेपालबाट पहिलो महिला स्नातकोत्तर गर्ने व्यक्ति हुन्।\nनोट: विन्देश्वरी शाहको मृत्यु वि.सं. २०६१ पुस १८ मा भएको थियो।', 'nepali'),
      (v_set_id, 2, E'दुर्घटनाग्रस्त जहाजहरुको कारण पत्ता लगाउन प्रयोग गरिने यन्त्र कुन हो ?', E'Black box', E'White box', E'Yellow box', E'Orange box', 'A', E'दुर्घटनाग्रस्त जहाजको कारण पत्ता लगाउन प्रयोग गरिने यन्त्रलाई **ब्ल्याक बक्स (Black box)** भनिन्छ। यो एक उडान रेकर्डर हो जसले विमान दुर्घटनाको अनुसन्धानलाई सहज बनाउन मद्दत गर्दछ।\nनोट: यसको नाम ''ब्ल्याक बक्स'' भए तापनि, यसलाई सजिलै फेला पार्न सकियोस् भनेर सामान्यतया चम्किलो सुन्तला (Orange) रंगले रंगाइएको हुन्छ।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधानको कुन धारामा महिलाको हक सम्बन्धि व्यवस्था गरेको छ ?', E'धारा ३८', E'धारा ३९', E'धारा ४०', E'धारा ४१', 'A', E'नेपालको संविधानको **धारा ३८** मा महिलाको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा ३९ मा बालबालिकाको हकको व्यवस्था छ।\n- धारा ४० मा दलितको हक सम्बन्धी व्यवस्था गरिएको छ।\n- धारा ४१ मा ज्येष्ठ नागरिकको हकको व्यवस्था छ।', 'nepali'),
      (v_set_id, 4, E'पृथ्वीको व्यास भन्दा सुर्यको व्यास कति गुणा ठूलो छ ?', E'२१५ गुणा', E'१०९ गुणा', E'३१८ गुणा', E'२६४ गुणा', 'B', E'सूर्यको व्यास पृथ्वीको व्यासभन्दा करिब **१०९ गुणा** ठूलो छ। सूर्यको व्यास लगभग १३,९२,७०० किलोमिटर छ भने पृथ्वीको व्यास लगभग १२,७४२ किलोमिटर छ।\nनोट: बृहस्पतिको व्यास पृथ्वीको भन्दा करिब ११ गुणा ठूलो छ, तर यसको पिण्ड (mass) पृथ्वीको भन्दा ३१८ गुणा बढी छ।', 'nepali'),
      (v_set_id, 5, E'हाल नेपालले श्रम सम्झौता गरेका देशको संख्या कति रहेको छ ?', E'११ मुलुक', E'१२ मुलुक', E'१३ मुलुक', E'१४ मुलुक', 'C', E'नेपालले श्रम सम्झौता गरेका देशको संख्या **१३** पुगेको छ।\nनोट: सन् २०२६ जनवरी २५ मा नेपाल र साउदी अरबबीच श्रम सम्झौतामा हस्ताक्षर भएपछि यो संख्या १३ पुगेको हो।', 'nepali'),
      (v_set_id, 6, E'नेपालमा प्रचलित प्रथा मध्येको एक ''खुल्ला प्रथा'' कुन जिल्लामा प्रचलित रहेको छ ?', E'डोल्पा', E'अछाम', E'बैतडी', E'मुगु', 'A', E'**''खुल्ला प्रथा'' डोल्पा जिल्लाको सर्मी गाउँमा प्रचलित रहेको छ।**\n- अछाम जिल्ला छाउपडी प्रथाको मुख्य गढ हो।\n- बैतडी जिल्ला देउकी प्रथाको केन्द्रको रुपमा चिनिन्छ, जहाँ मेलौली देवीको मन्दिर रहेको छ।', 'nepali'),
      (v_set_id, 7, E'नेपालको भूगोलमा सबैभन्दा कम गाँउपालिका भएको जिल्ला कुन हो ?', E'रुकुम पूर्व', E'चितवन', E'मुस्ताङ', E'भक्तपुर', 'B', E'नेपालमा सबैभन्दा कम गाउँपालिका भएको जिल्ला **चितवन** हो, जहाँ केवल एउटा (इच्छाकामना) गाउँपालिका रहेको छ।\n- पूर्वी रुकुममा ३ वटा स्थानीय तह छन्, जुन नेपालमा सबैभन्दा कम स्थानीय तह भएको जिल्ला हो।\n- भक्तपुर जिल्लामा एउटा पनि गाउँपालिका छैन।\nनोट: सबैभन्दा बढी गाउँपालिका भएको जिल्ला धादिङ (११ वटा) हो।', 'nepali'),
      (v_set_id, 8, E'मकालु हिमाल कुन हिमशृंखला अन्तर्गत रहेको छ ?', E'महालंगुर', E'गणेश', E'खुम्बु', E'कुम्भकर्ण', 'D', E'मकालु हिमाल **कुम्भकर्ण** हिमशृंखला अन्तर्गत रहेको छ।\n- महालंगुर/खुम्बु हिमशृंखलामा सगरमाथा, ल्होत्से र चो ओयु हिमालहरू पर्दछन्।\n- गणेश हिमशृंखला (मानसिरी) मा मनास्लु हिमाल पर्दछ।\nनोट: ८,००० मिटरभन्दा अग्ला हिमालहरूमध्ये कञ्चनजङ्घा, धवलागिरि र अन्नपूर्ण हिमालहरू आफ्नै नामको हिमशृंखलामा पर्दछन्।', 'nepali'),
      (v_set_id, 9, E'देहायका मध्ये भोटमा मुल भएको नदि कुन होइन ?', E'तामाकोशी', E'कालिगण्डकी', E'कर्णाली', E'त्रिशुली', 'B', E'देहायका नदीहरूमध्ये **कालिगण्डकी** नदीको मुहान भोट (तिब्बत) मा होइन। यसको मुहान मुस्ताङ जिल्लाको न्हुविन हिमाल ग्लेसियरमा पर्दछ।\nनोट: भोटमा मुहान भएका प्रमुख नदीहरूमा अरुण, तामाकोशी, सुनकोशी, तमोर, कर्णाली र त्रिशुली पर्दछन्।', 'nepali'),
      (v_set_id, 10, E'नेपालको इतिहासमा शेर ब. शाह को हत्या कस्ले गरेका हुन ?', E'बालनरसिंह कुँवर', E'जंगबहादुर राणा', E'प्रतापसिंह शाह', E'रण ब. शाह', 'A', E'नेपालको इतिहासमा शेरबहादुर शाहको हत्या **बालनरसिंह कुँवरले** गरेका थिए।\n- जंगबहादुर राणा नेपालका प्रथम राणा प्रधानमन्त्री थिए र उनी बालनरसिंह कुँवरका छोरा थिए।\n- प्रतापसिंह शाह पृथ्वीनारायण शाहका छोरा र नेपालका तेस्रा शाहवंशीय राजा थिए।\n- रणबहादुर शाहको हत्या उनका सौतेनी भाइ शेरबहादुर शाहले गरेका थिए।\nनोट: बालनरसिंह कुँवरको यही कदमपछि दरबारमा राणाहरूको प्रवेश भएको मानिन्छ।', 'nepali'),
      (v_set_id, 11, E'नेपाल सँगै संयुक्त राष्ट्र संघको सदस्यता लिने मुलुक कति रहेका छन ?', E'१५ मुलुक', E'१६ मुलुक', E'१७ मुलुक', E'१८ मुलुक', 'B', E'नेपालसँगै संयुक्त राष्ट्र संघको सदस्यता लिने मुलुकको संख्या **१६** रहेको थियो। नेपालले सन् १९५५ डिसेम्बर १४ मा ''प्याकेज डिल'' अन्तर्गत ७२औं सदस्यको रूपमा सदस्यता प्राप्त गरेको थियो।\nनोट: सदस्यता प्राप्त गर्दा नेपालका प्रधानमन्त्री टंकप्रसाद आचार्य र राजा महेन्द्र थिए।', 'nepali'),
      (v_set_id, 12, E'नेपालले कहिले देखि संयुक्त राष्ट्र संघमा स्थायी प्रतिनिधि मण्डलका नेता पठाउन सुरु गरेको हो ?', E'सन् १९५६', E'सन् १९५७', E'सन् १९५८', E'सन् १९५९', 'D', E'नेपालले **सन् १९५९** देखि संयुक्त राष्ट्र संघमा स्थायी प्रतिनिधि मण्डलका नेता पठाउन सुरु गरेको हो।\nनोट: संयुक्त राष्ट्र संघका लागि नेपालका पहिलो स्थायी प्रतिनिधि ऋषिकेश शाह थिए।', 'nepali'),
      (v_set_id, 13, E'मञ्जुश्रीले कुन स्थानबाट पानी कटाएर नेपाल उपत्यका बस्न योग्य बनाएकी थिइन् ?', E'नागार्जुन पर्वत', E'चोभार', E'स्वयंभु', E'गुहेश्वरी', 'B', E'किम्बदन्ती अनुसार मञ्जुश्रीले **चोभारको** डाँडो काटेर नेपाल उपत्यकाको पानी बाहिर पठाई बस्न योग्य बनाएकी थिइन्।\n- नागार्जुन पर्वत काठमाडौं उपत्यकाको उत्तर-पश्चिममा अवस्थित एक प्रसिद्ध डाँडा हो।\n- स्वयम्भू काठमाडौंमा रहेको एक प्राचीन बौद्ध स्तुप हो, जुन उपत्यकाको उत्पत्तिको कथासँग पनि जोडिएको छ।\n- गुहेश्वरी काठमाडौंमा अवस्थित एक पवित्र हिन्दू मन्दिर हो, जुन सतीदेवीको अंग पतन भएको स्थान मानिन्छ।', 'nepali'),
      (v_set_id, 14, E'विश्व पृथ्वि दिवस हरेक वर्ष कुन तारिखमा कहिले मनाइन्छ ?', E'अप्रिल २२', E'जुन ५', E'मे २२', E'डिसेम्बर ५', 'A', E'विश्व पृथ्वी दिवस हरेक वर्ष **अप्रिल २२** मा मनाइन्छ।\n- जुन ५ मा विश्व वातावरण दिवस मनाइन्छ।\n- मे २२ मा अन्तर्राष्ट्रिय जैविक विविधता दिवस मनाइन्छ।\n- डिसेम्बर ५ मा विश्व माटो दिवस मनाइन्छ।\nनोट: सन् १९७० देखि पृथ्वी दिवस मनाउन थालिएको हो।', 'nepali'),
      (v_set_id, 15, E'अन्तर्राष्ट्रिय शिक्षा दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ?', E'जनवरी २१', E'जनवरी २२', E'जनवरी २३', E'जनवरी २४', 'D', E'अन्तर्राष्ट्रिय शिक्षा दिवस प्रत्येक वर्ष **जनवरी २४** मा मनाइन्छ। संयुक्त राष्ट्र महासभाले सन् २०१८ को डिसेम्बर ३ मा यो दिवस मनाउने प्रस्ताव पारित गरेको थियो र पहिलो पटक सन् २०१९ मा मनाइएको थियो।\nनोट: नेपालमा भने राष्ट्रिय शिक्षा दिवस हरेक वर्ष असोज २ गते मनाइन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/२२', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_23.csv  →  आसमान दैनिक GK — २०८२/१२/२३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/२३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/२३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/२३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको आर्थिक इतिहासमा पहिलोपटक बजेटको व्यवस्था कहिले भएको थियो?', E'वि.सं. २००८', E'वि.सं. २०१३', E'वि.सं. २०१८', E'वि.सं. २०२२', 'A', E'नेपालको आर्थिक इतिहासमा पहिलोपटक बजेटको व्यवस्था **वि.सं. २००८** मा भएको थियो। यो बजेट २००८ माघ २१ मा घोषणा गरिएको थियो, जसमा आयतर्फ रु. ३.०५ करोड र व्ययतर्फ रु. ५.२५ करोड अनुमान गरिएको थियो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधान बमोजिम सम्मानपूर्वक बाँच्न पाउने हक कसलाई प्राप्त हुन्छ?', E'प्रत्येक व्यक्तिलाई', E'प्रत्येक नागरिकलाई', E'हरेक व्यक्तिलाई', E'सबै नागरिकलाई', 'A', E'नेपालको संविधानले **प्रत्येक व्यक्तिलाई** सम्मानपूर्वक बाँच्न पाउने हकको प्रत्याभूति गरेको छ। यो हक मौलिक हक अन्तर्गत पर्दछ र यो नागरिक वा गैर-नागरिक सबैलाई समान रूपमा लागू हुन्छ।', 'nepali'),
      (v_set_id, 3, E'शुक्र पछि पृथ्वीबाट सबैभन्दा नजिकमा रहेको ग्रह कुन हो?', E'बुध', E'बृहस्पति', E'शनि', E'मंगल', 'D', E'शुक्र पछि पृथ्वीबाट सबैभन्दा नजिकमा रहेको ग्रह **मंगल** हो।\n- बुध सूर्यबाट सबैभन्दा नजिकको ग्रह हो।\n- बृहस्पति सौर्यमण्डलको सबैभन्दा ठूलो ग्रह हो।\n- शनि ग्रह आफ्नो वरिपरि रहेको सुन्दर चक्र (ring) को लागि परिचित छ।\nनोट: पृथ्वीबाट ग्रहहरूको दूरीको क्रम शुक्र, मंगल, बुध, बृहस्पति, शनि, अरुण र वरुण हो।', 'nepali'),
      (v_set_id, 4, E'दक्षिण अमेरिकाको अग्लो शिखर माउन्ट एकान्कागुआ कुन मुलुकको सिमानामा रहेको छ?', E'अर्जेन्टिना र पेरु', E'अर्जेन्टिना र ब्राजिल', E'पेरु र चिली', E'अर्जेन्टिना र चिली', 'D', E'दक्षिण अमेरिकाको अग्लो शिखर माउन्ट एकान्कागुआ **अर्जेन्टिना र चिलीको** सिमानामा रहेको छ।\nनोट: यो एन्डिज पर्वतमालाको सबैभन्दा अग्लो भाग हो, जसको उचाइ ६,९६२ मिटर छ।', 'nepali'),
      (v_set_id, 5, E'देहायका मध्ये कुन केन्द्र चितवन जिल्लामा रहेको छैन?', E'हात्ती प्रजनन केन्द्र', E'गिद्ध प्रजनन केन्द्र', E'चमेरा संरक्षण क्षेत्र', E'जैविक विविधता सूचना केन्द्र', 'C', E'**चमेरा संरक्षण क्षेत्र कपिलवस्तु जिल्लाको देवानगढियामा रहेको छ।**\n- हात्ती प्रजनन केन्द्र चितवनको मेघौलीमा अवस्थित छ।\n- गिद्ध प्रजनन केन्द्र चितवनको कसरामा रहेको छ।\n- जैविक विविधता सूचना केन्द्र चितवनको टिकौलीमा अवस्थित छ।', 'nepali'),
      (v_set_id, 6, E'नेपालको संघीय संसदको प्रतिनिधि सभामा प्रत्यक्षतर्फ २ जनाका दरले निर्वाचित हुने जिल्लाको संख्या कति छ?', E'२६', E'२१', E'२०', E'३५', 'B', E'संघीय संसदको प्रतिनिधि सभामा प्रत्यक्षतर्फ २ जनाका दरले निर्वाचित हुने जिल्लाको संख्या **२१** रहेको छ।\n| निर्वाचन क्षेत्र संख्या | जिल्ला संख्या |\n| --- | --- |\n| १ | ३५ |\n| २ | २१ |\n| ३ | १९ |\n| ४ | ३ |\n| ५ | १ |\n| ६ | १ |\n| १० | १ |', 'nepali'),
      (v_set_id, 7, E'मिश्रको समयमा पिरामिडको खास अर्थ के हो?', E'राजाहरुको चिहान', E'सत्यको बाटो', E'शान्तीको सुरु', E'धार्मिक स्थल', 'A', E'प्राचीन मिश्रमा पिरामिडहरू **राजाहरूको चिहान (Tomb)** को रूपमा बनाइन्थ्यो।\nनोट: गिजामा रहेको खुफु राजाको पिरामिड विश्वकै सबैभन्दा ठूलो पिरामिड हो, जुन बनाउन १ लाख मजदुरलाई २० वर्ष लागेको थियो।', 'nepali'),
      (v_set_id, 8, E'संगित सँग सम्बन्धित ६८ औं ग्रामी अवार्ड २०२६ मा वर्षको उत्कृष्ट गितको उपाधी कुनलाई प्रदान गरिएको छ ?', E'wildflower', E'Beginning', E'The fact', E'Bad bunny', 'A', E'**६८ औं ग्रामी अवार्ड २०२६ मा वर्षको उत्कृष्ट गीतको उपाधि बिली एलिशको ''वाइल्ड फ्लावर'' (wildflower) ले जितेको थियो।**\n- वर्षको उत्कृष्ट रेकर्ड: केन्ड्रिक लामारको SZA - लुथर\n- वर्षको उत्कृष्ट एल्वम: डेबी तिरारको Bad bunny\n- सर्वश्रेष्ठ नयाँ कलाकार: ओलिभिया डीन', 'nepali'),
      (v_set_id, 9, E'माइक्रोसफ्ट एआई रिपोर्ट, २०२५ अनुसार नेपाल कति औं स्थानमा रहेको छ ?', E'७५ औं', E'७६ औं', E'७७ औं', E'७८ औं', 'B', E'माइक्रोसफ्ट एआई रिपोर्ट, २०२५ अनुसार नेपाल **७६ औं** स्थानमा रहेको छ। उक्त रिपोर्ट अनुसार नेपालको AI अपनाउने दर १३% रहेको छ।\nनोट: AI अपनाउने दरमा शीर्ष स्थानमा यूएई (६४.०%) र अन्तिम (१४७ औं) स्थानमा कम्बोडिया (५.१%) रहेका छन्।', 'nepali'),
      (v_set_id, 10, E'आर्थिक वर्ष २०८२/८३ को बजेटका उद्देश्य कति वटा रहेका छन्?', E'तीन वटा', E'चार वटा', E'पाँच वटा', E'छ वटा', 'C', E'आर्थिक वर्ष २०८२/८३ को बजेटका **पाँच वटा** उद्देश्य रहेका छन्।\nती उद्देश्यहरू निम्न छन्:\n- १. उच्च दिगो एवं फराकिलो आर्थिक वृद्धि हासिल गरी गरिबी निवारण गर्ने\n- २. उद्यमशीलता विकास र सार्वजनिक तथा निजी लगानी विस्तार गरी रोजगारी सिर्जना गर्ने\n- ३. आधुनिक प्रविधिको प्रयोग बढाउँदै आर्थिक दक्षता वृद्धि गर्ने\n- ४. सामाजिक संरक्षण एवं विकासका माध्यमबाट सामाजिक न्याय कायम गर्ने\n- ५. गुणस्तरीय सार्वजनिक सेवा र सुशासन प्रवर्द्धन गर्ने।', 'nepali'),
      (v_set_id, 11, E'नेपालको पहिलो पटक युरोप भ्रमण गरेका प्रधानमन्त्री जंग बहादुर राणाले कहिले युरोप भ्रमण गरेका थिए?', E'वि.सं. १९०४', E'वि.सं. १९०६', E'वि.सं. १९०८', E'वि.सं. १९१०', 'B', E'नेपालका पहिलो युरोप भ्रमण गर्ने प्रधानमन्त्री जंग बहादुर राणाले **वि.सं. १९०६** मा बेलायतको भ्रमण गरेका थिए।\nनोट: उनी वि.सं. १९०६ देखि १९०७ सम्म युरोप भ्रमणमा रहँदा बम बहादुर राणाले कार्यवाहक प्रधानमन्त्रीको जिम्मेवारी सम्हालेका थिए।', 'nepali'),
      (v_set_id, 12, E'विज्ञानसँग सम्बन्धित प्रमुख वेद कुन हो?', E'ऋग्वेद', E'सामवेद', E'यजुर्वेद', E'अथर्ववेद', 'D', E'**अथर्ववेद** विज्ञान, विशेषगरी अर्थ विज्ञान र औषधी विज्ञानसँग सम्बन्धित वेद हो।\n- ऋग्वेद सबैभन्दा पुरानो र ठूलो वेद हो, जसमा जाति व्यवस्थाको वर्णन पाइन्छ।\n- सामवेद सबैभन्दा सानो र प्रसिद्ध वेद हो, जसबाट संगीतको उत्पत्ति भएको मानिन्छ।\n- यजुर्वेद कर्मकाण्डसँग सम्बन्धित प्रमुख वेद हो।\nनोट: अथर्ववेदलाई सबैभन्दा नवीनतम वेद पनि मानिन्छ।', 'nepali'),
      (v_set_id, 13, E'सामान्य मानिसमा एक हातमा पाँच औंला हुनु पर्नेमा ६ वटा औंला देखायो। यस्तो परिणाम आउनुको कारण के होला?', E'क्रमविकास', E'वंशानुगत', E'परिवृत्ति', E'उत्परिवर्तन', 'D', E'सामान्यतया पाँच औंला हुनुपर्नेमा छ वटा देखिनु **उत्परिवर्तन (Mutation)** को परिणाम हो।\n- क्रमविकास लामो समयमा हुने जैविक परिवर्तनको प्रक्रिया हो।\n- वंशानुगत गुणहरू पुस्तान्तरण हुने प्रक्रिया हो, जस्तै बुवाको कपाल छिटो झर्ने भए छोराको पनि छिटो झर्नु।\n- परिवृत्ति (Variation) एउटै दम्पतीका सन्तानमा देखिने भिन्नता हो, जस्तै कोही अग्लो, कोही होचो हुनु।\nनोट: उत्परिवर्तन जीवको DNA मा आउने अचानक परिवर्तन हो।', 'nepali'),
      (v_set_id, 14, E'सार्कको अवधारणा ल्याउने व्यक्ति कुन मुलुकका नागरिक हुन?', E'बंगलादेश', E'नेपाल', E'भारत', E'भुटान', 'A', E'सार्कको अवधारणा ल्याउने व्यक्ति **बंगलादेशका** तत्कालीन राष्ट्रपति जियाउल रहमान हुन्।\nनोट: उनले सन् १९८० मे २ मा यो अवधारणा प्रस्तुत गरेका थिए र सार्कको स्थापना ८ डिसेम्बर १९८५ मा ढाकामा भएको थियो।', 'nepali'),
      (v_set_id, 15, E'सन् २००९ अक्टोबर १६ मा समुद्रमुनी मन्त्रिपरिषदको बैठक गरी कुन राष्ट्रले विश्व समुदायलाई कार्बन ग्यास कटौतीको आह्वान गरेको थियो?', E'चीन', E'भारत', E'अमेरिका', E'माल्दिभ्स', 'D', E'सन् २००९ अक्टोबर १६ मा **माल्दिभ्सले** समुद्रमुनी मन्त्रिपरिषदको बैठक आयोजना गरी विश्व समुदायलाई कार्बन ग्यास कटौतीको आह्वान गरेको थियो। जलवायु परिवर्तनको असरबाट सामुद्रिक क्षेत्रमा परेको प्रभाव र साना तथा जलपरिवेष्ठित मुलुकमा पर्ने नकारात्मक असरबारे विश्वको ध्यानाकर्षण गराउनु यस बैठकको मुख्य उद्देश्य थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/२३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_25.csv  →  आसमान दैनिक GK — २०८२/१२/२५  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/२५'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/२५';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/२५', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'शुन्यमा आधारित बजेटको अर्थ के हो?', E'नयाँ आधारमा बजेट तयार पार्नु', E'पुरानो बजेटलाई बढाउनु', E'बजेट घटाउनु', E'कर बढाउनु', 'A', E'शुन्यमा आधारित बजेट (Zero-Based Budgeting) भन्नाले विगतका खर्चहरूलाई बेवास्ता गरी **नयाँ आधारमा बजेट तयार पार्ने** प्रक्रियालाई बुझिन्छ। यसमा हरेक कार्यक्रम वा क्रियाकलापको आवश्यकता र औचित्यको आधारमा शून्यबाटै मूल्यांकन गरिन्छ।', 'nepali'),
      (v_set_id, 2, E'प्रत्येक नागरिकलाई खाद्य सम्बन्धी हक हुनेछ। भन्ने कुरा नेपालको संविधानको कुन धारामा उल्लेख गरिएको छ?', E'धारा ३५', E'धारा ३६', E'धारा ३७', E'धारा ३८', 'B', E'**नेपालको संविधानको धारा ३६ मा प्रत्येक नागरिकलाई खाद्य सम्बन्धी हकको व्यवस्था गरिएको छ।**\n- धारा ३५ मा स्वास्थ्य सम्बन्धी हकको व्यवस्था छ।\n- धारा ३७ मा आवासको हकको व्यवस्था गरिएको छ।\n- धारा ३८ मा महिलाको हक सम्बन्धी व्यवस्था उल्लेख छ।\nनोट: धारा ३६ अनुसार, प्रत्येक नागरिकलाई खाद्यवस्तुको अभावमा जीवन जोखिममा पर्ने अवस्थाबाट सुरक्षित हुने हक पनि हुनेछ।', 'nepali'),
      (v_set_id, 3, E'एका तर्फ चिसो र अर्को तर्फ तातो हुने ग्रह कुन हो?', E'शुक्र', E'बुध', E'पृथ्वी', E'मंगल', 'B', E'**बुध ग्रहको एकातर्फ चिसो र अर्कोतर्फ तातो हुन्छ।** वायुमण्डल नभएका कारण सूर्यतिर फर्केको भाग अत्यधिक तातो र सूर्यबाट लुकेको भाग अत्यधिक चिसो हुन्छ।\n- शुक्र ग्रह सौर्यमण्डलको सबैभन्दा तातो ग्रह हो र यसलाई ''Morning Star'' र ''Evening Star'' पनि भनिन्छ।\n- पृथ्वीलाई ''निलो ग्रह'' (Blue Planet) भनिन्छ।\n- मंगल ग्रहलाई ''रातो ग्रह'' (Red Planet) को नामले चिनिन्छ।', 'nepali'),
      (v_set_id, 4, E'विश्वको लगभग कति प्रतिशत जमिनको भूभागमा घाँसे मैदान रहेको छ?', E'१० प्रतिशत', E'२० प्रतिशत', E'३० प्रतिशत', E'४० प्रतिशत', 'D', E'विश्वको जमिनको भूभागको लगभग **४० प्रतिशत** हिस्सा घाँसे मैदानले ओगटेको छ। यी मैदानहरूमा रूखहरूको सट्टा घाँस प्रमुख वनस्पतिको रूपमा पाइन्छ।', 'nepali'),
      (v_set_id, 5, E'काठमाडौं उपत्यकाको क्षेत्रफल कति रहेको छ?', E'६४२ वर्ग कि.मि.', E'६६६ वर्ग कि.मि.', E'५४२ वर्ग कि.मि.', E'३४२ वर्ग कि.मि.', 'A', E'काठमाडौं उपत्यकाको क्षेत्रफल **६४२ वर्ग कि.मि.** रहेको छ।\n- सुर्खेत उपत्यकाको क्षेत्रफल ४१ वर्ग कि.मि. छ।\n- पोखरा उपत्यकाको क्षेत्रफल १२४ वर्ग कि.मि. छ।\n- दाङ उपत्यकाको क्षेत्रफल १००० वर्ग कि.मि. रहेको छ।', 'nepali'),
      (v_set_id, 6, E'गुराँस हिमश्रृंखला अन्तर्गत कुन हिमाल पर्छ?', E'गणेश', E'चामर', E'अपि', E'तिलिचो', 'C', E'गुराँस हिमश्रृंखला अन्तर्गत **अपि हिमाल** पर्दछ।\nनोट: अपि हिमाल दार्चुला जिल्लामा अवस्थित छ र यसको उचाइ ७,१३२ मिटर (२३,३९९ फिट) रहेको छ।', 'nepali'),
      (v_set_id, 7, E'हाल नेपालको राष्ट्रिय गौरवका आयोजनाहरू मध्ये कति जलविद्युत आयोजनाहरू रहेका छन् ?', E'४ वटा', E'३ वटा', E'२ वटा', E'५ वटा', 'A', E'हाल नेपालका राष्ट्रिय गौरवका आयोजनाहरूमध्ये **४ वटा** जलविद्युत आयोजनाहरू रहेका छन्। कुल २७ राष्ट्रिय गौरवका आयोजनाहरू कार्यान्वयनमा छन्।\nनोट: अन्य प्रमुख क्षेत्रहरूमा राजमार्ग (६ वटा), सिँचाइ (६ वटा), र विमानस्थल (३ वटा) आयोजनाहरू पर्दछन्।', 'nepali'),
      (v_set_id, 8, E'विश्व क्यान्सर दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'फेब्रुअरी १', E'फेब्रुअरी २', E'फेब्रुअरी ३', E'फेब्रुअरी ४', 'D', E'विश्व क्यान्सर दिवस प्रत्येक वर्ष **फेब्रुअरी ४** मा मनाइन्छ। यो दिवस सन् २००० देखि मनाउन थालिएको हो।\nनोट: सन् २०२६ को क्यान्सर दिवसको नारा ''United by Unique'' थियो।', 'nepali'),
      (v_set_id, 9, E'सोह्रौं योजनाको अन्त्य सम्म प्रतिव्यक्ति विद्युत उपभोग कति पुर्याउने लक्ष्य रहेको छ?', E'५०० किलोवाट घण्टा', E'६०० किलोवाट घण्टा', E'७०० किलोवाट घण्टा', E'८०० किलोवाट घण्टा', 'C', E'सोह्रौं योजनाको अन्त्यसम्ममा प्रतिव्यक्ति विद्युत उपभोग **७०० किलोवाट घण्टा** पुर्याउने लक्ष्य रहेको छ।\nनोट: सोही योजनाले श्रम उत्पादकत्व २७५ हजार रुपैयाँ र कृषि वस्तुको औसत उत्पादकत्व ३.७ मे.ट. प्रति हेक्टर पुर्याउने लक्ष्य पनि लिएको छ।', 'nepali'),
      (v_set_id, 10, E'चित्राक्षर लिपि सर्वप्रथम कुन सभ्यताबाट विकास भएको हो?', E'मिश्रको सभ्यता', E'युनानी सभ्यता', E'मेसोपोटामिया सभ्यता', E'सिन्धुघाँटीको सभ्यता', 'A', E'चित्राक्षर लिपिको विकास सर्वप्रथम **मिश्रको सभ्यताबाट** भएको हो। मिश्र सभ्यतामा मन्दिर तथा पिरामिडमा लेखिने यस लिपिलाई हायरोग्लिफिक (Hieroglyphic) भनिन्थ्यो।', 'nepali'),
      (v_set_id, 11, E'सबैभन्दा कम उमेरमा प्रधानमन्त्री भएका नेपालका प्रधानमन्त्री को हुन्?', E'जंग ब राणा', E'देव समसेर', E'मोहन समसेर', E'भिमसेन थापा', 'A', E'**जंगबहादुर राणा** नेपालको सबैभन्दा कम उमेरमा (२८ वर्ष) प्रधानमन्त्री बनेका थिए।\n- देव समसेर सबैभन्दा छोटो कार्यकाल (११४ दिन) भएका राणा प्रधानमन्त्री हुन्।\n- मोहन समसेर नेपालका अन्तिम राणा प्रधानमन्त्री थिए।\n- भिमसेन थापा नेपालका प्रथम तथा सबैभन्दा लामो समयसम्म सेवा गर्ने प्रधानमन्त्री (मुख्तियार) मानिन्छन्।', 'nepali'),
      (v_set_id, 12, E'ऋग्वेदमा सबैभन्दा धेरै कुन देवताको प्रशंसा गरिएको छ?', E'गायत्री', E'सुर्य', E'इन्द्र', E'जल/नदी', 'C', E'ऋग्वेदमा सबैभन्दा धेरै प्रशंसा **इन्द्र** देवताको गरिएको छ।\nनोट: ऋग्वेदमा पाइने पहिलो मन्त्र गायत्री मन्त्र हो, जसमा सूर्य देवताको प्रशंसा गरिएको छ।', 'nepali'),
      (v_set_id, 13, E'स्वास्थ्य कार्यक्रम समावेश कुन योजनाबाट सुरु भएको थियो?', E'आठौं योजना', E'सातौं योजना', E'छैटौं योजना', E'पाँचौं योजना', 'D', E'**स्वास्थ्य कार्यक्रम पाँचौं पञ्चवर्षीय योजनाबाट** समावेश हुन सुरु भएको थियो।\n- छैटौं योजनामा वातावरण नीति आएको थियो।\n- सातौं योजनाबाट वातावरणीय प्रभाव मूल्याङ्कन (EIA) को सुरुवात भयो।\n- आठौं योजनाबाट दिगो विकासको अवधारणा सुरु भएको थियो।', 'nepali'),
      (v_set_id, 14, E'हाल सार्कको अध्यक्षता कुन मुलुकले गरिरहेको छ?', E'बंगलादेश', E'नेपाल', E'भारत', E'भुटान', 'B', E'हाल सार्कको अध्यक्षता **नेपालले** गरिरहेको छ। सार्कको नियम अनुसार, जुन मुलुकमा शिखर सम्मेलन आयोजना हुन्छ, अर्को सम्मेलन नभएसम्म सोही मुलुक अध्यक्ष रहन्छ। सन् २०१४ मा १८औं शिखर सम्मेलन काठमाडौंमा आयोजना भएयता अर्को सम्मेलन हुन सकेको छैन।', 'nepali'),
      (v_set_id, 15, E'समुन्द्रमुनी मन्त्रीपरिषदको बैठक कुन महासागरमा आयोजना भएको हो?', E'प्रशान्त महासागर', E'आन्ध्र महासागर', E'हिन्द महासागर', E'कुमेरु महासागर', 'C', E'समुन्द्रमुनी मन्त्रीपरिषदको बैठक **हिन्द महासागरमा** आयोजना गरिएको थियो। जलवायु परिवर्तनको असरबारे सचेतना जगाउन माल्दिभ्सले हिन्द महासागरको २० फुट (६ मिटर) मुनि यो बैठक आयोजना गरेको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/२५', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_27.csv  →  आसमान दैनिक GK — २०८२/१२/२७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/२७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/२७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/२७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'१६ औं योजनाको अन्त्य सम्म नेपालको आर्थिक वृद्धिदर कति पुऱ्याउने लक्ष्य रहेको छ?', E'७.१ प्रतिशत', E'७.५ प्रतिशत', E'७.३ प्रतिशत', E'१०.५ प्रतिशत', 'C', E'१६ औं योजनाको अन्त्यसम्म नेपालको आर्थिक वृद्धिदर **७.३ प्रतिशत** पुऱ्याउने लक्ष्य रहेको छ।\n- ७.१ प्रतिशत सोह्रौं योजनाले लिएको औसत आर्थिक वृद्धि दरको लक्ष्य हो।\n- १०.५ प्रतिशत आगामी २५ वर्षे अर्थात् आ.व. २१००/०१ सम्मको आर्थिक वृद्धिदरको लक्ष्य हो।\nनोट: सोह्रौं योजनाको आधार वर्ष २०७९/८० मा आर्थिक वृद्धि ३.५% रहेको थियो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधानको कुन धारा अनुसार प्रत्येक उपभोक्तालाई गुणस्तरीय वस्तु तथा सेवा प्राप्त गर्ने हक हुनेछ?', E'धारा ४३', E'धारा ४४', E'धारा ४५', E'धारा ४६', 'B', E'नेपालको संविधानको **धारा ४४** अनुसार प्रत्येक उपभोक्तालाई गुणस्तरीय वस्तु तथा सेवा प्राप्त गर्ने हक हुनेछ।\n- धारा ४३ मा सामाजिक सुरक्षाको हकको व्यवस्था छ।\n- धारा ४५ मा देश निकाला विरुद्धको हकको व्यवस्था गरिएको छ।\n- धारा ४६ मा संवैधानिक उपचारको हकको व्यवस्था छ।\nनोट: गुणस्तरहीन वस्तु वा सेवाबाट क्षति पुगेको व्यक्तिलाई कानुन बमोजिम क्षतिपूर्ति पाउने हक पनि यसै धारा अन्तर्गत पर्दछ।', 'nepali'),
      (v_set_id, 3, E'पृथ्वी सौर्यमण्डलको कति औं सानो ग्रह हो?', E'तेस्रो', E'पाँचौ', E'छैटौं', E'चौथो', 'D', E'आकारको हिसाबले पृथ्वी सौर्यमण्डलको **चौथो** सानो ग्रह हो। यो सूर्यबाट तेस्रो नजिकको ग्रह हो र सौर्यमण्डलको पाँचौ ठूलो ग्रह पनि हो।\nनोट: सौर्यमण्डलका ग्रहहरूलाई आकारको आधारमा सानोबाट ठूलो क्रममा राख्दा बुध, मंगल, शुक्र, पृथ्वी, वरुण, अरुण, शनि र बृहस्पति पर्दछन्।', 'nepali'),
      (v_set_id, 4, E'दक्षिण अमेरिका महादेशमा फैलिएको घाँसे मैदानलाई के भनिन्छ?', E'डाउन्स', E'स्टेप्स', E'भेल्ड', E'पम्पाज', 'D', E'दक्षिण अमेरिका महादेशमा फैलिएको घाँसे मैदानलाई **पम्पाज** भनिन्छ।\n- डाउन्स अस्ट्रेलियामा पाइने घाँसे मैदान हो।\n- स्टेप्स एसिया र युरोप महादेशमा पाइने घाँसे मैदान हो।\n- भेल्ड अफ्रिकामा पाइने घाँसे मैदान हो।\nनोट: उत्तर अमेरिकामा पाइने घाँसे मैदानलाई प्रेयरी भनिन्छ।', 'nepali'),
      (v_set_id, 5, E'विश्वको सबैभन्दा गहिरो उपत्यका कुन हो?', E'ताराकोट', E'नुब्री', E'अरुण', E'सिञ्जा', 'C', E'**विश्वको सबैभन्दा गहिरो उपत्यका अरुण उपत्यका हो, जुन संखुवासभा जिल्लामा पर्दछ।**\n- ताराकोट उपत्यका डोल्पा जिल्लामा पर्दछ।\n- नुब्री उपत्यका गोरखा जिल्लामा पर्दछ।\n- सिञ्जा उपत्यका जुम्ला जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 6, E'देहायका मध्ये कुन नेपाली हिमालको हिमशृङ्खला अन्नपूर्ण हो?', E'मनास्लु', E'माछापुच्छ्रे', E'धौलागिरी', E'गौरिशंकर', 'B', E'**माछापुच्छ्रे हिमाल अन्नपूर्ण हिमशृङ्खलामा पर्दछ।**\n- मनास्लु हिमाल गणेश हिमशृङ्खलामा पर्दछ।\n- धौलागिरी हिमाल धौलागिरी हिमशृङ्खलामा पर्दछ।\n- गौरिशंकर हिमाल रोल्वालिङ हिमशृङ्खलामा पर्दछ।', 'nepali'),
      (v_set_id, 7, E'G-7 समूहमा समावेश नभएको देश कुन हो?', E'जापान', E'क्यानडा', E'चीन', E'इटाली', 'C', E'**चीन G-7 समूहमा समावेश छैन।**\n- जापान, क्यानडा र इटाली G-7 समूहका सदस्य राष्ट्रहरू हुन्।\nनोट: G-7 का सदस्य राष्ट्रहरूमा अमेरिका, बेलायत, फ्रान्स, जर्मनी, इटाली, क्यानडा र जापान पर्दछन्। चीन G-20 समूहको सदस्य हो।', 'nepali'),
      (v_set_id, 8, E'कुन देशले २०२६ को ICC महिला T-20 विश्वकप छनोट प्रतियोगिता आयोजना गरेको थियो?', E'भारत', E'नेपाल', E'श्रीलंका', E'बंगलादेश', 'B', E'**नेपालले २०२६ को ICC महिला T-20 विश्वकप छनोट प्रतियोगिता आयोजना गरेको थियो।** यो प्रतियोगिता २०२६ जनवरी १८ देखि फेब्रुअरी १ सम्म आयोजना भएको थियो र यसको उपाधि बंगलादेशले जितेको थियो।', 'nepali'),
      (v_set_id, 9, E'सोह्रौं योजनाको लिएका उद्देश्य कतिवटा रहेका छन्?', E'२ वटा', E'३ वटा', E'४ वटा', E'५ वटा', 'B', E'सोह्रौं योजनाले **३ वटा** उद्देश्य लिएको छ।\n- ती उद्देश्यहरूमा सुशासन कायम गर्नु, सामाजिक न्याय स्थापित गर्नु, र मानवीय जीवन र राष्ट्रिय अर्थतन्त्रमा समृद्धि हासिल गर्नु पर्दछन्।', 'nepali'),
      (v_set_id, 10, E'मिश्रको सभ्यतामा राजालाई दैवी सिद्धान्तको देन भन्ने विश्वास मानिन्थ्यो भने राजालाई के भनिन्थ्यो?', E'हाड', E'जार', E'फारोह', E'चिहान', 'C', E'**मिश्रको सभ्यतामा राजालाई फारोह भनिन्थ्यो र उनीहरूलाई दैवी सिद्धान्तको देन मानिन्थ्यो।**\n- जार रुसका सम्राटहरूलाई दिइने उपाधि थियो।\n- हाड र चिहान मिश्रको सभ्यतासँग सम्बन्धित शब्दहरू भए तापनि राजाको उपाधि होइनन्।\nनोट: मिश्रको सभ्यतामा कागज, कलम र मसीको आविष्कार सर्वप्रथम भएको मानिन्छ।', 'nepali'),
      (v_set_id, 11, E'दुई पैसाको टिकट वितरण सुरु कुन राणा प्रधानमन्त्रीको पाला देखि भएको थियो?', E'जुद्ध समसेर', E'वीर समसेर', E'भिम समसेर', E'रणोदिप सिंह', 'D', E'दुई पैसाको टिकट वितरण **रणोदिप सिंहको** पालामा सुरु भएको थियो।\n- जुद्ध समसेरको पालामा १९९० सालको महाभूकम्प गएको थियो र उनले भूकम्प पीडितोद्धारको काम गरेका थिए।\n- वीर समसेरले वीर अस्पताल, घण्टाघर र वीर पुस्तकालयको स्थापना गरेका थिए।\n- भिम समसेरले शनिबार बिदा दिने र कार्यालय समय १० देखि ५ बजेसम्म कायम गर्ने चलन चलाएका थिए।\nनोट: रणोदिप सिंहकै पालामा हुलाक घरको स्थापना, मालपोत उठाउने नयाँ बन्दोबस्त र तेजारथ अड्डाको स्थापना भएको थियो।', 'nepali'),
      (v_set_id, 12, E'भगवान राम बस्ने स्थान कुन हो?', E'वैकुण्ठ', E'साकेत', E'कैलाश', E'चित्रकूट', 'B', E'**भगवान राम बस्ने स्थानलाई साकेत भनिन्छ।**\n- वैकुण्ठ भगवान विष्णु बस्ने स्थान हो।\n- कैलाश भगवान शिव बस्ने स्थान हो।\n- चित्रकूट राम वनवास गएको समयमा बसेको वन हो।\nनोट: सामान्यतया देवीदेवताहरूको वासस्थान सुमेरु पर्वतलाई मानिन्छ।', 'nepali'),
      (v_set_id, 13, E'विश्व स्वास्थ्य सङ्गठन (World Health Organization) को प्रधान कार्यालय कहाँ रहेको छ?', E'रोम', E'जेनेभा', E'न्युयोर्क', E'लन्डन', 'B', E'विश्व स्वास्थ्य सङ्गठन (WHO) को प्रधान कार्यालय स्विट्जरल्याण्डको **जेनेभामा** रहेको छ।\n- रोममा खाद्य तथा कृषि सङ्गठन (FAO) को मुख्यालय छ।\n- न्युयोर्कमा संयुक्त राष्ट्र संघ (UN) को मुख्यालय अवस्थित छ।\n- लन्डनमा अन्तर्राष्ट्रिय सामुद्रिक सङ्गठन (IMO) को मुख्यालय रहेको छ।\nनोट: विश्व स्वास्थ्य सङ्गठनको स्थापना ७ अप्रिल १९४८ मा भएको थियो र नेपालले १० मे १९५४ मा यसको सदस्यता लिएको थियो।', 'nepali'),
      (v_set_id, 14, E'सार्क मुलुकहरू मध्ये नेपाल क्षेत्रफलका आधारमा कति औं ठूलो मुलुक हो?', E'छैटौं', E'चौथो', E'पाँचौं', E'तेस्रो', 'C', E'क्षेत्रफलको आधारमा सार्क मुलुकहरू मध्ये नेपाल **पाँचौं** ठूलो मुलुक हो।\nसार्क मुलुकहरूको क्षेत्रफलको आधारमा ठूलो देखि सानोको क्रम यसप्रकार छ:\n१. भारत\n२. पाकिस्तान\n३. अफगानिस्तान\n४. बंगलादेश\n५. नेपाल\n६. श्रीलंका\n७. भुटान\n८. माल्दिभ्स', 'nepali'),
      (v_set_id, 15, E'मन्त्रीपरिषद् बैठक कालापत्थर के सँग सम्बन्धित रहेको छ?', E'Population Conference', E'Global warming', E'Greenhouse effect', E'Climate change', 'D', E'मन्त्रीपरिषद्को कालापत्थर बैठक **जलवायु परिवर्तन (Climate change)** सँग सम्बन्धित छ। विश्व समुदायको ध्यान आकर्षण गर्न वि.सं. २०६६ मंसिर १९ गते सगरमाथाको आधार शिविर कालापत्थरमा यो ऐतिहासिक बैठक बसेको थियो।\nनोट: उक्त बैठक तत्कालिन प्रधानमन्त्री माधव कुमार नेपालको अध्यक्षतामा सम्पन्न भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/२७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2082_12_29.csv  →  आसमान दैनिक GK — २०८२/१२/२९  (9 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८२/१२/२९'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८२/१२/२९';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८२/१२/२९', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाललाई लोडसेडिङ मुक्त घोषणा कहिले गरियो?', E'वि.सं. २०६५', E'वि.सं. २०६८', E'वि.सं. २०७५', E'वि.सं. २०७८', 'C', E'नेपाललाई **वि.सं. २०७५ वैशाख ३१** मा लोडसेडिङ मुक्त घोषणा गरिएको थियो।\nनोट: नेपालमा ऊर्जा संकटको घोषणा भने वि.सं. २०६५ पौष १० मा ५ वर्षका लागि गरिएको थियो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधानको पालना गर्नु प्रत्येक ........ को कर्तव्य हो।', E'व्यक्ति', E'नागरिक', E'जनता', E'सर्वसाधारण', 'A', E'नेपालको संविधानको भाग-१ (प्रारम्भिक) को धारा १(२) मा ''यस संविधानको पालना गर्नु प्रत्येक **व्यक्तिको** कर्तव्य हुनेछ'' भनी उल्लेख गरिएको छ।\nनोट: सोही धाराको उपधारा (१) अनुसार, यो संविधान नेपालको मूल कानून हो र यससँग बाझिने कानून बाझिएको हदसम्म अमान्य हुनेछ।', 'nepali'),
      (v_set_id, 3, E'सौर्यमण्डलको सबैभन्दा टाढाको क्षेत्र कुन हो।', E'क्विपर बेल्ट', E'वरुण', E'उर्ट क्लाउड', E'यम', 'C', E'**उर्ट क्लाउड हाम्रो सौर्यमण्डलको सबैभन्दा टाढाको क्षेत्र हो।**\n- क्विपर बेल्ट अरुण र वरुण ग्रह बाहिरको बरफको क्षेत्र हो, जुन सूर्यबाट लगभग ३० देखि ५० एस्ट्रोनोमिकल युनिट (AU) को दूरीमा अवस्थित छ।\n- वरुण (Neptune) सौर्यमण्डलको आठौं र सूर्यबाट सबैभन्दा टाढाको ग्रह हो।\n- यम (Pluto) क्विपर बेल्टमा अवस्थित एक फुच्चे ग्रह (dwarf planet) हो।', 'nepali'),
      (v_set_id, 4, E'WHO (विश्व स्वास्थ्य संगठन) का हालका महानिर्देशक को हुन्?', E'बान कि मुन', E'टेड्रोस अधानोम', E'एन्टोनियो गुटेरेस', E'अजय बंगा', 'B', E'**टेड्रोस अधानोम विश्व स्वास्थ्य संगठन (WHO) का हालका महानिर्देशक हुन्।**\n- बान कि मुन संयुक्त राष्ट्र संघका आठौं महासचिव थिए।\n- एन्टोनियो गुटेरेस संयुक्त राष्ट्र संघका वर्तमान (नवौं) महासचिव हुन्।\n- अजय बंगा विश्व बैंक समूहका वर्तमान अध्यक्ष हुन्।\nनोट: टेड्रोस अधानोमको दोस्रो ५-वर्षे कार्यकाल सन् २०२२ अगस्त १६ देखि सुरु भएको हो।', 'nepali'),
      (v_set_id, 5, E'शिख धर्मको प्रमुख धार्मिक ग्रन्थ कुन हो?', E'गुरु ग्रन्थ', E'त्रिपिटक', E'कुरान', E'बचनामृत', 'A', E'शिख धर्मको प्रमुख धार्मिक ग्रन्थ **गुरु ग्रन्थ** हो, जसलाई ''गुरु ग्रन्थ साहिब'' पनि भनिन्छ।\n- त्रिपिटक बौद्ध धर्मको प्रमुख ग्रन्थ हो।\n- कुरान इस्लाम धर्मको प्रमुख ग्रन्थ हो।\n- बचनामृत जैन धर्मको प्रमुख ग्रन्थ हो।', 'nepali'),
      (v_set_id, 6, E'ताङवे जातिको मुख्य बसोबास जिल्ला कुन हो?', E'मुनाडु', E'मुस्ताङ', E'मुगु', E'डोल्पा', 'B', E'ताङवे जातिको मुख्य बसोबास **मुस्ताङ जिल्ला** हो। मुस्ताङको घुसाङ ताङवे गाउँलाई यिनीहरूको मूल थलो मानिन्छ।\nनोट: ताङवे जातिमा जेठो छोराले बिहे गरेको श्रीमतीलाई सबै भाइहरूले श्रीमती स्वीकार गर्नुपर्ने बहुपति प्रथा प्रचलनमा रहेको छ।', 'nepali'),
      (v_set_id, 7, E'मानव शरीरमा रगतमा रहेको तरल पदार्थलाई के भनिन्छ?', E'ल्युकोसाइटिस', E'हेमोग्लोविन', E'क्युबिक', E'प्लाज्मा', 'D', E'मानव शरीरमा रगतमा रहेको तरल पदार्थलाई **प्लाज्मा** भनिन्छ। यसले रक्तकोषहरूलाई पोषण प्रदान गर्ने र पौष्टिक पदार्थहरूलाई तन्तुहरूसम्म पुऱ्याउने कार्य गर्दछ।\n- ल्युकोसाइटिस भनेको रगतमा सेतो रक्तकोषको संख्या बढ्ने अवस्था हो।\n- हेमोग्लोविन रातो रक्तकोषमा पाइने एक प्रोटिन हो जसले रगतलाई रातो रंग दिन्छ र अक्सिजन बोक्छ।\n- क्युबिक एक ज्यामितीय आकार हो, रगतको अंश होइन।', 'nepali'),
      (v_set_id, 8, E'अन्टार्र्टिकामा कुन महादेशको आकाशमा ओजोन तहमा प्वाल परेको तथ्य पत्ता लागेको हो?', E'अन्टार्कटिका', E'युरोप', E'अस्ट्रेलिया', E'उत्तर अमेरिका', 'A', E'**अन्टार्कटिका** महादेशको आकाशमा ओजोन तहमा प्वाल परेको तथ्य पत्ता लागेको हो। वैज्ञानिकहरूले अन्टार्कटिकामाथि फेला पारेको यो प्वाललाई ''Holy Way'' नाम दिएका छन्।\nनोट: सन् १९८६ मा पत्ता लागेको यो प्वालको मुख्य कारण क्लोरोफ्लोरोकार्बन (CFCs) जस्ता ग्यासहरू हुन्।', 'nepali'),
      (v_set_id, 9, E'UNO सदस्यता प्राप्त गर्ने पहिलो सार्क मुलुक भारत हो भने अन्तिम मुलुक कुन हो?', E'बंगलादेश', E'श्रीलंका', E'पाकिस्तान', E'भुटान', 'A', E'संयुक्त राष्ट्र संघ (UNO) को सदस्यता प्राप्त गर्ने अन्तिम सार्क मुलुक **बंगलादेश** हो। भारत UNO को सदस्यता प्राप्त गर्ने पहिलो सार्क राष्ट्र हो।\nनोट: सार्क राष्ट्रहरूले UNO को सदस्यता प्राप्त गरेको क्रम: भारत, अफगानिस्तान, पाकिस्तान, नेपाल, श्रीलंका, माल्दिभ्स, भुटान र अन्त्यमा बंगलादेश।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८२/१२/२९', 9;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_03.csv  →  आसमान दैनिक GK — २०८३/०१/०३  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/०३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/०३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/०३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'साफ यू-२० च्याम्पियनसिप २०२६ को विजेता राष्ट्र कुन हो ?', E'भारत', E'नेपाल', E'बंगलादेश', E'माल्दिभ्स', 'C', E'साफ यू-२० च्याम्पियनसिप २०२६ को विजेता राष्ट्र **बंगलादेश** हो।\n- भारत उक्त च्याम्पियनसिपको उपविजेता बनेको थियो।\n- नेपाल प्रतियोगितामा सहभागी ७ टोलीहरू मध्ये एक थियो।\n- माल्दिभ्सले उक्त च्याम्पियनसिपको आयोजना गरेको थियो।\nनोट: यो प्रतियोगिता २३ मार्च देखि ३ अप्रिल २०२६ सम्म माल्दिभ्सको मालेमा आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 2, E'नेपालमा e-Pension Verification (ई-पेन्सन प्रमाणीकरण प्रणाली) शुभारम्भ कहिले देखि भएको छ ?', E'२०८२ चैत २२', E'२०८२ चैत २४', E'२०८२ चैत २७', E'२०८२ चैत २९', 'C', E'नेपालमा e-Pension Verification (ई-पेन्सन प्रमाणीकरण प्रणाली) को शुभारम्भ **वि.सं. २०८२ चैत २७** गते भएको हो। यो प्रणालीको शुभारम्भ तत्कालीन अर्थमन्त्री डा. स्वर्णिम वाग्लेले महालेखा नियन्त्रक कार्यालय, काठमाडौँबाट गरेका थिए।\nनोट: यो प्रणाली सुरुवात हुँदा नेपालका प्रधानमन्त्री बालेन्द्र शाह थिए।', 'nepali'),
      (v_set_id, 3, E'वनस्पति दिवस, २०८२ को नारा देहाएका मध्ये कुन हो ?', E'समृद्धिका लागि वनस्पति', E'समृद्धिको आधार वनस्पति', E'वनस्पतिबाट उज्ज्वल भविष्य', E'वनस्पति बाट समृद्धि', 'A', E'वनस्पति दिवस, २०८२ को नारा ''**समृद्धिका लागि वनस्पति**'' रहेको थियो। यो दिवस हरेक वर्ष चैत २९ गते मनाइन्छ र २०८२ मा यसको २७औं संस्करण मनाइएको थियो।\nनोट: यसै अवसरमा प्रदान गरिने राष्ट्रिय वनस्पति पुरस्कार २०८२ प्रा.डा. सुरेश कुमार घिमिरेलाई प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 4, E'लोक सेवा आयोगहरूको छैटौं राष्ट्रिय सम्मेलन, २०८२ कहाँ सम्पन्न भएको छ ?', E'कास्की, पोखरा', E'सुर्खेत, विरेन्द्रनगर', E'मोरङ, विराटनगर', E'रुपन्देही, लुम्बिनी', 'A', E'लोक सेवा आयोगहरूको **छैटौं राष्ट्रिय सम्मेलन कास्की, पोखरामा** सम्पन्न भएको छ।\n- सुर्खेत, विरेन्द्रनगरमा चौथो राष्ट्रिय सम्मेलन (२०८०) भएको थियो।\n- मोरङ, विराटनगरमा पाँचौ राष्ट्रिय सम्मेलन (२०८१) भएको थियो।\n- रुपन्देही, लुम्बिनीमा दोस्रो राष्ट्रिय सम्मेलन (२०७८) भएको थियो।\nनोट: सातौं राष्ट्रिय सम्मेलन २०८३ मा मधेस प्रदेशमा हुने तय भएको छ।', 'nepali'),
      (v_set_id, 5, E'२०८२ सालमा कति औं सहकारी दिवस मनाइएको छ ?', E'६७ औं', E'६८ औं', E'६९ औं', E'७० औं', 'C', E'२०८२ सालमा **६९ औं** राष्ट्रिय सहकारी दिवस मनाइएको छ।\nनोट: नेपालको पहिलो सहकारी संस्था, बखान सहकारी संस्था, चितवनमा २०१३ साल चैत २० गते स्थापना भएको दिनको सम्झनामा हरेक वर्ष चैत २० गते यो दिवस मनाइन्छ।', 'nepali'),
      (v_set_id, 6, E'विश्वकै कान्छी उपसभामुखको रुपमा प्रतिनिधि सभाको नयाँ उपसभामुखमा रुबीकुमारी ठाकुर कहिले निर्वाचित भइन् ?', E'२०८२ चैत २२', E'२०८२ चैत २४', E'२०८२ चैत २७', E'२०८२ चैत २९', 'C', E'प्रतिनिधि सभाको नयाँ उपसभामुखमा रुबीकुमारी ठाकुर **२०८२ चैत २७** गते निर्वाचित भएकी हुन्।\nनोट: उनी श्रम संस्कृति पार्टीकी उम्मेदवार हुन् र उनले २२९ मत प्राप्त गरेकी थिइन्। उनी नेपालको १३ औं उपसभामुख हुन्।', 'nepali'),
      (v_set_id, 7, E'विश्वकै सबैभन्दा ठूलो डिजिटल अभ्यास को रुपमा हालसालै कुन मुलुकमा पूर्ण डिजिटल (कागजविहीन) जनगणना सुरु भएको छ ?', E'चीन', E'अमेरिका', E'भारत', E'जापान', 'C', E'**भारतले** विश्वकै सबैभन्दा ठूलो डिजिटल अभ्यासको रुपमा पूर्ण डिजिटल (कागजविहीन) जनगणना सुरु गरेको छ।\nनोट: यो जनगणना २०२६ अप्रिल १ देखि सुरु भएको हो र भारत हाल विश्वकै सबैभन्दा धेरै जनसंख्या भएको मुलुक हो।', 'nepali'),
      (v_set_id, 8, E'भारतीय गायिका आशा भोसलेको निधन कहिले भएको हो ?', E'२०२६ अप्रिल ११', E'२०२६ अप्रिल १२', E'२०२६ अप्रिल १३', E'२०२६ अप्रिल १४', 'B', E'भारतीय प्रसिद्ध गायिका आशा भोसलेको निधन **२०२६ अप्रिल १२** (वि.सं. २०८२ चैत्र २९) मा भएको हो।\nनोट: उनको ९२ वर्षको उमेरमा मुम्बईको ब्रीच क्यान्डी अस्पतालमा निधन भएको थियो। उनले ''मोहनी लाग्ला है'' जस्ता चर्चित नेपाली गीतहरू पनि गाएकी छिन्।', 'nepali'),
      (v_set_id, 9, E'हालसालै नेपालकै पहिलो नमूना सफा तथा स्वच्छ गाउँपालिकाको रूपमा कुन स्थानीय तहलाई घोषणा गरिएको छ ?', E'धुलिखेल न.पा.', E'सुनवल न.पा.', E'बैजनाथ गा.पा.', E'ज्वालामुखी गा.पा.', 'D', E'**ज्वालामुखी गाउँपालिका, धादिङलाई** नेपालकै पहिलो नमूना सफा तथा स्वच्छ गाउँपालिकाको रूपमा घोषणा गरिएको छ।\n- धुलिखेल नगरपालिकालाई नेपालको पहिलो स्वस्थ सहर (२०८१ भदौ १२) घोषणा गरिएको थियो।\n- सुनवल नगरपालिका नेपालको पहिलो बालमैत्री नगरपालिका (२०७२ जेठ ३२) हो।\nनोट: यो घोषणा २०८२ चैत २९ मा सम्माननीय सभामुख डोलप्रसाद अर्यालले गर्नुभएको थियो।', 'nepali'),
      (v_set_id, 10, E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या कति पुगेको छ?', E'४५ वटा', E'४६ वटा', E'४७ वटा', E'४८ वटा', 'D', E'गोरखापत्रमा समाचार प्रकाशन हुने भाषाको संख्या **४८ वटा** पुगेको छ। पछिल्लो पटक वि.सं. २०८३ वैशाख १ देखि सन्थाल (४७ औं) र हायु (४८ औं) भाषामा समाचार प्रकाशन सुरु गरिएको हो।\nनोट: गोरखापत्रले वि.सं. २०६४ असोज १ गतेबाट विभिन्न मातृभाषामा समाचार प्रकाशन गर्न थालेको हो।', 'nepali'),
      (v_set_id, 11, E'हालसालै देहायको कुन दक्षिण पूर्वी एसियाली मुलुकमा ऊर्जा संकटकाल घोषणा भएको हो?', E'फिलिपिन्स', E'मलेसिया', E'थाइल्याण्ड', E'इण्डोनेसिया', 'A', E'हालसालै दक्षिण पूर्वी एसियाली मुलुक **फिलिपिन्समा** ऊर्जा संकटकाल घोषणा गरिएको छ। फिलिपिन्सका राष्ट्रपति फर्डिनान्ड मार्कोस जुनियरले सन् २०२६ मार्च २४ मा राष्ट्रिय ऊर्जा संकटकालको घोषणा गरेका हुन्।', 'nepali'),
      (v_set_id, 12, E'राष्ट्रिय भेटेरिनरी सम्मेलन, २०२६ कुन जिल्लामा आयोजना भएको छ?', E'कास्की', E'रुपन्देही', E'ललितपुर', E'चितवन', 'B', E'१६ औं राष्ट्रिय भेटेरिनरी सम्मेलन, २०२६ **रुपन्देही** जिल्लाको मणिग्राममा आयोजना भएको छ। नेपाल भेटेरिनरी एशोसियसनको आयोजनामा यो सम्मेलन २०८२ चैत २४ र २५ गते सम्पन्न भएको थियो।\nनोट: सम्मेलनको मुख्य नारा "दिगो पशुधन र खाद्य सुरक्षाको लागि स्वास्थ्य" रहेको थियो।', 'nepali'),
      (v_set_id, 13, E'आर्थिक सर्वेक्षण २०८१/८२ अनुसार हाल नेपालमा जम्मा राष्ट्रिय गौरवको आयोजना कति रहेको छन् ?', E'२४ वटा', E'२५ वटा', E'२६ वटा', E'२७ वटा', 'D', E'आर्थिक सर्वेक्षण २०८१/८२ अनुसार हाल नेपालमा जम्मा राष्ट्रिय गौरवको आयोजनाको संख्या **२७ वटा** रहेको छ। आर्थिक वर्ष २०८०/८१ मा ३ वटा क्रिकेट रंगशालालाई राष्ट्रिय गौरवको आयोजनामा समावेश गर्ने निर्णय भएपछि यो संख्या २७ पुगेको हो।\nनोट: थप भएका आयोजनाहरूमा मुलपानी, गौतम बुद्ध अन्तर्राष्ट्रिय र गिरिजाप्रसाद कोइराला क्रिकेट रंगशाला रहेका छन्।', 'nepali'),
      (v_set_id, 14, E'नवौं हिन्द महासागर सम्मेलन २०२६ कहाँ आयोजना भएको छ ?', E'मौरिसस', E'ओमान', E'भारत', E'नेपाल', 'A', E'नवौं हिन्द महासागर सम्मेलन २०२६ **मौरिससमा** आयोजना भएको थियो।\n- ओमानको मस्कटमा आठौं हिन्द महासागर सम्मेलन २०२५ आयोजना भएको थियो।', 'nepali'),
      (v_set_id, 15, E'वरिष्ठ कलाकार सुनिल थापाको निधन देहाएका मध्ये कुन मितिमा भएको हो ?', E'२०८२ माघ २४', E'२०८२ जेठ १८', E'२०८२ वैशाख २३', E'२०८२ वैशाख १०', 'A', E'वरिष्ठ कलाकार सुनिल थापाको निधन **२०८२ माघ २४** गते भएको हो।\n- २०८२ जेठ १८ मा गायक तथा संगीतकार गणेश रसिकको निधन भएको थियो।\n- २०८२ वैशाख २३ मा पूर्वमन्त्री एवं साहित्यकार प्रदीप नेपालको निधन भएको थियो।\n- २०८२ वैशाख १० मा पूर्वप्रहरी महानिरीक्षक दुर्लभकुमार थापाको निधन भएको थियो।', 'nepali'),
      (v_set_id, 16, E'मर्स्याङ्दी जलविद्युत आयोजना कुन जिल्लामा सञ्चालित छ?', E'गुल्मी', E'लमजुङ', E'स्याङ्जा', E'तनहुँ', 'D', E'**मर्स्याङ्दी जलविद्युत आयोजना तनहुँ जिल्लामा सञ्चालित छ।**\n- लमजुङ जिल्लामा मध्य-मर्स्याङ्दी जलविद्युत आयोजना सञ्चालित छ।\n- स्याङ्जा जिल्लामा नेपालको कालीगण्डकी ''ए'' जलविद्युत आयोजना (१४४ मेगावाट) रहेको छ।\n- गुल्मी जिल्लामा रिडी खोला जलविद्युत आयोजना छ।\nनोट: मर्स्याङ्दी जलविद्युत आयोजनाको क्षमता ६९ मेगावाट हो।', 'nepali'),
      (v_set_id, 17, E'सार्वभौमसत्ता र राजकीयसत्ता सँग सम्बन्धित व्यवस्था नेपालको संविधानको कुन धारामा उल्लेख रहेको छ?', E'धारा १', E'धारा २', E'धारा ३', E'धारा ४', 'B', E'**नेपालको संविधानको धारा २ मा सार्वभौमसत्ता र राजकीयसत्ता नेपाली जनतामा निहित रहने व्यवस्था गरिएको छ।**\n- धारा १ ले संविधानलाई मूल कानुनको रूपमा स्थापित गरेको छ।\n- धारा ३ मा राष्ट्रसम्बन्धी परिभाषा र व्यवस्था उल्लेख छ।\n- धारा ४ मा नेपाल राज्यको परिभाषा र स्वरूपबारे व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 18, E'बाहिरी ग्रहहरू मध्ये सबैभन्दा धेरै घनत्व भएको ग्रह कुन हो?', E'शनि', E'अरुण', E'वरुण', E'पृथ्वी', 'C', E'**बाहिरी ग्रहहरूमध्ये सबैभन्दा बढी घनत्व भएको ग्रह वरुण हो।**\n- शनि सौर्यमण्डलकै सबैभन्दा कम घनत्व भएको ग्रह हो।\n- अरुण बाहिरी ग्रहहरूमध्ये तेस्रो बढी घनत्व भएको ग्रह हो।\n- पृथ्वी सौर्यमण्डलको सबैभन्दा बढी घनत्व भएको ग्रह हो, तर यो एक भित्री ग्रह हो, बाहिरी होइन।', 'nepali'),
      (v_set_id, 19, E'सन् २०२७ मा कुन देशमा दक्षिण एसियाली खेलकुद (साग) आयोजना हुने भएको छ ?', E'पाकिस्तान', E'भारत', E'नेपाल', E'बंगलादेश', 'A', E'**१४औं दक्षिण एसियाली खेलकुद (साग) पाकिस्तानमा आयोजना हुने तय भएको छ।**\n- भारतले सन् २०१६ मा १२औं साग, नेपालले सन् २०१९ मा १३औं साग र बंगलादेशले सन् २०१० मा ११औं साग आयोजना गरेको थियो।', 'nepali'),
      (v_set_id, 20, E'२०२६ मा मनाइएको सिमसार दिवस कति औं हो ?', E'२९ औं', E'३० औं', E'३१ औं', E'३२ औं', 'B', E'**३० औं संस्करण।**\n- विश्व सिमसार दिवस (World Wetlands Day) हरेक वर्ष फेब्रुअरी २ मा मनाइन्छ र सन् १९९७ देखि मनाउन सुरु गरिएको हो।', 'nepali'),
      (v_set_id, 21, E'१६ औं योजनाले मुख्य प्राथमिकतामा राखेको २ विषय कुन कुन हुन्?', E'डिजिटल डाटाबेस र ई-गर्भनेन्स', E'सुशासन र सबल लोकतन्त्र', E'स्वस्थ र सन्तुलित पर्यावरण', E'राष्ट्रिय एकता, सुरक्षा र सम्मान', 'A', E'१६ औं योजनाले मुख्य प्राथमिकतामा **डिजिटल डाटाबेस र ई-गर्भनेन्स** लाई राखेको छ।\nनोट: यस योजनाको कुल अनुमानित लागत रु. १११ खर्ब ८४ अर्ब २३ करोड रहेको छ, जसमा सार्वजनिक, निजी र सहकारी क्षेत्रको लगानी समावेश छ।', 'nepali'),
      (v_set_id, 22, E'दक्षिणी ध्रुविय महासागरको उपनामले कुन महासागरलाई चिनिन्छ?', E'सुमेरु महासागर', E'हिन्द महासागर', E'प्रशान्त महासागर', E'कुमेरु महासागर', 'D', E'**दक्षिणी ध्रुविय महासागरको उपनामले कुमेरु महासागरलाई चिनिन्छ।**\n- सुमेरु महासागर उत्तरी ध्रुवमा अवस्थित छ।\n- हिन्द महासागर विश्वको तेस्रो ठूलो महासागर हो।\n- प्रशान्त महासागर विश्वको सबैभन्दा ठूलो महासागर हो।\nनोट: अन्टार्कटिका महादेशलाई घेरेर रहेको कुमेरु महासागर विश्वको चौथो ठूलो महासागर हो।', 'nepali'),
      (v_set_id, 23, E'क्षेत्रफलका हिसाबले सबैभन्दा सानो उपमहानगरपालिका देहाएका मध्ये कुन हो?', E'नेपालगन्ज', E'धरान', E'धनगढी', E'इटहरी', 'A', E'क्षेत्रफलका हिसाबले नेपालका ११ उपमहानगरपालिकाहरूमध्ये सबैभन्दा सानो **नेपालगन्ज (बाँके)** हो।\nनोट: क्षेत्रफलको आधारमा सबैभन्दा ठूलो उपमहानगरपालिका घोराही (दाङ) हो।', 'nepali'),
      (v_set_id, 24, E'"मेरो रगत फ्रान्सको समृद्धिको कारण बनोस्, राष्ट्र चिरञ्जीवी रहोस्" यो भनाइ कसको हो?', E'केटलबी', E'रुसो', E'भोल्तेयर', E'लुई सोह्रौं', 'D', E'**लुई सोह्रौं** ले मृत्युदण्ड दिनुभन्दा अघि "मेरो रगत फ्रान्सको समृद्धिको कारण बनोस्, राष्ट्र चिरञ्जीवी रहोस्" भनेका थिए। उनलाई सन् १७९३ जनवरी २१ मा गिलेटिनले काटेर मृत्युदण्ड दिइएको थियो।', 'nepali'),
      (v_set_id, 25, E'नेपालको प्रथम वैज्ञानिक गेहेन्द्र सम्सेर कसको नाती हुन्?', E'चन्द्र समसेर', E'धीर समसेर', E'मोहन समसेर', E'वीर समसेर', 'B', E'नेपालका प्रथम वैज्ञानिक गेहेन्द्र सम्सेर **धीर सम्सेरका** नाति थिए।\n- चन्द्र सम्सेरले गेहेन्द्र सम्सेरको हत्या गराएका थिए।\n- मोहन सम्सेर नेपालका अन्तिम राणा प्रधानमन्त्री थिए।\n- वीर सम्सेर गेहेन्द्र सम्सेरका पिता थिए।', 'nepali'),
      (v_set_id, 26, E'माङ्हिम, सिलौटी कुन धर्मको धार्मिक स्थल हुन्?', E'किराँत धर्म', E'शिख धर्म', E'यहुदी धर्म', E'जैन धर्म', 'A', E'**माङ्हिम र सिलौटी किराँत धर्मका धार्मिक स्थलहरू हुन्।**\n- शिख धर्मको धार्मिक स्थललाई गुरुद्वारा भनिन्छ।\n- यहुदी धर्मको धार्मिक स्थल सिनागग हो।\n- जैन धर्मको धार्मिक स्थललाई जैन मन्दिर भनिन्छ।', 'nepali'),
      (v_set_id, 27, E'पुष १५ गते मनाइने तमु ल्होसार कुन जाति प्रचलित रहेको?', E'तामाङ', E'शेर्पा', E'नेवार', E'गुरुङ', 'D', E'**पुष १५ गते मनाइने तमु ल्होसार गुरुङ जातिमा प्रचलित रहेको छ।**\n- तामाङ जातिले सोनाम ल्होसार मनाउँछन्।\n- शेर्पा जातिले ग्याल्पो ल्होसार, डुम्जी र फाङडी ल्होसो जस्ता पर्वहरू मनाउँछन्।\n- नेवार समुदायको प्रमुख चाड नेपाल संवत् अनुसारको नयाँ वर्ष (म्ह पूजा) हो।\nनोट: गुरुङ समुदायले तमु ल्होसारलाई नयाँ वर्षको रूपमा मनाउँछन् र उनीहरुको प्रमुख पर्वमा ट्होटे पर्व पनि पर्दछ।', 'nepali'),
      (v_set_id, 28, E'रक्तनली (Blood vessels) कति प्रकारका रहेका हुन्छन्?', E'२ भाग', E'३ भाग', E'४ भाग', E'५ भाग', 'B', E'मानव शरीरमा रक्तनलीहरू मुख्यतया **३ प्रकारका** रहेका हुन्छन्।\n- ती धमनी (Artery), सिरा (Veins), र रक्तकेशिका (Capillaries) हुन्।', 'nepali'),
      (v_set_id, 29, E'ओजोनोस्फेयरको उपनामले वायुमण्डलको कुन तहलाई चिनिन्छ?', E'निम्न मण्डल', E'समताप मण्डल', E'मध्य मण्डल', E'तापीय मण्डल', 'B', E'**ओजोनोस्फेयरको उपनामले वायुमण्डलको समताप मण्डल (Stratosphere) लाई चिनिन्छ।**\n- निम्न मण्डल (Troposphere) वायुमण्डलको सबैभन्दा तल्लो तह हो, जहाँ मौसमसम्बन्धी घटनाहरू हुन्छन्।\n- मध्य मण्डल (Mesosphere) समताप मण्डल भन्दा माथिको तह हो।\n- तापीय मण्डल (Thermosphere) वायुमण्डलको सबैभन्दा बाहिरी तह हो।\nनोट: ओजोन तहले सूर्यबाट आउने हानिकारक पराबैजनी (UV) विकिरणलाई सोसेर पृथ्वीको जीवन रक्षा गर्दछ।', 'nepali'),
      (v_set_id, 30, E'नेपालको आर्थिक वर्ष सुरुवात साउन १ बाट हुन्छ भने छिमेकी मुलुक भारतमा आर्थिक वर्ष सुरुवात कुन तारिखबाट हुन्छ?', E'जनवरी १', E'जुलाई १', E'अक्टोबर १', E'जुन १', 'B', E'**छिमेकी मुलुक भारतमा आर्थिक वर्षको सुरुवात जुलाई १ बाट हुन्छ।**\n- श्रीलंकामा आर्थिक वर्ष जनवरी १ बाट सुरु हुन्छ।\n- माल्दिभ्समा आर्थिक वर्ष अक्टोबर १ बाट सुरु हुन्छ।\n- जुन १ कुनै पनि सार्क मुलुकको आर्थिक वर्ष सुरुवातको मिति होइन।\nनोट: भारतका साथै बंगलादेश, पाकिस्तान र भुटानको आर्थिक वर्ष पनि जुलाई १ बाटै सुरु हुन्छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/०३', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_06.csv  →  आसमान दैनिक GK — २०८३/०१/०६  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/०६'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/०६';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/०६', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'निजी क्षेत्रको सबैभन्दा ठूलो जलविद्युत आयोजना सोलुखोलाको विद्युत उत्पादन क्षमता कति रहेको छ?', E'९३ मेगावाट', E'६० मेगावाट', E'८६ मेगावाट', E'७४ मेगावाट', 'C', E'निजी क्षेत्रको सबैभन्दा ठूलो जलविद्युत आयोजना सोलुखोला (दुधकोशी) को विद्युत उत्पादन क्षमता **८६ मेगावाट** रहेको छ। यो आयोजना सोलुखुम्बु जिल्लामा अवस्थित छ।\nनोट: यस आयोजनाको उद्घाटन प्रधानमन्त्री पुष्प कमल दाहाल ''प्रचण्ड''ले २०७९ फागुन २३ गते गर्नुभएको थियो।', 'nepali'),
      (v_set_id, 2, E'नेपालको संविधानको कुन धारामा गैरआवासीय नेपाली नागरिकता सम्बन्धि व्यवस्था रहेको छ?', E'धारा १४', E'धारा २', E'धारा १२', E'धारा ११', 'A', E'**नेपालको संविधानको धारा १४ मा गैरआवासीय नेपाली नागरिकता प्रदान गर्न सकिने व्यवस्था रहेको छ।**\n- धारा १२ मा वंशीय आधार तथा लैंगिक पहिचान सहितको नागरिकताको व्यवस्था छ।\n- धारा ११ मा अंगीकृत तथा सम्मानार्थ नागरिकता सम्बन्धी व्यवस्थाहरू छन्।', 'nepali'),
      (v_set_id, 3, E'सबैभन्दा थोरै उपग्रह भएको ग्रह कुन हो?', E'शुक्र', E'बुध', E'पृथ्वी', E'मंगल', 'C', E'**पृथ्वीको एकमात्र प्राकृतिक उपग्रह चन्द्रमा रहेको छ।**\n- शुक्र र बुध ग्रहका कुनै पनि उपग्रह छैनन्।\n- मंगल ग्रहका फोबोस र डिमोस गरी दुईवटा उपग्रह छन्।', 'nepali'),
      (v_set_id, 4, E'WHO ले हालसालै सतर्क रहन आव्हान गरेको निपाह भाइरस पहिलो पटक कहाँ पहिचान गरिएको थियो?', E'भारत', E'बंगलादेश', E'मलेसिया', E'नेपाल', 'C', E'विश्व स्वास्थ्य संगठन (WHO) ले सतर्क रहन आव्हान गरेको निपाह भाइरस पहिलो पटक **मलेसियामा** पहिचान गरिएको थियो।\n- भारतको पश्चिम बंगालमा २०२६ जनवरीमा यो भाइरस देखा परेको थियो।\n- बंगलादेशमा पनि समय-समयमा निपाह भाइरसको प्रकोप देखिने गरेको छ।\n- नेपालमा भने हालसम्म निपाह भाइरसको पुष्टि भएको छैन।\nनोट: निपाह भाइरस पहिलो पटक सन् १९९८-९९ मा मलेसियामा फैलिएको प्रकोपको समयमा पहिचान गरिएको थियो।', 'nepali'),
      (v_set_id, 5, E'राष्ट्रपति रामचन्द्र पौडेलले २०८६ फेब्रुअरी मा कुन देशको औपचारिक भ्रमणमा गएका छन्?', E'चीन', E'भारत', E'जापान', E'म्यानमार', 'C', E'राष्ट्रपति रामचन्द्र पौडेलले **जापानको** चारदिने औपचारिक भ्रमण गर्नुभएको थियो।\n- नेपाल र जापान बीचको कुटनैतिक सम्बन्ध स्थापना भएको ७० औं वर्षगाँठको अवसरमा फेब्रुअरी २०२६ मा यो भ्रमण भएको थियो।\nनोट: भ्रमणको क्रममा राष्ट्रपति पौडेललाई ''गार्ड अफ अनर'' प्रदान गरिएको थियो।', 'nepali'),
      (v_set_id, 6, E'दीर्घकालीन सोच, २१०० अन्तर्गत लिएका दीर्घकालीन राष्ट्रिय लक्ष्य कति वटा रहेका छन्?', E'१० वटा', E'२० वटा', E'३० वटा', E'४० वटा', 'A', E'नेपालको दीर्घकालीन सोच ''समृद्ध नेपाल, सुखी नेपाली'' (वि.सं. २१००) अन्तर्गत जम्मा **१० वटा** राष्ट्रिय लक्ष्यहरू निर्धारण गरिएको छ।\n- यी लक्ष्यहरूलाई समृद्धितर्फ ४ वटा र सुखतर्फ ६ वटा गरी दुई मुख्य समूहमा विभाजन गरिएको छ।', 'nepali'),
      (v_set_id, 7, E'सबैभन्दा अन्तिममा गहिरो बिन्दु पहिचान भएको महासागर कुन हो?', E'सुमेरु महासागर', E'हिन्द महासागर', E'प्रशान्त महासागर', E'कुमेरु महासागर', 'D', E'सबैभन्दा अन्तिममा गहिरो बिन्दु पहिचान भएको महासागर **कुमेरु महासागर** (Southern Ocean) हो।\n- सुमेरु महासागरको सबैभन्दा गहिरो भाग मोलय डिप (Molloy Deep) हो।\n- हिन्द महासागरको सबैभन्दा गहिरो भाग जाभा ट्रेन्च (Java Trench) हो।\n- प्रशान्त महासागरको मारियाना ट्रेन्च (Mariana Trench) विश्वकै सबैभन्दा गहिरो बिन्दु हो।\nनोट: कुमेरु महासागरको सबैभन्दा गहिरो भाग साउथ स्याण्डवीच ट्रेन्च (७,२३४ मि.) हो, जुन सन् २०१९ मा पत्ता लागेको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपालको भूगोलमा सबैभन्दा ठूलो गाउँपालिका अवस्थित जिल्ला कुन हो?', E'अर्घाखाँची', E'डोल्पा', E'मनाङ', E'हुम्ला', 'D', E'**नेपालको सबैभन्दा ठूलो गाउँपालिका नाम्खा हुम्ला जिल्लामा अवस्थित छ।**\n- अर्घाखाँची जिल्लामा नेपालको सबैभन्दा ठूलो नगरपालिका, सितगंगा, पर्दछ।\n- डोल्पा जिल्लामा नेपालको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज, शे-फोक्सुण्डो, रहेको छ।\n- मनाङ जिल्लामा सबैभन्दा कम जनसंख्या भएको गाउँपालिका, नार्फुभूमि, अवस्थित छ।\nनोट: क्षेत्रफलको हिसाबले सबैभन्दा सानो गाउँपालिका बारा जिल्लाको परवानीपुर हो।', 'nepali'),
      (v_set_id, 9, E'फ्रान्सको किसानहरूले आफ्नो आम्दानीको कति प्रतिशत कर तिर्नु पर्दथ्यो?', E'६० प्रतिशत', E'७० प्रतिशत', E'८० प्रतिशत', E'९० प्रतिशत', 'C', E'फ्रान्सेली क्रान्ति अघि, किसानहरूले आफ्नो आम्दानीको **८० प्रतिशत** सम्म कर तिर्नुपर्ने अवस्था थियो। यो कर चर्च र राज्य दुवैलाई बुझाउनु पर्थ्यो, जबकि चर्चले भने राज्यलाई कर तिर्नु पर्दैनथ्यो।', 'nepali'),
      (v_set_id, 10, E'नेपाली इतिहासमा "कार्यालय समय फागुनदेखि कार्तिक सम्म १०-५ र मंसिरदेखि माघसम्म १०-४ बनाउने" निर्धारण कसले गरेका हुन?', E'देवशमशेर', E'विरशमशेर', E'भीमशमशेर', E'पद्मशमशेर', 'D', E'**पद्मशमशेरले कार्यालय समयलाई फागुनदेखि कार्तिकसम्म १०-५ र मंसिरदेखि माघसम्म १०-४ निर्धारण गरेका थिए।**\n- देवशमशेरले सरकारी कार्यालय समय १०-५ बजे निर्धारण गरेका थिए।\n- भीमशमशेरले कार्यालय समय १०-४ र शुक्रबार आधा दिन बिदा दिने चलन चलाएका थिए।\n- विरशमशेरले नेपालमा पहिलो पटक खानेपानीको व्यवस्था गरेका थिए।', 'nepali'),
      (v_set_id, 11, E'लामा, पाञ्चेन कुन धर्म विशेषसँग सम्बन्धित रहेको छ?', E'बौद्ध', E'शिख', E'जैन', E'हिन्दु', 'A', E'**लामा र पाञ्चेन बौद्ध धर्मसँग सम्बन्धित धार्मिक पदहरू हुन्।**\n- शिख धर्मका धार्मिक प्रमुखलाई गुरु वा सतगुरु भनिन्छ।\n- जैन धर्मका अनुयायीहरूले तीर्थंकरहरूलाई मान्दछन्।\n- हिन्दु धर्ममा गुरु, पुरोहित, ऋषि, पण्डित र मुनि जस्ता धार्मिक व्यक्तित्वहरू हुन्छन्।', 'nepali'),
      (v_set_id, 12, E'गुरुङ समुदायका मानिसहरूको मृत्यु भएपछि गरिने काजक्रिया लाई के भनिन्छ?', E'पाते', E'अर्घौं', E'लामा', E'घ्याप्रिङ', 'B', E'**गुरुङ समुदायमा मृत्युपछि गरिने काजक्रियालाई अर्घौं भनिन्छ।**\n- पाते गुरुङ जातिको पहिलो चलचित्रको नाम हो।\n- लामा र घ्याप्रिङ गुरुङ समुदायका धार्मिक कार्यहरू सम्पन्न गर्ने पुरोहितहरू हुन्।', 'nepali'),
      (v_set_id, 13, E'मानव शरिरको रगतमा रक्तकोष कति प्रतिशत रहेको हुन्छ?', E'५० प्रतिशत', E'४५ प्रतिशत', E'५५ प्रतिशत', E'७५ प्रतिशत', 'B', E'मानव शरीरको रगतमा रक्तकोषको मात्रा लगभग **४५ प्रतिशत** हुन्छ। रगतको बाँकी ५५ प्रतिशत हिस्सा प्लाज्माले ओगटेको हुन्छ।\nनोट: एक स्वस्थ वयस्क व्यक्तिको शरीरमा औसतमा करिब साढे पाँच लिटर रगत हुन्छ।', 'nepali'),
      (v_set_id, 14, E'सर्वप्रथम क्लोरोफ्लोरोकार्बन ग्याँसको उत्पादन गर्ने वैज्ञानिक को हुन्?', E'जे सि फारम्यान', E'शेरउड रोल्याण्ड', E'डोब्सन', E'थोमस मिज', 'D', E'सर्वप्रथम क्लोरोफ्लोरोकार्बन (CFC) ग्याँसको उत्पादन गर्ने वैज्ञानिक **डा. थोमस मिज** हुन्।\n- जे. सि. फारम्यानले सर्वप्रथम ओजन तह पत्ता लगाएका थिए।\n- शेरउड रोल्याण्डले सर्वप्रथम ओजन तह पातलिँदै गएको पत्ता लगाएका थिए।\n- डोब्सनले सर्वप्रथम ओजन विनाश दर पत्ता लगाएका थिए।\nनोट: डा. थोमस मिजले सन् १९३० मा चिस्याउने ग्याँसको रुपमा क्लोरोफ्लोरोकार्बन पत्ता लगाएका थिए।', 'nepali'),
      (v_set_id, 15, E'नेपालको अतिरिक्त कुन सार्क मुलुकको राष्ट्रिय खेल भलिबल हो?', E'भारत', E'श्रीलंका', E'पाकिस्तान', E'भुटान', 'B', E'नेपालको अतिरिक्त **श्रीलंकाको** राष्ट्रिय खेल भलिबल हो।\n- भारत र पाकिस्तान दुवैको राष्ट्रिय खेल हकी हो।\n- भुटानको राष्ट्रिय खेल धनुषवाण हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/०६', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_07.csv  →  आसमान दैनिक GK — २०८३/०१/०७  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/०७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/०७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/०७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपालको कुन योजनादेखि वातावरण संरक्षण नीति तथा अवधारणालाई समावेश गरिएको हो?', E'छैटौं योजनाबाट', E'सातौं योजनाबाट', E'आठौं योजनाबाट', E'नवौं योजनाबाट', 'A', E'नेपालमा **छैटौं योजना (२०४२-२०४७)** देखि वातावरण संरक्षण नीति तथा अवधारणालाई समावेश गर्न थालिएको हो।\nनोट: यही योजनाबाट निजीकरण, विकासमा महिला सहभागिता, र विकेन्द्रीकरण जस्ता अवधारणाहरू पनि सुरु भएका थिए।', 'nepali'),
      (v_set_id, 2, E'देहायका मध्ये नेपालको सम्मानार्थ नागरिकता प्राप्त गर्ने अन्तिम व्यक्ति को हुन्?', E'टोनी हेगन', E'एडमन्ड हिलारी', E'उम होंग गिल', E'कोलिन स्मिथ', 'C', E'**उम होंग गिल** नेपालको सम्मानार्थ नागरिकता प्राप्त गर्ने अन्तिम (चौथो) व्यक्ति हुन्।\n- एडमन्ड हिलारी पहिलो, टोनी हेगन दोस्रो र कोलिन स्मिथ तेस्रो व्यक्ति थिए जसले नेपालको सम्मानार्थ नागरिकता प्राप्त गरे।', 'nepali'),
      (v_set_id, 3, E'सबैभन्दा पहिले अनुसन्धान गरिएको ग्रह कुन हो?', E'बुध', E'मंगल', E'बृहस्पति', E'शुक्र', 'D', E'**शुक्र ग्रह** अन्तरिक्ष यानद्वारा अन्वेषण र खोज गरिएको पहिलो ग्रह थियो।\n- मंगल ग्रहमा पृथ्वीसँग मिल्दोजुल्दो वातावरण र जीवनको सम्भावना भएकाले धेरै अनुसन्धान भएको छ।\n- बुध सौर्यमण्डलमा सूर्यको सबैभन्दा नजिकको ग्रह हो।\n- बृहस्पति सौर्यमण्डलको सबैभन्दा ठूलो ग्रह हो।', 'nepali'),
      (v_set_id, 4, E'अन्तर्राष्ट्रिय मानव भ्रातृत्व दिवस प्रत्येक वर्ष कुन दिन मनाइन्छ?', E'फेब्रुअरी १', E'फेब्रुअरी २', E'फेब्रुअरी ३', E'फेब्रुअरी ४', 'D', E'अन्तर्राष्ट्रिय मानव भ्रातृत्व दिवस प्रत्येक वर्ष **फेब्रुअरी ४** मा मनाइन्छ। यो दिवस सन् २०२० मा संयुक्त राष्ट्र संघ (UN) द्वारा स्थापित भएको थियो।\nनोट: सन् २०२६ को नारा ''Dialogue Over Division'' रहेको थियो।', 'nepali'),
      (v_set_id, 5, E'२५ औं शीतकालीन ओलम्पिक खेल २०२६ को आयोजक देश कुन हो?', E'इटाली', E'स्पेन', E'फ्रान्स', E'जर्मनी', 'A', E'**इटालीले** २५ औं शीतकालीन ओलम्पिक खेल २०२६ को आयोजना गरेको थियो।\nनोट: यो खेलकुद सन् २०२६ फेब्रुअरी ६ देखि २२ सम्म सम्पन्न भएको थियो।', 'nepali'),
      (v_set_id, 6, E'सोह्रौं योजनाको अन्त्य सम्म साक्षरता दर (५ वर्ष माथि) कति पुर्याउने लक्ष्य रहेको छ?', E'८५ प्रतिशत', E'९० प्रतिशत', E'७५ प्रतिशत', E'८० प्रतिशत', 'A', E'सोह्रौं योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्म ५ वर्षमाथिको साक्षरता दर **८५ प्रतिशत** पुर्याउने लक्ष्य रहेको छ।\nनोट: योजनाको सुरुवातमा यो दर ७६.२ प्रतिशत रहेको थियो।', 'nepali'),
      (v_set_id, 7, E'पृथ्वीको केन्द्रबाट उत्तर-दक्षिण हुने गरी खिचिएको काल्पनिक रेखाको माथिल्लो छेउलाई के भनिन्छ?', E'उत्तरी ध्रुव', E'दक्षिणी ध्रुव', E'भूमध्य रेखा', E'सुमेरु वृत', 'A', E'पृथ्वीको केन्द्रबाट उत्तर-दक्षिण हुने गरी खिचिएको काल्पनिक रेखाको माथिल्लो छेउलाई **उत्तरी ध्रुव** भनिन्छ।\n- दक्षिणी ध्रुव सोही काल्पनिक रेखाको तल्लो छेउलाई भनिन्छ।\n- भूमध्य रेखा पृथ्वीको केन्द्रबाट पूर्व-पश्चिम खिचिएको काल्पनिक रेखा हो जसले पृथ्वीलाई उत्तरी र दक्षिणी गोलार्धमा विभाजन गर्दछ।\n- सुमेरु वृत (Arctic Circle) उत्तरी गोलार्धमा ६६.५ डिग्री अक्षांशमा रहेको प्रमुख अक्षांश रेखा हो।', 'nepali'),
      (v_set_id, 8, E'स्थानीय तहहरूको प्रशासनिक वर्गीकरण अन्तर्गत सुगम स्थानीय तह कति रहेका छन्?', E'९९ वटा', E'९८ वटा', E'९७ वटा', E'९६ वटा', 'B', E'नेपालमा प्रशासनिक वर्गीकरण अनुसार सुगम स्थानीय तहको संख्या **९८ वटा** रहेको छ।\nनोट: सरकारले स्थानीय तहहरूलाई अतिदुर्गम (१६२), दुर्गम (२१८), मध्यम (२७५) र सुगम (९८) गरी चार श्रेणीमा वर्गीकरण गरेको छ।', 'nepali'),
      (v_set_id, 9, E'फ्रान्समा गणतन्त्रको घोषणा कहिले भयो?', E'सन् १७९१', E'सन् १७९२', E'सन् १७९३', E'सन् १७९४', 'B', E'फ्रान्समा **सन् १७९२** सेप्टेम्बर २२ मा गणतन्त्रको घोषणा भएको थियो।\nनोट: यसको ठीक एक दिन अघि, अर्थात् सन् १७९२ सेप्टेम्बर २१ मा राजतन्त्रको अन्त्य भएको थियो।', 'nepali'),
      (v_set_id, 10, E'निम्न घटनामध्ये कुन राणा प्रधानमन्त्री भीमसमसेर सँग सम्बन्धित छैन?', E'प्रजापरिषद', E'लाइब्रेरि पर्व', E'प्रचण्ड गोर्खा पर्व', E'चर्खा प्रचारमा रोक', 'A', E'**प्रजापरिषद**को स्थापना जुद्ध समसेरको पालामा भएको थियो, त्यसैले यो भीमसमसेरसँग सम्बन्धित छैन।\n- लाइब्रेरि पर्व वि.सं. १९८७ मा भीमसमसेरको पालामा भएको थियो।\n- प्रचण्ड गोर्खा पर्व वि.सं. १९८८ मा भीमसमसेरकै पालामा घटेको थियो।\n- चर्खा प्रचारमा रोक लगाउने कार्य पनि भीमसमसेरले नै गरेका थिए।\nनोट: नेपाल प्रजापरिषद नेपालको पहिलो राजनीतिक दल थियो, जसको स्थापना वि.सं. १९९३ मा भएको थियो।', 'nepali'),
      (v_set_id, 11, E'हिन्दु धर्मको सबैभन्दा पुरानो सम्प्रदाय कुन हो?', E'शाक्त', E'शैव', E'वैष्णव', E'गणपत', 'B', E'हिन्दु धर्मको सबैभन्दा पुरानो सम्प्रदाय **शैव** हो।\n- हिन्दु धर्मका अन्य प्रमुख सम्प्रदायहरूमा शाक्त, वैष्णव, सौर्य र गणपत पर्दछन्।', 'nepali'),
      (v_set_id, 12, E'धवला पर्व कुन जातिको प्रमुख चाड हो?', E'ब्यासी', E'थकाली', E'थानुक', E'जिरेल', 'A', E'धवला पर्व **ब्यासी** जातिको प्रमुख चाड हो।\n- यो पर्व माघ महिनामा भैलो खेलेर मनाइन्छ र यस जातिमा ज्येष्ठ छोरीको वदानि पूजा गर्ने चलन पनि रहेको छ।', 'nepali'),
      (v_set_id, 13, E'सेता रक्तकोषमा कुन तत्व हुने गर्दछ?', E'हेमोग्लोबिन', E'न्युक्लियस', E'प्लेटलेट्स', E'प्लाजमा', 'B', E'सेता रक्तकोष (White Blood Cells) मा **न्युक्लियस** (केन्द्रक) हुने गर्दछ, तर राता रक्तकोषमा यो हुँदैन।\n- हेमोग्लोबिन रातो रक्तकोषमा पाइने प्रोटिन हो, जसले रगतलाई रातो रंग दिन्छ र अक्सिजन बोक्ने काम गर्छ।\n- प्लेटलेट्स रगत जमाउन मद्दत गर्ने रक्तकोषिका हुन्।\n- प्लाज्मा रगतको तरल भाग हो, जसमा रक्तकोषहरू तैरिएका हुन्छन्।', 'nepali'),
      (v_set_id, 14, E'राष्ट्रिय जनगणना २०७८ अनुसार भौगोलिक आधारमा हिमाली क्षेत्रको जनसंख्या कति प्रतिशत रहेको छ?', E'६.०८ प्रतिशत', E'६.९८ प्रतिशत', E'६.२८ प्रतिशत', E'६.३८ प्रतिशत', 'A', E'राष्ट्रिय जनगणना २०७८ अनुसार भौगोलिक आधारमा हिमाली क्षेत्रको जनसंख्या **६.०८ प्रतिशत** रहेको छ। सोही जनगणना अनुसार, पहाडी क्षेत्रमा ४०.३१ प्रतिशत र तराई क्षेत्रमा ५३.६१ प्रतिशत जनसंख्या रहेको छ।', 'nepali'),
      (v_set_id, 15, E'सिंह कुन सार्क मुलुकको राष्ट्रिय जनावर हो?', E'भारत', E'श्रीलंका', E'पाकिस्तान', E'भुटान', 'B', E'**सिंह श्रीलंकाको राष्ट्रिय जनावर हो।**\n- भारतको राष्ट्रिय जनावर बाघ हो।\n- पाकिस्तानको राष्ट्रिय जनावर मारखोर हो।\n- भुटानको राष्ट्रिय जनावर ताकिन हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/०७', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_08.csv  →  आसमान दैनिक GK — २०८३/०१/०८  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/०८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/०८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/०८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'नेपाल बहुसूचक सर्वेक्षण २०७१/७२ (२०१४-१५) अनुसार कति प्रतिशत घरपरिवारमा टेलिफोन सुविधाको पहुँच रहेको छ ?', E'९४.५ प्रतिशत', E'९५.५ प्रतिशत', E'९६.५ प्रतिशत', E'९७.५ प्रतिशत', 'B', E'नेपाल बहुसूचक सर्वेक्षण २०७१/७२ अनुसार **९५.५ प्रतिशत** घरपरिवारमा टेलिफोन (स्थिर टेलिफोन वा मोबाइल फोन) सुविधाको पहुँच रहेको छ।\nनोट: प्रदेश अनुसार सबैभन्दा धेरै बागमती प्रदेशमा (९७.१%) र सबैभन्दा कम सुदूरपश्चिम प्रदेशमा (९२.६%) टेलिफोनको पहुँच रहेको छ।', 'nepali'),
      (v_set_id, 2, E'सबैभन्दा धेरै नगरपालिका भएको प्रदेश मधेसमा जम्मा कतिवटा नगरपालिका रहेको छन् ?', E'७९ वटा', E'७३ वटा', E'८८ वटा', E'५४ वटा', 'B', E'मधेस प्रदेशमा जम्मा **७३ वटा** नगरपालिका रहेका छन्, जुन नेपालका प्रदेशहरूमध्ये सबैभन्दा बढी हो।\n- ७९ वटा स्थानीय तह कर्णाली प्रदेशमा रहेका छन्, जुन सबैभन्दा कम हो।\n- ८८ वटा गाउँपालिका कोशी प्रदेशमा रहेका छन्, जुन सबैभन्दा बढी हो।\n- ५४ वटा गाउँपालिका कर्णाली र सुदूरपश्चिम प्रदेशमा रहेका छन्, जुन सबैभन्दा कम हो।\nनोट: सबैभन्दा थोरै नगरपालिका भएको प्रदेश कर्णाली हो, जहाँ २५ वटा नगरपालिका छन्।', 'nepali'),
      (v_set_id, 3, E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार नेपाल विश्वको कति औं स्थानमा रहेको छ ?', E'१०७ औं', E'१०८ औं', E'१०९ औं', E'११० औं', 'C', E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार नेपाल **१०९ औं** स्थानमा रहेको छ।\nनोट: यो सूचकांक ट्रान्सपरेन्सी इन्टरनेशनल (Transparency International) द्वारा सार्वजनिक गरिन्छ र उक्त प्रतिवेदनमा नेपालले ३४ अंक प्राप्त गरेको थियो।', 'nepali'),
      (v_set_id, 4, E'साझा पुरस्कार पुरस्कारको राशी कति रहेको छ ?', E'१ लाख मात्र', E'२ लाख मात्र', E'५१ हजार मात्र', E'४ लाख मात्र', 'C', E'साझा पुरस्कारको राशि **५१ हजार रुपैयाँ** रहेको छ।\nनोट: मदन पुरस्कार, पृथ्वीप्रज्ञा पुरस्कार र जगदम्बाश्री पुरस्कारको राशि ४ लाख रुपैयाँ रहेको छ।', 'nepali'),
      (v_set_id, 5, E'नेपालमा हालसम्म भएको जनगणना मध्ये सबैभन्दा धेरै जनसंख्या वृद्धिदर भएको जनगणना कुन हो ?', E'आठौं', E'सातौं', E'नवौं', E'छैटौं', 'A', E'नेपालमा हालसम्म भएको जनगणनामध्ये सबैभन्दा धेरै जनसंख्या वृद्धिदर **आठौं जनगणना (वि.सं. २०३८)** मा भएको थियो, जतिबेला वृद्धिदर २.६२ प्रतिशत थियो।\nनोट: नेपालको दोस्रो र तेस्रो जनगणनामा जनसंख्या वृद्धिदर ऋणात्मक थियो।', 'nepali'),
      (v_set_id, 6, E'अरबी भाषालाई संयुक्त राष्ट्रसंघको आधिकारिक भाषाको रुपमा कहिले मान्यता दिइएको हो ?', E'सन् १९८३', E'सन् १९७३', E'सन् १९९३', E'सन् २००३', 'B', E'अरबी भाषालाई संयुक्त राष्ट्रसंघको आधिकारिक भाषाको रुपमा **सन् १९७३** मा मान्यता दिइएको थियो।\nनोट: संयुक्त राष्ट्रसंघका ६ आधिकारिक भाषाहरू छन्: अरबी, चिनियाँ, अंग्रेजी, फ्रेन्च, रुसी र स्पेनिस।', 'nepali'),
      (v_set_id, 7, E'पाकिस्तानले सार्कको बजेटमा कति प्रतिशत योगदान गर्दछ ?', E'२२.९२ प्रतिशत', E'२२.५२ प्रतिशत', E'२२.७२ प्रतिशत', E'२२.३२ प्रतिशत', 'B', E'पाकिस्तानले सार्कको बजेटमा **२२.५२ प्रतिशत** योगदान गर्दछ।\nसार्क बजेटमा सदस्य राष्ट्रहरूको योगदान यसप्रकार छ:\n- भारत: ३०.३२%\n- पाकिस्तान: २२.५२%\n- नेपाल, बंगलादेश, श्रीलंका (प्रत्येक): १०.७२%\n- भुटान, माल्दिभ्स, अफगानिस्तान (प्रत्येक): ५%', 'nepali'),
      (v_set_id, 8, E'नेपालको संविधानमा उल्लेख भएको राज्यका नीतिहरु अन्तर्गत देहाएको मध्ये कुन नीति पर्दैन ?', E'श्रम र रोजगार', E'कृषि र भूमि सुधार', E'शिक्षा र स्वास्थ्य', E'न्याय र दण्ड व्यवस्था', 'D', E'**''न्याय र दण्ड व्यवस्था''** सम्बन्धी नीति नेपालको संविधानमा उल्लेखित राज्यका नीतिहरू अन्तर्गत पर्दैन।\n- श्रम र रोजगार, कृषि र भूमि सुधार, र शिक्षा र स्वास्थ्य सम्बन्धी नीतिहरू भने राज्यका नीतिहरूमा समावेश गरिएका छन्।\nनोट: नेपालको संविधानको धारा ५१ मा जम्मा १३ वटा राज्यका नीतिहरू उल्लेख छन्।', 'nepali'),
      (v_set_id, 9, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा तामाङ जाति कति रहेको छ ?', E'५.६२ प्रतिशत', E'५.६७ प्रतिशत', E'६.२४ प्रतिशत', E'६.४२ प्रतिशत', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा तामाङ जातिको जनसंख्या **५.६२ प्रतिशत** रहेको छ। यो नेपालको पाँचौं ठूलो जातीय समूह हो।\nजनसंख्याको आधारमा शीर्ष ५ जातिहरू यसप्रकार छन्:\n- १. क्षेत्री: १६.४५%\n- २. पहाडी ब्राह्मण: ११.२९%\n- ३. मगर: ६.९%\n- ४. थारु: ६.२%\n- ५. तामाङ: ५.६२%', 'nepali'),
      (v_set_id, 10, E'नेपाल बहुसूचक सर्वेक्षण २०८१/८२ (२०२४-२५) अनुसार सबैभन्दा कम बालमृत्यु दर भएको प्रदेश कुन हो ?', E'बागमती', E'कर्णाली', E'गण्डकी', E'कोशी', 'C', E'नेपाल बहुसूचक सर्वेक्षण २०८१/८२ अनुसार सबैभन्दा कम बालमृत्यु दर **गण्डकी प्रदेशमा** रहेको छ, जहाँ प्रति १००० जीवित जन्ममा २० जना बालबालिकाको मृत्यु हुने गरेको छ।\nनोट: सोही सर्वेक्षण अनुसार सबैभन्दा बढी बालमृत्यु दर सुदूरपश्चिम प्रदेशमा (४८ जना) रहेको छ भने सबैभन्दा कम नवजात शिशुमृत्यु र शिशुमृत्यु दर बागमती प्रदेशमा रहेको छ।', 'nepali'),
      (v_set_id, 11, E'राष्ट्रिय जनगणना २०७८ अनुसार भौगोलिक आधारमा हिमाली क्षेत्रको जनसंख्या कति प्रतिशत रहेको छ ?', E'६.०८ प्रतिशत', E'६.१६ प्रतिशत', E'६.२८ प्रतिशत', E'६.३८ प्रतिशत', 'A', E'राष्ट्रिय जनगणना २०७८ अनुसार भौगोलिक आधारमा हिमाली क्षेत्रको जनसंख्या **६.०८ प्रतिशत** रहेको छ।\nभौगोलिक क्षेत्र अनुसार जनसंख्या वितरण:\n- तराई: ५३.६१ % (१,५६,३४,००६ जना)\n- पहाड: ४०.३१ % (१,१७,५७,६२४ जना)\n- हिमाल: ६.०८ % (१७,७२,९४८ जना)', 'nepali'),
      (v_set_id, 12, E'दाङ-सल्यान-रुकुम सडक खण्डलाई के नामले चिनिन्छ ?', E'अरनिको राजमार्ग', E'रत्न राजमार्ग', E'कर्णाली राजमार्ग', E'राप्ती राजमार्ग', 'D', E'दाङ-सल्यान-रुकुम सडक खण्डलाई **राप्ती राजमार्ग** नामले चिनिन्छ, जुन दाङको अमेलियादेखि रुकुमको मुसिकोटसम्म फैलिएको छ।\n- अरनिको राजमार्ग काठमाडौंको माइतीघरदेखि कोदारीको मितेरी पुलसम्म पुग्छ।\n- रत्न राजमार्ग नेपालगन्जको जमुनिया सीमादेखि सुर्खेतको बाङ्गेसिमलसम्म फैलिएको छ।\n- कर्णाली राजमार्ग सुर्खेतको बाङ्गेसिमलदेखि जुम्ला र कालीकोटसम्म पुग्छ।', 'nepali'),
      (v_set_id, 13, E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार विश्वमा सबैभन्दा कम भ्रष्टाचार हुने मुलुक कुन हो?', E'डेनमार्क', E'फिनल्याण्ड', E'सिंगापुर', E'न्युजिल्याण्ड', 'A', E'भ्रष्टाचार अवधारणा सूचकांक, २०२४ अनुसार विश्वमा सबैभन्दा कम भ्रष्टाचार हुने मुलुक **डेनमार्क** हो, जसले ८९ अंक प्राप्त गरेको छ।\n- फिनल्याण्ड ८८ अंकका साथ दोस्रो स्थानमा छ।\n- सिंगापुर ८४ अंकका साथ तेस्रो स्थानमा छ।\n- न्युजिल्याण्ड र नर्वे ८१ अंकका साथ संयुक्त रूपमा चौथो स्थानमा रहेका छन्।\nनोट: सोही सूचकांकमा सबैभन्दा बढी भ्रष्टाचार हुने मुलुकहरूमा साउथ सुडान, सोमालिया, सिरिया र भेनेजुयला रहेका छन्।', 'nepali'),
      (v_set_id, 14, E'WTO को कान्छो सदस्य कुन हो ?', E'अफगानिस्तान', E'लाइबेरिया', E'कोमोरोस', E'टिमोर लिस्टे', 'D', E'विश्व व्यापार संगठन (WTO) को कान्छो सदस्य **टिमोर लिस्टे** हो।\n- कोमोरोस WTO को १६५ औं सदस्य हो, जसले सन् २०२४ अगष्ट २९ मा सदस्यता प्राप्त गरेको थियो।\n- अफगानिस्तान WTO को १६४ औं सदस्य हो, जसले सन् २०१६ जुलाई २९ मा सदस्यता प्राप्त गरेको थियो।\n- लाइबेरिया WTO को १६३ औं सदस्य हो, जसले सन् २०१६ जुलाई १४ मा सदस्यता प्राप्त गरेको थियो।\nनोट: टिमोर लिस्टेले सन् २०२४ अगष्ट ३० मा १६६ औं सदस्यको रूपमा सदस्यता प्राप्त गरेको हो।', 'nepali'),
      (v_set_id, 15, E'गुरुङ जातिको घरको भित्तामा कोरिने एक प्रकारको चित्रलाई के भनिन्छ ?', E'पौभा चित्र', E'पुराती चित्र', E'थांका चित्र', E'भित्ते चित्र', 'B', E'गुरुङ जातिको घरको भित्तामा कोरिने एक प्रकारको चित्रलाई **पुराती चित्र** भनिन्छ।\n- पौभा चित्र नेवार समुदायमा प्रचलित एक परम्परागत धार्मिक चित्रकला हो।\n- थांका चित्र तिब्बती बौद्ध धर्मावलम्बीहरूले कपडामा बनाउने धार्मिक चित्रकला हो।\n- भित्ते चित्र भनेको कुनै पनि घर वा भवनको भित्तामा बनाइने चित्रको एक सामान्य प्रकार हो, जुन विभिन्न जाति र समुदायमा प्रचलित छ।', 'nepali'),
      (v_set_id, 16, E'सगरमाथा दिवस कहिले मनाइन्छ?', E'मे ९', E'मे ११', E'मे २९', E'मे ३०', 'C', E'सगरमाथा दिवस हरेक वर्ष **मे २९** मा मनाइन्छ। पहिलो पटक सगरमाथा आरोहण गर्ने तेन्जिङ नोर्गे शेर्पा र एडमण्ड हिलारीले सन् १९५३ मे २९ मा सफल आरोहण गरेका थिए, सोही दिनको सम्झनामा यो दिवस मनाउन थालिएको हो।\nनोट: नेपालमा सन् २००८ देखि औपचारिक रूपमा सगरमाथा दिवस मनाउन सुरु गरिएको हो।', 'nepali'),
      (v_set_id, 17, E'अक्टोबर क्रान्तिको उपनामले विश्व इतिहासको कुन क्रान्तिलाई चिनिन्छ?', E'फ्रान्सेली राज्य', E'रुसी राज्य', E'औद्योगिक', E'गौरवमय', 'B', E'**रुसी क्रान्तिलाई अक्टोबर क्रान्तिको उपनामले पनि चिनिन्छ।**\n- फ्रान्सेली क्रान्ति सन् १७८९ मा भएको थियो, जसले राजतन्त्रको अन्त्य गर्‍यो।\n- औद्योगिक क्रान्ति १८औं शताब्दीमा बेलायतबाट सुरु भएको प्राविधिक र सामाजिक परिवर्तनको लहर थियो।\n- गौरवमय क्रान्ति सन् १६८८ मा बेलायतमा भएको रक्तहीन क्रान्ति थियो।\nनोट: रुसी जुलियन क्यालेन्डरअनुसार यो क्रान्ति अक्टोबरमा भएकोले यसलाई अक्टोबर क्रान्ति भनिएको हो।', 'nepali'),
      (v_set_id, 18, E'ललितपुरमा मानव बस्ती बसाल्ने राजा को हुन्?', E'वरदेव', E'आनन्ददेव', E'शिवदेव', E'गुणकामदेव', 'A', E'**ललितपुरमा मानव बस्ती बसाल्ने राजा वरदेव हुन्।**\n- आनन्ददेवले भक्तपुरमा मानव बस्ती बसालेका थिए।\n- शिवदेव प्रथमले कीर्तिपुरमा मानव बस्ती बसालेका थिए।\n- गुणकामदेवले कान्तिपुर (काठमाडौं) मा मानव बस्ती बसालेका थिए।', 'nepali'),
      (v_set_id, 19, E'प्रश्न वाचक चिन्ह भएको ठाँउमा उपयुक्त विकल्प छनोट गर्नुहोस्। ''हिन्दु'' : ''सिन्धुघाँटी पाकिस्तान'' :: ''इस्लाम'' : ?', E'जेरुसलाम, इजरायल', E'प्यालेस्टाइन इजरायल', E'मक्का, साउदी अरेबिया', E'पंजाब, भारत', 'C', E'**जसरी हिन्दु धर्मको उद्गम स्थल सिन्धुघाँटी (हाल पाकिस्तान) मानिन्छ, त्यसैगरी इस्लाम धर्मको उद्गम स्थल मक्का (साउदी अरेबिया) हो।**\n- जेरुसलाम यहुदी, ईसाई र इस्लाम तीनवटै धर्मको लागि एक पवित्र शहर हो।\n- प्यालेस्टाइन र इजरायल मध्यपूर्वका देशहरू हुन्, जुन धार्मिक रूपमा महत्वपूर्ण छन् तर इस्लामको उद्गम स्थल होइनन्।\n- पंजाब भारत र पाकिस्तानमा फैलिएको क्षेत्र हो र यो विशेषगरी शिख धर्मको लागि महत्वपूर्ण छ।', 'nepali'),
      (v_set_id, 20, E'आदिवासी ज्ञान सम्मेलन, २०८२ सञ्चालन मिति कुन विकल्प सहि रहेको छ?', E'२०८२ माघ २१ देखि २२', E'२०८२ माघ २३ देखि २५', E'२०८२ माघ २५ देखि २७', E'२०८२ माघ २७ देखि २९', 'C', E'आदिवासी ज्ञान सम्मेलन **२०८२ माघ २५ देखि २७** सम्म सञ्चालन भएको थियो।', 'nepali'),
      (v_set_id, 21, E'हालसालै नेपाल बिमा प्राधिकरणको पहिलो महिला अध्यक्षका को नियुक्त भएकी छिन् ?', E'निर्मला शर्मा', E'सविता भण्डारी', E'चन्द्रकला पौडेल', E'मनदेवी श्रेष्ठ', 'C', E'नेपाल बिमा प्राधिकरणको पहिलो महिला अध्यक्षमा **चन्द्रकला पौडेल** नियुक्त भएकी छिन्।\nनोट: २०८२ माघ १३ गतेको मन्त्रिपरिषद्को बैठकले उनलाई प्राधिकरणको अध्यक्षको जिम्मेवारी दिएको थियो।', 'nepali'),
      (v_set_id, 22, E'आर्थिक वर्ष २०८२/८३ को बजेटले राष्ट्रिय रोजगार प्रवर्द्धनका लागि कति रुपैयाँ विनियोजन गरेको छ?', E'करिब २ अर्ब', E'करिब ३ अर्ब', E'करिब ४ अर्ब', E'करिब ५ अर्ब', 'A', E'आर्थिक वर्ष २०८२/८३ को बजेटले राष्ट्रिय रोजगार प्रवर्द्धनका लागि **करिब २ अर्ब** (१ अर्ब ९९ करोड) रुपैयाँ विनियोजन गरेको छ।\nनोट: सोही बजेटले चुरे संरक्षणका लागि १ अर्ब ६९ करोड र सामाजिक सुरक्षा भत्ताका लागि १ खर्ब ९ अर्ब विनियोजन गरेको थियो।', 'nepali'),
      (v_set_id, 23, E'त्रिभुवन विमानस्थलमा सर्वप्रथम जेट विमान अवतरण कहिले भयो?', E'२०२३ फागुन २५', E'२०६४ पुस १', E'२०५५ पुस ८', E'२०१९ माघ २', 'A', E'**त्रिभुवन विमानस्थलमा सर्वप्रथम जेट विमान २०२३ फागुन २५ गते अवतरण भएको थियो।**\n- वि.सं. २०६४ पुस १ मा लुक्ला विमानस्थलको नाम तेञ्जिङ-हिलारी विमानस्थल नामाकरण गरिएको थियो।\n- वि.सं. २०५५ पुस ८ मा भैरहवा विमानस्थलको नाम परिवर्तन गरी गौतम बुद्ध विमानस्थल राखिएको थियो।\n- वि.सं. २०१९ माघ २ मा काठमाडौंबाट दिल्ली पहिलो हवाई सेवा सुरु भएको थियो।', 'nepali'),
      (v_set_id, 24, E'नेपालको संविधानको कुन धारामा मन्त्रिपरिषद्को गठनसँग सम्बन्धित व्यवस्था रहेको छ?', E'धारा ७५', E'धारा ७६', E'धारा ७७', E'धारा ७८', 'B', E'नेपालको संविधानको **धारा ७६** मा मन्त्रिपरिषद्को गठनसम्बन्धी व्यवस्था गरिएको छ। यस धारा अनुसार, राष्ट्रपतिले प्रतिनिधि सभामा बहुमत प्राप्त संसदीय दलको नेतालाई प्रधानमन्त्री नियुक्त गर्ने र निजको अध्यक्षतामा मन्त्रिपरिषद्को गठन हुने व्यवस्था छ।\nनोट: बहुमत प्राप्त नभएको अवस्थामा दुई वा दुईभन्दा बढी दलको समर्थनमा बहुमत प्राप्त गर्न सक्ने सदस्यलाई प्रधानमन्त्री नियुक्त गर्ने जस्ता वैकल्पिक व्यवस्थाहरू पनि यही धारामा उल्लेख छन्।', 'nepali'),
      (v_set_id, 25, E'अन्तर्राष्ट्रिय तिथि रेखा कस्तो हुन्छ?', E'पूर्ण वृत्ताकार', E'वृत्ताकार', E'बांगोटिंगो', E'सिधा', 'C', E'अन्तर्राष्ट्रिय तिथि रेखा **बांगोटिंगो** हुन्छ। १८० डिग्री देशान्तर रेखालाई अन्तर्राष्ट्रिय तिथि रेखा भनिन्छ। तिथि, मिति, समय र बारमा एकरूपता ल्याउन र एउटै देशमा फरक-फरक बार नपरोस् भनेर यसलाई चार पटक मोडिएको छ।', 'nepali'),
      (v_set_id, 26, E'शिशुग्रह शब्दको प्रयोग सर्वप्रथम गर्ने वैज्ञानिक को हुन्?', E'निकोलस कोपर्निकस', E'क्याउड टम्बाग', E'जोहन गाल', E'विलियम हर्शेल', 'D', E'**शिशुग्रह (asteroid) शब्दको प्रयोग सर्वप्रथम गर्ने वैज्ञानिक विलियम हर्शेल हुन्।**\n- निकोलस कोपर्निकसलाई सौर्यमण्डलका पिता मानिन्छ र उनले ब्रह्माण्डको खोज गरेका थिए।\n- क्याउड टम्बाग (Clyde Tombaugh) ले यम ग्रहको खोज गरेका थिए।\n- जोहन गालले सन् १८४६ मा बरुण ग्रह पत्ता लगाएका थिए।\nनोट: विलियम हर्शेलले १३ मार्च, १७८१ मा अरुण ग्रह पनि पत्ता लगाएका थिए।', 'nepali'),
      (v_set_id, 27, E'हालसम्म मदन पुरस्कार पाउने महिला साहित्यकार कति जना रहेको छन्?', E'२ जना', E'३ जना', E'४ जना', E'१ जना', 'C', E'हालसम्म मदन पुरस्कार पाउने महिला साहित्यकार **४ जना** रहेका छन्।\n- उनीहरू पारिजात (वि.सं. २०२२, ''शिरिषको फूल''), झमक घिमिरे (वि.सं. २०६७, ''जीवन काँडाकी फूल''), राधा पौडेल (वि.सं. २०७०, ''खलंगामा हमला''), र निलम कार्की ''न्यौपाने'' (वि.सं. २०७४, ''योगमाया'') हुन्।', 'nepali'),
      (v_set_id, 28, E'विश्वमा माग हुने ऊर्जा पूर्तीको प्रमुख स्रोत के हो?', E'कोइला', E'वनजङ्गल', E'पेट्रोल', E'सौर्य उर्जा', 'C', E'विश्वमा माग हुने ऊर्जा पूर्तीको प्रमुख स्रोत **पेट्रोलियम (पेट्रोल)** हो, जसले करिब ८० प्रतिशत माग ओगटेको छ।\n- कोइला, तेल, प्राकृतिक ग्याँस जस्ता स्रोतहरू अनवीकरणीय शक्ति हुन् किनभने यिनीहरूको पुनः निर्माण हुन लाखौं वर्ष लाग्छ।\n- वनजङ्गल परम्परागत ऊर्जाको स्रोत हो तर विश्वव्यापी मागको प्रमुख स्रोत होइन।\n- सौर्य उर्जा, हावा, र ज्वारभाटा नवीकरणीय शक्तिका स्रोतहरू हुन्।\nनोट: नेपालमा वैकल्पिक उर्जा केन्द्रको स्थापना वि.सं. २०५३ कार्तिक १८ गते भएको हो।', 'nepali'),
      (v_set_id, 29, E'वातावरण मुद्दासंग सम्बन्धित पहिलो अन्तर्राष्ट्रिय सम्मेलन कुन मुलुकमा भएको थियो?', E'ब्राजिल', E'स्वीडेन', E'नर्वे', E'बेलायत', 'B', E'वातावरण मुद्दामा केन्द्रित पहिलो अन्तर्राष्ट्रिय सम्मेलन **स्वीडेनको स्टकहोममा** भएको थियो। यो सम्मेलन सन् १९७२ जुन ५ देखि १६ सम्म सम्पन्न भएको थियो।\nनोट: यही सम्मेलनले जुन ५ लाई विश्व वातावरण दिवसको रूपमा मनाउने घोषणा गरेको थियो, जसको पहिलो नारा ''एक मात्र पृथ्वी'' (Only One Earth) थियो।', 'nepali'),
      (v_set_id, 30, E'UNO को वडापत्रको अन्तिम अध्याय १९ मा के उल्लेख गरिएको छ?', E'संशोधनहरु', E'संक्रमणकालीन सुरक्षा व्यवस्था', E'विविध प्रावधानहरु', E'अनुमोदन र हस्ताक्षर', 'D', E'**UNO को बडापत्रको अन्तिम अध्याय १९ मा अनुमोदन र हस्ताक्षर (Ratification and Signature) बारे उल्लेख गरिएको छ।**\n- अध्याय १८ मा संशोधनहरु (Amendments) सम्बन्धी व्यवस्था छ।\n- अध्याय १७ मा संक्रमणकालीन सुरक्षा व्यवस्था (Transitional Security Arrangements) को प्रावधान छ।\n- अध्याय १६ मा विविध प्रावधानहरु (Miscellaneous Provisions) उल्लेख गरिएको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/०८', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_13.csv  →  आसमान दैनिक GK — २०८३/०१/१३  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/१३'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/१३';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/१३', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'जुनको तावेइ कुन देशको नागरिक हुन?', E'जापान', E'चीन', E'पोल्याण्ड', E'जर्मनी', 'A', E'सगरमाथाको सफल आरोहण गर्ने प्रथम महिला जुनको तावेइ **जापानकी** नागरिक हुन्।\n- चीनकी कुमारी फान्तोग सगरमाथा आरोहण गर्ने दोस्री महिला हुन्।\n- पोल्याण्डकी वान्दा रुत्किविज (वान्दारकी ब्रिज) सगरमाथा आरोहण गर्ने तेस्री महिला हुन्।\nनोट: जुनको तावेइले सन् १९७५ मे १६ मा सगरमाथाको सफल आरोहण गरेकी थिइन्।', 'nepali'),
      (v_set_id, 2, E'सार्कको शक्तिशाली राष्ट्र भारतमा अंग्रेजले कहिले देखि शासन सुरु गरेका थिए?', E'१७५७ देखी', E'१७४७ देखी', E'१८४७ देखी', E'१८५७ देखी', 'A', E'भारतमा अंग्रेजहरूले **सन् १७५७** देखि आफ्नो शासन सुरु गरेका थिए।\nनोट: अंग्रेजले भारतमा लगभग १९० वर्ष (सन् १७५७ देखि १९४७ सम्म) शासन गरेका थिए।', 'nepali'),
      (v_set_id, 3, E'नेपाली इतिहासमा नेपाल एकीकरणमा प्रमुख भुमिका खेलेका योद्धा पृथ्वीनारायण शाहको मृत्यु पश्चात कति रानीहरू सति गएका थिए?', E'८ जना', E'९ जना', E'११ जना', E'१० जना', 'B', E'पृथ्वीनारायण शाहको मृत्यु पश्चात **९ जना** रानीहरू सति गएका थिए।\n- रत्न मल्लको मृत्यु पश्चात १० जना रानीहरू सति गएका थिए।\n- प्रताप मल्लको मृत्यु पश्चात पनि ९ जना रानीहरू सति गएका थिए।\n- योगनरेन्द्र मल्लको मृत्यु पश्चात सबैभन्दा धेरै, ३१ जना रानीहरू सति गएका थिए।', 'nepali'),
      (v_set_id, 4, E'गिर्जाघर कुन धर्मसँग सम्बन्धित रहेको छ?', E'इस्लाम', E'इसाई', E'बौद्ध', E'किरात', 'B', E'गिर्जाघर (चर्च) **इसाई धर्मसँग** सम्बन्धित धार्मिक स्थल हो।\n- इस्लाम धर्मको धार्मिक स्थललाई मस्जीद, दरगाहा वा मुसल्ला भनिन्छ।\n- बौद्ध धर्मको धार्मिक स्थल स्तुप, विहार वा गुम्बा हो।\nनोट: इसाई धर्मका अन्य धार्मिक स्थलहरूमा क्याथेड्रल पनि पर्दछ।', 'nepali'),
      (v_set_id, 5, E'साफ यु-१९ महिला च्याम्पियनसिप, २०२६ को उपाधि कुन देशले जितेको छ ?', E'भारत', E'बंगलादेश', E'भुटान', E'नेपाल', 'A', E'**सन् २०२६ को साफ यु-१९ महिला च्याम्पियनसिपको उपाधि भारतले जितेको थियो।**\n- बंगलादेश उक्त प्रतियोगिताको उपविजेता बनेको थियो।\n- भुटान र आयोजक नेपाल पनि प्रतियोगितामा सहभागी थिए।\nनोट: यो प्रतियोगिता नेपालको पोखरामा २०८२ माघ १७ देखि २४ गतेसम्म (३१ जनवरी देखि ७ फेब्रुअरी २०२६) सञ्चालन भएको थियो।', 'nepali'),
      (v_set_id, 6, E'आर्थिक वर्ष २०८२/८३ को बजेटले नेपालको कुल जडित विद्युत क्षमता कति पुऱ्याइने लक्ष्य राखेको छ?', E'४६०० मेगावाट', E'४८०० मेगावाट', E'५००० मेगावाट', E'५५०० मेगावाट', 'B', E'आर्थिक वर्ष २०८२/८३ को बजेटले नेपालको कुल जडित विद्युत क्षमता **४८०० मेगावाट** पुऱ्याउने लक्ष्य राखेको छ।\nनोट: उक्त आर्थिक वर्षमा थप ९ सय मेगावाट बिजुली उत्पादन गरी यो लक्ष्य हासिल गरिनेछ।', 'nepali'),
      (v_set_id, 7, E'नेपाल वायु सेवा निगमको स्थापना कहिले भयो?', E'२०४९ जेठ ४', E'२०७७ कार्तिक २०', E'२०१९ असार १७', E'२००६ वैशाख ११', 'C', E'**नेपाल वायु सेवा निगमको स्थापना वि.सं. २०१९ असार १७ गते भएको हो।**\n- वि.सं. २०४९ जेठ ४ मा नेपाल एयरवेजले उडान सुरु गरेको थियो।\n- वि.सं. २०७७ कार्तिक २० मा नेपालमा पहिलो विमान दुर्घटना (भैरहवामा) भएको थियो।\n- वि.सं. २००६ वैशाख ११ मा नेपालमा पहिलो हवाईजहाज अवतरण भएको थियो।', 'nepali'),
      (v_set_id, 8, E'नेपाल सरकारले तलका मध्ये कुन आधारमा प्रदेश र स्थानीय तहलाई वित्तीय समानीकरण अनुदान वितरण गर्ने संवैधानिक व्यवस्था रहेको छ?', E'खर्चको आवश्यकता र जनसंख्याको आकार', E'भौगोलिक बनावट र राजस्वका स्रोतहरू', E'जीवनस्तरको सर्वेक्षण र राजस्वको क्षमता', E'खर्चको आवश्यकता र राजस्वको क्षमता', 'D', E'नेपालको संविधानको धारा ६० को उपधारा ४ अनुसार नेपाल सरकारले प्रदेश र स्थानीय तहलाई **खर्चको आवश्यकता र राजस्वको क्षमताको** आधारमा वित्तीय समानीकरण अनुदान वितरण गर्ने व्यवस्था छ।', 'nepali'),
      (v_set_id, 9, E'सबैभन्दा धेरै time zone भएको मुलुक कुन हो?', E'बेलायत', E'रुस', E'अमेरिका', E'फ्रान्स', 'D', E'सबैभन्दा धेरै टाइम जोन भएको मुलुक **फ्रान्स** हो, जहाँ कुल १२ वटा टाइम जोनहरू छन्।\n- रुस र अमेरिकामा ११-११ वटा टाइम जोनहरू रहेका छन्।\n- बेलायतमा ९ वटा टाइम जोनहरू छन्।\nनोट: अन्तर्राष्ट्रिय प्रमाणिक समय (UTC) सँग ग्रिनविच प्रमाणिक समय (GMT) को आधारमा विभिन्न मुलुकको टाइम जोन निर्धारण गरिन्छ।', 'nepali'),
      (v_set_id, 10, E'सौर्यमण्डलका भित्री ग्रहहरू (inner planets) मध्ये आकारका हिसाबले सबैभन्दा ठूलो ग्रह कुन हो?', E'पृथ्वी ग्रह', E'बृहस्पति ग्रह', E'शनि ग्रह', E'शुक्र ग्रह', 'A', E'सौर्यमण्डलका भित्री ग्रहहरूमध्ये आकारको हिसाबले सबैभन्दा ठूलो ग्रह **पृथ्वी** हो।\n- बृहस्पति ग्रह सौर्यमण्डलको सबैभन्दा ठूलो ग्रह हो, तर यो बाहिरी ग्रह (Outer Planet) अन्तर्गत पर्दछ।\n- शनि ग्रह सौर्यमण्डलको दोस्रो ठूलो ग्रह हो र यो पनि बाहिरी ग्रह हो।\n- शुक्र ग्रह आकारमा पृथ्वीसँग मिल्दोजुल्दो भए तापनि पृथ्वीभन्दा केही सानो छ।\nनोट: भित्री ग्रहहरूमा बुध, शुक्र, पृथ्वी र मंगल पर्दछन् भने बाहिरी ग्रहहरूमा बृहस्पति, शनि, अरुण र वरुण पर्दछन्।', 'nepali'),
      (v_set_id, 11, E'साझा पुरस्कार सर्वप्रथम कसलाई प्रदान गरिएको थियो?', E'बालकृष्ण सम', E'सत्यमोहन जोशी', E'माधवप्रसाद घिमिरे', E'भूपि शेरचन', 'D', E'साझा पुरस्कार सर्वप्रथम **भूपि शेरचन**लाई उनको कृति ''घुम्ने मेचमाथि अन्धो मान्छे'' का लागि प्रदान गरिएको थियो।\n- सत्यमोहन जोशीले ''हाम्रो लोक संस्कृति'' कृतिका लागि वि.सं. २०१३ मा सर्वप्रथम मदन पुरस्कार प्राप्त गरेका थिए।\n- बालकृष्ण समले वि.सं. २०२८ मा ''स्वास्नीमान्छे'' कृतिका लागि साझा पुरस्कार पाएका थिए।\n- माधवप्रसाद घिमिरेले वि.सं. २०५४ मा ''आफ्नो चिनारी आफ्नो चिन्तन'' कृतिका लागि साझा पुरस्कार पाएका थिए।\nनोट: साझा पुरस्कारको स्थापना वि.सं. २०२६ मा भएको थियो।', 'nepali'),
      (v_set_id, 12, E'अनन्त शक्ति स्रोत के हो?', E'कोइला', E'वनजङ्गल', E'पेट्रोल', E'सूर्य', 'D', E'**सूर्य** लाई अनन्त शक्तिको स्रोत मानिन्छ, किनकि यसले न्युक्लियर फ्युजन (Nuclear Fusion) नामक आणविक प्रतिक्रियाबाट निरन्तर अपार ऊर्जा उत्पादन गर्दछ।\n- कोइला एक जीवाश्म इन्धन हो र यसको भण्डार सीमित छ।\n- वनजङ्गल नवीकरणीय स्रोत भए तापनि यो अनन्त होइन र यसको अत्यधिक प्रयोगले विनाश निम्त्याउँछ।\n- पेट्रोल पनि जीवाश्म इन्धन हो, जुन कच्चा तेलबाट बन्छ र यसको स्रोत सीमित छ।', 'nepali'),
      (v_set_id, 13, E'संयुक्त राष्ट्र संघ को कति औं महासभाले ब्रुटल्याण्ड कमिसन गठन गरेको थियो?', E'३८ औं', E'३९ औं', E'४० औं', E'४१ औं', 'A', E'संयुक्त राष्ट्र संघको **३८ औं** महासभाले ब्रुटल्याण्ड कमिसन गठन गरेको थियो।\nनोट: यो कमिसन सन् १९८३ मा नर्वेकी प्रधानमन्त्री ग्रो हार्लेम ब्रुटल्याण्डको अध्यक्षतामा गठन गरिएको थियो, जसले दिगो विकासको अवधारणालाई अगाडि बढायो।', 'nepali'),
      (v_set_id, 14, E'संयुक्त राष्ट्रसंघ बडापत्र हालसम्म कतिपटक संशोधन भएको छ?', E'४ पटक', E'५ पटक', E'६ पटक', E'३ पटक', 'B', E'संयुक्त राष्ट्रसंघको बडापत्र हालसम्म **५ पटक** संशोधन भएको छ।\nनोट: बडापत्रका धारा २३, २७, ६१ र १०९ संशोधन भएका छन्, जसमा धारा ६१ लाई दुई पटक संशोधन गरिएको हुनाले कुल संशोधन संख्या पाँच पुगेको हो।', 'nepali'),
      (v_set_id, 15, E'वरिष्ठ कलाकार सुनिल थापाको निधन कहिले भएको छ ?', E'२०८२ माघ २४', E'२०८२ माघ २६', E'२०८२ माघ २८', E'२०८२ माघ २२', 'C', E'वरिष्ठ कलाकार सुनिल थापाको निधन **वि.सं. २०८२ माघ २८** गते भएको हो।\nनोट: उहाँ नेपाली चलचित्रमा ''राते काईंला'' को उपनामले चर्चित हुनुहुन्थ्यो र खलनायकको भूमिकालाई पनि नायक सरह चर्चा र सम्मान दिलाउन सफल हुनुभएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/१३', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_27.csv  →  आसमान दैनिक GK — २०८३/०१/२७  (10 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/२७'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/२७';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/२७', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'संयुक्त राष्ट्र संघको महासचिवको सिफारिस कुन अंगले गर्छ ?', E'महासभा', E'सचिवालय', E'न्यायालय', E'सुरक्षा परिषद्', 'D', E'संयुक्त राष्ट्र संघको महासचिवको सिफारिस **सुरक्षा परिषद्ले** गर्दछ।\n- महासभाले सुरक्षा परिषद्को सिफारिसमा महासचिवको नियुक्ति गर्दछ।\n- सचिवालय संयुक्त राष्ट्र संघको एक मुख्य प्रशासकीय अंग हो, जसको नेतृत्व महासचिवले गर्छन्।\n- अन्तर्राष्ट्रिय न्यायालय संयुक्त राष्ट्र संघको प्रमुख न्यायिक अंग हो।', 'nepali'),
      (v_set_id, 2, E'प्रमुख चुनौतीका रुपमा रहेको गरिबीलाई घटाउन निवारण गर्ने एकमात्र उद्देश्य कुन योजनाले राखेको थियो ?', E'नवौं योजना', E'आठौं योजना', E'सातौं योजना', E'दशौं योजना', 'A', E'**नवौं योजना (२०५४-२०५९)** ले गरिबी निवारणलाई आफ्नो एकमात्र मूल उद्देश्यको रूपमा राखेको थियो।\n- आठौं योजना (२०४९-२०५४) बाट दिगो विकासको अवधारणा सुरु भएको थियो।\n- सातौं योजना (२०४२-२०४७) मा पहिलोपटक वातावरण प्रभाव मूल्याङ्कन (EIA) को सुरुवात गरियो।\n- दशौं योजना (२०५९-२०६४) ले सहस्राब्दी विकास लक्ष्य (MDGs) लाई आत्मसात् गरेको थियो।\nनोट: नवौं योजनाले दीर्घकालीन सोच र सामाजिक सुरक्षाको अवधारणा पनि सुरु गरेको थियो।', 'nepali'),
      (v_set_id, 3, E'हाल उत्तर एटलान्टिक सन्धि संगठन (नेटो) को सदस्य राष्ट्रहरूको संख्या कति रहेको छ?', E'३२ मुलुक', E'३१ मुलुक', E'३३ मुलुक', E'३४ मुलुक', 'A', E'उत्तर एटलान्टिक सन्धि संगठन (नेटो) को सदस्य राष्ट्रहरूको संख्या **३२** पुगेको छ। स्वीडेन सन् २०२४ मार्च ७ मा नेटोको ३२औं सदस्य राष्ट्र बनेको हो।\nनोट: यसअघि फिनल्यान्ड सन् २०२३ अप्रिल ४ मा ३१औं सदस्य राष्ट्र बनेको थियो।', 'nepali'),
      (v_set_id, 4, E'विश्वमा कार्यक्रम बजेटको सुरुवात गर्ने पहिलो मुलुक कुन हो ?', E'अमेरिका', E'फ्रान्स', E'बेलायत', E'अस्ट्रेलिया', 'A', E'विश्वमा कार्यक्रम बजेटको सुरुवात गर्ने पहिलो मुलुक **अमेरिका** हो।\n- फ्रान्स विश्वमा वर्षमा दुईपटक बजेट पेश गर्ने राष्ट्र हो।\n- बेलायतबाट बजेट प्रणालीको सुरुवात भएको हो।\n- अस्ट्रेलियाबाट विश्वमा लैंगिक उत्तरदायी बजेटको सुरुवात भएको थियो।', 'nepali'),
      (v_set_id, 5, E'पृथ्वीको ध्रुवीय रेखीय व्यास कति किलोमिटर रहेको छ ?', E'12756 कि मि', E'12742 कि मि', E'12735 कि मि', E'12714 कि मि', 'D', E'पृथ्वीको ध्रुवीय व्यास **१२,७१४ कि.मि.** रहेको छ। पृथ्वीको भूमध्यरेखीय व्यास १२,७५६ कि.मि. र औसत व्यास १२,७३५ कि.मि. छ।\nनोट: पृथ्वीको ध्रुवीय व्यासभन्दा भूमध्यरेखीय व्यास ४२ कि.मि.ले बढी रहेको छ।', 'nepali'),
      (v_set_id, 6, E'नेपालमा कुन योजनाबाट जलवायु परिवर्तन समावेश गरिएको हो ?', E'छैठौं योजना', E'आठौं योजना', E'नवौं योजना', E'तेह्रौं योजना', 'D', E'नेपालमा **तेह्रौं योजना**बाट जलवायु परिवर्तनको विषयलाई समावेश गरिएको हो।\n- छैठौं योजनाबाट वातावरण संरक्षण नीति सम्बन्धी व्यवस्था सुरु भएको थियो।\n- आठौं योजनादेखि दिगो विकाससम्बन्धी अवधारणालाई समावेश गरिएको थियो।\n- नवौं योजनादेखि जैविक विविधता संरक्षण नीति सुरु भएको थियो।', 'nepali'),
      (v_set_id, 7, E'सर्वप्रथम क्लोरोफ्लोरोकार्बन ग्याँसको उत्पादन गर्ने वैज्ञानिक को हुन् ?', E'जे सि फारम्यान', E'शेरउड रोल्याण्ड', E'डोब्सन', E'थोमस मिज', 'D', E'सर्वप्रथम क्लोरोफ्लोरोकार्बन (CFC) ग्याँसको उत्पादन गर्ने वैज्ञानिक **डा. थोमस मिज** हुन्।\n- जे.सि.फारम्यानले सर्वप्रथम ओजोन तह पत्ता लगाएका थिए।\n- शेरउड रोल्याण्डले सर्वप्रथम ओजोन तह पातलिँदै गएको पत्ता लगाएका थिए।\n- डोब्सनले सर्वप्रथम ओजोन बिनास दर पत्ता लगाएका थिए।', 'nepali'),
      (v_set_id, 8, E'नेपालको वर्तमान संविधानको कुन धारामा स्वच्छ वातावरणको हक उल्लेख गरेको छ ?', E'धारा ३०', E'धारा ३२', E'धारा ३४', E'धारा २८', 'A', E'नेपालको वर्तमान संविधानको **धारा ३०** मा स्वच्छ वातावरणको हक उल्लेख गरिएको छ।\n- धारा ३२ मा भाषा तथा संस्कृतिको हकको व्यवस्था छ।\n- धारा ३४ मा श्रमको हकको व्यवस्था गरिएको छ।\n- धारा २८ मा गोपनीयताको हक उल्लेख छ।', 'nepali'),
      (v_set_id, 9, E'''टीका vaccine'' पत्ता लगाउने वैज्ञानिक को हुन् ?', E'थोमस अल्वा एडिसन', E'सर आइज्याक न्युटन', E'ग्यालिलियो ग्यालिली', E'लुई पाश्चर', 'D', E'**लुई पाश्चर** ''टीका'' (Vaccine) पत्ता लगाउने वैज्ञानिक हुन्। उनले रेबिज विरुद्धको खोप, पाश्चराइजेसन प्रक्रिया र ब्याक्टेरियाको खोज जस्ता महत्वपूर्ण कार्यहरू गरेका थिए।\n- थोमस अल्वा एडिसनले विद्युतीय बत्ती (light bulb) र फोनोग्राफको आविष्कार गरेका थिए।\n- सर आइज्याक न्युटन गुरुत्वाकर्षणको नियम र गतिको तीन नियमहरूका लागि प्रसिद्ध छन्।\n- ग्यालिलियो ग्यालिलीले टेलिस्कोपमा सुधार गरी महत्वपूर्ण खगोलीय अवलोकनहरू गरेका थिए।', 'nepali'),
      (v_set_id, 10, E'१६ औं योजनाको अन्त्यसम्म नेपालको प्रतिव्यक्ति राष्ट्रिय आय कति पुर्याउने लक्ष्य रहेको छ ?', E'२२५१ अमेरिकी डलर', E'२३५१ अमेरिकी डलर', E'२४५१ अमेरिकी डलर', E'२५५१ अमेरिकी डलर', 'B', E'नेपालको सोह्रौं आवधिक योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्ममा प्रतिव्यक्ति राष्ट्रिय आय **२३५१ अमेरिकी डलर** पुर्याउने लक्ष्य निर्धारण गरिएको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/२७', 10;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_28.csv  →  आसमान दैनिक GK — २०८३/०१/२८  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/२८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/२८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/२८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'दरबार हाइस्कूलको स्थापना कहिले भएको हो?', E'वि.सं. १९१०', E'वि.सं. १९१२', E'वि.सं. १९१४', E'वि.सं. १९१६', 'A', E'जंगबहादुर राणाले **वि.सं. १९१०** मा दरबार हाइस्कूलको स्थापना गरेका थिए।\nनोट: वीर समसेरले सर्वसाधारणका छोराछोरीलाई पनि दरबार हाइस्कूलमा पढ्न पाउने व्यवस्था मिलाएका थिए भने देव समसेरले वि.सं. १९५८ मा भाषा पाठशालाको स्थापना गरेका थिए।', 'nepali'),
      (v_set_id, 2, E'कुसवाडिया जातिको मुख्य बसोबास क्षेत्र कुन हो?', E'बाँके, बर्दिया', E'कैलाली, कन्चनपुर', E'दाङ, बाँके', E'सल्यान, दाङ', 'A', E'कुसवाडिया जातिको मुख्य बसोबास क्षेत्र **बाँके र बर्दिया** जिल्ला हो।\nनोट: यो जातिलाई ''कुछबन्दिया'' पनि भनिन्छ र यिनीहरूले आफूलाई प्रकृति पुजक भन्न रुचाउँछन्।', 'nepali'),
      (v_set_id, 3, E'नेपालको संविधान अनुसार कुन शिक्षा अनिवार्य र निःशुल्क रहेको छ?', E'माध्यमिक', E'आधारभूत', E'आधारभूत र माध्यमिक', E'उच्च शिक्षा', 'B', E'नेपालको संविधान अनुसार **आधारभूत शिक्षा** अनिवार्य र निःशुल्क रहेको छ।\n- माध्यमिक तहको शिक्षा निःशुल्क पाउने हक भए तापनि अनिवार्य छैन।\n- उच्च शिक्षा अपांगता भएका र आर्थिक रूपले विपन्न नागरिकलाई मात्र कानून बमोजिम निःशुल्क हुने व्यवस्था छ।\n- आधारभूत र माध्यमिक दुवै तह अनिवार्य र निःशुल्क हुने व्यवस्था छैन।\nनोट: शिक्षा सम्बन्धी यो हक नेपालको संविधानको धारा ३१ मा मौलिक हकको रूपमा व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 4, E'सोह्रौं योजनाको अन्त्य सम्म नेपालको गरिबीको रेखामुनी रहेको जनसंख्या (निरपेक्ष गरिबी) कति पुऱ्याउने लक्ष्य रहेको छ?', E'१२ प्रतिशत', E'११ प्रतिशत', E'० प्रतिशत', E'५ प्रतिशत', 'A', E'सोह्रौं योजना (आ.व. २०८१/८२ - २०८५/८६) को अन्त्यसम्ममा नेपालमा निरपेक्ष गरिबीको रेखामुनि रहेको जनसंख्यालाई **१२ प्रतिशतमा** झार्ने लक्ष्य निर्धारण गरिएको छ।\nनोट: नेपालले सन् २१०० सम्ममा निरपेक्ष गरिबीलाई शून्यमा झार्ने दीर्घकालीन लक्ष्य लिएको छ।', 'nepali'),
      (v_set_id, 5, E'तलका मध्ये प्रमुख हरितगृह ग्याँस कुन हो?', E'कार्बनडाइअक्साइड', E'क्लोरोफ्लोरो कार्बन', E'मिथेन', E'सल्फरडाइअक्साइड', 'A', E'**कार्बनडाइअक्साइड प्रमुख हरितगृह ग्याँस हो।**\n- क्लोरोफ्लोरो कार्बन (CFC) ओजोन तहको विनाश गर्ने प्रमुख ग्याँस हो।\n- मिथेन (CH4) पनि एक महत्त्वपूर्ण हरितगृह ग्याँस हो, जुन कृषि र पशुपालनबाट उत्सर्जन हुन्छ।\n- सल्फरडाइअक्साइड (SO2) अम्लीय वर्षाको प्रमुख कारक हो।', 'nepali'),
      (v_set_id, 6, E'२०७८ सालको जनगणना अनुसार जनसङ्ख्या बृद्धीदर दोस्रो बढी भएको जिल्ला कुन हो?', E'रुपन्देही', E'चितवन', E'भक्तपुर', E'झापा', 'A', E'**२०७८ सालको जनगणना अनुसार रुपन्देही जिल्लाको जनसंख्या वृद्धिदर दोस्रो उच्च रहेको छ।**\n- चितवन जनसंख्या वृद्धिदरमा तेस्रो स्थानमा छ।\n- भक्तपुर जनसंख्या वृद्धिदरमा पहिलो स्थानमा छ।\n- झापा जनसंख्या वृद्धिदरमा पाँचौं स्थानमा छ।\nनोट: जनसंख्या वृद्धिदर सबैभन्दा कम भएको जिल्ला रामेछाप हो।', 'nepali'),
      (v_set_id, 7, E'विश्वको सबैभन्दा बिकशित, ठूलो, पुरानो भाषा परिवार कुन हो?', E'Indo-european', E'sino-tibetan', E'astro-asiatic', E'darvidian', 'A', E'**भारोपेली (Indo-European) भाषा परिवार विश्वको सबैभन्दा विकसित, ठूलो र पुरानो भाषा परिवार मानिन्छ।**\n- चिनियाँ तिब्बती-भोटबर्मेली (Sino-Tibetan) परिवारमा नेवारी, गुरुङ, तामाङ, मगर, राई, लिम्बु जस्ता भाषाहरू पर्दछन्।\n- आग्नेय (Astro-Asiatic) परिवारमा नेपालमा बोलिने सतार वा सन्थाली भाषा पर्दछ।\n- द्रविड (Dravidian) परिवारमा नेपालमा बोलिने झाँगड वा धाँगड भाषा पर्दछ।\nनोट: नेपाली भाषा पनि भारोपेली भाषा परिवार अन्तर्गत पर्दछ।', 'nepali'),
      (v_set_id, 8, E'नेपालको कुल अन्तर्राष्ट्रिय सिमाना कति कि. मि. रहेको छ?', E'२८२६ कि मि', E'२८३६ कि मि', E'२९२६ कि मि', E'२९३६ कि मि', 'C', E'नेपालको कुल अन्तर्राष्ट्रिय सिमाना **२९२६ कि.मि.** रहेको छ।\n- यो सिमाना भारतसँग १६९० कि.मि. र चीनसँग १२३६ कि.मि. रहेको छ।', 'nepali'),
      (v_set_id, 9, E'नेपालको भूगोलमा सबैभन्दा धेरै नगरपालिका कुन प्रदेशमा अवस्थित छन्?', E'बागमती प्रदेश', E'कोशी प्रदेश', E'लुम्बिनी प्रदेश', E'मधेश प्रदेश', 'D', E'**नेपालमा सबैभन्दा धेरै नगरपालिका भएको प्रदेश मधेश प्रदेश हो, जहाँ ७३ वटा नगरपालिकाहरू छन्।**\n- बागमती प्रदेशमा ४१ वटा नगरपालिकाहरू छन्।\n- कोशी प्रदेशमा सबैभन्दा बढी स्थानीय तह (१३७) र गाउँपालिका (८८) छन्, तर नगरपालिकाको संख्या ४६ मात्र छ।\n- लुम्बिनी प्रदेशमा ३२ वटा नगरपालिकाहरू छन्।\nनोट: सबैभन्दा कम स्थानीय तह (७९) भएको प्रदेश कर्णाली हो।', 'nepali'),
      (v_set_id, 10, E'अन्नपूर्ण संरक्षण क्षेत्रको क्षेत्रफल कति रहेको छ?', E'६७९२ वर्ग कि.मि.', E'७२६९ वर्ग कि.मि.', E'७६२९ वर्ग कि.मि.', E'७६९२ वर्ग कि.मि.', 'C', E'अन्नपूर्ण संरक्षण क्षेत्रको क्षेत्रफल **७६२९ वर्ग कि.मि.** रहेको छ।\nनोट: यो नेपालको पहिलो संरक्षण क्षेत्र हो, जुन वि.सं. २०४९ मा स्थापना भएको थियो र लमजुङ, मनाङ, मुस्ताङ, म्याग्दी तथा कास्की जिल्लामा फैलिएको छ।', 'nepali'),
      (v_set_id, 11, E'तराई प्रदेशको जनसंख्या कति रहेको छ?', E'५५.६१ प्रतिशत', E'५३.६१ प्रतिशत', E'५१.६१ प्रतिशत', E'५३.५१ प्रतिशत', 'B', E'राष्ट्रिय जनगणना २०७८ अनुसार, तराई प्रदेशको जनसंख्या कुल जनसंख्याको **५३.६१ प्रतिशत** रहेको छ, जुन १ करोड ५६ लाख ३४ हजार ६ जना हो।\nनोट: सोही जनगणना अनुसार पहाडमा ४०.३१ प्रतिशत र हिमालमा ६.०८ प्रतिशत जनसंख्या रहेको छ।', 'nepali'),
      (v_set_id, 12, E'पृथ्वी पछि सबैभन्दा धेरै घनत्व भएको ग्रह कुन हो ?', E'शुक्र', E'बुध', E'मंगल', E'बृहस्पति', 'B', E'पृथ्वी पछि सबैभन्दा धेरै घनत्व भएको ग्रह **बुध** हो।\n- शुक्र घनत्वको आधारमा तेस्रो स्थानमा पर्छ।\n- मंगल घनत्वको आधारमा चौथो स्थानमा पर्छ।\n- बृहस्पति घनत्वको आधारमा छैटौं स्थानमा पर्छ।\nनोट: घनत्वका आधारमा ग्रहहरूको क्रम यसप्रकार छ: पृथ्वी, बुध, शुक्र, मंगल, वरुण, बृहस्पति, अरुण, र शनि।', 'nepali'),
      (v_set_id, 13, E'नेपालको भूगोलको सबैभन्दा अग्लो स्थानमा रहेको झरना कुन हो?', E'हयातुङ', E'अरुण', E'पचाल', E'सुलिगढ', 'D', E'नेपालको भूगोलको सबैभन्दा अग्लो स्थानमा (highest altitude) रहेको झरना **सुलिगढ झरना** हो, जुन डोल्पा जिल्लामा पर्दछ।\n- हयातुङ झरना नेपालको दोस्रो अग्लो (tallest) झरना हो, जुन ३६५ मिटर अग्लो छ र तेह्रथुममा पर्दछ।\n- अरुण नेपालको सबैभन्दा अग्लो स्थानमा बग्ने नदी हो।\n- पचाल झरना नेपालको सबैभन्दा अग्लो (tallest) झरना हो, जुन ३८१ मिटर अग्लो छ र कालिकोटमा पर्दछ।', 'nepali'),
      (v_set_id, 14, E'नेपालको संविधान धारा ७ पहिलो पटक प्रयोगमा ल्याउने प्रदेश कुन हो?', E'बागमती', E'कोशी', E'गण्डकी', E'कर्णाली', 'A', E'नेपालको संविधानको धारा ७ लाई पहिलो पटक प्रयोगमा ल्याउने प्रदेश **बागमती प्रदेश** हो। बागमती प्रदेशले वि.सं. २०८१ वैशाख २४ देखि नेपाली भाषाका अतिरिक्त तामाङ र नेपाल भाषालाई पनि सरकारी कामकाजको भाषाको रूपमा लागू गरेको छ।\nनोट: संविधानको धारा ७ को उपधारा (२) ले प्रदेशलाई आफ्नो क्षेत्रभित्र बहुसंख्यकले बोल्ने एक वा एकभन्दा बढी राष्ट्र भाषालाई सरकारी कामकाजको भाषा निर्धारण गर्ने अधिकार दिएको छ।', 'nepali'),
      (v_set_id, 15, E'२९ वर्षको उमेरमा भगवान गौतम बुद्ध घर छोडेर भिक्षु बने, यो घटनालाई के भनिन्छ?', E'महाभिनिष्क्रमण', E'धर्मचक्रप्रवर्तन', E'भिक्षुमहास्थान', E'महापरिनिर्वाण', 'A', E'भगवान गौतम बुद्धले २९ वर्षको उमेरमा घर छोडेर भिक्षु बनेको घटनालाई **महाभिनिष्क्रमण** भनिन्छ।\n- धर्मचक्रप्रवर्तन बुद्धले दिनुभएको पहिलो उपदेशलाई भनिन्छ।\n- भिक्षुमहास्थान कुनै विशेष बौद्ध पारिभाषिक शब्द होइन।\n- महापरिनिर्वाण गौतम बुद्धको निधनको घटनालाई भनिन्छ।', 'nepali'),
      (v_set_id, 16, E'एसियाली विकास बैंकको दक्षिण एसिया विभाग महानिर्देशकमा नियुक्त हुन सफल नेपाली को हुन् ?', E'निर्मला शर्मा', E'सविता भण्डारी', E'चन्द्रकला पौडेल', E'सोना श्रेष्ठ', 'D', E'सोना श्रेष्ठ एसियाली विकास बैंक (ADB) को दक्षिण एसिया विभागको महानिर्देशकमा नियुक्त भएकी छिन्। उनी **वि.सं. २०८२ माघ २९ (सन् २०२६ फेब्रुअरी १२)** मा नियुक्त भएकी हुन्।\nनोट: उनको कार्यक्षेत्रमा नेपाल, भारत, भुटान, बंगलादेश, माल्दिभ्स र श्रीलंका पर्दछन्।', 'nepali'),
      (v_set_id, 17, E'विश्व रेडियो दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'फेब्रुअरी ११', E'फेब्रुअरी १३', E'फेब्रुअरी १५', E'फेब्रुअरी १७', 'B', E'विश्व रेडियो दिवस प्रत्येक वर्ष **फेब्रुअरी १३** मा मनाइन्छ। पहिलोपटक यो दिवस सन् २०१२ फेब्रुअरी १३ मा मनाइएको थियो।\nनोट: सन् २०२६ को नारा ''Radio and Artificial Intelligence: AI is a tool, not a voice'' रहेको थियो।', 'nepali'),
      (v_set_id, 18, E'अन्तर्राष्ट्रिय मुद्रा कोष, २०२४ अनुसार नेपालको मुद्रास्फीति कति रहेको छ?', E'३.९ प्रतिशत', E'४.९ प्रतिशत', E'६.९ प्रतिशत', E'५.९ प्रतिशत', 'B', E'अन्तर्राष्ट्रिय मुद्रा कोष (IMF) को २०२४ को प्रतिवेदन अनुसार, सन् २०२५ मा नेपालको मुद्रास्फीति **४.९ प्रतिशत** रहने प्रक्षेपण गरिएको थियो।\nनोट: सोही प्रतिवेदनले सन् २०२५ मा विश्व अर्थतन्त्रको मुद्रास्फीति २.५ प्रतिशत र दक्षिण एसियाली मुलुकमध्ये बंगलादेशको सबैभन्दा बढी (१०.० प्रतिशत) रहने उल्लेख गरेको थियो।', 'nepali'),
      (v_set_id, 19, E'देहायका मध्ये कुन देश सँग नेपालको विप्पा सम्झौता भएको छैन?', E'बेलायत', E'फिनल्यान्ड', E'चीन', E'जर्मनी', 'C', E'नेपालले चीनसँग विप्पा (द्विपक्षीय लगानी प्रवर्द्धन तथा संरक्षण सम्झौता) गरेको छैन। नेपालले हालसम्म जम्मा **६ वटा** मुलुकसँग यस्तो सम्झौता गरेको छ, जसमा बेलायत, फिनल्यान्ड र जर्मनी पनि पर्दछन्।\nनोट: विप्पा सम्झौता भएका अन्य राष्ट्रहरू फ्रान्स, भारत र मौरिसस हुन्। पहिलो सम्झौता फ्रान्ससँग (२ मे १९८३) र अन्तिम भारतसँग (२१ अक्टोबर २०११) भएको थियो।', 'nepali'),
      (v_set_id, 20, E'नेपालको संविधानको कुन धारामा उपराष्ट्रपतिको सम्बन्ध व्यवस्था गरेको छ?', E'धारा ६८', E'धारा ६७', E'धारा ६६', E'धारा ६९', 'B', E'नेपालको संविधानको **धारा ६७** मा उपराष्ट्रपति सम्बन्धी व्यवस्था गरिएको छ।\nनोट: संविधानको भाग ६ मा राष्ट्रपति र उपराष्ट्रपति सम्बन्धी व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 21, E'''Red Planet'' को उपनामले सौर्यमण्डलको कुन ग्रहलाई चिनिन्छ?', E'शुक्र', E'बुध', E'मंगल', E'पृथ्वी', 'C', E'**मंगल ग्रहलाई ''Red Planet'' (रातो ग्रह) को उपनामले चिनिन्छ।**\n- शुक्र ग्रहलाई ''Morning Star'' र ''Evening Star'' को रूपमा चिनिन्छ।\n- बुध सौर्यमण्डलको सबैभन्दा सानो ग्रह हो।\n- पृथ्वीलाई ''Blue Planet'' (निलो ग्रह) भनिन्छ।\nनोट: मंगल ग्रहको सतहमा आइरन अक्साइड (फलामको खिया) को प्रचुरताले गर्दा यो रातो देखिन्छ।', 'nepali'),
      (v_set_id, 22, E'ठूलो भूपरिवेष्ठित राष्ट्र कजाकिस्तान विश्वको कति औं ठूलो मुलुक हो?', E'आठौं', E'नवौं', E'दशौं', E'एघारौं', 'B', E'क्षेत्रफलको आधारमा विश्वको सबैभन्दा ठूलो भूपरिवेष्ठित राष्ट्र कजाकिस्तान विश्वको **नवौं** ठूलो मुलुक हो।\nनोट: विश्वको सबैभन्दा ठूलो देश रुस हो भने सबैभन्दा सानो भूपरिवेष्ठित राष्ट्र भ्याटिकन सिटी हो।', 'nepali'),
      (v_set_id, 23, E'नेपाल एसियाको कति औं ठूलो देश हो?', E'२४ औं', E'२५ औं', E'२६ औं', E'२७ औं', 'C', E'क्षेत्रफलको आधारमा नेपाल एसियाको **२६ औं** ठूलो देश हो।\nनोट: नेपाल विश्वको ९३ औं ठूलो, सार्कमा ५ औं ठूलो र विश्वको २१ औं ठूलो भूपरिवेष्ठित देश हो।', 'nepali'),
      (v_set_id, 24, E'हिटलर जर्मनीको तानाशाह कहिले बनेका हुन्?', E'सन् १९२१', E'सन् १९३३', E'सन् १९३४', E'सन् १९४५', 'C', E'**हिटलर सन् १९३४ मा जर्मनीको तानाशाह बनेका थिए।**\n- सन् १९२१ मा हिटलरले नाजी पार्टीको स्थापना गरेका थिए।\n- सन् १९३३ मा राष्ट्रपति हिन्देनबर्गले हिटलरलाई जर्मनीको चान्सलर (प्रधानमन्त्री) नियुक्त गरेका थिए।\n- सन् १९४५ अप्रिल ३० मा हिटलरले दोस्रो विश्वयुद्धमा पराजयपछि आत्महत्या गरेका थिए।\nनोट: हिटलरको नारा ''एक राष्ट्र, एक देश, एक नेता'' थियो।', 'nepali'),
      (v_set_id, 25, E'देहायका मध्ये कुन कथन मानदेवसँग सम्बन्धित छैन?', E'सर्वप्रथम शिलालेखको स्थापना', E'पहिलो मुद्रा प्रचलन', E'गोकर्णमा मानव वस्ती', E'गुप्त संवत् सुरु', 'D', E'**गुप्त संवत् सुरु गर्ने कार्य मानदेवसँग सम्बन्धित छैन।**\n- सर्वप्रथम शिलालेखको स्थापना मानदेवले गरेका थिए।\n- पहिलो मुद्रा प्रचलन मानदेवले गरेका थिए।\n- गोकर्णमा मानव वस्ती बसाल्ने काम मानदेवले गरेका थिए।\nनोट: गुप्त संवत् अंशुवर्माले चलाएका थिए।', 'nepali'),
      (v_set_id, 26, E'२९ वर्षको उमेरमा भगवान गौतम बुद्ध घर छोडेर भिक्षु बने, यो घटनालाई के भनिन्छ?', E'महाभिनिष्क्रमण', E'धर्मचक्रप्रवर्तन', E'भिक्षुमहास्थान', E'महापरिनिर्वाण', 'A', E'**भगवान गौतम बुद्धले २९ वर्षको उमेरमा घर छोडेर भिक्षु बनेको घटनालाई महाभिनिष्क्रमण भनिन्छ।**\n- बुद्धले दिएको पहिलो उपदेशलाई धर्मचक्रप्रवर्तन भनिन्छ।\n- गौतम बुद्धको निधनको घटनालाई महापरिनिर्वाण भनिन्छ।\n- भिक्षुमहास्थान बौद्ध धर्मको कुनै विशेष घटना वा शब्दावली होइन।\nनोट: बुद्ध धर्मको दर्शनलाई प्रतित्यसमुत्पाद भनिन्छ।', 'nepali'),
      (v_set_id, 27, E'मर्नेको नामबाट चौतारा अनिवार्य बनाउनु पर्ने चलन कुन जातिमा रहेको छ?', E'मेचे', E'चेपाङ', E'थामी', E'दुरा', 'C', E'**थामी जातिमा** मर्नेको नामबाट चौतारा अनिवार्य बनाउनु पर्ने चलन रहेको छ।\nनोट: यस जातिमा मंसिरमा मात्र विवाह गर्ने र दुलाहा-दुलहीको टाउको ६ पटक ठोकाएर विवाह गर्ने अनौठो चलन पनि रहेको छ।', 'nepali'),
      (v_set_id, 28, E'दुखाई मापन गर्ने यन्त्र देहाएका मध्ये कुन हो?', E'ल्याक्टोमिटर', E'एल्गोमिटर', E'ब्रेथलाइजर', E'पोलिग्राफ', 'B', E'दुखाई मापन गर्ने यन्त्रलाई **एल्गोमिटर** भनिन्छ।\n- ल्याक्टोमिटरले दूधको शुद्धता मापन गर्दछ।\n- ब्रेथलाइजरले चालकले मादक पदार्थ सेवन गरे/नगरेको जाँच्न प्रयोग गरिन्छ।\n- पोलिग्राफ झुटो बोलेको पत्ता लगाउन प्रयोग हुने यन्त्र हो।', 'nepali'),
      (v_set_id, 29, E'United Nations Climate Change Conference (Cop-29) ले २०३५ सम्ममा विकसित देशले वार्षिक कम्तिमा कति रकम जलवायु कोषमा जम्मा गर्ने वित्तीय लक्ष्य लिएको छ?', E'१०० अर्ब USS', E'२०० अर्ब USS', E'३०० अर्ब USS', E'४०० अर्ब USS', 'C', E'COP-29 ले २०३५ सम्ममा विकसित देशहरूले वार्षिक कम्तिमा **३०० अर्ब अमेरिकी डलर** जलवायु कोषमा जम्मा गर्ने नयाँ वित्तीय लक्ष्य लिएको छ।\nनोट: यसअघि पेरिस सम्झौता अनुसार सन् २०२२ सम्म वार्षिक १०० अर्ब डलर जम्मा गर्ने लक्ष्य थियो, जसलाई प्रतिस्थापन गर्दै यो नयाँ लक्ष्य निर्धारण गरिएको हो।', 'nepali'),
      (v_set_id, 30, E'भारत र पाकिस्तान पछि धेरै जनसंख्या भएको सार्क मुलुक कुन हो?', E'अफगानिस्तान', E'बंगलादेश', E'नेपाल', E'श्रीलंका', 'B', E'भारत र पाकिस्तान पछि सार्क मुलुकहरूमा सबैभन्दा धेरै जनसंख्या भएको देश **बंगलादेश** हो।\nनोट: सार्क मुलुकहरूको जनसंख्याको क्रम (घट्दो क्रममा) यसप्रकार छ: भारत, पाकिस्तान, बंगलादेश, अफगानिस्तान, नेपाल, श्रीलंका, भुटान र माल्दिभ्स।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/२८', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_30.csv  →  आसमान दैनिक GK — २०८३/०१/३०  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/३०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/३०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/३०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'निरपेक्ष गरिबी भन्नाले के जनाउँछ?', E'आधारभूत आवश्यकताहरू नपुगेको अवस्था', E'अरूसँग तुलना गर्दा कम आय भएको अवस्था', E'धनी र गरिब बीचको असमानता', E'केवल ग्रामीण क्षेत्रमा पाइने गरिबी', 'A', E'निरपेक्ष गरिबी भन्नाले मानिसलाई जीवनयापनका लागि आवश्यक पर्ने **आधारभूत आवश्यकताहरू (जस्तै: गाँस, बास, कपास) नपुगेको अवस्था** हो।\n- अरूसँग तुलना गर्दा कम आय भएको अवस्थालाई सापेक्ष गरिबी भनिन्छ।\n- धनी र गरिब बीचको असमानताले आय असमानतालाई जनाउँछ।\n- गरिबी ग्रामीण र शहरी दुवै क्षेत्रमा पाइने हुनाले केवल ग्रामीण क्षेत्रमा मात्र पाइन्छ भन्नु गलत हो।', 'nepali'),
      (v_set_id, 2, E'आर्थिक वर्ष २०८२/८३ को बजेटले कुन दिनलाई जातीय भेदभाव तथा छुवाछुत उन्मुलन राष्ट्रिय दिवस मनाउने घोषणा गरेको छ?', E'जेठ १६', E'जेठ १७', E'जेठ २०', E'जेठ २१', 'D', E'आर्थिक वर्ष २०८२/८३ को बजेटले हरेक वर्ष **जेठ २१** लाई जातीय भेदभाव तथा छुवाछुत उन्मुलन राष्ट्रिय दिवस मनाउने घोषणा गरेको छ।\nनोट: सरकारले छुवाछुत र भेदभाव रहित समाज निर्माणमा बल पुर्याउने उद्देश्यले यो दिवस मनाउने निर्णय गरेको हो।', 'nepali'),
      (v_set_id, 3, E'उच्च अदालतका मुख्य न्यायाधीश तथा न्यायाधीशको पद रिक्त कति वर्ष उमेर पुरा भएमा हुन्छ?', E'६० वर्ष', E'६२ वर्ष', E'६३ वर्ष', E'६५ वर्ष', 'C', E'उच्च अदालतका मुख्य न्यायाधीश तथा न्यायाधीशको पद **६३ वर्ष** उमेर पुरा भएमा रिक्त हुन्छ।\n- ६५ वर्षको उमेरमा भने प्रधान न्यायाधीश वा सर्वोच्च अदालतको न्यायाधीशको पद रिक्त हुने व्यवस्था छ।', 'nepali'),
      (v_set_id, 4, E'२०८२ सालमा कति औं सेना दिवस मनाइएको छ ?', E'२६१ औं', E'२६२ औं', E'२६३ औं', E'२६४ औं', 'C', E'नेपाली सेनाले वि.सं. २०८२ सालमा आफ्नो **२६३ औं** सेना दिवस मनाएको छ।\nनोट: सेना दिवस प्रत्येक वर्ष महाशिवरात्रीको दिन मनाइन्छ र २०८२ को कार्यक्रममा राष्ट्रपति रामचन्द्र पौडेल प्रमुख अतिथि हुनुहुन्थ्यो।', 'nepali'),
      (v_set_id, 5, E'सन् २०२६ फेब्रुअरीमा बंगलादेशको प्रधानमन्त्री बन्न सफल राजनीतिज्ञ को हुन्?', E'तारिक रहमान', E'सादिक सेक', E'फरहान अली', E'जमाल हसन', 'A', E'बंगलादेश राष्ट्रिय पार्टी (बीएनपी) का अध्यक्ष **तारिक रहमान** सन् २०२६ फेब्रुअरी १७ मा बंगलादेशको प्रधानमन्त्री बनेका छन्।\nनोट: ६० वर्षीय तारिक पूर्व राष्ट्रपति जियाउर रहमान तथा बंगलादेशकी प्रथम महिला प्रधानमन्त्री बेगम खालिदा जियाका छोरा हुन्।', 'nepali'),
      (v_set_id, 6, E'मानचित्र विधा (The Art of Map) भन्नाले केलाई जनाउँदछ?', E'Climatology', E'Cartography', E'Hydrology', E'Mapology', 'B', E'**नक्सा बनाउने विज्ञान र कलालाई मानचित्र विधा (Cartography) भनिन्छ।**\n- Climatology भन्नाले जलवायु र मौसमको ढाँचा (Patterns) को अध्ययनलाई बुझाउँछ।\n- Hydrology भन्नाले नदी, ताल र पानी सहित जल स्रोतहरूको अध्ययन (जलविज्ञान) लाई जनाउँछ।\n- Mapology कुनै स्थापित प्राविधिक शब्द होइन, तर यसले सामान्यतया नक्सासँग सम्बन्धित अध्ययनलाई जनाउन सक्छ।', 'nepali'),
      (v_set_id, 7, E'कुमारी हिमालको उपनामले कुन हिमाललाई चिनिन्छ?', E'जुगल', E'अन्नपूर्ण', E'माछापुच्छ्रे', E'मनास्लु', 'C', E'**माछापुच्छ्रे हिमाललाई कुमारी हिमाल वा ''Mother Horn of Nepal'' को उपनामले चिनिन्छ।**\n- जुगल हिमाललाई भर्जिन हिमाल भनिन्छ।\n- अन्नपूर्ण हिमाललाई देवता हिमाल भनिन्छ।\n- मनास्लु हिमाललाई किलर माउन्टेन वा कटनको उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 8, E'"प्रत्येक व्यक्तिलाई कानुन अनुसार नै दण्ड दिइने छ" भन्ने कुरा महाधिकारपत्र म्याग्नाकार्टाको कुन धारामा व्यवस्था गरिएको छ?', E'धारा ५४', E'धारा ३८', E'धारा ३९', E'धारा १', 'C', E'**"प्रत्येक व्यक्तिलाई कानुन अनुसार नै दण्ड दिइने छ" भन्ने कुरा म्याग्नाकार्टाको धारा ३९ मा व्यवस्था गरिएको छ।**\n- धारा ५४ मा राजाले पनि कानुन मान्नु पर्ने व्यवस्था छ।\n- धारा ३८ मा व्यक्तिगत स्वतन्त्रताको बारेमा उल्लेख छ।\n- धारा १ मा चर्चको स्वायत्तता सम्बन्धी विषय रहेको छ।', 'nepali'),
      (v_set_id, 9, E'लिच्छविकालिन समयमा प्रचलित मुद्रा पण र पुराण कसले प्रचलनमा ल्याएका थिए?', E'गुणकामदेव', E'मानदेव', E'नरेन्द्रदेव', E'जय प्रकाश मल्ल', 'C', E'**लिच्छविकालिन मुद्रा पण र पुराण नरेन्द्रदेवले प्रचलनमा ल्याएका थिए।**\n- गुणकामदेवले गुणांक नामक मुद्रा प्रचलनमा ल्याए।\n- मानदेवले मानाङ्क नामक मुद्रा प्रचलनमा ल्याएका थिए।\n- जय प्रकाश मल्लले जावा नामक मुद्रा प्रचलनमा ल्याएका थिए।\nनोट: ''श्री मानांक'' र ''श्री भोगिनी'' अङ्कित मानाङ्क नेपालको प्रथम मुद्रा मानिन्छ।', 'nepali'),
      (v_set_id, 10, E'नेपालमा हालसम्म कति जना उपराष्ट्रपति भइसकेका छन्?', E'२ जना', E'३ जना', E'४ जना', E'५ जना', 'B', E'नेपालमा हालसम्म **३ जना** उपराष्ट्रपति भइसकेका छन्। उनीहरुको नामावली र कार्यकाल यसप्रकार छ:\n- १. परमानन्द झा (२०६५ साउन ८ देखि २०७२ कार्तिक १४)\n- २. नन्द बहादुर पुन (२०७२ कार्तिक १५ देखि २०७९ चैत ३)\n- ३. रामसहाय यादव (२०७९ चैत ३ देखि हाल सम्म)', 'nepali'),
      (v_set_id, 11, E'आङ्का लिपि कुन भाषाको लिपि हो?', E'लेप्चा', E'मगर', E'उर्दु', E'तामाङ', 'B', E'**आङ्का लिपि मगर भाषाको लिपि हो।**\n- लेप्चा भाषाको लिपिलाई रोङ भनिन्छ।\n- उर्दु भाषाको लिपिलाई अरबी भनिन्छ।\n- तामाङ भाषाको लिपिलाई तमुहिग भनिन्छ।', 'nepali'),
      (v_set_id, 12, E'लेन्सको शक्ति कुन एकाइमा नापिन्छ?', E'डायप्टर', E'माइक्रोमिटर', E'क्युरी', E'हर्ज', 'A', E'**लेन्सको शक्ति डायप्टर एकाइमा नापिन्छ।**\n- माइक्रोमिटरले ज्यादै छोटो दुरी नाप्छ।\n- क्युरी रेडियो एक्टिभिटिजको एकाइ हो।\n- हर्ज (Hz) आवृत्तिको एकाइ हो।', 'nepali'),
      (v_set_id, 13, E'अम्लीय वर्षा (Acid Rain) गराउने प्रमुख ग्याँसहरू कुन हो?', E'CO₂', E'CH₄', E'NO₂', E'N₂O', 'C', E'अम्लीय वर्षा गराउने प्रमुख ग्याँसहरूमा **नाइट्रोजन डाइअक्साइड (NO₂) र सल्फर डाइअक्साइड (SO₂) पर्दछन्।**\nनोट: सर्वप्रथम अम्लीय वर्षा भएको भनी पत्ता लगाउने वैज्ञानिक रबर्ट राङगस स्मिथ हुन्।', 'nepali'),
      (v_set_id, 14, E'साक्षरतादर बढि भएको सार्क मुलुक कुन हो?', E'भारत', E'माल्दिभ्स', E'नेपाल', E'श्रीलंका', 'B', E'सार्क मुलुकहरू मध्ये सबैभन्दा बढी साक्षरतादर भएको मुलुक **माल्दिभ्स** हो।\nनोट: माल्दिभ्सको औसत आयु, प्रतिव्यक्ति आय र जनघनत्व पनि सार्क राष्ट्रहरूमा सबैभन्दा बढी रहेको छ।', 'nepali'),
      (v_set_id, 15, E'विज्ञान क्षेत्रसँग सम्बन्धीत चन्द्रमाको अध्ययन गर्ने विज्ञान देहाएका मध्ये कुन हो?', E'ओरोलोजि', E'पारानालोजी', E'सिस्मोलोजि', E'सेलीनोग्राफी', 'D', E'**चन्द्रमाको अध्ययन गर्ने विज्ञानलाई सेलीनोग्राफी भनिन्छ।**\n- ओरोलोजि पर्वत सम्बन्धी अध्ययन गर्ने विज्ञान हो।\n- पारानालोजीले मनोवैज्ञानिक घटनाहरूको अध्ययन गर्दछ जुन सामान्य मनोविज्ञानले व्याख्या गर्न सक्दैन।\n- सिस्मोलोजि भूकम्प सम्बन्धी अध्ययन गर्ने शास्त्र हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/३०', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_01_31.csv  →  आसमान दैनिक GK — २०८३/०१/३१  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०१/३१'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०१/३१';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०१/३१', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'मानिस र सिंहको मिश्रण भगवान विष्णुको अवतारको रुपमा कुन युगमा रहेको थियो ?', E'सत्ययुग', E'त्रैतायुग', E'द्वापरयुग', E'कलियुग', 'A', E'भगवान विष्णुको नरसिंह अवतार, जो आधा मानिस र आधा सिंहको स्वरूप हो, **सत्ययुगमा** प्रकट भएको थियो।\n- त्रैतायुगमा भगवान विष्णुले वामन, परशुराम र राम अवतार लिनुभएको थियो।\n- द्वापरयुगमा कृष्ण र बलराम अवतारको वर्णन पाइन्छ।\n- कलियुगमा कल्की अवतार हुने विश्वास गरिन्छ।', 'nepali'),
      (v_set_id, 2, E'क्षेत्रफलका आधारमा नेपालको सबैभन्दा ठूलो नगरपालिका कुन हो?', E'भक्तपुर', E'बुढानिलकण्ठ', E'ठुलिभेरी', E'शितगंगा', 'D', E'क्षेत्रफलका आधारमा नेपालको सबैभन्दा ठूलो नगरपालिका अर्घाखाँची जिल्लामा अवस्थित **शितगंगा** हो।\n- भक्तपुर नेपालको सबैभन्दा सानो नगरपालिका हो।\n- बुढानिलकण्ठ काठमाडौंको सबैभन्दा धेरै जनसंख्या भएको नगरपालिका हो।\n- ठुलिभेरी (डोल्पा) सबैभन्दा कम जनसंख्या भएको नगरपालिका हो।', 'nepali'),
      (v_set_id, 3, E'सिन्धुली पछि सबैभन्दा धेरै जिल्लासँग जिल्ला सिमाना जोडिएको जिल्ला कुन हो?', E'काभ्रेपलाञ्चोक', E'मकवानपुर', E'ललितपुर', E'रामेछाप', 'B', E'नेपालमा सबैभन्दा धेरै जिल्लासँग सिमाना जोडिएको जिल्ला सिन्धुली हो, जसले १० वटा जिल्लालाई छुन्छ। त्यसपछि **मकवानपुर** जिल्लाले ९ वटा जिल्लासँग सिमाना जोडेको छ।\nनोट: सबैभन्दा कम (२/२ वटा) जिल्लासँग सिमाना जोडिएका जिल्लाहरू झापा, दार्चुला र कञ्चनपुर हुन्।', 'nepali'),
      (v_set_id, 4, E'सिउँडीको रुखलाई देवता मानी पुजा गर्ने प्रचलन कुन जाति विशेषसँग सम्बन्धित छ ?', E'मेचे', E'चेपाङ', E'मार्फि', E'दुरा', 'A', E'**मेचे** जातिमा सिउँडीको रुखलाई कुलदेवताको रूपमा पूजा गर्ने प्रचलन रहेको छ।\n- चेपाङ जातिमा दाइजोको रूपमा छोरीलाई चिउरीको बोट दिने चलन प्रचलित छ।\n- मार्फि (मार्फाली) थकाली समुदायको एक उपसमूह हो, जो मुस्ताङमा बसोबास गर्छन्।\n- दुरा जाति लमजुङ जिल्लामा बसोबास गर्ने एक आदिवासी जनजाति हो।', 'nepali'),
      (v_set_id, 5, E'सबैभन्दा धेरै वडा रहेको नेपालको भूगोलको महानगरपालिका कुन हो?', E'भरतपुर', E'काठमाडौं', E'विराटनगर', E'पोखरा', 'D', E'नेपालका महानगरपालिकाहरूमध्ये सबैभन्दा धेरै वडा **पोखरा महानगरपालिकामा (३३ वटा)** रहेका छन्।\n- काठमाडौं महानगरपालिकामा ३२ वटा वडाहरू छन्।\n- भरतपुर महानगरपालिकामा २९ वटा वडाहरू छन्।\n- विराटनगर महानगरपालिकामा १९ वटा वडाहरू छन्।', 'nepali'),
      (v_set_id, 6, E'आठ हजार मिटर भन्दा अग्ला आठवटा हिमाल मध्ये गण्डकी प्रदेशमा अवस्थित हिमालको संख्या कति रहेको छ?', E'५ वटा', E'४ वटा', E'३ वटा', E'२ वटा', 'C', E'नेपालका आठ हजार मिटरभन्दा अग्ला आठवटा हिमालहरूमध्ये **३ वटा** गण्डकी प्रदेशमा अवस्थित छन्। ती हिमालहरू धवलागिरि, मनास्लु र अन्नपूर्ण हुन्। बाँकी पाँचवटा (सगरमाथा, कन्चनजङ्घा, ल्होत्से, मकालु, चोओयु) कोशी प्रदेशमा पर्दछन्।\nनोट: विश्वमा ८,००० मिटरभन्दा अग्ला जम्मा १४ वटा हिमाल रहेका छन्।', 'nepali'),
      (v_set_id, 7, E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा कति नयाँ जातजाति थपिएका छन ?', E'१७ वटा', E'१५ वटा', E'१३ वटा', E'११ वटा', 'A', E'राष्ट्रिय जनगणना, २०७८ अनुसार नेपालमा **१७ वटा** नयाँ जातजाति थपिएका छन्। यससँगै नेपालमा जातजातिको कुल संख्या २०६८ को जनगणनाको १२५ बाट बढेर १४२ पुगेको छ।', 'nepali'),
      (v_set_id, 8, E'नेपालले ICC टी-२० विश्वकपमा १२ वर्ष पछि कुन देश विरुद्ध ऐतिहासिक विजय प्राप्त गरेको हो ?', E'इटाली', E'वेस्ट इण्डिज', E'स्कटल्यान्ड', E'इंग्ल्याण्ड', 'C', E'नेपालले ICC टी-२० विश्वकपमा १२ वर्षपछि **स्कटल्यान्ड** विरुद्ध ऐतिहासिक विजय प्राप्त गरेको हो। सन् २०२४ को विश्वकपमा नेपालले स्कटल्यान्डलाई ७ विकेटले पराजित गरेको थियो। यो नेपालको टी-२० विश्वकपमा तेस्रो जित थियो।\nनोट: यसअघि सन् २०१४ को विश्वकपमा नेपालले अफगानिस्तान र हङकङलाई पराजित गरेको थियो।', 'nepali'),
      (v_set_id, 9, E'संयुक्त राष्ट्रसंघको महासचिवले भाग लिन नपाउने अंग कुन हो ?', E'आर्थिक परिषद्', E'सचिवालय', E'महासभा', E'न्यायालय', 'D', E'संयुक्त राष्ट्रसंघको महासचिवले **अन्तर्राष्ट्रिय न्यायालयको** कामकारबाहीमा भाग लिन पाउँदैनन्।\n- सचिवालयको प्रमुख प्रशासकीय अधिकृत महासचिव नै हुन्छन्।\n- महासभा र आर्थिक तथा सामाजिक परिषद्को बैठकमा महासचिवले भाग लिन्छन् र प्रतिवेदन पेश गर्दछन्।\nनोट: अन्तर्राष्ट्रिय न्यायालय संयुक्त राष्ट्रसंघको प्रमुख न्यायिक अंग हो, जसको प्रधान कार्यालय नेदरल्याण्डको हेगमा रहेको छ।', 'nepali'),
      (v_set_id, 10, E'राष्ट्रिय जनगणना, २०७८ अनुसार मनाङ र मुस्ताङ पछि सबैभन्दा कम जनघनत्व भएको जिल्ला कुन हो ?', E'मुगु', E'डोल्पा', E'हुम्ला', E'जुम्ला', 'B', E'राष्ट्रिय जनगणना, २०७८ अनुसार मनाङ र मुस्ताङ पछि सबैभन्दा कम जनघनत्व भएको जिल्ला **डोल्पा** हो। सबैभन्दा कम जनघनत्व भएका ५ जिल्लाहरूको क्रम यसप्रकार छ:\n- १. मनाङ: ३ व्यक्ति प्रति वर्ग कि.मि.\n- २. मुस्ताङ: ४ व्यक्ति प्रति वर्ग कि.मि.\n- ३. डोल्पा: ५ व्यक्ति प्रति वर्ग कि.मि.\n- ४. हुम्ला: १० व्यक्ति प्रति वर्ग कि.मि.\n- ५. मुगु: १८ व्यक्ति प्रति वर्ग कि.मि.', 'nepali'),
      (v_set_id, 11, E'आर्थिक विकास र उत्पादन मुलक रोजगारी दिगो विकासको कुन लक्ष्य सँग सम्बन्धित छ ?', E'लक्ष्य: ६', E'लक्ष्य: ७', E'लक्ष्य: ८', E'लक्ष्य: ९', 'C', E'**समावेशी र दिगो आर्थिक वृद्धि तथा उत्पादनमुलक रोजगार प्रवर्द्धन दिगो विकासको लक्ष्य ८ सँग सम्बन्धित छ।**\n- लक्ष्य ६ मा सबैका लागि सुरक्षित खानेपानी र सरसफाईको व्यवस्था रहेको छ।\n- लक्ष्य ७ सबैले खर्च धान्न सक्ने, भरपर्दो र दिगो आधुनिक ऊर्जासँग सम्बन्धित छ।\n- लक्ष्य ९ पूर्वाधार निर्माण, उद्योग र नवीन खोजसँग सम्बन्धित छ।', 'nepali'),
      (v_set_id, 12, E'जनआन्दोलन ६२/६३ नेपालमा कति दिन चलेको थियो ?', E'२१ दिन', E'१९ दिन', E'२३ दिन', E'२४ दिन', 'B', E'राजा ज्ञानेन्द्रको प्रतिगमनको कदम विरुद्ध भएको जनआन्दोलन-II (२०६२/६३) जम्मा **१९ दिन** चलेको थियो। यो आन्दोलन वि.सं. २०६२ चैत्र २४ गतेदेखि २०६३ वैशाख ११ गतेसम्म चलेको थियो, जसलाई १९ दिने जनआन्दोलन पनि भनिन्छ।\nनोट: यही आन्दोलनको फलस्वरूप नेपालमा लोकतन्त्रको पुनर्स्थापना भई २०६३ माघ १ गते अन्तरिम संविधान जारी भएको थियो।', 'nepali'),
      (v_set_id, 13, E'संयुक्त राष्ट्रसंघ (UNO) का अनुसार कति डेसिबल सम्मको सामान्य ध्वनी हो ?', E'६५ डेसिबल', E'७५ डेसिबल', E'८५ डेसिबल', E'९५ डेसिबल', 'A', E'संयुक्त राष्ट्रसंघ (UNO) का अनुसार **६५ डेसिबल** सम्मको ध्वनीलाई सामान्य मानिन्छ।\nनोट: UNO ले ७५ डेसिबलभन्दा बढीको ध्वनीलाई खराब र ८५ डेसिबलभन्दा माथिको ध्वनीलाई हानिकारक ध्वनीको सूचीमा राखेको छ।', 'nepali'),
      (v_set_id, 14, E'भगवान गौतम बुद्धले दिएका उपदेश कुन पिटकमा समावेश गरिएका छन ?', E'उपदेश पिटक', E'विनय पिटक', E'अभिधम्म पिटक', E'शुक्ति पिटक', 'D', E'**भगवान गौतम बुद्धले दिएका उपदेशहरू शुक्ति पिटकमा समावेश गरिएका छन्।**\n- विनय पिटकमा बौद्ध भिक्षु एवं भिक्षुणीहरूले पालना गर्नुपर्ने नियमहरू समावेश छन्।\n- अभिधम्म पिटकमा बौद्ध दर्शनका विषयहरू समावेश गरिएका छन्।\n- उपदेश पिटक त्रिपिटकको अंग होइन, यो एक भ्रामक विकल्प हो।\nनोट: शुक्ति पिटक, विनय पिटक र अभिधम्म पिटकको संग्रहलाई त्रिपिटक भनिन्छ, जुन बौद्ध धर्मको प्रमुख ग्रन्थ हो।', 'nepali'),
      (v_set_id, 15, E'आगामी कोप ३१ सन् २०२६ मा कुन स्थानमा आयोजना हुने भएको छ ?', E'बाकु', E'बेलेम', E'अस्ट्रेलिया', E'अन्टाल्या', 'D', E'**कोप ३१ सम्मेलन सन् २०२६ मा टर्कीएको अन्टाल्यामा आयोजना भएको थियो।**\n- बाकु, अजरबैजानमा कोप २९ (सन् २०२४) आयोजना भएको थियो।\n- बेलेम, ब्राजिलमा कोप ३० (सन् २०२५) सम्पन्न भएको थियो।\n- अस्ट्रेलियाले हालसम्म कोप सम्मेलन आयोजना गरेको छैन।\nनोट: पहिलो कोप सम्मेलन सन् १९९५ मा जर्मनीको बर्लिनमा भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०१/३१', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_02_04.csv  →  आसमान दैनिक GK — २०८३/०२/०४  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०२/०४'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०२/०४';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०२/०४', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आर्थिक तथा सामाजिक परिषदको सदस्यको कार्यकाल कति वर्षको रहेको हुन्छ ?', E'१ वर्ष', E'३ वर्ष', E'५ वर्ष', E'९ वर्ष', 'B', E'संयुक्त राष्ट्र संघको आर्थिक तथा सामाजिक परिषदको सदस्यको कार्यकाल **३ वर्षको** हुन्छ।\n- महासभाको अध्यक्षको कार्यकाल १ वर्षको हुन्छ।\n- महासचिवको कार्यकाल ५ वर्षको हुन्छ।\n- अन्तर्राष्ट्रिय न्यायालयका न्यायाधीशको पदावधि ९ वर्षको हुन्छ।\nनोट: आर्थिक तथा सामाजिक परिषदमा ५४ सदस्य राष्ट्रहरू रहन्छन्।', 'nepali'),
      (v_set_id, 2, E'हालसम्म नेपालमा कति वटा राष्ट्रिय जनगणना सम्पन्न भइसकेको छ ?', E'१३ वटा', E'११ वटा', E'१० वटा', E'१२ वटा', 'D', E'हालसम्म नेपालमा **१२ वटा** राष्ट्रिय जनगणना सम्पन्न भइसकेको छ। नेपालमा जनगणनाको सुरुवात वि.सं. १९६८ (सन् १९११) बाट भएको हो र यो हरेक १०/१० वर्षमा गरिन्छ।\nनोट: १२ औं राष्ट्रिय जनगणना, २०७८ को नारा ''मेरो गणना, मेरो सहभागिता'' रहेको थियो।', 'nepali'),
      (v_set_id, 3, E'उत्परिवर्तनका पिता (Father of mutation) को रुपमा कुन वैज्ञानिकलाई चिनिन्छ ?', E'चार्ल्स डार्विन', E'ह्युगो डिभ्रिज', E'जोन ग्रेगर मेण्डल', E'जीन-ब्याप्टिस्ट लेमार्क', 'B', E'उत्परिवर्तनका पिता (Father of mutation) को रुपमा **ह्युगो डिभ्रिज**लाई चिनिन्छ।\n- चार्ल्स डार्विनलाई क्रमविकासको सिद्धान्त (Theory of Evolution) का पिता मानिन्छ।\n- जोन ग्रेगर मेण्डललाई आनुवंशिकी (Genetics) का पिता भनिन्छ।\n- जीन-ब्याप्टिस्ट लेमार्कले उपार्जित गुणहरूको वंशाणुगत सिद्धान्त (Theory of Inheritance of Acquired Characteristics) प्रतिपादन गरेका थिए।', 'nepali'),
      (v_set_id, 4, E'राजर्षी महाराजको उपनामले कुन राणा प्रधानमन्त्रीलाई चिनिन्छ ?', E'जुद्ध सम्सेर', E'चन्द्र सम्सेर', E'पद्म सम्सेर', E'भीम सम्सेर', 'A', E'**जुद्ध शमशेरलाई राजर्षी महाराजको उपनामले चिनिन्छ।**\n- चन्द्र शमशेरलाई ''फिस्टे महाराज'' उपनामले चिनिन्थ्यो।\n- पद्म शमशेरलाई ''रुन्चे महाराज'' भनेर चिनिन्थ्यो।\n- भीम शमशेरलाई ''बुढा महाराज'' उपनामले चिनिन्थ्यो।', 'nepali'),
      (v_set_id, 5, E'नेपालको इतिहासमा सबैभन्दा कम उमेरमा राजा हुने को थिए ?', E'दिपेन्द्र वीरविक्रम शाह', E'रण बहादुर शाह', E'ज्ञानेन्द्र वीरविक्रम शाह', E'गिर्वाणयुद्ध विक्रम शाह', 'D', E'**नेपालको इतिहासमा सबैभन्दा कम उमेरमा राजा हुने व्यक्ति गिर्वाणयुद्ध विक्रम शाह हुन्, जो १.५ वर्षको उमेरमा राजा भएका थिए।**\n- दिपेन्द्र वीरविक्रम शाह नेपालका सबैभन्दा कम अवधिका राजा (तीन दिन) थिए।\n- रण बहादुर शाह २.५ वर्षको उमेरमा राजा भएका थिए।\n- ज्ञानेन्द्र वीरविक्रम शाह शाहवंशीय इतिहासमा सबैभन्दा बढी उमेरमा र दुई पटक राजा हुने व्यक्ति हुन्।', 'nepali'),
      (v_set_id, 6, E'सबैभन्दा सानो प्रदेश मधेश प्रदेशले कुल नेपाली क्षेत्रफलको कति प्रतिशत भूभाग ओगटेको छ ?', E'६.२८ प्रतिशत', E'६.७९ प्रतिशत', E'६.५७ प्रतिशत', E'६.६० प्रतिशत', 'C', E'नेपालको सबैभन्दा सानो प्रदेश, मधेश प्रदेशले देशको कुल क्षेत्रफलको **६.५७ प्रतिशत** भूभाग ओगटेको छ।\nनोट: मधेश प्रदेशको कुल क्षेत्रफल ९,६६१ वर्ग किलोमिटर रहेको छ।', 'nepali'),
      (v_set_id, 7, E'प्रथम विश्वयुद्धपछि जर्मनीमा उदाएको शासन व्यवस्था के रहेको थियो ?', E'साम्यवाद', E'फाँसिवाद', E'नाजीवाद', E'समाजवाद', 'C', E'**प्रथम विश्वयुद्धपछि जर्मनीमा हिटलरको नेतृत्वमा नाजीवाद शासन व्यवस्था उदाएको थियो।**\n- फाँसिवाद इटालीमा बेनिटो मुसोलिनीको नेतृत्वमा विकास भएको शासन प्रणाली हो। नाजीवादलाई फाँसिवादको जर्मन रूप मानिन्छ।\n- साम्यवाद कार्ल मार्क्स र फ्रेडरिक एंगेल्सद्वारा प्रतिपादित एक राजनीतिक तथा आर्थिक सिद्धान्त हो।\n- समाजवाद एक राजनीतिक, सामाजिक र आर्थिक दर्शन हो जसले उत्पादनका साधनहरूमा सामाजिक स्वामित्वको वकालत गर्दछ।', 'nepali'),
      (v_set_id, 8, E'नेपालको संविधान अनुसार राज्यका निर्देशक सिद्धान्त कतिवटा रहेको छन् ?', E'७ वटा', E'४ वटा', E'१३ वटा', E'१८ वटा', 'B', E'नेपालको संविधानको भाग-४, धारा ५० मा राज्यका निर्देशक सिद्धान्तहरू सम्बन्धी व्यवस्था गरिएको छ, जसअनुसार यस्ता सिद्धान्तहरू **४ वटा** रहेका छन्।\nनोट: संविधानको धारा ५१ मा राज्यका नीतिहरू १३ वटा उल्लेख गरिएका छन्।', 'nepali'),
      (v_set_id, 9, E'संयुक्त राष्ट्रसंघमा उपमहासचिव राख्ने व्यवस्था कुन महासचिवको पालादेखि सुरु भएको थियो ?', E'कोफी अन्नान', E'ट्रिग्बे ली', E'वान कि मुन', E'एन्टोनियो गुट्रेस', 'A', E'संयुक्त राष्ट्रसंघमा उपमहासचिव पदको व्यवस्था महासचिव **कोफी अन्नानको** पालादेखि सुरु भएको हो।\nनोट: संयुक्त राष्ट्रसंघको पहिलो उपमहासचिव क्यानडाकी लुइस फ्रेचेट थिइन्, जसले २ मार्च १९९८ मा पदभार ग्रहण गरेकी थिइन्।', 'nepali'),
      (v_set_id, 10, E'जिम्माजमानी परिषद् कहिले देखि निष्कृय अवस्थामा रहेको छ ?', E'सन् १९९४', E'सन् १९९५', E'सन् १९९६', E'सन् १९९३', 'A', E'संयुक्त राष्ट्र संघको जिम्माजमानी परिषद् **सन् १९९४** देखि निष्कृय अवस्थामा रहेको छ। सन् १९४५ मा गठन भएको यो परिषद्को अन्तिम अधीनस्त क्षेत्र पलाउले स्वतन्त्रता पाएपछि यो निष्कृय भएको हो।\nनोट: यो परिषद्लाई संयुक्त राष्ट्र संघको सबैभन्दा सफल अंग मानिन्छ।', 'nepali'),
      (v_set_id, 11, E'सार्क मुलुकहरू मध्ये नेपाल क्षेत्रफलका आधारमा कति औं ठूलो मुलुक हो ?', E'छैटौं', E'चौथो', E'पाँचौं', E'तेस्रो', 'C', E'क्षेत्रफलका आधारमा सार्क मुलुकहरू मध्ये नेपाल **पाँचौं** ठूलो मुलुक हो।\nनोट: सार्क मुलुकहरूको क्षेत्रफलको क्रम यसप्रकार छ: भारत, पाकिस्तान, अफगानिस्तान, बंगलादेश, नेपाल, श्रीलंका, भुटान र माल्दिभ्स।', 'nepali'),
      (v_set_id, 12, E'नेपालमा अवस्थित संरक्षण क्षेत्र मध्ये सबैभन्दा सानो संरक्षण क्षेत्र कुन हो ?', E'अन्नपूर्ण', E'रारा', E'अपि नाम्पा', E'कृष्णसार', 'D', E'नेपालको सबैभन्दा सानो संरक्षण क्षेत्र **कृष्णसार संरक्षण क्षेत्र** हो, जसको क्षेत्रफल १६.९५ वर्ग कि.मि. छ।\n- अन्नपूर्ण संरक्षण क्षेत्र नेपालको सबैभन्दा ठूलो संरक्षण क्षेत्र हो।\n- रारा एक राष्ट्रिय निकुञ्ज हो, संरक्षण क्षेत्र होइन।\n- अपि नाम्पा संरक्षण क्षेत्र दार्चुला जिल्लामा पर्दछ।\nनोट: कृष्णसार संरक्षण क्षेत्र बर्दिया जिल्लामा अवस्थित छ र यसको स्थापना वि.सं. २०६५ मा भएको हो।', 'nepali'),
      (v_set_id, 13, E'महाभारतयुद्ध कालका नेपालका राजाको उपनामले कुन राजालाई चिनिन्छ?', E'स्थुंको', E'पटुको', E'जितेदास्ती', E'हुमती', 'D', E'**हुमती**लाई महाभारतयुद्ध कालका नेपालका राजाको उपनामले चिनिन्छ।\n- स्थुंको (स्थुङ्को) गोपाल वंशलाई पराजित गरी शासन सत्तामा आउने प्रथम किराँती राजा हुन्।\n- पटुको तेस्रो किराँती राजा थिए।\n- जितेदास्ती सातौँ किराँती राजा थिए, जो महाभारतको युद्धमा पाण्डवको पक्षबाट लडेको मानिन्छ।', 'nepali'),
      (v_set_id, 14, E'सोह्रौं योजनाको अन्त्य सम्म नेपालको गरिबीको रेखामुनी रहेको जनसंख्या (निरपेक्ष गरिबी) कति पुर्याउने लक्ष्य रहेको छ ?', E'१२ प्रतिशत', E'११ प्रतिशत', E'० प्रतिशत', E'५ प्रतिशत', 'A', E'सोह्रौं योजना (आ.व. २०८१/८२ - २०८४/८५) को अन्त्यसम्ममा नेपालको निरपेक्ष गरिबीको रेखामुनी रहेको जनसंख्यालाई **१२ प्रतिशतमा** झार्ने लक्ष्य राखिएको छ।\nनोट: हाल नेपालमा निरपेक्ष गरिबी २०.३ प्रतिशत रहेको छ भने आ.व. २१००/०१ सम्ममा यसलाई शून्यमा झार्ने दीर्घकालीन सोच छ।', 'nepali'),
      (v_set_id, 15, E'दिगो विकास लक्ष्यहरू क्रमशः नं. ४ र ५ को सम्बन्धमा कुन विकल्प सही छ ?', E'गुणस्तरीय शिक्षा र लैंगिक समानता', E'गुणस्तरीय शिक्षा र शुन्य भोकमरी', E'लैंगिक समानता र जलवायु सम्बन्धी कार्य', E'शुन्य भोकमरी र जलवायु सम्बन्धी कार्य', 'A', E'दिगो विकास लक्ष्य नम्बर ४ **गुणस्तरीय शिक्षा (Quality Education)** र लक्ष्य नम्बर ५ लैंगिक समानता (Gender Equality) हो।\n- शुन्य भोकमरी दिगो विकास लक्ष्य नम्बर २ हो।\n- जलवायु सम्बन्धी कार्य दिगो विकास लक्ष्य नम्बर १३ हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०२/०४', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_02_05.csv  →  आसमान दैनिक GK — २०८३/०२/०५  (30 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०२/०५'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०२/०५';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०२/०५', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'शासन व्यवस्थामा एनेट प्रथाको अन्त्य कुन प्रधानमन्त्रीको पालादेखि भएको थियो ?', E'जंग ब राणा', E'भिमसेन थापा', E'मोहन सम्सेर', E'वि पि कोइराला', 'C', E'**मोहन सम्सेरको पालामा एनेट प्रथाको अन्त्य भएको थियो।**\n- जंग ब राणाले शासन सत्ता भाइमा जाने (छोरामा नजाने) ''एनेट प्रथा'' को थालनी गरेका थिए।\n- भिमसेन थापा नेपालका प्रथम मुख्तियार (प्रधानमन्त्री) थिए।\n- वि पि कोइराला राणा शासनको अन्त्यपछि बनेका प्रथम जननिर्वाचित प्रधानमन्त्री हुन्।\nनोट: मोहन सम्सेर राणा शासनका अन्तिम प्रधानमन्त्री थिए।', 'nepali'),
      (v_set_id, 2, E'प्रतिनिधि सभा निर्वाचन, २०७९ मा प्रत्यक्षतर्फ निर्वाचित महिला सांसदको संख्या कति रहेको छ ?', E'१४ जना', E'१५ जना', E'१६ जना', E'१७ जना', 'A', E'प्रतिनिधि सभा निर्वाचन, २०७९ मा प्रत्यक्षतर्फ निर्वाचित महिला सांसदको संख्या **१४ जना** रहेको छ।\nनोट: यी मध्ये राष्ट्रिय स्वतन्त्र पार्टी (रास्वपा) बाट १३ जना र नेपाली कांग्रेसबाट १ जना निर्वाचित भएका थिए।', 'nepali'),
      (v_set_id, 3, E'देहायका मध्ये कुन झरना डोटी जिल्लामा अवस्थित रहेको छ ?', E'जोरपानी झरना', E'रुप्से झरना', E'वैकुण्ठे झरना', E'सुलिगढ झरना', 'A', E'**जोरपानी झरना डोटी जिल्लामा अवस्थित छ।**\n- रुप्से झरना म्याग्दी जिल्लामा पर्दछ।\n- वैकुण्ठे झरना पाल्पा जिल्लामा अवस्थित छ।\n- सुलिगढ झरना डोल्पा जिल्लामा रहेको छ।', 'nepali'),
      (v_set_id, 4, E'नेपाललाई ७७ जिल्लामा विभाजन गर्दा नेपालका तत्कालिन प्रधानमन्त्री को थिए ?', E'शेर ब देउवा', E'पुष्प क. दाहाल (प्रचण्ड)', E'केपी शर्मा वलि', E'सुशील कोइराला', 'A', E'**नेपाललाई ७७ जिल्लामा विभाजन गर्दा तत्कालिन प्रधानमन्त्री शेरबहादुर देउवा थिए।**\n- पुष्पकमल दाहाल (प्रचण्ड) र केपी शर्मा ओली पनि नेपालका पूर्व प्रधानमन्त्रीहरू हुन्।\n- सुशील कोइरालाको पालामा वि.सं. २०७२ असोज ३ गते नेपाललाई ७ प्रदेशमा विभाजन गरिएको थियो।\nनोट: वि.सं. २०७४ भदौ ५ गतेको मन्त्रिपरिषद् बैठकले नवलपरासी र रुकुमलाई २/२ जिल्लामा विभाजन गरी ७७ जिल्ला कायम गर्ने निर्णय गरेको थियो।', 'nepali'),
      (v_set_id, 5, E'भौगोलिक विभाजन अन्तर्गत पहाडी प्रदेशको अवस्थिति देहायका मध्ये कुन विकल्प सहि छ पहिचान गर्नुहोस् ?', E'५०० देखि ३००० मि.', E'५०० देखि ३५०० मि.', E'६०० देखि ३५०० मि.', E'६०० देखि ३००० मि.', 'D', E'भौगोलिक विभाजन अनुसार पहाडी प्रदेश **६०० देखि ३००० मिटर**को उचाइमा अवस्थित छ।\n- हिमाली प्रदेश ३००० देखि ८८४८.८६ मिटर र तराई प्रदेश ५९ देखि ६०० मिटरको उचाइमा पर्दछन्।', 'nepali'),
      (v_set_id, 6, E'चन्द्रमा पहिलो मानव कदम देहायका मध्ये कुन मितिमा परेको थियो ?', E'1961 april 12', E'1969 july 20', E'1963 june 16', E'1965 april 12', 'B', E'चन्द्रमामा पहिलो मानव कदम **सन् १९६९ जुलाई २०** मा परेको थियो, जब नील आर्मस्ट्रङले एपोलो ११ यानबाट चन्द्रमाको सतहमा पाइला टेकेका थिए।\n- सन् १९६१ अप्रिल १२ मा सोभियत संघका युरी गागरिन भोस्तोक १ यानबाट अन्तरिक्षमा पुग्ने पहिलो व्यक्ति बनेका थिए।', 'nepali'),
      (v_set_id, 7, E'स्थायी मानव बसोबास जनसंख्याको आधारमा सबैभन्दा कम जनसंख्या भएको महादेश कुन हो ?', E'दक्षिण अमेरिका', E'उत्तर अमेरिका', E'अस्ट्रेलिया', E'युरोप', 'C', E'स्थायी मानव बसोबासको आधारमा सबैभन्दा कम जनसंख्या भएको महादेश **अस्ट्रेलिया** हो।\n- दक्षिण अमेरिका जनसंख्याको आधारमा दोस्रो कम जनसंख्या भएको महादेश हो।\n- उत्तर अमेरिका जनसंख्याको आधारमा चौथो स्थानमा पर्छ।\n- युरोप क्षेत्रफलको आधारमा दोस्रो सानो महादेश हो।\nनोट: अन्टार्कटिकामा स्थायी मानव बसोबास नभएकाले यसलाई सामान्यतया यस सूचीमा समावेश गरिँदैन।', 'nepali'),
      (v_set_id, 8, E'घोडाभेडा प्रथा नेपालको कुन जिल्लामा प्रचलित रहेको छ ?', E'बैतडी', E'डोल्पा', E'मुगु', E'अछाम', 'C', E'घोडाभेडा प्रथा **मुगु** जिल्लामा प्रचलित रहेको छ।\n- बैतडी जिल्ला देउकी प्रथासँग सम्बन्धित छ।\n- डोल्पा जिल्लामा खुल्ला प्रथा प्रचलित छ।\n- अछाम जिल्ला छाउपडी प्रथाको लागि चिनिन्छ।\nनोट: घोडाभेडा प्रथामा स्थानीय भलादमीहरूले विवाद मिलाएपछि मध्यस्थकर्तालाई भेडा काटेर खुवाउने र घोडामा चढाएर पठाउने चलन छ।', 'nepali'),
      (v_set_id, 9, E'विज्ञानसँग सम्बन्धित प्रमुख वेद कुन हो ?', E'ऋग्वेद', E'सामवेद', E'यजुर्वेद', E'अथर्ववेद', 'D', E'विज्ञानसँग सम्बन्धित प्रमुख वेद **अथर्ववेद** हो, जुन सबैभन्दा नयाँ वेद पनि मानिन्छ।\n- ऋग्वेद ज्ञानसँग सम्बन्धित सबैभन्दा पुरानो वेद हो।\n- सामवेद उपासना र संगीतसँग सम्बन्धित छ।\n- यजुर्वेद कर्मकाण्डसँग सम्बन्धित रहेको छ।', 'nepali'),
      (v_set_id, 10, E'देहायका मध्ये कुन नाच गुरुङ समुदायमा प्रचलित रहेको छ ?', E'घाटु नाच', E'साकेला नाच', E'सेलो नाच', E'तरवार नाच', 'A', E'**घाटु नाच** गुरुङ समुदायमा प्रचलित एक प्रमुख नाच हो।\n- साकेला नाच किराँत (राई) समुदायमा प्रचलित छ।\n- सेलो नाच तामाङ समुदायमा प्रचलित छ।\n- तरवार नाच थारु समुदायमा प्रचलित रहेको छ।', 'nepali'),
      (v_set_id, 11, E'कृषि तथा भूमि सुधार सँग सम्बन्धि नीति नेपालको संविधानको कुन धारमा उल्लेख गरिएको छ ?', E'५१(क)', E'५१(घ)', E'५१(च)', E'५१(ङ)', 'D', E'कृषि तथा भूमि सुधार सम्बन्धी नीति नेपालको संविधानको **धारा ५१ (ङ)** मा उल्लेख गरिएको छ।\n- धारा ५१(क) मा राष्ट्रिय एकता र राष्ट्रिय सुरक्षा सम्बन्धी नीति छ।\n- धारा ५१(घ) मा अर्थ, उद्योग र वाणिज्य सम्बन्धी नीति उल्लेख छ।\n- धारा ५१(च) मा विकास सम्बन्धी नीति रहेको छ।\nनोट: नेपालको संविधानको भाग-४ मा राज्यका निर्देशक सिद्धान्त, नीति तथा दायित्वहरू अन्तर्गत धारा ५१ मा राज्यका विभिन्न नीतिहरू व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 12, E'विश्व इतिहासमा पुनर्जागरणको सुरुवात कुन मुलुकबाट भएको थियो ?', E'फ्रान्स', E'वेलायत', E'इटाली', E'अमेरिका', 'C', E'विश्व इतिहासमा पुनर्जागरणको सुरुवात **इटालीबाट** भएको थियो।\nनोट: पुनर्जागरणको सुरुवात १४ औं शताब्दीमा इटालीको फ्लोरेन्स सहरबाट भएको मानिन्छ।', 'nepali'),
      (v_set_id, 13, E'नेपाल प्रिमियर लिग (NPL) को ट्रफी कहिले सार्वजनिक गरियो ?', E'२०८१ असार २१', E'२०८१ भदौ ३', E'२०८१ मंसिर १५', E'२०८१ मंसिर १०', 'D', E'नेपाल प्रिमियर लिग (NPL) को ट्रफी **२०८१ मंसिर १०** गते धरहराबाट सार्वजनिक गरिएको हो। यसको घोषणा २०८१ असार २१ मा र लोगो २०८१ भदौ ३ मा सार्वजनिक गरिएको थियो।\nनोट: उक्त ट्रफीमा सगरमाथा क्षेत्रको कालापत्थरबाट ल्याइएको ढुंगा प्रयोग गरिएको छ।', 'nepali'),
      (v_set_id, 14, E'नेपाल सरकारले आफ्नै लगानीमा निर्माण सम्पन्न गरेको पहिलो जलविद्युत आयोजना कुन हो ?', E'खिम्ती', E'सुन्दरीजल', E'फर्पिङ', E'माथिल्लो तामाकोसी', 'B', E'नेपाल सरकारले आफ्नै लगानीमा निर्माण सम्पन्न गरेको पहिलो जलविद्युत आयोजना **सुन्दरीजल** हो। बेलायतको सहयोगमा बनेको नेपालको पहिलो जलविद्युत आयोजना फर्पिङ हो भने निजी क्षेत्रको लगानीमा निर्माण सम्पन्न भएको पहिलो आयोजना खिम्ती हो।', 'nepali'),
      (v_set_id, 15, E'बालबालिकालाई क्षयरोग विरुद्ध दिइने खोपको नाम के हो ?', E'OPV', E'PCV', E'BCG', E'DPT', 'C', E'**बालबालिकालाई क्षयरोग विरुद्ध BCG खोप दिइन्छ।**\n- OPV खोप पोलियो रोग विरुद्ध दिइन्छ।\n- PCV खोप निमोनिया रोग विरुद्ध दिइन्छ।\n- DPT खोप भ्यागुते रोग, लहरे खोकी र धनुष्टंकार विरुद्ध दिइन्छ।', 'nepali'),
      (v_set_id, 16, E'नेपालको इतिहासको पहिलो कृषि मन्त्री को हुन् ?', E'भरतमणि शर्मा', E'यज्ञबहादुर बस्नेत', E'नृपजङ्ग राणा', E'गणेशमान सिंह', 'A', E'नेपालको इतिहासका प्रथम कृषि मन्त्री **भरतमणि शर्मा** हुन्।\n- यज्ञबहादुर बस्नेत पहिलो स्वास्थ्य तथा स्वायत्त शासन मन्त्री थिए।\n- नृपजङ्ग राणा पहिलो शिक्षा मन्त्री थिए।\n- गणेशमान सिंह पहिलो उद्योग तथा वाणिज्य मन्त्री थिए।\nनोट: यो मन्त्रीमण्डल २००७ साल फागुन ७ गते गठन भएको थियो।', 'nepali'),
      (v_set_id, 17, E'बौद्ध धर्ममा पहेलो रंगको अर्थ के हो ?', E'बुद्धको अन्तःकरण', E'बुद्धको शरीर', E'बुद्धको दाँत', E'बुद्धको अस्थिधातु', 'D', E'बौद्ध धर्ममा पहेलो रंगले **बुद्धको अस्थिधातु**लाई जनाउँछ।\n- कलेजी रंगले बुद्धको अन्तःकरणलाई जनाउँछ।\n- निलो रंगले बुद्धको शरीरलाई जनाउँछ।\n- सेतो रंगले बुद्धको दाँतलाई जनाउँछ।\nनोट: बौद्ध धर्ममा रातो रंगले बुद्धको रगतलाई संकेत गर्दछ।', 'nepali'),
      (v_set_id, 18, E'नेपालबाट सबैभन्दा नजिकमा रहेको सार्क राजधानी कुन हो ?', E'ढाका', E'थिम्पु', E'माले', E'नयाँ दिल्ली', 'B', E'नेपालबाट सबैभन्दा नजिकमा रहेको सार्क राजधानी भुटानको **थिम्पु** हो। यो राजधानी नेपालबाट करिब ४०० कि.मि. को हवाई दूरीमा अवस्थित छ।\nनोट: नेपालबाट सबैभन्दा नजिकको देश भने बंगलादेश हो, जुन २७ कि.मि. को दूरीमा छ।', 'nepali'),
      (v_set_id, 19, E'नेपालको सबैभन्दा उच्च स्थानमा रहेको गुम्बा कुन हो ?', E'चम्पादेवि', E'मुक्तिनाथ', E'पाथिभरा', E'स्याङ्बोचे', 'D', E'**नेपालको सबैभन्दा उच्च स्थानमा रहेको गुम्बा स्याङ्बोचे हो।**\n- चम्पादेवी काठमाडौं उपत्यकाको दक्षिणमा रहेको एक डाँडा र धार्मिक स्थल हो।\n- मुक्तिनाथ नेपालको सबैभन्दा अग्लो स्थानमा रहेको मन्दिर हो, जुन मुस्ताङ जिल्लामा पर्दछ।\n- पाथिभरा नेपालको सबैभन्दा अग्लो स्थानमा रहेको देवीस्थान हो, जुन ताप्लेजुङ जिल्लामा पर्दछ।', 'nepali'),
      (v_set_id, 20, E'सन् २०२६ बाट कार्यकाल सुरु भएको सुरक्षा परिषदमा अस्थायी सदस्य मुलुक देहाएका मध्ये कुन हो?', E'कम्बोडिया', E'कंगो', E'पाकिस्तान', E'भुटान', 'B', E'सुरक्षा परिषदमा सन् २०२६ बाट कार्यकाल सुरु गर्ने अस्थायी सदस्य मुलुक **कंगो** हो।\nनोट: कंगोसँगै बहराइन, लाइबेरिया, कोलम्बिया र लाटभियाले पनि सन् २०२६ जनवरी १ देखि आफ्नो दुई वर्षे कार्यकाल सुरु गरेका थिए।', 'nepali'),
      (v_set_id, 21, E'पृथ्वी सौर्यमण्डलको कति औं सानो ग्रह हो ?', E'तेस्रो', E'पाँचौ', E'छैठौं', E'चौथो', 'D', E'पृथ्वी सौर्यमण्डलको **चौथो** सानो ग्रह हो।\n- ग्रहहरूको आकारको आधारमा क्रम (सानोदेखि ठूलो) यसप्रकार छ: बुध, मंगल, शुक्र, पृथ्वी, वरुण, अरुण, शनि र वृहस्पति।', 'nepali'),
      (v_set_id, 22, E'विश्वको सबैभन्दा अग्लो पर्वतमाला कुन हो ?', E'रकी', E'एण्डिज', E'हिमालय', E'अल्पास', 'C', E'**विश्वको सबैभन्दा अग्लो पर्वतमाला हिमालय हो।**\n- एण्डिज पर्वतमाला विश्वको सबैभन्दा लामो पर्वतमाला हो, जसको लम्बाई करिब ७,२०० कि.मी. छ।\n- रकी पर्वतमाला उत्तर अमेरिकामा अवस्थित एक प्रमुख पर्वत श्रृंखला हो।\n- आल्प्स पर्वतमाला युरोपको सबैभन्दा उच्च र विस्तृत पर्वत श्रृंखला प्रणाली हो।\nनोट: हिमालय पर्वतमाला विश्वको सबैभन्दा कान्छो पर्वतमाला पनि हो र यो ५ देशहरू (भुटान, भारत, नेपाल, चीन, पाकिस्तान) मा फैलिएको छ।', 'nepali'),
      (v_set_id, 23, E'भगवान गौतम बुद्ध कति वर्षको उमेरमा बिबाह गरेको थिए ?', E'२९ वर्ष', E'१६ वर्ष', E'३५ वर्ष', E'७ वर्ष', 'B', E'भगवान गौतम बुद्धले **१६ वर्षको** उमेरमा विवाह गरेका थिए।\n- उनले २९ वर्षको उमेरमा गृहत्याग गरेका थिए।\n- उनले ३५ वर्षको उमेरमा ज्ञान प्राप्त गरेका थिए।', 'nepali'),
      (v_set_id, 24, E'अवशिष्ट अधिकार सम्बन्धि व्यवस्था नेपालको संविधानको कुन धारामा रहेको छ ?', E'धारा ६१', E'धारा ५९', E'धारा ६०', E'धारा ५८', 'D', E'नेपालको संविधानको **धारा ५८** मा अवशिष्ट अधिकार सम्बन्धी व्यवस्था रहेको छ।\n- यस धारा अनुसार संघ, प्रदेश तथा स्थानीय तहको अधिकारको सूची वा साझा सूचीमा उल्लेख नभएको वा संविधानमा कुनै तहले प्रयोग गर्ने गरी नतोकिएको विषयमा संघको अधिकार हुने व्यवस्था छ।', 'nepali'),
      (v_set_id, 25, E'विश्व इतिहासमा दोस्रो विश्वयुद्ध करिब कति वर्ष चलेको थियो ?', E'६ वर्ष', E'४ वर्ष', E'५ वर्ष', E'७ वर्ष', 'A', E'दोस्रो विश्वयुद्ध करिब **६ वर्ष** चलेको थियो।\n- यो युद्ध १ सेप्टेम्बर १९३९ मा सुरु भई २ सेप्टेम्बर १९४५ मा समाप्त भएको थियो, अर्थात् यो कूल ६ वर्ष १ दिनसम्म चलेको थियो।', 'nepali'),
      (v_set_id, 26, E'विश्वमा सर्वप्रथम Tissue culture कसमा प्रयोग गरिएको थियो ?', E'च्याउ', E'आलु', E'भेडा', E'टमाटर', 'B', E'विश्वमा सर्वप्रथम Tissue culture **आलुमा** प्रयोग गरिएको थियो।\n- जैविक प्रविधिबाट उत्पादन गरिएको पहिलो वस्तु च्याउ हो।\n- क्लोनिङ प्रविधिको प्रयोग सर्वप्रथम डली नामक भेडामा गरिएको थियो।\n- नेपालमा भने टिस्यु कल्चरको प्रयोग सर्वप्रथम आलु र टमाटरमा गरिएको थियो।', 'nepali'),
      (v_set_id, 27, E'तराई क्षेत्रको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज कुन हो ?', E'बर्दिया', E'बाँके', E'चितवन', E'पर्सा', 'A', E'तराई क्षेत्रको सबैभन्दा ठूलो राष्ट्रिय निकुञ्ज **बर्दिया राष्ट्रिय निकुञ्ज** हो।\n- बाघ संरक्षणका लागि स्थापना गरिएको राष्ट्रिय निकुञ्ज बाँके राष्ट्रिय निकुञ्ज हो।\n- चितवन राष्ट्रिय निकुञ्ज नेपालको पहिलो र सबैभन्दा धेरै पर्यटक घुम्न आउने राष्ट्रिय निकुञ्ज हो।\n- पर्सा राष्ट्रिय निकुञ्ज गौरी गाईको लागि प्रख्यात छ।', 'nepali'),
      (v_set_id, 28, E'देहायका मध्ये कुन संगठनको संस्थापक मुलुक संख्या ५ वटा रहेको छन् ?', E'ईयु', E'सार्क', E'बिमस्टेक', E'आसियान', 'D', E'दिएका संगठनहरूमध्ये **आसियान (ASEAN)** का संस्थापक सदस्य राष्ट्रहरूको संख्या ५ थियो।\n- युरोपेली संघ (ईयु) का संस्थापक सदस्य राष्ट्र ६ वटा थिए।\n- सार्क (SAARC) का संस्थापक सदस्य राष्ट्र ७ वटा थिए।\n- बिमस्टेक (BIMSTEC) का संस्थापक सदस्य राष्ट्र ४ वटा थिए।', 'nepali'),
      (v_set_id, 29, E'Cop-1 प्रथम कोप सम्मेलन कुन देशमा सम्पन्न भएको थियो?', E'इजिप्ट', E'बेलायत', E'स्पेन', E'जर्मनी', 'D', E'जलवायु परिवर्तनसम्बन्धी पहिलो कोप (COP-1) सम्मेलन **जर्मनीको बर्लिनमा** सम्पन्न भएको थियो। यो सम्मेलन सन् १९९५ मार्च २८ देखि अप्रिल ७ सम्म आयोजना गरिएको थियो।', 'nepali'),
      (v_set_id, 30, E'सार्कको कति औं शिखर सम्मेलनबाट अफगानिस्तान सहभागी भएको थियो ?', E'१३औं', E'१४ औं', E'१८ औं', E'हालसम्म छैन', 'B', E'अफगानिस्तान सार्कको **१४ औं शिखर सम्मेलनबाट** सदस्यको रूपमा सहभागी भएको थियो।\n- १३ औं शिखर सम्मेलनले अफगानिस्तानलाई सार्कको सदस्य बनाउने निर्णय गरेको थियो।\n- १८ औं शिखर सम्मेलन सन् २०१४ मा काठमाडौं, नेपालमा सम्पन्न भएको थियो।\n- अफगानिस्तान सार्कको आठौं सदस्य राष्ट्र हो, त्यसैले ''हालसम्म छैन'' भन्ने विकल्प गलत छ।\nनोट: १४ औं शिखर सम्मेलन सन् २००७ अप्रिल ३-४ मा भारतको नयाँ दिल्लीमा आयोजना भएको थियो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०२/०५', 30;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_02_08.csv  →  आसमान दैनिक GK — २०८३/०२/०८  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०२/०८'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०२/०८';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०२/०८', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'आर्थिक वर्ष २०८३/८४ का लागि नेपाल सरकारको वार्षिक नीति तथा कार्यक्रम अनुसार कहिलेसम्म देशका सबै नागरिकलाई स्वच्छ खानेपानीको व्यवस्था गरिने नीति उल्लेख गरिएको छ ?', E'वि.सं २०८५ सम्म', E'वि.सं २०८६ सम्म', E'वि.सं २०८७ सम्म', E'वि.सं २०८८ सम्म', 'C', E'नेपाल सरकारले आर्थिक वर्ष २०८३/८४ को वार्षिक नीति तथा कार्यक्रम मार्फत **वि.सं २०८७ सम्ममा** देशका सबै नागरिकलाई स्वच्छ खानेपानीको व्यवस्था गर्ने लक्ष्य लिएको छ।', 'nepali'),
      (v_set_id, 2, E'गोरखापत्रमा समाचार प्रकाशन हुन थालेको पछिल्लो भाषा कुन हो ?', E'बोटे', E'सन्थाल', E'हायू', E'कुलुङ', 'A', E'गोरखापत्रमा समाचार प्रकाशन हुन थालेको पछिल्लो भाषा **बोटे** हो।\n- यो भाषा ४९औं भाषाको रूपमा वि.सं. २०८३ वैशाख ८ गतेदेखि समावेश भएको हो।\n- सन्थाल र हायु भाषा क्रमशः ४७औं र ४८औं भाषाको रूपमा वि.सं. २०८२ मा समावेश भएका थिए।\n- कुलुङ भाषा ४६औं भाषाको रूपमा वि.सं. २०८२ मंसिर १६ गतेदेखि समावेश भएको थियो।', 'nepali'),
      (v_set_id, 3, E'वर्तमान प्रधानन्यायाधीश मनोजकुमार शर्मा नेपालका कति औं प्रधानन्यायाधीश हुन्?', E'३२ औं', E'३३ औं', E'३४ औं', E'३५ औं', 'B', E'वर्तमान प्रधानन्यायाधीश डा. मनोजकुमार शर्मा नेपालका **३३ औं** प्रधानन्यायाधीश हुन्। उहाँलाई राष्ट्रपति रामचन्द्र पौडेलले वि.सं. २०८३ जेठ ५ गते नियुक्त गर्नुभएको हो।\nनोट: प्रधानन्यायाधीशको पदावधि ६ वर्ष वा ६५ वर्षको उमेर हदसम्म हुन्छ।', 'nepali'),
      (v_set_id, 4, E'महालेखा परीक्षकको ६३ औं वार्षिक प्रतिवेदन, २०८३ अनुसार नेपालको सबैभन्दा बढी बेरुजु रहेको प्रदेश कुन हो?', E'कोशी', E'मधेस', E'बागमती', E'गण्डकी', 'B', E'महालेखा परीक्षकको ६३ औं वार्षिक प्रतिवेदन, २०८३ अनुसार नेपालको सबैभन्दा बढी बेरुजु **मधेस प्रदेशमा (३.७७ प्रतिशत)** रहेको छ।\nनोट: सोही प्रतिवेदन अनुसार सबैभन्दा कम बेरुजु बागमती प्रदेशमा (०.८३ प्रतिशत) रहेको छ।', 'nepali'),
      (v_set_id, 5, E'आफ्नै रेकर्ड तोड्दै कामिरिता शेर्पाले सगरमाथाको ३२ औं पटक सफल आरोहण कहिले गरे?', E'२०८३ जेठ ३', E'२०८२ जेठ १३', E'२०८३ जेठ ५', E'२०८२ जेठ ३', 'A', E'कामिरिता शेर्पाले सगरमाथाको ३२ औं पटक सफल आरोहण **वि.सं. २०८३ जेठ ३** गते गरेका हुन्।\nनोट: उनले पहिलो पटक सन् १९९४ मे १३ मा सगरमाथा आरोहण गरेका थिए र उनलाई ''एभरेष्ट म्यान'' उपनामले चिनिन्छ।', 'nepali'),
      (v_set_id, 6, E'इबोलाको भाइरसलाई लक्षित गर्दै डब्ल्युएचओले स्वास्थ्य संकटकाल घोषणा कहिले गरेको छ ?', E'सन् २०२६ मे १४', E'सन् २०२६ मे १५', E'सन् २०२६ मे १६', E'सन् २०२६ मे १७', 'D', E'विश्व स्वास्थ्य संगठन (WHO) ले प्रजातान्त्रिक गणतन्त्र कंगोमा फैलिएको इबोला प्रकोपलाई लक्षित गर्दै **सन् २०२६ मे १७** मा अन्तर्राष्ट्रिय स्वास्थ्य संकटकाल घोषणा गरेको थियो।\nनोट: यो घोषणा कंगोको पूर्वी इटुरी प्रान्तमा इबोला भाइरसबाट ८० जनाको मृत्यु भएपछि गरिएको थियो।', 'nepali'),
      (v_set_id, 7, E'एकदिवसीय (ओडिआई) क्रिकेटको इतिहासमा सबैभन्दा कम खेलमा १५० विकेट पूरा गर्ने विश्व कीर्तिमान कायम गर्ने नेपाली खेलाडीको हुन् ?', E'सन्दीप लामिछाने', E'दिपेन्द्रसिंह ऐरी', E'नन्दन यादव', E'सोमकाल कामी', 'A', E'**एकदिवसीय (ओडिआई) क्रिकेटमा सबैभन्दा कम खेलमा १५० विकेट पूरा गर्ने विश्व कीर्तिमान कायम गर्ने नेपाली खेलाडी सन्दीप लामिछाने हुन्।**\n- दिपेन्द्रसिंह ऐरी नेपाली क्रिकेट टोलीका एक प्रमुख अलराउन्डर हुन्।\n- नन्दन यादव नेपाली राष्ट्रिय क्रिकेट टोलीका बलर हुन्।\n- सोमपाल कामी नेपाली राष्ट्रिय क्रिकेट टोलीका तीव्र गतिका बलर तथा ब्याट्सम्यान हुन्।\nनोट: सन्दीपले जम्मा ७३ खेलमा १५० ओडिआई विकेट पूरा गर्दै अस्ट्रेलियाका मिचेल स्टार्कको (७७ खेलको) कीर्तिमान तोडेका थिए।', 'nepali'),
      (v_set_id, 8, E'"Operation Epic Fury" कोड नाम दिइएको अमेरिका र इजरायलको संयुक्त सैन्य कारबाहीले इरानमा कहिले हमला गरेको थियो?', E'सन् २०२६ जुन २२', E'सन् २०२६ फेब्रुअरी २८', E'सन् २०२६ अप्रिल ७', E'सन् २०२६ जनवरी १५', 'B', E'अमेरिका र इजरायलद्वारा इरानविरुद्ध सञ्चालित "Operation Epic Fury" नामक संयुक्त सैन्य अभियान **सन् २०२६ फेब्रुअरी २८** मा सुरु भएको थियो।\nनोट: यस अभियानको मुख्य लक्ष्य इरानको मिसाइल क्षमतालाई कमजोर बनाउनु थियो।', 'nepali'),
      (v_set_id, 9, E'उत्तम शान्ति पुरस्कार, २०८२ कसलाई प्रदान गरिएको छ ?', E'प्रेमशान्ति तुलाधर', E'अभि सुवेदी', E'शैलेन्द्र साकार', E'तीर्थबहादुर श्रेष्ठ', 'D', E'प्रख्यात वनस्पतिविज्ञ डा. **तीर्थबहादुर श्रेष्ठ**लाई उत्तम शान्ति पुरस्कार, २०८२ प्रदान गरिएको छ।\n- प्रा. प्रेमशान्ति तुलाधरलाई मातृभाषा राष्ट्रिय सेवा पुरस्कार-२०८२ प्रदान गरिएको थियो।\nनोट: डा. श्रेष्ठलाई उनको कृति ''नेपाल गाथा'' (विधा: गैरआख्यान) का लागि यो पुरस्कार प्रदान गरिएको हो र पुरस्कारको राशि रु. एक लाख छ।', 'nepali'),
      (v_set_id, 10, E'सन् २०२६ विश्व रेडक्रस दिवसको नारा देहाएका मध्ये कुन रहेको थियो ?', E'Bound by Kindness', E'United in Humanity', E'Universal Compassion', E'Power of Togetherness', 'B', E'सन् २०२६ को विश्व रेडक्रस दिवसको नारा ''**United in Humanity**'' (मानवतामा एकजुट) रहेको थियो।\nनोट: विश्व रेडक्रस दिवस हरेक वर्ष मे ८ मा मनाइन्छ, जसको स्थापना हेनरी ड्युनाले गरेका हुन्।', 'nepali'),
      (v_set_id, 11, E'नेपाल सरकार कार्य विभाजन नियमावली, २०८३ ले मन्त्रालयको संख्या घटाएर कतिमा सिमित राखिएको छ ?', E'१८ वटा', E'१९ वटा', E'२० वटा', E'२१ वटा', 'A', E'नेपाल सरकार कार्य विभाजन नियमावली, २०८३ ले मन्त्रालयको संख्या घटाएर **१८ वटा**मा सिमित गरेको छ। यो नियमावली २०८३ बैशाख ३० गते स्वीकृत भएको थियो।', 'nepali'),
      (v_set_id, 12, E'हालसालै २०२६ मा नेपाल देहाएको कुन संगठनको उपाध्यक्षमा निर्वाचित भएको छ ?', E'WTO', E'WHO', E'UNO', E'FAO', 'B', E'हालसालै सन् २०२६ मा नेपाल **विश्व स्वास्थ्य संगठन (WHO)** को उपाध्यक्षमा निर्वाचित भएको छ।\n- WTO को पूरा रूप विश्व व्यापार संगठन (World Trade Organization) हो।\n- UNO को पूरा रूप संयुक्त राष्ट्र संघ (United Nations Organization) हो।\n- FAO को पूरा रूप खाद्य तथा कृषि संगठन (Food and Agriculture Organization) हो।\nनोट: नेपाल स्विट्जरल्याण्डको जेनेभामा मे १८-२३, २०२६ मा आयोजित ७९औं विश्व स्वास्थ्य महासभामा सर्वसम्मत रुपमा उपाध्यक्ष निर्वाचित भएको हो।', 'nepali'),
      (v_set_id, 13, E'नेपालमा पहिलो पटक औपचारिक रुपमा ई - पेन्सन व्यवस्थाको सुरुवात कुन जिल्लाबाट भएको छ ?', E'काठमाडौं', E'पाँचथर', E'सोलुखुम्बु', E'कास्की', 'C', E'नेपालमा पहिलो पटक औपचारिक रुपमा ई-पेन्सन व्यवस्थाको सुरुवात **सोलुखुम्बु जिल्लाबाट** भएको हो। यसको औपचारिक सुरुवात २०८३ वैशाख २७ गते भएको थियो।\nनोट: ई-पेन्सन प्राप्त गर्ने पहिलो व्यक्ति भिमलाल तामाङ हुन्।', 'nepali'),
      (v_set_id, 14, E'विश्व दूरसञ्चार दिवस प्रत्येक वर्ष कुन तारिखमा मनाइन्छ ?', E'मे १७', E'मे १८', E'मे १९', E'मे २०', 'A', E'विश्व दूरसञ्चार दिवस प्रत्येक वर्ष **मे १७** तारिखमा मनाइन्छ। अन्तर्राष्ट्रिय दूरसञ्चार संगठन (ITU) को स्थापना सन् १८६५ मे १७ मा भएको सम्झनामा सन् १९६९ देखि यो दिवस मनाउन थालिएको हो।\nनोट: सन् २०२६ को नारा ''Digital lifelines: Strengthening resilience in a connected world'' रहेको थियो।', 'nepali'),
      (v_set_id, 15, E'२०८२ चैत्र १३ गते सार्वजनिक भएको नेपाल सरकारको शासकीय सुधारसम्बन्धी एक सय दिने कार्यसूची अन्तर्गत आगामी पाँच वर्षभित्र नेपालको प्रतिव्यक्ति आय कति पुऱ्याउने लक्ष्य रहेको छ ?', E'२८०० डलर', E'३००० डलर', E'३२०० डलर', E'३४०० डलर', 'B', E'२०८२ चैत्र १३ गते सार्वजनिक भएको नेपाल सरकारको शासकीय सुधारसम्बन्धी कार्यसूची अनुसार आगामी पाँच वर्षभित्र नेपालको प्रतिव्यक्ति आय **३००० डलर** पुऱ्याउने लक्ष्य रहेको छ।\nनोट: सोही अवधिमा औसत आर्थिक वृद्धिदर ७ प्रतिशत हासिल गर्ने र बहुआयामिक गरिबीको दर १० प्रतिशतमा झार्ने लक्ष्य पनि राखिएको छ।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०२/०८', 15;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- daily_gk_2083_02_10.csv  →  आसमान दैनिक GK — २०८३/०२/१०  (15 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id uuid;
  v_subtopic_id uuid;
  v_set_id uuid;
  v_existing_id uuid;
  v_next_step int;
BEGIN
  -- Lookup the target subtopic and its parent topic
  SELECT st.id, st.topic_id
    INTO v_subtopic_id, v_topic_id
  FROM public.subtopics st
  WHERE st.slug = 'aasman-collection'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'aasman-collection subtopic not found in DB';
  END IF;

  -- Idempotency: skip if a set with this exact title already exists
  SELECT id INTO v_existing_id
  FROM public.question_sets
  WHERE title = E'आसमान दैनिक GK — २०८३/०२/१०'
    AND topic_id = v_topic_id
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'आसमान दैनिक GK — २०८३/०२/१०';
    RETURN;
  END IF;

  -- 1. Insert the question_set shell
  INSERT INTO public.question_sets (topic_id, subtopic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, v_subtopic_id, E'आसमान दैनिक GK — २०८३/०२/१०', 1, 'learning', true)
  RETURNING id INTO v_set_id;

  -- 2. Insert questions, then mirror into the junction table by order_number
  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d, correct_option, explanation, language)
    VALUES
      (v_set_id, 1, E'थुनामा रहेको व्यक्तिलाई अमानवीय र अपमानजनक व्यवहार गर्न पाइने छैन। यो नेपालको संविधानको कुन हक अन्तर्गत रहेको छ ?', E'शोषण विरुद्धको हक', E'न्याय सम्बन्धि हक', E'अपराध पिडितको हक', E'यातना विरुद्धको हक', 'D', E'नेपालको संविधानको धारा २२ अनुसार, थुनामा रहेको व्यक्तिलाई शारीरिक वा मानसिक यातना दिन वा अपमानजनक व्यवहार गर्न नपाइने कुरा **यातना विरुद्धको हक** अन्तर्गत पर्दछ।\n- शोषण विरुद्धको हक (धारा २९) अन्तर्गत कसैलाई पनि बेचबिखन गर्न, दास बनाउन वा इच्छा विरुद्ध काममा लगाउन पाइँदैन।\n- न्याय सम्बन्धी हक (धारा २०) अनुसार कुनै पनि व्यक्तिलाई पक्राउको कारण सहित सूचना नदिई थुनामा राख्न पाइँदैन।\n- अपराध पीडितको हक (धारा २१) ले पीडितलाई आफ्नो मुद्दाको अनुसन्धानबारे जानकारी पाउने अधिकार सुनिश्चित गर्दछ।', 'nepali'),
      (v_set_id, 2, E'ICC T-20 विश्वकप क्रिकेट प्रतियोगिता, २०२६ मा सर्वाधिक रन बनाउने खेलाडीको हुन् ?', E'टिम सेफर्ट', E'जसप्रीत बुमराह', E'साहिबजादा फरहान', E'वरुण चक्रवर्ती', 'C', E'ICC T-20 विश्वकप क्रिकेट प्रतियोगिता, २०२६ मा पाकिस्तानका **साहिबजादा फरहान** सर्वाधिक रन बनाउने खेलाडी बनेका थिए।\n- न्युजिल्याण्डका टिम सेफर्टले प्रतियोगितामा सर्वाधिक ४ अर्धशतक बनाएका थिए।\n- भारतका जसप्रीत बुमराह र वरुण चक्रवर्तीले समान १४ विकेट लिँदै प्रतियोगितामा सर्वाधिक विकेट लिने खेलाडी बनेका थिए।\nनोट: साहिबजादा फरहानले प्रतियोगितामा २ शतक सहित कुल ३८३ रन बनाएका थिए।', 'nepali'),
      (v_set_id, 3, E'नेपालले दिगो विकासको कति वटा परिणात्मक लक्ष्य राखेको छ ?', E'१४९ वटा', E'१६४ लक्ष्य', E'१६९ लक्ष्य', E'१७४ लक्ष्य', 'A', E'नेपालले दिगो विकासका लागि **१४९ वटा** परिणात्मक लक्ष्य राखेको छ। विश्वव्यापी रूपमा दिगो विकासका १६९ वटा लक्ष्यहरू भए तापनि नेपालले लक्ष्य १४ (पानीमुनिको जीवन) बाहेक अन्य लक्ष्यहरूलाई राष्ट्रिय सन्दर्भमा अनुकूलन गरेको हो।', 'nepali'),
      (v_set_id, 4, E'नेपाल र भारत बिच भएको महाकाली सम्झौतामा कतिवटा धारा रहेको छन् ?', E'धारा १८', E'धारा १३', E'धारा १६', E'धारा १२', 'D', E'**नेपाल र भारत बिच भएको महाकाली सम्झौतामा १२ वटा धारा रहेका छन्।**\n- कोशी सम्झौतामा १८ धारा रहेका छन्।\n- गण्डकी सम्झौतामा १३ धारा रहेका छन्।\n- त्रिपक्षीय सम्झौतामा १६ धारा रहेका छन्।', 'nepali'),
      (v_set_id, 5, E'नेपालले कहिलेदेखि संयुक्तराष्ट्र संघमा स्थायी प्रतिनिधि पठाउन सुरु गर्यो ?', E'सन् १९५७', E'सन् १९५८', E'सन् १९५९', E'सन् १९५६', 'C', E'नेपालले **सन् १९५९** देखि संयुक्त राष्ट्र संघमा स्थायी प्रतिनिधि पठाउन सुरु गरेको हो।', 'nepali'),
      (v_set_id, 6, E'मल्लकालिन समयमा कुलो नहर आदिको रेखदेख गर्ने निकायलाई के भनिन्थ्यो ?', E'डाल्पा', E'पञ्चम', E'लिंगवल', E'माप्चोक', 'A', E'**मल्लकालीन समयमा कुलो, नहर आदिको रेखदेख गर्ने निकायलाई डाल्पा भनिन्थ्यो।** सोही समयमा सानातिना झगडा हेर्ने बुढापाकाको समूहलाई पञ्चसमुच्चय भनिन्थ्यो भने लिच्छविकालमा कुलो, पैनी, बाँध र बाटोघाटो सम्बन्धी कार्य गर्ने निकायलाई लिंगवल भनिन्थ्यो।', 'nepali'),
      (v_set_id, 7, E'परचक्रकामको उपनामले कुन लिच्छवि राजालाई चिनिन्छ ?', E'नरेन्द्रदेव', E'शिवदेव', E'जयदेव द्वितीय', E'सुपुष्प', 'C', E'**जयदेव द्वितीयलाई परचक्रकामको उपनामले चिनिन्छ, जसको अर्थ ''अर्काको देश जित्ने अभिलाषा'' हो।**\n- नरेन्द्रदेवलाई ''लिच्छविकालीन आकाशको पूर्ण चन्द्र'' भनी चिनिन्थ्यो।\n- शिवदेवलाई ''लिच्छवीका कुलकेतु'' भनेर चिनिन्थ्यो।\n- सुपुष्पलाई ''आदिपुरुष'' उपनामले चिनिन्थ्यो।', 'nepali'),
      (v_set_id, 8, E'नेपालको भूगोलमा सबैभन्दा ठूलो गाँउपालिका अवस्थित जिल्ला कुन हो ?', E'अर्घाखाँची', E'डोल्पा', E'मनाङ', E'हुम्ला', 'D', E'**नेपालको भूगोलमा सबैभन्दा ठूलो गाउँपालिका (नाम्खा) हुम्ला जिल्लामा अवस्थित छ।**\n- अर्घाखाँची जिल्लामा क्षेत्रफलको आधारमा सबैभन्दा ठूलो नगरपालिका, शीतगंगा नगरपालिका पर्दछ।\n- डोल्पा जिल्लामा सबैभन्दा कम जनसंख्या भएको नगरपालिका, ठूलीभेरी नगरपालिका रहेको छ।\n- मनाङ जिल्लामा सबैभन्दा कम जनसंख्या भएको गाउँपालिका, नार्पा भूमि गाउँपालिका पर्दछ।', 'nepali'),
      (v_set_id, 9, E'देहायका मध्ये कुन दह धादिङ जिल्लामा अवस्थित रहेको छ पहिचान गर्नुहोस् ?', E'कछुवा दह', E'सुन दह', E'कालोसेतो दह', E'मुरली दह', 'C', E'**कालोसेतो दह धादिङ जिल्लामा अवस्थित छ।**\n- कछुवा दह सल्यान जिल्लामा पर्दछ।\n- सुन दह डोटी जिल्लामा पर्दछ।\n- मुरली दह सुर्खेत जिल्लामा पर्दछ।\nनोट: धादिङ जिल्लामा गंगाजमुना कुण्ड पनि पर्दछ।', 'nepali'),
      (v_set_id, 10, E'छिमेकी मुलुक भारत अन्तरिक्ष प्रवेश गर्ने कति औं मुलुक हो ?', E'छैठौं', E'पाँचौं', E'चौथो', E'तेस्रो', 'A', E'छिमेकी मुलुक भारत अन्तरिक्षमा प्रवेश गर्ने **छैठौं** मुलुक हो।\nनोट: भारत चन्द्रमामा पुग्ने भने चौथो मुलुक हो।', 'nepali'),
      (v_set_id, 11, E'माङ्हिम, सिलौटी कुन धर्मको धार्मिक स्थल हुन् ?', E'किराँत धर्म', E'शिख धर्म', E'यहुदी धर्म', E'जैन धर्म', 'A', E'**माङ्हिम र सिलौटी किराँत धर्मका धार्मिक स्थलहरू हुन्।**\n- शिख धर्मको धार्मिक स्थललाई गुरुद्वारा भनिन्छ।\n- यहुदी धर्मको धार्मिक स्थल सिनागग हो।\n- जैन धर्मको धार्मिक स्थल जैन मन्दिर हो।', 'nepali'),
      (v_set_id, 12, E'प्यागोडा शैलीबाट निर्मित सबैभन्दा पुरानो मन्दिर कुन हो ?', E'स्वयम्भूनाथ', E'पशुपतिनाथ', E'चाँगुनारायण', E'ब्रह्मा मन्दिर', 'C', E'**प्यागोडा शैलीमा निर्मित नेपालको सबैभन्दा पुरानो मन्दिर चाँगुनारायण हो।**\n- स्वयम्भूनाथलाई नेपालको सबैभन्दा पुरानो मन्दिर मानिन्छ, तर यो स्तुप शैलीमा निर्मित छ।\n- ब्रह्मा मन्दिर नेपालको सबैभन्दा पुरानो शिखर शैलीको मन्दिर हो।', 'nepali'),
      (v_set_id, 13, E'''कुनै पनि व्यक्तिलाई देश निकाला गर्न पाइने छैन'' माथिको कथन नेपालको संविधानको कुन धारामा उल्लेख गरिएको छ ?', E'धारा ४४', E'धारा ४३', E'धारा ४५', E'धारा ४६', 'C', E'**''कुनै पनि व्यक्तिलाई देश निकाला गर्न पाइने छैन'' भन्ने कथन नेपालको संविधानको धारा ४५ मा उल्लेख छ, जुन देश निकाला विरुद्धको हक हो।**\n- धारा ४४ मा उपभोक्ताको हकको व्यवस्था गरिएको छ।\n- धारा ४३ मा सामाजिक सुरक्षाको हकको व्यवस्था गरिएको छ।\n- धारा ४६ मा संवैधानिक उपचारको हकको व्यवस्था गरिएको छ।', 'nepali'),
      (v_set_id, 14, E'नेपालको म्याग्नाकार्टा भनेर कुन दस्तावेजलाई चिनिन्छ ?', E'प्रतिनिधि सभा घोषणापत्र, २०७०', E'प्रतिनिधि सभा घोषणापत्र, २०६३', E'नेपाल सरकार वैधानिक कानुन, २००४', E'नेपालको अन्तरिम शासन विधान, २००७', 'B', E'प्रतिनिधि सभा घोषणापत्र, २०६३ लाई नेपालको म्याग्नाकार्टा भनेर चिनिन्छ। यो घोषणापत्र तत्कालीन प्रधानमन्त्री गिरिजाप्रसाद कोइरालाको पालामा **२०६३ जेठ ४ गते** जारी भएको थियो।', 'nepali'),
      (v_set_id, 15, E'२०८२ मा कति औं निर्वाचन दिवस मनाइएको हो ?', E'१० औं', E'११ औं', E'१२ औं', E'१३ औं', 'A', E'वि.सं. २०८२ मा **१० औं** निर्वाचन दिवस मनाइएको हो।\n- नेपालमा पहिलो पटक वि.सं. २०१५ फागुन ७ गते भएको आम निर्वाचनको दिनलाई आधार मानेर वि.सं. २०७३ देखि हरेक वर्ष फागुन ७ गते निर्वाचन दिवस मनाउन थालिएको हो।', 'nepali')
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- 3. Append to the topic's learning path so the set is reachable.
  --    Unlocked by default — users can pick any session, not strictly sequential.
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths
  WHERE topic_id = v_topic_id;

  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% questions)', E'आसमान दैनिक GK — २०८३/०२/१०', 15;
END $$;
